static void m11_dm2_bind_verified_sound_playback(void)
{
    static DM2_V1_SoundPlaybackBackend backend;

    /* SKProject SKWIN/SkwinSDL.cpp::OpenAudio owns the SDL playback device;
     * c_sound.cpp owns the GDAT sample lookup already bound by the verified
     * boot profile.  Do not create or bind a backend before that profile is
     * admitted, because an unverified file must never yield audible output. */
    dm2_v1_sound_sdl_backend_describe(&backend);
    dm2_v1_sound_bind_playback_backend(&backend);
}

static void m11_dm2_copy_printable(unsigned char *dst,
                                   int dst_len,
                                   const char *src,
                                   int src_len)
{
    int i;
    if (!dst || dst_len <= 0) return;
    memset(dst, ' ', (size_t)dst_len);
    if (!src || src_len <= 0) return;
    for (i = 0; i < dst_len && i < src_len && src[i] != '\0'; ++i) {
        unsigned char ch = (unsigned char)src[i];
        dst[i] = (ch >= 0x20u && ch <= 0x7eu) ? ch : ' ';
    }
}

static void m11_dm2_mirror_session_party(M11_GameViewState *state,
                                         const DM2_V1_SessionState *session)
{
    int count;

    if (!state || !session) return;
    count = session->champion_count;
    if (count < 0) count = 0;
    if (count > CHAMPION_MAX_PARTY) count = CHAMPION_MAX_PARTY;
    memset(&state->world.party, 0, sizeof(state->world.party));
    memset(state->dm2State.champion_inventory_objects, 0,
           sizeof(state->dm2State.champion_inventory_objects));
    state->world.party.championCount = count;
    state->world.party.activeChampionIndex =
        (count > 0 && session->leader_index < (uint8_t)count)
            ? (int)session->leader_index
            : (count > 0 ? 0 : -1);
    state->world.party.mapX = (int)session->party_x;
    state->world.party.mapY = (int)session->party_y;
    state->world.party.mapIndex = (int)session->party_level;
    state->world.party.direction = (int)(session->party_dir & 3u);
    for (int i = 0; i < count; ++i) {
        struct ChampionState_Compat *dst = &state->world.party.champions[i];
        const DM2_ChampionRecord *src =
            (const DM2_ChampionRecord *)session->champion_data[i];
        memset(dst, 0, sizeof(*dst));
        dst->present = 1;
        dst->portraitIndex = i;
        m11_dm2_copy_printable(dst->name,
                               CHAMPION_NAME_LENGTH,
                               src->first_name,
                               DM2_CHAMPION_NAME_FIRST_LEN);
        m11_dm2_copy_printable(dst->title,
                               CHAMPION_TITLE_LENGTH,
                               src->last_name,
                               DM2_CHAMPION_NAME_LAST_LEN);
        dst->hp.current = src->cur_hp;
        dst->hp.maximum = src->max_hp ? src->max_hp : src->cur_hp;
        dst->hp.shifted = (unsigned short)(dst->hp.maximum << 1);
        dst->stamina.current = src->stamina;
        dst->stamina.maximum = src->stamina;
        dst->stamina.shifted = (unsigned short)(dst->stamina.maximum << 1);
        dst->mana.current = src->mana;
        dst->mana.maximum = src->mana;
        dst->mana.shifted = (unsigned short)(dst->mana.maximum << 1);
        dst->food = src->food;
        dst->water = src->water;
        dst->direction = (unsigned char)(src->absolute_direction & 3u);
        dst->cell = (unsigned char)(src->squad_position & 3u);
        for (int slot = 0; slot < CHAMPION_SLOT_COUNT; ++slot) {
            dst->inventory[slot] = THING_NONE;
            state->dm2State.champion_inventory_objects[i][slot] =
                src->inventory[slot];
        }
    }

}

static void m11_dm2_clear_new_game_party_state(M11_GameViewState *state)
{
    if (!state) return;
    memset(&state->world.party, 0, sizeof(state->world.party));
    state->world.party.activeChampionIndex = -1;
    memset(state->dm2State.champion_inventory_objects, 0,
           sizeof(state->dm2State.champion_inventory_objects));
    state->dm2State.leader_hand_object = 0u;
}

static int m11_dm2_resume_from_save_path(M11_GameViewState *state,
                                         DM2_V1_BootStartupLaunch *launch,
                                         const char *save_path);
static M11_GameInputResult m11_dm2_startup_apply_host_receipt(
    M11_GameViewState *state,
    const DM2_V1_StartupHostReceipt *host_receipt);
static int m11_dm2_startup_apply_session_callback(
    void *userdata,
    const DM2_V1_SessionState *session);

static int m11_dm2_resume_from_save_path(M11_GameViewState *state,
                                         DM2_V1_BootStartupLaunch *launch,
                                         const char *save_path)
{
    DM2_V1_StartupExecution execution;
    DM2_V1_StartupDirectResumeReceipt receipt;

    if (!state || !launch || !save_path || !save_path[0]) {
        return 0;
    }
    if (!dm2_v1_boot_startup_execute_launch_save_path_with_host_receipt(
            launch,
            save_path,
            m11_dm2_startup_apply_session_callback,
            state,
            &execution,
            &receipt)) {
        return 0;
    }
    (void)m11_dm2_startup_apply_host_receipt(state, &receipt.host_receipt);
    /* A decoded SUPPRESS prefix has no owned record-checkcode/DB-chain
     * reader yet.  Do not turn its legacy leader-hand cache into live UI
     * state; dm2_runtime_apply_source_session keeps the hand empty too. */
    state->dm2State.leader_hand_object = 0u;
    return receipt.session_applied;
}

static void m11_dm2_startup_state_receipt_to_m11(
    M11_GameViewState *state,
    const DM2_V1_StartupMenuStateReceipt *receipt)
{
    if (!state || !receipt) {
        return;
    }
    snprintf(state->dm2State.startup_save_root,
             sizeof(state->dm2State.startup_save_root),
             "%s",
             receipt->save_root);
    state->dm2State.startup_resume_available = receipt->resume_available;
    state->dm2State.startup_slot_mask = receipt->slot_mask;
    state->dm2State.startup_menu_row_count = receipt->row_count;
    state->dm2State.startup_menu_selected_row = receipt->selected_row;
}

