static int m11_dm2_boot_runtime_startup_pointer(
    M11_GameViewState *state,
    int x,
    int y,
    DM2_V1_StartupExecution *out_execution,
    DM2_V1_StartupHostActionReceipt *out_receipt)
{
    DM2_V1_BootRuntimeStartupSnapshot snapshot;
    if (!state || !out_execution || !out_receipt) {
        return 0;
    }
    m11_dm2_boot_runtime_startup_snapshot(state, &snapshot);
    return dm2_v1_boot_startup_execute_original_pointer_from_runtime_state(
        snapshot.profile,
        snapshot.startup_menu_active,
        snapshot.startup_save_root,
        snapshot.resume_available,
        snapshot.slot_mask,
        snapshot.selected_row,
        x,
        y,
        m11_dm2_startup_apply_session_callback,
        state,
        out_execution,
        out_receipt);
}

static M11_GameInputResult m11_dm2_startup_handle_input(
    M11_GameViewState *state,
    M12_MenuInput input)
{
    if (!state || !state->dm2State.startup_menu_active) {
        return M11_GAME_INPUT_IGNORED;
    }
    /* DM2_SHOW_CREDITS accepts only the source mouse event 0xEF.  Keyboard
     * navigation must not leak into SHOW_MENU_SCREEN while its 1,800-step
     * event loop owns the screen. */
    if (state->dm2State.startup_credits_active) {
        return M11_GAME_INPUT_IGNORED;
    }
    /* SHOW_MENU_SCREEN consumes DM2's own MessageLoop events.  Its menu
     * actions are the source UI events 0xD7/0xD9, selected by the mounted
     * GDAT RAW4 click matrix.  M12's UP/DOWN/ACCEPT tokens have no imported
     * DM2 keyboard-to-event translation, so treating its host row model as a
     * menu action could select a synthetic save/new-game route.  Keep those
     * tokens inert until c_0aaf/c_input's original translation is ported.
     * Source: SKWIN SkWinCore.cpp::SHOW_MENU_SCREEN (55182-55220),
     * HANDLE_UI_EVENT (32001-32021); SKULLWIN startend.cpp::DM2_SHOW_MENU_SCREEN.
     */
    (void)input;
    return M11_GAME_INPUT_IGNORED;
}

static int m11_csb_mapped_inventory_slot(int csb_slot)
{
    if (csb_slot == CSB_V1_SLOT_READY_HAND) return CHAMPION_SLOT_HAND_LEFT;
    if (csb_slot == CSB_V1_SLOT_ACTION_HAND) return CHAMPION_SLOT_ACTION_HAND;
    if (csb_slot >= CSB_V1_SLOT_BELT_1 && csb_slot <= CSB_V1_SLOT_BELT_4) {
        return CHAMPION_SLOT_POUCH_1 + (csb_slot - CSB_V1_SLOT_BELT_1);
    }
    if (csb_slot >= CSB_V1_SLOT_PACK_1 && csb_slot <= CSB_V1_SLOT_PACK_8) {
        return CHAMPION_SLOT_BACKPACK_1 + (csb_slot - CSB_V1_SLOT_PACK_1);
    }
    if (csb_slot >= CSB_V1_SLOT_PACK_9 && csb_slot <= CSB_V1_SLOT_PACK_12) {
        return CHAMPION_SLOT_BACKPACK_9 + (csb_slot - CSB_V1_SLOT_PACK_9);
    }
    return -1;
}

static int m11_csb_slot_for_m11_inventory_slot(int championSlot)
{
    if (championSlot == CHAMPION_SLOT_HAND_LEFT) return CSB_V1_SLOT_READY_HAND;
    if (championSlot == CHAMPION_SLOT_ACTION_HAND) return CSB_V1_SLOT_ACTION_HAND;
    if (championSlot >= CHAMPION_SLOT_POUCH_1 &&
        championSlot <= CHAMPION_SLOT_POUCH_1 + 3) {
        return CSB_V1_SLOT_BELT_1 + (championSlot - CHAMPION_SLOT_POUCH_1);
    }
    if (championSlot >= CHAMPION_SLOT_BACKPACK_1 &&
        championSlot <= CHAMPION_SLOT_BACKPACK_8) {
        return CSB_V1_SLOT_PACK_1 + (championSlot - CHAMPION_SLOT_BACKPACK_1);
    }
    if (championSlot >= CHAMPION_SLOT_BACKPACK_9 &&
        championSlot <= CHAMPION_SLOT_BACKPACK_12) {
        return CSB_V1_SLOT_PACK_9 + (championSlot - CHAMPION_SLOT_BACKPACK_9);
    }
    return -1;
}

typedef struct {
    const M11_GameViewState *state;
    int framebuffer_width;
    int framebuffer_height;
} M11_CSB_RuntimeSpriteContext;

static int m11_csb_viewport_projectile_sprite_drawer(
    void *user,
    const CSB_V1_ViewportRuntimeProjectileSpriteBlit *blit,
    uint8_t *screen_pixels,
    int screen_stride)
{
    const M11_CSB_RuntimeSpriteContext *ctx =
        (const M11_CSB_RuntimeSpriteContext *)user;

    if (!ctx || !ctx->state || !blit ||
        !screen_pixels || screen_stride <= 0 || !ctx->state->assetsAvailable) {
        return 0;
    }
    /* ReDMCSB DUNVIEW.C F0115 lines 5710-5722 picks the scale row from
     * view depth/cell before the F0791 C10 projectile blit.  Reuse the
     * M11 DM1 sprite path here; CSB PC34 shares the projectile bitmap
     * indices and viewport coordinate tables for this bounded draw step. */
    return m11_draw_projectile_sprite_ex(
        ctx->state,
        screen_pixels,
        screen_stride,
        ctx->framebuffer_height,
        blit->x,
        blit->y,
        blit->w,
        blit->h,
        blit->graphic_index,
        blit->forward,
        blit->relative_dir,
        blit->relative_cell,
        blit->flip_flags,
        blit->source_zone_row,
        blit->transparent_color,
        blit->uses_f0791_blit);
}

static int m11_csb_viewport_projectile_object_sprite_drawer(
    void *user,
    const CSB_V1_ViewportRuntimeProjectileObjectSpriteBlit *blit,
    uint8_t *screen_pixels,
    int screen_stride)
{
    const M11_CSB_RuntimeSpriteContext *ctx =
        (const M11_CSB_RuntimeSpriteContext *)user;

    if (!ctx || !ctx->state || !blit || !screen_pixels ||
        screen_stride <= 0 || !ctx->state->assetsAvailable) {
        return 0;
    }
    if (!m11_csb_install_runtime_source_graphic(ctx->state,
                                                (unsigned int)blit->graphic_index)) {
        return 0;
    }
    /* ReDMCSB DUNVIEW.C F0115:5896-5900: F0142's positive G0209 result
     * re-enters the object code only to consume C2900's projectile lane. */
    return m11_draw_thrown_object_projectile_sprite(
        ctx->state, screen_pixels, screen_stride, ctx->framebuffer_height,
        blit->graphic_index, blit->object_aspect_index, blit->depth_index,
        blit->relative_cell, blit->view_lane, blit->source_zone_row);
}

static int m11_csb_viewport_explosion_sprite_drawer(
    void *user,
    const CSB_V1_ViewportRuntimeExplosionSpriteBlit *blit,
    uint8_t *screen_pixels,
    int screen_stride)
{
    const M11_CSB_RuntimeSpriteContext *ctx =
        (const M11_CSB_RuntimeSpriteContext *)user;

    if (!ctx || !ctx->state || !blit || !screen_pixels ||
        screen_stride <= 0 || !ctx->state->assetsAvailable) {
        return 0;
    }
    /* ReDMCSB DUNVIEW.C F0115 lines 5916-6200 draws explosions in a
     * final pass with F0114/F0675 bitmap selection.  CSB PC34 shares
     * the DM1 explosion bitmap aspect mapping for this M11 bridge. */
    return m11_draw_explosion_sprite_bound_ex(
        ctx->state,
        screen_pixels,
        screen_stride,
        ctx->framebuffer_height,
        blit->x,
        blit->y,
        blit->w,
        blit->h,
        blit->aspect_index,
        blit->graphic_index,
        blit->is_smoke,
        blit->frame,
        blit->max_frames,
        blit->attack,
        blit->depth_index,
        blit->transparent_color,
        blit->uses_f0791_blit);
}

static void m11_csb_runtime_overlay_stats_apply(
    const M11_GameViewState *state,
    const CSB_V1_ViewportRuntimeDrawCounts *counts)
{
    M11_GameViewState *mutable_state = (M11_GameViewState *)state;

    if (!mutable_state || !counts) {
        return;
    }
    mutable_state->csbState.runtime_object_sprite_drawn_count =
        counts->object_sprite_drawn_count;
    mutable_state->csbState.runtime_object_icon_drawn_count =
        counts->object_icon_drawn_count;
    mutable_state->csbState.runtime_object_marker_drawn_count =
        counts->object_marker_drawn_count;
    mutable_state->csbState.runtime_group_sprite_drawn_count =
        counts->group_sprite_drawn_count;
    mutable_state->csbState.runtime_group_marker_drawn_count =
        counts->group_marker_drawn_count;
    mutable_state->csbState.runtime_projectile_sprite_drawn_count =
        counts->projectile_sprite_drawn_count;
    mutable_state->csbState.runtime_projectile_material_resolved_count =
        counts->projectile_material_resolved_count;
    mutable_state->csbState.runtime_projectile_marker_drawn_count =
        counts->projectile_marker_drawn_count;
    mutable_state->csbState.runtime_post_teleport_projectile_handoff_drawn_count =
        counts->post_teleport_projectile_handoff_drawn_count;
    mutable_state->csbState.runtime_post_teleport_projectile_handoff_blocked_count =
        counts->post_teleport_projectile_handoff_blocked_count;
    mutable_state->csbState.runtime_explosion_sprite_drawn_count =
        counts->explosion_sprite_drawn_count;
    mutable_state->csbState.runtime_explosion_marker_drawn_count =
        counts->explosion_marker_drawn_count;
}

static void m11_csb_runtime_overlay_stats_reset(
    const M11_GameViewState *state)
{
    CSB_V1_ViewportRuntimeDrawCounts counts;

    csb_v1_viewport_runtime_draw_counts_reset(&counts);
    m11_csb_runtime_overlay_stats_apply(state, &counts);
}

int M11_GameView_ProbeCsbRuntimeOverlayDrawStats(
    const M11_GameViewState *state,
    int *outObjectSpriteCount,
    int *outObjectIconCount,
    int *outObjectMarkerCount,
    int *outGroupSpriteCount,
    int *outGroupMarkerCount,
    int *outProjectileSpriteCount,
    int *outProjectileMaterialCount,
    int *outProjectileMarkerCount,
    int *outExplosionSpriteCount,
    int *outExplosionMarkerCount)
{
    if (!state || !outObjectSpriteCount || !outObjectIconCount ||
        !outObjectMarkerCount || !outGroupSpriteCount ||
        !outGroupMarkerCount || !outProjectileSpriteCount ||
        !outProjectileMaterialCount || !outProjectileMarkerCount ||
        !outExplosionSpriteCount || !outExplosionMarkerCount) {
        return 0;
    }
    *outObjectSpriteCount = state->csbState.runtime_object_sprite_drawn_count;
    *outObjectIconCount = state->csbState.runtime_object_icon_drawn_count;
    *outObjectMarkerCount = state->csbState.runtime_object_marker_drawn_count;
    *outGroupSpriteCount = state->csbState.runtime_group_sprite_drawn_count;
    *outGroupMarkerCount = state->csbState.runtime_group_marker_drawn_count;
    *outProjectileSpriteCount = state->csbState.runtime_projectile_sprite_drawn_count;
    *outProjectileMaterialCount = state->csbState.runtime_projectile_material_resolved_count;
    *outProjectileMarkerCount = state->csbState.runtime_projectile_marker_drawn_count;
    *outExplosionSpriteCount = state->csbState.runtime_explosion_sprite_drawn_count;
    *outExplosionMarkerCount = state->csbState.runtime_explosion_marker_drawn_count;
    return 1;
}

