static int m11_csb_viewport_group_sprite_drawer(
    void *user,
    const CSB_V1_ViewportRuntimeGroupSpriteBlit *blit,
    uint8_t *screen_pixels,
    int screen_stride)
{
    const M11_CSB_RuntimeSpriteContext *ctx =
        (const M11_CSB_RuntimeSpriteContext *)user;

    if (!ctx || !ctx->state || !blit || !screen_pixels ||
        screen_stride <= 0 || !ctx->state->assetsAvailable) {
        return 0;
    }
    /* DUNVIEW.C F0115:5222-5627 resolves G0243/G0219 before it reaches
     * C3200.  The CSB runtime overlay already carries that resolved type,
     * facing, native C3200 rectangle and source transparency.  PC 3.4 CSB
     * retains the shared C584+ creature archive layout, but the bytes still
     * come only from this live CSB GRAPHICS.DAT asset loader.  In particular,
     * do not substitute the old coloured group marker when one source bitmap
     * is absent: the bound drawer tells the viewport core to leave it blank.
     *
     * The C3200 placement has already selected left/right geometry; side is
     * deliberately not reinterpreted as a pose mirror here. */
    if (ctx->state->sourceKind != M11_GAME_SOURCE_CSB_BOOT ||
        blit->creature_type < 0 || blit->depth_index < 0 ||
        blit->depth_index > 2 || blit->w <= 0 || blit->h <= 0) {
        return 0;
    }
    return m11_draw_creature_sprite_ex_material(
        ctx->state, screen_pixels, screen_stride, ctx->framebuffer_height,
        blit->x, blit->y, blit->w, blit->h, blit->creature_type,
        blit->depth_index, 0, blit->direction, blit->transparent_color);
}

/* CSB F0098 receives C079/C078 through the same M10-expanded, verified
 * GRAPHICS.DAT loader as the rest of the CSB M11 session.  The current CSB
 * loader has source proof only for the PC3.4 set-zero floor pair; unrelated
 * graphic requests remain no-draw until their CSBWin ownership is bound. */
static int m11_csb_decode_active_source_graphic(
    const CSB_V1_BootProfile *profile, unsigned int graphic_index,
    unsigned char **out_pixels, int *out_width, int *out_height,
    CSB_V1_StartupGraphicDecodeReceipt_PC34 *out_receipt)
{
    if (!profile || !profile->graphics_verified || !profile->graphics_path[0]) {
        return 0;
    }
    if (profile->variant_id == CSB_V1_VARIANT_ST20_EN ||
        profile->variant_id == CSB_V1_VARIANT_ST21_EN) {
        return csb_v1_boot_decode_atari_st_graphics_dat_asset_pc34(
            profile->graphics_path, graphic_index, out_pixels, out_width,
            out_height, out_receipt);
    }
    return csb_v1_boot_decode_graphics_dat_asset_pc34(
        profile->graphics_path, graphic_index, out_pixels, out_width,
        out_height, out_receipt);
}

static int m11_csb_viewport_graphic_provider(void *user_data,
                                             int graphic_index,
                                             const uint8_t **out_pixels,
                                             int *out_width,
                                             int *out_height)
{
    enum {
        /* ReDMCSB DEFS.H M644/M646: PC3.4 FloorSet 0 and WallSet 0. */
        M11_CSB_PC34_GRAPHIC_FLOOR_SET0 = 78,
        M11_CSB_PC34_GRAPHIC_CEILING_SET0 = 79,
        M11_CSB_PC34_GRAPHIC_FIRST_WALL_SET = 86,
        M11_CSB_PC34_FLOOR_SET_GRAPHIC_COUNT = 2,
        M11_CSB_PC34_WALL_SET_GRAPHIC_COUNT = 40,
        M11_CSB_PC34_WALL_SURFACE_OFFSET = 7
    };
    M11_GameViewState *state = (M11_GameViewState *)user_data;
    CSB_V1_StartupGraphicDecodeReceipt_PC34 receipt;
    unsigned char **cached_pixels;
    int *cached_width;
    int *cached_height;
    unsigned int source_graphic;
    int expected_width;
    int expected_height;
    int floor_set;
    int wall_set;
    const CSB_V1_BootProfile *profile;

    if (!state || state->sourceKind != M11_GAME_SOURCE_CSB_BOOT ||
        !state->assetsAvailable || !out_pixels || !out_width ||
        !out_height) {
        return 0;
    }
    profile = (const CSB_V1_BootProfile *)state->csbBootProfile;
    if (!profile || !profile->runtime.dungeon_handle ||
        profile->runtime.current_level < 0 ||
        profile->runtime.current_level >=
            profile->runtime.dungeon_handle->level_count) {
        return 0;
    }
    floor_set = profile->runtime.dungeon_handle->map_floor_set[
        profile->runtime.current_level];
    wall_set = profile->runtime.dungeon_handle->map_wall_set[
        profile->runtime.current_level];
    if (floor_set < 0 || floor_set > 15 || wall_set < 0 || wall_set > 15) {
        return 0;
    }
    if (graphic_index == -1) {
        source_graphic = M11_CSB_PC34_GRAPHIC_FLOOR_SET0 +
            (unsigned int)floor_set * M11_CSB_PC34_FLOOR_SET_GRAPHIC_COUNT;
        expected_width = 224;
        expected_height = 97;
        cached_pixels = &state->csbViewportFloorPixels;
        cached_width = &state->csbViewportFloorWidth;
        cached_height = &state->csbViewportFloorHeight;
    } else if (graphic_index == -2) {
        source_graphic = M11_CSB_PC34_GRAPHIC_CEILING_SET0 +
            (unsigned int)floor_set * M11_CSB_PC34_FLOOR_SET_GRAPHIC_COUNT;
        expected_width = 224;
        expected_height = 39;
        cached_pixels = &state->csbViewportCeilingPixels;
        cached_width = &state->csbViewportCeilingWidth;
        cached_height = &state->csbViewportCeilingHeight;
    } else if (graphic_index >= 93 && graphic_index <= 107) {
        const int wall_slot = graphic_index - 93;
        source_graphic = M11_CSB_PC34_GRAPHIC_FIRST_WALL_SET +
            (unsigned int)wall_set * M11_CSB_PC34_WALL_SET_GRAPHIC_COUNT +
            M11_CSB_PC34_WALL_SURFACE_OFFSET + (unsigned int)wall_slot;
        /* ReDMCSB DUNVIEW.C F0122/F0123 pass the native C03/C02 D1 side
         * rasters to F0104/F0105.  Accepting an arbitrary decoded size here
         * could silently bind a different (but structurally valid) PC3.4
         * GRAPHICS.DAT record to C713/C714.  These source records are the
         * 60x111 D1L/D1R pair; retain the broader per-surface validation for
         * the remaining wall slots until each native raster is bound. */
        if (graphic_index == 95 || graphic_index == 96) {
            expected_width = 60;
            expected_height = 111;
        } else {
            expected_width = 1;
            expected_height = 1;
        }
        cached_pixels = &state->csbViewportWallPixels[wall_slot];
        cached_width = &state->csbViewportWallWidths[wall_slot];
        cached_height = &state->csbViewportWallHeights[wall_slot];
    } else if (graphic_index >= 86 && graphic_index <= 92) {
        const M11_AssetSlot *door_frame_asset;
        /* ReDMCSB DEFS.H M654--M660 and DUNVIEW.C F0096:2196-2202:
         * seven PC3.4 door-frame source records precede the 15 wall
         * surfaces in each 40-record wall-set family.  Do not borrow the
         * legacy global frame atlas when the active CSB package can provide
         * this exact record. */
        source_graphic = M11_CSB_PC34_GRAPHIC_FIRST_WALL_SET +
            (unsigned int)wall_set * M11_CSB_PC34_WALL_SET_GRAPHIC_COUNT +
            (unsigned int)(graphic_index - 86);
        if (!m11_csb_install_runtime_source_graphic(state, source_graphic)) {
            return 0;
        }
        door_frame_asset = M11_AssetLoader_Load(
            &state->assetLoader, source_graphic);
        if (!door_frame_asset || !door_frame_asset->loaded ||
            !door_frame_asset->pixels || door_frame_asset->width == 0u ||
            door_frame_asset->height == 0u) {
            return 0;
        }
        *out_pixels = door_frame_asset->pixels;
        *out_width = (int)door_frame_asset->width;
        *out_height = (int)door_frame_asset->height;
        return 1;
    } else if (graphic_index == 41 ||
               (graphic_index >= 70 && graphic_index <= 76)) {
        const M11_AssetSlot *field_asset;
        /* ReDMCSB DEFS.H C041 and C070--C076: the Thieves Eye hole and
         * fields are ordinary decoded source graphics. Install them through
         * the CSB decoder, not the generic DM1 loader. */
        if (!m11_csb_install_runtime_source_graphic(state,
                                                    (unsigned int)graphic_index)) {
            return 0;
        }
        field_asset = M11_AssetLoader_Load(&state->assetLoader,
                                           (unsigned int)graphic_index);
        if (!field_asset || !field_asset->loaded || !field_asset->pixels ||
            field_asset->width == 0u || field_asset->height == 0u) {
            return 0;
        }
        *out_pixels = field_asset->pixels;
        *out_width = (int)field_asset->width;
        *out_height = (int)field_asset->height;
        return 1;
    } else if (graphic_index >= 246 && graphic_index <= 257) {
        const M11_AssetSlot *door_asset;
        /* ReDMCSB DUNVIEW.C F0096 selects G0693 through MAP.D/DB0. The
         * viewport resolver has already retained that exact item identity. */
        if (!m11_csb_install_runtime_source_graphic(
                state, (unsigned int)graphic_index)) {
            return 0;
        }
        door_asset = M11_AssetLoader_Load(&state->assetLoader,
                                          (unsigned int)graphic_index);
        if (!door_asset || !door_asset->loaded || !door_asset->pixels ||
            door_asset->width == 0u || door_asset->height == 0u) {
            return 0;
        }
        *out_pixels = door_asset->pixels;
        *out_width = (int)door_asset->width;
        *out_height = (int)door_asset->height;
        return 1;
    } else if (graphic_index >= 385) {
        const M11_AssetSlot *fo_asset;
        /* ReDMCSB DEFS.H M616: floor ornament source graphics start at 385,
         * 6 variants per ornament.  Decode from GRAPHICS.DAT on demand. */
        if (!m11_csb_install_runtime_source_graphic(
                state, (unsigned int)graphic_index)) {
            return 0;
        }
        fo_asset = M11_AssetLoader_Load(&state->assetLoader,
                                        (unsigned int)graphic_index);
        if (!fo_asset || !fo_asset->loaded || !fo_asset->pixels ||
            fo_asset->width == 0u || fo_asset->height == 0u) {
            return 0;
        }
        *out_pixels = fo_asset->pixels;
        *out_width = (int)fo_asset->width;
        *out_height = (int)fo_asset->height;
        return 1;
    } else {
        return 0;
    }
    if ((graphic_index < 0 && state->csbViewportFloorSet != floor_set) ||
        (graphic_index >= 93 && graphic_index <= 107 &&
         state->csbViewportWallSet != wall_set)) {
        int i;
        if (graphic_index < 0) {
            free(state->csbViewportFloorPixels);
            free(state->csbViewportCeilingPixels);
            state->csbViewportFloorPixels = NULL;
            state->csbViewportCeilingPixels = NULL;
            state->csbViewportFloorWidth = state->csbViewportFloorHeight = 0;
            state->csbViewportCeilingWidth = state->csbViewportCeilingHeight = 0;
            state->csbViewportFloorSet = floor_set;
        } else {
            for (i = 0; i < 15; ++i) {
                free(state->csbViewportWallPixels[i]);
                state->csbViewportWallPixels[i] = NULL;
                state->csbViewportWallWidths[i] = 0;
                state->csbViewportWallHeights[i] = 0;
            }
            state->csbViewportWallSet = wall_set;
        }
    }
    if (!*cached_pixels) {
        memset(&receipt, 0, sizeof(receipt));
        if (!m11_csb_decode_active_source_graphic(
                profile, source_graphic, cached_pixels, cached_width,
                cached_height, &receipt) || !receipt.valid ||
            ((graphic_index < 0 || graphic_index == 95 ||
              graphic_index == 96) &&
             (*cached_width != expected_width ||
              *cached_height != expected_height))) {
            free(*cached_pixels);
            *cached_pixels = NULL;
            *cached_width = 0;
            *cached_height = 0;
            return 0;
        }
    }
    if (!*cached_pixels || *cached_width < expected_width ||
        *cached_height < expected_height) {
        return 0;
    }
    *out_pixels = *cached_pixels;
    *out_width = *cached_width;
    *out_height = *cached_height;
    return 1;
}

/* The shared M11 loader understands the common PC34 container, but CSB's
 * GRAPHICS.DAT has its own IMG3/LZW ownership.  Runtime F0115/F0114 sprites
 * must therefore enter the cache through the same CSB decoder as the boot,
 * HUD and viewport surfaces.  A failed source decode deliberately leaves the
 * sprite absent; it must not fall back to a DM1-decoded cache entry. */
static int m11_csb_install_runtime_source_graphic(
    const M11_GameViewState *state, unsigned int graphic_index)
{
    M11_GameViewState *mutable_state = (M11_GameViewState *)state;
    CSB_V1_StartupGraphicDecodeReceipt_PC34 receipt;
    uint32_t package_identity;
    unsigned int word_index;
    uint64_t graphic_mask;
    unsigned char *pixels = NULL;
    int width = 0;
    int height = 0;
    int installed = 0;

    if (!state || graphic_index >= M11_ASSET_CACHE_SLOTS ||
        state->sourceKind != M11_GAME_SOURCE_CSB_BOOT ||
        !state->assetsAvailable || !state->csbBootProfile ||
        !((const CSB_V1_BootProfile *)state->csbBootProfile)->graphics_verified ||
        !((const CSB_V1_BootProfile *)state->csbBootProfile)->graphics_path[0]) {
        return 0;
    }
    package_identity = state->csbStartupExpectedPackageIdentity;
    if (package_identity == 0u) return 0;
    if (mutable_state->csbRuntimeSourceGraphicsPackageIdentity !=
        package_identity) {
        memset(mutable_state->csbRuntimeSourceGraphicsBound, 0,
               sizeof(mutable_state->csbRuntimeSourceGraphicsBound));
        memset(mutable_state->csbRuntimeSourceGraphicsRejected, 0,
               sizeof(mutable_state->csbRuntimeSourceGraphicsRejected));
        mutable_state->csbRuntimeSourceGraphicsPackageIdentity =
            package_identity;
    }
    word_index = graphic_index / 64u;
    graphic_mask = UINT64_C(1) << (graphic_index % 64u);
    if (mutable_state->csbRuntimeSourceGraphicsBound[word_index] &
        graphic_mask) {
        return 1;
    }
    if (mutable_state->csbRuntimeSourceGraphicsRejected[word_index] &
        graphic_mask) {
        return 0;
    }
    memset(&receipt, 0, sizeof(receipt));
    if (m11_csb_decode_active_source_graphic(
            (const CSB_V1_BootProfile *)state->csbBootProfile, graphic_index,
            &pixels, &width, &height, &receipt) && receipt.valid &&
        width > 0 && height > 0 && width <= 65535 && height <= 65535) {
        installed = M11_AssetLoader_InstallDecodedPixels(
            &mutable_state->assetLoader, graphic_index, pixels,
            (unsigned short)width, (unsigned short)height);
    }
    free(pixels);
    if (installed) {
        mutable_state->csbRuntimeSourceGraphicsBound[word_index] |=
            graphic_mask;
    } else {
        /* The package is immutable for a running session.  Remember an
         * absent or invalid source graphic as well, otherwise a live frame
         * would repeatedly reopen GRAPHICS.DAT for the same fail-closed draw. */
        mutable_state->csbRuntimeSourceGraphicsRejected[word_index] |=
            graphic_mask;
    }
    return installed;
}

/* CSBWin CSBCode.cpp::ReadTablesFromGraphicsFile expands GRAPHICS.DAT item
 * 0x232 into Data::Palette552, then its boot path calls
 * setpalette(&d.Palette552[0]). Keep this separate from the PC3.4 VGA table:
 * TAG0088b2's low four-bit indices name Atari ST 0x0RGB registers here. */
static int m11_csb_atari_st_palette_rgb6_from_layout(
    const CSB_V1_CSBWinLayout0232 *layout, uint8_t palette_index,
    uint8_t out_rgb6[256][3])
{
    int color;

    if (!layout || !layout->valid || !out_rgb6 ||
        palette_index >= CSB_V1_CSBWIN_LAYOUT_0232_VIEWPORT_PALETTE_COUNT) {
        return 0;
    }
    for (color = 0; color < 256; ++color) {
        const uint16_t source = layout->viewport_palettes[palette_index][
            color & 0x0f];
        if ((source & 0xf888u) != 0u) return 0;
        out_rgb6[color][0] = (uint8_t)(((source >> 8) & 0x07u) * 9u);
        out_rgb6[color][1] = (uint8_t)(((source >> 4) & 0x07u) * 9u);
        out_rgb6[color][2] = (uint8_t)((source & 0x07u) * 9u);
    }
    return 1;
}

/* CSBWin CSBCode.cpp::SelectPaletteForLightLevel reads only the two hand
 * possessions of each current champion.  Keep the data boundary strict:
 * a decoded saved-game body, a loaded original dungeon and every non-empty
 * hand record are required before this replaces the source boot palette. */
static int m11_csb_atari_st_runtime_palette_rgb6(
    const CSB_V1_BootProfile *profile, uint8_t out_rgb6[256][3])
{
    const CSB_V1_RuntimeProfile *runtime;
    const CSB_V1_DungeonData *dungeon;
    CSB_V1_CSBWinLayout0232 layout;
    uint8_t torch_charges[8] = { 0 };
    uint8_t palette_index;
    int champion_index;

    if (!profile || !out_rgb6 ||
        (profile->variant_id != CSB_V1_VARIANT_ST20_EN &&
         profile->variant_id != CSB_V1_VARIANT_ST21_EN) ||
        !profile->graphics_verified || !profile->graphics_path[0]) {
        return 0;
    }
    runtime = &profile->runtime;
    dungeon = runtime->dungeon_handle;
    if (!runtime->csbwin_body_runtime_summary_valid ||
        !runtime->party_state_valid || !dungeon ||
        runtime->current_level < 0 || runtime->current_level >= dungeon->level_count ||
        runtime->party_state.ChampionCount < 0 ||
        runtime->party_state.ChampionCount > CSB_V1_MAX_CHAMPIONS ||
        !csb_v1_csbwin_layout_0232_read_graphics_dat(profile->graphics_path,
                                                      &layout) ||
        !layout.valid) {
        return 0;
    }
    for (champion_index = 0; champion_index < CSB_V1_MAX_CHAMPIONS;
         ++champion_index) {
        int slot;
        for (slot = 1; slot >= 0; --slot) {
            const uint16_t thing = runtime->party_state.Champions[
                champion_index].Slots[slot];
            const int charge_index = champion_index * 2 + (1 - slot);
            const uint8_t *record;
            int thing_type;
            int record_size;
            int icon_index;

            if (champion_index >= runtime->party_state.ChampionCount ||
                thing == THING_NONE || thing == THING_ENDOFLIST) {
                continue;
            }
            record = csb_v1_dungeon_get_thing_record(dungeon, thing,
                                                      &thing_type, NULL,
                                                      &record_size);
            if (!record || record_size < 4) return 0;
            icon_index = csb_v1_boot_runtime_object_icon_index_pc34(
                profile, thing);
            /* ReDMCSB's GetBasicObjectType admits Torch_a through Torch_d.
             * F0033 makes those the sole base icon 4 family in the actual
             * object table, including its lit charge variants 5..7. */
            if (thing_type == THING_TYPE_WEAPON && icon_index >= 4 &&
                icon_index <= 7) {
                const uint16_t word = (uint16_t)record[2] |
                    ((uint16_t)record[3] << 8);
                torch_charges[charge_index] =
                    (uint8_t)((word >> 10) & 0x0fu);
            }
        }
    }
    if (!csb_v1_csbwin_layout_0232_select_light_palette(
            &layout,
            dungeon->map_experience_multiplier[runtime->current_level],
            runtime->csbwin_character_tail_brightness, torch_charges,
            &palette_index)) {
        return 0;
    }
    return m11_csb_atari_st_palette_rgb6_from_layout(&layout, palette_index,
                                                      out_rgb6);
}

static int m11_csb_atari_st_initial_palette_rgb6(
    const CSB_V1_BootProfile *profile, uint8_t out_rgb6[256][3])
{
    CSB_V1_CSBWinLayout0232 layout;

    if (!profile || !out_rgb6 ||
        (profile->variant_id != CSB_V1_VARIANT_ST20_EN &&
         profile->variant_id != CSB_V1_VARIANT_ST21_EN) ||
        !profile->graphics_verified || !profile->graphics_path[0] ||
        !csb_v1_csbwin_layout_0232_read_graphics_dat(profile->graphics_path,
                                                      &layout)) {
        return 0;
    }
    return m11_csb_atari_st_palette_rgb6_from_layout(&layout, 0u, out_rgb6);
}

/* CSBWin's item C232 is not a bitmap: it is the original 0x722-byte HUD
 * layout record used by CSBCode.cpp.  It names the exact GRAPHICS.DAT images
 * and their destination rectangles.  Keep this resolver on the active
 * source decoder so an Atari ST/CSBWin session can never accidentally pull
 * similarly-numbered PC3.4 pixels from the generic M11 loader. */
static int m11_csb_csbwin_hud_source_resolver(
    void *user_data, uint16_t graphic_index, const uint8_t **out_pixels,
    int *out_width, int *out_height)
{
    M11_GameViewState *state = (M11_GameViewState *)user_data;
    const M11_AssetSlot *asset;

    if (!state || !out_pixels || !out_width || !out_height ||
        !m11_csb_install_runtime_source_graphic(state, graphic_index)) {
        return 0;
    }
    asset = M11_AssetLoader_Load(&state->assetLoader, graphic_index);
    if (!asset || !asset->loaded || !asset->pixels ||
        asset->width == 0u || asset->height == 0u) {
        return 0;
    }
    *out_pixels = asset->pixels;
    *out_width = (int)asset->width;
    *out_height = (int)asset->height;
    return 1;
}

/* The Atari/CSBWin startup route has no PC34 C017/C040 terminal page.  Its
 * real runtime HUD owner is instead the C232 coordinate record plus the
 * source graphics it references.  Present that complete, atomic layer after
 * ANIM.C hands control to FTLCODE.  This deliberately does not claim to be
 * a dungeon renderer: no unproven PC34 viewport record is substituted for
 * the still-unbound CSBWin dungeon owner. */
static int m11_csb_present_atari_st_runtime_hud(
    M11_GameViewState *state, unsigned char *framebuffer,
    int framebuffer_width, int framebuffer_height)
{
    const CSB_V1_BootProfile *profile;
    CSB_V1_CSBWinLayout0232 layout;
    CSB_V1_CSBWinHudMaterialPlan0232 plan;
    CSB_V1_CSBWinHudCompositionReceipt0232 receipt;
    unsigned char candidate[320 * 200];
    int y;

    if (!state || !framebuffer || framebuffer_width < 320 ||
        framebuffer_height < 200 || !state->csbAtariStRuntimeHandoffComplete ||
        state->sourceKind != M11_GAME_SOURCE_CSB_BOOT) {
        return 0;
    }
    profile = (const CSB_V1_BootProfile *)state->csbBootProfile;
    if (!profile || (profile->variant_id != CSB_V1_VARIANT_ST20_EN &&
                     profile->variant_id != CSB_V1_VARIANT_ST21_EN) ||
        !profile->graphics_verified || !profile->graphics_path[0]) {
        return 0;
    }
    memset(&layout, 0, sizeof(layout));
    memset(&plan, 0, sizeof(plan));
    memset(&receipt, 0, sizeof(receipt));
    if (!csb_v1_csbwin_layout_0232_read_graphics_dat(profile->graphics_path,
                                                      &layout) ||
        !csb_v1_csbwin_layout_0232_build_hud_material_plan(&layout, &plan)) {
        return 0;
    }
    for (y = 0; y < 200; ++y) {
        memcpy(candidate + (size_t)y * 320u,
               framebuffer + (size_t)y * (size_t)framebuffer_width,
               320u);
    }
    if (!csb_v1_csbwin_layout_0232_compose_hud(
            &plan, m11_csb_csbwin_hud_source_resolver, state, candidate,
            sizeof(candidate), &receipt) || !receipt.valid ||
        receipt.material_count != CSB_V1_CSBWIN_LAYOUT_0232_HUD_MATERIAL_COUNT) {
        return 0;
    }
    for (y = 0; y < 200; ++y) {
        memcpy(framebuffer + (size_t)y * (size_t)framebuffer_width,
               candidate + (size_t)y * 320u, 320u);
    }
    /* C232 owns the completed CSBWin HUD page.  Do not add a host-side
     * progress/diagnostic message here: it would be visible chrome with no
     * CSBWin pixel or text owner. */
    return 1;
}

static int m11_csb_door_panel_family_for_wall(
    CSB_V1_CSBWinViewportWall wall, CSB_V1_CSBWinDoorPanelFamily *out_family)
{
    static const CSB_V1_CSBWinDoorPanelFamily families[
        CSB_V1_CSBWIN_VIEWPORT_WALL_COUNT] = {
        CSB_V1_CSBWIN_DOOR_PANEL_COUNT, CSB_V1_CSBWIN_DOOR_PANEL_F3L1,
        CSB_V1_CSBWIN_DOOR_PANEL_F3, CSB_V1_CSBWIN_DOOR_PANEL_F3R1,
        CSB_V1_CSBWIN_DOOR_PANEL_COUNT, CSB_V1_CSBWIN_DOOR_PANEL_F2L1,
        CSB_V1_CSBWIN_DOOR_PANEL_F2, CSB_V1_CSBWIN_DOOR_PANEL_F2R1,
        CSB_V1_CSBWIN_DOOR_PANEL_F1L1, CSB_V1_CSBWIN_DOOR_PANEL_F1,
        CSB_V1_CSBWIN_DOOR_PANEL_F1R1, CSB_V1_CSBWIN_DOOR_PANEL_COUNT,
        CSB_V1_CSBWIN_DOOR_PANEL_COUNT, CSB_V1_CSBWIN_DOOR_PANEL_COUNT
    };

    if (!out_family || (unsigned int)wall >=
        CSB_V1_CSBWIN_VIEWPORT_WALL_COUNT ||
        families[wall] == CSB_V1_CSBWIN_DOOR_PANEL_COUNT) return 0;
    *out_family = families[wall];
    return 1;
}

/* Viewport.cpp passes the room's DB0 record and the raw door-state bits to
 * DrawDoor.  Keep both lookups on the loaded CSB map: a panel must never
 * borrow the active map's first DoorSet or an invented closed-door state. */
static int m11_csb_atari_st_resolve_door_panel(
    const CSB_V1_DungeonData *dungeon, int level, int direction,
    int party_x, int party_y, int steps_forward, int steps_right,
    uint8_t nearness, uint8_t *out_door_state, int *out_db0_mode,
    uint16_t *out_graphic_index)
{
    const uint8_t *record;
    int map_x;
    int map_y;
    int raw_square;
    int thing;
    int thing_type;
    int thing_size;
    uint16_t door_word;
    uint16_t door_set;

    if (out_door_state) *out_door_state = 0u;
    if (out_db0_mode) *out_db0_mode = 0;
    if (out_graphic_index) *out_graphic_index = 0u;
    if (!dungeon || !out_door_state || !out_db0_mode || !out_graphic_index ||
        level < 0 || level >= dungeon->level_count || nearness > 2u ||
        csb_v1_dungeon_f0150_get_relative_location_pc34(
            direction, steps_forward, steps_right, party_x, party_y,
            &map_x, &map_y) != 0 ||
        (raw_square = csb_v1_dungeon_f0151_get_square_pc34(
            dungeon, level, map_x, map_y)) < 0 ||
        ((raw_square >> 5) & 0x07) != 4 ||
        (raw_square & 0x07) > 5 ||
        (thing = csb_v1_dungeon_get_first_thing(
            dungeon, level, map_x, map_y)) < 0 ||
        !(record = csb_v1_dungeon_get_thing_record(
            dungeon, (uint16_t)thing, &thing_type, NULL, &thing_size)) ||
        thing_type != 0 || thing_size < 4) {
        return 0;
    }
    door_word = (uint16_t)record[2] | ((uint16_t)record[3] << 8);
    door_set = (uint16_t)((door_word & 0x0001u) != 0u
        ? dungeon->map_door_set1[level] : dungeon->map_door_set0[level]);
    if (!csb_v1_csbwin_door_panel_graphic_index(
            door_set, (uint8_t)(door_word & 0x0001u), nearness,
            out_graphic_index)) {
        return 0;
    }
    *out_door_state = (uint8_t)(raw_square & 0x07);
    *out_db0_mode = (door_word & 0x0020u) != 0u;
    return 1;
}

static int m11_csb_blit_atari_st_viewport_graphic(
    M11_GameViewState *state, uint16_t graphic_index, int mirrored,
    const CSB_V1_CSBWinViewportProjectionRectangle *projection,
    unsigned char *viewport, int viewport_width, int viewport_height)
{
    const M11_AssetSlot *asset;
    uint8_t *packed = NULL;
    size_t packed_size = 0u;
    CSB_V1_CSBWinPlanarBitmap planar;
    int ok = 0;

    if (!state || !projection || !viewport ||
        !m11_csb_install_runtime_source_graphic(state, graphic_index)) return 0;
    asset = M11_AssetLoader_Load(&state->assetLoader, graphic_index);
    if (!asset || !asset->loaded || !asset->pixels ||
        asset->width == 0u || asset->height == 0u ||
        !csb_v1_csbwin_planar_bitmap_pack_indexed(
            asset->pixels, asset->width, asset->height, &packed, &packed_size)) {
        goto done;
    }
    memset(&planar, 0, sizeof(planar));
    planar.bytes = packed;
    planar.width = asset->width;
    planar.height = asset->height;
    planar.byte_stride = (uint16_t)(((unsigned)asset->width + 15u) / 16u * 8u);
    ok = packed_size == (size_t)planar.byte_stride * planar.height &&
        csb_v1_csbwin_planar_bitmap_blit_wall_projection(
            &planar, projection, mirrored, viewport, viewport_width,
            viewport_height, viewport_width);
done:
    free(packed);
    return ok;
}

/* CSBWin's Viewport.cpp::FloorAndCeilingOnly builds a 224x136 packed page:
 * 29 rows ceiling, 37 rows black and 70 rows floor.  The active decoder
 * yields the same source pixels as indexed bytes, so re-pack them through
 * the reversible four-plane boundary before TAG0088b2-equivalent wall
 * commands consume their byte strides. */
static int m11_csb_present_atari_st_runtime_viewport(
    M11_GameViewState *state, unsigned char *framebuffer,
    int framebuffer_width, int framebuffer_height)
{
    enum {
        VIEWPORT_X = 48, VIEWPORT_Y = 33, VIEWPORT_WIDTH = 224,
        VIEWPORT_HEIGHT = 136, CEILING_HEIGHT = 29, BLACK_HEIGHT = 37,
        FLOOR_HEIGHT = 70
    };
    static const struct {
        int forward;
        int right;
    } wall_locations[CSB_V1_CSBWIN_VIEWPORT_WALL_COUNT] = {
        {3, -2}, {3, -1}, {3, 0}, {3, 1}, {3, 2},
        {2, -1}, {2, 0}, {2, 1}, {1, -1}, {1, 0}, {1, 1},
        {0, -1}, {0, 0}, {0, 1}
    };
    const CSB_V1_BootProfile *profile;
    const CSB_V1_DungeonData *dungeon;
    CSB_V1_CSBWinViewportLayout022e layout;
    CSB_V1_CSBWinViewportMaterialPlan material_plan;
    const M11_AssetSlot *ceiling;
    const M11_AssetSlot *floor;
    unsigned char viewport[VIEWPORT_WIDTH * VIEWPORT_HEIGHT];
    uint16_t ceiling_graphic;
    uint16_t floor_graphic;
    int floor_set;
    int wall_set;
    int y;
    size_t draw_index;

    if (!state || !framebuffer || framebuffer_width < 320 ||
        framebuffer_height < 200 || !state->csbAtariStRuntimeHandoffComplete ||
        state->sourceKind != M11_GAME_SOURCE_CSB_BOOT) {
        return 0;
    }
    profile = (const CSB_V1_BootProfile *)state->csbBootProfile;
    if (!profile || (profile->variant_id != CSB_V1_VARIANT_ST20_EN &&
                     profile->variant_id != CSB_V1_VARIANT_ST21_EN) ||
        !profile->graphics_verified || !profile->graphics_path[0] ||
        !profile->runtime.dungeon_handle ||
        profile->runtime.current_level < 0 ||
        profile->runtime.current_level >=
            profile->runtime.dungeon_handle->level_count) {
        return 0;
    }
    dungeon = profile->runtime.dungeon_handle;
    floor_set = dungeon->map_floor_set[profile->runtime.current_level];
    wall_set = dungeon->map_wall_set[profile->runtime.current_level];
    if (floor_set < 0 || floor_set > 15 || wall_set < 0 || wall_set > 15 ||
        !csb_v1_csbwin_viewport_layout_022e_read_graphics_dat(
            profile->graphics_path, &layout) ||
        !csb_v1_csbwin_viewport_build_f0128_material_plan(
            (uint16_t)floor_set, (uint16_t)wall_set, &layout,
            &material_plan) || !material_plan.valid ||
        !m11_csb_install_runtime_source_graphic(
            state, material_plan.ceiling_graphic_index) ||
        !m11_csb_install_runtime_source_graphic(
            state, material_plan.floor_graphic_index)) {
        return 0;
    }
    ceiling_graphic = material_plan.ceiling_graphic_index;
    floor_graphic = material_plan.floor_graphic_index;
    ceiling = M11_AssetLoader_Load(&state->assetLoader, ceiling_graphic);
    floor = M11_AssetLoader_Load(&state->assetLoader, floor_graphic);
    if (!ceiling || !floor || !ceiling->loaded || !floor->loaded ||
        !ceiling->pixels || !floor->pixels ||
        ceiling->width != VIEWPORT_WIDTH || ceiling->height != CEILING_HEIGHT ||
        floor->width != VIEWPORT_WIDTH || floor->height != FLOOR_HEIGHT) {
        return 0;
    }
    /* ReDMCSB/CSBWin Viewport.cpp::FloorAndCeilingOnly and TAG0088b2 own
     * this complete Atari page.  It never crosses the PC3.4 F0128 V2.2
     * command compositor, so retire any earlier PC-frame accounting before
     * publishing the source-owned result. */
    state->csbState.runtime_v22_cells_painted = 0;
    memset(viewport, 0, sizeof(viewport));
    memcpy(viewport, ceiling->pixels, (size_t)VIEWPORT_WIDTH * CEILING_HEIGHT);
    memcpy(viewport + (size_t)(CEILING_HEIGHT + BLACK_HEIGHT) * VIEWPORT_WIDTH,
           floor->pixels, (size_t)VIEWPORT_WIDTH * FLOOR_HEIGHT);
    for (draw_index = 0u; draw_index < material_plan.wall_command_count;
         ++draw_index) {
        const CSB_V1_CSBWinViewportMaterialCommand *draw =
            &material_plan.wall_commands[draw_index];
        const M11_AssetSlot *wall;
        uint8_t *packed = NULL;
        size_t packed_size = 0u;
        CSB_V1_CSBWinPlanarBitmap packed_wall;
        int square_type;

        if ((unsigned)draw->wall >= CSB_V1_CSBWIN_VIEWPORT_WALL_COUNT ||
            draw->wall == CSB_V1_CSBWIN_VIEWPORT_WALL_F0) {
            return 0;
        }
        square_type = csb_v1_dungeon_f0153_get_relative_square_type_pc34(
            dungeon, profile->runtime.current_level, profile->runtime.party_dir,
            wall_locations[draw->wall].forward, wall_locations[draw->wall].right,
            profile->runtime.party_x, profile->runtime.party_y);
        if (square_type == 4) {
            CSB_V1_CSBWinDoorPanelFamily family;
            CSB_V1_CSBWinDoorFramePlan door_plan;
            const CSB_V1_CSBWinViewportProjectionRectangle *panel_first;
            const CSB_V1_CSBWinViewportProjectionRectangle *panel_second;
            uint16_t panel_graphic;
            uint8_t door_state;
            int db0_mode;
            size_t door_draw;

            /* CSBWin has no DoorRects family for F3L2/F3R2/F0 lanes; their
             * local-cell owners are separate and must not borrow a frame. */
            if (!m11_csb_door_panel_family_for_wall(draw->wall, &family)) {
                continue;
            }
            if (!csb_v1_csbwin_viewport_build_door_frame_plan(
                    &layout, family, &door_plan)) return 0;
            for (door_draw = 0u; door_draw < door_plan.count; ++door_draw) {
                const CSB_V1_CSBWinDoorFrameDraw *door_draw_command =
                    &door_plan.draws[door_draw];
                uint16_t door_graphic;
                int source_mirrored = door_draw_command->bitmap_slot == 0u;

                if (!csb_v1_csbwin_viewport_graphic_index(
                        (uint16_t)wall_set,
                        (uint16_t)(door_draw_command->bitmap_slot == 0u ? 1u :
                            door_draw_command->bitmap_slot - 1u),
                        &door_graphic) ||
                    !m11_csb_blit_atari_st_viewport_graphic(
                        state, door_graphic,
                        source_mirrored != door_draw_command->mirrored,
                        &door_draw_command->projection, viewport,
                        VIEWPORT_WIDTH, VIEWPORT_HEIGHT)) return 0;
            }
            /* CSBWin Viewport.cpp's facing scripts draw track/frame material
             * before StdDrawDoor.  DrawDoor then selects a real DB0 panel
             * bitmap and one or two state rectangles.  An absent/malformed
             * DB0 record leaves the pre-existing source frame visible rather
             * than manufacturing a panel. */
            if (!m11_csb_atari_st_resolve_door_panel(
                    dungeon, profile->runtime.current_level,
                    profile->runtime.party_dir, profile->runtime.party_x,
                    profile->runtime.party_y,
                    wall_locations[draw->wall].forward,
                    wall_locations[draw->wall].right,
                    draw->wall >= CSB_V1_CSBWIN_VIEWPORT_WALL_F1L1 ? 0u :
                    draw->wall >= CSB_V1_CSBWIN_VIEWPORT_WALL_F2L1 ? 1u : 2u,
                    &door_state, &db0_mode, &panel_graphic)) {
                continue;
            }
            if (!csb_v1_csbwin_viewport_door_panel_projections(
                    &layout, family, door_state, db0_mode,
                    &panel_first, &panel_second)) return 0;
            if (panel_first && !m11_csb_blit_atari_st_viewport_graphic(
                    state, panel_graphic, 0, panel_first, viewport,
                    VIEWPORT_WIDTH, VIEWPORT_HEIGHT)) return 0;
            if (panel_second && !m11_csb_blit_atari_st_viewport_graphic(
                    state, panel_graphic, 0, panel_second, viewport,
                    VIEWPORT_WIDTH, VIEWPORT_HEIGHT)) return 0;
            continue;
        }
        /* Viewport.cpp's DrawCellF* wall branch is entered only for
         * roomSTONE. Every other room kind owns a different source command. */
        if (square_type != 0) continue;
        if (!m11_csb_install_runtime_source_graphic(state, draw->graphic_index)) {
            return 0;
        }
        wall = M11_AssetLoader_Load(&state->assetLoader, draw->graphic_index);
        if (!wall || !wall->loaded || !wall->pixels ||
            wall->width == 0u || wall->height == 0u ||
            !csb_v1_csbwin_planar_bitmap_pack_indexed(
                wall->pixels, wall->width, wall->height, &packed, &packed_size)) {
            free(packed);
            return 0;
        }
        memset(&packed_wall, 0, sizeof(packed_wall));
        packed_wall.bytes = packed;
        packed_wall.width = wall->width;
        packed_wall.height = wall->height;
        packed_wall.byte_stride = (uint16_t)(((unsigned)wall->width + 15u) / 16u * 8u);
        if (packed_size != (size_t)packed_wall.byte_stride * packed_wall.height ||
            !csb_v1_csbwin_planar_bitmap_blit_wall_projection(
                &packed_wall, &draw->projection, draw->mirrored, viewport,
                VIEWPORT_WIDTH, VIEWPORT_HEIGHT, VIEWPORT_WIDTH)) {
            free(packed);
            return 0;
        }
        free(packed);
    }
    for (y = 0; y < VIEWPORT_HEIGHT; ++y) {
        memcpy(framebuffer + (size_t)(VIEWPORT_Y + y) * framebuffer_width + VIEWPORT_X,
               viewport + (size_t)y * VIEWPORT_WIDTH, VIEWPORT_WIDTH);
    }
    return 1;
}

static int m11_render_csb_boot_viewport(M11_GameViewState *state,
                                        unsigned char *framebuffer,
                                        int framebufferWidth,
                                        int framebufferHeight)
{
    CSB_V1_ViewportRuntimeDrawerBinding drawer_binding;
    CSB_V1_ViewportRuntimeDrawCounts draw_counts;
    CSB_V1_FirstLiveDungeonFrameReceipt_PC34 live_receipt;
    M11_CSB_RuntimeSpriteContext runtime_sprite_context;
    size_t framebuffer_bytes;
    unsigned char *candidate_page;

    if (!state || !state->csbBootProfile || !framebuffer) {
        return 0;
    }
    state->csbState.runtime_viewport_source_session_ready = 0;
    state->csbState.runtime_viewport_source_session_generation = 0u;
    state->csbState.runtime_viewport_source_tick = 0u;
    state->csbState.runtime_viewport_pixel_hash = 0u;
    state->csbState.runtime_viewport_draw_counts_hash = 0u;
    state->csbState.runtime_v22_cells_painted = 0;
    if (!m11_csb_dsa_save_runtime_viewport_current(state) ||
        !m11_csb_dsa_restored_timer_transaction_current(state)) {
        return 0;
    }
    if (framebufferWidth < 320 || framebufferHeight < 200) {
        return 0;
    }
    if ((size_t)framebufferWidth > (size_t)-1 / (size_t)framebufferHeight) {
        return 0;
    }
    framebuffer_bytes = (size_t)framebufferWidth * (size_t)framebufferHeight;
    candidate_page = (unsigned char *)malloc(framebuffer_bytes);
    if (!candidate_page) {
        return 0;
    }
    /* F0128/F0115 receives a caller-owned page. Keep the displayed page
     * intact until the complete source-backed viewport and sprite passes
     * succeed, so a failed real-asset route cannot expose a partial frame. */
    memcpy(candidate_page, framebuffer, framebuffer_bytes);

    runtime_sprite_context.state = state;
    runtime_sprite_context.framebuffer_width = framebufferWidth;
    runtime_sprite_context.framebuffer_height = framebufferHeight;
    memset(&drawer_binding, 0, sizeof(drawer_binding));
    drawer_binding.projectile_sprite_drawer =
        m11_csb_viewport_projectile_sprite_drawer;
    drawer_binding.projectile_sprite_user = &runtime_sprite_context;
    drawer_binding.projectile_sprite_drawer_source_bound = 1;
    drawer_binding.projectile_object_sprite_drawer =
        m11_csb_viewport_projectile_object_sprite_drawer;
    drawer_binding.projectile_object_sprite_user = &runtime_sprite_context;
    drawer_binding.explosion_sprite_drawer =
        m11_csb_viewport_explosion_sprite_drawer;
    drawer_binding.explosion_sprite_user = &runtime_sprite_context;
    drawer_binding.object_sprite_drawer =
        m11_csb_viewport_object_sprite_drawer;
    drawer_binding.object_sprite_user = &runtime_sprite_context;
    /* DUNVIEW.C F0115 owns the perspective object bitmap.  If M11 cannot
     * decode that active CSB GRAPHICS.DAT record, the viewport must not fall
     * back to the icon atlas or a diagnostic marker. */
    drawer_binding.object_sprite_drawer_source_bound = 1;
    drawer_binding.object_icon_drawer =
        m11_csb_viewport_object_icon_drawer;
    drawer_binding.object_icon_user = &runtime_sprite_context;
    drawer_binding.group_sprite_drawer =
        m11_csb_viewport_group_sprite_drawer;
    drawer_binding.group_sprite_user = &runtime_sprite_context;
    drawer_binding.group_sprite_drawer_source_bound = 1;
    drawer_binding.runtime_overlay_source_required =
        state->csbDsaSaveRuntimeRouteRequired ? 1 : 0;
    drawer_binding.runtime_overlay_source_admitted =
        m11_csb_dsa_overlay_material_current(state) ? 1 : 0;
    drawer_binding.runtime_overlay_source_hash =
        drawer_binding.runtime_overlay_source_admitted
            ? ((const CSB_V1_StartupRuntimeAssetSession_PC34 *)
                    state->csbStartupRuntimeAssetSession)
                  ->csbgraphics_palette_receipt_hash
            : 0u;
    drawer_binding.real_graphics_session = 1;
    drawer_binding.graphic_provider_callback = m11_csb_viewport_graphic_provider;
    drawer_binding.graphic_provider_user_data = state;

    if (!csb_v1_boot_render_viewport_frame_pc34(
            state->csbBootProfile,
            candidate_page,
            framebufferWidth,
            framebufferHeight,
            &drawer_binding,
            &draw_counts)) {
        free(candidate_page);
        return 0;
    }
    memset(&live_receipt, 0, sizeof(live_receipt));
    if (!csb_v1_boot_first_live_dungeon_frame_receipt_from_session_pc34(
            (const CSB_V1_BootProfile *)state->csbBootProfile,
            (const CSB_V1_StartupRuntimeAssetSession_PC34 *)
                state->csbStartupRuntimeAssetSession,
            &draw_counts, candidate_page, framebufferWidth, framebufferHeight,
            &live_receipt) || !live_receipt.valid ||
        !live_receipt.real_asset_matched ||
        !live_receipt.terminal_session_owned ||
        !live_receipt.viewport_frame_consumed ||
        !live_receipt.no_synthetic_surface) {
        free(candidate_page);
        return 0;
    }
    /* The CSB renderer owns F0128 composition. It reports modern replacements
     * from the exact source command that admitted them, rather than replaying
     * an overlay from M11 after the source draw order has completed. */
    if (state->presentationMode == M12_PRESENTATION_V22_MODERN) {
        state->csbState.runtime_v22_cells_painted =
            draw_counts.v22_f0128_replacement_count;
    } else {
        state->csbState.runtime_v22_cells_painted = 0;
    }
    /* Commit after the optional V2.2 F0128 command replacements.  The page
     * stays transactional: an absent artpack or an unsupported command keeps
     * the verified source frame, while admitted modern pixels reach the host
     * only as part of the same completed frame. */
    memcpy(framebuffer, candidate_page, framebuffer_bytes);
    free(candidate_page);
    state->csbState.runtime_viewport_source_session_ready = 1;
    state->csbState.runtime_viewport_source_session_generation =
        live_receipt.session_generation;
    state->csbState.runtime_viewport_source_tick = live_receipt.source_tick;
    state->csbState.runtime_viewport_pixel_hash = live_receipt.viewport_pixel_hash;
    state->csbState.runtime_viewport_draw_counts_hash =
        live_receipt.draw_counts_hash;
    m11_csb_runtime_overlay_stats_reset(state);
    m11_csb_runtime_overlay_stats_apply(state, &draw_counts);
    return 1;
}

static void m11_clear_csb_v1_party_hud_source_surfaces(
    unsigned char *framebuffer,
    int framebufferWidth,
    int framebufferHeight)
{
    int slot;

    if (!framebuffer || framebufferWidth < 320 || framebufferHeight < 200) {
        return;
    }
    /* ReDMCSB CHAMDRAW.C F0288/F0293 clears C113..C116 and the status
     * rectangles before it can draw party-owned content.  M11 retains its
     * framebuffer, so an absent CSBWin GAMEBLOCK party receipt must actively
     * remove the prior frame rather than leave a host-side party visible. */
    for (slot = 0; slot < CHAMPION_MAX_PARTY; ++slot) {
        DM1_V1_LayoutZoneRectPc34 icon_rect;
        DM1_V1_ChampionStatusRectPc34 status_rect;

        if (dm1_v1_champion_icon_rect_pc34(slot, &icon_rect)) {
            m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                          icon_rect.x, icon_rect.y,
                          icon_rect.w, icon_rect.h, 0u);
        }
        if (dm1_v1_champion_status_box_rect_pc34(slot, &status_rect)) {
            m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                          status_rect.x, status_rect.y,
                          status_rect.w, status_rect.h, 0u);
        }
    }
}

static const M11_GameViewState *m11_csb_v1_party_hud_source_state(
    const M11_GameViewState *state,
    M11_GameViewState *out_state)
{
    CSB_V1_RuntimeM11MirrorReceipt_PC34 receipt;

    if (!state || !out_state ||
        state->sourceKind != M11_GAME_SOURCE_CSB_BOOT ||
        !state->csbBootProfile ||
        !csb_v1_boot_runtime_m11_mirror_receipt_pc34(
            (const CSB_V1_BootProfile *)state->csbBootProfile, &receipt) ||
        !receipt.valid || !receipt.party.valid) {
        return NULL;
    }

    /* The M11 world is a presentation mirror, never a CSB party authority.
     * PANEL.C F0354/CHAMDRAW.C F0287 consume the current GAMEBLOCK/CHARDESC
     * party after ENTRANCE.C F0806 hands the game off.  Rebuild just that
     * surface from the fresh CSB runtime receipt so a stale or caller-seeded
     * M11 party cannot paint names, bars, hands, or position icons. */
    *out_state = *state;
    out_state->world.party = receipt.party.party;
    out_state->leaderHandObjectPresent = receipt.leader_hand_present;
    out_state->leaderHandThing = receipt.leader_hand_thing;
    out_state->leaderHandIconIndex = receipt.leader_hand_icon_index;
    snprintf(out_state->leaderHandObjectName,
             sizeof(out_state->leaderHandObjectName), "%s",
             receipt.leader_hand_object_name);
    return out_state;
}

/* PANEL.C owns the C017/C040 base raster.  Once that source page is live,
 * CHAMDRAW.C, ACTIDRAW.C, CASTER.C, MENUDRAW.C, and TEXT.C may update their
 * individual regions.  Keep their admission in one place: the generic M11
 * DM1 panel code is only a drawing primitive here, never a replacement HUD.
 * The cursor itself remains an SDL host cursor; its held-object/name state is
 * represented by the source-owned C017 leader-hand field below. */
static int m11_csb_v1_runtime_hud_materials_ready(
    const M11_GameViewState *state)
{
    static const struct {
        unsigned int graphic;
        int width;
        int height;
    } required[] = {
        { 28u, 76, 14 }, /* C028 champion direction strip */
        { 10u, 87, 45 }, /* C010 action area */
        { 9u, 87, 25 },  /* C009 spell-area background */
        { 11u, 14, 26 }, /* C011 PC3.4 spell/rune source */
        { 13u, 87, 45 }  /* C013 movement controls */
    };
    size_t index;

    if (!state || state->sourceKind != M11_GAME_SOURCE_CSB_BOOT ||
        !state->csbBootProfile || !state->assetsAvailable ||
        !M11_Font_IsLoaded(&state->originalFont) ||
        state->csbRuntimeHudMaterialPackageIdentity == 0u ||
        state->csbRuntimeHudMaterialPackageIdentity !=
            state->csbStartupExpectedPackageIdentity ||
        !m11_csb_startup_package_identity_current(state)) {
        return 0;
    }
    for (index = 0; index < sizeof(required) / sizeof(required[0]); ++index) {
        const M11_AssetSlot *asset = M11_AssetLoader_Load(
            (M11_AssetLoader *)&state->assetLoader, required[index].graphic);
        if (!asset || !asset->loaded || !asset->pixels ||
            asset->width != required[index].width ||
            asset->height != required[index].height) {
            return 0;
        }
    }
    return 1;
}

static int m11_csb_v1_install_runtime_hud_materials(M11_GameViewState *state)
{
    static const struct {
        unsigned int graphic;
        int width;
        int height;
    } required[] = {
        { 28u, 76, 14 }, { 10u, 87, 45 }, { 9u, 87, 25 },
        { 11u, 14, 26 }, { 13u, 87, 45 }
    };
    size_t index;

    if (!state || state->sourceKind != M11_GAME_SOURCE_CSB_BOOT ||
        !state->csbBootProfile || !m11_csb_startup_package_identity_current(state)) {
        return 0;
    }
    for (index = 0; index < sizeof(required) / sizeof(required[0]); ++index) {
        unsigned char *pixels = NULL;
        int width = 0;
        int height = 0;
        CSB_V1_StartupGraphicDecodeReceipt_PC34 receipt;

        memset(&receipt, 0, sizeof(receipt));
        if (!m11_csb_decode_active_source_graphic(
                (const CSB_V1_BootProfile *)state->csbBootProfile,
                required[index].graphic, &pixels, &width, &height, &receipt) ||
            !receipt.valid || width != required[index].width ||
            height != required[index].height ||
            !M11_AssetLoader_InstallDecodedPixels(&state->assetLoader,
                                                   required[index].graphic,
                                                   pixels,
                                                   (unsigned short)width,
                                                   (unsigned short)height)) {
            free(pixels);
            return 0;
        }
        free(pixels);
    }
    state->csbRuntimeHudMaterialPackageIdentity =
        state->csbStartupExpectedPackageIdentity;
    return 1;
}

/* CHAMDRAW.C F0287/F0291/F0292 and F0320/F0345 use these independent
 * GRAPHICS.DAT records after C017/C040 has been installed.  They are not
 * interchangeable with the generic DM1 cache: all must be admitted from the
 * active CSB package before the shared champion-row consumer may draw. */
static int m11_csb_v1_install_runtime_champion_materials(
    const M11_GameViewState *state)
{
    static const unsigned int graphics[] = {
        8u, 15u, 16u, 28u, 32u, 33u, 34u, 35u, 37u, 38u, 39u
    };
    size_t index;

    if (!state || state->sourceKind != M11_GAME_SOURCE_CSB_BOOT) {
        return 0;
    }
    for (index = 0; index < sizeof(graphics) / sizeof(graphics[0]); ++index) {
        if (!m11_csb_install_runtime_source_graphic(state, graphics[index])) {
            return 0;
        }
    }
    return 1;
}

static void m11_draw_csb_v1_runtime_hud(const M11_GameViewState *state,
                                        unsigned char *framebuffer,
                                        int framebufferWidth,
                                        int framebufferHeight)
{
    M11_GameViewState source_party_state;
    const M11_GameViewState *party_state;

    if (!state || !framebuffer || framebufferWidth < 320 ||
        framebufferHeight < 200) {
        return;
    }

    /* CSB can legitimately enter Prison with no imported party. PANEL.C and
     * MENUDRAW.C still own the C013 movement panel in that state. Previously
     * the CSB-only asset install happened only after a party mirror was
     * available, so the no-party path cleared the screen and then had no
     * authenticated C013 pixels to present. Load the shared source material
     * before branching on party ownership; this does not create a party HUD
     * and keeps a missing GRAPHICS.DAT route fail-closed. */
    if (!m11_csb_v1_runtime_hud_materials_ready(state) &&
        !m11_csb_v1_install_runtime_hud_materials(
            (M11_GameViewState *)state)) {
        m11_clear_csb_v1_party_hud_source_surfaces(
            framebuffer, framebufferWidth, framebufferHeight);
        m11_clear_csb_v1_message_area_source_owned(
            state, framebuffer, framebufferWidth, framebufferHeight);
        return;
    }
    party_state = m11_csb_v1_party_hud_source_state(state,
                                                     &source_party_state);
    if (!party_state) {
        m11_clear_csb_v1_party_hud_source_surfaces(
            framebuffer, framebufferWidth, framebufferHeight);
        /* C013 and C015 have independent source owners.  A missing party
         * receipt must not replace them with an M11 party fallback. */
        m11_draw_v1_movement_arrows(state, framebuffer, framebufferWidth,
                                    framebufferHeight);
        m11_clear_csb_v1_message_area_source_owned(
            state, framebuffer, framebufferWidth, framebufferHeight);
        return;
    }
    if (!m11_csb_v1_install_runtime_champion_materials(state)) {
        /* The shared renderer is permitted to draw the row only after every
         * source-owned CHAMDRAW surface is installed through CSB's decoder. */
        m11_clear_dm1_v1_top_row_receipt_zones(
            framebuffer, framebufferWidth, framebufferHeight);
        m11_clear_csb_v1_message_area_source_owned(
            state, framebuffer, framebufferWidth, framebufferHeight);
        return;
    }
    /* ReDMCSB CHAMDRAW.C F0287/F0290 and DUNVIEW.C F0097 redraw the
     * champion/control surfaces after the dungeon view.  Use the V1 draw
     * lane already backed by the selected CSB GRAPHICS.DAT; do not insert
     * diagnostic labels or substitute generated HUD artwork. */
    m11_draw_v1_champion_icons(party_state, framebuffer, framebufferWidth,
                               framebufferHeight);
    /* ReDMCSB CHAMDRAW.C F0292 prepares champion icons before F0287
     * draws the three bottom-anchored stat bars. */
    m11_draw_party_panel(party_state, framebuffer, framebufferWidth,
                         framebufferHeight);
    m11_draw_v1_spell_area_overlay(party_state, framebuffer, framebufferWidth,
                                   framebufferHeight);
    m11_draw_v1_action_area_overlay(party_state, framebuffer,
                                    framebufferWidth, framebufferHeight);
    m11_draw_v1_movement_arrows(state, framebuffer, framebufferWidth,
                                framebufferHeight);
    m11_draw_v1_leader_hand_object_name(party_state, framebuffer,
                                        framebufferWidth, framebufferHeight);
    m11_clear_csb_v1_message_area_source_owned(
        party_state, framebuffer, framebufferWidth, framebufferHeight);
}

/* The ordinary CSB package identity is fixed when the hash-verified boot
 * receipt opens its runtime session.  Presentation may observe it, but must
 * never repair or replace it after a session has started. */
static int m11_csb_startup_package_identity_current(
    const M11_GameViewState *state)
{
    const CSB_V1_StartupRuntimeAssetSession_PC34 *session;
    const CSB_V1_BootProfile *profile;

    if (!state || state->sourceKind != M11_GAME_SOURCE_CSB_BOOT ||
        state->csbStartupExpectedPackageIdentity == 0u) {
        return 0;
    }
    profile = (const CSB_V1_BootProfile *)state->csbBootProfile;
    /* Atari ST owns its ANIMATE.SCR/DAT startup page directly.  It has no
     * PC34 TITLE.C runtime session to authenticate, so retain the immutable
     * launch identity while that original animation is being presented. */
    if (profile && (profile->variant_id == CSB_V1_VARIANT_ST20_EN ||
                    profile->variant_id == CSB_V1_VARIANT_ST21_EN ||
                    profile->variant_id == CSB_V1_VARIANT_FMTOWNS_EN ||
                    profile->variant_id == CSB_V1_VARIANT_FMTOWNS_JA) &&
        !state->csbStartupRuntimeAssetSession) {
        return 1;
    }
    if (!state->csbStartupRuntimeAssetSession) {
        return 0;
    }
    session = (const CSB_V1_StartupRuntimeAssetSession_PC34 *)
        state->csbStartupRuntimeAssetSession;
    return session->csbStartupPackageIdentity ==
        state->csbStartupExpectedPackageIdentity;
}

static int m11_csb_live_hud_session_ready(const M11_GameViewState *state)
{
    CSB_V1_StartupSessionTerminalReceipt_PC34 terminal;
    CSB_V1_StartupFullRuntimeReceipt_PC34 full_runtime;
    CSB_V1_StartupRuntimeHostSurfaceReceipt_PC34 host_surface;
    CSB_V1_StartupRenderPlan_PC34 plan;
    CSB_V1_StartupRuntimeAssetSession_PC34 *session;
    int ready = 0;

    if (!m11_csb_startup_package_identity_current(state)) {
        return 0;
    }
    session = (CSB_V1_StartupRuntimeAssetSession_PC34 *)
        state->csbStartupRuntimeAssetSession;
    /* LOADSAVE.C F0435 restores a live GAMEBLOCK directly. It has no
     * TITLE.C/ENTRANCE.C terminal page to consume, but must still retain the
     * same verified package, real HUD bindings, and a live save mirror. */
    if (session->direct_resume_loaded) {
        return session->valid && session->real_asset_matched &&
            session->hud_assets_bound && session->generation != 0u &&
            m11_csb_dsa_save_runtime_viewport_current(state) &&
            m11_csb_dsa_restored_timer_transaction_current(state);
    }
    /* ENTRANCE.C F0806 releases C004/C002/C003 only after the opening loop;
     * PANEL.C F0346/F0347 then owns C040/C017 before DUNVIEW.C F0128 starts
     * the first live page. M11 therefore consumes the completed CSB host
     * surface, not merely a resident-surface pointer or an asset-loader copy. */
    if (!csb_v1_startup_session_terminal_receipt_pc34(session, &terminal) ||
        !terminal.valid || !terminal.c017_ready || !terminal.c040_ready ||
        !csb_v1_boot_startup_full_runtime_receipt_from_session_pc34(
            session, &full_runtime) ||
        !full_runtime.valid || !full_runtime.title_to_hud_same_session ||
        !full_runtime.playback_route_ready ||
        full_runtime.session_generation != terminal.session_generation) {
        return 0;
    }
    memset(&plan, 0, sizeof(plan));
    plan.surface = CSB_V1_STARTUP_RENDER_ENTRANCE_CLOSED_PC34;
    plan.title_stage = CSB_V1_STARTUP_STAGE_DUNGEON_RUNTIME_PC34;
    plan.title_special_palette = -1;
    plan.special_palette = -1;
    memset(&host_surface, 0, sizeof(host_surface));
    if (csb_v1_boot_startup_runtime_host_surface_receipt_from_session_pc34(
            session, &plan, terminal.source_tick, &host_surface) &&
        host_surface.valid && host_surface.real_asset_matched &&
        host_surface.no_legacy_wrappers && host_surface.no_synthetic_surface &&
        host_surface.host_surface ==
            CSB_V1_STARTUP_RUNTIME_HOST_SURFACE_HUD_PC34 &&
        host_surface.runtime_hud_decision &&
        host_surface.uses_c017_inventory && host_surface.uses_c040_resurrect &&
        /* C017/C040 is a terminal runtime page.  A retained C001/C004
         * palette is not its source frame and must remain no-draw. Keep this
         * check in the single startup readiness query so the panel blit never
         * replays or mutates the C002/C003 startup plan mid-frame. */
        host_surface.special_palette == -1 &&
        host_surface.title_special_palette == -1 &&
        host_surface.frame.session_generation == terminal.session_generation &&
        host_surface.frame.source_tick == terminal.source_tick &&
        host_surface.host_surface_hash != 0u) {
        ready = 1;
    }
    csb_v1_boot_startup_runtime_host_surface_receipt_release_pc34(
        &host_surface);
    return ready;
}

static int m11_csb_consume_c040_clear_session(M11_GameViewState *state)
{
    CSB_V1_StartupSessionTerminalReceipt_PC34 terminal;
    CSB_V1_StartupSessionLiveHudReceipt_PC34 live_hud;
    const CSB_V1_StartupRuntimeAssetSession_PC34 *session;

    if (!m11_csb_startup_package_identity_current(state)) {
        return 0;
    }
    if (state->candidateMirrorPanelActive ||
        !state->csbState.c040_panel_session_active) {
        return 1;
    }
    session = (const CSB_V1_StartupRuntimeAssetSession_PC34 *)
        state->csbStartupRuntimeAssetSession;
    /* ReDMCSB PANEL.C F0346/F0347 returns from C040 to the neutral C017
     * panel exactly once.  Do not let a later terminal session clear a
     * candidate panel that was presented by an earlier session. */
    if (!csb_v1_startup_session_terminal_receipt_pc34(session, &terminal) ||
        !csb_v1_startup_session_live_hud_receipt_pc34(
            session, &terminal, 1u, state->csbState.c040_panel_source_tick,
            state->csbState.c040_panel_session_generation, &live_hud) ||
        !live_hud.valid || !live_hud.c040_cleared_once ||
        !live_hud.c017_live_base_only) {
        return 0;
    }
    state->csbState.c040_panel_session_active = 0;
    state->csbState.c040_panel_source_tick = 0u;
    state->csbState.c040_panel_session_generation = 0u;
    state->csbState.c040_clear_live_hud_ready = 1;
    state->csbState.c040_clear_source_tick = live_hud.source_tick;
    state->csbState.c040_clear_session_generation =
        live_hud.session_generation;
    return 1;
}

static int m11_draw_csb_v1_inventory_surface(
    M11_GameViewState *state,
    unsigned char *framebuffer,
    int framebufferWidth,
    int framebufferHeight)
{
    const CSB_V1_StartupRuntimeAssetSession_PC34 *session;
    CSB_V1_StartupRuntimeHudPanelReceipt_PC34 receipt;

    if (!state || !framebuffer || !m11_csb_startup_package_identity_current(state) ||
        framebufferWidth < 224 || framebufferHeight < 169) {
        return 0;
    }
    session = (const CSB_V1_StartupRuntimeAssetSession_PC34 *)
        state->csbStartupRuntimeAssetSession;
    /* CSB owns the C017/C040 composition and M11 receives only its completed
     * source receipt. This leaves M11 responsible for the viewport beneath
     * PANEL.C's rectangle, not for any startup asset or transparency rule. */
    if (!csb_v1_boot_startup_runtime_hud_panel_blit_from_session_pc34(
            (CSB_V1_StartupRuntimeAssetSession_PC34 *)session,
            state->candidateMirrorPanelActive ? 1 : 0, framebuffer,
            framebufferWidth, framebufferHeight, &receipt) || !receipt.valid ||
        !receipt.c017_presented ||
        (state->candidateMirrorPanelActive && !receipt.c040_presented)) {
        return 0;
    }
    if (receipt.c040_presented) {
        state->csbState.c040_panel_session_active = 1;
        state->csbState.c040_panel_source_tick = receipt.source_tick;
        state->csbState.c040_panel_session_generation =
            receipt.session_generation;
    }
    /* F0347 has supplied the complete C017 base before any live champion,
     * action, spell, leader-hand/cursor text, or message lane is allowed to
     * touch the page.  This is intentionally after the receipt validation:
     * a failed C017/C040 transaction must never expose a generic inventory
     * renderer in its place. */
    m11_draw_csb_v1_runtime_hud(state, framebuffer, framebufferWidth,
                                framebufferHeight);
    return 1;
}

static void m11_apply_csb_runtime_m11_mirror_receipt(
    M11_GameViewState *state,
    const CSB_V1_RuntimeM11MirrorReceipt_PC34 *receipt)
{
    if (!state || !receipt || !receipt->valid) {
        return;
    }
    state->csbState.level_loaded = receipt->view.level_loaded;
    state->csbState.current_level = receipt->view.current_level;
    state->csbState.current_map_difficulty =
        receipt->view.current_map_difficulty;
    state->csbState.party_x = receipt->view.party_x;
    state->csbState.party_y = receipt->view.party_y;
    state->csbState.party_dir = receipt->view.party_dir;
    state->csbState.tick_count = receipt->view.tick_count;
    if (receipt->party.valid) {
        state->world.party = receipt->party.party;
    }
    if (receipt->leader_hand_present) {
        state->leaderHandObjectPresent = 1;
        state->leaderHandThing = receipt->leader_hand_thing;
        state->leaderHandIconIndex = receipt->leader_hand_icon_index;
        snprintf(state->leaderHandObjectName,
                 sizeof(state->leaderHandObjectName),
                 "%s",
                 receipt->leader_hand_object_name);
    } else {
        state->leaderHandObjectPresent = 0;
        state->leaderHandThing = THING_NONE;
        state->leaderHandIconIndex = -1;
        state->leaderHandObjectName[0] = '\0';
    }
}

static void m11_apply_csb_runtime_startup_session_state_receipt(
    M11_GameViewState *state,
    const CSB_V1_RuntimeStartupSessionStateReceipt_PC34 *receipt)
{
    if (!state || !receipt) {
        return;
    }
    state->csbState.startup_entrance_resume_available =
        receipt->entrance_resume_available ? 1 : 0;
    snprintf(state->csbState.startup_entrance_resume_path,
             sizeof(state->csbState.startup_entrance_resume_path),
             "%s",
             receipt->entrance_resume_path);
    state->csbState.startup_import_available =
        receipt->import_available ? 1 : 0;
    state->csbState.startup_import_champion_count =
        receipt->import_champion_count;
    state->csbState.startup_import_selected_action_index =
        receipt->import_selected_action_index;
    state->csbState.startup_import_preview_active =
        receipt->import_preview_active ? 1 : 0;
    state->csbState.startup_import_utility_state =
        receipt->import_utility_state;
    snprintf(state->csbState.startup_import_dm1_save_path,
             sizeof(state->csbState.startup_import_dm1_save_path),
             "%s",
             receipt->import_dm1_save_path);
    snprintf(state->csbState.startup_import_utility_prompt,
             sizeof(state->csbState.startup_import_utility_prompt),
             "%s",
             receipt->import_utility_prompt);
}

static void m11_audio_emit_source_sound_with_volume(
    M11_GameViewState* state,
    int soundIndex,
    int sourceVolume,
    M11_AudioMarker fallbackMarker);
static void m11_audio_emit_source_sound(
    M11_GameViewState* state,
    int soundIndex,
    M11_AudioMarker fallbackMarker);

static void m11_sync_csb_state_from_boot_profile(M11_GameViewState *state,
                                                 const void *boot_profile)
{
    CSB_V1_RuntimeM11MirrorReceipt_PC34 receipt;
    const CSB_V1_BootProfile *profile;
    const CsbV1AudioRuntime *audio_runtime;
    if (!state || !boot_profile) {
        return;
    }
    profile = (const CSB_V1_BootProfile *)boot_profile;
    if (csb_v1_boot_runtime_m11_mirror_receipt_pc34(
            profile,
            &receipt)) {
        m11_apply_csb_runtime_m11_mirror_receipt(state, &receipt);
    }
    /* ReDMCSB SOUND.C F0064/F0065 owns immediate and delayed playback
     * arbitration. When its profile reports a new completed play, transport
     * that exact PC3.4 GRAPHICS.DAT sample; do not use marker fallback. */
    audio_runtime = &profile->runtime.audio_runtime;
    if (audio_runtime->totalCompletedPlays <
        state->csbRuntimeAudioCompletedPlaysConsumed) {
        /* A newly loaded source runtime starts a fresh transient sequence. */
        state->csbRuntimeAudioCompletedPlaysConsumed = 0u;
    }
    while (state->csbRuntimeAudioCompletedPlaysConsumed <
           audio_runtime->totalCompletedPlays) {
        int16_t sound_index;
        int16_t source_volume;
        uint32_t sequence =
            state->csbRuntimeAudioCompletedPlaysConsumed + 1u;
        if (!csb_v1_audio_runtime_completed_play_details_at(
                audio_runtime, sequence, &sound_index, &source_volume)) {
            /* Do not invent a missed source event if a host failed to keep
             * up with the bounded history. Resume at the current source end. */
            state->csbRuntimeAudioCompletedPlaysConsumed =
                audio_runtime->totalCompletedPlays;
            m11_set_status(state, "AUDIO", "SOURCE EVENT HISTORY EXPIRED");
            break;
        }
        m11_audio_emit_source_sound_with_volume(
            state, sound_index, source_volume, M11_AUDIO_MARKER_NONE);
        state->csbRuntimeAudioCompletedPlaysConsumed = sequence;
    }
    state->csbRuntimeAudioImmediatePlaysConsumed =
        audio_runtime->totalImmediatePlays;
    state->csbRuntimeAudioPendingFlushesConsumed =
        audio_runtime->totalPendingFlushes;
}

static int m11_csb_prepare_atari_st_animation_handoff(
    M11_GameViewState *state)
{
    const CSB_V1_BootProfile *profile;
    CSB_V1_AtariStAnimationTraceReceipt trace;
    char user_data[FSP_PATH_MAX];
    char cache_root[FSP_PATH_MAX];

    if (!state || !state->csbBootProfile) return 0;
    profile = (const CSB_V1_BootProfile *)state->csbBootProfile;
    if ((profile->variant_id != CSB_V1_VARIANT_ST20_EN &&
         profile->variant_id != CSB_V1_VARIANT_ST21_EN) ||
        !profile->asset_root[0] || !FSP_GetUserDataDir(user_data,
            sizeof(user_data)) || !FSP_JoinPath(cache_root,
            sizeof(cache_root), user_data, "cache")) return 0;
    memset(&trace, 0, sizeof(trace));
    if (!csb_v1_atari_st_animation_trace_from_root(profile->asset_root,
            cache_root, &trace) || !trace.valid ||
        trace.waited_vbl_count == 0u) return 0;
    if (trace.played_sound_count >
        CSB_V1_ATARI_ST_ANIMATION_MAX_PLAYED_SOUNDS) return 0;
    state->csbAtariStAnimationEndVbl = trace.waited_vbl_count;
    state->csbAtariStAnimationSoundCount = trace.played_sound_count;
    memset(state->csbAtariStAnimationSoundPlayed, 0,
           sizeof(state->csbAtariStAnimationSoundPlayed));
    memset(state->csbAtariStAnimationSoundBytes, 0,
           sizeof(state->csbAtariStAnimationSoundBytes));
    {
        uint16_t sound_index;
        for (sound_index = 0u;
             sound_index < state->csbAtariStAnimationSoundCount;
             ++sound_index) {
            if (!csb_v1_atari_st_animation_copy_played_sound_from_root(
                    profile->asset_root, cache_root, sound_index,
                    state->csbAtariStAnimationSoundData[sound_index],
                    sizeof(state->csbAtariStAnimationSoundData[sound_index]),
                    &state->csbAtariStAnimationSoundBytes[sound_index],
                    &state->csbAtariStAnimationSoundPeriods[sound_index],
                    &state->csbAtariStAnimationSoundVbls[sound_index], NULL)) {
                return 0;
            }
        }
    }
    state->csbAtariStRuntimeHandoffComplete = 0;
    return 1;
}

static unsigned int m11_csb_atari_st_sound_hash(const uint8_t *bytes,
                                                  size_t byte_count)
{
    unsigned int hash = 2166136261u;
    size_t index;

    if (!bytes || byte_count == 0u) return 0u;
    for (index = 0u; index < byte_count; ++index) {
        hash ^= bytes[index];
        hash *= 16777619u;
    }
    return hash ? hash : 1u;
}

static void m11_csb_play_due_atari_st_animation_sounds(
    M11_GameViewState *state)
{
    uint16_t sound_index;

    if (!state) return;
    for (sound_index = 0u;
         sound_index < state->csbAtariStAnimationSoundCount;
         ++sound_index) {
        const size_t byte_count =
            state->csbAtariStAnimationSoundBytes[sound_index];
        if (state->csbAtariStAnimationSoundPlayed[sound_index] ||
            state->csbAtariStAnimationVbl <
                state->csbAtariStAnimationSoundVbls[sound_index] ||
            byte_count == 0u || byte_count >
                sizeof(state->csbAtariStAnimationSoundData[sound_index])) {
            continue;
        }
        if (M11_Audio_PlayCsbAtariStPsg(&state->audioState,
                state->csbAtariStAnimationSoundData[sound_index],
                (int)byte_count,
                state->csbAtariStAnimationSoundPeriods[sound_index],
                m11_csb_atari_st_sound_hash(
                    state->csbAtariStAnimationSoundData[sound_index],
                    byte_count))) {
            state->csbAtariStAnimationSoundPlayed[sound_index] = 1;
        }
    }
}

/* ANIM.C invokes FTLCODE after its own script ends. Firestaff already owns a
 * verified CSB runtime profile from that exact package, so cross the same
 * program boundary only after the final source VBlank; do not route ST media
 * through the incompatible PC TITLE.C/ENTRANCE.C session. */
static int m11_csb_complete_atari_st_runtime_handoff(M11_GameViewState *state)
{
    CSB_V1_BootProfile *profile;

    if (!state || !state->csbBootProfile ||
        state->csbAtariStRuntimeHandoffComplete ||
        state->csbAtariStAnimationEndVbl == 0u ||
        state->csbAtariStAnimationVbl < state->csbAtariStAnimationEndVbl) {
        return 0;
    }
    profile = (CSB_V1_BootProfile *)state->csbBootProfile;
    if ((profile->variant_id != CSB_V1_VARIANT_ST20_EN &&
         profile->variant_id != CSB_V1_VARIANT_ST21_EN) ||
        !profile->runtime.dungeon_handle) {
        return 0;
    }
    profile->runtime.state = CSB_STATE_GAME;
    state->csbState.startup_title_active = 0;
    state->csbState.startup_entrance_active = 0;
    state->csbState.startup_entrance_dismissed = 1;
    state->csbAtariStRuntimeHandoffComplete = 1;
    m11_sync_csb_state_from_boot_profile(state, profile);
    /* ReDMCSB ANIM.C main lines 2100-2130 finishes its palette curtain and
     * exits without a runtime status message.  Retain the source-owned page
     * rather than publishing a host-generated readiness notification. */
    return 1;
}

