/* TEXT2.C F0041 and MENUDRAW.C F0397/F0398 consume the PC34 M653 interface
 * font, whose local ReDMCSB media mappings resolve only to 695 or 557.  The
 * generic font loader may inspect other 768-byte records for non-HUD callers;
 * this DM1 HUD route must never promote one of those records as a substitute
 * glyph source. */
static int m11_dm1_pc34_hud_font_is_source_bound(
    const M11_GameViewState* state)
{
    int graphic_index;

    if (!state || !state->assetsAvailable || !state->originalFontAvailable ||
        g_activeOriginalFont != &state->originalFont ||
        !M11_Font_IsLoaded(g_activeOriginalFont)) {
        return 0;
    }
    graphic_index = M11_Font_ResolvedGraphicIndex(g_activeOriginalFont);
    return graphic_index == M11_FONT_GRAPHIC_INDEX_PC34 ||
           graphic_index == M11_FONT_GRAPHIC_INDEX_LEGACY;
}

/* Accessibility: in-game font size multiplier. Set from state->fontScale
 * (itself propagated from M12 launcher's fontScale setting) in
 * M11_GameView_Draw.  Used by m11_draw_glyph to scale glyph rendering.
 * 0 = use M11_TextStyle scale directly (backward compatible). */
static int g_m11_font_scale_override = 0;

static void m11_put_pixel(unsigned char* framebuffer,
                          int framebufferWidth,
                          int framebufferHeight,
                          int x,
                          int y,
                          unsigned char color) {
    if (!framebuffer) {
        return;
    }
    if (x < 0 || y < 0 || x >= framebufferWidth || y >= framebufferHeight) {
        return;
    }
    framebuffer[(y * framebufferWidth) + x] = color;
}

static void m11_fill_rect(unsigned char* framebuffer,
                          int framebufferWidth,
                          int framebufferHeight,
                          int x,
                          int y,
                          int w,
                          int h,
                          unsigned char color) {
    int yy;
    int xx;
    for (yy = 0; yy < h; ++yy) {
        for (xx = 0; xx < w; ++xx) {
            m11_put_pixel(framebuffer, framebufferWidth, framebufferHeight,
                          x + xx, y + yy, color);
        }
    }
}


/* Dim a rectangle by setting per-pixel brightness to a darker level.
 * Used for pause/confirm overlays instead of replacing the background. */
static void m11_dim_rect(unsigned char* framebuffer,
                         int framebufferWidth,
                         int framebufferHeight,
                         int x, int y, int w, int h,
                         int dimLevel) {
    for (int yy = 0; yy < h; ++yy) {
        int py = y + yy;
        if (py < 0 || py >= framebufferHeight) continue;
        for (int xx = 0; xx < w; ++xx) {
            int px = x + xx;
            if (px < 0 || px >= framebufferWidth) continue;
            int idx = py * framebufferWidth + px;
            unsigned char raw = framebuffer[idx];
            unsigned char colorIdx = raw & 0x0F;
            /* Set upper nibble to dim level (higher = dimmer) */
            framebuffer[idx] = (unsigned char)((dimLevel << 4) | colorIdx);
        }
    }
}

static void m11_draw_rect(unsigned char* framebuffer,
                          int framebufferWidth,
                          int framebufferHeight,
                          int x,
                          int y,
                          int w,
                          int h,
                          unsigned char color) {
    int i;
    for (i = 0; i < w; ++i) {
        m11_put_pixel(framebuffer, framebufferWidth, framebufferHeight, x + i, y, color);
        m11_put_pixel(framebuffer, framebufferWidth, framebufferHeight, x + i, y + h - 1, color);
    }
    for (i = 0; i < h; ++i) {
        m11_put_pixel(framebuffer, framebufferWidth, framebufferHeight, x, y + i, color);
        m11_put_pixel(framebuffer, framebufferWidth, framebufferHeight, x + w - 1, y + i, color);
    }
}

static void m11_hatch_rect(unsigned char* framebuffer,
                           int framebufferWidth,
                           int framebufferHeight,
                           int x,
                           int y,
                           int w,
                           int h) {
    int yy;
    for (yy = y; yy < y + h; ++yy) {
        int xx;
        for (xx = x; xx < x + w; ++xx) {
            /* DM1 PC VGA VIDEODRV.C F8155_VIDRV_06_HatchScreenBox:
             * leave odd (x^y) pixels untouched and force even checker
             * pixels to black. */
            if (((xx ^ yy) & 1) == 0) {
                m11_put_pixel(framebuffer, framebufferWidth, framebufferHeight,
                              xx, yy, M11_COLOR_BLACK);
            }
        }
    }
}

static void m11_draw_hline(unsigned char* framebuffer,
                           int framebufferWidth,
                           int framebufferHeight,
                           int x1,
                           int x2,
                           int y,
                           unsigned char color) {
    int x;
    if (x2 < x1) {
        int swap = x1;
        x1 = x2;
        x2 = swap;
    }
    for (x = x1; x <= x2; ++x) {
        m11_put_pixel(framebuffer, framebufferWidth, framebufferHeight, x, y, color);
    }
}

static void m11_draw_vline(unsigned char* framebuffer,
                           int framebufferWidth,
                           int framebufferHeight,
                           int x,
                           int y1,
                           int y2,
                           unsigned char color) {
    int y;
    if (y2 < y1) {
        int swap = y1;
        y1 = y2;
        y2 = swap;
    }
    for (y = y1; y <= y2; ++y) {
        m11_put_pixel(framebuffer, framebufferWidth, framebufferHeight, x, y, color);
    }
}

static const M11_Glyph* m11_find_glyph(char ch) {
    size_t i;
    unsigned char uch = (unsigned char)ch;
    if (uch >= 'a' && uch <= 'z') {
        ch = (char)(uch - ('a' - 'A'));
    }
    for (i = 0; i < sizeof(g_font) / sizeof(g_font[0]); ++i) {
        if (g_font[i].ch == ch) {
            return &g_font[i];
        }
    }
    return &g_font[0];
}

/* UTF-8 + Latin Extended glyph lookup.  The M11 5x7 font is
 * byte-oriented (1 char = 1 glyph), so to render the 244
 * accented characters in sv.po (Ö Ä Å ä å) — and the
 * ~25 accented Latin Extended-A letters needed by the other
 * 17 supported languages — we expose a UTF-8-aware variant.
 *
 * The output is rendered as if it were a M11_Glyph: the rows
 * are written into outRows[7] and the M11_Glyph struct is
 * returned with ch = the original char (so the calling
 * m11_draw_glyph doesn't have to change).  If the codepoint
 * is not in the table, *outIsLatinExt is 0 and rows are the
 * SPACE fallback.  *outBytesConsumed is 1 (ASCII), 2 (Latin
 * Extended), 3 (BMP), or 4 (astral); the caller advances the
 * input pointer by that many bytes. */
static M11_Glyph m11_find_glyph_utf8_with_rows(
    const char* p, int* outBytesConsumed, int* outIsLatinExt)
{
    M11_Glyph result;
    unsigned char rows[7];
    int k;
    for (k = 0; k < 7; ++k) rows[k] = 0;
    int rc = m11_find_glyph_utf8(p, outBytesConsumed, rows, outIsLatinExt);
    (void)rc;
    for (k = 0; k < 7; ++k) result.rows[k] = rows[k];
    result.ch = p[0]; /* first byte; M11_Glyph uses 1-byte ch */
    return result;
}

static void m11_draw_glyph(unsigned char* framebuffer,
                           int framebufferWidth,
                           int framebufferHeight,
                           int x,
                           int y,
                           char ch,
                           const M11_TextStyle* style,
                           int drawShadow) {
    const M11_Glyph* glyph = m11_find_glyph(ch);
    int row;
    int col;
    int yy;
    int xx;
    const M11_TextStyle* s = style ? style : &g_text_small;
    int effective_scale = g_m11_font_scale_override > 0
                          ? g_m11_font_scale_override : s->scale;
    for (row = 0; row < 7; ++row) {
        for (col = 0; col < 5; ++col) {
            if ((glyph->rows[row] & (1 << (4 - col))) == 0) {
                continue;
            }
            for (yy = 0; yy < effective_scale; ++yy) {
                for (xx = 0; xx < effective_scale; ++xx) {
                    int shadowX = drawShadow ? s->shadowDx * effective_scale : 0;
                    int shadowY = drawShadow ? s->shadowDy * effective_scale : 0;
                    m11_put_pixel(framebuffer, framebufferWidth, framebufferHeight,
                                  x + col * effective_scale + xx + shadowX,
                                  y + row * effective_scale + yy + shadowY,
                                  drawShadow ? s->shadowColor : s->color);
                }
            }
        }
    }
}

/* Forward declaration for original-font text renderer */
static void m11_draw_text_original(
    const M11_FontState* font,
    unsigned char* framebuffer,
    int framebufferWidth,
    int framebufferHeight,
    int x,
    int y,
    const char* text,
    const M11_TextStyle* style);

static void m11_draw_text(unsigned char* framebuffer,
                          int framebufferWidth,
                          int framebufferHeight,
                          int x,
                          int y,
                          const char* text,
                          const M11_TextStyle* style) {
    int cursor = x;
    size_t i;
    M11_TextStyle chromeScratch;
    const M11_TextStyle* s = m11_chrome_remap_style(style, &chromeScratch);
    if (!text) {
        return;
    }
    /* Use original DM1 font when available */
    if (g_activeOriginalFont && M11_Font_IsLoaded(g_activeOriginalFont)) {
        m11_draw_text_original(g_activeOriginalFont, framebuffer,
            framebufferWidth, framebufferHeight, x, y, text, s);
        return;
    }
    /* A real DM1 session must never replace M653 with Firestaff's diagnostic
     * 5x7 host font.  The source font is loaded from the authenticated
     * GRAPHICS.DAT bind; if that bind failed, leave the source text undrawn
     * rather than changing its glyphs or spacing. */
    if (g_drawState && m11_is_dm1_source_kind(g_drawState->sourceKind)) {
        return;
    }
    for (i = 0; text[i] != '\0'; /* i advances per UTF-8 codepoint */) {
        int consumed = 1;
        int isLatinExt = 0;
        M11_Glyph g = m11_find_glyph_utf8_with_rows(&text[i], &consumed, &isLatinExt);
        char ch_for_draw = g.ch;
        if (isLatinExt) {
            /* Direct draw using g.rows; the ch field is irrelevant
             * for the Latin Extended path because m11_draw_glyph
             * uses g.rows directly when ch is non-ASCII.  We call
             * the existing renderer to keep the shadow / scale /
             * tracking logic identical. */
            ch_for_draw = (char)0x80; /* sentinel: ASCII lookup
                                          will return space, but
                                          we want to render g.rows
                                          instead.  We do that by
                                          directly iterating. */
        }
        /* Render the decoded glyph.  When the byte is a
         * non-ASCII UTF-8 lead byte, m11_find_glyph returns the
         * space glyph; we must instead use g.rows directly. */
        if (isLatinExt || (unsigned char)ch_for_draw >= 0x80) {
            int effective_scale = (g_m11_font_scale_override > 0
                                   ? g_m11_font_scale_override : s->scale);
            int row, col, yy, xx;
            for (row = 0; row < 7; ++row) {
                for (col = 0; col < 5; ++col) {
                    if ((g.rows[row] & (1 << (4 - col))) == 0) continue;
                    for (yy = 0; yy < effective_scale; ++yy) {
                        for (xx = 0; xx < effective_scale; ++xx) {
                            int shadowX = s->shadowDx * effective_scale;
                            int shadowY = s->shadowDy * effective_scale;
                            m11_put_pixel(framebuffer, framebufferWidth, framebufferHeight,
                                          cursor + col * effective_scale + xx + shadowX,
                                          y + row * effective_scale + yy + shadowY,
                                          s->shadowColor);
                            m11_put_pixel(framebuffer, framebufferWidth, framebufferHeight,
                                          cursor + col * effective_scale + xx,
                                          y + row * effective_scale + yy,
                                          s->color);
                        }
                    }
                }
            }
            cursor += (5 * effective_scale) + s->tracking;
        } else {
            m11_draw_glyph(framebuffer, framebufferWidth, framebufferHeight,
                           cursor, y, ch_for_draw, s, 1);
            m11_draw_glyph(framebuffer, framebufferWidth, framebufferHeight,
                           cursor, y, ch_for_draw, s, 0);
            int effective_scale = g_m11_font_scale_override > 0
                                  ? g_m11_font_scale_override : s->scale;
            cursor += (5 * effective_scale) + s->tracking;
        }
        i += (size_t)consumed;
    }
}

static unsigned char m11_ra_overlay_color(unsigned int rgba,
                                          Firestaff_RA_OverlayCommandType type) {
    if (type == FIRESTAFF_RA_OVERLAY_COMMAND_TEXT) {
        if (rgba == 0xff4d4dffu) {
            return M11_COLOR_LIGHT_RED;
        }
        if (rgba == 0xffa64dffu || rgba == 0xffd65affu) {
            return M11_COLOR_YELLOW;
        }
        if (rgba == 0xcfd5e6ffu) {
            return M11_COLOR_SILVER;
        }
        return M11_COLOR_WHITE;
    }
    if (rgba == 0xff4d4dffu) {
        return M11_COLOR_RED;
    }
    if (rgba == 0xffa64dffu) {
        return M11_COLOR_ORANGE;
    }
    if (rgba == 0xffd65affu) {
        return M11_COLOR_YELLOW;
    }
    if (rgba == 0x5cc8ffffu) {
        return M11_COLOR_LIGHT_CYAN;
    }
    return M11_COLOR_BLACK;
}

static void m11_draw_ra_overlay(const M11_GameViewState* state,
                                unsigned char* framebuffer,
                                int framebufferWidth,
                                int framebufferHeight) {
    Firestaff_RA_OverlayCommand commands[FIRESTAFF_RA_OVERLAY_COMMAND_MAX];
    size_t count;
    size_t i;
    M11_TextStyle style;

    if (!state || !framebuffer) {
        return;
    }
    count = firestaff_ra_overlay_build_commands(
        &state->retroAchievementsOverlay,
        framebufferWidth,
        framebufferHeight,
        commands,
        sizeof(commands) / sizeof(commands[0]));
    for (i = 0; i < count; ++i) {
        Firestaff_RA_OverlayCommand* cmd = &commands[i];
        unsigned char color = m11_ra_overlay_color(cmd->rgba, cmd->type);
        if (cmd->type == FIRESTAFF_RA_OVERLAY_COMMAND_RECT ||
            cmd->type == FIRESTAFF_RA_OVERLAY_COMMAND_BADGE) {
            m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                          cmd->x, cmd->y, cmd->w, cmd->h, color);
            if (cmd->type == FIRESTAFF_RA_OVERLAY_COMMAND_BADGE) {
                m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                              cmd->x + 2, cmd->y + 2,
                              cmd->w - 4, cmd->h - 4, M11_COLOR_BLACK);
                m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                              cmd->x + 7, cmd->y + 13, "RA", &g_text_small);
            }
        } else if (cmd->type == FIRESTAFF_RA_OVERLAY_COMMAND_TEXT) {
            style = g_text_small;
            style.color = color;
            style.shadowDx = 0;
            style.shadowDy = 0;
            m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                          cmd->x, cmd->y, cmd->text, &style);
        }
    }
}

/* TEXT2.C F0644 writes a six-by-six visible M653 cell using a baseline,
 * rather than the top-left origin used by the generic inscription renderer.
 * MEDIA508 derives the target top as baseline - 4.  Keep that conversion in
 * one primitive so F0387 and F0397/F0398 cannot slowly diverge. */
enum { M11_DM1_M653_BASELINE_TO_TOP_PC34 = 4 };

static int m11_draw_dm1_m653_cell_clipped_at_baseline(
    const M11_FontState* font,
    unsigned char* framebuffer,
    int framebufferWidth,
    int framebufferHeight,
    int baselineX,
    int baselineY,
    unsigned char ch,
    unsigned char foreground,
    unsigned char background,
    int clipX,
    int clipY,
    int clipW,
    int clipH)
{
    const int fontX = ((int)ch * M11_FONT_CHAR_CELL_WIDTH) +
                      M11_FONT_X_OFFSET;
    const int topY = baselineY - M11_DM1_M653_BASELINE_TO_TOP_PC34;
    int row;

    if (!font || !M11_Font_IsLoaded(font) || !framebuffer ||
        clipW <= 0 || clipH <= 0) {
        return 0;
    }
    for (row = 0; row < M11_FONT_CHAR_VISIBLE_H; ++row) {
        int col;
        for (col = 0; col < M11_FONT_CHAR_VISIBLE_W; ++col) {
            const int dstX = baselineX + col;
            const int dstY = topY + row;
            if (dstX >= clipX && dstX < clipX + clipW &&
                dstY >= clipY && dstY < clipY + clipH &&
                dstX >= 0 && dstX < framebufferWidth &&
                dstY >= 0 && dstY < framebufferHeight) {
                framebuffer[dstY * framebufferWidth + dstX] =
                    M11_Font_GetPixel(font, fontX + col, row)
                        ? foreground : background;
            }
        }
    }
    return 1;
}

static int m11_draw_dm1_m653_cell_at_baseline(
    const M11_FontState* font,
    unsigned char* framebuffer,
    int framebufferWidth,
    int framebufferHeight,
    int baselineX,
    int baselineY,
    unsigned char ch,
    unsigned char foreground,
    unsigned char background)
{
    return m11_draw_dm1_m653_cell_clipped_at_baseline(
        font, framebuffer, framebufferWidth, framebufferHeight,
        baselineX, baselineY, ch, foreground, background,
        0, 0, framebufferWidth, framebufferHeight);
}

static void m11_draw_dm1_ui_text_trailing_spaces(
    const M11_GameViewState* state,
    unsigned char* framebuffer,
    int framebufferWidth,
    int framebufferHeight,
    int x,
    int y,
    const char* text,
    int maxChars,
    unsigned char fgColor,
    unsigned char bgColor,
    const DM1_V1_ActionAreaRectPc34* clipRect) {
    int i;
    if (!framebuffer || maxChars <= 0 || !clipRect ||
        clipRect->w <= 0 || clipRect->h <= 0) {
        return;
    }
    /* ACTIDRAW.C F0387 -> TEXT2.C writes the fixed native cell font into
     * C113..C115.  The global host fontScale is valid for Firestaff text,
     * but made source action names such as WAR CRY oversized and clipped. */
    if (m11_dm1_pc34_hud_font_is_source_bound(state)) {
        /* TEXT2.C F0041 pads the field with spaces after the FIRST NUL;
         * it never resumes.  G0490 action names live in one packed
         * NUL-separated table, so an unlatched terminator printed the
         * NEXT table entry into the trailing cells ("WAR CRY" bled
         * "STAB", "PUNCH" bled "KICK"). */
        int terminated = 0;
        for (i = 0; i < maxChars; ++i) {
            unsigned char ch = ' ';
            if (!terminated && text && text[i] != '\0') {
                ch = (unsigned char)text[i];
            } else {
                terminated = 1;
            }
            (void)m11_draw_dm1_m653_cell_clipped_at_baseline(
                g_activeOriginalFont, framebuffer, framebufferWidth,
                framebufferHeight,
                x + (i * DM1_V1_ACTION_MENU_TEXT_CELL_ADVANCE_PC34), y,
                ch, fgColor, bgColor,
                clipRect->x, clipRect->y, clipRect->w, clipRect->h);
        }
        return;
    }
    /* TEXT2.C has no host-font alternative.  Missing authentic font data
     * must leave an exact cleared native cell, never a substituted glyph. */
    for (i = 0; i < maxChars; ++i) {
        m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                      x + (i * DM1_V1_ACTION_MENU_TEXT_CELL_ADVANCE_PC34),
                      y - M11_DM1_M653_BASELINE_TO_TOP_PC34,
                      DM1_V1_ACTION_MENU_TEXT_CELL_ADVANCE_PC34,
                      M11_FONT_CHAR_VISIBLE_H,
                      bgColor);
    }
}

/* CHAMDRAW.C F0292 writes Name[8] through F0053 into a 43x7 status strip.
 * The strip is cleared by its caller; TEXT2 then emits at most seven native
 * 6px cells from x+1,y=5.  F0053's Y coordinate is the text baseline, while
 * M11_Font_DrawChar expects the first bitmap row.  Convert at this boundary
 * so the 6-pixel glyph remains within C159..C162's seven-row strip. */
static void m11_draw_dm1_status_name_text(unsigned char* framebuffer,
                                          int framebufferWidth,
                                          int framebufferHeight,
                                          int x,
                                          int y,
                                          const char* text,
                                          unsigned char fgColor,
                                          unsigned char bgColor) {
    int i;
    int charCount = 0;
    int drawX;
    if (!framebuffer || !g_activeOriginalFont ||
        !M11_Font_IsLoaded(g_activeOriginalFont)) {
        return;
    }
    /* CHAMDRAW.C F0292 delegates the C159..C162 name strips to F0650,
     * which centers the bounded seven-character Name[] field. The caller
     * supplies C163's one-pixel text inset, so recover the C159 field left
     * before applying the original 43-pixel zone geometry. */
    while (charCount < DM1_V1_CPNBC_NAME_FIELD_VISIBLE_CHARS_PC34 &&
           text && text[charCount] != '\0') {
        ++charCount;
    }
    drawX = x - DM1_V1_CPNBC_NAME_BOX_LEFT_PAD_PC34 +
        (DM1_V1_CPNBC_NAME_BOX_LEFT_TO_RIGHT_PC34 -
         charCount * DM1_V1_CPNBC_GLYPH_WIDTH_PC34) / 2;

    for (i = 0; i < charCount; ++i) {
        unsigned char ch;
        ch = (unsigned char)text[i];
        (void)M11_Font_DrawChar(
            g_activeOriginalFont, framebuffer, framebufferWidth,
            framebufferHeight,
            drawX + i * DM1_V1_CPNBC_GLYPH_WIDTH_PC34,
            y - (M11_FONT_CHAR_VISIBLE_H - 1),
            ch, fgColor, (int)bgColor, 1);
    }
}

/* CHAMDRAW.C F0623:697 passes F0288(damage, C0_FALSE, 3) to F0053 with
 * C15 foreground and C08 background. A missing original font is no-draw. */
static void m11_draw_v1_damage_number_text(unsigned char* framebuffer,
                                           int framebufferWidth,
                                           int framebufferHeight,
                                           int x,
                                           int y,
                                           const char* text) {
    int i;
    if (!framebuffer || !g_activeOriginalFont ||
        !M11_Font_IsLoaded(g_activeOriginalFont)) {
        return;
    }
    /* F0053 receives the text baseline.  M11_Font_DrawChar receives the
     * first visible bitmap row; converting here keeps the number inside the
     * C015/C016 source surface instead of painting over C159..C162 names. */
    y -= (M11_FONT_CHAR_VISIBLE_H - 1);
    for (i = 0; i < 3; ++i) {
        if (!text || text[i] == '\0') {
            break;
        }
        (void)M11_Font_DrawChar(
            g_activeOriginalFont, framebuffer, framebufferWidth,
            framebufferHeight, x + i * DM1_V1_CPNBC_GLYPH_WIDTH_PC34, y,
            (unsigned char)text[i], M11_COLOR_WHITE, M11_COLOR_RED, 1);
    }
}

static void m11_execute_csb_startup_primitive_commands(
    unsigned char *framebuffer,
    int framebufferWidth,
    int framebufferHeight,
    const CSB_V1_StartupRenderPlan_PC34 *plan)
{
    int i;
    if (!plan || !framebuffer || framebufferWidth <= 0 ||
        framebufferHeight <= 0) {
        return;
    }
    for (i = 0; i < plan->primitive_command_count &&
                i < CSB_V1_STARTUP_PRIMITIVE_COMMAND_CAP_PC34; ++i) {
        const CSB_V1_StartupPrimitiveCommand_PC34 *cmd =
            &plan->primitive_commands[i];
        if (!cmd->visible || cmd->w <= 0 || cmd->h <= 0) {
            continue;
        }
        switch (cmd->kind) {
        case CSB_V1_STARTUP_PRIMITIVE_FILL_RECT_PC34:
            m11_fill_rect(framebuffer,
                          framebufferWidth,
                          framebufferHeight,
                          cmd->x,
                          cmd->y,
                          cmd->w,
                          cmd->h,
                          (unsigned char)cmd->color);
            break;
        case CSB_V1_STARTUP_PRIMITIVE_DRAW_RECT_PC34:
            m11_draw_rect(framebuffer,
                          framebufferWidth,
                          framebufferHeight,
                          cmd->x,
                          cmd->y,
                          cmd->w,
                          cmd->h,
                          (unsigned char)cmd->color);
            break;
        case CSB_V1_STARTUP_PRIMITIVE_DOOR_PANEL_PC34:
            m11_fill_rect(framebuffer,
                          framebufferWidth,
                          framebufferHeight,
                          cmd->x,
                          cmd->y,
                          cmd->w,
                          cmd->h,
                          (unsigned char)cmd->color);
            m11_fill_rect(framebuffer,
                          framebufferWidth,
                          framebufferHeight,
                          cmd->x,
                          cmd->y,
                          cmd->w,
                          1,
                          (unsigned char)cmd->light_edge_color);
            m11_fill_rect(framebuffer,
                          framebufferWidth,
                          framebufferHeight,
                          cmd->x,
                          cmd->y + cmd->h - 1,
                          cmd->w,
                          1,
                          (unsigned char)cmd->dark_edge_color);
            m11_fill_rect(framebuffer,
                          framebufferWidth,
                          framebufferHeight,
                          cmd->x,
                          cmd->y,
                          1,
                          cmd->h,
                          (unsigned char)cmd->light_edge_color);
            m11_fill_rect(framebuffer,
                          framebufferWidth,
                          framebufferHeight,
                          cmd->x + cmd->w - 1,
                          cmd->y,
                          1,
                          cmd->h,
                          (unsigned char)cmd->dark_edge_color);
            break;
        case CSB_V1_STARTUP_PRIMITIVE_NONE_PC34:
        default:
            break;
        }
    }
}

