static int m11_dialog_source_split_two_lines(const char* text,
                                             char* line1,
                                             size_t line1Size,
                                             char* line2,
                                             size_t line2Size,
                                             int zoneWidth) {
    int textW;
    int maxW;
    int best = -1;
    int i;
    if (!text || !line1 || !line2 || line1Size == 0 || line2Size == 0) return 0;
    if (zoneWidth <= 0) zoneWidth = 77;
    textW = m11_measure_text_pixels(text, &g_text_shadow);
    maxW = zoneWidth - (zoneWidth >> 3);
    if (textW <= maxW) {
        snprintf(line1, line1Size, "%s", text);
        line2[0] = '\0';
        return 1;
    }
    if (maxW > textW - (textW >> 3)) {
        maxW = textW - (textW >> 3);
    }
    for (i = 1; text[i] != '\0'; ++i) {
        if (text[i] == ' ') {
            char tmp[128];
            size_t n = (size_t)i < sizeof(tmp) - 1 ? (size_t)i : sizeof(tmp) - 1;
            memcpy(tmp, text, n);
            tmp[n] = '\0';
            if (m11_measure_text_pixels(tmp, &g_text_shadow) <= maxW) {
                best = i;
            }
        }
    }
    if (best <= 0) {
        best = maxW / 6;
        if (best < 1) best = 1;
    }
    if ((size_t)best >= line1Size) best = (int)line1Size - 1;
    memcpy(line1, text, (size_t)best);
    line1[best] = '\0';
    snprintf(line2, line2Size, "%s", text + best + (text[best] == ' ' ? 1 : 0));
    return 2;
}

static void m11_draw_dialog_choice_text(unsigned char* framebuffer,
                                        int framebufferWidth,
                                        int framebufferHeight,
                                        int viewportX,
                                        int viewportY,
                                        int width,
                                        const char* text) {
    M11_TextStyle choiceStyle = g_text_shadow;
    choiceStyle.color = M11_COLOR_WHITE;
    choiceStyle.shadowColor = M11_COLOR_BROWN;
    if (!text || text[0] == '\0') return;
    m11_draw_text_centered_in_rect(framebuffer,
                                   framebufferWidth,
                                   framebufferHeight,
                                   M11_VIEWPORT_X + viewportX,
                                   M11_VIEWPORT_Y + viewportY,
                                   width,
                                   text,
                                   &choiceStyle);
}

static void m11_draw_dialog_choices_source(const M11_GameViewState* state,
                                           unsigned char* framebuffer,
                                           int framebufferWidth,
                                           int framebufferHeight) {
    int i;
    if (!state || state->dialogChoiceCount <= 0) return;
    for (i = 0; i < state->dialogChoiceCount && i < 4; ++i) {
        DM1_V1_DialogRectPc34 r;
        if (!dm1_v1_dialog_choice_text_rect_pc34(state->dialogChoiceCount,
                                                 i, &r)) {
            continue;
        }
        if (state->csbDiskMenuActive &&
            state->csbDiskMenuSelectedChoice == i + 1) {
            M11_TextStyle selectedStyle = g_text_shadow;
            selectedStyle.color = M11_COLOR_YELLOW;
            selectedStyle.shadowColor = M11_COLOR_BROWN;
            m11_draw_text_centered_in_rect(framebuffer, framebufferWidth,
                                           framebufferHeight,
                                           M11_VIEWPORT_X + r.x,
                                           M11_VIEWPORT_Y + r.y, r.w,
                                           state->dialogChoices[i],
                                           &selectedStyle);
        } else {
            m11_draw_dialog_choice_text(framebuffer, framebufferWidth,
                                        framebufferHeight,
                                        r.x, r.y, r.w,
                                        state->dialogChoices[i]);
        }
    }
}

static void m11_copy_endgame_rect(const DM1_V1_EndgameRectPc34* rect,
                                  int* outX,
                                  int* outY,
                                  int* outW,
                                  int* outH)
{
    if (!rect) return;
    if (outX) *outX = rect->x;
    if (outY) *outY = rect->y;
    if (outW) *outW = rect->w;
    if (outH) *outH = rect->h;
}

static int m11_dialog_choice_at_point(const M11_GameViewState* state,
                                      int x,
                                      int y) {
    int vx = x - M11_VIEWPORT_X;
    int vy = y - M11_VIEWPORT_Y;
    int i;
    if (!state || state->dialogChoiceCount <= 0) return 0;

    /* The plain ESC confirm uses the same scale-aware centered dialog
     * layout as the renderer.  The
     * unsaved-game guard is different: ReDMCSB LOADSAVE.C lines 1371-1379
     * draws the ordinary two-choice source dialog with SAVE AND QUIT first
     * and CANCEL second, then F0424_DIALOG_GetChoice returns C2_CANCEL for
     * the lower choice.  Let that guard use C456/C457 below so its click
     * zones match what is drawn. */
    if (state->returnToMenuConfirmActive && !state->quitGuardActive &&
        state->dialogChoiceCount == 2) {
        M11_ReturnConfirmDialogLayout layout;
        m11_return_confirm_dialog_layout_for(state, M11_FB_WIDTH,
                                             M11_FB_HEIGHT, &layout);
        int cdlgX = layout.boxX;
        int choiceY = layout.choiceY;
        int hitY = choiceY - 5;
        int choiceW = layout.choiceW;
        if (y >= hitY && y < hitY + 25) {
            if (x >= cdlgX && x < cdlgX + choiceW) return 1;       /* YES */
            if (x >= cdlgX + choiceW && x < cdlgX + 2 * choiceW) return 2; /* NO */
        }
        return 0;
    }

    if (vx < 0 || vy < 0 || vx >= M11_VIEWPORT_W || vy >= M11_VIEWPORT_H) return 0;
    for (i = 0; i < state->dialogChoiceCount && i < 4; ++i) {
        DM1_V1_DialogRectPc34 r;
        if (!dm1_v1_dialog_choice_hit_rect_pc34(state->dialogChoiceCount,
                                                i, &r)) {
            continue;
        }
        if (vx >= r.x && vx < r.x + r.w && vy >= r.y && vy < r.y + r.h) {
            return i + 1;
        }
    }
    return 0;
}

/* Draw text using the original DM1 font when available, with shadow.
 * Falls back to the builtin hardcoded font otherwise. */
static void m11_draw_text_original(
    const M11_FontState* font,
    unsigned char* framebuffer,
    int framebufferWidth,
    int framebufferHeight,
    int x,
    int y,
    const char* text,
    const M11_TextStyle* style)
{
    M11_TextStyle chromeScratch;
    const M11_TextStyle* s = m11_chrome_remap_style(style, &chromeScratch);
    if (!text) return;
    if (font && M11_Font_IsLoaded(font)) {
        /* Accessibility: apply fontScale override to original DM1 font */
        int effective_scale = g_m11_font_scale_override > 0
                              ? g_m11_font_scale_override : s->scale;
        /* Shadow pass */
        if (s->shadowDx != 0 || s->shadowDy != 0) {
            M11_Font_DrawString(font, framebuffer, framebufferWidth,
                framebufferHeight, x + s->shadowDx, y + s->shadowDy,
                text, s->shadowColor, -1, effective_scale);
        }
        /* Foreground pass */
        M11_Font_DrawString(font, framebuffer, framebufferWidth,
            framebufferHeight, x, y, text, s->color, -1, effective_scale);
    } else {
        m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                      x, y, text, s);
    }
}

static const char* m11_direction_name(int dir) {
    switch (dir) {
        case DIR_NORTH: return "NORTH";
        case DIR_EAST: return "EAST";
        case DIR_SOUTH: return "SOUTH";
        case DIR_WEST: return "WEST";
        default: return "UNKNOWN";
    }
}

static const char* m11_source_name(M11_GameSourceKind sourceKind) {
    switch (sourceKind) {
        case M11_GAME_SOURCE_CUSTOM_DUNGEON:
            return "CUSTOM";
        case M11_GAME_SOURCE_DIRECT_DUNGEON:
            return "DIRECT";
        case M11_GAME_SOURCE_NEXUS_DGN:
            return "NEXUS";
        case M11_GAME_SOURCE_THERON_TRACK02:
            return "THERON";
        case M11_GAME_SOURCE_CSB_BOOT:
            return "CSB";
        default:
            return "BUILTIN";
    }
}

static unsigned int m11_audio_source_fnv1a(const uint8_t *bytes, size_t count) {
    unsigned int hash = 2166136261u;
    size_t index;

    if (!bytes || count == 0u) {
        return 0u;
    }
    for (index = 0u; index < count; ++index) {
        hash ^= bytes[index];
        hash *= 16777619u;
    }
    return hash;
}

static void m11_audio_emit_source_sound_with_volume(
    M11_GameViewState* state,
    int soundIndex,
    int sourceVolume,
    M11_AudioMarker fallbackMarker) {
    const CSB_V1_BootProfile *csbProfile;
    CsbV1Pc34SoundPayload payload;
    if (!state) {
        return;
    }
    if (m11_is_dm1_source_kind(state->sourceKind)) {
        /* DM1 SOUND.C F0060 owns the event's SND3 sample.  A missing or
         * malformed source record is silent; a generated marker would make
         * an unverified effect sound plausible while being wrong. */
        (void)M11_Audio_EmitSourceSoundIndex(&state->audioState, soundIndex);
        return;
    }
    if (state->sourceKind == M11_GAME_SOURCE_CSB_BOOT) {
        /* CSB PC3.4 owns its effect samples in the executable-selected
         * GRAPHICS.DAT table, not DM1's SND3 namespace. Do not turn a missing
         * source record into a generic marker. */
        csbProfile = (const CSB_V1_BootProfile *)state->csbBootProfile;
        memset(&payload, 0, sizeof(payload));
        if (csbProfile && csbProfile->graphics_path[0] != '\0' &&
            csb_v1_audio_runtime_load_pc34_sound_payload(
                csbProfile->graphics_path, (int16_t)soundIndex, &payload)) {
            (void)M11_Audio_PlayCsbPc34RuntimePcmAtSourceVolume(
                &state->audioState, payload.bytes, (int)payload.byteCount,
                (int)payload.spec.period,
                m11_audio_source_fnv1a(payload.bytes, payload.byteCount),
                sourceVolume);
        }
        csb_v1_audio_runtime_pc34_sound_payload_free(&payload);
        return;
    }
    (void)M11_Audio_EmitSoundIndex(&state->audioState, soundIndex,
                                    fallbackMarker);
}

static void m11_audio_emit_source_sound(M11_GameViewState* state,
                                        int soundIndex,
                                        M11_AudioMarker fallbackMarker) {
    m11_audio_emit_source_sound_with_volume(state, soundIndex, 3,
                                            fallbackMarker);
}

