static void m11_audio_emit_for_emission(M11_GameViewState* state,
                                        const struct TickEmission_Compat* emission) {
    DM1_V1_AudioEmissionPlanPc34 plan;
    if (!state || !emission) {
        return;
    }
    if (!DM1_V1_BuildAudioEmissionPlanPc34(emission, &plan)) {
        return;
    }
    if (plan.route == DM1_V1_AUDIO_EMISSION_ROUTE_SOURCE_SOUND) {
        (void)M11_Audio_EmitSourceSoundIndex(&state->audioState,
                                               plan.sourceSoundIndex);
        state->audioEventCount += 1;
    }
}

/* m11_join_path replaced by FSP_JoinPath from fs_portable_compat. */

static void m11_write_u32_le(unsigned char* dst, uint32_t value) {
    if (!dst) {
        return;
    }
    dst[0] = (unsigned char)(value & 0xFFu);
    dst[1] = (unsigned char)((value >> 8) & 0xFFu);
    dst[2] = (unsigned char)((value >> 16) & 0xFFu);
    dst[3] = (unsigned char)((value >> 24) & 0xFFu);
}

static uint32_t m11_read_u32_le(const unsigned char* src) {
    if (!src) {
        return 0;
    }
    return ((uint32_t)src[0]) |
           ((uint32_t)src[1] << 8) |
           ((uint32_t)src[2] << 16) |
           ((uint32_t)src[3] << 24);
}

static int m11_game_view_load_quicksave_path(M11_GameViewState* state,
                                             const char* path);
static void m11_set_status(M11_GameViewState* state,
                           const char* title,
                           const char* detail);
static void m11_refresh_hash(M11_GameViewState* state);
static void m11_mark_explored(M11_GameViewState* state);

static void m11_discard_transient_dm1_action_effects_after_resume(
    M11_GameViewState* state)
{
    int i;
    if (!state) return;
    /* ReDMCSB TIMELINE.C F0253 owns removal of the F0407 defense delta.
     * The Firestaff sidecar intentionally does not serialize live action
     * receipts, so remove any pre-resume projection before accepting the
     * restored world; otherwise a stale UI lock can remove defense later. */
    for (i = 0; i < state->world.party.championCount && i < CHAMPION_MAX_PARTY; ++i) {
        if (state->world.party.champions[i].actionIndex < 44u) {
            DM1_ActionDefenseInputPc34 input;
            DM1_ActionDefensePlanPc34 plan;
            memset(&input, 0, sizeof(input));
            memset(&plan, 0, sizeof(plan));
            input.actionIndex = (int)state->world.party.champions[i].actionIndex;
            if (dm1_v1_action_defense_remove_plan_f0407_pc34(&input, &plan) &&
                plan.valid) {
                state->world.party.champions[i].actionDefense += plan.defenseDelta;
                state->world.party.champions[i].actionIndex =
                    (unsigned char)plan.resultingActionIndex;
            }
        }
    }
    memset(&state->dm1LiveActionEffects, 0, sizeof(state->dm1LiveActionEffects));
    memset(state->actionDisabledTicks, 0, sizeof(state->actionDisabledTicks));
    memset(state->actionDisabledIndex, 0xFF, sizeof(state->actionDisabledIndex));
    memset(state->actionEnableSlotOrdinal, 0xFF, sizeof(state->actionEnableSlotOrdinal));
    memset(state->pendingShootReadyHandRefill, 0, sizeof(state->pendingShootReadyHandRefill));
}

static void m11_dm1_c13_visible_runtime_handoff_clear(
    const M11_GameViewState* state)
{
    if (!state || s_m11_dm1_c13_visible_runtime_handoff.owner == state) {
        memset(&s_m11_dm1_c13_visible_runtime_handoff, 0,
               sizeof(s_m11_dm1_c13_visible_runtime_handoff));
    }
}

static int m11_dm1_world_has_c13_rebirth(const M11_GameViewState* state)
{
    int i;

    if (!state) {
        return 0;
    }
    for (i = 0; i < state->world.timeline.count; ++i) {
        if (state->world.timeline.events[i].kind ==
            TIMELINE_EVENT_VI_ALTAR_REBIRTH) {
            return 1;
        }
    }
    return 0;
}

static void m11_dm1_c13_visible_runtime_handoff_bind(
    const M11_GameViewState* state,
    const char* source_path)
{
    DM1OriginalSavePC34CorpusRoundtripReport* report = NULL;
    char root[DM1_ORIGINAL_SAVE_PATH_MAX];
    int i;

    m11_dm1_c13_visible_runtime_handoff_clear(state);
    if (!m11_dm1_world_has_c13_rebirth(state)) {
        return;
    }

    /* F0435 has already adopted the authenticated original world before
     * this optional C13 presentation receipt is requested.  A missing
     * corpus proof must not turn that valid restored game into a black
     * screen: bind an owner only once the source-specific transition itself
     * is available. */
    if (!source_path || !source_path[0] ||
        !FSP_ParentDir(root, sizeof(root), source_path)) {
        return;
    }
    report = (DM1OriginalSavePC34CorpusRoundtripReport*)calloc(1u,
        sizeof(*report));
    if (!report ||
        dm1_v1_original_save_pc34_roundtrip_corpus_root(root, report) !=
            DM1_ORIGINAL_SAVE_PC34_HANDOFF_OK) {
        free(report);
        return;
    }
    for (i = 0; i < report->receipt_count; ++i) {
        const DM1OriginalSavePC34CorpusReceipt* receipt =
            &report->receipts[i];
        if (strcmp(receipt->path, source_path) != 0 ||
            receipt->source_c13_event_count <= 0 ||
            !receipt->roundtrip_receipts_committed ||
            !receipt->c13_visible_runtime_m11_handoff_receipt_available ||
            !receipt->c13_visible_runtime_m11_handoff_valid ||
            receipt->c13_visible_runtime_m11_handoff_fingerprint == 0u ||
            receipt->c13_visible_runtime_m11_handoff_game_tick !=
                state->world.gameTick ||
            receipt->c13_visible_runtime_m11_handoff_queue_game_tick !=
                state->world.gameTick) {
            continue;
        }
        s_m11_dm1_c13_visible_runtime_handoff.pending = 1;
        s_m11_dm1_c13_visible_runtime_handoff.owner = state;
        s_m11_dm1_c13_visible_runtime_handoff.blocked = 0;
        s_m11_dm1_c13_visible_runtime_handoff.gameTick =
            receipt->c13_visible_runtime_m11_handoff_game_tick;
        s_m11_dm1_c13_visible_runtime_handoff.queueGameTick =
            receipt->c13_visible_runtime_m11_handoff_queue_game_tick;
        s_m11_dm1_c13_visible_runtime_handoff.fingerprint =
            receipt->c13_visible_runtime_m11_handoff_fingerprint;
        break;
    }
    free(report);
}

static int m11_dm1_c13_visible_runtime_handoff_consume_transition(
    const M11_GameViewState* state)
{
    M11_Dm1C13VisibleRuntimeHandoffRuntime* runtime =
        &s_m11_dm1_c13_visible_runtime_handoff;

    if (!state || runtime->owner != state) {
        return 1;
    }
    if (runtime->blocked) {
        return 0;
    }
    if (!runtime->pending) {
        return 1;
    }
    if (runtime->fingerprint == 0u ||
        runtime->gameTick != state->world.gameTick ||
        runtime->queueGameTick != state->world.gameTick) {
        runtime->pending = 0;
        runtime->blocked = 1;
        return 0;
    }
    /* The receipt belongs to exactly this visible transition. A later draw
     * must use the normal live runtime, never a retained C13 transition. */
    runtime->pending = 0;
    return 1;
}

int M11_GameView_LoadDm1SavePath(M11_GameViewState* state,
                                 const char* path,
                                 int* outUsedBackup)
{
    struct GameWorld_Compat loadedWorld;
    struct DM1SaveHeader saveHeader;
    struct DM1SaveResumeRequest resumeRequest;
    struct DM1SaveResumeReceipt resumeReceipt;
    DM1OriginalSaveClassifyResult originalSave;
    int usedBackup = 0;
    int loadedOriginalPc34 = 0;
    int rc;

    if (outUsedBackup) {
        *outUsedBackup = 0;
    }
    if (!state || !state->active || !path || path[0] == '\0') {
        return 0;
    }
    if (!DM1_SaveResumeSourceAllowed(state->sourceId)) {
        return 0;
    }
    if (state->candidateMirrorPanelActive) {
        /* ReDMCSB COMMAND.C F0380 gates the C140 save/load command surface
         * with !G0299_ui_CandidateChampionOrdinal while the C040
         * resurrect/reincarnate panel owns input.  A direct host load must
         * not replace the world behind that live panel; the intentional
         * live-C040 quicksave/resume persistence stays with
         * M11_GameView_QuickSave and the startup resume handoff, which run
         * before any panel can be active. */
        return 0;
    }

    memset(&loadedWorld, 0, sizeof(loadedWorld));
    memset(&originalSave, 0, sizeof(originalSave));
    if (dm1_v1_original_save_classify_file(path, &originalSave) &&
        originalSave.shape == DM1_ORIGINAL_SAVE_SHAPE_ORIGINAL_DM1_PC34 &&
        originalSave.pc34_importer_candidate) {
        rc = dm1_v1_original_save_pc34_handoff_materialize_runtime_from_file(
            path, &state->world, &loadedWorld, NULL, NULL);
        if (rc == DM1_ORIGINAL_SAVE_PC34_HANDOFF_OK) {
            loadedOriginalPc34 = 1;
            memset(&saveHeader, 0, sizeof(saveHeader));
        }
    } else {
        rc = DM1_LoadGameWithBackup(path, &loadedWorld, &saveHeader,
                                    &usedBackup);
    }
    if (rc != DM1_SAVE_OK) {
        F0883_WORLD_Free_Compat(&loadedWorld);
        return 0;
    }

    if (dm1_v1_original_save_pc34_handoff_adopt_runtime_world(
            &state->world, &loadedWorld) != DM1_ORIGINAL_SAVE_PC34_HANDOFF_OK) {
        F0883_WORLD_Free_Compat(&loadedWorld);
        return 0;
    }
    /* ReDMCSB LOADSAVE.C F0435 restores original PC34 parts into the live
     * dungeon runtime. F0433/Firestaff-native saves use the normal resume
     * path and must not inherit that external-original provenance. */
    state->dm1ViewportRuntimeOrigin = loadedOriginalPc34
        ? DM1_V1_VIEWPORT_RUNTIME_ORIGIN_ORIGINAL_SAVE_PC34
        : DM1_V1_VIEWPORT_RUNTIME_ORIGIN_QUICKSAVE_RESUME_PC34;
    if (loadedOriginalPc34) {
        m11_dm1_c13_visible_runtime_handoff_bind(state, path);
    } else {
        m11_dm1_c13_visible_runtime_handoff_clear(state);
    }
    memset(&state->lastTickResult, 0, sizeof(state->lastTickResult));
    m11_discard_transient_dm1_action_effects_after_resume(state);
    m11_refresh_hash(state);
    m11_mark_explored(state);
    memset(&resumeRequest, 0, sizeof(resumeRequest));
    memset(&resumeReceipt, 0, sizeof(resumeReceipt));
    resumeRequest.sourceId = state->sourceId;
    resumeRequest.path = path;
    resumeRequest.gameTick = (uint32_t)state->world.gameTick;
    resumeRequest.worldHash = state->lastWorldHash;
    resumeRequest.musicOn = saveHeader.musicOn;
    resumeRequest.usedBackup = usedBackup;
    if (!DM1_BuildSaveResumeReceipt(&resumeRequest, &resumeReceipt) ||
        !m11_apply_dm1_save_resume_receipt(state, &resumeReceipt)) {
        return 0;
    }
    if (outUsedBackup) {
        *outUsedBackup = usedBackup;
    }
    return 1;
}

int M11_GameView_LoadDm1OriginalPc34SaveBytes(M11_GameViewState* state,
                                              const uint8_t* bytes,
                                              size_t size,
                                              const char* sourcePath)
{
    struct GameWorld_Compat loadedWorld;
    struct DM1SaveResumeRequest resumeRequest;
    struct DM1SaveResumeReceipt resumeReceipt;
    DM1OriginalSaveClassifyResult originalSave;

    if (!state || !state->active || !bytes || size == 0u ||
        !DM1_SaveResumeSourceAllowed(state->sourceId)) {
        return 0;
    }
    if (state->candidateMirrorPanelActive) {
        /* Same COMMAND.C F0380 C140/G0299 boundary as
         * M11_GameView_LoadDm1SavePath: the C040 candidate panel owns input,
         * so a direct F0435 byte adoption must not swap the world behind it. */
        return 0;
    }
    memset(&loadedWorld, 0, sizeof(loadedWorld));
    memset(&originalSave, 0, sizeof(originalSave));
    if (!dm1_v1_original_save_classify_bytes(bytes, size, &originalSave) ||
        originalSave.shape != DM1_ORIGINAL_SAVE_SHAPE_ORIGINAL_DM1_PC34 ||
        !originalSave.pc34_importer_candidate ||
        dm1_v1_original_save_pc34_handoff_materialize_runtime_from_bytes(
            bytes, size, &state->world, &loadedWorld, NULL, NULL) !=
            DM1_ORIGINAL_SAVE_PC34_HANDOFF_OK) {
        F0883_WORLD_Free_Compat(&loadedWorld);
        return 0;
    }
    if (dm1_v1_original_save_pc34_handoff_adopt_runtime_world(
            &state->world, &loadedWorld) != DM1_ORIGINAL_SAVE_PC34_HANDOFF_OK) {
        F0883_WORLD_Free_Compat(&loadedWorld);
        return 0;
    }
    /* F0435 consumes these bytes directly. A receipt path is diagnostic only;
     * reopening it here would allow a later replacement save to affect M11. */
    state->dm1ViewportRuntimeOrigin =
        DM1_V1_VIEWPORT_RUNTIME_ORIGIN_ORIGINAL_SAVE_PC34;
    m11_dm1_c13_visible_runtime_handoff_bind(state, sourcePath);
    memset(&state->lastTickResult, 0, sizeof(state->lastTickResult));
    m11_discard_transient_dm1_action_effects_after_resume(state);
    m11_refresh_hash(state);
    m11_mark_explored(state);
    memset(&resumeRequest, 0, sizeof(resumeRequest));
    memset(&resumeReceipt, 0, sizeof(resumeReceipt));
    resumeRequest.sourceId = state->sourceId;
    resumeRequest.path = sourcePath ? sourcePath : "original-pc34-snapshot";
    resumeRequest.gameTick = (uint32_t)state->world.gameTick;
    resumeRequest.worldHash = state->lastWorldHash;
    if (!DM1_BuildSaveResumeReceipt(&resumeRequest, &resumeReceipt) ||
        !m11_apply_dm1_save_resume_receipt(state, &resumeReceipt)) {
        return 0;
    }
    return 1;
}

int M11_GameView_ExportQuickSaveAsDM1PC34(const char* quickSavePath,
                                          const char* exportPath)
{
    FILE* file = NULL;
    long fileSizeLong;
    int blobSize;
    unsigned char header[M11_QUICKSAVE_HEADER_SIZE];
    unsigned char* blob = NULL;
    struct GameWorld_Compat loadedWorld;
    uint32_t expectedHash;
    uint32_t loadedHash = 0;
    int ok = 0;

    if (!quickSavePath || quickSavePath[0] == '\0' ||
        !exportPath || exportPath[0] == '\0') {
        return 0;
    }

    file = fopen(quickSavePath, "rb");
    if (!file) {
        return 0;
    }
    if (fread(header, 1U, sizeof(header), file) != sizeof(header) ||
        memcmp(header, g_m11_quicksave_magic,
               sizeof(g_m11_quicksave_magic)) != 0) {
        fclose(file);
        return 0;
    }

    blobSize = (int)m11_read_u32_le(header + 8);
    expectedHash = m11_read_u32_le(header + 12);
    if (blobSize <= 0 ||
        fseek(file, 0L, SEEK_END) != 0) {
        fclose(file);
        return 0;
    }
    fileSizeLong = ftell(file);
    if (fileSizeLong < (long)M11_QUICKSAVE_HEADER_SIZE ||
        fileSizeLong != (long)(M11_QUICKSAVE_HEADER_SIZE + blobSize) ||
        fseek(file, (long)M11_QUICKSAVE_HEADER_SIZE, SEEK_SET) != 0) {
        fclose(file);
        return 0;
    }

    blob = (unsigned char*)malloc((size_t)blobSize);
    if (!blob) {
        fclose(file);
        return 0;
    }
    if (fread(blob, 1U, (size_t)blobSize, file) != (size_t)blobSize ||
        fclose(file) != 0) {
        free(blob);
        return 0;
    }

    memset(&loadedWorld, 0, sizeof(loadedWorld));
    if (F0898_WORLD_Deserialize_Compat(&loadedWorld, blob, blobSize, NULL) &&
        F0891_ORCH_WorldHash_Compat(&loadedWorld, &loadedHash) &&
        loadedHash == expectedHash) {
        /*
         * ReDMCSB LOADSAVE.C F0433 writes GLOBAL_DATA plus ACTIVE_GROUP,
         * PARTY, EVENTS, and TIMELINE save parts. DM1_SaveGamePC34()
         * is the bounded Firestaff bridge from an M11 quicksave world
         * snapshot back into that PC 3.4-shaped save envelope.
         */
        ok = (DM1_SaveGamePC34(&loadedWorld, exportPath,
                               expectedHash ? expectedHash : 0x4D313151u)
              == DM1_SAVE_OK);
        if (ok) {
            unsigned char *tail_bytes = NULL;
            size_t tail_size = 0U;

            if (!m11_read_quicksave_pc34_tail(quickSavePath, &tail_bytes,
                                               &tail_size)) {
                ok = 0;
            } else if (tail_bytes) {
                FILE *tail_file = fopen(exportPath, "ab");
                int tail_write_ok = tail_file &&
                    fwrite(tail_bytes, 1U, tail_size, tail_file) == tail_size;
                if (tail_file && fclose(tail_file) != 0) {
                    tail_write_ok = 0;
                }
                if (!tail_write_ok) {
                    ok = 0;
                }
                free(tail_bytes);
            }
        }
    }
    F0883_WORLD_Free_Compat(&loadedWorld);
    free(blob);
    if (!ok) {
        remove(exportPath);
    }
    return ok;
}

int M11_GameView_GetQuickSavePath(const M11_GameViewState* state,
                                  char* out,
                                  size_t outSize) {
    const char* envPath;
    const char* sourceId = "dm1";
    const char* saveNamespace = "saves/dm1";
    const char* filenameFormat = "firestaff-%s-dm1save.sav";
    int rc;

    if (!out || outSize == 0U) {
        return 0;
    }

    envPath = getenv("FIRESTAFF_QUICKSAVE_PATH");
    if (envPath && envPath[0] != '\0') {
        rc = snprintf(out, outSize, "%s", envPath);
        return rc > 0 && (size_t)rc < outSize;
    }

    if (state && state->sourceId[0] != '\0') {
        sourceId = state->sourceId;
    }
    /* A CSB save is not a DM1 save with a different source id.  Keep its
     * Firestaff-native envelope separate from original CSBGAME.DAT media:
     * original paths may be imported/exported explicitly, while the default
     * host quicksave cannot be mistaken for one of those source files. */
    if (state && (state->sourceKind == M11_GAME_SOURCE_CSB_BOOT ||
                  strcmp(sourceId, "csb") == 0)) {
        saveNamespace = "saves/csb";
        filenameFormat = "firestaff-%s-save.sav";
    }

    {
        char user_data[FSP_PATH_MAX];
        char saves_dir[FSP_PATH_MAX];
        char filename[128];

        if (!FSP_GetUserDataDir(user_data, sizeof(user_data)) ||
            !FSP_JoinPath(saves_dir, sizeof(saves_dir), user_data,
                          saveNamespace) ||
            snprintf(filename, sizeof(filename), filenameFormat, sourceId) <= 0 ||
            !FSP_JoinPath(out, outSize, saves_dir, filename)) {
            return 0;
        }
    }
    return 1;
}

/* Firestaff builds before the CSB namespace split stored the bounded native
 * CSB snapshot under saves/dm1.  Keep a read-only migration path so an
 * upgrade neither hides a user's existing save nor treats it as original
 * CSBGAME media.  Explicit paths remain entirely caller-owned. */
static int m11_get_legacy_csb_quicksave_path(char* out, size_t outSize)
{
    char user_data[FSP_PATH_MAX];
    char saves_dir[FSP_PATH_MAX];

    if (!out || outSize == 0u || !FSP_GetUserDataDir(user_data,
                                                      sizeof(user_data)) ||
        !FSP_JoinPath(saves_dir, sizeof(saves_dir), user_data, "saves/dm1") ||
        !FSP_JoinPath(out, outSize, saves_dir,
                      "firestaff-csb-dm1save.sav")) {
        return 0;
    }
    return 1;
}

static int m11_path_is_readable(const char *path)
{
    FILE *file;

    if (!path || path[0] == '\0') {
        return 0;
    }
    file = fopen(path, "rb");
    if (!file) {
        return 0;
    }
    (void)fclose(file);
    return 1;
}

/* Hash discovery returns archive members as virtual paths (archive::entry).
 * The original loaders consume ordinary files, so materialize only the
 * already hash-admitted DM1 pair into the per-user runtime cache.  Keeping
 * the extracted bytes beside each other also lets the source startup binder
 * derive GRAPHICS.DAT from the concrete DUNGEON.DAT path exactly as it does
 * for a loose PC34 installation. */
static int m11_materialize_dm1_virtual_asset(const char *virtual_path,
                                             const char *role,
                                             char *out_path,
                                             size_t out_path_size)
{
    char user_data[FSP_PATH_MAX];
    char cache_root[FSP_PATH_MAX];
    char cache_dir[FSP_PATH_MAX];
    if (!virtual_path || !role || !out_path || out_path_size == 0U) {
        return 0;
    }
    if (!strstr(virtual_path, "::")) {
        if (snprintf(out_path, out_path_size, "%s", virtual_path) <= 0 ||
            strlen(virtual_path) >= out_path_size) {
            out_path[0] = '\0';
            return 0;
        }
        return 1;
    }
    if (!FSP_GetUserDataDir(user_data, sizeof(user_data)) ||
        !FSP_JoinPath(cache_root, sizeof(cache_root), user_data,
                      "asset-cache") ||
        !FSP_JoinPath(cache_root, sizeof(cache_root), cache_root, "dm1") ||
        !FSP_JoinPath(cache_dir, sizeof(cache_dir), cache_root, "runtime") ||
        !FSP_CreateDirectoryRecursive(cache_dir) ||
        !FSP_JoinPath(out_path, out_path_size, cache_dir, role) ||
        !asset_extract_virtual_path(virtual_path, out_path)) {
        out_path[0] = '\0';
        return 0;
    }
    return 1;
}

static int m11_materialize_dm1_virtual_pair(char *dungeon_path,
                                            size_t dungeon_path_size)
{
    char graphics_virtual[M11_GAME_VIEW_PATH_CAPACITY];
    char materialized_dungeon[M11_GAME_VIEW_PATH_CAPACITY];
    char materialized_graphics[M11_GAME_VIEW_PATH_CAPACITY];
    char *separator;
    const char *entry_start;
    const char *last_slash;
    const char *last_backslash;
    size_t prefix_length;
    if (!dungeon_path || dungeon_path_size == 0U) {
        return 0;
    }
    separator = strstr(dungeon_path, "::");
    if (!separator) {
        return 1;
    }
    if (snprintf(graphics_virtual, sizeof(graphics_virtual), "%s",
                 dungeon_path) <= 0) {
        return 0;
    }
    separator = strstr(graphics_virtual, "::");
    if (!separator) {
        return 0;
    }
    entry_start = separator + 2;
    last_slash = strrchr(entry_start, '/');
    last_backslash = strrchr(entry_start, '\\');
    if (!last_slash || (last_backslash && last_backslash > last_slash)) {
        last_slash = last_backslash;
    }
    prefix_length = last_slash
        ? (size_t)(last_slash - graphics_virtual) + 1U
        : (size_t)(entry_start - graphics_virtual);
    if (prefix_length + sizeof("GRAPHICS.DAT") > sizeof(graphics_virtual)) {
        return 0;
    }
    memcpy(graphics_virtual + prefix_length, "GRAPHICS.DAT",
           sizeof("GRAPHICS.DAT"));
    if (
        !m11_materialize_dm1_virtual_asset(dungeon_path, "DUNGEON.DAT",
                                            materialized_dungeon,
                                            sizeof(materialized_dungeon)) ||
        !m11_materialize_dm1_virtual_asset(graphics_virtual, "GRAPHICS.DAT",
                                            materialized_graphics,
                                            sizeof(materialized_graphics))) {
        return 0;
    }
    if (snprintf(dungeon_path, dungeon_path_size, "%s", materialized_dungeon) <= 0 ||
        strlen(materialized_dungeon) >= dungeon_path_size) {
        dungeon_path[0] = '\0';
        return 0;
    }
    return 1;
}

static int m11_resolve_builtin_dungeon_path(char* out,
                                            size_t outSize,
                                            const char* dataDir,
                                            const char* gameId) {
    if (!out || !dataDir || !gameId) {
        return 0;
    }
    /* ReDMCSB DUNGEON.C F0237 / LOADSAVE.C F0435 open the verified game
     * data, not a user-facing filename contract.  Prefer recursive MD5
     * search so renamed files and arbitrary user layouts boot first. */
    {
        static const struct { const char *game; const char *md5; } kExpectedHashes[] = {
            { "dm1",  "766450c940651fc021c92fe5d0d0b3a6" },
            { "csb",  "6695d2acebce49f95db1d8f3a5c733de" },
            { "dm2",  "6caccd7875009e82fe2e28e7f6d6adc0" },
            { "nexus", "e88d60859f65f08fa622e1992b02280f" },
            { "theron", "b7afb338ad31be1025b53f9aff12d73a" },
            { "theron", "f23601102138f87c33025877767ebf76" },
            { NULL, NULL }
        };
        const char *expectedMd5 = NULL;
        int i;
        for (i = 0; kExpectedHashes[i].game != NULL; ++i) {
            if (strcmp(gameId, kExpectedHashes[i].game) == 0) {
                expectedMd5 = kExpectedHashes[i].md5;
                if (strcmp(gameId, "dm1") == 0) {
                    char directPath[M11_GAME_VIEW_PATH_CAPACITY];
                    if (FSP_JoinPath(directPath,
                                     sizeof(directPath),
                                     dataDir,
                                     "DUNGEON.DAT") &&
                        asset_file_matches_md5(directPath, expectedMd5)) {
                        strncpy(out, directPath, outSize - 1);
                        out[outSize - 1] = '\0';
                        return 1;
                    }
                    /* 2026-07-21 pass373 fix: the M12 asset scan promotes a
                     * requested <root>/dm1 data dir to its parent root
                     * (m12_promote_game_subdir_scan_root), so the runtime
                     * data dir can be the parent of the directory that
                     * actually holds DUNGEON.DAT.  Without this subdir probe
                     * the recursive MD5 scan below can resolve an archived
                     * zip:: member (F0500 opens plain paths only) even though
                     * the verified file sits one level down.  Same MD5
                     * contract as the direct probe above. */
                    {
                        char subdirPath[M11_GAME_VIEW_PATH_CAPACITY];
                        if (FSP_JoinPath(subdirPath,
                                         sizeof(subdirPath),
                                         dataDir,
                                         "dm1") &&
                            FSP_JoinPath(directPath,
                                         sizeof(directPath),
                                         subdirPath,
                                         "DUNGEON.DAT") &&
                            asset_file_matches_md5(directPath, expectedMd5)) {
                            strncpy(out, directPath, outSize - 1);
                            out[outSize - 1] = '\0';
                            return 1;
                        }
                    }
                }
                if (strcmp(gameId, "csb") == 0) {
                    char directPath[M11_GAME_VIEW_PATH_CAPACITY];

                    /* A selected CSB directory normally contains the
                     * authenticated loose PC3.4 pair.  Resolve that exact
                     * DUNGEON.DAT before the recursive hash finder reaches
                     * unrelated CSB ports, CD images, or large archives in
                     * the same user data root.  The later MD5 scan remains
                     * the archive/renamed-media path. */
                    if (FSP_JoinPath(directPath, sizeof(directPath), dataDir,
                                     "DUNGEON.DAT") &&
                        asset_file_matches_md5(directPath, expectedMd5)) {
                        strncpy(out, directPath, outSize - 1);
                        out[outSize - 1] = '\0';
                        return 1;
                    }
                    {
                        char subdirPath[M11_GAME_VIEW_PATH_CAPACITY];
                        if (FSP_JoinPath(subdirPath, sizeof(subdirPath),
                                         dataDir, "csb") &&
                            FSP_JoinPath(directPath, sizeof(directPath),
                                         subdirPath, "DUNGEON.DAT") &&
                            asset_file_matches_md5(directPath, expectedMd5)) {
                            strncpy(out, directPath, outSize - 1);
                            out[outSize - 1] = '\0';
                            return 1;
                        }
                    }
                }
                /* Try this hash; if it fails, keep looking for a
                 * secondary match in the same game's entry list
                 * (e.g. theron JP -> US fallback). */
                {
                    char resolved[ASSET_PATH_MAX];
                    if (asset_find_by_md5(dataDir, expectedMd5, resolved,
                                          (int)sizeof(resolved), 32)) {
                        strncpy(out, resolved, outSize - 1);
                        out[outSize - 1] = '\0';
                        return 1;
                    }
                }
            }
        }
    }
    /* Never admit a dungeon by filename alone.  The hash scanner above
     * supports renamed files and containers, while a loose DUNGEON.DAT may
     * belong to another release or be incomplete data. */
    return 0;
}

static uint8_t m11_forward_command_for_direction(int direction) {
    switch (direction) {
        case DIR_NORTH: return CMD_MOVE_NORTH;
        case DIR_EAST: return CMD_MOVE_EAST;
        case DIR_SOUTH: return CMD_MOVE_SOUTH;
        case DIR_WEST: return CMD_MOVE_WEST;
        default: return CMD_NONE;
    }
}

static uint8_t m11_backward_command_for_direction(int direction) {
    switch (direction) {
        case DIR_NORTH: return CMD_MOVE_SOUTH;
        case DIR_EAST: return CMD_MOVE_WEST;
        case DIR_SOUTH: return CMD_MOVE_NORTH;
        case DIR_WEST: return CMD_MOVE_EAST;
        default: return CMD_NONE;
    }
}

static uint8_t m11_strafe_left_command_for_direction(int direction) {
    switch (direction) {
        case DIR_NORTH: return CMD_MOVE_WEST;
        case DIR_EAST: return CMD_MOVE_NORTH;
        case DIR_SOUTH: return CMD_MOVE_EAST;
        case DIR_WEST: return CMD_MOVE_SOUTH;
        default: return CMD_NONE;
    }
}

static uint8_t m11_strafe_right_command_for_direction(int direction) {
    switch (direction) {
        case DIR_NORTH: return CMD_MOVE_EAST;
        case DIR_EAST: return CMD_MOVE_SOUTH;
        case DIR_SOUTH: return CMD_MOVE_WEST;
        case DIR_WEST: return CMD_MOVE_NORTH;
        default: return CMD_NONE;
    }
}

static unsigned char m11_tile_color(int elementType) {
    switch (elementType) {
        case DUNGEON_ELEMENT_WALL: return M11_COLOR_DARK_GRAY;
        case DUNGEON_ELEMENT_CORRIDOR: return M11_COLOR_LIGHT_GRAY;
        case DUNGEON_ELEMENT_PIT: return M11_COLOR_BROWN;
        case DUNGEON_ELEMENT_STAIRS: return M11_COLOR_YELLOW;
        case DUNGEON_ELEMENT_DOOR: return M11_COLOR_LIGHT_RED;
        case DUNGEON_ELEMENT_TELEPORTER: return M11_COLOR_LIGHT_CYAN;
        case DUNGEON_ELEMENT_FAKEWALL: return M11_COLOR_MAGENTA;
        default: return M11_COLOR_BLACK;
    }
}

static int m11_map_square_base(const struct DungeonDatState_Compat* dungeon,
                               int mapIndex) {
    int i;
    int base = 0;
    if (!dungeon || !dungeon->maps || mapIndex < 0 || mapIndex >= (int)dungeon->header.mapCount) {
        return -1;
    }
    for (i = 0; i < mapIndex; ++i) {
        base += (int)dungeon->maps[i].width * (int)dungeon->maps[i].height;
    }
    return base;
}

static int m11_get_square_byte(const struct GameWorld_Compat* world,
                               int mapIndex,
                               int mapX,
                               int mapY,
                               unsigned char* outSquare) {
    const struct DungeonMapDesc_Compat* map;
    const struct DungeonMapTiles_Compat* tiles;
    int index;
    if (!world || !world->dungeon || !world->dungeon->tilesLoaded || !outSquare) {
        return 0;
    }
    if (mapIndex < 0 || mapIndex >= (int)world->dungeon->header.mapCount) {
        return 0;
    }
    map = &world->dungeon->maps[mapIndex];
    if (mapX < 0 || mapY < 0 || mapX >= (int)map->width || mapY >= (int)map->height) {
        return 0;
    }
    tiles = &world->dungeon->tiles[mapIndex];
    index = mapX * (int)map->height + mapY;
    if (!tiles->squareData || index < 0 || index >= tiles->squareCount) {
        return 0;
    }
    *outSquare = tiles->squareData[index];
    return 1;
}

static int m11_square_type_is_corridor_or_pit(unsigned char square) {
    int squareType = (square & DUNGEON_SQUARE_MASK_TYPE) >> 5;
    return squareType == DUNGEON_ELEMENT_CORRIDOR ||
           squareType == DUNGEON_ELEMENT_PIT;
}

static int m11_get_viewport_square_byte_pc34(const struct GameWorld_Compat* world,
                                             int mapIndex,
                                             int mapX,
                                             int mapY,
                                             unsigned char* outSquare) {
    const struct DungeonMapDesc_Compat* map;
    unsigned char edgeSquare = 0;
    unsigned char wallFlags = 0;

    if (m11_get_square_byte(world, mapIndex, mapX, mapY, outSquare)) {
        return 1;
    }
    if (!world || !world->dungeon || !world->dungeon->tilesLoaded ||
        !world->dungeon->maps || !outSquare ||
        mapIndex < 0 || mapIndex >= (int)world->dungeon->header.mapCount) {
        return 0;
    }

    map = &world->dungeon->maps[mapIndex];
    if (map->width <= 0 || map->height <= 0) {
        return 0;
    }

    /* ReDMCSB DUNGEON.C F0151 lines 1423-1478 returns a wall square when
     * viewport sampling walks outside the current map.  Border corridor/pit
     * squares keep their random-ornament-facing flag; otherwise the synthetic
     * wall has no flags.  Keep this viewport-only so gameplay collision and
     * object mutation paths retain their strict in-bounds checks. */
    if (mapY >= 0 && mapY < (int)map->height) {
        if (mapX == -1 &&
            m11_get_square_byte(world, mapIndex, 0, mapY, &edgeSquare) &&
            m11_square_type_is_corridor_or_pit(edgeSquare)) {
            wallFlags = 0x04; /* MASK0x0004_WALL_EAST_RANDOM_ORNAMENT_ALLOWED */
        } else if (mapX == (int)map->width &&
                   m11_get_square_byte(world, mapIndex, (int)map->width - 1,
                                       mapY, &edgeSquare) &&
                   m11_square_type_is_corridor_or_pit(edgeSquare)) {
            wallFlags = 0x01; /* MASK0x0001_WALL_WEST_RANDOM_ORNAMENT_ALLOWED */
        }
    } else if (mapX >= 0 && mapX < (int)map->width) {
        if (mapY == -1 &&
            m11_get_square_byte(world, mapIndex, mapX, 0, &edgeSquare) &&
            m11_square_type_is_corridor_or_pit(edgeSquare)) {
            wallFlags = 0x02; /* MASK0x0002_WALL_SOUTH_RANDOM_ORNAMENT_ALLOWED */
        } else if (mapY == (int)map->height &&
                   m11_get_square_byte(world, mapIndex, mapX,
                                       (int)map->height - 1, &edgeSquare) &&
                   m11_square_type_is_corridor_or_pit(edgeSquare)) {
            wallFlags = 0x08; /* MASK0x0008_WALL_NORTH_RANDOM_ORNAMENT_ALLOWED */
        }
    }

    *outSquare = (unsigned char)((DUNGEON_ELEMENT_WALL << 5) | wallFlags);
    return 1;
}

static int m11_set_square_byte(struct GameWorld_Compat* world,
                               int mapIndex,
                               int mapX,
                               int mapY,
                               unsigned char newValue) {
    struct DungeonMapDesc_Compat* map;
    struct DungeonMapTiles_Compat* tiles;
    int index;
    if (!world || !world->dungeon || !world->dungeon->tilesLoaded) return 0;
    if (mapIndex < 0 || mapIndex >= (int)world->dungeon->header.mapCount) return 0;
    map = &world->dungeon->maps[mapIndex];
    if (mapX < 0 || mapY < 0 || mapX >= (int)map->width || mapY >= (int)map->height) return 0;
    tiles = &world->dungeon->tiles[mapIndex];
    index = mapX * (int)map->height + mapY;
    if (!tiles->squareData || index < 0 || index >= tiles->squareCount) return 0;
    tiles->squareData[index] = newValue;
    return 1;
}

static unsigned short m11_raw_next_thing(const struct DungeonThings_Compat* things,
                                         unsigned short thing) {
    return F0512_DUNGEON_GetThingNext_Compat(things, thing);
}

static unsigned short m11_get_first_square_thing(const struct GameWorld_Compat* world,
                                                 int mapIndex,
                                                 int mapX,
                                                 int mapY);

/* ReDMCSB DUNGEON.C F0160/F0161: SquareFirstThings is the compact
 * per-column array whenever the dungeon publishes the cumulative column
 * metadata (real DUNGEON.DAT always does).  Legacy dense fixtures
 * (probes/tests that only fill the raw array) fall back to the dense
 * mapX*height+mapY interpretation.  Reading the compact array densely
 * aliases chains onto wrong squares (false creature/item payloads). */
static int m11_world_has_compact_sft(const struct GameWorld_Compat* world) {
    return world && world->dungeon &&
           world->dungeon->columnsCumulativeSquareFirstThingCount != NULL &&
           world->dungeon->dungeonColumnCount > 0;
}

static unsigned short m11_square_chain_head(const struct GameWorld_Compat* world,
                                            int mapIndex,
                                            int mapX,
                                            int mapY) {
    if (m11_world_has_compact_sft(world)) {
        return F0511_DUNGEON_GetSquareFirstThing_Compat(
            world->dungeon, world->things, mapIndex, mapX, mapY);
    }
    return m11_get_first_square_thing(world, mapIndex, mapX, mapY);
}

static unsigned short m11_get_first_square_thing(const struct GameWorld_Compat* world,
                                                 int mapIndex,
                                                 int mapX,
                                                 int mapY) {
    int base;
    const struct DungeonMapDesc_Compat* map;
    int squareIndex;
    if (!world || !world->dungeon || !world->things || !world->things->squareFirstThings) {
        return THING_ENDOFLIST;
    }
    if (mapIndex < 0 || mapIndex >= (int)world->dungeon->header.mapCount) {
        return THING_ENDOFLIST;
    }
    map = &world->dungeon->maps[mapIndex];
    if (mapX < 0 || mapY < 0 || mapX >= (int)map->width || mapY >= (int)map->height) {
        return THING_ENDOFLIST;
    }
    base = m11_map_square_base(world->dungeon, mapIndex);
    if (base < 0) {
        return THING_ENDOFLIST;
    }
    squareIndex = base + mapX * (int)map->height + mapY;
    if (squareIndex < 0 || squareIndex >= world->things->squareFirstThingCount) {
        return THING_ENDOFLIST;
    }
    return world->things->squareFirstThings[squareIndex];
}

static unsigned short m11_get_flagged_square_first_thing(const struct GameWorld_Compat* world,
                                                         int mapIndex,
                                                         int mapX,
                                                         int mapY) {
    if (!world || !world->dungeon || !world->things || !world->things->squareFirstThings) {
        return THING_ENDOFLIST;
    }
    return F0511_DUNGEON_GetSquareFirstThing_Compat(
        world->dungeon, world->things, mapIndex, mapX, mapY);
}

static unsigned short m11_get_viewport_static_first_thing(const struct GameWorld_Compat* world,
                                                          int mapIndex,
                                                          int mapX,
                                                          int mapY) {
    unsigned char square = 0;
    if (m11_get_square_byte(world, mapIndex, mapX, mapY, &square)) {
        if (square & DUNGEON_SQUARE_MASK_THING_LIST) {
            /* ReDMCSB DUNGEON.C F0160/F0161 stores SquareFirstThings as a
             * compact table indexed only by squares with the thing-list flag,
             * on every map.  Using dense mapX*height+mapY indexing after HoC
             * can bind the viewport to an unrelated thing chain, which shows
             * up as misplaced floor objects, creatures, sensors, or effects. */
            return m11_get_flagged_square_first_thing(world, mapIndex, mapX, mapY);
        }
        if (world && world->dungeon && world->things) {
            int totalSquares = 0;
            int mi;
            for (mi = 0; mi < (int)world->dungeon->header.mapCount; ++mi) {
                totalSquares += world->dungeon->tiles[mi].squareCount;
            }
            if (world->things->squareFirstThingCount < totalSquares) {
                return THING_ENDOFLIST;
            }
        }
    }
    /* Synthetic probe worlds created before the compact-table model may lack
     * MASK0x0010_THING_LIST while still storing dense squareFirstThings. */
    return m11_get_first_square_thing(world, mapIndex, mapX, mapY);
}

static int m11_count_square_things(const struct GameWorld_Compat* world,
                                   int mapIndex,
                                   int mapX,
                                   int mapY) {
    unsigned short thing = m11_get_viewport_static_first_thing(world, mapIndex, mapX, mapY);
    int count = 0;
    while (thing != THING_ENDOFLIST && thing != THING_NONE && count < 32) {
        ++count;
        thing = m11_raw_next_thing(world->things, thing);
    }
    return count;
}

struct M11_ViewportCell;

/* ── DM1 random ornament computation (F0169/F0170 from ReDMCSB) ──
 * Floor ornaments in DM1 are assigned per-square using a deterministic
 * pseudorandom algorithm seeded by the dungeon header's OrnamentRandomSeed.
 * The algorithm hashes map coordinates + map index/dimensions to produce
 * a per-square ornament index.  If the square allows random ornaments
 * (bit 3 of the corridor square byte) and the map has floor ornaments,
 * the square gets a floor ornament ordinal (1-based, 0 = none).
 * Ref: ReDMCSB DUNGEON.C F0169_DUNGEON_GetRandomOrnamentIndex,
 *      F0170_DUNGEON_GetRandomOrnamentOrdinal,
 *      F0172_DUNGEON_SetSquareAspect (corridor case). */

/* Compute the floor ornament ordinal for a corridor/pit/stairs/teleporter
 * square.  Returns 1-based ordinal, or 0 if none.
 * This mirrors F0172_DUNGEON_SetSquareAspect's floor ornament path.
 * Two sources of floor ornaments:
 *  1. Random floor ornaments based on MASK0x0008 bit in the square byte
 *  2. Sensor things with ornamentOrdinal 0..15 (explicit placement or
 *     explicit suppression of the random ornament)
 * Ref: ReDMCSB DUNGEON.C F0172 lines ~2189-2196. */
static int m11_compute_floor_ornament_ordinal(
    const M11_GameViewState* state,
    int mapIndex,
    int mapX,
    int mapY,
    unsigned char square) {
    int elementType = (square & DUNGEON_SQUARE_MASK_TYPE) >> 5;
    const struct DungeonMapDesc_Compat* map;
    int randomAllowed;
    int randomFloorOrnCount;
    unsigned short ornSeed;
    unsigned int value2;
    int idx;
    int ordinal = 0;

    /* Floor ornaments only appear on corridor, pit, and teleporter squares.
     * ReDMCSB DUNGEON.C F0172 routes stairs through T0172046_Stairs
     * without assigning M558_FLOOR_ORNAMENT_ORDINAL; the stairs 0x08
     * bit is orientation, not random-ornament permission. */
    if (elementType != DUNGEON_ELEMENT_CORRIDOR &&
        elementType != DUNGEON_ELEMENT_PIT &&
        elementType != DUNGEON_ELEMENT_TELEPORTER) {
        return 0;
    }
    if (!state || !state->world.dungeon ||
        mapIndex < 0 || mapIndex >= (int)state->world.dungeon->header.mapCount) {
        return 0;
    }

    map = &state->world.dungeon->maps[mapIndex];
    ornSeed = state->world.dungeon->header.ornamentRandomSeed;
    randomFloorOrnCount = (int)map->randomFloorOrnamentCount;

    /* Random floor ornament from square byte bit 3 (MASK0x0008) */
    randomAllowed = (square & 0x08) != 0;
    /* ReDMCSB DUNGEON.C F0172 applies the map's random-floor-ornament
     * stream to every corridor map, including map zero (Hall of Champions).
     * The map's real metadata and seed decide whether a tile is decorated;
     * a Firestaff-specific HoC suppression would hide legitimate plates,
     * grates, and other floor ornaments. */
    if (randomAllowed && randomFloorOrnCount > 0) {
        /* value2 = 3000 + (mapIndex << 6) + mapWidth + mapHeight
         * Ref: ReDMCSB F0170 call from F0172 */
        value2 = (unsigned int)(3000 + (mapIndex << 6) +
                                (int)map->width + (int)map->height);
        idx = (int)((((((unsigned int)(2000 + (mapX << 5) + mapY)) * 31417u) >> 1) +
                     (value2 * 11u) + ornSeed) >> 2) % 30;
        if (idx < randomFloorOrnCount) {
            ordinal = idx + 1; /* 1-based */
        }
    }
    /* Sensors overwrite the random value, including ordinal zero.  F0172
     * assigns Remote.OrnamentOrdinal unconditionally; zero is how original
     * dungeon data suppresses a random grate/pressure plate on that square.
     * Ref: ReDMCSB DUNGEON.C F0172 — C03_THING_TYPE_SENSOR path. */
    if (state->world.things && state->world.things->sensors) {
        unsigned short scanThing = m11_get_viewport_static_first_thing(
            &state->world, mapIndex, mapX, mapY);
        int scanSafety = 0;
        while (scanThing != THING_ENDOFLIST && scanThing != THING_NONE && scanSafety < 64) {
            if (THING_GET_TYPE(scanThing) == THING_TYPE_SENSOR) {
                int sIdx = THING_GET_INDEX(scanThing);
                if (sIdx >= 0 && sIdx < state->world.things->sensorCount) {
                    /* Use the original 4-bit remote ornament field.  Do
                     * not discard zero: it is an explicit source-owned
                     * replacement for the calculated random ordinal. */
                    int sOrd = (int)state->world.things->sensors[sIdx].ornamentOrdinal;
                    ordinal = sOrd;
                    break;
                }
            }
            scanThing = m11_raw_next_thing(state->world.things, scanThing);
            ++scanSafety;
        }
    }

    return ordinal;
}

/* ── DM1 Creature Viewport Coordinate Sets (G0224) ──
 * Exact front-cell viewport coordinates extracted from original item 558
 * documentation (Graphic558 / G0224). Each entry is {centerX, bottomY}
 * in the original 224×136 viewport.
 *
 * We only encode the 3 coordinate sets actually referenced by the DM1
 * creature aspect table in this renderer (sets 0, 1 and 2).
 *
 * For set 0 / set 2 the five slots map to c1..c5.
 * For set 1 the five slots map to c6..c10.
 * Depth index mapping here is 0=D1, 1=D2, 2=D3.
 */
static const unsigned char s_creatureFrontCoordSets[3][3][5][2] = {
    /* Depth 0 (D1) */
    {
        /* Set 0: c1..c5 */  {{ 83,103 }, {141,103 }, {148,119 }, { 76,119 }, {109,111 }},
        /* Set 1: c6..c10 */ {{ 81,119 }, {142,119 }, {111,105 }, {111,111 }, {111,119 }},
        /* Set 2: c1..c5 */  {{ 83, 94 }, {141, 94 }, {148, 98 }, { 76, 98 }, {109, 96 }}
    },
    /* Depth 1 (D2) */
    {
        /* Set 0: c1..c5 */  {{ 92, 81 }, {131, 81 }, {132, 90 }, { 91, 90 }, {111, 85 }},
        /* Set 1: c6..c10 */ {{ 91, 90 }, {132, 90 }, {111, 83 }, {111, 85 }, {111, 90 }},
        /* Set 2: c1..c5 */  {{ 92, 73 }, {131, 73 }, {132, 78 }, { 91, 78 }, {111, 75 }}
    },
    /* Depth 2 (D3) */
    {
        /* Set 0: c1..c5 */  {{ 95, 70 }, {127, 70 }, {129, 75 }, { 93, 75 }, {111, 72 }},
        /* Set 1: c6..c10 */ {{ 94, 75 }, {128, 75 }, {111, 70 }, {111, 72 }, {111, 75 }},
        /* Set 2: c1..c5 */  {{ 95, 59 }, {127, 59 }, {129, 61 }, { 93, 61 }, {111, 60 }}
    }
};

void M11_GameView_GetCreatureFrontSlotPoint(int coordSet,
                                            int depthIndex,
                                            int visibleCount,
                                            int slotIndex,
                                            int* outCenterX,
                                            int* outBottomY) {
    int pointIndex = 4;
    if (outCenterX) *outCenterX = 111;
    if (outBottomY) *outBottomY = (depthIndex <= 0) ? 111 : (depthIndex == 1 ? 85 : 72);
    if (coordSet < 0 || coordSet > 2 || depthIndex < 0 || depthIndex > 2 ||
        slotIndex < 0 || slotIndex > 3) {
        return;
    }

    if (coordSet == 1) {
        if (visibleCount <= 1) {
            pointIndex = 4; /* c10 */
        } else {
            pointIndex = slotIndex < 2 ? slotIndex : 4; /* c6/c7, clamp extras */
        }
    } else {
        if (visibleCount <= 1) {
            pointIndex = 4; /* c5 */
        } else {
            pointIndex = slotIndex;
            if (pointIndex > 3) pointIndex = 3;
        }
    }

    if (outCenterX) *outCenterX = (int)s_creatureFrontCoordSets[depthIndex][coordSet][pointIndex][0];
    if (outBottomY) *outBottomY = (int)s_creatureFrontCoordSets[depthIndex][coordSet][pointIndex][1];
}

/* Other M11 combat/update paths still need this cache-slot predicate. The
 * F0115 viewport route below deliberately delegates its instance discovery
 * to DM1's typed runtime input instead. */
static int m11_projectile_instance_active(
    const struct ProjectileInstance_Compat* projectile) {
    return projectile && projectile->slotIndex >= 0 && projectile->reserved3 != 0;
}

static void m11_summarize_square_things(const struct GameWorld_Compat* world,
                                        int mapIndex,
                                        int mapX,
                                        int mapY,
                                        DM1_F0115RuntimeSummaryPc34* outSummary) {
    DM1_F0115RuntimeSummaryPc34 summary;
    memset(&summary, 0, sizeof(summary));
    /* ReDMCSB: DUNVIEW.C F0115 layers the static chain before restarting
     * for live projectile/explosion passes. M10/DM1 own bounded SFT and
     * active-instance discovery; M11 consumes only the resulting receipt. */
    (void)dm1_v1_f0115_runtime_summary_from_world_pc34(
        world, mapIndex, mapX, mapY, &summary);

    if (outSummary) {
        *outSummary = summary;
    }
}

