static int m11_refill_ready_hand_after_dm1_shoot(M11_GameViewState* state,
                                                 int championIndex);
static int m11_refill_ready_hand_after_shoot(M11_GameViewState* state,
                                             int championIndex);

/* The live action-lock list is an M11 cooldown mirror, not a second owner of
 * ReDMCSB TIMELINE.C C11.  MENU.C F0407 schedules the authenticated SWING
 * C11 through F0330; when that receipt reaches F0253, retire this matching
 * local mirror before the end-of-tick cooldown pass can replay F0253's
 * ActionDefense/ActionIndex mutation. */
static void m11_consume_action_lock_c11(M11_GameViewState* state,
                                        int championIndex,
                                        int actionIndex) {
    int i;
    if (!state ||
        championIndex < 0 || championIndex >= CHAMPION_MAX_PARTY) {
        return;
    }
    for (i = 0; i < state->dm1LiveActionEffects.count; ++i) {
        DM1_V1_LiveActionEffectPc34* entry =
            &state->dm1LiveActionEffects.entries[i];
        if (entry->kind != DM1_V1_LIVE_ACTION_EFFECT_ACTION_LOCK_PC34 ||
            entry->championIndex != championIndex ||
            entry->actionIndex != actionIndex) {
            continue;
        }
        state->dm1LiveActionEffects.entries[i] =
            state->dm1LiveActionEffects.entries[
                state->dm1LiveActionEffects.count - 1];
        --state->dm1LiveActionEffects.count;
        return;
    }
}

static void m11_decrement_action_disabled_ticks(M11_GameViewState* state) {
    DM1_V1_LiveActionEffectsAdvancePlanPc34 advancePlan;
    int i;
    if (!state) return;
    memset(&advancePlan, 0, sizeof(advancePlan));
    if (!dm1_v1_live_action_effects_advance_pc34(
            &state->dm1LiveActionEffects, state->world.gameTick,
            &advancePlan)) return;
    /* F0328 can enter F0330 before F0407 consumes its action tick.  Keep the
     * UI lock mirror aligned with that already-authenticated C11 receipt,
     * rather than starting a second host countdown.  F0253 remains the only
     * path allowed to clear the action state when the event becomes due. */
    for (i = 0; i < state->world.timeline.count; ++i) {
        const struct TimelineEvent_Compat* event =
            &state->world.timeline.events[i];
        int championIndex;
        uint32_t remaining;
        if (event->kind != TIMELINE_EVENT_ENABLE_CHAMPION_ACTION ||
            event->aux0 != DM1_EVENT_ENABLE_CHAMPION_ACTION ||
            event->aux2 != DM1_EVENT_ENABLE_CHAMPION_ACTION) {
            continue;
        }
        championIndex = event->aux4;
        if (championIndex < 0 || championIndex >= CHAMPION_MAX_PARTY ||
            event->fireAtTick <= state->world.gameTick) {
            continue;
        }
        remaining = event->fireAtTick - state->world.gameTick;
        state->actionDisabledTicks[championIndex] =
            remaining > 255u ? 255u : (unsigned char)remaining;
    }
    for (i = 0; i < advancePlan.expiredCount; ++i) {
        int championIndex = advancePlan.expiredChampionIndex[i];
        int actionIndex = advancePlan.expiredActionIndex[i];
        if (championIndex < 0 || championIndex >= CHAMPION_MAX_PARTY) continue;
        /* The authenticated F0407 SWING and THROW C11 routes use their
         * host locks only as gates while the source receipt is pending. They
         * must never synthesize TIMELINE.C F0253 if F0330 moved C11 behind
         * an earlier owner. Missing/malformed C11 therefore remains locked
         * rather than releasing defense/action state from a local timeout. */
        if (state->actionEnableSlotOrdinal[championIndex] == 0u ||
            state->actionEnableSlotOrdinal[championIndex] ==
                DM1_PC34_C01_ACTION_HAND_SLOT_ORDINAL) {
            continue;
        }
        state->actionDisabledTicks[championIndex] = 0u;
        if (championIndex < state->world.party.championCount &&
            actionIndex >= 0 && actionIndex < 44) {
            DM1_ActionDefenseInputPc34 defenseIn;
            DM1_ActionDefensePlanPc34 defensePlan;
            memset(&defenseIn, 0, sizeof(defenseIn));
            memset(&defensePlan, 0, sizeof(defensePlan));
            defenseIn.actionIndex = actionIndex;
            if (dm1_v1_action_defense_remove_plan_f0407_pc34(
                    &defenseIn, &defensePlan) && defensePlan.valid) {
                state->world.party.champions[championIndex].actionDefense +=
                    defensePlan.defenseDelta;
                state->world.party.champions[championIndex].actionIndex =
                    (unsigned char)defensePlan.resultingActionIndex;
            }
        }
        if (state->pendingShootReadyHandRefill[championIndex]) {
            state->pendingShootReadyHandRefill[championIndex] = 0u;
            (void)m11_refill_ready_hand_after_shoot(state, championIndex);
        }
        state->actionDisabledIndex[championIndex] = 0xFFu;
        state->actionEnableSlotOrdinal[championIndex] = 0xFFu;
    }
}

static int m11_move_weapon_from_quiver_after_c11_f0259(
    M11_GameViewState* state,
    int championIndex) {
    struct ChampionState_Compat* champion;
    struct DM1F0259QuiverRefillPlanPc34 refill;
    if (!state || championIndex < 0 ||
        championIndex >= state->world.party.championCount ||
        championIndex >= CHAMPION_MAX_PARTY) {
        return 0;
    }
    champion = &state->world.party.champions[championIndex];
    if (!champion->present) return 0;
    memset(&refill, 0, sizeof(refill));
    if (!DM1_V1_F0259_PlanQuiverRefillPc34Compat(
            champion, championIndex, CHAMPION_SLOT_HAND_RIGHT, &refill) ||
        !refill.moved) {
        return 0;
    }
    champion->inventory[refill.destinationSlot] = refill.thing;
    champion->inventory[refill.sourceSlot] = THING_NONE;
    return 1;
}

/* ReDMCSB TIMELINE.C C11 calls F0253 first and F0259 only when its
 * B.SlotOrdinal is C01.  The M11 sidecar is the live owner recorded when
 * F0407/F0412 created C11; accepting a different ordinal would turn a stale
 * or duplicate receipt into a second state/inventory mutation. */
static void m11_enable_champion_action_from_timeline(M11_GameViewState* state,
                                                     int championIndex,
                                                     int slotOrdinal) {
    int actionIndex;
    if (!state || championIndex < 0 || championIndex >= CHAMPION_MAX_PARTY) return;
    if ((slotOrdinal != 0 &&
         slotOrdinal != DM1_PC34_C01_ACTION_HAND_SLOT_ORDINAL) ||
        state->actionEnableSlotOrdinal[championIndex] !=
            (unsigned char)slotOrdinal) {
        return;
    }
    actionIndex = (int)state->actionDisabledIndex[championIndex];
    /* F0253 reads Champion.ActionIndex itself. F0328's THROW lock has no
     * action index in the M11 cooldown sidecar, so recover the source owner
     * only after the receipt ordinal has passed the stale/duplicate gate. */
    if ((actionIndex < 0 || actionIndex >= 44) &&
        championIndex < state->world.party.championCount) {
        actionIndex = (int)state->world.party.champions[championIndex]
            .actionIndex;
    }
    /* ReDMCSB MENU.C F0407:1613-1617 writes C01's 1-based C11 receipt
     * only from the successful C042_ACTION_THROW branch after F0328.  Do
     * not let an imported or stale ordinal-two receipt coupled to a normal
     * melee/action owner reach F0259 and move the action-hand quiver slot. */
    if (slotOrdinal == DM1_PC34_C01_ACTION_HAND_SLOT_ORDINAL &&
        actionIndex != DM1_ACTION_THROW) {
        return;
    }
    /* ReDMCSB TIMELINE.C C11 -> F0253 owns the real completion. Every
     * ordinal-zero F0407 action keeps one local gate mirror; consume its
     * matching record before the after-tick aging pass can replay F0253's
     * defense/action-index mutation. */
    m11_consume_action_lock_c11(state, championIndex, actionIndex);
    state->actionDisabledTicks[championIndex] = 0u;
    if (championIndex < state->world.party.championCount &&
        actionIndex >= 0 && actionIndex < 44) {
        DM1_ActionDefenseInputPc34 defenseIn;
        DM1_ActionDefensePlanPc34 defensePlan;
        memset(&defenseIn, 0, sizeof(defenseIn));
        memset(&defensePlan, 0, sizeof(defensePlan));
        defenseIn.actionIndex = actionIndex;
        if (dm1_v1_action_defense_remove_plan_f0407_pc34(
                &defenseIn, &defensePlan) && defensePlan.valid) {
            state->world.party.champions[championIndex].actionDefense +=
                defensePlan.defenseDelta;
            state->world.party.champions[championIndex].actionIndex =
                (unsigned char)defensePlan.resultingActionIndex;
        }
    }
    /* ReDMCSB TIMELINE.C F0253, not the C11 B.SlotOrdinal follow-up,
     * owns SHOOT's compatible quiver refill. It observes ActionIndex while
     * it is still C032, after re-enabling the champion and before resetting
     * that field to C0xFF. F0259 below remains the separate, ordinal-bound
     * generic weapon move. */
    if (actionIndex == DM1_ACTION_SHOOT) {
        (void)m11_refill_ready_hand_after_shoot(state, championIndex);
    }
    state->pendingShootReadyHandRefill[championIndex] = 0u;
    state->actionDisabledIndex[championIndex] = 0xFFu;
    state->actionEnableSlotOrdinal[championIndex] = 0xFFu;
    /* TIMELINE.C C11:1927-1932 invokes F0259 only after F0253 has cleared
     * ActionIndex and refreshed the living champion. */
    if (slotOrdinal == DM1_PC34_C01_ACTION_HAND_SLOT_ORDINAL) {
        (void)m11_move_weapon_from_quiver_after_c11_f0259(
            state, championIndex);
    }
}

static void m11_materialize_action_lock(M11_GameViewState* state,
                                        int championIndex,
                                        int actionIndex,
                                        int ticks) {
    DM1_V1_LiveActionEffectInputPc34 input;
    if (!state || championIndex < 0 || championIndex >= CHAMPION_MAX_PARTY || ticks <= 0) return;
    memset(&input, 0, sizeof(input));
    input.kind = DM1_V1_LIVE_ACTION_EFFECT_ACTION_LOCK_PC34;
    input.championIndex = championIndex;
    input.actionIndex = actionIndex;
    input.disabledTicks = ticks;
    input.sourceTick = state->world.gameTick;
    (void)dm1_v1_live_action_effect_materialize_pc34(
        &state->dm1LiveActionEffects, &input, NULL);
    state->actionDisabledTicks[championIndex] =
        ticks > 255 ? 255u : (unsigned char)ticks;
}

static void m11_materialize_action_result(M11_GameViewState* state,
                                          int kind, int championIndex,
                                          int actionIndex, int damage,
                                          int combatOutcome, int doorAffected) {
    DM1_V1_LiveActionEffectInputPc34 input;
    if (!state) return;
    memset(&input, 0, sizeof(input));
    input.kind = kind;
    input.championIndex = championIndex;
    input.actionIndex = actionIndex;
    input.damage = damage;
    input.combatOutcome = combatOutcome;
    input.doorAffected = doorAffected;
    input.disabledTicks = 1;
    input.sourceTick = state->world.gameTick;
    (void)dm1_v1_live_action_effect_materialize_pc34(
        &state->dm1LiveActionEffects, &input, NULL);
}

static void m11_disable_champion_action_after_spell_f0412(
        M11_GameViewState* state,
        int championIndex,
        int ticks) {
    if (!state) return;
    if (championIndex < 0 || championIndex >= CHAMPION_MAX_PARTY) return;
    if (ticks <= 0) return;
    /* ReDMCSB: MENU.C F0412 lines 2034-2039 calls F0330 after
     * successful spell XP.  Spells do not assign Champion.ActionIndex;
     * TIMELINE.C F0253 only removes G0495 defense if an action index is
     * present, so preserve any existing action disable and otherwise use
     * C0xFF_ACTION_NONE. */
    if (state->actionDisabledIndex[championIndex] >= 44u) {
        state->actionDisabledIndex[championIndex] = 0xFFu;
    }
    m11_materialize_action_lock(state, championIndex,
                                (int)state->actionDisabledIndex[championIndex], ticks);
    state->actionEnableSlotOrdinal[championIndex] = 0u;
}

static void m11_disable_champion_action_f0328_throw(
        M11_GameViewState* state,
        int championIndex,
        int ticks) {
    if (!state) return;
    if (championIndex < 0 || championIndex >= CHAMPION_MAX_PARTY) return;
    if (ticks <= 0) return;
    /* ReDMCSB: CHAMPION.C F0328 line 2168 calls F0330 with 4 ticks.
     * F0330 initializes the enable-action event SlotOrdinal to 0; F0407
     * may later overwrite it with C01's 1-based inventory ordinal for action-row
     * THROW after F0328 succeeds. */
    state->actionDisabledIndex[championIndex] = 0xFFu;
    state->actionEnableSlotOrdinal[championIndex] = 0u;
    m11_materialize_action_lock(state, championIndex, 0xFF, ticks);
    (void)DM1_V1_F0330_ScheduleEnableChampionActionPc34Compat(
        &state->world, championIndex, ticks, 0);
}

/* ── Apply sensor effects from movement pipeline ──
 * Called after movement pipeline processes a tick.
 * Reads leaveEffects and enterEffects from the pipeline result
 * and applies them to the game world (door toggles, pit toggles,
 * teleporter toggles, text display).
 *
 * Ref: ReDMCSB MOVESENS.C F0268/F0272 effect dispatch. */
static int m11_print_dm1_sensor_message(M11_GameViewState* state,
                                        int textIndex) {
    char decoded[96];
    unsigned int wordOffset;

    if (!state || !state->world.things ||
        !state->world.things->textData ||
        state->world.things->textDataWordCount <= 0 ||
        !state->world.things->textStrings || textIndex < 0 ||
        textIndex >= state->world.things->textStringCount) {
        return 0;
    }
    wordOffset = state->world.things->textStrings[textIndex].textDataWordOffset;
    if (F0507_DUNGEON_DecodeTextAtOffset_Compat(
            state->world.things->textData,
            state->world.things->textDataWordCount,
            wordOffset, decoded, sizeof(decoded)) < 0 || decoded[0] == '\0') {
        return 0;
    }
    dm1_v1_text_set_game_time(&state->dm1V1TextMessage,
                              (long)state->world.gameTick);
    dm1_v1_text_print_message(&state->dm1V1TextMessage,
                              DM1_V1_COLOR_WHITE, decoded);
    return 1;
}

static void m11_apply_sensor_effects(M11_GameViewState* state,
                                     const struct SensorEffectList_Compat* effects) {
    int i;
    if (!state || !effects || effects->count <= 0) return;

    for (i = 0; i < effects->count && i < SENSOR_EFFECT_LIST_MAX_COUNT; ++i) {
        const struct SensorEffect_Compat* e = &effects->effects[i];

        switch (e->kind) {
        case SENSOR_EFFECT_TELEPORT:
            /* Teleport party to destination */
            if (e->destMapX >= 0 && e->destMapY >= 0) {
                state->world.party.mapX = e->destMapX;
                state->world.party.mapY = e->destMapY;
                m11_set_status(state, "SENSOR", "TELEPORTED");
                m11_refresh_hash(state);
            }
            break;

        case SENSOR_EFFECT_SHOW_TEXT: {
            /* ReDMCSB TEXT.C owns this path. Do not replace a missing or
             * malformed source string with a host label such as TEXT #N. */
            (void)m11_print_dm1_sensor_message(state, e->textIndex);
            break;
        }

        case SENSOR_EFFECT_TOGGLE_REMOTE: {
            /* Toggle remote target square: door, pit, teleporter, etc.
             * e->destMapX/Y = target coordinates
             * e->textIndex = effect code (0=SET, 1=CLEAR, 2=TOGGLE, 3=HOLD)
             *
             * ReDMCSB MOVESENS.C F0268: resolves target square type
             * and creates a timed event.  We apply immediately since
             * our timeline system handles the animation delay. */
            unsigned char targetSquare = 0;
            int targetElement;

            if (!m11_get_square_byte(&state->world,
                                     state->world.party.mapIndex,
                                     e->destMapX, e->destMapY,
                                     &targetSquare)) {
                break;
            }
            targetElement = (targetSquare & DUNGEON_SQUARE_MASK_TYPE) >> 5;

            if (targetElement == DUNGEON_ELEMENT_DOOR) {
                /* Toggle door at remote location */
                int doorEffect = 2; /* DOOR_EFFECT_TOGGLE */
                if (e->textIndex == 0) doorEffect = 0; /* SET = open */
                else if (e->textIndex == 1) doorEffect = 1; /* CLEAR = close */

                {
                    int resolvedEffect = -1;
                    int currentState = -1;
                    if (F0714_DOOR_ResolveAnimationEffect_Compat(
                            state->world.dungeon,
                            state->world.party.mapIndex,
                            e->destMapX, e->destMapY,
                            doorEffect,
                            &resolvedEffect, &currentState)) {
                        struct TimelineEvent_Compat animEvent;
                        if (F0713_DOOR_BuildAnimationEvent_Compat(
                                state->world.party.mapIndex,
                                e->destMapX, e->destMapY,
                                resolvedEffect,
                                state->world.gameTick,
                                &animEvent)) {
                            (void)F0721_TIMELINE_Schedule_Compat(
                                &state->world.timeline, &animEvent);
                        }
                    }
                }
                m11_set_status(state, "SENSOR", "DOOR TRIGGERED");
                /* ReDMCSB: audible sensors play C01_SOUND_SWITCH.
                 * Route through M11 audio backend when available. */
                if (state->audioState.lastSoundIndex >= -1) { /* audio available */
                    m11_audio_emit_source_sound(state, 1, M11_AUDIO_MARKER_DOOR); /* C01_SOUND_SWITCH */
                }
            } else if (targetElement == DUNGEON_ELEMENT_PIT) {
                /* Toggle pit open/closed.
                 * ReDMCSB DEFS.H: MASK0x0008_PIT_OPEN = bit 3. */
                int pitBit = (targetSquare & DM1_PIT_MASK_OPEN) ? 1 : 0;
                if (e->textIndex == 2) { /* TOGGLE */
                    pitBit = !pitBit;
                } else if (e->textIndex == 0) { /* SET = open */
                    pitBit = 1;
                } else if (e->textIndex == 1) { /* CLEAR = close */
                    pitBit = 0;
                }
                {
                    unsigned char newSq = (unsigned char)(
                        (targetSquare & ~DM1_PIT_MASK_OPEN) |
                        (pitBit ? DM1_PIT_MASK_OPEN : 0));
                    m11_set_square_byte(&state->world,
                                        state->world.party.mapIndex,
                                        e->destMapX, e->destMapY, newSq);
                }
                m11_set_status(state, "SENSOR", pitBit ? "PIT OPENED" : "PIT CLOSED");
                m11_refresh_hash(state);
            } else if (targetElement == DUNGEON_ELEMENT_FAKEWALL) {
                /* Toggle fakewall to corridor (or vice versa).
                 * ReDMCSB MOVESENS.C F0268: rewrites bits 7:5. */
                int makeCorridor = 1;
                if (e->textIndex == 1) makeCorridor = 0; /* CLEAR = restore fakewall */
                else if (e->textIndex == 2) makeCorridor = 1; /* TOGGLE when fakewall */
                {
                    unsigned char newSq = (unsigned char)(
                        (targetSquare & 0x1F) |
                        ((makeCorridor ? DUNGEON_ELEMENT_CORRIDOR : DUNGEON_ELEMENT_FAKEWALL) << 5));
                    m11_set_square_byte(&state->world,
                                        state->world.party.mapIndex,
                                        e->destMapX, e->destMapY, newSq);
                }
                m11_set_status(state, "SENSOR",
                               makeCorridor ? "WALL REVEALED" : "WALL HIDDEN");
                m11_refresh_hash(state);
            } else if (targetElement == DUNGEON_ELEMENT_CORRIDOR &&
                       e->textIndex == 1) {
                /* CLEAR on a corridor = restore it to fakewall */
                unsigned char newSq = (unsigned char)(
                    (targetSquare & 0x1F) |
                    (DUNGEON_ELEMENT_FAKEWALL << 5));
                m11_set_square_byte(&state->world,
                                    state->world.party.mapIndex,
                                    e->destMapX, e->destMapY, newSq);
                m11_set_status(state, "SENSOR", "WALL HIDDEN");
                m11_refresh_hash(state);
            } else if (targetElement == DUNGEON_ELEMENT_TELEPORTER) {
                /* Toggle teleporter active/inactive */
                int telBit = targetSquare & 0x01;
                if (e->textIndex == 2) telBit = !telBit;
                else if (e->textIndex == 0) telBit = 1;
                else if (e->textIndex == 1) telBit = 0;
                {
                    unsigned char newSq = (targetSquare & ~0x01) | (telBit ? 0x01 : 0x00);
                    m11_set_square_byte(&state->world,
                                        state->world.party.mapIndex,
                                        e->destMapX, e->destMapY, newSq);
                }
                m11_set_status(state, "SENSOR",
                               telBit ? "TELEPORTER ACTIVATED" : "TELEPORTER DEACTIVATED");
                m11_refresh_hash(state);
            }
            break;
        }
        case SENSOR_EFFECT_UNSUPPORTED:
            /* Log but don't crash */
            break;

        default:
            break;
        }
    }
}

