static const char* m11_creature_name(int creatureType) {
    const char* name = dm1_creature_type_name(creatureType);
    return (name && name[0] != '\0') ? name : "UNKNOWN";
}

static void m11_get_item_name(const struct DungeonThings_Compat* things,
                              unsigned short thingId,
                              char* out,
                              size_t outSize) {
    int thingType;
    int thingIndex;
    if (!out || outSize == 0U) {
        return;
    }
    if (!things || thingId == THING_NONE || thingId == THING_ENDOFLIST) {
        snprintf(out, outSize, "NOTHING");
        return;
    }
    thingType = THING_GET_TYPE(thingId);
    thingIndex = THING_GET_INDEX(thingId);
    switch (thingType) {
        case THING_TYPE_WEAPON:
            if (things->weapons && thingIndex >= 0 && thingIndex < things->weaponCount) {
                int subtype = things->weapons[thingIndex].type;
                if (subtype >= 0 && subtype < (int)(sizeof(s_weaponTypeNames) / sizeof(s_weaponTypeNames[0]))) {
                    snprintf(out, outSize, "%s", s_weaponTypeNames[subtype]);
                    return;
                }
            }
            snprintf(out, outSize, "WEAPON %d", thingIndex);
            return;
        case THING_TYPE_ARMOUR:
            if (things->armours && thingIndex >= 0 && thingIndex < things->armourCount) {
                int subtype = things->armours[thingIndex].type;
                if (subtype >= 0 && subtype < (int)(sizeof(s_armourTypeNames) / sizeof(s_armourTypeNames[0]))) {
                    snprintf(out, outSize, "%s", s_armourTypeNames[subtype]);
                    return;
                }
            }
            snprintf(out, outSize, "ARMOUR %d", thingIndex);
            return;
        case THING_TYPE_POTION:
            if (things->potions && thingIndex >= 0 && thingIndex < things->potionCount) {
                int subtype = things->potions[thingIndex].type;
                if (subtype >= 0 && subtype < (int)(sizeof(s_potionTypeNames) / sizeof(s_potionTypeNames[0]))) {
                    snprintf(out, outSize, "%s", s_potionTypeNames[subtype]);
                    return;
                }
            }
            snprintf(out, outSize, "POTION %d", thingIndex);
            return;
        case THING_TYPE_JUNK:
            if (things->junks && thingIndex >= 0 && thingIndex < things->junkCount) {
                int subtype = things->junks[thingIndex].type;
                if (subtype >= 0 && subtype < (int)(sizeof(s_junkTypeNames) / sizeof(s_junkTypeNames[0]))) {
                    snprintf(out, outSize, "%s", s_junkTypeNames[subtype]);
                    return;
                }
            }
            snprintf(out, outSize, "JUNK %d", thingIndex);
            return;
        case THING_TYPE_SCROLL:
            snprintf(out, outSize, "SCROLL");
            return;
        case THING_TYPE_CONTAINER:
            if (things->containers && thingIndex >= 0 && thingIndex < things->containerCount) {
                int subtype = things->containers[thingIndex].type;
                if (subtype >= 0 && subtype < (int)(sizeof(s_containerTypeNames) / sizeof(s_containerTypeNames[0]))) {
                    snprintf(out, outSize, "%s", s_containerTypeNames[subtype]);
                    return;
                }
            }
            snprintf(out, outSize, "CONTAINER %d", thingIndex);
            return;
        default:
            snprintf(out, outSize, "%s %d",
                     F0505_DUNGEON_GetThingTypeName_Compat(thingType), thingIndex);
            return;
    }
}

/* ReDMCSB OBJECT.C F0031 reads the non-raster M564 record before F0034 asks
 * for a leader-hand label.  M11's normal bitmap loader intentionally expands
 * raster entries only, so read this raw F0490 member separately. */
static int m11_dm1_load_object_names_m564(M11_GameViewState* state) {
    enum { M11_DM1_M564_PC34 = 694, M11_DM1_M564_LEGACY = 556,
           M11_DM1_OBJECT_NAME_COUNT = 199 };
    FILE* file;
    long fileLength;
    unsigned char* fileBytes = NULL;
    unsigned char* decoded = NULL;
    size_t decodedSize = 0u;
    size_t offset = 0u;
    int nameIndex;
    int highBitTerminated = 0;

    if (!state || !state->assetLoader.graphicsDatPath[0]) return 0;
    state->dm1ObjectNameTableValid = 0;
    memset(state->dm1ObjectNames, 0, sizeof(state->dm1ObjectNames));
    file = fopen(state->assetLoader.graphicsDatPath, "rb");
    if (!file || fseek(file, 0L, SEEK_END) != 0 ||
        (fileLength = ftell(file)) <= 0 || fseek(file, 0L, SEEK_SET) != 0) {
        if (file) fclose(file);
        return 0;
    }
    fileBytes = (unsigned char*)malloc((size_t)fileLength);
    decoded = (unsigned char*)malloc(65535u);
    if (!fileBytes || !decoded ||
        fread(fileBytes, 1u, (size_t)fileLength, file) != (size_t)fileLength) {
        fclose(file);
        free(decoded);
        free(fileBytes);
        return 0;
    }
    fclose(file);
    /* ReDMCSB's M564 number is media-dependent: current PC3.4 data uses
     * record 694, while older DM1 layouts use 556.  Admit only a complete
     * C199 stream, never a raster record that happens to decode. */
    if (csb_v1_graphics_decode_raw_entry_pc34(fileBytes, (size_t)fileLength,
                                               M11_DM1_M564_PC34, decoded, 65535u,
                                               &decodedSize) != 0) {
        if (csb_v1_graphics_decode_raw_entry_pc34(fileBytes, (size_t)fileLength,
                                                   M11_DM1_M564_LEGACY, decoded, 65535u,
                                                   &decodedSize) != 0) {
            free(decoded);
            free(fileBytes);
            return 0;
        }
    }
    for (offset = 0u; offset < decodedSize; ++offset) {
        if ((decoded[offset] & 0x80u) != 0u) {
            highBitTerminated = 1;
            break;
        }
    }
    offset = 0u;
    for (nameIndex = 0; nameIndex < M11_DM1_OBJECT_NAME_COUNT; ++nameIndex) {
        size_t written = 0u;
        int terminated = 0;
        while (offset < decodedSize) {
            unsigned char ch = decoded[offset++];
            if (highBitTerminated) {
                if (written + 1u < sizeof(state->dm1ObjectNames[nameIndex])) {
                    state->dm1ObjectNames[nameIndex][written++] = (char)(ch & 0x7fu);
                }
            } else if (ch != 0u &&
                       written + 1u < sizeof(state->dm1ObjectNames[nameIndex])) {
                state->dm1ObjectNames[nameIndex][written++] = (char)ch;
            }
            if ((highBitTerminated && (ch & 0x80u) != 0u) ||
                (!highBitTerminated && ch == 0u)) {
                terminated = 1;
                break;
            }
        }
        if (!terminated) {
            memset(state->dm1ObjectNames, 0, sizeof(state->dm1ObjectNames));
            free(decoded);
            free(fileBytes);
            return 0;
        }
    }
    free(decoded);
    free(fileBytes);
    state->dm1ObjectNameTableValid = 1;
    return 1;
}

static void m11_get_source_item_name(const M11_GameViewState* state,
                                     const struct DungeonThings_Compat* things,
                                     unsigned short thingId,
                                     char* out,
                                     size_t outSize) {
    int icon;
    if (state && m11_is_dm1_source_kind(state->sourceKind)) {
        /* ReDMCSB OBJECT.C F0031/F0033 owns DM1 names through M564's
         * icon-indexed stream.  A missing or malformed source table must not
         * turn the hand-written subtype catalog below into a production
         * answer: that catalog is not the PC34 object-name source and was the
         * cause of misleading HoC floor-item labels. */
        if (!state->dm1ObjectNameTableValid) {
            if (outSize > 0u) out[0] = '\0';
            return;
        }
        icon = dm1_v1_dungeon_get_object_icon_index_pc34(
            things, thingId, state->world.party.direction);
        if (icon >= 0 && icon < 199 && state->dm1ObjectNames[icon][0]) {
            snprintf(out, outSize, "%s", state->dm1ObjectNames[icon]);
            return;
        }
        if (outSize > 0u) out[0] = '\0';
        return;
    }
    m11_get_item_name(things, thingId, out, outSize);
}

/* ================================================================
 * Thing chain manipulation: remove an item from a square,
 * prepend an item to a square
 * ================================================================ */

static unsigned short m11_get_raw_next_thing(const struct DungeonThings_Compat* things,
                                             unsigned short thingId) {
    int type;
    int index;
    const unsigned char* raw;
    if (!things || thingId == THING_NONE || thingId == THING_ENDOFLIST) {
        return THING_ENDOFLIST;
    }
    type = THING_GET_TYPE(thingId);
    index = THING_GET_INDEX(thingId);
    if (type < 0 || type >= 16 || !things->rawThingData[type] ||
        index < 0 || index >= things->thingCounts[type]) {
        return THING_ENDOFLIST;
    }
    raw = things->rawThingData[type] + (index * s_thingDataByteCount[type]);
    return (unsigned short)(raw[0] | ((unsigned short)raw[1] << 8));
}

static unsigned short m11_get_decoded_next_thing(
    const struct DungeonThings_Compat* things,
    unsigned short thingId) {
    int type;
    int index;
    if (!things || thingId == THING_NONE || thingId == THING_ENDOFLIST) {
        return THING_ENDOFLIST;
    }
    type = THING_GET_TYPE(thingId);
    index = THING_GET_INDEX(thingId);
    if (index < 0) return THING_ENDOFLIST;
    switch (type) {
        case THING_TYPE_GROUP:
            return (things->groups && index < things->groupCount)
                ? things->groups[index].next : THING_ENDOFLIST;
        case THING_TYPE_WEAPON:
            return (things->weapons && index < things->weaponCount)
                ? things->weapons[index].next : THING_ENDOFLIST;
        case THING_TYPE_ARMOUR:
            return (things->armours && index < things->armourCount)
                ? things->armours[index].next : THING_ENDOFLIST;
        case THING_TYPE_SCROLL:
            return (things->scrolls && index < things->scrollCount)
                ? things->scrolls[index].next : THING_ENDOFLIST;
        case THING_TYPE_POTION:
            return (things->potions && index < things->potionCount)
                ? things->potions[index].next : THING_ENDOFLIST;
        case THING_TYPE_CONTAINER:
            return (things->containers && index < things->containerCount)
                ? things->containers[index].next : THING_ENDOFLIST;
        case THING_TYPE_JUNK:
            return (things->junks && index < things->junkCount)
                ? things->junks[index].next : THING_ENDOFLIST;
        default:
            break;
    }
    return THING_ENDOFLIST;
}

static void m11_set_raw_next_thing(struct DungeonThings_Compat* things,
                                   unsigned short thingId,
                                   unsigned short newNext) {
    int type;
    int index;
    unsigned char* raw;
    if (!things || thingId == THING_NONE || thingId == THING_ENDOFLIST) {
        return;
    }
    type = THING_GET_TYPE(thingId);
    index = THING_GET_INDEX(thingId);
    if (type < 0 || type >= 16 || !things->rawThingData[type] ||
        index < 0 || index >= things->thingCounts[type]) {
        return;
    }
    raw = things->rawThingData[type] + (index * s_thingDataByteCount[type]);
    raw[0] = (unsigned char)(newNext & 0xFFu);
    raw[1] = (unsigned char)((newNext >> 8) & 0xFFu);
}

static void m11_write_u16_le(unsigned char* raw, unsigned short value) {
    if (!raw) return;
    raw[0] = (unsigned char)(value & 0xFFu);
    raw[1] = (unsigned char)((value >> 8) & 0xFFu);
}

static unsigned short m11_get_raw_next_thing(
    const struct DungeonThings_Compat* things,
    unsigned short thingId);

static void m11_write_raw_group_record(struct DungeonThings_Compat* things,
                                       int groupIndex) {
    struct DungeonGroup_Compat* group;
    unsigned char* raw;
    unsigned short bitfield;

    if (!things || !things->groups || groupIndex < 0 ||
        groupIndex >= things->groupCount ||
        groupIndex >= things->thingCounts[THING_TYPE_GROUP] ||
        !things->rawThingData[THING_TYPE_GROUP] ||
        s_thingDataByteCount[THING_TYPE_GROUP] < 16) {
        return;
    }

    group = &things->groups[groupIndex];
    raw = things->rawThingData[THING_TYPE_GROUP] +
        (groupIndex * s_thingDataByteCount[THING_TYPE_GROUP]);
    bitfield = (unsigned short)(raw[14] | ((unsigned short)raw[15] << 8));
    bitfield = (unsigned short)((bitfield & 0xf890u) |
                                ((unsigned short)(group->behavior & 0x0Fu)) |
                                ((unsigned short)(group->count & 0x03u) << 5) |
                                ((unsigned short)(group->direction & 0x03u) << 8) |
                                ((unsigned short)(group->doNotDiscard & 0x01u) << 10));

    m11_write_u16_le(raw + 0, group->next);
    m11_write_u16_le(raw + 2, group->slot);
    raw[4] = group->creatureType;
    raw[5] = group->cells;
    m11_write_u16_le(raw + 6, group->health[0]);
    m11_write_u16_le(raw + 8, group->health[1]);
    m11_write_u16_le(raw + 10, group->health[2]);
    m11_write_u16_le(raw + 12, group->health[3]);
    m11_write_u16_le(raw + 14, bitfield);
}

/* GROUP.C F0190 consumes the loaded C04 record, not an independently
 * invented DungeonGroup mirror.  Keep the M11 death route fail-closed until
 * the C04 fields and the source square chain still describe the same group. */
static int m11_raw_group_record_matches_live(
    const struct DungeonThings_Compat* things,
    unsigned short groupThing) {
    const struct DungeonGroup_Compat* group;
    const unsigned char* raw;
    unsigned short bitfield;
    int groupIndex;
    int slot;

    if (!things || THING_GET_TYPE(groupThing) != THING_TYPE_GROUP) return 0;
    groupIndex = THING_GET_INDEX(groupThing);
    if (groupIndex < 0 || groupIndex >= things->groupCount ||
        (things->thingCounts[THING_TYPE_GROUP] > 0 &&
         groupIndex >= things->thingCounts[THING_TYPE_GROUP]) ||
        !things->groups) {
        return 0;
    }
    raw = dm1_v1_dungeon_get_thing_data_pc34(things, groupThing);
    if (!raw) return 1;
    group = &things->groups[groupIndex];
    bitfield = (unsigned short)(raw[14] | ((unsigned short)raw[15] << 8));
    if (raw[4] >= 27u ||
        group->next != (unsigned short)(raw[0] | ((unsigned short)raw[1] << 8)) ||
        group->slot != (unsigned short)(raw[2] | ((unsigned short)raw[3] << 8)) ||
        group->creatureType != raw[4] || group->cells != raw[5] ||
        group->behavior != (unsigned char)(bitfield & 0x0fu) ||
        group->count != (unsigned char)((bitfield >> 5) & 0x03u) ||
        group->direction != (unsigned char)((bitfield >> 8) & 0x03u) ||
        group->doNotDiscard != (unsigned char)((bitfield >> 10) & 0x01u)) {
        return 0;
    }
    for (slot = 0; slot < 4; ++slot) {
        unsigned short rawHealth = (unsigned short)(
            raw[6 + slot * 2] | ((unsigned short)raw[7 + slot * 2] << 8));
        if (group->health[slot] != rawHealth) return 0;
    }
    return 1;
}

static int m11_raw_square_contains_thing(
    const struct GameWorld_Compat* world,
    int mapIndex,
    int mapX,
    int mapY,
    unsigned short target) {
    const struct DungeonMapDesc_Compat* map;
    int base;
    int squareIndex;
    unsigned short current;
    int safety = 0;

    if (!world || !world->dungeon || !world->things ||
        !world->things->squareFirstThings || target == THING_NONE ||
        target == THING_ENDOFLIST || mapIndex < 0 ||
        mapIndex >= (int)world->dungeon->header.mapCount) {
        return 0;
    }
    map = &world->dungeon->maps[mapIndex];
    if (mapX < 0 || mapY < 0 || mapX >= (int)map->width ||
        mapY >= (int)map->height) {
        return 0;
    }
    if (m11_world_has_compact_sft(world)) {
        current = F0511_DUNGEON_GetSquareFirstThing_Compat(
            world->dungeon, world->things, mapIndex, mapX, mapY);
    } else {
        base = m11_map_square_base(world->dungeon, mapIndex);
        if (base < 0) return 0;
        squareIndex = base + mapX * (int)map->height + mapY;
        if (squareIndex < 0 || squareIndex >= world->things->squareFirstThingCount) {
            return 0;
        }
        current = world->things->squareFirstThings[squareIndex];
    }
    while (current != THING_NONE && current != THING_ENDOFLIST && safety++ < 64) {
        if (current == target) return 1;
        current = m11_get_raw_next_thing(world->things, current);
    }
    return 0;
}

/* GROUP.C F0197/F0198 read the loaded dungeon square for every F0199 ray
 * step.  A missing square or an unsupported closed door is blocked: M11
 * must not invent a clear sight line from its decoded display state. */
struct M11GroupSightRouteSource {
    const struct GameWorld_Compat* world;
    int mapIndex;
    int smell;
};

/* DUNGEON.C F0174 selects G0275[Door.Type] from the loaded map descriptor.
 * The ray must retain the actual C00 owner as well: a display-only door or a
 * stale decoded door cannot turn an opaque route into a sight line. */
static int m11_group_sight_door_can_see_through_source(
    const struct GameWorld_Compat* world,
    int mapIndex,
    int mapX,
    int mapY)
{
    const struct DungeonMapDesc_Compat* map;
    const struct DungeonThings_Compat* things;
    const struct DungeonDoor_Compat* door;
    const unsigned char* raw;
    const DM1_V1_RaDoorProjectileDoorInfoPc34* info;
    unsigned short thing;
    unsigned short bitfield;
    int doorIndex;
    int doorSet;

    if (!world || !world->dungeon || !world->things ||
        mapIndex < 0 || mapIndex >= (int)world->dungeon->header.mapCount) {
        return 0;
    }
    map = &world->dungeon->maps[mapIndex];
    things = world->things;
    thing = m11_square_chain_head(world, mapIndex, mapX, mapY);
    if (THING_GET_TYPE(thing) != THING_TYPE_DOOR || !things->doors) return 0;
    doorIndex = THING_GET_INDEX(thing);
    if (doorIndex < 0 || doorIndex >= things->doorCount ||
        doorIndex >= things->thingCounts[THING_TYPE_DOOR]) {
        return 0;
    }
    raw = dm1_v1_dungeon_get_thing_data_pc34(things, thing);
    if (!raw) return 0;
    door = &things->doors[doorIndex];
    bitfield = (unsigned short)(raw[2] | ((unsigned short)raw[3] << 8));
    if (door->next != (unsigned short)(raw[0] | ((unsigned short)raw[1] << 8)) ||
        door->type != (unsigned char)(bitfield & 0x01u) ||
        door->ornamentOrdinal != (unsigned char)((bitfield >> 1) & 0x0fu) ||
        door->vertical != (unsigned char)((bitfield >> 5) & 0x01u) ||
        door->button != (unsigned char)((bitfield >> 6) & 0x01u) ||
        door->magicDestructible != (unsigned char)((bitfield >> 7) & 0x01u) ||
        door->meleeDestructible != (unsigned char)((bitfield >> 8) & 0x01u)) {
        return 0;
    }
    doorSet = door->type ? map->doorSet1 : map->doorSet0;
    info = dm1_v1_ra_door_projectile_reject_door_info_pc34(
        (size_t)(doorSet & 0x03));
    return info && info->door_type == (doorSet & 0x03) &&
        info->creatures_can_see_through;
}

static int m11_group_sight_route_square_blocked(int mapX, int mapY,
                                                void* context) {
    const struct M11GroupSightRouteSource* source =
        (const struct M11GroupSightRouteSource*)context;
    struct DM1GroupSightSquare_Compat square;
    unsigned char rawSquare;
    int type;

    if (!source || !source->world ||
        !m11_get_square_byte(source->world, source->mapIndex,
                             mapX, mapY, &rawSquare)) {
        return 1;
    }
    memset(&square, 0, sizeof(square));
    type = (rawSquare & DUNGEON_SQUARE_MASK_TYPE) >> 5;
    if (type < DUNGEON_ELEMENT_WALL || type > DUNGEON_ELEMENT_FAKEWALL) {
        return 1;
    }
    square.elementType = type;
    square.doorState = rawSquare & 0x07;
    square.fakeWallOpen = (rawSquare & 0x04) != 0;
    square.fakeWallImaginary = (rawSquare & 0x01) != 0;

    square.creaturesCanSeeThrough =
        type == DUNGEON_ELEMENT_DOOR &&
        m11_group_sight_door_can_see_through_source(
            source->world, source->mapIndex, mapX, mapY);
    return source->smell
        ? F0817e_DM1_GROUP_IsSmellPartyBlocked_Compat(&square)
        : F0817d_DM1_GROUP_IsViewPartyBlocked_Compat(&square);
}

static int m11_group_live_position_matches_source(
    const M11_GameViewState* state,
    unsigned short groupThing,
    int mapIndex,
    int mapX,
    int mapY) {
    const struct DungeonGroup_Compat* group;
    int groupIndex;
    int i;

    if (!state || !state->world.things ||
        THING_GET_TYPE(groupThing) != THING_TYPE_GROUP) {
        return 0;
    }
    groupIndex = THING_GET_INDEX(groupThing);
    if (groupIndex < 0 || groupIndex >= state->world.things->groupCount ||
        !m11_raw_group_record_matches_live(state->world.things, groupThing) ||
        !m11_raw_square_contains_thing(&state->world, mapIndex, mapX, mapY,
                                       groupThing)) {
        return 0;
    }
    group = &state->world.things->groups[groupIndex];
    for (i = 0; i < state->world.creatureAICount; ++i) {
        const struct CreatureAIState_Compat* ai = &state->world.creatureAI[i];
        if (ai->reserved0 != groupIndex) continue;
        if (ai->groupMapIndex != mapIndex || ai->groupMapX != mapX ||
            ai->groupMapY != mapY || ai->creatureType != group->creatureType) {
            return 0;
        }
    }
    return 1;
}

static void m11_set_decoded_next_thing(struct DungeonThings_Compat* things,
                                       unsigned short thingId,
                                       unsigned short newNext) {
    int type;
    int index;
    if (!things || thingId == THING_NONE || thingId == THING_ENDOFLIST) {
        return;
    }
    type = THING_GET_TYPE(thingId);
    index = THING_GET_INDEX(thingId);
    if (index < 0) return;
    switch (type) {
    case THING_TYPE_GROUP:
        if (things->groups && index < things->groupCount) {
            things->groups[index].next = newNext;
        }
        break;
    case THING_TYPE_TELEPORTER:
        if (things->teleporters && index < things->teleporterCount) {
            things->teleporters[index].next = newNext;
        }
        break;
    case THING_TYPE_SENSOR:
        if (things->sensors && index < things->sensorCount) {
            things->sensors[index].next = newNext;
        }
        break;
    case THING_TYPE_WEAPON:
        if (things->weapons && index < things->weaponCount) {
            things->weapons[index].next = newNext;
        }
        break;
    case THING_TYPE_ARMOUR:
        if (things->armours && index < things->armourCount) {
            things->armours[index].next = newNext;
        }
        break;
    case THING_TYPE_SCROLL:
        if (things->scrolls && index < things->scrollCount) {
            things->scrolls[index].next = newNext;
        }
        break;
    case THING_TYPE_POTION:
        if (things->potions && index < things->potionCount) {
            things->potions[index].next = newNext;
        }
        break;
    case THING_TYPE_CONTAINER:
        if (things->containers && index < things->containerCount) {
            things->containers[index].next = newNext;
        }
        break;
    case THING_TYPE_JUNK:
        if (things->junks && index < things->junkCount) {
            things->junks[index].next = newNext;
        }
        break;
    case THING_TYPE_PROJECTILE:
        if (things->projectiles && index < things->projectileCount) {
            things->projectiles[index].next = newNext;
        }
        break;
    case THING_TYPE_EXPLOSION:
        if (things->explosions && index < things->explosionCount) {
            things->explosions[index].next = newNext;
        }
        break;
    default:
        break;
    }
}

static void m11_set_next_thing(struct DungeonThings_Compat* things,
                               unsigned short thingId,
                               unsigned short newNext) {
    m11_set_decoded_next_thing(things, thingId, newNext);
    m11_set_raw_next_thing(things, thingId, newNext);
}

static int m11_append_thing_to_chain_tail(struct DungeonThings_Compat* things,
                                          unsigned short* head,
                                          unsigned short thing) {
    unsigned short current;
    int safety = 0;
    if (!things || !head || thing == THING_NONE || thing == THING_ENDOFLIST) {
        return 0;
    }
    m11_set_next_thing(things, thing, THING_ENDOFLIST);
    if (*head == THING_NONE || *head == THING_ENDOFLIST) {
        *head = thing;
        return 1;
    }
    current = *head;
    while (current != THING_NONE && current != THING_ENDOFLIST &&
           safety++ < 64) {
        unsigned short next = m11_get_raw_next_thing(things, current);
        if (next == THING_NONE || next == THING_ENDOFLIST) {
            next = m11_get_decoded_next_thing(things, current);
        }
        if (next == THING_NONE || next == THING_ENDOFLIST) {
            m11_set_next_thing(things, current, thing);
            return 1;
        }
        current = next;
    }
    return 0;
}

/* Remove a specific thing from a square's chain. Returns 1 if removed. */
static int m11_unlink_thing_from_square(struct GameWorld_Compat* world,
                                        int mapIndex,
                                        int mapX,
                                        int mapY,
                                        unsigned short target) {
    int base;
    const struct DungeonMapDesc_Compat* map;
    int squareIndex;
    unsigned short current;
    unsigned short prev;
    int safety = 0;

    if (!world || !world->dungeon || !world->things || !world->things->squareFirstThings) {
        return 0;
    }
    /* Compact F0160/F0161 layout: unlink through the source F0515
     * contract so the per-column cumulative counts stay consistent. */
    if (m11_world_has_compact_sft(world)) {
        return F0515_DUNGEON_UnlinkThingFromList_Compat(
            world->dungeon, world->things, target, THING_ENDOFLIST,
            mapIndex, mapX, mapY);
    }
    if (mapIndex < 0 || mapIndex >= (int)world->dungeon->header.mapCount) {
        return 0;
    }
    map = &world->dungeon->maps[mapIndex];
    if (mapX < 0 || mapY < 0 || mapX >= (int)map->width || mapY >= (int)map->height) {
        return 0;
    }
    base = m11_map_square_base(world->dungeon, mapIndex);
    if (base < 0) {
        return 0;
    }
    squareIndex = base + mapX * (int)map->height + mapY;
    if (squareIndex < 0 || squareIndex >= world->things->squareFirstThingCount) {
        return 0;
    }

    current = world->things->squareFirstThings[squareIndex];
    prev = THING_ENDOFLIST;

    while (current != THING_ENDOFLIST && current != THING_NONE && safety < 64) {
        if (current == target) {
            unsigned short next = m11_raw_next_thing(world->things, current);
            if (prev == THING_ENDOFLIST) {
                world->things->squareFirstThings[squareIndex] = next;
            } else {
                m11_set_next_thing(world->things, prev, next);
            }
            m11_set_next_thing(world->things, current, THING_ENDOFLIST);
            return 1;
        }
        prev = current;
        current = m11_raw_next_thing(world->things, current);
        ++safety;
    }
    return 0;
}

/* Prepend a thing to a square's chain. */
static int m11_prepend_thing_to_square(struct GameWorld_Compat* world,
                                       int mapIndex,
                                       int mapX,
                                       int mapY,
                                       unsigned short thingId) {
    int base;
    const struct DungeonMapDesc_Compat* map;
    int squareIndex;
    unsigned short oldFirst;

    if (!world || !world->dungeon || !world->things || !world->things->squareFirstThings) {
        return 0;
    }
    if (mapIndex < 0 || mapIndex >= (int)world->dungeon->header.mapCount) {
        return 0;
    }
    /* Compact F0160/F0161 layout: link through the source F0514
     * contract (inserts a slot for unflagged squares and keeps the
     * per-column cumulative counts consistent). */
    if (m11_world_has_compact_sft(world)) {
        return F0514_DUNGEON_LinkThingToList_Compat(
            world->dungeon, world->things, thingId, THING_ENDOFLIST,
            mapIndex, mapX, mapY);
    }
    map = &world->dungeon->maps[mapIndex];
    if (mapX < 0 || mapY < 0 || mapX >= (int)map->width || mapY >= (int)map->height) {
        return 0;
    }
    base = m11_map_square_base(world->dungeon, mapIndex);
    if (base < 0) {
        return 0;
    }
    squareIndex = base + mapX * (int)map->height + mapY;
    if (squareIndex < 0 || squareIndex >= world->things->squareFirstThingCount) {
        return 0;
    }

    oldFirst = world->things->squareFirstThings[squareIndex];
    m11_set_next_thing(world->things, thingId, oldFirst);
    world->things->squareFirstThings[squareIndex] = thingId;
    return 1;
}

static unsigned short m11_thing_with_cell(int thingType, int thingIndex, int cell) {
    return (unsigned short)(((cell & 0x03) << 14) |
                            ((thingType & 0x0F) << 10) |
                            (thingIndex & 0x03FF));
}

static void m11_store_raw_object4(struct DungeonThings_Compat* things,
                                  int thingType,
                                  int thingIndex,
                                  unsigned short next,
                                  int itemType,
                                  int cursed) {
    unsigned char* raw;
    unsigned short bf;
    if (!things || thingType < 0 || thingType >= 16 ||
        thingIndex < 0 || thingIndex >= things->thingCounts[thingType] ||
        !things->rawThingData[thingType]) {
        return;
    }

    raw = things->rawThingData[thingType] +
          thingIndex * s_thingDataByteCount[thingType];
    raw[0] = (unsigned char)(next & 0xFFu);
    raw[1] = (unsigned char)((next >> 8) & 0xFFu);
    bf = (unsigned short)(itemType & 0x7F);
    if (cursed) bf |= 0x0100u;
    raw[2] = (unsigned char)(bf & 0xFFu);
    raw[3] = (unsigned char)((bf >> 8) & 0xFFu);
}

static void m11_set_object_drop_next(struct DungeonThings_Compat* things,
                                     unsigned short thing,
                                     unsigned short next) {
    int type;
    int index;
    if (!things || thing == THING_NONE || thing == THING_ENDOFLIST) return;
    type = THING_GET_TYPE(thing);
    index = THING_GET_INDEX(thing);
    switch (type) {
    case THING_TYPE_WEAPON:
        if (things->weapons && index >= 0 && index < things->weaponCount) {
            things->weapons[index].next = next;
            m11_store_raw_object4(things, type, index, next,
                                  things->weapons[index].type,
                                  things->weapons[index].cursed);
        }
        break;
    case THING_TYPE_ARMOUR:
        if (things->armours && index >= 0 && index < things->armourCount) {
            things->armours[index].next = next;
            m11_store_raw_object4(things, type, index, next,
                                  things->armours[index].type,
                                  things->armours[index].cursed);
        }
        break;
    case THING_TYPE_JUNK:
        if (things->junks && index >= 0 && index < things->junkCount) {
            things->junks[index].next = next;
            m11_store_raw_object4(things, type, index, next,
                                  things->junks[index].type,
                                  things->junks[index].cursed);
        }
        break;
    case THING_TYPE_POTION:
        if (things->potions && index >= 0 && index < things->potionCount) {
            unsigned char* raw;
            unsigned short bf;
            things->potions[index].next = next;
            if (things->rawThingData[type] &&
                index < things->thingCounts[type]) {
                raw = things->rawThingData[type] +
                      index * s_thingDataByteCount[type];
                raw[0] = (unsigned char)(next & 0xFFu);
                raw[1] = (unsigned char)((next >> 8) & 0xFFu);
                bf = (unsigned short)(things->potions[index].power & 0xFFu);
                bf |= (unsigned short)((things->potions[index].type & 0x7Fu) << 8);
                if (things->potions[index].doNotDiscard) bf |= 0x8000u;
                raw[2] = (unsigned char)(bf & 0xFFu);
                raw[3] = (unsigned char)((bf >> 8) & 0xFFu);
            }
        }
        break;
    default:
        break;
    }
}

static int m11_find_unused_object_slot(const struct DungeonThings_Compat* things,
                                       int thingType) {
    int i;
    if (!things) return -1;
    switch (thingType) {
    case THING_TYPE_WEAPON:
        if (!things->weapons) return -1;
        for (i = 0; i < things->weaponCount; ++i) {
            if (things->weapons[i].next == THING_NONE) return i;
        }
        break;
    case THING_TYPE_ARMOUR:
        if (!things->armours) return -1;
        for (i = 0; i < things->armourCount; ++i) {
            if (things->armours[i].next == THING_NONE) return i;
        }
        break;
    case THING_TYPE_JUNK:
        if (!things->junks) return -1;
        for (i = 0; i < things->junkCount; ++i) {
            if (things->junks[i].next == THING_NONE) return i;
        }
        break;
    default:
        break;
    }
    return -1;
}

static unsigned short m11_allocate_fixed_possession_thing(
    struct DungeonThings_Compat* things,
    const struct DM1FixedPossessionDrop_Compat* drop) {
    int index;
    unsigned short thing;
    if (!things || !drop) return THING_NONE;
    index = m11_find_unused_object_slot(things, drop->thingType);
    if (index < 0) return THING_NONE;

    thing = m11_thing_with_cell(drop->thingType, index, drop->cell);
    switch (drop->thingType) {
    case THING_TYPE_WEAPON:
        memset(&things->weapons[index], 0, sizeof(things->weapons[index]));
        things->weapons[index].next = THING_ENDOFLIST;
        things->weapons[index].type = (unsigned char)(drop->itemType & 0x7F);
        things->weapons[index].cursed = (unsigned char)(drop->cursed ? 1 : 0);
        break;
    case THING_TYPE_ARMOUR:
        memset(&things->armours[index], 0, sizeof(things->armours[index]));
        things->armours[index].next = THING_ENDOFLIST;
        things->armours[index].type = (unsigned char)(drop->itemType & 0x7F);
        things->armours[index].cursed = (unsigned char)(drop->cursed ? 1 : 0);
        break;
    case THING_TYPE_JUNK:
        memset(&things->junks[index], 0, sizeof(things->junks[index]));
        things->junks[index].next = THING_ENDOFLIST;
        things->junks[index].type = (unsigned char)(drop->itemType & 0x7F);
        things->junks[index].cursed = (unsigned char)(drop->cursed ? 1 : 0);
        break;
    default:
        return THING_NONE;
    }
    m11_store_raw_object4(things, drop->thingType, index, THING_ENDOFLIST,
                          drop->itemType, drop->cursed);
    return thing;
}

static int m11_link_fixed_possession_thing_to_square(
    struct GameWorld_Compat* world,
    int mapIndex,
    int mapX,
    int mapY,
    unsigned short thing) {
    int base;
    const struct DungeonMapDesc_Compat* map;
    int squareIndex;
    unsigned short oldFirst;

    if (!world || !world->dungeon || !world->things || !world->things->squareFirstThings) return 0;
    if (mapIndex < 0 || mapIndex >= (int)world->dungeon->header.mapCount) return 0;
    map = &world->dungeon->maps[mapIndex];
    if (mapX < 0 || mapY < 0 || mapX >= (int)map->width || mapY >= (int)map->height) return 0;
    /* Real PC34 saves compact SquareFirstThings by flagged square.  F0514
     * owns both tail linking and the insertion/cumulative-column update. */
    if (m11_world_has_compact_sft(world)) {
        return F0514_DUNGEON_LinkThingToList_Compat(
            world->dungeon, world->things, thing, THING_ENDOFLIST,
            mapIndex, mapX, mapY);
    }
    base = m11_map_square_base(world->dungeon, mapIndex);
    if (base < 0) return 0;
    squareIndex = base + mapX * (int)map->height + mapY;
    if (squareIndex < 0 || squareIndex >= world->things->squareFirstThingCount) return 0;

    oldFirst = world->things->squareFirstThings[squareIndex];
    m11_set_object_drop_next(world->things, thing, THING_ENDOFLIST);
    if (oldFirst == THING_ENDOFLIST || oldFirst == THING_NONE) {
        world->things->squareFirstThings[squareIndex] = thing;
    } else {
        unsigned short current = oldFirst;
        int safety = 0;
        while (current != THING_ENDOFLIST && current != THING_NONE &&
               safety++ < 64) {
            unsigned short next = m11_get_raw_next_thing(world->things, current);
            if (next == THING_ENDOFLIST || next == THING_NONE) {
                next = m11_get_decoded_next_thing(world->things, current);
            }
            if (next == THING_ENDOFLIST || next == THING_NONE) {
                int currentType = THING_GET_TYPE(current);
                if (currentType == THING_TYPE_WEAPON ||
                    currentType == THING_TYPE_ARMOUR ||
                    currentType == THING_TYPE_JUNK) {
                    m11_set_object_drop_next(world->things, current, thing);
                } else {
                    m11_set_raw_next_thing(world->things, current, thing);
                    m11_set_decoded_next_thing(world->things, current, thing);
                }
                break;
            }
            current = next;
        }
    }
    return 1;
}

/* A saved PC34 party can already contain the source-created bones record
 * before M11 sees the zero-health champion for the first time.  Treat that
 * record as the completed F0319 transition instead of dropping its inventory
 * and manufacturing a second bones record after load. */
static int m11_has_champion_bones_f0319(const struct DungeonThings_Compat* things,
                                        int championIndex) {
    int i;
    if (!things || !things->junks || championIndex < 0) return 0;
    for (i = 0; i < things->junkCount; ++i) {
        const struct DungeonJunk_Compat* junk = &things->junks[i];
        if (junk->type == DM1_JUNK_TYPE_BONES && junk->doNotDiscard &&
            junk->chargeCount == (unsigned char)championIndex) {
            return 1;
        }
    }
    return 0;
}

/* ReDMCSB CHAMPION.C F0318:1527-1550 and F0319:1552-1687. */
static void m11_kill_champion_f0319(M11_GameViewState* state, int championIndex) {
    struct ChampionState_Compat* champion;
    int slot;
    int aliveIndex = -1;
    if (!state || championIndex < 0 ||
        championIndex >= state->world.party.championCount) return;
    champion = &state->world.party.champions[championIndex];
    if (!champion->present) return;
    if (state->championDeathHandledMask & (unsigned char)(1u << championIndex)) {
        return;
    }
    if (m11_has_champion_bones_f0319(state->world.things, championIndex)) {
        state->championDeathHandledMask |= (unsigned char)(1u << championIndex);
        return;
    }

    champion->hp.current = 0;
    if (state->inventoryPanelActive &&
        state->world.party.activeChampionIndex == championIndex) {
        state->inventoryPanelActive = 0;
    }
    state->spellPanelOpen = 0;

    for (slot = 0; slot < dm1_v1_slot_drop_order_size_pc34(); ++slot) {
        int inventorySlot = dm1_v1_slot_drop_order_get_pc34(slot);
        unsigned short thing;
        if (inventorySlot < 0 || inventorySlot >= CHAMPION_SLOT_COUNT) continue;
        thing = champion->inventory[inventorySlot];
        if (thing == THING_NONE || thing == THING_ENDOFLIST) continue;
        /* CHAMPION.C F0319 drops inventory objects through F0163. A
         * structural Thing value cannot inhabit a champion slot; rejecting
         * it keeps an uninitialised C00 record from becoming a fake floor
         * item ahead of the independently-owned F0215 projectile drop. */
        if (!dm1_v1_thing_type_is_floor_item_pc34(THING_GET_TYPE(thing))) {
            continue;
        }
        champion->inventory[inventorySlot] = THING_NONE;
        (void)m11_prepend_thing_to_square(&state->world,
                                           state->world.party.mapIndex,
                                           state->world.party.mapX,
                                           state->world.party.mapY,
                                           (unsigned short)((thing & 0x3fffu) |
                                               ((unsigned short)(champion->cell & 3) << 14)));
    }

    /* F0319 allocates an actual unused JUNK record; lack of one leaves the
     * source path without bones instead of manufacturing a replacement. */
    if (state->world.things) {
        int junkIndex = m11_find_unused_object_slot(state->world.things,
                                                     THING_TYPE_JUNK);
        if (junkIndex >= 0) {
            unsigned short bones = m11_thing_with_cell(THING_TYPE_JUNK,
                                                        junkIndex, champion->cell);
            unsigned char* raw = state->world.things->rawThingData[THING_TYPE_JUNK];
            memset(&state->world.things->junks[junkIndex], 0,
                   sizeof(state->world.things->junks[junkIndex]));
            state->world.things->junks[junkIndex].next = THING_ENDOFLIST;
            state->world.things->junks[junkIndex].type = DM1_JUNK_TYPE_BONES;
            state->world.things->junks[junkIndex].doNotDiscard = 1;
            state->world.things->junks[junkIndex].chargeCount =
                (unsigned char)championIndex;
            if (raw && junkIndex < state->world.things->thingCounts[THING_TYPE_JUNK]) {
                raw += junkIndex * s_thingDataByteCount[THING_TYPE_JUNK];
                raw[0] = 0xff; raw[1] = 0xff;
                raw[2] = DM1_JUNK_TYPE_BONES | 0x80u;
                raw[3] = (unsigned char)((championIndex & 3) << 6);
            }
            (void)m11_prepend_thing_to_square(&state->world,
                                               state->world.party.mapIndex,
                                               state->world.party.mapX,
                                               state->world.party.mapY, bones);
        }
    }
    champion->wounds = 0;
    champion->poisonDose = 0;
    champion->direction = (unsigned char)(state->world.party.direction & 3);
    state->world.lifecycle.champions[championIndex].poisonEventCount = 0;
    state->championDeathHandledMask |= (unsigned char)(1u << championIndex);
    for (slot = 0; slot < state->world.party.championCount; ++slot) {
        if (state->world.party.champions[slot].present &&
            state->world.party.champions[slot].hp.current > 0) {
            aliveIndex = slot;
            break;
        }
    }
    if (aliveIndex >= 0 && state->world.party.activeChampionIndex == championIndex) {
        state->world.party.activeChampionIndex = aliveIndex;
    }
}

static int m11_materialize_creature_fixed_possession_drops(
    M11_GameViewState* state,
    int creatureType,
    int sourceCell,
    int mapIndex,
    int mapX,
    int mapY) {
    struct DM1FixedPossessionDrop_Compat drops[DM1_MAX_FIXED_POSSESSION_DROPS];
    int dropCount = 0;
    int weaponDropped = 0;
    int materialized = 0;
    int i;

    if (!state || !state->world.things) return -1;
    if (!F0824_DM1_GROUP_ResolveFixedPossessionDrops_Compat(
            creatureType, sourceCell, &state->world.masterRng, drops,
            DM1_MAX_FIXED_POSSESSION_DROPS, &dropCount, &weaponDropped)) {
        return -1;
    }

    for (i = 0; i < dropCount; ++i) {
        unsigned short thing =
            m11_allocate_fixed_possession_thing(state->world.things, &drops[i]);
        if (thing == THING_NONE) {
            continue;
        }
        if (m11_link_fixed_possession_thing_to_square(
                &state->world, mapIndex, mapX, mapY, thing)) {
            ++materialized;
        } else {
            m11_set_object_drop_next(state->world.things, thing, THING_NONE);
        }
    }

    if (materialized > 0) {
        m11_audio_emit_source_sound(
            state, weaponDropped ? DM1_SND_METALLIC_THUD : DM1_SND_WOODEN_THUD,
            M11_AUDIO_MARKER_COMBAT);
    }
    return materialized;
}

int M11_GameView_ProbeMaterializeCreatureFixedPossessionDrops(
    M11_GameViewState* state,
    int creatureType,
    int sourceCell,
    int mapIndex,
    int mapX,
    int mapY) {
    return m11_materialize_creature_fixed_possession_drops(
        state, creatureType, sourceCell, mapIndex, mapX, mapY);
}

/* Find the first item-type thing on a square. */
static unsigned short m11_find_first_item_on_square(
    const struct GameWorld_Compat* world,
    int mapIndex,
    int mapX,
    int mapY) {
    unsigned short thing = m11_square_chain_head(world, mapIndex, mapX, mapY);
    int safety = 0;
    while (thing != THING_ENDOFLIST && thing != THING_NONE && safety < 64) {
        if (dm1_v1_thing_type_is_floor_item_pc34(THING_GET_TYPE(thing))) {
            return thing;
        }
        thing = m11_raw_next_thing(world->things, thing);
        ++safety;
    }
    return THING_NONE;
}

/* ReDMCSB CLIKVIEW.C F0373 takes G0292_aT_PileTopObject[viewCell], not an
 * arbitrary object from the square's chain.  The packed THING cell is the
 * source identity of that rendered pile. */
static unsigned short m11_find_pile_top_item_on_square(
    const struct GameWorld_Compat* world,
    int mapIndex,
    int mapX,
    int mapY,
    int viewCell,
    int partyDirection) {
    unsigned short thing = m11_square_chain_head(world, mapIndex, mapX, mapY);
    int sourceCell = (partyDirection + viewCell) & 3;
    int safety = 0;

    while (thing != THING_ENDOFLIST && thing != THING_NONE && safety < 64) {
        if (dm1_v1_thing_type_is_floor_item_pc34(THING_GET_TYPE(thing)) &&
            (int)THING_GET_CELL(thing) == sourceCell) {
            return thing;
        }
        thing = m11_raw_next_thing(world->things, thing);
        ++safety;
    }
    return THING_NONE;
}

/* Declared here because the source slot-mask table lives with the inventory
 * panel implementation below this pickup path. */
static unsigned int m11_v1_inventory_source_slot_box_mask(int sourceSlotBoxIndex);

/* Find the first empty slot admitted by ReDMCSB F0302/G0038. */
static int m11_find_empty_slot(const struct ChampionState_Compat* champ,
                               const struct DungeonThings_Compat* things,
                               unsigned short thing) {
    unsigned int allowedSlots;
    if (!champ || !champ->present || !things ||
        thing == THING_NONE || thing == THING_ENDOFLIST) {
        return -1;
    }
    allowedSlots = dm1_v1_dungeon_get_object_allowed_slots_pc34(things, thing);
    if (allowedSlots == 0u) return -1;

    /* ReDMCSB checks ObjectAllowedSlots & G0038[slot] before every
     * placement. Keep the action-hand-first UX, but only among legal slots. */
    {
        static const int preferredSlots[] = {
            CHAMPION_SLOT_HAND_RIGHT,
            CHAMPION_SLOT_HAND_LEFT,
            CHAMPION_SLOT_POUCH_1,
            CHAMPION_SLOT_POUCH_2,
            CHAMPION_SLOT_BACKPACK_1,
            CHAMPION_SLOT_BACKPACK_2,
            CHAMPION_SLOT_BACKPACK_3,
            CHAMPION_SLOT_BACKPACK_4,
            CHAMPION_SLOT_BACKPACK_5,
            CHAMPION_SLOT_BACKPACK_6,
            CHAMPION_SLOT_BACKPACK_7,
            CHAMPION_SLOT_BACKPACK_8,
            CHAMPION_SLOT_BACKPACK_9,
            CHAMPION_SLOT_BACKPACK_10,
            CHAMPION_SLOT_BACKPACK_11,
            CHAMPION_SLOT_BACKPACK_12,
            CHAMPION_SLOT_BACKPACK_13,
            CHAMPION_SLOT_BACKPACK_14,
            CHAMPION_SLOT_BACKPACK_15,
            CHAMPION_SLOT_BACKPACK_16,
            CHAMPION_SLOT_BACKPACK_17
        };
        size_t i;
        for (i = 0; i < sizeof(preferredSlots) / sizeof(preferredSlots[0]); ++i) {
            int sourceSlot =
                M11_GameView_GetV1InventorySourceSlotBoxForChampionSlot(
                    preferredSlots[i]);
            if (sourceSlot >= 0 &&
                (allowedSlots & m11_v1_inventory_source_slot_box_mask(sourceSlot)) != 0u &&
                champ->inventory[preferredSlots[i]] == THING_NONE) {
                return preferredSlots[i];
            }
        }
    }
    return -1;
}

/* Count items in a champion's inventory. */
int M11_GameView_CountChampionItems(const M11_GameViewState* state, int championIndex) {
    int count = 0;
    int slot;
    const struct ChampionState_Compat* champ;
    if (!state || championIndex < 0 || championIndex >= CHAMPION_MAX_PARTY) {
        return 0;
    }
    champ = &state->world.party.champions[championIndex];
    if (!champ->present) {
        return 0;
    }
    for (slot = 0; slot < CHAMPION_SLOT_COUNT; ++slot) {
        if (champ->inventory[slot] != THING_NONE) {
            ++count;
        }
    }
    return count;
}

int M11_GameView_GetSkillLevel(const M11_GameViewState* state,
                               int championIndex,
                               int skillIndex) {
    DM1_ChampionSkillState skillState;
    DM1_SkillLevelQuery query;
    const struct ChampionLifecycleState_Compat* lifecycleChampion;
    const struct ChampionState_Compat* champion;
    int partyIsResting;
    int i;

    if (!state || !state->active) return -1;
    if (championIndex < 0 || championIndex >= CHAMPION_MAX_PARTY) return -1;
    champion = &state->world.party.champions[championIndex];
    if (!champion->present) return -1;
    if (skillIndex < 0 || skillIndex >= DM1_TOTAL_SKILL_COUNT) return -1;

    lifecycleChampion = &state->world.lifecycle.champions[championIndex];
    memset(&skillState, 0, sizeof(skillState));
    for (i = 0; i < DM1_TOTAL_SKILL_COUNT && i < LIFECYCLE_SKILL_COUNT; ++i) {
        skillState.skills[i].experience = lifecycleChampion->skills20[i].experience;
        skillState.skills[i].temporaryExperience =
            lifecycleChampion->skills20[i].temporaryExperience;
    }

    partyIsResting = state->resting ||
                     state->world.partyIsResting ||
                     state->world.lifecycle.rest.isResting;
    if (!dm1_skill_build_query_from_champion_inventory(
            champion, state->world.things, partyIsResting, &query)) {
        return F0848_LIFECYCLE_ComputeSkillLevel_Compat(
            lifecycleChampion, skillIndex, 0);
    }

    /* ReDMCSB: MENU.C/F0407 and F0412 query skill levels through
     * CHAMPION.C F0303, so live M11 checks must include resting,
     * temporary XP, and action-hand/neck object modifiers. */
    return dm1_skill_get_level_ex(&skillState, skillIndex, 0, &query);
}

static int m11_game_view_get_f0230_parry_skill(
    const M11_GameViewState* state,
    int championIndex) {
    int parrySkill = M11_GameView_GetSkillLevel(
        state, championIndex, DM1_SKILL_IDX_PARRY);
    return parrySkill < 0 ? 0 : parrySkill;
}

int M11_GameView_ProbeF0230ParryAdjustedAttack(
    const M11_GameViewState* state,
    int championIndex,
    int random16,
    int creatureBaseAttack,
    int doubledMapDifficulty) {
    int parrySkill = m11_game_view_get_f0230_parry_skill(
        state, championIndex);
    /* ReDMCSB: PROJEXPL.C F0230 lines 1390-1395:
     * RANDOM(16) + CreatureAttack + (MapDifficulty << 1)
     * - (F0303(PARRY) << 1). */
    return random16 + creatureBaseAttack + doubledMapDifficulty
           - (parrySkill * 2);
}

static int m11_game_view_get_f0352_potion_priest_skill(
    const M11_GameViewState* state,
    int championIndex) {
    int priestSkill = M11_GameView_GetSkillLevel(
        state, championIndex, DM1_SKILL_IDX_PRIEST);
    return priestSkill < 0 ? 0 : priestSkill;
}

int M11_GameView_ProbeF0352PotionEyeDescription(
    const M11_GameViewState* state,
    int championIndex,
    unsigned int thingType,
    unsigned int iconIndex,
    unsigned int potionPower,
    const char* objectName,
    char* outText,
    unsigned int outCapacity) {
    return INVENTORY_Compat_FormatPotionEyeDescription(
        thingType,
        iconIndex,
        potionPower,
        (unsigned int)m11_game_view_get_f0352_potion_priest_skill(
            state, championIndex),
        objectName,
        outText,
        outCapacity,
        NULL);
}

/* ================================================================
 * Pickup: take first item from current cell -> champion inventory
 * ================================================================ */

int M11_GameView_PickupItem(M11_GameViewState* state) {
    unsigned short item;
    struct ChampionState_Compat* champ;
    char itemName[48];

    if (!state || !state->active || state->partyDead) {
        return 0;
    }
    if (m11_dm1_hoc_menu_route_blocks_normal_input(state)) {
        /* ReDMCSB: COMMAND.C F0380 lines 2159, 2180, 2303,
         * 2309, 2338, and 2367 route normal status, inventory,
         * spell, action, rest, and save commands around
         * G0299_ui_CandidateChampionOrdinal while C040 owns input.
         * Keep Firestaff's direct object convenience API from
         * mutating floor/inventory state behind that live panel. */
        return 0;
    }
    if (state->world.party.activeChampionIndex < 0 ||
        state->world.party.activeChampionIndex >= CHAMPION_MAX_PARTY) {
        m11_set_status(state, "PICKUP", "NO ACTIVE CHAMPION");
        return 0;
    }
    champ = &state->world.party.champions[state->world.party.activeChampionIndex];
    if (!champ->present || champ->hp.current == 0) {
        m11_set_status(state, "PICKUP", "CHAMPION CANNOT ACT");
        return 0;
    }

    /* F0373 owns the visible pile top. Prefer the frame-local target that
     * was actually painted, preventing an invisible chain neighbour from
     * being removed when several objects share a square. */
    item = THING_NONE;
    {
        int targetIndex;
        for (targetIndex = s_m11_dm1_rendered_pile_target_count - 1;
             targetIndex >= 0; --targetIndex) {
            const M11_Dm1RenderedPileTarget* target =
                &s_m11_dm1_rendered_pile_targets[targetIndex];
            if (target->valid &&
                target->mapIndex == state->world.party.mapIndex &&
                target->mapX == state->world.party.mapX &&
                target->mapY == state->world.party.mapY) {
                item = target->thing;
                break;
            }
        }
    }
    if (item == THING_NONE) {
        item = m11_find_first_item_on_square(
            &state->world,
            state->world.party.mapIndex,
            state->world.party.mapX,
            state->world.party.mapY);
    }
    if (item == THING_NONE) {
        m11_set_status(state, "PICKUP", "NOTHING TO PICK UP");
        snprintf(state->inspectTitle, sizeof(state->inspectTitle), "EMPTY FLOOR");
        snprintf(state->inspectDetail, sizeof(state->inspectDetail),
                 "NO ITEMS ON THIS CELL");
        return 0;
    }

    /* ReDMCSB CLIKVIEW.C F0373 removes the visible pile-top object and
     * calls F0297, which owns G4055_s_LeaderHandObject.  A floor pickup is
     * therefore independent of free inventory capacity: the object follows
     * the pointer until F0302 places it in a legal hand/container slot. */
    if (DM1_V1_M11Runtime_GetLeaderHandThingPc34Compat(state) != THING_NONE) {
        m11_set_status(state, "PICKUP", "LEADER HAND FULL");
        snprintf(state->inspectTitle, sizeof(state->inspectTitle), "HAND FULL");
        snprintf(state->inspectDetail, sizeof(state->inspectDetail),
                 "PLACE THE HELD OBJECT FIRST");
        return 0;
    }

    if (!m11_unlink_thing_from_square(&state->world,
                                      state->world.party.mapIndex,
                                      state->world.party.mapX,
                                      state->world.party.mapY,
                                      item)) {
        m11_set_status(state, "PICKUP", "CHAIN ERROR");
        return 0;
    }

    if (!DM1_V1_M11Runtime_SetLeaderHandObjectPc34Compat(state, item)) {
        (void)m11_prepend_thing_to_square(&state->world,
                                          state->world.party.mapIndex,
                                          state->world.party.mapX,
                                          state->world.party.mapY,
                                          item);
        m11_set_status(state, "PICKUP", "HAND ROUTE FAILED");
        return 0;
    }
    m11_get_source_item_name(state, state->world.things, item, itemName, sizeof(itemName));
    m11_log_event(state, M11_COLOR_LIGHT_GREEN, "T%u: HELD %s",
                  (unsigned int)state->world.gameTick, itemName);
    m11_set_status(state, "PICKUP", "ITEM IN HAND");
    snprintf(state->inspectTitle, sizeof(state->inspectTitle), "PICKED UP");
    snprintf(state->inspectDetail, sizeof(state->inspectDetail),
             "%s -> MOUSE HAND", itemName);
    m11_refresh_hash(state);
    return 1;
}

/* ================================================================
 * Drop: take item from champion hand/slot -> current cell
 * ================================================================ */

int M11_GameView_DropItem(M11_GameViewState* state) {
    struct ChampionState_Compat* champ;
    unsigned short item = THING_NONE;
    int dropSlot = -1;
    int slot;
    char itemName[48];
    char champName[16];

    if (!state || !state->active || state->partyDead) {
        return 0;
    }
    if (m11_dm1_hoc_menu_route_blocks_normal_input(state)) {
        /* ReDMCSB: COMMAND.C F0380 lines 2159, 2180, 2303,
         * 2309, 2338, and 2367 keep the C040 candidate panel
         * as the active command surface through
         * G0299_ui_CandidateChampionOrdinal. */
        return 0;
    }
    if (state->world.party.activeChampionIndex < 0 ||
        state->world.party.activeChampionIndex >= CHAMPION_MAX_PARTY) {
        m11_set_status(state, "DROP", "NO ACTIVE CHAMPION");
        return 0;
    }
    champ = &state->world.party.champions[state->world.party.activeChampionIndex];
    if (!champ->present || champ->hp.current == 0) {
        m11_set_status(state, "DROP", "CHAMPION CANNOT ACT");
        return 0;
    }

    /* F0374 consumes G4055 (the transient mouse/leader hand) before any
     * champion slot is considered.  Previously this command searched only
     * the inventory, leaving a picked-up object apparently undroppable until
     * the user found the pointer-specific viewport route.  The keyboard
     * command targets the party's current square directly; it must not run
     * the pointer helper's viewport-cell hit testing. */
    item = DM1_V1_M11Runtime_GetLeaderHandThingPc34Compat(state);
    if (item != THING_NONE) {
        DM1_V1_M11Runtime_ClearLeaderHandObjectPc34Compat(state);
        if (!m11_prepend_thing_to_square(&state->world,
                                         state->world.party.mapIndex,
                                         state->world.party.mapX,
                                         state->world.party.mapY,
                                         item)) {
            (void)DM1_V1_M11Runtime_SetLeaderHandObjectPc34Compat(state, item);
            m11_set_status(state, "DROP", "DROP TARGET UNAVAILABLE");
            return 0;
        }
        m11_get_source_item_name(state, state->world.things, item,
                                 itemName, sizeof(itemName));
        m11_set_status(state, "DROP", "ITEM DROPPED");
        snprintf(state->inspectTitle, sizeof(state->inspectTitle), "DROPPED");
        snprintf(state->inspectDetail, sizeof(state->inspectDetail),
                 "%s FROM MOUSE HAND", itemName);
        m11_refresh_hash(state);
        return 1;
    }

    /* Drop from hands first (right, then left), then last backpack item */
    if (champ->inventory[CHAMPION_SLOT_HAND_RIGHT] != THING_NONE) {
        dropSlot = CHAMPION_SLOT_HAND_RIGHT;
    } else if (champ->inventory[CHAMPION_SLOT_HAND_LEFT] != THING_NONE) {
        dropSlot = CHAMPION_SLOT_HAND_LEFT;
    } else {
        for (slot = CHAMPION_SLOT_BACKPACK_8; slot >= CHAMPION_SLOT_BACKPACK_1; --slot) {
            if (champ->inventory[slot] != THING_NONE) {
                dropSlot = slot;
                break;
            }
        }
        if (dropSlot < 0) {
            for (slot = CHAMPION_SLOT_POUCH_2; slot >= CHAMPION_SLOT_POUCH_1; --slot) {
                if (champ->inventory[slot] != THING_NONE) {
                    dropSlot = slot;
                    break;
                }
            }
        }
    }

    if (dropSlot < 0) {
        m11_set_status(state, "DROP", "NOTHING TO DROP");
        snprintf(state->inspectTitle, sizeof(state->inspectTitle), "EMPTY HANDS");
        snprintf(state->inspectDetail, sizeof(state->inspectDetail),
                 "PICK SOMETHING UP FIRST (G KEY)");
        return 0;
    }

    item = champ->inventory[dropSlot];
    champ->inventory[dropSlot] = THING_NONE;

    if (!m11_prepend_thing_to_square(&state->world,
                                     state->world.party.mapIndex,
                                     state->world.party.mapX,
                                     state->world.party.mapY,
                                     item)) {
        /* Restore if chain operation fails */
        champ->inventory[dropSlot] = item;
        m11_set_status(state, "DROP", "CHAIN ERROR");
        return 0;
    }

    m11_get_source_item_name(state, state->world.things, item, itemName, sizeof(itemName));
    m11_format_champion_name(champ->name, champName, sizeof(champName));

    m11_log_event(state, M11_COLOR_YELLOW, "T%u: %s DROPPED %s",
                  (unsigned int)state->world.gameTick, champName, itemName);
    m11_set_status(state, "DROP", "ITEM DROPPED");
    snprintf(state->inspectTitle, sizeof(state->inspectTitle), "DROPPED");
    snprintf(state->inspectDetail, sizeof(state->inspectDetail),
             "%s FROM %s SLOT %d", itemName, champName, dropSlot);
    m11_refresh_hash(state);
    return 1;
}

