void M11_GameView_ProcessTickEmissions(M11_GameViewState* state) {
    int i;
    if (!state) {
        return;
    }
    for (i = 0; i < state->lastTickResult.emissionCount; ++i) {
        const struct TickEmission_Compat* e = &state->lastTickResult.emissions[i];
        m11_audio_emit_for_emission(state, e);
        switch (e->kind) {
            case EMIT_DAMAGE_DEALT: {
                DM1_MeleeDamageEmissionInputPc34 meleeEmissionIn;
                DM1_MeleeDamageEmissionPlanPc34 meleeEmissionPlan;
                memset(&meleeEmissionIn, 0, sizeof(meleeEmissionIn));
                memset(&meleeEmissionPlan, 0, sizeof(meleeEmissionPlan));
                meleeEmissionIn.damage = (int)e->payload[2];
                meleeEmissionIn.combatOutcome = (int)e->payload[3];
                if (!dm1_v1_melee_damage_emission_plan_f0231_pc34(
                        &meleeEmissionIn, &meleeEmissionPlan) ||
                    !meleeEmissionPlan.showDamageFeedback) {
                    break;
                }
                m11_materialize_action_result(
                    state, DM1_V1_LIVE_ACTION_EFFECT_DAMAGE_PC34,
                    (int)e->payload[0], -1, meleeEmissionPlan.damage,
                    (int)e->payload[3], 0);
                m11_log_event(state, M11_COLOR_LIGHT_RED,
                              "T%u: DAMAGE %d DEALT",
                              (unsigned int)state->world.gameTick,
                              meleeEmissionPlan.damage);
                /* ReDMCSB: PROJEXPL.C F0231 lines 1534-1536 awards
                 * damage XP/stamina at hit resolution, and MENU.C F0407
                 * lines 1620-1628 separately applies the action tail XP.
                 * M10 owns those source effects; M11 only presents the
                 * positive EMIT_DAMAGE_DEALT feedback. */
                M11_GameView_NotifyCreatureHit(state, meleeEmissionPlan.damage);
                break;
            }
            case EMIT_KILL_NOTIFY: {
                /* payload[0] = creature type (if available), else -1 */
                int cType = (int)e->payload[0];
                DM1_MeleeKillNotifyPlanPc34 killPlan;
                if (m11_dm1_kill_notify_plan(
                        state, cType >= 0 ? cType : 0, &killPlan)) {
                    m11_apply_kill_notify_plan(state, &killPlan);
                }
                break;
            }
            case EMIT_XP_AWARD:
                m11_log_event(state, M11_COLOR_YELLOW,
                              "T%u: EXPERIENCE GAINED",
                              (unsigned int)state->world.gameTick);
                break;
            case EMIT_CHAMPION_DAMAGED: {
                int champIdx = (int)e->payload[0];
                int damage = (int)e->payload[2];
                if (damage > 0) {
                    M11_GameView_NotifyChampionDamage(state, champIdx, damage);
                    m11_log_event(state, M11_COLOR_LIGHT_RED,
                                  "T%u: CHAMPION %d DAMAGED %d",
                                  (unsigned int)state->world.gameTick,
                                  champIdx + 1, damage);
                }
                break;
            }
            case EMIT_CHAMPION_DAMAGE_HIDDEN: {
                int champIdx = (int)e->payload[0];
                /* TIMELINE.C F0254 redraws the exact champion panel and
                 * clears its saved damage graphic. The runtime renderer owns
                 * that overlay as championDamageTimer/Amount. */
                if (champIdx >= 0 && champIdx < CHAMPION_MAX_PARTY) {
                    state->championDamageTimer[champIdx] = 0;
                    state->championDamageAmount[champIdx] = 0;
                }
                break;
            }
            case EMIT_TEXT_MESSAGE: {
                char decoded[256];
                int textIndex = (int)e->payload[0];
                /* ReDMCSB TIMELINE.C F0245:949-954 calls F0168 with
                 * C1_TEXT_TYPE_MESSAGE, then F0047 directly.  The M10
                 * emission is already restricted to a hidden->visible
                 * TextString on the party square, so M11 only consumes its
                 * source index through the same message decoder. */
                if (F0508_DUNGEON_DecodeTextStringThing_Compat(
                        state->world.things, textIndex,
                        DUNGEON_TEXT_TYPE_MESSAGE, decoded,
                        (int)sizeof(decoded)) > 0) {
                    /* TEXT.C F0047 owns C015. Keep decoded source text in
                     * its source state, not in M11's diagnostic log. */
                    dm1_v1_text_set_game_time(
                        &state->dm1V1TextMessage,
                        (long)state->world.gameTick);
                    dm1_v1_text_print_message(&state->dm1V1TextMessage,
                                              DM1_V1_COLOR_WHITE, decoded);
                }
                break;
            }
            case EMIT_CHAMPION_DOWN: {
                int champIdx = (int)e->payload[0];
                char name[16];
                if (champIdx >= 0 && champIdx < CHAMPION_MAX_PARTY &&
                    state->world.party.champions[champIdx].present) {
                    m11_format_champion_name(
                        state->world.party.champions[champIdx].name,
                        name, sizeof(name));
                } else {
                    snprintf(name, sizeof(name), "CHAMPION");
                }
                m11_log_event(state, M11_COLOR_LIGHT_RED,
                              "T%u: %s HAS FALLEN",
                              (unsigned int)state->world.gameTick, name);
                break;
            }
            case EMIT_PARTY_MOVED:
                m11_log_event(state, M11_COLOR_LIGHT_GRAY,
                              "T%u: PARTY MOVED TO %d,%d",
                              (unsigned int)state->world.gameTick,
                              state->world.party.mapX,
                              state->world.party.mapY);
                break;
            case EMIT_PARTY_FELL:
                m11_log_event(state, M11_COLOR_YELLOW,
                              "T%u: FELL INTO PIT! LEVEL %d",
                              (unsigned int)state->world.gameTick,
                              (int)e->payload[0] + 1);
                m11_set_status(state, "PIT", "FELL TO NEXT LEVEL");
                snprintf(state->inspectTitle, sizeof(state->inspectTitle), "PIT FALL");
                snprintf(state->inspectDetail, sizeof(state->inspectDetail),
                         "DROPPED TO LEVEL %d, POSITION (%d,%d)",
                         (int)e->payload[0] + 1,
                         (int)e->payload[1],
                         (int)e->payload[2]);
                break;
            case EMIT_PARTY_TELEPORTED:
                m11_log_event(state, M11_COLOR_LIGHT_CYAN,
                              "T%u: TELEPORTED TO MAP %d (%d,%d)",
                              (unsigned int)state->world.gameTick,
                              (int)e->payload[0] + 1,
                              (int)e->payload[1],
                              (int)e->payload[2]);
                m11_set_status(state, "TELEPORT", "PARTY TRANSPORTED");
                snprintf(state->inspectTitle, sizeof(state->inspectTitle), "TELEPORTER");
                snprintf(state->inspectDetail, sizeof(state->inspectDetail),
                         "ARRIVED AT LEVEL %d, POSITION (%d,%d)",
                         (int)e->payload[0] + 1,
                         (int)e->payload[1],
                         (int)e->payload[2]);
                break;
            case EMIT_DOOR_STATE:
                m11_materialize_action_result(
                    state, DM1_V1_LIVE_ACTION_EFFECT_DOOR_PC34,
                    -1, -1, 0, COMBAT_OUTCOME_INVALID, 1);
                m11_log_event(state, M11_COLOR_YELLOW,
                              "T%u: DOOR STATE CHANGED",
                              (unsigned int)state->world.gameTick);
                break;
            case EMIT_SPELL_EFFECT: {
                /* payload[0]=champIdx, [1]=spellKind, [2]=spellType,
                 * [3]=packed power ordinal + G0487 SkillIndex */
                int sChamp = (int)e->payload[0];
                int sKind = (int)e->payload[1];
                int sType = (int)e->payload[2];
                int sPow  = (int)EMIT_SPELL_EFFECT_UNPACK_POWER(e->payload[3]);
                int sSkill = (int)EMIT_SPELL_EFFECT_UNPACK_SKILL(e->payload[3]);
                int sXp = (int)EMIT_SPELL_EFFECT_UNPACK_XP(e->payload[3]);
                const char* kindStr = "SPELL";
                m11_materialize_action_result(
                    state, DM1_V1_LIVE_ACTION_EFFECT_SPELL_PC34,
                    sChamp, -1, sPow, sKind, 0);
                if (sKind == C2_SPELL_KIND_PROJECTILE_COMPAT) kindStr = "PROJECTILE";
                else if (sKind == C3_SPELL_KIND_OTHER_COMPAT) kindStr = "ENCHANTMENT";
                else if (sKind == C1_SPELL_KIND_POTION_COMPAT) kindStr = "POTION";
                m11_log_event(state, M11_COLOR_CYAN,
                              "T%u: %s EFFECT APPLIED (TYPE %d, POWER %d)",
                              (unsigned int)state->world.gameTick,
                              kindStr, sType, sPow);
                /* ReDMCSB: MENU.C F0412 lines 1826-1839 computes spell
                 * experience from G0487 Spell.SkillIndex, then lines
                 * 2034-2039 award it once and disable the caster after
                 * the spell effect succeeds. */
                m11_award_magic_xp(state, sChamp, sSkill, sXp);
                break;
            }
            case EMIT_ACTION_DISABLED:
                m11_disable_champion_action_after_spell_f0412(
                    state, (int)e->payload[0], (int)e->payload[1]);
                break;
            case EMIT_ACTION_ENABLED:
                m11_enable_champion_action_from_timeline(
                    state, (int)e->payload[0], (int)e->payload[1]);
                break;
            case EMIT_GAME_WON:
                if (!state->gameWon) {
                    state->gameWon = 1;
                    state->gameWonTick = state->world.gameTick;
                    m11_log_event(state, M11_COLOR_LIGHT_GREEN,
                                  "T%u: THE QUEST IS COMPLETE!",
                                  (unsigned int)state->world.gameTick);
                    m11_set_status(state, "ENDGAME", "VICTORY!");
                    snprintf(state->inspectTitle,
                             sizeof(state->inspectTitle), "VICTORY");
                    snprintf(state->inspectDetail,
                             sizeof(state->inspectDetail),
                             "LORD CHAOS IS DEFEATED. THE FIRESTAFF IS RESTORED.");
                }
                break;
            case EMIT_PARTY_DEAD:
                if (!state->partyDead) {
                    state->partyDead = 1;
                    m11_log_event(state, M11_COLOR_LIGHT_RED,
                                  "T%u: ALL CHAMPIONS HAVE FALLEN",
                                  (unsigned int)state->world.gameTick);
                    m11_set_status(state, "DEATH", "PARTY WIPED");
                    snprintf(state->inspectTitle,
                             sizeof(state->inspectTitle), "GAME OVER");
                    snprintf(state->inspectDetail,
                             sizeof(state->inspectDetail),
                             "THE DUNGEON CLAIMS YOUR SOULS. LOAD A SAVE OR RETURN TO MENU.");
                }
                break;
            case EMIT_CREATURE_MOVED:
                m11_audio_emit_creature_movement_sound(
                    state, (int)e->payload[1],
                    (int)e->payload[2], (int)e->payload[3]);
                break;
            case EMIT_SENSOR_EFFECT: {
                /* ReDMCSB TIMELINE.C F0245:972-986 handles sensor
                 * walk-on/walk-off effects emitted by F0718.
                 * payload[0]=kind, [1]=sensorType, [2]=triggerEvent,
                 * [3]=textIndex or destMapIndex.
                 *
                 * This emission is an observation receipt only.  The
                 * source-owned movement pipeline applies the corresponding
                 * F0276 effect immediately after the timeline dispatch;
                 * rendering SHOW_TEXT here would print every walk-on message
                 * twice and would force it through the wrong presentation
                 * color. */
                break;
            }
            default:
                break;
        }
    }

    /* V1 projectile cycle: after the M10 orchestrator has advanced
     * one tick and its emissions have been processed, step each live
     * projectile via F0811 so the cast visibly travels and detonates
     * instead of freezing at its spawn cell.  Runs exactly once per
     * orchestrator tick; no-op when no projectiles are live. */
    m11_advance_projectiles_v1(state, 0);

    /* V1 explosion cycle: after projectiles have stepped (and may have
     * spawned new first-frame explosions on impact), advance every
     * live explosion one frame via F0822.  This turns the post-
     * detonation aftermath into the classic DM1 multi-frame progression
     * (poison/smoke clouds decay and dissipate; fireball/lightning
     * emit their damage action on the first advance and despawn the
     * slot) rather than leaving a single frozen burst frame. */
    m11_advance_explosions_v1(state);
}

static void m11_dm1_f0740_bind_driver(M11_GameViewState *state);

void M11_GameView_Init(M11_GameViewState* state) {
    if (!state) {
        return;
    }
    m11_dm1_c13_visible_runtime_handoff_clear(state);
    memset(state, 0, sizeof(*state));
    dm1_spell_init(&state->dm1SpellCasting);
    dm1_v1_text_init(&state->dm1V1TextMessage);
    firestaff_ra_overlay_init(&state->retroAchievementsOverlay);
    (void)M11_Audio_Init(&state->audioState);
    if (state->audioState.originalSongAvailable &&
        state->audioState.originalSongDatPath[0]) {
        state->dm1MusicSourceBound = dm1_v1_f0740_f0743_bind_song_dat_pc34(
            state->audioState.originalSongDatPath, &state->dm1MusicSource);
    }
    /* V1 presentation: debug HUD off by default, opt-in via env */
    {
        const char* dbg = getenv("FIRESTAFF_DEBUG_HUD");
        state->showDebugHUD = (dbg && dbg[0] == '1') ? 1 : 0;
    }
    state->candidateMirrorOrdinal = -1;
    state->candidateMirrorPartyIndex = -1;
    state->leaderHandObjectPresent = 0;
    state->leaderHandThing = THING_NONE;
    state->leaderHandIconIndex = -1;
    state->dm1ViewportRuntimeOrigin =
        DM1_V1_VIEWPORT_RUNTIME_ORIGIN_NEW_START_PC34;
    state->dm1ViewportPresentedPaletteIndex = -1;
    state->v1ScrollPanelActive = 0;
    state->v1ScrollPanelThing = THING_NONE;
    state->v1OpenChestThing = THING_NONE;
    state->v1ObjectDescriptionThing = THING_NONE;
    state->v1ObjectDescriptionIconIndex = -1;
    state->v1FoodWaterPanelActive = 0;
    {
        int i;
        for (i = 0; i < CHAMPION_MAX_PARTY; ++i) {
            state->actionDisabledIndex[i] = 0xFFu;
            state->actionEnableSlotOrdinal[i] = 0xFFu;
        }
    }
    m11_set_status(state, "BOOT", "GAME VIEW NOT STARTED");
    m11_set_inspect_readout(state, "NO FOCUS", "PRESS ENTER OR CLICK THE VIEW TO READ THE FRONT CELL");

    /* M11 construction is on the launch critical path.  It previously
     * scanned PO files here, always selecting English first and allowing
     * filesystem latency to block game startup before TITLE/ENTRANCE.  M12
     * owns localized UI catalogs; the V1 engine therefore starts from its
     * original English strings until a selected game-domain catalog is
     * explicitly installed by the frontend. */
    DM1_V1_VBlankTiming_Init(&state->vblankTiming);
    DM1_V1_MovementPipeline_InitPc34Compat(&state->dm1V1MovementPipeline);
    DM1_SaveMenu_Init(&state->saveMenu);
    state->dm1MusicOn = 1;
    dm1_v1_f0740_f0743_music_state_init_pc34(&state->dm1MusicState);
    memset(&state->dm1MusicSource, 0, sizeof(state->dm1MusicSource));
    m11_dm1_f0740_bind_driver(state);
    state->dm1MusicSourceBound = 0;
    /* Generate a random game ID (matches ReDMCSB G0525_l_GameID
     * = RANDOM(65536) * RANDOM(65536) in LOADSAVE.C F0435) */
    state->dm1GameID = ((uint32_t)(rand() & 0xFFFF) << 16) | (uint32_t)(rand() & 0xFFFF);
    /* DM1 V2 Phase 5: camera interpolation state starts at zero.
     * M11_GameView_SetCameraOffset() is called from the V2 presentation
     * lane after each V1 tick; V1 paths leave these fields zero. */
    state->camera_offset_x = 0;
    state->camera_offset_y = 0;
    state->camera_interpolated_facing = 0;
    state->camera_duration_ms = 96;
    /* Phase 5: zero the private camera controller */
    memset(&state->p5_camera, 0, sizeof(state->p5_camera));
}

int M11_GameView_SetCsbEntranceF0128Raster(
    M11_GameViewState *state,
    const CSB_V1_ViewportFirstFrameMaterializationReceipt *material_receipt,
    const CSB_V1_ViewportFirstFrameRasterReceiptPc34 *raster_receipt,
    const uint8_t *viewport_pixels,
    size_t viewport_pixel_count,
    uint32_t source_tick,
    uint32_t session_generation)
{
    CSB_V1_ViewportFirstFrameMaterializationReceipt material_copy;
    CSB_V1_ViewportFirstFrameRasterReceiptPc34 raster_copy;

    if (!state) return 0;
    if (material_receipt) material_copy = *material_receipt;
    if (raster_receipt) raster_copy = *raster_receipt;
    state->csbStartupF0128EntranceBound = 0;
    memset(&state->csbStartupF0128EntranceMaterialReceipt, 0,
           sizeof(state->csbStartupF0128EntranceMaterialReceipt));
    memset(&state->csbStartupF0128EntranceRasterReceipt, 0,
           sizeof(state->csbStartupF0128EntranceRasterReceipt));
    if (!material_receipt || !raster_receipt || !viewport_pixels ||
        viewport_pixel_count != sizeof(state->csbStartupF0128EntrancePixels) ||
        source_tick == 0u || session_generation == 0u ||
        !material_copy.valid || !material_copy.consumed_by_m11_render ||
        !material_copy.real_graphics_session ||
        !material_copy.no_synthetic_pixels ||
        !material_copy.no_fallback_visuals ||
        material_copy.combined_material_hash == 0u ||
        !raster_copy.valid || !raster_copy.consumed_by_raster ||
        raster_copy.rejected || raster_copy.command_count <= 0 ||
        raster_copy.combined_material_hash !=
            material_copy.combined_material_hash ||
        raster_copy.raster_hash == 0u) {
        return 0;
    }

    state->csbStartupF0128EntranceMaterialReceipt = material_copy;
    state->csbStartupF0128EntranceRasterReceipt = raster_copy;
    memcpy(state->csbStartupF0128EntrancePixels, viewport_pixels,
           sizeof(state->csbStartupF0128EntrancePixels));
    state->csbStartupF0128EntranceSourceTick = source_tick;
    state->csbStartupF0128EntranceSessionGeneration = session_generation;
    state->csbStartupF0128EntranceBound = 1;
    return 1;
}

void M11_GameView_Shutdown(M11_GameViewState* state) {
    if (!state) {
        return;
    }
    if (state->sourceKind == M11_GAME_SOURCE_CSB_BOOT) {
        csb_v2_runtime_cleanup();
    }
    if (state->sourceKind == M11_GAME_SOURCE_DM2_BOOT) {
        /* The SDL device is a host resource, while decoded PCM remains
         * owned by the verified GDAT loader in the DM2 boot profile. */
        dm2_v1_sound_bind_playback_backend(NULL);
    }
    theron_v1_track01_cdda_stream_stop(&state->theronTrack01CddaStream);
    m11_nexus_release_title(state);
    {
        Theron_V1_BootProfile *theronProfile =
            (Theron_V1_BootProfile*)state->theronBootProfile;
        Theron_V1_World *theronWorld =
            (Theron_V1_World*)state->theronWorld;
        Theron_V1_Viewport *theronViewport =
            (Theron_V1_Viewport*)state->theronViewport;
        TrAssetBundle *theronAssets =
            (TrAssetBundle*)state->theronAssets;
        theron_v1_boot_runtime_release(&theronProfile,
                                       &theronWorld,
                                       &theronViewport,
                                       &theronAssets);
        state->theronBootProfile = theronProfile;
        state->theronWorld = theronWorld;
        state->theronViewport = theronViewport;
        state->theronAssets = theronAssets;
    }
    m11_v22_inplace_draw_shutdown();
    csb_v22_inplace_draw_shutdown();
    if (state->csbStartupRuntimeAssetSession) {
        csb_v1_boot_startup_runtime_asset_session_release_pc34(
            (CSB_V1_StartupRuntimeAssetSession_PC34 *)
                state->csbStartupRuntimeAssetSession);
        free(state->csbStartupRuntimeAssetSession);
        state->csbStartupRuntimeAssetSession = NULL;
    }
    m11_csb_release_fmtowns_title(state);
    m11_csb_release_fmtowns_switch(state);
    free(state->csbViewportFloorPixels);
    free(state->csbViewportCeilingPixels);
    state->csbViewportFloorPixels = NULL;
    state->csbViewportCeilingPixels = NULL;
    for (size_t i = 0; i < 15u; ++i) {
        free(state->csbViewportWallPixels[i]);
        state->csbViewportWallPixels[i] = NULL;
        state->csbViewportWallWidths[i] = 0;
        state->csbViewportWallHeights[i] = 0;
    }
    if (state->csbBootProfile) {
        csb_v1_boot_cleanup((CSB_V1_BootProfile*)state->csbBootProfile);
        free(state->csbBootProfile);
        state->csbBootProfile = NULL;
    }
    if (state->dm2BootProfile) {
        dm2_v1_boot_cleanup((DM2_V1_BootProfile*)state->dm2BootProfile);
        free(state->dm2BootProfile);
        state->dm2BootProfile = NULL;
        state->dm2World = NULL;
    }
    if (state->nexusLightRuntimeReady || state->nexusLightRuntime.initialized) {
        nexus_v1_light_runtime_shutdown(&state->nexusLightRuntime);
        state->nexusLightRuntimeReady = 0;
    }
    nexus_v2_hud_runtime_shutdown();
    nexus_v2_lighting_runtime_shutdown();
    nexus_v2_smooth_movement_runtime_shutdown();
    nexus_v2_touch_runtime_shutdown();
    if (state->assetsAvailable) {
        M11_AssetLoader_Shutdown(&state->assetLoader);
        state->assetsAvailable = 0;
    }
    if (state->active) {
        F0883_WORLD_Free_Compat(&state->world);
    }
    M11_Audio_Shutdown(&state->audioState);
    memset(state, 0, sizeof(*state));
}

static void m11_nexus_release_title(M11_GameViewState* state) {
    Nexus_TitleScreen* title;
    if (!state || !state->nexusTitleScreen) {
        return;
    }
    title = (Nexus_TitleScreen*)state->nexusTitleScreen;
    nexus_title_free(title);
    free(title);
    state->nexusTitleScreen = NULL;
    state->nexusState.title_active = 0;
    state->nexusState.title_loaded = 0;
    state->nexusState.title_frame = 0;
    state->nexusState.champion_select_active = 0;
    state->nexusState.champion_cursor = 0;
    state->nexusState.champion_select_frame = 0;
}

static void m11_nexus_startup_snapshot_to_state(
    M11_GameViewState *state,
    const Nexus_V1_StartupMenuStateReceipt *receipt);
static int m11_nexus_startup_load_save_callback(
    void *userdata,
    const char *save_path);

static void m11_nexus_runtime_startup_snapshot(
    const M11_GameViewState *state,
    Nexus_V1_LauncherRuntimeStartupSnapshot *snapshot)
{
    if (!snapshot) {
        return;
    }
    nexus_v1_launcher_runtime_startup_snapshot_clear(snapshot);
    if (!state) {
        return;
    }
    snapshot->runtime.title_active = state->nexusState.title_active;
    snapshot->runtime.title_frame = state->nexusState.title_frame;
    snapshot->runtime.save_select_active = state->nexusState.startup_save_select_active;
    snapshot->runtime.champion_select_active = state->nexusState.champion_select_active;
    snapshot->runtime.save_dir = state->nexusState.startup_save_dir;
    snapshot->runtime.slot_mask = state->nexusState.startup_save_slot_mask;
    snapshot->runtime.save_selected_row = state->nexusState.startup_save_selected_row;
    snapshot->runtime.save_row_count = state->nexusState.startup_save_row_count;
    snapshot->runtime.engine = state->nexusEngine;
    snapshot->runtime.champion_cursor = state->nexusState.champion_cursor;
    snapshot->runtime.champion_frame = state->nexusState.champion_select_frame;
}

static int m11_nexus_runtime_receipt_from_state(
    const M11_GameViewState *state,
    Nexus_V1_LauncherRuntimeReceipt *receipt)
{
    Nexus_V1_LauncherRuntimeStartupSnapshot snapshot;
    Nexus_V1_StartupHostFacts host_facts;

    if (!receipt) {
        return 0;
    }
    memset(receipt, 0, sizeof(*receipt));
    if (!state || !state->nexusEngine) {
        return 0;
    }
    m11_nexus_runtime_startup_snapshot(state, &snapshot);
    receipt->engine = state->nexusEngine;
    receipt->title_screen =
        (Nexus_TitleScreen*)state->nexusTitleScreen;
    receipt->title_screen_keep = 1;
    receipt->level_loaded = state->nexusState.level_loaded;
    receipt->party_x = state->nexusState.party_x;
    receipt->party_y = state->nexusState.party_y;
    receipt->party_dir = state->nexusState.party_dir;
    receipt->tick_count = state->nexusState.tick_count;
    receipt->title_loaded = state->nexusState.title_loaded;
    snprintf(receipt->title, sizeof(receipt->title), "%s", state->title);
    snprintf(receipt->source_id,
             sizeof(receipt->source_id),
             "%s",
             state->sourceId);
    snprintf(receipt->dungeon_path,
             sizeof(receipt->dungeon_path),
             "%s",
             state->dungeonPath);
    (void)nexus_v1_launcher_startup_assets_receipt_from_snapshot(
        &snapshot,
        &receipt->startup_assets);
    memset(&host_facts, 0, sizeof(host_facts));
    if (nexus_v1_launcher_startup_host_facts_from_snapshot(&snapshot,
                                                           &host_facts)) {
        (void)nexus_v1_startup_launch_from_host_facts_with_receipt(
            &host_facts,
            &receipt->startup_receipt);
    }
    return 1;
}

