int M11_GameView_GetDm1HocMenuRouteReceipt(
    const M11_GameViewState* state,
    DM1_V1_EntranceMenuRouteReceiptPc34* outReceipt) {
    DM1_V1_EntranceCtxPc34 ctx;
    int mirrorOrdinal;
    int slotIndex;

    if (!state || !outReceipt) {
        return 0;
    }

    DM1_V1_Entrance_InitPc34Compat(&ctx);
    ctx.partyChampionCount = state->world.party.championCount;
    ctx.state = DM1_ENTRANCE_VIEWING;

    if (state->candidateMirrorPanelActive) {
        mirrorOrdinal = state->candidateMirrorOrdinal >= 0
                            ? state->candidateMirrorOrdinal
                            : m11_front_cell_mirror_ordinal(state);
        if (mirrorOrdinal < 0) {
            mirrorOrdinal = 0;
        }
        slotIndex = DM1_V1_Entrance_AddMirrorPc34Compat(
            &ctx, mirrorOrdinal, state->world.party.mapX,
            state->world.party.mapY, state->world.party.direction, 0);
        if (slotIndex < 0) {
            return 0;
        }
        ctx.selectedMirrorIndex = slotIndex;
        ctx.state = DM1_ENTRANCE_SELECTING;
    }

    /* ReDMCSB ENTRANCE.C F0441 lines 850-883 keeps entrance drawing/input
     * in the entrance loop, and REVIVE.C F0280 lines 127-130/272 rejects
     * party overflow before publishing G0299_ui_CandidateChampionOrdinal.
     * This adapter lets M11/M12 consume the DM1-owned HoC route receipt
     * instead of branching directly on candidateMirrorPanelActive. */
    return DM1_V1_Entrance_BuildMenuRouteReceiptPc34Compat(&ctx, outReceipt);
}

static int m11_dm1_hoc_menu_route_blocks_normal_input(
    const M11_GameViewState* state) {
    DM1_V1_EntranceMenuRouteReceiptPc34 receipt;
    if (!M11_GameView_GetDm1HocMenuRouteReceipt(state, &receipt)) {
        return 0;
    }
    return (receipt.showChampionPanel ||
            receipt.showResurrectReincarnateChoices) ? 1 : 0;
}

/* ReDMCSB PANEL.C F0346:1619-1637 installs M568 by blitting original
 * C040 before COMMAND.C can dispatch C160/C161/C162.  The M11 host route
 * must not accept an invisible substitute panel.  This deliberately gates
 * only SDL/host input; the M10 candidate APIs remain data-model operations
 * for source-locked save/runtime tests. */
static int m11_dm1_hoc_c040_input_material_ready(
    const M11_GameViewState* state)
{
    const M11_AssetSlot* backdrop;
    const M11_AssetSlot* panel;
    DM1_V1_LayoutZoneRectPc34 panelRect;

    if (!state || !state->candidateMirrorPanelActive ||
        state->candidateMirrorRenameActive) {
        return 0;
    }
    /* The panel is safe to receive C160/C161/C162 when its two original
     * source bitmaps are resident.  `assetsAvailable` is a broad launcher
     * readiness latch and can remain clear while M11 has already rendered
     * C017/C040 from the live GRAPHICS.DAT loader. */
    panelRect = dm1_v1_inventory_panel_rect_pc34();
    if (!dm1_v1_inventory_panel_zone_id_pc34()) {
        return 0;
    }
    /* ReDMCSB PANEL.C F0347 installs C017 as the inventory view before
     * F0346 overlays C040 at C101.  C040 alone is not a complete visible
     * command surface, so host C160/C161/C162 must not mutate the candidate
     * while the original backdrop is unavailable. */
    backdrop = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader,
                                    (unsigned int)
                                        dm1_v1_graphic_inventory_backdrop_pc34());
    if (!backdrop || !backdrop->loaded || !backdrop->pixels ||
        backdrop->width != M11_VIEWPORT_W ||
        backdrop->height != M11_VIEWPORT_H) {
        return 0;
    }
    panel = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader, 40);
    return panel && panel->loaded && panel->pixels &&
           panel->width == panelRect.w &&
           panel->height == panelRect.h;
}

static int m11_dm1_hoc_c027_input_material_ready(
    const M11_GameViewState* state)
{
    const M11_AssetSlot* panel;
    DM1_V1_LayoutZoneRectPc34 panelRect;

    if (!state || !state->candidateMirrorPanelActive ||
        !state->originalFontAvailable) {
        return 0;
    }
    panelRect = dm1_v1_inventory_panel_rect_pc34();
    if (!dm1_v1_inventory_panel_zone_id_pc34()) {
        return 0;
    }
    panel = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader, 27);
    return panel && panel->loaded && panel->pixels &&
           panel->width == panelRect.w &&
           panel->height == panelRect.h;
}

/* ReDMCSB REVIVE.C F0282 lines 805-817 walks the front square after a
 * successful C160/C161 choice and disables the first SENSOR it encounters.
 * It deliberately does not re-check C127/sensorData: BUG0_87 documents that
 * this can affect a preceding custom-dungeon sensor.  Keep that original
 * ownership, rather than repairing it with an M11 mirror/TextString scan. */
static int m11_front_mirror_first_sensor_index_pc34(
    const M11_GameViewState* state,
    int* outSensorIndex) {
    int mapX;
    int mapY;
    int sftIndex;
    unsigned short thing;
    int maxLinks = 0;
    int safety;
    int type;

    if (!state || !outSensorIndex || !state->world.dungeon ||
        !state->world.things || !state->world.things->squareFirstThings ||
        !state->world.things->sensors ||
        state->world.things->sensorCount <= 0) {
        return 0;
    }

    mapX = state->world.party.mapX;
    mapY = state->world.party.mapY;
    switch (state->world.party.direction & 3) {
        case DIR_NORTH: mapY -= 1; break;
        case DIR_EAST:  mapX += 1; break;
        case DIR_SOUTH: mapY += 1; break;
        default:        mapX -= 1; break;
    }
    sftIndex = F0510_DUNGEON_GetSquareFirstThingIndex_Compat(
        state->world.dungeon, state->world.party.mapIndex, mapX, mapY);
    if (sftIndex < 0 ||
        sftIndex >= state->world.things->squareFirstThingCount) {
        return 0;
    }
    thing = state->world.things->squareFirstThings[sftIndex];
    for (type = 0; type < DUNGEON_THING_TYPE_COUNT; ++type) {
        if (state->world.things->thingCounts[type] > 0) {
            maxLinks += state->world.things->thingCounts[type];
        }
    }
    if (maxLinks <= 0) {
        return 0;
    }
    for (safety = 0;
         safety < maxLinks &&
         thing != THING_ENDOFLIST && thing != THING_NONE;
         ++safety) {
        int thingType = THING_GET_TYPE(thing);
        int thingIndex = THING_GET_INDEX(thing);
        unsigned short next = m11_raw_next_thing(state->world.things, thing);
        if (thingType == THING_TYPE_SENSOR && state->world.things->sensors &&
            thingIndex >= 0 && thingIndex < state->world.things->sensorCount) {
            *outSensorIndex = thingIndex;
            return 1;
        }
        thing = next;
    }
    return 0;
}

/* Build the complete F0282 confirmation -> apply plan from the exact F0280
 * selection receipt.  This is deliberately a pre-mutation gate: a stale
 * C127/C026/C040 source leaves the live party and panel untouched. */
static int m11_dm1_hoc_prepare_confirmation_apply(
    const M11_GameViewState* state,
    int command,
    int renameAccepted,
    int firstSensorIndex,
    DM1_V1_HocCandidateConfirmationReceiptPc34* outConfirmation,
    DM1_V1_HocCandidateApplyReceiptPc34* outApply)
{
    DM1_V1_HocCandidateConfirmationInputPc34 confirmationInput;
    DM1_V1_HocCandidateConfirmationApplyBridgeInputPc34 bridgeInput;
    DM1_V1_HocCandidateConfirmationApplyBridgeReceiptPc34 bridge;
    const M11_AssetSlot* portraits;
    const M11_AssetSlot* c040Panel;
    DM1_V1_LayoutZoneRectPc34 panelRect;

    if (!state || !outConfirmation || !outApply ||
        !s_m11_dm1_hoc_candidate_receipts.valid ||
        s_m11_dm1_hoc_candidate_receipts.owner != state ||
        state->candidateMirrorOrdinal < 0 ||
        state->candidateMirrorPartyIndex < 0 ||
        state->candidateMirrorPartyIndex >= state->world.party.championCount ||
        s_m11_dm1_hoc_candidate_receipts.selection
                .nextPartyChampionCount !=
            (uint16_t)state->world.party.championCount ||
        s_m11_dm1_hoc_candidate_receipts.selection
                .nextCandidateChampionOrdinal !=
            (uint16_t)(state->candidateMirrorPartyIndex + 1) ||
        s_m11_dm1_hoc_candidate_receipts.selection
                .nextActiveMirrorOrdinal !=
            (uint16_t)state->candidateMirrorOrdinal) {
        return 0;
    }

    portraits = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader, 26u);
    c040Panel = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader, 40u);
    panelRect = dm1_v1_inventory_panel_rect_pc34();
    if (!portraits || !portraits->loaded || !portraits->pixels ||
        portraits->width < CHAMPION_PORTRAIT_BITMAP_WIDTH * 8 ||
        portraits->height < CHAMPION_PORTRAIT_BITMAP_HEIGHT * 3 ||
        !c040Panel || !c040Panel->loaded || !c040Panel->pixels ||
        c040Panel->width != panelRect.w || c040Panel->height != panelRect.h) {
        return 0;
    }

    memset(&confirmationInput, 0, sizeof(confirmationInput));
    confirmationInput.selection = &s_m11_dm1_hoc_candidate_receipts.selection;
    confirmationInput.state.partyChampionCount =
        (uint16_t)state->world.party.championCount;
    confirmationInput.state.candidateChampionOrdinal =
        (uint16_t)(state->candidateMirrorPartyIndex + 1);
    confirmationInput.state.activeMirrorOrdinal =
        (uint16_t)state->candidateMirrorOrdinal;
    confirmationInput.state.activeMirrorSourceBound = 1;
    confirmationInput.state.c040PanelOpen = state->candidateMirrorPanelActive;
    confirmationInput.state.c127SensorEnabled = 1;
    confirmationInput.state.c127SensorOrdinal =
        (uint16_t)state->candidateMirrorOrdinal;
    confirmationInput.state.c026PortraitAtlasAvailable = 1;
    confirmationInput.state.c040PanelGraphicAvailable = 1;
    confirmationInput.state.sensorGeneration =
        s_m11_dm1_hoc_candidate_receipts.sensorGeneration;
    confirmationInput.state.panelGeneration =
        s_m11_dm1_hoc_candidate_receipts.panelGeneration;
    confirmationInput.command = (int16_t)command;
    confirmationInput.renameAccepted = renameAccepted;
    memset(outConfirmation, 0, sizeof(*outConfirmation));
    if (!DM1_V1_HocCandidateConfirmation_BuildReceiptPc34(
            &confirmationInput, outConfirmation) || !outConfirmation->valid ||
        !outConfirmation->sourceOwned || !outConfirmation->commitReady ||
        outConfirmation->awaitsRename) {
        return 0;
    }

    memset(&bridgeInput, 0, sizeof(bridgeInput));
    bridgeInput.confirmation = outConfirmation;
    bridgeInput.state.partyChampionCount = confirmationInput.state.partyChampionCount;
    bridgeInput.state.candidateChampionOrdinal =
        confirmationInput.state.candidateChampionOrdinal;
    bridgeInput.state.activeMirrorOrdinal = confirmationInput.state.activeMirrorOrdinal;
    bridgeInput.state.activeMirrorSourceBound = 1;
    bridgeInput.state.c040PanelOpen = 1;
    bridgeInput.state.c127SensorEnabled = 1;
    bridgeInput.state.c127SensorOrdinal = confirmationInput.state.c127SensorOrdinal;
    bridgeInput.state.c026PortraitAtlasAvailable = 1;
    bridgeInput.state.c040PanelGraphicAvailable = 1;
    bridgeInput.state.firstMirrorSensorOwnerAvailable = firstSensorIndex >= 0;
    bridgeInput.state.sensorGeneration = confirmationInput.state.sensorGeneration;
    bridgeInput.state.panelGeneration = confirmationInput.state.panelGeneration;
    memset(&bridge, 0, sizeof(bridge));
    if (!DM1_V1_HocCandidateConfirmationApplyBridge_BuildReceiptPc34(
            &bridgeInput, &bridge) || !bridge.valid || !bridge.sourceOwned ||
        !bridge.atomic ||
        !DM1_V1_HocCandidateApply_BuildReceiptPc34(
            &(DM1_V1_HocCandidateApplyInputPc34){
                &bridge.handoff, bridge.applyState }, outApply) ||
        !outApply->valid || !outApply->sourceOwned || !outApply->atomic ||
        outApply->nextPartyChampionCount !=
            outConfirmation->nextPartyChampionCount) {
        return 0;
    }
    return 1;
}

static int m11_dm1_hoc_publish_presentation_receipt(
    const M11_GameViewState* state,
    const DM1_V1_HocCandidateApplyReceiptPc34* apply,
    const DM1_V1_HocCandidateConfirmationReceiptPc34* confirmation)
{
    DM1_V1_HocCandidatePresentationInputPc34 input;
    DM1_V1_HocCandidatePresentationReceiptPc34 receipt;
    const M11_AssetSlot* portraits;
    const M11_AssetSlot* c040Panel;
    DM1_V1_LayoutZoneRectPc34 panelRect;

    if (!state || !apply || !confirmation ||
        s_m11_dm1_hoc_candidate_receipts.owner != state) {
        return 0;
    }
    portraits = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader, 26u);
    c040Panel = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader, 40u);
    panelRect = dm1_v1_inventory_panel_rect_pc34();
    memset(&input, 0, sizeof(input));
    input.apply = apply;
    input.state.partyChampionCount = (uint16_t)state->world.party.championCount;
    input.state.candidateChampionOrdinal = 0;
    input.state.mirrorOrdinal = confirmation->mirrorOrdinal;
    input.state.mirrorSourceBound = 1;
    input.state.c040PanelOpen = state->candidateMirrorPanelActive;
    input.state.c127SensorEnabled = apply->nextMirrorSensorEnabled;
    input.state.c026PortraitAtlasAvailable =
        portraits && portraits->loaded && portraits->pixels;
    input.state.c040PanelGraphicAvailable =
        c040Panel && c040Panel->loaded && c040Panel->pixels &&
        c040Panel->width == panelRect.w && c040Panel->height == panelRect.h;
    input.state.previousSensorGeneration =
        s_m11_dm1_hoc_candidate_receipts.sensorGeneration;
    input.state.sensorGeneration = confirmation->expectedSensorGeneration;
    input.state.presentedPanelGeneration = apply->nextPresentedPanelGeneration;
    memset(&receipt, 0, sizeof(receipt));
    if (!DM1_V1_HocCandidatePresentation_BuildReceiptPc34(&input, &receipt) ||
        !receipt.valid || !receipt.sourceOwned) {
        return 0;
    }
    s_m11_dm1_hoc_candidate_receipts.pendingPresentation = receipt;
    s_m11_dm1_hoc_candidate_receipts.sensorGeneration = receipt.sensorGeneration;
    s_m11_dm1_hoc_candidate_receipts.panelGeneration =
        receipt.presentedPanelGeneration;
    s_m11_dm1_hoc_candidate_receipts.valid = 0;
    return 1;
}

/* The draw loop consumes a presentation receipt exactly once before F0128
 * repaints the viewport.  It never manufactures C026/C040 pixels. */
static void m11_dm1_hoc_consume_presentation_receipt(
    const M11_GameViewState* state)
{
    DM1_V1_HocCandidatePresentationReceiptPc34* receipt =
        &s_m11_dm1_hoc_candidate_receipts.pendingPresentation;

    if (!receipt->valid) {
        return;
    }
    if (!state || s_m11_dm1_hoc_candidate_receipts.owner != state ||
        !receipt->sourceOwned ||
        receipt->sensorGeneration != s_m11_dm1_hoc_candidate_receipts.sensorGeneration ||
        receipt->presentedPanelGeneration !=
            s_m11_dm1_hoc_candidate_receipts.panelGeneration) {
        memset(receipt, 0, sizeof(*receipt));
        return;
    }
    /* The full M11 frame starts black and F0128 redraws only live source
     * surfaces.  Consuming this receipt therefore retires C040 without a
     * host replacement; C162's C026 is admitted only by its live C127 path. */
    memset(receipt, 0, sizeof(*receipt));
}

static uint32_t m11_dm1_hoc_source_hash(const unsigned char* pixels,
                                        int width,
                                        int height)
{
    uint32_t hash = 2166136261u;
    size_t count;
    size_t i;

    if (!pixels || width <= 0 || height <= 0) {
        return 0u;
    }
    count = (size_t)width * (size_t)height;
    for (i = 0u; i < count; ++i) {
        hash ^= pixels[i];
        hash *= 16777619u;
    }
    return hash ? hash : 1u;
}

static void m11_dm1_hoc_presented_frame_consumer_build(
    const M11_GameViewState* state)
{
    DM1_V1_HocPresentedMirrorMaterialPc34 mirrorMat;
    DM1_V1_HocPresentedInscriptionMaterialPc34 inscriptionMat;
    DM1_V1_HocPresentedObjectMaterialPc34 objectMat;
    DM1_V1_HocPresentedActionSpellMaterialPc34 actionSpellMat;
    DM1_V1_HocPresentedPaletteMaterialPc34 paletteMat;
    DM1_V1_HocPresentedViewportCoverageMaterialPc34 viewportCoverageMat;
    DM1_V1_HocPresentedFrameConsumerInputPc34 input;
    const M11_Dm1HoCMirrorHostPresentationReceipt* mirror;
    const M11_Dm1InscriptionHostPresentationReceipt* inscription;
    const M11_Dm1FloorItemHostPresentationReceipt* floorItem;

    memset(&s_m11_dm1_hoc_presented_frame_consumer_receipt, 0,
           sizeof(s_m11_dm1_hoc_presented_frame_consumer_receipt));
    if (!state || !m11_is_dm1_source_kind(state->sourceKind))
        return;

    mirror = &s_m11_dm1_hoc_mirror_host_presentation_receipt;
    inscription = &s_m11_dm1_inscription_host_presentation_receipt;
    floorItem = &s_m11_dm1_floor_item_host_presentation_receipt;

    memset(&mirrorMat, 0, sizeof(mirrorMat));
    if (mirror->valid) {
        mirrorMat.valid = 1;
        mirrorMat.backingGraphicIndex = mirror->backingGraphicIndex;
        mirrorMat.portraitGraphicIndex = mirror->portraitGraphicIndex;
        mirrorMat.backingWidth = mirror->backingWidth;
        mirrorMat.backingHeight = mirror->backingHeight;
        mirrorMat.portraitWidth = mirror->portraitWidth;
        mirrorMat.portraitHeight = mirror->portraitHeight;
        mirrorMat.backingTransparentColor = mirror->backingTransparentColor;
        mirrorMat.portraitTransparentColor = mirror->portraitTransparentColor;
        mirrorMat.backingHash = m11_dm1_hoc_source_hash(NULL, 0, 0);
        mirrorMat.portraitHash = m11_dm1_hoc_source_hash(NULL, 0, 0);
        {
            const M11_AssetSlot* backing = M11_AssetLoader_Load(
                (M11_AssetLoader*)&state->assetLoader,
                (unsigned int)mirror->backingGraphicIndex);
            const M11_AssetSlot* portraits = M11_AssetLoader_Load(
                (M11_AssetLoader*)&state->assetLoader,
                (unsigned int)mirror->portraitGraphicIndex);
            if (backing && backing->loaded && backing->pixels)
                mirrorMat.backingHash = m11_dm1_hoc_source_hash(
                    backing->pixels, (int)backing->width, (int)backing->height);
            if (portraits && portraits->loaded && portraits->pixels)
                mirrorMat.portraitHash = m11_dm1_hoc_source_hash(
                    portraits->pixels, (int)portraits->width,
                    (int)portraits->height);
        }
    }

    memset(&inscriptionMat, 0, sizeof(inscriptionMat));
    if (inscription->valid) {
        inscriptionMat.valid = 1;
        inscriptionMat.fontGraphicIndex = inscription->fontGraphicIndex;
        inscriptionMat.glyphByteCount = inscription->glyphByteCount;
        inscriptionMat.lineCount = inscription->lineCount;
        inscriptionMat.glyphSourceWidth = inscription->glyphSourceWidth;
        inscriptionMat.glyphSourceHeight = inscription->glyphSourceHeight;
        inscriptionMat.glyphCellCount = inscription->glyphCellCount;
        inscriptionMat.opaqueGlyphPixelCount = inscription->opaqueGlyphPixelCount;
        inscriptionMat.transparentGlyphPixelCount =
            inscription->transparentGlyphPixelCount;
        inscriptionMat.textDataHash = inscription->textDataFNV1a;
        inscriptionMat.glyphBytesHash = inscription->glyphBytesFNV1a;
        inscriptionMat.fontPixelsHash = inscription->fontPixelsFNV1a;
        inscriptionMat.sourceCellsHash = inscription->sourceCellsFNV1a;
    }

    memset(&objectMat, 0, sizeof(objectMat));
    if (floorItem->valid && floorItem->floorItemLane) {
        objectMat.valid = 1;
        objectMat.graphicsId = floorItem->graphicsId;
        objectMat.transparentColor = floorItem->transparentColor;
        objectMat.sourceZone = floorItem->sourceZone;
        objectMat.destinationW = floorItem->destinationW;
        objectMat.destinationH = floorItem->destinationH;
        objectMat.assetWidth = floorItem->assetWidth;
        objectMat.assetHeight = floorItem->assetHeight;
        objectMat.materialHash = m11_dm1_hoc_source_hash(NULL, 0, 0);
        if (floorItem->graphicsId > 0) {
            const M11_AssetSlot* objSlot = M11_AssetLoader_Load(
                (M11_AssetLoader*)&state->assetLoader,
                (unsigned int)floorItem->graphicsId);
            if (objSlot && objSlot->loaded && objSlot->pixels)
                objectMat.materialHash = m11_dm1_hoc_source_hash(
                    objSlot->pixels, (int)objSlot->width,
                    (int)objSlot->height);
        }
    }

    memset(&actionSpellMat, 0, sizeof(actionSpellMat));
    if (s_m11_dm1_action_spell_last_presentation.valid) {
        const DM1_V1_ActionSpellHudPresentationReceiptPc34 *asp =
            &s_m11_dm1_action_spell_last_presentation;
        actionSpellMat.valid = 1;
        actionSpellMat.primaryGraphicId = asp->requiredPrimaryGraphicId;
        actionSpellMat.secondaryGraphicId = asp->requiredSecondaryGraphicId;
        actionSpellMat.primaryZoneId = asp->requiredPrimaryZoneId;
        actionSpellMat.secondaryZoneId = asp->requiredSecondaryZoneId;
        actionSpellMat.fontGraphicId = asp->requiredFontGraphicId;
        actionSpellMat.requiresRealActionMenuLayout = asp->requiresRealActionMenuLayout;
        actionSpellMat.requiresRealSpellAreaLayout = asp->requiresRealSpellAreaLayout;
        actionSpellMat.suppressSyntheticFallback = asp->suppressSyntheticFallback;
        actionSpellMat.sourceTick = asp->sourceTick;
        actionSpellMat.serial = asp->serial;
    }

    memset(&paletteMat, 0, sizeof(paletteMat));
    {
        uint32_t ph = 2166136261u;
        int pi;
        for (pi = 0; pi < 16; pi++) {
            ph ^= G9010_auc_VgaPaletteBrightest_Compat[pi][0];
            ph *= 16777619u;
            ph ^= G9010_auc_VgaPaletteBrightest_Compat[pi][1];
            ph *= 16777619u;
            ph ^= G9010_auc_VgaPaletteBrightest_Compat[pi][2];
            ph *= 16777619u;
        }
        paletteMat.valid = 1;
        paletteMat.entryCount = 16;
        paletteMat.paletteHash = ph;
    }

    memset(&viewportCoverageMat, 0, sizeof(viewportCoverageMat));
    {
        const M11_Dm1HoCMirrorViewportMaterialFrameReceipt *vpFrame =
            &s_m11_dm1_hoc_mirror_viewport_material_frame_receipt;
        if (vpFrame->count > 0) {
            uint32_t vcHash = 2166136261u;
            int vi;
            int matCount = 0;
            for (vi = 0; vi < vpFrame->count; vi++) {
                const M11_Dm1HoCMirrorViewportMaterialReceipt *e =
                    &vpFrame->entries[vi];
                if (e->valid && e->materialized) matCount++;
                vcHash ^= (uint32_t)e->viewWallIndex;
                vcHash *= 16777619u;
                vcHash ^= (uint32_t)e->backingGraphicIndex;
                vcHash *= 16777619u;
                vcHash ^= (uint32_t)e->materialized;
                vcHash *= 16777619u;
            }
            viewportCoverageMat.valid = 1;
            viewportCoverageMat.mirrorSquareCount = vpFrame->count;
            viewportCoverageMat.materializedCount = matCount;
            viewportCoverageMat.allMaterialized =
                (matCount == vpFrame->count) ? 1 : 0;
            viewportCoverageMat.coverageHash = vcHash;
        }
    }

    memset(&input, 0, sizeof(input));
    input.runtimeTick = (uint32_t)state->world.gameTick;
    input.mirror = mirrorMat.valid ? &mirrorMat : NULL;
    input.inscription = inscriptionMat.valid ? &inscriptionMat : NULL;
    input.object = objectMat.valid ? &objectMat : NULL;
    input.actionSpell = actionSpellMat.valid ? &actionSpellMat : NULL;
    input.palette = paletteMat.valid ? &paletteMat : NULL;
    input.viewportCoverage =
        viewportCoverageMat.valid ? &viewportCoverageMat : NULL;
    dm1_v1_hoc_presented_frame_consumer_build_receipt_pc34(
        &input, &s_m11_dm1_hoc_presented_frame_consumer_receipt);
}

/* The C040 candidate panel and C026 atlas must arrive at the actual M11
 * render boundary as one source-owned frame.  Keep the adapter narrow: it
 * binds only resident GRAPHICS.DAT material already selected by the C127
 * candidate route, then lets the DM1 admission module validate the tick and
 * generations. */
static int m11_dm1_hoc_publish_runtime_frame_admission(
    const M11_GameViewState* state)
{
    const M11_AssetSlot* panel;
    const M11_AssetSlot* portraits;
    DM1_V1_LayoutZoneRectPc34 panelRect;
    DM1_V1_ObjectIconSourceZonePc34 portraitZone;
    DM1_V1_HocCandidatePreM11LifecycleBridgeReceiptPc34 preM11Bridge;
    DM1_V1_HocCandidatePreM11HostRenderReceiptPc34 hostRender;
    DM1_V1_HocCandidateRuntimeFrameAdmissionInputPc34 input;
    DM1_V1_HocCandidateRuntimeFrameAdmissionReceiptPc34 admission;
    uint64_t tick;

    memset(&s_m11_dm1_hoc_runtime_frame_admission, 0,
           sizeof(s_m11_dm1_hoc_runtime_frame_admission));
    if (!state || !state->candidateMirrorPanelActive ||
        state->candidateMirrorRenameActive ||
        s_m11_dm1_hoc_candidate_receipts.owner != state ||
        state->candidateMirrorOrdinal < 0 ||
        !dm1_v1_inventory_panel_zone_id_pc34()) {
        return 0;
    }
    panelRect = dm1_v1_inventory_panel_rect_pc34();
    panel = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader, 40u);
    portraits = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader,
                                     26u);
    if (!panel || !panel->loaded || !panel->pixels ||
        panel->width != panelRect.w || panel->height != panelRect.h ||
        !portraits || !portraits->loaded || !portraits->pixels ||
        !dm1_v1_graphic_validate_champion_portrait_atlas_pc34(
            (int)portraits->width, (int)portraits->height) ||
        !dm1_v1_graphic_champion_portrait_source_zone_pc34(
            state->candidateMirrorOrdinal, &portraitZone)) {
        return 0;
    }
    tick = (uint64_t)state->world.gameTick;
    memset(&preM11Bridge, 0, sizeof(preM11Bridge));
    memset(&hostRender, 0, sizeof(hostRender));
    preM11Bridge.valid = 1;
    preM11Bridge.sourceOwned = 1;
    preM11Bridge.admitToM11 = 1;
    preM11Bridge.mirrorOrdinal = (uint16_t)state->candidateMirrorOrdinal;
    preM11Bridge.sensorGeneration =
        s_m11_dm1_hoc_candidate_receipts.sensorGeneration;
    preM11Bridge.presentedPanelGeneration =
        s_m11_dm1_hoc_candidate_receipts.panelGeneration;
    preM11Bridge.hostTick = tick;
    preM11Bridge.c040SourceHash =
        m11_dm1_hoc_source_hash(panel->pixels, panel->width, panel->height);
    preM11Bridge.c026SourceHash =
        m11_dm1_hoc_source_hash(portraits->pixels, portraits->width,
                                portraits->height);
    if (preM11Bridge.c040SourceHash == 0u ||
        preM11Bridge.c026SourceHash == 0u) {
        return 0;
    }
    hostRender.valid = 1;
    hostRender.sourceOwned = 1;
    hostRender.renderAtM11Boundary = 1;
    hostRender.commandCount = 2;
    hostRender.mirrorOrdinal = preM11Bridge.mirrorOrdinal;
    hostRender.sensorGeneration = preM11Bridge.sensorGeneration;
    hostRender.presentedPanelGeneration =
        preM11Bridge.presentedPanelGeneration;
    hostRender.hostTick = tick;
    hostRender.c040SourceHash = preM11Bridge.c040SourceHash;
    hostRender.c026SourceHash = preM11Bridge.c026SourceHash;
    hostRender.commands[0].kind =
        DM1_V1_HOC_CANDIDATE_RENDER_CLEAR_C040_PC34;
    hostRender.commands[0].material.sourceOwned = 1;
    hostRender.commands[0].material.graphicIndex = 40;
    hostRender.commands[0].material.width = panelRect.w;
    hostRender.commands[0].material.height = panelRect.h;
    hostRender.commands[0].material.dstLeft = panelRect.x;
    hostRender.commands[0].material.dstTop = panelRect.y;
    hostRender.commands[0].material.sourceHash = preM11Bridge.c040SourceHash;
    hostRender.commands[1].kind =
        DM1_V1_HOC_CANDIDATE_RENDER_DRAW_C026_PC34;
    hostRender.commands[1].material.sourceOwned = 1;
    hostRender.commands[1].material.graphicIndex = 26;
    hostRender.commands[1].material.sourceX = portraitZone.x;
    hostRender.commands[1].material.sourceY = portraitZone.y;
    hostRender.commands[1].material.width = portraitZone.w;
    hostRender.commands[1].material.height = portraitZone.h;
    hostRender.commands[1].material.dstLeft = 96;
    hostRender.commands[1].material.dstTop = 35;
    hostRender.commands[1].material.sourceHash = preM11Bridge.c026SourceHash;
    memset(&input, 0, sizeof(input));
    input.preM11Bridge = &preM11Bridge;
    input.hostRender = &hostRender;
    input.runtimeTick = tick;
    memset(&admission, 0, sizeof(admission));
    if (!DM1_V1_HocCandidateRuntimeFrameAdmission_BuildReceiptPc34(
            &input, &admission) || !admission.valid ||
        !admission.sourceOwned || !admission.admitRuntimeFrame) {
        return 0;
    }
    s_m11_dm1_hoc_runtime_frame_admission.owner = state;
    s_m11_dm1_hoc_runtime_frame_admission.required = 1;
    s_m11_dm1_hoc_runtime_frame_admission.admission = admission;
    return 1;
}

static int m11_dm1_hoc_runtime_frame_admission_current(
    const M11_GameViewState* state,
    DM1_V1_HocCandidateRuntimeFrameAdmissionReceiptPc34* outAdmission)
{
    const M11_Dm1HocRuntimeFrameAdmissionRuntime* runtime =
        &s_m11_dm1_hoc_runtime_frame_admission;

    if (!state || !state->candidateMirrorPanelActive ||
        state->candidateMirrorRenameActive) {
        return 1;
    }
    if (runtime->owner != state || !runtime->required ||
        !runtime->admission.valid || !runtime->admission.sourceOwned ||
        !runtime->admission.admitRuntimeFrame ||
        runtime->admission.commandCount != 2 ||
        runtime->admission.runtimeTick != (uint64_t)state->world.gameTick ||
        runtime->admission.mirrorOrdinal !=
            (uint16_t)state->candidateMirrorOrdinal ||
        runtime->admission.sensorGeneration !=
            s_m11_dm1_hoc_candidate_receipts.sensorGeneration ||
        runtime->admission.presentedPanelGeneration !=
            s_m11_dm1_hoc_candidate_receipts.panelGeneration) {
        return 0;
    }
    if (outAdmission) {
        *outAdmission = runtime->admission;
    }
    return 1;
}

/* Adapt the already-admitted live C127/C040/C026 frame to the final capture
 * lifecycle. The material fields are copied from the actual loader-backed
 * admission only; a missing or stale source never manufactures a lifecycle. */
static int m11_dm1_hoc_final_runtime_capture_current(
    const M11_GameViewState* state,
    const DM1_V1_HocCandidateRuntimeFrameAdmissionReceiptPc34* admission,
    DM1_V1_HocLiveFinalRuntimeCaptureReceiptPc34* outCapture)
{
    DM1_V1_HocLiveM11BridgeLifecycleReceiptPc34 lifecycle;
    DM1_V1_HocLiveFinalRuntimeCaptureInputPc34 input;

    if (!state || !admission || !outCapture || !admission->valid ||
        !admission->sourceOwned || !admission->admitRuntimeFrame ||
        admission->commandCount != 2 ||
        admission->runtimeTick != (uint64_t)state->world.gameTick ||
        admission->c040SourceHash == 0u || admission->c026SourceHash == 0u) {
        return 0;
    }
    memset(&lifecycle, 0, sizeof(lifecycle));
    lifecycle.valid = 1;
    lifecycle.sourceOwned = 1;
    lifecycle.active = 1;
    lifecycle.currentC127Proof = 1;
    lifecycle.publishCurrent = 1;
    lifecycle.clearC040 = 1;
    lifecycle.drawC026Portrait = 1;
    lifecycle.mirrorOrdinal = admission->mirrorOrdinal;
    lifecycle.candidateChampionOrdinal = admission->mirrorOrdinal + 1u;
    lifecycle.sensorGeneration = admission->sensorGeneration;
    lifecycle.panelGeneration = admission->presentedPanelGeneration;
    lifecycle.admittedTick = admission->runtimeTick;
    lifecycle.c040.sourceOwned = 1;
    lifecycle.c040.graphicIndex = admission->commands[0].material.graphicIndex;
    lifecycle.c040.width = admission->commands[0].material.width;
    lifecycle.c040.height = admission->commands[0].material.height;
    lifecycle.c040.dstX = admission->commands[0].material.dstLeft;
    lifecycle.c040.dstY = admission->commands[0].material.dstTop;
    lifecycle.c040.sourceHash = admission->c040SourceHash;
    lifecycle.c026.sourceOwned = 1;
    lifecycle.c026.graphicIndex = admission->commands[1].material.graphicIndex;
    lifecycle.c026.sourceX = admission->commands[1].material.sourceX;
    lifecycle.c026.sourceY = admission->commands[1].material.sourceY;
    lifecycle.c026.width = admission->commands[1].material.width;
    lifecycle.c026.height = admission->commands[1].material.height;
    lifecycle.c026.dstX = admission->commands[1].material.dstLeft;
    lifecycle.c026.dstY = admission->commands[1].material.dstTop;
    lifecycle.c026.sourceHash = admission->c026SourceHash;
    memset(&input, 0, sizeof(input));
    input.lifecycle = &lifecycle;
    input.runtimeTick = admission->runtimeTick;
    memset(outCapture, 0, sizeof(*outCapture));
    return DM1_V1_HocLiveFinalRuntimeCapture_BuildReceiptPc34(
        &input, outCapture) && outCapture->valid && outCapture->sourceOwned &&
        outCapture->captureCurrentFrame && outCapture->captureC127Proof &&
        outCapture->captureC040Panel && outCapture->captureC026Portrait &&
        !outCapture->captureClearRevoke &&
        outCapture->runtimeTick == admission->runtimeTick &&
        outCapture->c040.sourceHash == admission->c040SourceHash &&
        outCapture->c026.sourceHash == admission->c026SourceHash;
}

static void m11_clear_dm1_hoc_runtime_frame_zones(
    unsigned char* framebuffer,
    int framebufferWidth,
    int framebufferHeight,
    const DM1_V1_HocCandidateRuntimeFrameAdmissionReceiptPc34* admission)
{
    DM1_V1_LayoutZoneRectPc34 panelRect =
        dm1_v1_inventory_panel_rect_pc34();
    int portraitX = 96;
    int portraitY = 35;
    int portraitW = 32;
    int portraitH = 29;

    if (!framebuffer) return;
    if (admission && admission->commandCount == 2) {
        panelRect.x = admission->commands[0].material.dstLeft;
        panelRect.y = admission->commands[0].material.dstTop;
        panelRect.w = admission->commands[0].material.width;
        panelRect.h = admission->commands[0].material.height;
        portraitX = admission->commands[1].material.dstLeft;
        portraitY = admission->commands[1].material.dstTop;
        portraitW = admission->commands[1].material.width;
        portraitH = admission->commands[1].material.height;
    }
    m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                  M11_VIEWPORT_X + panelRect.x,
                  M11_VIEWPORT_Y + panelRect.y,
                  panelRect.w, panelRect.h, M11_COLOR_BLACK);
    m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                  M11_VIEWPORT_X + portraitX,
                  M11_VIEWPORT_Y + portraitY,
                  portraitW, portraitH, M11_COLOR_BLACK);
}

static int m11_disable_front_mirror_sensor_owner(
    M11_GameViewState* state,
    int sensorIndex) {
    if (!state || !state->world.things || !state->world.things->sensors ||
        sensorIndex < 0 ||
        sensorIndex >= state->world.things->sensorCount) {
        return 0;
    }
    state->world.things->sensors[sensorIndex].sensorType = 0;
    return 1;
}

static int m11_front_mirror_record_already_in_party(const M11_GameViewState* state,
                                                     int mirrorOrdinal) {
    struct ChampionState_Compat champion;
    if (!state || !state->mirrorCatalogAvailable || mirrorOrdinal < 0) return 0;
    F0600_CHAMPION_InitEmpty_Compat(&champion);
    if (!F0675_CHAMPION_MirrorCatalogCopyRecord_Compat(&state->mirrorCatalog,
                                                       mirrorOrdinal,
                                                       &champion)) {
        return 0;
    }
    return F0626_PARTY_ContainsChampionName_Compat(&state->world.party,
                                                   champion.name);
}

static void m11_apply_reincarnation_to_candidate(M11_GameViewState* state,
                                                 int championIndex) {
    struct ChampionState_Compat* champ;
    uint8_t rngValues[12];
    ReincarnationResult_Compat r;
    int i;

    if (!state || championIndex < 0 || championIndex >= CHAMPION_MAX_PARTY) return;
    champ = &state->world.party.champions[championIndex];
    if (!champ->present) return;

    /* ReDMCSB REVIVE.C F0282 (DM1 V1 MEDIA265_S20E): reincarnation clears
     * skills, halves health/stamina/mana, then distributes 12 RANDOM(7)
     * statistic increments. Firestaff uses a deterministic local stream for
     * this runtime gate; the pure F0864 helper owns the source-locked math. */
    for (i = 0; i < 12; ++i) {
        rngValues[i] = (uint8_t)((state->world.gameTick +
                                  (unsigned int)championIndex * 3u +
                                  (unsigned int)i) % 7u);
    }
    r = F0864_RESURRECTION_ComputeReincarnation_Compat(
        (int16_t)champ->hp.maximum, (int16_t)champ->hp.current,
        (int16_t)champ->stamina.maximum, (int16_t)champ->stamina.current,
        (int16_t)champ->mana.maximum, (int16_t)champ->mana.current,
        rngValues);

    champ->hp.maximum = (unsigned short)r.newMaxHealth;
    champ->hp.current = (unsigned short)r.newCurrentHealth;
    champ->hp.shifted = (unsigned short)(champ->hp.maximum << 1);
    champ->stamina.maximum = (unsigned short)r.newMaxStamina;
    champ->stamina.current = (unsigned short)r.newCurrentStamina;
    champ->stamina.shifted = (unsigned short)(champ->stamina.maximum << 1);
    champ->mana.maximum = (unsigned short)r.newMaxMana;
    champ->mana.current = (unsigned short)r.newCurrentMana;
    champ->mana.shifted = (unsigned short)(champ->mana.maximum << 1);
    for (i = 0; i < CHAMPION_SKILL_COUNT; ++i) {
        champ->skillLevels[i] = 0;
        champ->skillExperience[i] = 0;
    }
    for (i = 0; i < CHAMPION_ATTR_COUNT; ++i) {
        champ->attributes[i] = (unsigned short)(champ->attributes[i] + r.statIncrements[i]);
    }
}

static void m11_repair_mirror_candidate_survival_fields(M11_GameViewState* state,
                                                        int championIndex) {
    struct ChampionState_Compat sourceRecord;
    struct ChampionState_Compat* champ;

    if (!state || !state->mirrorCatalogAvailable ||
        state->candidateMirrorOrdinal < 0 ||
        championIndex < 0 || championIndex >= CHAMPION_MAX_PARTY) {
        return;
    }
    champ = &state->world.party.champions[championIndex];
    if (!champ->present) return;
    if (champ->hp.maximum > 0 && champ->hp.current > 0 &&
        champ->stamina.maximum > 0 && champ->mana.maximum > 0 &&
        champ->maxLoad > 0 && champ->food > 0 && champ->water > 0) {
        return;
    }

    /* ReDMCSB REVIVE.C F0280 lines 227-242 materializes a live mirror
     * candidate from the C127 sensorData before C040 opens.  If stale HoC
     * routing or a partial candidate restore ever reaches F0282/Confirm with
     * zeroed survival fields, repair only those fields from the same source
     * mirror record instead of confirming a dead/immobile champion. */
    F0600_CHAMPION_InitEmpty_Compat(&sourceRecord);
    if (!F0675_CHAMPION_MirrorCatalogCopyRecord_Compat(
            &state->mirrorCatalog, state->candidateMirrorOrdinal,
            &sourceRecord)) {
        return;
    }
    champ->hp = sourceRecord.hp;
    champ->stamina = sourceRecord.stamina;
    champ->mana = sourceRecord.mana;
    champ->food = sourceRecord.food;
    champ->water = sourceRecord.water;
    champ->maxLoad = sourceRecord.maxLoad;
    if (champ->hp.current == 0 && champ->hp.maximum > 0) {
        champ->hp.current = champ->hp.maximum;
    }
}

static int m11_select_mirror_candidate_by_ordinal(M11_GameViewState* state,
                                                  int mirrorOrdinal) {
    ChampionPortraitClickInput_Compat click;
    HocMirrorCandidateSelectionReceipt_Compat routeReceipt;
    DM1_V1_HocCandidateClickPresentationInputPc34 presentationInput;
    DM1_V1_HocCandidateClickPresentationReceiptPc34 clickPresentation;
    DM1_V1_HocMirrorCandidateClickAdmissionInputPc34 admissionInput;
    DM1_V1_HocMirrorCandidateClickAdmissionReceiptPc34 admissionReceipt;
    DM1_V1_HocCandidateSelectionStateInputPc34 selectionInput;
    DM1_V1_HocCandidateSelectionStateReceiptPc34 selectionReceipt;
    DM1_V1_ChampionMirrorRuntimeRenderDecisionPc34 mirrorDecision;
    struct ChampionState_Compat sourceRecord;
    const M11_AssetSlot* portraits;
    const M11_AssetSlot* c040Panel;
    int previousPartyCount;
    int firstSensorIndex = -1;
    int wallCell = -1;
    char mirrorName[16];
    char mirrorTitle[32];

    mirrorName[0] = '\0';
    mirrorTitle[0] = '\0';
    if (!state || !state->active) return 0;
    /* ReDMCSB REVIVE.C F0282:806-807 enters F0281 synchronously for C161.
     * Its rename modal owns the appended candidate until C160/C161/C162
     * completes; another C127 cannot replace that candidate underneath it. */
    if (state->candidateMirrorPanelActive || state->candidateMirrorRenameActive) {
        return 0;
    }
    if (mirrorOrdinal < 0 ||
        !m11_front_mirror_click_wall_cell(state, mirrorOrdinal, &wallCell)) {
        return 0;
    }
    if (!m11_build_dm1_hoc_current_front_mirror_runtime_decision(
            state, &mirrorDecision) || !mirrorDecision.valid ||
        !mirrorDecision.drawChampionPortraitAsWallOverlay ||
        mirrorDecision.render.renderIndex != mirrorOrdinal) {
        return 0;
    }
    if (!m11_front_mirror_first_sensor_index_pc34(state, &firstSensorIndex)) {
        return 0;
    }
    m11_repair_dead_party_leader(state);
    if (!m11_party_has_pc34_candidate_layout(&state->world.party)) {
        m11_set_status(state, "MIRROR", "PARTY STATE INVALID");
        m11_set_inspect_readout(state, "CHAMPION MIRROR",
                                "CANNOT ADD TO A NON-PC34 PARTY LAYOUT");
        return 0;
    }
    if (state->world.party.championCount >= CHAMPION_MAX_PARTY) {
        m11_set_status(state, "MIRROR", "PARTY FULL");
        m11_set_inspect_readout(state, "CHAMPION MIRROR",
                                "NO ROOM FOR ANOTHER CHAMPION");
        return 0;
    }
    if (m11_front_mirror_record_already_in_party(state, mirrorOrdinal)) {
        m11_set_status(state, "MIRROR", "DISABLED");
        m11_set_inspect_readout(state, "CHAMPION MIRROR",
                                "THIS MIRROR HAS ALREADY JOINED THE PARTY");
        return 0;
    }

    previousPartyCount = state->world.party.championCount;
    F0600_CHAMPION_InitEmpty_Compat(&sourceRecord);
    portraits = M11_AssetLoader_Load(&state->assetLoader, 26u);
    c040Panel = M11_AssetLoader_Load(&state->assetLoader, 40u);
    memset(&click, 0, sizeof(click));
    click.command = DM1_COMMAND_CLICK_IN_DUNGEON_VIEW;
    click.leaderEmptyHanded =
        (DM1_V1_M11Runtime_GetLeaderHandThingPc34Compat(state) == THING_NONE);
    click.leaderIndex = state->world.party.activeChampionIndex;
    click.frontWallOrnamentHit = 1;
    click.frontSquareInBounds = 1;
    click.sensorType = DM1_SENSOR_WALL_CHAMPION_PORTRAIT;
    click.sensorData = (uint16_t)mirrorOrdinal;
    /* F0172's C127 receipt owns the source wall cell.  Do not replace it
     * with the D1C host rectangle's cell: HoC sensors use their packed
     * Thing cell, and F0280 admits only that same sensor/click pairing. */
    click.sensorCell = wallCell;
    click.clickedWallCell = wallCell;
    click.partyChampionCount = (uint16_t)previousPartyCount;
    routeReceipt =
        F0871_RESURRECTION_BuildHocMirrorCandidateSelectionReceipt_Compat(
            &click,
            F0675_CHAMPION_MirrorCatalogCopyRecord_Compat(
                &state->mirrorCatalog, mirrorOrdinal, &sourceRecord),
            portraits && portraits->loaded && portraits->pixels &&
                portraits->width >= CHAMPION_PORTRAIT_BITMAP_WIDTH * 8 &&
                portraits->height >= CHAMPION_PORTRAIT_BITMAP_HEIGHT * 3,
            state->candidateMirrorPanelActive ||
                state->candidateMirrorRenameActive);
    if (!routeReceipt.valid ||
        routeReceipt.candidateChampionIndex !=
            (uint16_t)previousPartyCount ||
        routeReceipt.partyChampionCountAfter !=
            (uint16_t)(previousPartyCount + 1)) {
        m11_set_status(state, "MIRROR", "SOURCE DATA MISSING");
        m11_set_inspect_readout(state, "CHAMPION MIRROR",
                                "ORIGINAL RECORD AND C026 PORTRAIT ARE REQUIRED");
        return 0;
    }
    /* Publish the exact C127/C026/C040 selection generation that F0282 must
     * later consume.  A direct candidate mutation without this receipt has
     * no source-owned confirmation route. */
    memset(&presentationInput, 0, sizeof(presentationInput));
    presentationInput.click = click;
    presentationInput.viewportX = mirrorDecision.render.dstX +
        mirrorDecision.render.width / 2;
    presentationInput.viewportY = mirrorDecision.render.dstY +
        mirrorDecision.render.height / 2;
    presentationInput.c127SensorOrdinal = (uint16_t)mirrorOrdinal;
    presentationInput.c127SensorEnabled = 1;
    presentationInput.originalChampionRecordAvailable = 1;
    presentationInput.c026PortraitAtlasAvailable =
        portraits && portraits->loaded && portraits->pixels &&
        portraits->width >= CHAMPION_PORTRAIT_BITMAP_WIDTH * 8 &&
        portraits->height >= CHAMPION_PORTRAIT_BITMAP_HEIGHT * 3;
    presentationInput.c040PanelGraphicAvailable =
        c040Panel && c040Panel->loaded && c040Panel->pixels &&
        c040Panel->width == dm1_v1_inventory_panel_rect_pc34().w &&
        c040Panel->height == dm1_v1_inventory_panel_rect_pc34().h;
    if (s_m11_dm1_hoc_candidate_receipts.owner != state) {
        memset(&s_m11_dm1_hoc_candidate_receipts, 0,
               sizeof(s_m11_dm1_hoc_candidate_receipts));
        s_m11_dm1_hoc_candidate_receipts.owner = state;
    }
    presentationInput.priorPanelGeneration =
        s_m11_dm1_hoc_candidate_receipts.panelGeneration;
    presentationInput.presentedPanelGeneration =
        s_m11_dm1_hoc_candidate_receipts.panelGeneration;
    memset(&clickPresentation, 0, sizeof(clickPresentation));
    memset(&selectionInput, 0, sizeof(selectionInput));
    if (!DM1_V1_HocCandidateClickPresentation_BuildReceiptPc34(
            &presentationInput, &clickPresentation)) {
        return 0;
    }
    memset(&admissionInput, 0, sizeof(admissionInput));
    admissionInput.mirrorRuntime.wallSquareVisible = 1;
    admissionInput.clickPresentation = presentationInput;
    admissionInput.c026.sourceOwned = 1;
    admissionInput.c026.graphicIndex = mirrorDecision.render.graphicIndex;
    admissionInput.c026.sourceX = mirrorDecision.render.sourceX;
    admissionInput.c026.sourceY = mirrorDecision.render.sourceY;
    admissionInput.c026.width = mirrorDecision.render.width;
    admissionInput.c026.height = mirrorDecision.render.height;
    admissionInput.c026.dstX = mirrorDecision.render.dstX;
    admissionInput.c026.dstY = mirrorDecision.render.dstY;
    admissionInput.c026.sourceHash = portraits && portraits->pixels
        ? m11_dm1_runtime_capture_fnv1a(
              portraits->pixels, (size_t)portraits->width * portraits->height)
        : 0u;
    admissionInput.c040.sourceOwned = 1;
    admissionInput.c040.graphicIndex = 40;
    admissionInput.c040.width = c040Panel ? (int)c040Panel->width : 0;
    admissionInput.c040.height = c040Panel ? (int)c040Panel->height : 0;
    admissionInput.c040.sourceHash = c040Panel && c040Panel->pixels
        ? m11_dm1_runtime_capture_fnv1a(
              c040Panel->pixels, (size_t)c040Panel->width * c040Panel->height)
        : 0u;
    memset(&admissionReceipt, 0, sizeof(admissionReceipt));
    if (!DM1_V1_HocMirrorCandidateClickAdmission_BuildFromRuntimeDecisionPc34(
            &mirrorDecision, &clickPresentation, &admissionInput.c026,
            &admissionInput.c040, &admissionReceipt) || !admissionReceipt.valid ||
        !admissionReceipt.admitCandidateClick ||
        admissionReceipt.mirrorOrdinal != (uint16_t)mirrorOrdinal) {
        return 0;
    }
    selectionInput.presentation = &clickPresentation;
    selectionInput.state.partyChampionCount = (uint16_t)previousPartyCount;
    selectionInput.state.candidateChampionOrdinal = 0;
    selectionInput.state.activeMirrorOrdinal = 0;
    selectionInput.state.c127SensorEnabled = 1;
    selectionInput.state.c127SensorOrdinal = (uint16_t)mirrorOrdinal;
    selectionInput.state.c026PortraitAtlasAvailable =
        presentationInput.c026PortraitAtlasAvailable;
    selectionInput.state.c040PanelGraphicAvailable =
        presentationInput.c040PanelGraphicAvailable;
    selectionInput.state.sensorGeneration =
        s_m11_dm1_hoc_candidate_receipts.sensorGeneration;
    selectionInput.state.panelGeneration =
        s_m11_dm1_hoc_candidate_receipts.panelGeneration;
    if (!DM1_V1_HocCandidateSelectionState_BuildReceiptPc34(
            &selectionInput, &selectionReceipt) || !selectionReceipt.valid ||
        !selectionReceipt.sourceOwned) {
        return 0;
    }
    if (M11_GameView_RecruitChampionByMirrorOrdinal(state, mirrorOrdinal) != 1) {
        return 0;
    }

    state->candidateMirrorOrdinal = mirrorOrdinal;
    state->candidateMirrorPartyIndex = previousPartyCount;
    state->candidateMirrorPanelActive = 1;
    state->candidateMirrorRenameActive = 0;
    memset(&state->candidateMirrorRename, 0, sizeof(state->candidateMirrorRename));
    state->inventoryPanelActive = 1;
    s_m11_dm1_hoc_candidate_receipts.selection = selectionReceipt;
    s_m11_dm1_hoc_candidate_receipts.valid = 1;
    s_m11_dm1_hoc_candidate_receipts.firstSensorIndex = firstSensorIndex;
    s_m11_dm1_hoc_candidate_receipts.sensorGeneration =
        selectionReceipt.sensorGeneration;
    s_m11_dm1_hoc_candidate_receipts.panelGeneration =
        selectionReceipt.panelGeneration;
    /* The visible C040/C026 route is frame-bound at selection time. A later
     * world tick must not reuse its material through the inventory overlay. */
    (void)m11_dm1_hoc_publish_runtime_frame_admission(state);
    if (previousPartyCount == 0) {
        /* ReDMCSB REVIVE.C:837-840 seeds G0362_l_LastPartyMovementTime
         * when the first champion joins from a mirror. */
        state->lastPartyMovementTick = state->world.gameTick;
    }
    (void)M11_GameView_GetMirrorNameByOrdinal(state, mirrorOrdinal,
                                              mirrorName, sizeof(mirrorName));
    (void)M11_GameView_GetMirrorTitleByOrdinal(state, mirrorOrdinal,
                                               mirrorTitle, sizeof(mirrorTitle));
    m11_refresh_hash(state);
    m11_set_status(state, "MIRROR", "RESURRECT OR REINCARNATE");
    snprintf(state->inspectTitle, sizeof(state->inspectTitle),
             "MIRROR: %s", mirrorName[0] ? mirrorName : "CHAMPION");
    snprintf(state->inspectDetail, sizeof(state->inspectDetail),
             "%s%s%s — CHOOSE RESURRECT, REINCARNATE, OR CANCEL",
             mirrorName[0] ? mirrorName : "CHAMPION",
             mirrorTitle[0] ? ", " : "",
             mirrorTitle[0] ? mirrorTitle : "");
    return 1;
}

int M11_GameView_SelectFrontMirrorCandidate(M11_GameViewState* state) {
    return m11_select_mirror_candidate_by_ordinal(
        state, m11_front_cell_mirror_ordinal(state));
}

int M11_GameView_ConfirmMirrorCandidate(M11_GameViewState* state,
                                        int reincarnate) {
    DM1_V1_HocCandidateConfirmationReceiptPc34 confirmation;
    DM1_V1_HocCandidateApplyReceiptPc34 apply;
    int championIndex;
    int firstSensorIndex;
    char mirrorName[16];

    mirrorName[0] = '\0';
    if (!state || !state->active || !state->candidateMirrorPanelActive ||
        state->candidateMirrorRenameActive || state->candidateMirrorOrdinal < 0) {
        return 0;
    }
    /* The C127 owner belongs to the selection receipt. The modal can remain
     * open while the view changes, but C160/C161 must still clear the sensor
     * that admitted this candidate rather than re-scanning a new front cell. */
    firstSensorIndex = s_m11_dm1_hoc_candidate_receipts.owner == state
        ? s_m11_dm1_hoc_candidate_receipts.firstSensorIndex : -1;
    championIndex = state->candidateMirrorPartyIndex;
    if (championIndex < 0 || championIndex >= state->world.party.championCount ||
        championIndex >= CHAMPION_MAX_PARTY ||
        !state->world.party.champions[championIndex].present) {
        return 0;
    }
    memset(&confirmation, 0, sizeof(confirmation));
    memset(&apply, 0, sizeof(apply));
    if (!m11_dm1_hoc_prepare_confirmation_apply(
            state,
            reincarnate ? DM1_COMMAND_REINCARNATE : DM1_COMMAND_RESURRECT,
            1, firstSensorIndex, &confirmation, &apply) ||
        confirmation.finalization.candidateChampionIndex !=
            (uint16_t)championIndex ||
        !apply.clearG0299CandidateOrdinal || !apply.closeC040Panel ||
        !apply.clearStalePanelPayload || !apply.writeMirrorSensorEnabled ||
        apply.nextMirrorSensorEnabled != 0) {
        m11_set_status(state, "MIRROR", "SOURCE RECEIPT STALE");
        return 0;
    }
    (void)M11_GameView_GetMirrorNameByOrdinal(state, state->candidateMirrorOrdinal,
                                              mirrorName, sizeof(mirrorName));
    m11_repair_mirror_candidate_survival_fields(state, championIndex);
    if (reincarnate) {
        m11_apply_reincarnation_to_candidate(state, championIndex);
    } else {
        /* ReDMCSB REVIVE.C F0282 C160 resurrect path.  A fresh mirror
         * candidate materialized by F0280 already carries the source
         * initial HP/STA/MANA from the mirror text, so a live candidate
         * keeps its vitals untouched.  The test-only edge case of a
         * dead-existing-champion slot reaching this code (HP=0) is
         * brought back to one hit point and asserted as leader, matching
         * dm1_v1_mirror_candidate_resurrect_rearm_pc34_compat.  Wounds
         * and poison from the prior death are cleared so the revived
         * champion does not bleed out in the first few ticks
         * (TAB-06 G0050 wound-defense correction in v2.7.25 made this
         * regression visible to real playtest). */
        struct ChampionState_Compat* champ = &state->world.party.champions[championIndex];
        if (champ->hp.current == 0) {
            champ->hp.current = 1;
        }
        champ->wounds = 0;
        champ->poisonDose = 0;
    }
    state->championDeathHandledMask &= (unsigned char)~(1u << championIndex);
    m11_repair_dead_party_leader(state);
    /* ReDMCSB REVIVE.C F0280:272-283 assigns the leader only when the
     * first C127 candidate enters the party. F0282:837-845 repeats that
     * first-party assignment after C160/C161 finalization; later C160
     * confirmations retain the existing leader and party order. */
    if (state->world.party.championCount == 1) {
        state->world.party.activeChampionIndex = 0;
    }
    if (firstSensorIndex >= 0 &&
        !m11_disable_front_mirror_sensor_owner(state, firstSensorIndex)) {
        return 0;
    }
    state->candidateMirrorRenameActive = 0;
    memset(&state->candidateMirrorRename, 0, sizeof(state->candidateMirrorRename));
    state->candidateMirrorPanelActive = 0;
    state->inventoryPanelActive = 0;
    state->candidateMirrorOrdinal = -1;
    state->candidateMirrorPartyIndex = -1;
    if (!m11_dm1_hoc_publish_presentation_receipt(state, &apply,
                                                   &confirmation)) {
        /* State has already committed atomically. Do not draw a substitute
         * panel/portrait on the next frame if the source presentation proof
         * went stale between F0282 apply and F0128. */
        memset(&s_m11_dm1_hoc_candidate_receipts.pendingPresentation, 0,
               sizeof(s_m11_dm1_hoc_candidate_receipts.pendingPresentation));
        s_m11_dm1_hoc_candidate_receipts.valid = 0;
    }
    m11_refresh_hash(state);
    m11_set_status(state, "MIRROR", reincarnate ? "REINCARNATED" : "RESURRECTED");
    snprintf(state->inspectTitle, sizeof(state->inspectTitle),
             "%s JOINS", mirrorName[0] ? mirrorName : "CHAMPION");
    snprintf(state->inspectDetail, sizeof(state->inspectDetail),
             "%s ADDED TO THE PARTY FROM THE SOURCE MIRROR RECORD",
             mirrorName[0] ? mirrorName : "CHAMPION");
    return 1;
}

int M11_GameView_BeginMirrorCandidateReincarnateRename(M11_GameViewState* state) {
    CandidatePanelState_Compat panelState;
    HocMirrorCandidateFinalizeReceipt_Compat finalizeReceipt;
    int championIndex;

    if (!state || !state->active || !state->candidateMirrorPanelActive ||
        state->candidateMirrorOrdinal < 0) {
        return 0;
    }
    championIndex = state->candidateMirrorPartyIndex;
    if (championIndex < 0 || championIndex >= state->world.party.championCount ||
        championIndex >= CHAMPION_MAX_PARTY ||
        !state->world.party.champions[championIndex].present) {
        return 0;
    }
    panelState.partyChampionCount =
        (uint16_t)state->world.party.championCount;
    panelState.candidateChampionOrdinal =
        (uint16_t)(state->candidateMirrorPartyIndex + 1);
    finalizeReceipt =
        F0872_RESURRECTION_BuildHocMirrorCandidateFinalizeReceipt_Compat(
            panelState, DM1_COMMAND_REINCARNATE, 0);
    if (finalizeReceipt.valid ||
        !finalizeReceipt.renameRequiredBeforeFinalize ||
        finalizeReceipt.candidateChampionIndex != (uint16_t)championIndex) {
        return 0;
    }

    /* ReDMCSB: REVIVE.C F0282:806-808 calls F0281 only for C161.
     * F0281:407-419 blits C027, clears Name/Title, and starts with
     * the name-field cursor. M11 keeps that modal routine as live
     * state instead of blocking the SDL loop. */
    dm1_v1_resurrection_rename_ui_gate_init_pc34(
        &state->candidateMirrorRename,
        DM1_V1_RESURRECTION_RENAME_UI_COMMAND_REINCARNATE_PC34_COMPAT);
    state->candidateMirrorRenameActive =
        state->candidateMirrorRename.f0281RenameCallCount == 1;
    if (!state->candidateMirrorRenameActive) {
        return 0;
    }

    state->inventoryPanelActive = 1;
    state->world.party.champions[championIndex].name[0] = '\0';
    state->world.party.champions[championIndex].title[0] = '\0';
    m11_set_status(state, "MIRROR", "ENTER NAME");
    m11_set_inspect_readout(state, "REINCARNATE",
                            "TYPE A NAME, THEN OK TO JOIN");
    return 1;
}

static int m11_candidate_rename_name_duplicates_existing_party(
    const M11_GameViewState* state,
    int candidateChampionIndex) {
    int i;
    int compareLimit;

    if (!state || candidateChampionIndex < 0) {
        return 0;
    }
    compareLimit = state->world.party.championCount - 1;
    if (compareLimit > CHAMPION_MAX_PARTY) {
        compareLimit = CHAMPION_MAX_PARTY;
    }
    if (compareLimit < 0) {
        compareLimit = 0;
    }
    /* ReDMCSB REVIVE.C F0281:448-464 trims the proposed name and
     * compares it against already-selected party champions using
     * G0305_ui_PartyChampionCount - 1, because F0280 appended the
     * candidate as the last party member before F0281 started. */
    for (i = 0; i < compareLimit; ++i) {
        const struct ChampionState_Compat* existing =
            &state->world.party.champions[i];
        if (i == candidateChampionIndex || !existing->present) {
            continue;
        }
        if (strcmp((const char*)existing->name,
                   state->candidateMirrorRename.name) == 0) {
            return 1;
        }
    }
    return 0;
}

static int m11_finish_candidate_rename_if_accepted(M11_GameViewState* state) {
    int championIndex;
    struct ChampionState_Compat* champ;

    if (!state || !state->candidateMirrorRenameActive ||
        !state->candidateMirrorRename.okAccepted) {
        return 0;
    }
    championIndex = state->candidateMirrorPartyIndex;
    if (championIndex < 0 || championIndex >= state->world.party.championCount ||
        championIndex >= CHAMPION_MAX_PARTY) {
        state->candidateMirrorRenameActive = 0;
        return 0;
    }
    if (m11_candidate_rename_name_duplicates_existing_party(state,
                                                           championIndex)) {
        state->candidateMirrorRename.returned = 0;
        state->candidateMirrorRename.okAccepted = 0;
        state->candidateMirrorRename.duplicateNameRejectedCount++;
        m11_set_status(state, "RENAME", "NAME IN USE");
        m11_set_inspect_readout(state, "REINCARNATE",
                                "CHOOSE A DIFFERENT NAME");
        return 1;
    }
    champ = &state->world.party.champions[championIndex];
    {
        size_t nameLen = strlen(state->candidateMirrorRename.name);
        size_t titleLen = strlen(state->candidateMirrorRename.title);
        if (nameLen >= sizeof(champ->name)) {
            nameLen = sizeof(champ->name) - 1U;
        }
        if (titleLen >= sizeof(champ->title)) {
            titleLen = sizeof(champ->title) - 1U;
        }
        memset(champ->name, 0, sizeof(champ->name));
        memcpy(champ->name, state->candidateMirrorRename.name, nameLen);
        memset(champ->title, 0, sizeof(champ->title));
        memcpy(champ->title, state->candidateMirrorRename.title, titleLen);
    }
    state->candidateMirrorRenameActive = 0;
    memset(&state->candidateMirrorRename, 0, sizeof(state->candidateMirrorRename));
    return M11_GameView_ConfirmMirrorCandidate(state, 1);
}

int M11_GameView_ApplyMirrorCandidateRenameCommand(M11_GameViewState* state,
                                                   int command) {
    int changed;

    if (!state || !state->candidateMirrorRenameActive) {
        return 0;
    }
    changed = dm1_v1_resurrection_rename_ui_gate_apply_command_pc34(
        &state->candidateMirrorRename, command);
    if (!changed) {
        return 0;
    }
    if (m11_finish_candidate_rename_if_accepted(state)) {
        return 1;
    }
    m11_set_status(state, "RENAME",
                   state->candidateMirrorRename.fieldMode ==
                           DM1_V1_RESURRECTION_RENAME_UI_FIELD_TITLE_PC34_COMPAT
                       ? "TITLE"
                       : "NAME");
    return 1;
}

int M11_GameView_ApplyMirrorCandidateRenameAscii(M11_GameViewState* state,
                                                 int ch) {
    int changed;

    if (!state || !state->candidateMirrorRenameActive) {
        return 0;
    }
    changed = dm1_v1_resurrection_rename_ui_gate_apply_ascii_pc34(
        &state->candidateMirrorRename, ch);
    if (!changed) {
        return 0;
    }
    if (m11_finish_candidate_rename_if_accepted(state)) {
        return 1;
    }
    m11_set_status(state, "RENAME",
                   state->candidateMirrorRename.fieldMode ==
                           DM1_V1_RESURRECTION_RENAME_UI_FIELD_TITLE_PC34_COMPAT
                       ? "TITLE"
                       : "NAME");
    return 1;
}

int M11_GameView_HandleMirrorCandidateRenameClick(M11_GameViewState* state,
                                                  int x,
                                                  int y) {
    int ch;

    if (!state || !state->candidateMirrorRenameActive) {
        return 0;
    }
    if (m11_point_in_rect(x, y, 197, 147, 19, 9)) {
        return M11_GameView_ApplyMirrorCandidateRenameCommand(
            state, DM1_V1_RESURRECTION_RENAME_UI_COMMAND_OK_PC34_COMPAT);
    }
    if (m11_point_in_rect(x, y, 107, 147, 69, 9)) {
        return M11_GameView_ApplyMirrorCandidateRenameCommand(
            state, DM1_V1_RESURRECTION_RENAME_UI_COMMAND_BACKSPACE_PC34_COMPAT);
    }
    if (x < 107 || x > 215 || y < 116 || y > 144) {
        return 0;
    }
    if (((x + 4) % 10) == 0 ||
        (((y + 5) % 10) == 0 && (x < 207 || y != 135))) {
        return 0;
    }

    ch = 'A' + (11 * ((y - 116) / 10)) + ((x - 107) / 10);
    if (ch == 86 || ch == 97) {
        return M11_GameView_ApplyMirrorCandidateRenameAscii(state, '\r');
    }
    if (ch >= 87) {
        --ch;
    }
    if (ch > 'Z') {
        static const char kSpecials[] = { ',', '.', ';', ':', ' ' };
        int specialIndex = ch - 'Z' - 1;
        if (specialIndex < 0 ||
            specialIndex >= (int)(sizeof(kSpecials) / sizeof(kSpecials[0]))) {
            return 0;
        }
        ch = kSpecials[specialIndex];
    }
    return M11_GameView_ApplyMirrorCandidateRenameAscii(state, ch);
}

int M11_GameView_CancelMirrorCandidate(M11_GameViewState* state) {
    DM1_V1_HocCandidateConfirmationReceiptPc34 confirmation;
    DM1_V1_HocCandidateApplyReceiptPc34 apply;
    int championIndex;
    if (!state || !state->active || !state->candidateMirrorPanelActive) {
        return 0;
    }
    championIndex = state->candidateMirrorPartyIndex;
    memset(&confirmation, 0, sizeof(confirmation));
    memset(&apply, 0, sizeof(apply));
    if (championIndex < 0 || championIndex >= state->world.party.championCount ||
        !m11_dm1_hoc_prepare_confirmation_apply(
            state, DM1_COMMAND_CANCEL, 1, -1, &confirmation, &apply) ||
        confirmation.finalization.candidateChampionIndex !=
            (uint16_t)championIndex ||
        !apply.clearG0299CandidateOrdinal || !apply.closeC040Panel ||
        !apply.clearStalePanelPayload || apply.writeMirrorSensorEnabled ||
        !apply.drawC026Portrait || !apply.nextMirrorSensorEnabled ||
        apply.nextPartyChampionCount + 1u !=
            (uint16_t)state->world.party.championCount) {
        m11_set_status(state, "MIRROR", "SOURCE RECEIPT STALE");
        return 0;
    }
    if (championIndex >= 0 && championIndex < CHAMPION_MAX_PARTY) {
        if (F0643_PARTY_ClearChampionSlot_Compat(&state->world.party,
                                                 championIndex)) {
            /* ReDMCSB REVIVE.C F0282 C162 cancels this temporary candidate.
             * Its prior F0407/F0330 C11 must not enable a later mirror
             * recruited into the same party slot. */
            DM1_V1_F0407_ClearRemovedChampionActionReceiptsPc34Compat(
                &state->world, championIndex);
        }
        if (state->world.party.championCount <= 0) {
            state->world.party.activeChampionIndex = -1;
        }
    }
    state->candidateMirrorRenameActive = 0;
    memset(&state->candidateMirrorRename, 0, sizeof(state->candidateMirrorRename));
    state->candidateMirrorPanelActive = 0;
    state->inventoryPanelActive = 0;
    state->candidateMirrorOrdinal = -1;
    state->candidateMirrorPartyIndex = -1;
    if (!m11_dm1_hoc_publish_presentation_receipt(state, &apply,
                                                   &confirmation)) {
        memset(&s_m11_dm1_hoc_candidate_receipts.pendingPresentation, 0,
               sizeof(s_m11_dm1_hoc_candidate_receipts.pendingPresentation));
        s_m11_dm1_hoc_candidate_receipts.valid = 0;
    }
    m11_refresh_hash(state);
    m11_set_status(state, "MIRROR", "CANCELLED");
    m11_set_inspect_readout(state, "CHAMPION MIRROR",
                            "SELECTION CANCELLED");
    return 1;
}

static M11_GameInputResult m11_csb_handle_source_keyboard(M11_GameViewState* state,
                                                          M12_MenuInput input);

static int m11_v1_movement_arrow_visual_mask_for_input(M12_MenuInput input) {
    int command = 0;
    switch (input) {
        case M12_MENU_INPUT_LEFT:
        case M12_MENU_INPUT_TURN_LEFT:
            command = DM1_V1_MOVEMENT_ARROW_COMMAND_TURN_LEFT_PC34;
            break;
        case M12_MENU_INPUT_RIGHT:
        case M12_MENU_INPUT_TURN_RIGHT:
            command = DM1_V1_MOVEMENT_ARROW_COMMAND_TURN_RIGHT_PC34;
            break;
        case M12_MENU_INPUT_UP:
            command = DM1_V1_MOVEMENT_ARROW_COMMAND_FORWARD_PC34;
            break;
        case M12_MENU_INPUT_DOWN:
            command = DM1_V1_MOVEMENT_ARROW_COMMAND_BACKWARD_PC34;
            break;
        case M12_MENU_INPUT_STRAFE_LEFT:
            command = DM1_V1_MOVEMENT_ARROW_COMMAND_LEFT_PC34;
            break;
        case M12_MENU_INPUT_STRAFE_RIGHT:
            command = DM1_V1_MOVEMENT_ARROW_COMMAND_RIGHT_PC34;
            break;
        default:
            return 0;
    }
    return dm1_v1_movement_arrow_visual_mask_for_command_pc34(command);
}

static void m11_mark_v1_movement_arrow_visual(M11_GameViewState* state,
                                               M12_MenuInput input) {
    int mask;
    if (!state) {
        return;
    }
    mask = m11_v1_movement_arrow_visual_mask_for_input(input);
    if (!mask) {
        return;
    }
    state->v1MovementArrowVisualMask = mask;
    state->v1MovementArrowVisualTicks = M11_V1_ARROW_VIS_TICKS;
}

enum {
    M11_GRAPHICS_POPUP_PAGE_PRESENTATION = 0,
    M11_GRAPHICS_POPUP_PAGE_FILTERS,
    M11_GRAPHICS_POPUP_PAGE_EFFECTS,
    M11_GRAPHICS_POPUP_PAGE_CHEATS,
    M11_GRAPHICS_POPUP_PAGE_COUNT,
    /* Keep the live dungeon visible while graphics settings are adjusted.
     * The prior 288x184 modal almost completely hid the 224x136 viewport. */
    M11_GRAPHICS_POPUP_X = 166,
    M11_GRAPHICS_POPUP_Y = 8,
    M11_GRAPHICS_POPUP_W = 148,
    M11_GRAPHICS_POPUP_H = 150
};

static int m11_graphics_popup_row_count(const M11_GameViewState* state,
                                        int page) {
    if (page == M11_GRAPHICS_POPUP_PAGE_PRESENTATION) return 9;
    if (page == M11_GRAPHICS_POPUP_PAGE_CHEATS) return 2;
    /* CSB has its own source-preserving V2 filter chain.  Do not present
     * DM1-only colour/sharpen controls as if they altered CSB's runtime. */
    if (page == M11_GRAPHICS_POPUP_PAGE_FILTERS &&
        state && state->sourceKind == M11_GAME_SOURCE_CSB_BOOT) return 6;
    return page == M11_GRAPHICS_POPUP_PAGE_FILTERS ? 11 : 8;
}

static int m11_graphics_popup_game_slot(const M11_GameViewState* state) {
    if (!state) return 0;
    if (state->sourceKind == M11_GAME_SOURCE_CSB_BOOT) return 1;
    if (state->sourceKind == M11_GAME_SOURCE_DM2_BOOT) return 2;
    if (state->sourceKind == M11_GAME_SOURCE_NEXUS_DGN) return 3;
    if (state->sourceKind == M11_GAME_SOURCE_THERON_TRACK02) return 4;
    return 0;
}

static int m11_graphics_popup_cycle(int value, int delta, int count) {
    value += delta;
    while (value < 0) value += count;
    while (value >= count) value -= count;
    return value;
}

static void m11_graphics_popup_apply_v2(const M11_GameViewState* state,
                                        const M12_Config* config) {
    if (!config) return;
    if (state && state->sourceKind == M11_GAME_SOURCE_CSB_BOOT) {
        CSB_V2_Settings settings;
        csb_v2_settings_from_m12_config(&settings, config);
        csb_v2_settings_apply_to_runtime(&settings);
        (void)M11_Render_SetV2Filters(settings.crtScanlinesEnabled,
                                      settings.crtScanlineStrength,
                                      settings.paletteCorrectionEnabled,
                                      100, 0, 0,
                                      settings.paletteCorrectionEnabled,
                                      100, settings.ditherCleanupEnabled,
                                      0, 0);
        return;
    }
    /* M12 has no independent persisted interpolation preference. Palette
     * correction therefore owns the renderer's interpolation gate too, with
     * the established full-strength value. The panel names that mapping
     * explicitly instead of inventing a synthetic asset or config option. */
    (void)M11_Render_SetV2Filters(config->dm1V2CrtScanlinesEnabled,
                                  config->dm1V2CrtScanlineStrength,
                                  config->dm1V2PaletteCorrectionEnabled,
                                  config->dm1V2PaletteGamma,
                                  config->dm1V2PaletteBrightness,
                                  config->dm1V2PaletteContrast,
                                  config->dm1V2PaletteCorrectionEnabled,
                                  100,
                                  config->dm1V2DitherCleanupEnabled,
                                  config->dm1V2SharpeningEnabled,
                                  config->dm1V2SharpeningStrength);
    (void)M11_Render_SetPhosphor(config->dm1V2PhosphorPersistenceEnabled,
                                 config->dm1V2PhosphorDecay);
    (void)M11_Render_SetColorPreset(config->dm1V2ColorPreset);
    (void)M11_Render_SetPixelGrid(config->dm1V2PixelGridEnabled,
                                  config->dm1V2PixelGridIntensity);
    (void)M11_Render_SetMotionBlur(config->dm1V2MotionBlurEnabled,
                                   config->dm1V2MotionBlurStrength);
}

static int m11_graphics_popup_mode_count(const M11_GameViewState* state) {
    M12_Config config;
    /* V2.2 is offered only to runtimes that have a real art-material gate.
     * DM2/Nexus keep their currently admitted V1/V2.0/V2.1 routes; a fake
     * V2.2 choice would be worse than not offering it. */
    if (!state || state->sourceKind == M11_GAME_SOURCE_DM2_BOOT ||
        state->sourceKind == M11_GAME_SOURCE_NEXUS_DGN) {
        return M12_PRESENTATION_V22_MODERN;
    }
    /* M12's installed bit is cross-game launcher state. CSB V2.2 has a
     * stricter per-game provenance gate, so a finished DM1 pack must not
     * expose CSB V2.2 in the live graphics menu. */
    if (state->sourceKind == M11_GAME_SOURCE_CSB_BOOT) {
        /* CSB owns both its pack admission and material provenance.  Do not
         * consult M12's DM1-oriented launcher bit after this: a real,
         * complete CSB pack may be installed without any DM1 V2.2 pack. */
        return csb_v22_famg_is_finished_real()
            ? M12_PRESENTATION_MODE_COUNT
            : M12_PRESENTATION_V22_MODERN;
    }
    M12_Config_Load(&config, NULL);
    /* A selected archive is not installed material. In particular it may
     * belong to another game, so exposing V2.2 from its path would let CSB
     * enter a presentation mode without a complete CSB manifest/cache. */
    if (!config.v22_modern_assets_installed) {
        return M12_PRESENTATION_V22_MODERN;
    }
    return M12_PRESENTATION_MODE_COUNT;
}

static const char* m11_graphics_popup_mode_name(int mode) {
    switch (mode) {
        case M12_PRESENTATION_V1_ORIGINAL: return "ORIGINAL V1";
        case M12_PRESENTATION_V20_FILTERED: return "V2.0 FILTERED";
        case M12_PRESENTATION_V21_UPSCALED: return "V2.1 UPSCALED";
        case M12_PRESENTATION_V22_MODERN: return "V2.2 ARTPACK";
        default: return "ORIGINAL V1";
    }
}

static int m11_graphics_popup_apply_mode(M11_GameViewState* state, int mode) {
    int resolved = mode;
    if (!state || mode < M12_PRESENTATION_V1_ORIGINAL ||
        mode >= m11_graphics_popup_mode_count(state)) {
        return 0;
    }
    if (state->sourceKind == M11_GAME_SOURCE_BUILTIN_CATALOG) {
        dm1_v2_presentation_mode_set_m12(mode);
        switch (dm1_v2_presentation_mode_get()) {
            case DM1_V2_PM_V20_FILTERED: resolved = M12_PRESENTATION_V20_FILTERED; break;
            case DM1_V2_PM_V21_UPSCALED: resolved = M12_PRESENTATION_V21_UPSCALED; break;
            case DM1_V2_PM_V22_MODERN: resolved = M12_PRESENTATION_V22_MODERN; break;
            default: resolved = M12_PRESENTATION_V1_ORIGINAL; break;
        }
    } else if (state->sourceKind == M11_GAME_SOURCE_CSB_BOOT) {
        csb_v2_presentation_mode_set_m12(mode);
        switch (csb_v2_presentation_mode_get()) {
            case CSB_V2_PM_V20_FILTERED: resolved = M12_PRESENTATION_V20_FILTERED; break;
            case CSB_V2_PM_V21_UPSCALED: resolved = M12_PRESENTATION_V21_UPSCALED; break;
            case CSB_V2_PM_V22_MODERN: resolved = M12_PRESENTATION_V22_MODERN; break;
            default: resolved = M12_PRESENTATION_V1_ORIGINAL; break;
        }
    } else if (state->sourceKind == M11_GAME_SOURCE_THERON_TRACK02) {
        theron_v2_presentation_mode_set_m12(mode);
        switch (theron_v2_presentation_mode_get()) {
            case THERON_V2_PM_V20_FILTERED: resolved = M12_PRESENTATION_V20_FILTERED; break;
            case THERON_V2_PM_V21_UPSCALED: resolved = M12_PRESENTATION_V21_UPSCALED; break;
            case THERON_V2_PM_V22_MODERN: resolved = M12_PRESENTATION_V22_MODERN; break;
            default: resolved = M12_PRESENTATION_V1_ORIGINAL; break;
        }
    }
    state->presentationMode = resolved;
    m11_set_status(state, "GRAPHICS", m11_graphics_popup_mode_name(resolved));
    return 1;
}

static int m11_graphics_popup_adjust(M11_GameViewState* state, int delta) {
    M12_Config config;
    int slot;
    int row;
    if (!state || delta == 0) return 0;
    M12_Config_Load(&config, NULL);
    slot = m11_graphics_popup_game_slot(state);
    row = state->graphicsPopupSelectedRow;
    if (state->graphicsPopupPage == M11_GRAPHICS_POPUP_PAGE_PRESENTATION) {
        switch (row) {
            case 0:
                if (!m11_graphics_popup_apply_mode(state,
                    m11_graphics_popup_cycle(state->presentationMode, delta,
                                              m11_graphics_popup_mode_count(state)))) return 0;
                config.graphicsIndex = state->presentationMode;
                if (state->presentationMode == M12_PRESENTATION_V1_ORIGINAL) {
                    config.gameResolution[slot] = M12_RES_320x200;
                    config.gameAspectRatio[slot] = M12_ASPECT_ORIGINAL;
                    state->presentationWidth = M11_FB_WIDTH;
                    state->presentationHeight = M11_FB_HEIGHT;
                } else {
                    if (config.gameResolution[slot] < M12_RES_640x400)
                        config.gameResolution[slot] = M12_RES_640x400;
                    M12_Resolution_Dimensions(config.gameResolution[slot],
                                              &state->presentationWidth,
                                              &state->presentationHeight);
                }
                break;
            case 1: config.scaleModeIndex = m11_graphics_popup_cycle(config.scaleModeIndex, delta, 6); (void)M11_Render_SetScaleMode(config.scaleModeIndex); break;
            case 2: config.scalingFilterIndex = !config.scalingFilterIndex; (void)M11_Render_SetScaleFilter(config.scalingFilterIndex); break;
            case 3: config.displayAspectMode = m11_graphics_popup_cycle(config.displayAspectMode, delta, 3); (void)M11_Render_SetDisplayAspectMode(config.displayAspectMode); break;
            case 4: config.integerScaling = !config.integerScaling; (void)M11_Render_SetIntegerScaling(config.integerScaling); break;
            case 5: config.vsyncIndex = !config.vsyncIndex; (void)M11_Render_SetVSync(config.vsyncIndex); break;
            case 6:
                config.showFpsOverlay = !config.showFpsOverlay;
                state->fpsOverlayEnabled = config.showFpsOverlay;
                break;
            case 7:
                if (state->presentationMode == M12_PRESENTATION_V1_ORIGINAL) return 1;
                config.gameResolution[slot] = m11_graphics_popup_cycle(config.gameResolution[slot], delta, M12_RES_COUNT);
                if (config.gameResolution[slot] < M12_RES_640x400) config.gameResolution[slot] = M12_RES_640x400;
                M12_Resolution_Dimensions(config.gameResolution[slot], &state->presentationWidth, &state->presentationHeight);
                break;
            case 8: config.windowModeIndex = m11_graphics_popup_cycle(config.windowModeIndex, delta, 3); (void)M11_Render_SetWindowMode(config.windowModeIndex); break;
        }
    } else if (state->graphicsPopupPage == M11_GRAPHICS_POPUP_PAGE_CHEATS) {
        /* Only expose cheats that have a real shared runtime owner.  The
         * launcher already owns this master toggle and speed setting for all
         * five games; do not invent game-specific debug powers here. */
        if (row == 0) {
            config.gameCheatsEnabled[slot] = !config.gameCheatsEnabled[slot];
            if (!config.gameCheatsEnabled[slot]) {
                config.gameSpeed[slot] = 1;
                config.gameSpeedMultiplier = 100;
                M11_QolRuntime_SetSpeedMultiplier(100);
            } else {
                static const int speedMultipliers[] = { 50, 100, 150 };
                int speed = config.gameSpeed[slot];
                if (speed < 0 || speed > 2) speed = 1;
                config.gameSpeed[slot] = speed;
                config.gameSpeedMultiplier = speedMultipliers[speed];
                M11_QolRuntime_SetSpeedMultiplier(speedMultipliers[speed]);
            }
        } else if (row == 1 && config.gameCheatsEnabled[slot]) {
            static const int speedMultipliers[] = { 50, 100, 150 };
            config.gameSpeed[slot] = m11_graphics_popup_cycle(
                config.gameSpeed[slot], delta, 3);
            config.gameSpeedMultiplier = speedMultipliers[config.gameSpeed[slot]];
            M11_QolRuntime_SetSpeedMultiplier(config.gameSpeedMultiplier);
        }
    } else {
        /* Filters are deliberately locked in V1: the source-original route
         * remains exact while enhanced modes can change presentation live. */
        if (state->presentationMode == M12_PRESENTATION_V1_ORIGINAL) return 1;
        if (state->graphicsPopupPage == M11_GRAPHICS_POPUP_PAGE_FILTERS) {
            switch (row) {
                case 0:
                    if (state->sourceKind == M11_GAME_SOURCE_CSB_BOOT)
                        config.csbV2CrtScanlinesEnabled = !config.csbV2CrtScanlinesEnabled;
                    else config.dm1V2CrtScanlinesEnabled = !config.dm1V2CrtScanlinesEnabled;
                    break;
                case 1:
                    if (state->sourceKind == M11_GAME_SOURCE_CSB_BOOT)
                        config.csbV2CrtScanlineStrength = m11_graphics_popup_cycle(config.csbV2CrtScanlineStrength, delta, 101);
                    else config.dm1V2CrtScanlineStrength = m11_graphics_popup_cycle(config.dm1V2CrtScanlineStrength, delta, 101);
                    break;
                case 2:
                    if (state->sourceKind == M11_GAME_SOURCE_CSB_BOOT)
                        config.csbV2PaletteCorrectionEnabled = !config.csbV2PaletteCorrectionEnabled;
                    else config.dm1V2PaletteCorrectionEnabled = !config.dm1V2PaletteCorrectionEnabled;
                    break;
                case 3:
                    if (state->sourceKind == M11_GAME_SOURCE_CSB_BOOT)
                        config.csbV2DitherCleanupEnabled = !config.csbV2DitherCleanupEnabled;
                    else { config.dm1V2PaletteGamma += delta * 5; if (config.dm1V2PaletteGamma < 80) config.dm1V2PaletteGamma = 260; if (config.dm1V2PaletteGamma > 260) config.dm1V2PaletteGamma = 80; }
                    break;
                case 4:
                    if (state->sourceKind == M11_GAME_SOURCE_CSB_BOOT) {
                        static const int scaleChoices[] = { 100, 200, 400 };
                        int choice = config.csbV2ScalePercent == 100 ? 0 :
                                     config.csbV2ScalePercent == 400 ? 2 : 1;
                        config.csbV2ScalePercent = scaleChoices[
                            m11_graphics_popup_cycle(choice, delta, 3)];
                    } else config.dm1V2PaletteBrightness = m11_graphics_popup_cycle(config.dm1V2PaletteBrightness + 50, delta * 5, 101) - 50;
                    break;
                case 5:
                    if (state->sourceKind == M11_GAME_SOURCE_CSB_BOOT)
                        config.csbV2BilinearEnabled = !config.csbV2BilinearEnabled;
                    else config.dm1V2PaletteContrast = m11_graphics_popup_cycle(config.dm1V2PaletteContrast + 50, delta * 5, 101) - 50;
                    break;
                case 6: config.dm1V2DitherCleanupEnabled = !config.dm1V2DitherCleanupEnabled; break;
                case 7: config.dm1V2SharpeningEnabled = !config.dm1V2SharpeningEnabled; break;
                case 8: config.dm1V2SharpeningStrength = m11_graphics_popup_cycle(config.dm1V2SharpeningStrength, delta, 101); break;
                case 9: config.dm1V2ColorPreset = m11_graphics_popup_cycle(config.dm1V2ColorPreset, delta, 7); break;
                case 10: config.dm1V2SmoothingEnabled = !config.dm1V2SmoothingEnabled; break;
            }
        } else {
            switch (row) {
                case 0: config.dm1V2PhosphorPersistenceEnabled = !config.dm1V2PhosphorPersistenceEnabled; break;
                case 1: config.dm1V2PhosphorDecay = m11_graphics_popup_cycle(config.dm1V2PhosphorDecay, delta, 101); break;
                case 2: config.dm1V2PixelGridEnabled = !config.dm1V2PixelGridEnabled; break;
                case 3: config.dm1V2PixelGridIntensity = m11_graphics_popup_cycle(config.dm1V2PixelGridIntensity, delta, 101); break;
                case 4: config.dm1V2MotionBlurEnabled = !config.dm1V2MotionBlurEnabled; break;
                case 5: config.dm1V2MotionBlurStrength = m11_graphics_popup_cycle(config.dm1V2MotionBlurStrength, delta, 101); break;
                case 6: config.dm1V2DynamicLightingEnabled = !config.dm1V2DynamicLightingEnabled; break;
                case 7: config.dm1V2SmoothTurnPanEnabled = !config.dm1V2SmoothTurnPanEnabled; break;
            }
        }
    }
    m11_graphics_popup_apply_v2(state, &config);
    (void)M12_Config_Save(&config);
    return 1;
}

static int m11_graphics_popup_handle_input(M11_GameViewState* state,
                                           M12_MenuInput input) {
    if (!state) return 0;
    if (input == M12_MENU_INPUT_GRAPHICS_POPUP) {
        state->graphicsPopupActive = !state->graphicsPopupActive;
        state->graphicsPopupPage = M11_GRAPHICS_POPUP_PAGE_PRESENTATION;
        state->graphicsPopupSelectedRow = 0;
        return 1;
    }
    if (!state->graphicsPopupActive) return 0;
    if (input == M12_MENU_INPUT_BACK) {
        state->graphicsPopupActive = 0;
        return 1;
    }
    if (input == M12_MENU_INPUT_ACCEPT || input == M12_MENU_INPUT_ACTION) {
        return m11_graphics_popup_adjust(state, 1);
    }
    if (input == M12_MENU_INPUT_CYCLE_CHAMPION) {
        state->graphicsPopupPage = (state->graphicsPopupPage + 1) % M11_GRAPHICS_POPUP_PAGE_COUNT;
        state->graphicsPopupSelectedRow = 0;
        return 1;
    }
    if (input == M12_MENU_INPUT_UP || input == M12_MENU_INPUT_DOWN) {
        state->graphicsPopupSelectedRow =
            (state->graphicsPopupSelectedRow +
             (input == M12_MENU_INPUT_UP ? m11_graphics_popup_row_count(state, state->graphicsPopupPage) - 1 : 1)) %
            m11_graphics_popup_row_count(state, state->graphicsPopupPage);
        return 1;
    }
    if (input != M12_MENU_INPUT_LEFT && input != M12_MENU_INPUT_RIGHT &&
        input != M12_MENU_INPUT_VALUE_LEFT && input != M12_MENU_INPUT_VALUE_RIGHT) {
        return 1;
    }
    return m11_graphics_popup_adjust(state,
        (input == M12_MENU_INPUT_LEFT || input == M12_MENU_INPUT_VALUE_LEFT) ? -1 : 1);
}

enum {
    M11_DM1_SAVE_DISK_MENU_NONE = 0,
    M11_DM1_SAVE_DISK_MENU_MAIN = 1,
    M11_DM1_SAVE_DISK_MENU_FORMAT_CONFIRM = 2
};

enum {
    M11_CSB_SAVE_DISK_MENU_NONE = 0,
    M11_CSB_SAVE_DISK_MENU_MAIN = 1,
    M11_CSB_SAVE_DISK_MENU_FORMAT_CONFIRM = 2
};

static void m11_dm1_show_save_disk_menu(M11_GameViewState* state) {
    if (!state) return;
    /* ReDMCSB LOADSAVE.C F0433:773-785.  The original physical save disk
     * is represented by Firestaff's per-DM1 local save namespace; the
     * choices and their order remain the original PC34 dialog contract. */
    M11_GameView_ShowDialogOverlayChoices(
        state,
        _("PUT THE GAME SAVE DISK IN ~"),
        _("SAVE GAME"),
        _("QUIT GAME"),
        _("FORMAT FLOPPY"),
        _("CANCEL"));
    state->dm1SaveDiskMenuStage = M11_DM1_SAVE_DISK_MENU_MAIN;
    m11_set_status(state, "SAVE DISK", "READY");
}

static M11_GameInputResult m11_dm1_write_save_disk(M11_GameViewState* state,
                                                    int quitAfterSave) {
    char savePath[M11_GAME_VIEW_PATH_CAPACITY];
    int saveResult;

    if (!state || !M11_GameView_GetQuickSavePath(state, savePath,
                                                  sizeof(savePath)) ||
        !dm1_v1_save_prepare_parent_directory_pc34(savePath)) {
        m11_set_status(state, "SAVE", "SAVE DIRECTORY UNAVAILABLE");
        return M11_GAME_INPUT_REDRAW;
    }
    saveResult = DM1_SaveGame(&state->world, savePath, state->dm1GameID,
                              quitAfterSave ? 0 : 1, state->dm1MusicOn);
    if (saveResult != DM1_SAVE_OK) {
        m11_set_status(state, "SAVE", DM1_SaveLoadErrorString(saveResult));
        return M11_GAME_INPUT_REDRAW;
    }
    state->lastSaveTick = (uint32_t)state->world.gameTick;
    M12_Config_SetLastSavePath(savePath);
    M11_GameView_DismissDialogOverlay(state);
    m11_set_status(state, "SAVE", "GAME SAVED");
    return quitAfterSave ? M11_GAME_INPUT_RETURN_TO_MENU : M11_GAME_INPUT_REDRAW;
}

static M11_GameInputResult m11_dm1_handle_save_disk_choice(
    M11_GameViewState* state,
    int choice) {
    int stage;

    if (!state || choice <= 0) return M11_GAME_INPUT_IGNORED;
    stage = state->dm1SaveDiskMenuStage;
    if (stage == M11_DM1_SAVE_DISK_MENU_MAIN) {
        switch (choice) {
        case 1:
            return m11_dm1_write_save_disk(state, 0);
        case 2:
            return m11_dm1_write_save_disk(state, 1);
        case 3:
            /* ReDMCSB F0432:423-440: a writable game-save disk first
             * requires an explicit format confirmation. */
            M11_GameView_ShowDialogOverlayChoices(
                state,
                _("THAT'S A GAME SAVE DISK!\nFORMAT DISK ANYWAY?"),
                _("OK"), _("CANCEL"), NULL, NULL);
            state->dm1SaveDiskMenuStage = M11_DM1_SAVE_DISK_MENU_FORMAT_CONFIRM;
            return M11_GAME_INPUT_REDRAW;
        case 4:
        default:
            M11_GameView_DismissDialogOverlay(state);
            m11_set_status(state, "SAVE DISK", "CANCELLED");
            return M11_GAME_INPUT_REDRAW;
        }
    }
    if (stage == M11_DM1_SAVE_DISK_MENU_FORMAT_CONFIRM) {
        if (choice == 1) {
            char savePath[M11_GAME_VIEW_PATH_CAPACITY];
            if (!M11_GameView_GetQuickSavePath(state, savePath,
                                               sizeof(savePath)) ||
                !dm1_v1_save_prepare_parent_directory_pc34(savePath)) {
                m11_set_status(state, "SAVE", "SAVE DIRECTORY UNAVAILABLE");
                return M11_GAME_INPUT_REDRAW;
            }
            /* The local namespace is the virtual save disk. Formatting it
             * clears the active save exactly like the source's F0432 path;
             * game data is never touched. */
            (void)remove(savePath);
            M11_GameView_DismissDialogOverlay(state);
            m11_set_status(state, "SAVE DISK", "FORMATTED");
            return M11_GAME_INPUT_REDRAW;
        }
        M11_GameView_DismissDialogOverlay(state);
        m11_set_status(state, "SAVE DISK", "CANCELLED");
        return M11_GAME_INPUT_REDRAW;
    }
    return M11_GAME_INPUT_IGNORED;
}

/* C140 enters the CSB save-disk dialog.  The Atari ST v2.1 source strings
 * at data offsets $50e..$54c give the four original choices and their order.
 * Firestaff's per-profile path is only the host transport for that physical
 * disk; it does not change the source menu contract. */
static void m11_csb_show_save_disk_menu(M11_GameViewState* state) {
    if (!state) return;
    M11_GameView_ShowDialogOverlayChoices(state,
        _("PUT THE GAME SAVE DISK IN ~"),
        _("LOAD SAVED GAME"), _("SAVE AND PLAY"),
        _("SAVE AND QUIT"), _("FORMAT FLOPPY"));
    state->csbDiskMenuActive = 1;
    state->csbDiskMenuSelectedChoice = 1;
    state->csbDiskMenuStage = M11_CSB_SAVE_DISK_MENU_MAIN;
    m11_set_status(state, "CSB", "DISK MENU");
    snprintf(state->inspectTitle, sizeof(state->inspectTitle), "CSB DISK MENU");
    snprintf(state->inspectDetail, sizeof(state->inspectDetail),
             "LOAD, SAVE, QUIT OR FORMAT");
}

static M11_GameInputResult m11_csb_handle_save_disk_choice(
    M11_GameViewState* state, int choice) {
    int ok = 0;
    int stage;

    if (!state || !state->csbDiskMenuActive || choice <= 0) {
        return M11_GAME_INPUT_IGNORED;
    }
    stage = state->csbDiskMenuStage;
    if (stage == M11_CSB_SAVE_DISK_MENU_MAIN) {
        switch (choice) {
        case 1:
            ok = M11_GameView_QuickLoad(state);
            break;
        case 2:
            ok = M11_GameView_QuickSave(state);
            break;
        case 3:
            if (M11_GameView_QuickSave(state)) {
                M11_GameView_DismissDialogOverlay(state);
                m11_set_status(state, "SAVE", "CSB SAVE AND QUIT");
                return M11_GAME_INPUT_RETURN_TO_MENU;
            }
            break;
        case 4:
            M11_GameView_ShowDialogOverlayChoices(
                state,
                _("THAT'S A GAME SAVE DISK!\nFORMAT DISK ANYWAY?"),
                _("OK"), _("CANCEL"), NULL, NULL);
            state->csbDiskMenuStage = M11_CSB_SAVE_DISK_MENU_FORMAT_CONFIRM;
            state->csbDiskMenuSelectedChoice = 1;
            return M11_GAME_INPUT_REDRAW;
        default:
            return M11_GAME_INPUT_IGNORED;
        }
        if (ok) {
            state->dialogSelectedChoice = choice;
            M11_GameView_DismissDialogOverlay(state);
            return M11_GAME_INPUT_REDRAW;
        }
        return M11_GAME_INPUT_REDRAW;
    }
    if (stage == M11_CSB_SAVE_DISK_MENU_FORMAT_CONFIRM) {
        if (choice == 1) {
            char save_path[M11_GAME_VIEW_PATH_CAPACITY];
            if (!M11_GameView_GetQuickSavePath(state, save_path,
                                               sizeof(save_path)) ||
                !dm1_v1_save_prepare_parent_directory_pc34(save_path)) {
                m11_set_status(state, "SAVE", "SAVE DIRECTORY UNAVAILABLE");
                return M11_GAME_INPUT_REDRAW;
            }
            /* F0432 formats the selected game-save medium. The host save
             * namespace is that medium; game data and unrelated saves stay
             * untouched. */
            (void)remove(save_path);
            M11_GameView_DismissDialogOverlay(state);
            m11_set_status(state, "SAVE DISK", "FORMATTED");
            return M11_GAME_INPUT_REDRAW;
        }
        if (choice == 2) {
            M11_GameView_DismissDialogOverlay(state);
            m11_set_status(state, "SAVE DISK", "CANCELLED");
            return M11_GAME_INPUT_REDRAW;
        }
        return M11_GAME_INPUT_IGNORED;
    }
    return M11_GAME_INPUT_IGNORED;
}

static M11_GameInputResult m11_csb_cancel_save_disk_menu(
    M11_GameViewState* state) {
    if (!state || !state->csbDiskMenuActive) return M11_GAME_INPUT_IGNORED;
    {
        state->dialogSelectedChoice = 0;
        M11_GameView_DismissDialogOverlay(state);
        m11_set_status(state, "SAVE DISK", "CANCELLED");
    }
    return M11_GAME_INPUT_REDRAW;
}

M11_GameInputResult M11_GameView_HandleInput(M11_GameViewState* state,
                                             M12_MenuInput input) {
    uint8_t command = CMD_NONE;
    const char* label = "NONE";
    if (!state || !state->active) {
        return M11_GAME_INPUT_IGNORED;
    }

    /* Session-timer forced-pause confirm dialog: ENTER returns to the
     * launcher; BACK dismisses the dialog (the runtime keeps the
     * FORCED_PAUSE latch so the next tick re-arms the dialog unless
     * the user picks ENTER).  This sits ahead of the regular dialog
     * and return-to-menu-confirm branches so it gets first refusal
     * on input.  See include/session_timer_runtime.h +
     * src/shared/session_timer_runtime.c + the corresponding
     * M11_GameView_Draw overlay branch. */
    if (state->sessionTimerForcedPauseDialogActive) {
        if (input == M12_MENU_INPUT_ACCEPT ||
            input == M12_MENU_INPUT_ACTION) {
            M11_GameView_ClearSessionTimerForcedPause(state);
            m11_set_status(state, "TIMER", "RETURN TO LAUNCHER");
            return M11_GAME_INPUT_RETURN_TO_MENU;
        }
        if (input == M12_MENU_INPUT_BACK) {
            M11_GameView_ClearSessionTimerForcedPause(state);
            m11_set_status(state, "TIMER", "DISMISSED");
            return M11_GAME_INPUT_REDRAW;
        }
        return M11_GAME_INPUT_IGNORED;
    }

    /* The runtime graphics panel is presentation-only and owns its keys
     * while visible. Keep it ahead of source-specific dispatch so changing
     * a filter or scale cannot accidentally move the party. */
    if (input == M12_MENU_INPUT_GRAPHICS_POPUP || state->graphicsPopupActive) {
        return m11_graphics_popup_handle_input(state, input)
            ? M11_GAME_INPUT_REDRAW : M11_GAME_INPUT_IGNORED;
    }

    /* Dialog overlay: text plaques dismiss; return-to-menu confirm requires an explicit choice. */
    if (state->dialogOverlayActive) {
        if (state->csbDiskMenuActive) {
            if (input == M12_MENU_INPUT_UP || input == M12_MENU_INPUT_DOWN) {
                int delta = input == M12_MENU_INPUT_UP ? -1 : 1;
                int count = state->dialogChoiceCount > 0 ?
                    state->dialogChoiceCount : 1;
                state->csbDiskMenuSelectedChoice =
                    ((state->csbDiskMenuSelectedChoice - 1 + delta + count) % count) + 1;
                return M11_GAME_INPUT_REDRAW;
            }
            if (input == M12_MENU_INPUT_BACK) {
                return m11_csb_cancel_save_disk_menu(state);
            }
            if (input == M12_MENU_INPUT_ACCEPT || input == M12_MENU_INPUT_ACTION) {
                return m11_csb_handle_save_disk_choice(
                    state, state->csbDiskMenuSelectedChoice);
            }
            return M11_GAME_INPUT_IGNORED;
        }
        if (state->dm1SaveDiskMenuStage != M11_DM1_SAVE_DISK_MENU_NONE) {
            if (input == M12_MENU_INPUT_BACK) {
                return m11_dm1_handle_save_disk_choice(
                    state,
                    state->dm1SaveDiskMenuStage ==
                        M11_DM1_SAVE_DISK_MENU_FORMAT_CONFIRM ? 2 : 4);
            }
            if (input == M12_MENU_INPUT_ACCEPT || input == M12_MENU_INPUT_ACTION) {
                return m11_dm1_handle_save_disk_choice(state, 1);
            }
            return M11_GAME_INPUT_IGNORED;
        }
        if (state->returnToMenuConfirmActive) {
            if (input == M12_MENU_INPUT_BACK) {
                int wasGuard = state->quitGuardActive;
                state->quitGuardActive = 0;
                M11_GameView_DismissDialogOverlay(state);
                m11_set_status(state, "RETURN",
                               wasGuard ? "CANCELLED (UNSAVED)" : "CANCELLED");
                return M11_GAME_INPUT_REDRAW;
            }
            if (input == M12_MENU_INPUT_ACCEPT || input == M12_MENU_INPUT_ACTION) {
                /* G2018 quit-guard branch: SAVE-AND-QUIT must persist the game
                 * before leaving (ReDMCSB LOADSAVE.C:1382-1384 invokes
                 * F0078_MOUSE_DisableScreenUpdate + sets Quit only after the
                 * save path has been taken; we collapse that into a direct
                 * DM1_SaveGame call so the same invariant holds). */
                if (state->quitGuardActive) {
                    char savePath[M11_GAME_VIEW_PATH_CAPACITY];
                    if (M11_GameView_GetQuickSavePath(state, savePath,
                                                      sizeof(savePath)) &&
                        dm1_v1_save_prepare_parent_directory_pc34(savePath)) {
                        int saveResult = DM1_SaveGame(&state->world, savePath,
                                                      state->dm1GameID, 0,
                                                      state->dm1MusicOn);
                        if (saveResult == DM1_SAVE_OK) {
                            state->lastSaveTick =
                                (uint32_t)state->world.gameTick;
                            M12_Config_SetLastSavePath(savePath);
                        } else {
                            m11_set_status(state, "SAVE",
                                           DM1_SaveLoadErrorString(saveResult));
                            return M11_GAME_INPUT_REDRAW;
                        }
                    } else {
                        m11_set_status(state, "SAVE", "SAVE DIRECTORY UNAVAILABLE");
                        return M11_GAME_INPUT_REDRAW;
                    }
                    state->quitGuardActive = 0;
                }
                state->dialogSelectedChoice = 1;
                M11_GameView_DismissDialogOverlay(state);
                m11_set_status(state, "RETURN", "BACK TO LAUNCHER");
                return M11_GAME_INPUT_RETURN_TO_MENU;
            }
            return M11_GAME_INPUT_IGNORED;
        }
        if (input == M12_MENU_INPUT_BACK) {
            M11_GameView_DismissDialogOverlay(state);
            return M11_GAME_INPUT_REDRAW;
        }
        if (input == M12_MENU_INPUT_ACCEPT && state->dialogChoiceCount > 0) {
            state->dialogSelectedChoice = 1;
            M11_GameView_DismissDialogOverlay(state);
            return M11_GAME_INPUT_REDRAW;
        }
        if (input != M12_MENU_INPUT_NONE) {
            M11_GameView_DismissDialogOverlay(state);
            return M11_GAME_INPUT_REDRAW;
        }
        return M11_GAME_INPUT_IGNORED;
    }

    /* Session-timer reminder overlay: any non-NONE input clears the
     * reminder banner so it does not block gameplay.  The runtime's
     * re-arm window prevents the banner from re-firing on the next
     * single tap. */
    if (state->sessionTimerReminderOverlayActive &&
        input != M12_MENU_INPUT_NONE) {
        M11_GameView_AcknowledgeSessionTimerReminder(state);
        return M11_GAME_INPUT_REDRAW;
    }

    if (!state->gameWon && !state->mapOverlayActive &&
        !state->inventoryPanelActive) {
        m11_mark_v1_movement_arrow_visual(state, input);
    }

    if (state->sourceKind == M11_GAME_SOURCE_CSB_BOOT) {
        CSB_V1_BootStartupHostInputDispatchReceipt_PC34 dispatch_receipt;
        M11_GameInputResult fmtowns_result =
            m11_csb_handle_fmtowns_game_entrance_input(state, input);
        if (fmtowns_result != M11_GAME_INPUT_IGNORED) {
            return fmtowns_result;
        }
        if (m11_csb_boot_runtime_startup_keyboard_dispatch(
                state,
                (int)input,
                &dispatch_receipt) &&
            dispatch_receipt.valid &&
            dispatch_receipt.startup_active) {
            return m11_csb_startup_apply_host_input_dispatch_receipt(
                state,
                &dispatch_receipt);
        }
    }

    if (m11_source_is_csb(state)) {
        /* COMMAND.C's F1-F4, movement, and disk commands all resolve against
         * the current GAMEBLOCK party.  Refresh only after startup input has
         * had its own source dispatcher, keeping live keyboard and pointer
         * command surfaces on the same authoritative mirror. */
        if (state->csbBootProfile) {
            m11_sync_csb_state_from_boot_profile(state,
                                                 state->csbBootProfile);
        }
        M11_GameInputResult csbResult = m11_csb_handle_source_keyboard(state, input);
        if (csbResult != M11_GAME_INPUT_IGNORED ||
            input == M12_MENU_INPUT_FREEZE_TOGGLE ||
            input == M12_MENU_INPUT_DISK_MENU ||
            (input >= M12_MENU_INPUT_CHAMPION_1_INVENTORY &&
             input <= M12_MENU_INPUT_CHAMPION_4_INVENTORY) ||
            state->csbGameFrozen ||
            state->csbDiskMenuActive) {
            return csbResult;
        }
    }
    if (state->sourceKind == M11_GAME_SOURCE_CSB_BOOT) {
        if (!state->csbBootProfile) {
            return M11_GAME_INPUT_IGNORED;
        }
        if (input == M12_MENU_INPUT_BACK) {
            m11_set_status(state, "RETURN", "BACK TO LAUNCHER");
            return M11_GAME_INPUT_RETURN_TO_MENU;
        }
        return M11_GAME_INPUT_IGNORED;
    }

    if (state->sourceKind == M11_GAME_SOURCE_NEXUS_DGN) {
        int cmd = NEXUS_CMD_NONE;
        if (!state->nexusEngine) {
            return M11_GAME_INPUT_IGNORED;
        }
        if (state->nexusState.title_active) {
            Nexus_V1_LauncherRuntimeStartupSnapshot snapshot;
            Nexus_V1_StartupTitleExecution execution;
            Nexus_V1_StartupHostActionReceipt receipt;
            M11_GameInputResult result;
            m11_nexus_runtime_startup_snapshot(state, &snapshot);
            if (!nexus_v1_launcher_startup_execute_title_firestaff_input_from_snapshot(
                    &snapshot,
                    (int)input,
                    &execution,
                    &receipt)) {
                return M11_GAME_INPUT_IGNORED;
            }
            result = m11_nexus_apply_startup_action_receipt(state, &receipt);
            /* MENU.BPK may still be correctly fail-closed on PRS3 evidence,
             * but that must not leave a completed real TITLE.CG sequence
             * indefinitely waiting for an unreachable menu route. */
            if (input == M12_MENU_INPUT_ACCEPT &&
                state->nexusState.title_active &&
                nexus_title_full_boot_start_ready(state->nexusState.title_frame)) {
                state->nexusState.title_active = 0;
                state->nexusState.startup_save_select_active = 0;
                state->nexusState.champion_select_active = 0;
                m11_set_status(state, "ASSETS", "MENU.BPK PRS3 CAPTURE REQUIRED");
                return M11_GAME_INPUT_REDRAW;
            }
            return result;
        }
        if (state->nexusState.startup_save_select_active) {
            return m11_nexus_startup_handle_save_input(state, input);
        }
        if (state->nexusState.champion_select_active) {
            Nexus_V1_StartupHostActionReceipt receipt;
            Nexus_V1_StartupDrawCommand startup_commands[80];
            Nexus_V1_DgnRenderCommand commands[NEXUS_V1_DGN_VIEW_RENDER_MAX_COMMANDS];
            Nexus_V1_StartupHostCallerReceipt host_caller_receipt;
            M11_GameInputResult result;
            if (!m11_nexus_refresh_startup_host_caller(
                    state,
                    input,
                    startup_commands,
                    (int)(sizeof(startup_commands) /
                          sizeof(startup_commands[0])),
                    commands,
                    (int)(sizeof(commands) / sizeof(commands[0])),
                    &host_caller_receipt)) {
                return M11_GAME_INPUT_IGNORED;
            }
            /* The host caller evaluates the champion command while producing
             * the canonical full-start package.  Applying its embedded action
             * receipt keeps M11 from evaluating an ACTION start a second time. */
            receipt = host_caller_receipt.ownership.runtime_route
                .host_action_receipt;
            result = m11_nexus_apply_startup_action_receipt(state, &receipt);
            /* A real MENU.BPK route can be correctly rejected while PRS3
             * remains undecoded.  Do not strand the user in the deliberately
             * no-draw dungeon state: report the source-backed blocker and
             * return to the launcher, where another game or data package can
             * be selected. */
            if (input == M12_MENU_INPUT_ACTION &&
                (state->nexusState.startup_dgn_render_blocked ||
                 state->nexusState.startup_dgn_viewport_host_blocks_runtime)) {
                if (!state->nexusState.startup_prs3_blocker_consumed) {
                    state->nexusState.champion_select_active = 0;
                }
                m11_set_status(state, "ASSETS", "MENU.BPK PRS3 TRACE REQUIRED");
                return M11_GAME_INPUT_RETURN_TO_MENU;
            }
            return result;
        }
        if (input == M12_MENU_INPUT_BACK) {
            m11_set_status(state, "RETURN", "BACK TO LAUNCHER");
            return M11_GAME_INPUT_RETURN_TO_MENU;
        }
        switch (input) {
            case M12_MENU_INPUT_UP:
                cmd = NEXUS_CMD_FORWARD;
                break;
            case M12_MENU_INPUT_DOWN:
                cmd = NEXUS_CMD_BACKWARD;
                break;
            case M12_MENU_INPUT_TURN_LEFT:
                cmd = NEXUS_CMD_TURN_LEFT;
                break;
            case M12_MENU_INPUT_TURN_RIGHT:
                cmd = NEXUS_CMD_TURN_RIGHT;
                break;
            case M12_MENU_INPUT_LEFT:
            case M12_MENU_INPUT_STRAFE_LEFT:
                cmd = NEXUS_CMD_STRAFE_LEFT;
                break;
            case M12_MENU_INPUT_RIGHT:
            case M12_MENU_INPUT_STRAFE_RIGHT:
                cmd = NEXUS_CMD_STRAFE_RIGHT;
                break;
            default:
                break;
        }
        if (cmd == NEXUS_CMD_NONE || !state->nexusEngine->mechanics) {
            return M11_GAME_INPUT_IGNORED;
        }
        if (nexus_mechanics_push_command(state->nexusEngine->mechanics,
                                         cmd) != 0) {
            return M11_GAME_INPUT_IGNORED;
        }
        nexus_v1_tick(state->nexusEngine);
        if (state->nexusEngine->mechanics) {
            state->nexusEngine->game.party_x =
                state->nexusEngine->mechanics->party_x;
            state->nexusEngine->game.party_y =
                state->nexusEngine->mechanics->party_y;
            state->nexusEngine->game.party_dir =
                state->nexusEngine->mechanics->party_dir;
        }
        state->nexusState.tick_count = state->nexusEngine->game.tick_count;
        state->nexusState.level_loaded = state->nexusEngine->level_loaded;
        state->nexusState.party_x = state->nexusEngine->game.party_x;
        state->nexusState.party_y = state->nexusEngine->game.party_y;
        state->nexusState.party_dir = state->nexusEngine->game.party_dir;
        m11_set_status(state, "MOVE", "NEXUS COMMAND");
        return M11_GAME_INPUT_REDRAW;
    }

    if (state->sourceKind == M11_GAME_SOURCE_THERON_TRACK02) {
        Theron_V1_World* world = (Theron_V1_World*)state->theronWorld;
        if (!world) {
            return M11_GAME_INPUT_IGNORED;
        }
        if (state->theronState.startup_phase != THERON_STARTUP_PHASE_IN_DUNGEON ||
            !state->theronState.level_loaded) {
            Theron_V1_BootStartupFullStartReceipt full_start;
            Theron_StartupActionHostReceipt receipt;

            /* Keep the failure path deterministic: the receipt is consumed
             * below even when rebuilding the full-start package fails. */
            theron_v1_startup_action_host_receipt_init(&receipt);

            if (state->theronState.startup_phase == THERON_STARTUP_PHASE_TITLE &&
                state->theronState.startup_title_animation_tick <
                    (M11_THERON_STARTUP_TITLE_FRAME_COUNT *
                     M11_THERON_STARTUP_TITLE_FRAME_TICKS)) {
                return M11_GAME_INPUT_REDRAW;
            }
            if (!m11_theron_boot_runtime_startup_full_start_receipt(
                    state,
                    NULL,
                    &full_start) ||
                !theron_v1_boot_startup_execute_input_from_full_start_receipt(
                    &full_start,
                    theron_v1_startup_input_from_firestaff_menu_code(
                        (int)input),
                    &receipt)) {
                return m11_theron_apply_startup_action_host_receipt(
                    state,
                    &receipt);
            }
            return m11_theron_apply_startup_action_host_receipt(state, &receipt);
        }
        /* v2.8.x: M11 no longer maps M12 tokens to Theron mechanics here.
         * The boot-layer runtime input facade owns the token-to-action
         * mapping, strafe rejection, move/turn/tick calls, and exit handling.
         * Source: THQUEST.ASM T520/T560/T600/T700; ReDMCSB COMMAND.C F7015 +
         * MOVESENS.C F0267/F0268 (DM-family analogue). */
        {
            Theron_V1_BootRuntimeInputReceipt receipt;
            if (!theron_v1_boot_runtime_handle_m12_input(
                    world,
                    state->theronBootProfile,
                    (int)input,
                    &receipt)) {
                return M11_GAME_INPUT_IGNORED;
            }
            state->theronState.party_x = receipt.party_x;
            state->theronState.party_y = receipt.party_y;
            state->theronState.party_dir = receipt.party_dir;
            state->theronState.tick_count = receipt.tick_count;
            if (receipt.result ==
                THERON_V1_BOOT_RUNTIME_INPUT_RESULT_EXIT_DUNGEON) {
                return m11_theron_apply_startup_action_host_receipt(
                    state,
                    &receipt.exit_receipt);
            }
            m11_set_status(state, receipt.status_scope, receipt.status);
            if (receipt.result ==
                THERON_V1_BOOT_RUNTIME_INPUT_RESULT_IGNORED) {
                return M11_GAME_INPUT_IGNORED;
            }
            return M11_GAME_INPUT_REDRAW;
        }
    }

    /* DM2 V1 input bridge.  M11 receives normalized keyboard/touch tokens;
     * DM2 owns the runtime movement and collision result.  Turn input is a
     * turn-only boundary instead of dm2_v1_runtime_move() so Q/E/Home/End do
     * not walk into the side cell.  Source: SKULL.ASM T048 input dispatch,
     * SKULL.ASM T520 party movement. */
    if (state->sourceKind == M11_GAME_SOURCE_DM2_BOOT) {
        int dir;
        int result;
        if (!state->dm2World) {
            return M11_GAME_INPUT_IGNORED;
        }
        if (state->dm2State.startup_menu_active) {
            return m11_dm2_startup_handle_input(state, input);
        }
        if (state->dm2SaveDialoguePanelActive) {
            if (input == M12_MENU_INPUT_BACK) {
                state->dm2SaveDialoguePanelActive = 0;
                return M11_GAME_INPUT_REDRAW;
            }
            return M11_GAME_INPUT_IGNORED;
        }
        if (input == M12_MENU_INPUT_BACK) {
            if (state->inventoryPanelActive) {
                state->inventoryPanelActive = 0;
                return M11_GAME_INPUT_REDRAW;
            }
            m11_set_status(state, "RETURN", "BACK TO LAUNCHER");
            return M11_GAME_INPUT_RETURN_TO_MENU;
        }
        if (input == M12_MENU_INPUT_INVENTORY_TOGGLE) {
            if (state->sourceKind == M11_GAME_SOURCE_DM2_BOOT) {
                /* SKProject CHANGE_VIEWPORT_TO_INVENTORY owns a DM2-specific
                 * GDAT/CHAMPIONS layout and event table. The shared M11
                 * inventory panel is built from DM1 GRAPHICS.DAT slots, so
                 * it cannot stand in for that source surface. */
                state->inventoryPanelActive = 0;
                m11_set_status(state, "INVENTORY",
                               "DM2 INVENTORY GDAT REQUIRED");
                return M11_GAME_INPUT_REDRAW;
            }
            state->mapOverlayActive = 0;
            M11_GameView_ToggleInventoryPanel(state);
            return M11_GAME_INPUT_REDRAW;
        }
        if (input == M12_MENU_INPUT_SAVE_GAME) {
            if (M11_GameView_QuickSave(state)) {
                return M11_GAME_INPUT_REDRAW;
            }
            return M11_GAME_INPUT_REDRAW;
        }
        if (state->inventoryPanelActive) {
            return input == M12_MENU_INPUT_NONE
                       ? M11_GAME_INPUT_IGNORED
                       : M11_GAME_INPUT_REDRAW;
        }
        m11_sync_dm2_state_from_runtime(state);
        dir = state->dm2State.party_dir & 3;
        if (input == M12_MENU_INPUT_TURN_LEFT ||
            input == M12_MENU_INPUT_LEFT) {
            DM2_V1_BootRuntimeReceipt receipt;
            result = dm2_v1_boot_runtime_turn(
                (DM2_V1_BootProfile *)state->dm2BootProfile,
                -1,
                &receipt) ? receipt.operation_result : -1;
            if (result == 0) {
                m11_sync_dm2_state_from_runtime(state);
                m11_set_status(state, NULL, NULL);
                return M11_GAME_INPUT_REDRAW;
            }
            return M11_GAME_INPUT_IGNORED;
        }
        if (input == M12_MENU_INPUT_TURN_RIGHT ||
            input == M12_MENU_INPUT_RIGHT) {
            DM2_V1_BootRuntimeReceipt receipt;
            result = dm2_v1_boot_runtime_turn(
                (DM2_V1_BootProfile *)state->dm2BootProfile,
                1,
                &receipt) ? receipt.operation_result : -1;
            if (result == 0) {
                m11_sync_dm2_state_from_runtime(state);
                m11_set_status(state, NULL, NULL);
                return M11_GAME_INPUT_REDRAW;
            }
            return M11_GAME_INPUT_IGNORED;
        }
        if (input == M12_MENU_INPUT_UP) {
            DM2_V1_BootRuntimeReceipt receipt;
            (void)dm2_v1_boot_runtime_move(
                (DM2_V1_BootProfile *)state->dm2BootProfile,
                dir,
                &receipt);
            result = receipt.operation_result;
            m11_sync_dm2_state_from_runtime(state);
            m11_set_status(state, NULL, NULL);
            return M11_GAME_INPUT_REDRAW;
        }
        if (input == M12_MENU_INPUT_DOWN) {
            DM2_V1_BootRuntimeReceipt receipt;
            (void)dm2_v1_boot_runtime_move(
                (DM2_V1_BootProfile *)state->dm2BootProfile,
                (dir + 2) & 3,
                &receipt);
            result = receipt.operation_result;
            m11_sync_dm2_state_from_runtime(state);
            m11_set_status(state, NULL, NULL);
            return M11_GAME_INPUT_REDRAW;
        }
        if (input == M12_MENU_INPUT_STRAFE_LEFT) {
            DM2_V1_BootRuntimeReceipt receipt;
            (void)dm2_v1_boot_runtime_move(
                (DM2_V1_BootProfile *)state->dm2BootProfile,
                (dir + 3) & 3,
                &receipt);
            result = receipt.operation_result;
            m11_sync_dm2_state_from_runtime(state);
            m11_set_status(state, NULL, NULL);
            return M11_GAME_INPUT_REDRAW;
        }
        if (input == M12_MENU_INPUT_STRAFE_RIGHT) {
            DM2_V1_BootRuntimeReceipt receipt;
            (void)dm2_v1_boot_runtime_move(
                (DM2_V1_BootProfile *)state->dm2BootProfile,
                (dir + 1) & 3,
                &receipt);
            result = receipt.operation_result;
            m11_sync_dm2_state_from_runtime(state);
            m11_set_status(state, NULL, NULL);
            return M11_GAME_INPUT_REDRAW;
        }
        if (input == M12_MENU_INPUT_ACCEPT ||
            input == M12_MENU_INPUT_ACTION) {
            DM2_V1_BootRuntimeActionReceipt receipt;
            if (!dm2_v1_boot_runtime_action_front_cell(
                    (DM2_V1_BootProfile *)state->dm2BootProfile,
                    dir,
                    &receipt)) {
                return M11_GAME_INPUT_IGNORED;
            }
            if (receipt.reset_shop_selection) {
                state->dm2ShopSelectedStockIndex = 0;
                state->dm2ShopSelectedInventoryIndex = 0;
            }
            if (receipt.action_kind == DM2_V1_BOOT_ACTION_SHOP) {
                /* SKProject renders a shop from the active wall actuator:
                 * _32cb_0f82_SHOP_GLASS resolves WALL_GFX image offsets,
                 * dt08 item lists, and the navigation-board overlay before
                 * it accepts interaction. The former M11 catalog used fixed
                 * host rectangles and text instead. Do not retain its
                 * transaction state while the actual G1 -> WALL_GFX chain
                 * remains unbound. */
                (void)dm2_v1_shop_leave(dm2_v1_shop_get_active_shop());
                m11_set_status(state, NULL, NULL);
                m11_sync_dm2_state_from_runtime(state);
                return M11_GAME_INPUT_REDRAW;
            }
            if (receipt.status) {
                m11_set_status(state, receipt.status_scope, receipt.status);
            } else {
                m11_set_status(state, NULL, NULL);
            }
            if (receipt.inspect_title || receipt.inspect_text) {
                m11_set_inspect_readout(
                    state,
                    receipt.inspect_title ? receipt.inspect_title
                                          : "DM2",
                    receipt.inspect_text ? receipt.inspect_text
                                         : "");
            }
            m11_sync_dm2_state_from_runtime(state);
            return M11_GAME_INPUT_REDRAW;
        }
        return M11_GAME_INPUT_IGNORED;
    }

    /* Source-backed champion mirror panel: CLIKCHAM routes
     * C160/C161/C162 through the resurrect/reincarnate/cancel panel.
     * M11 maps ACTION/ACCEPT to the default resurrect choice for now
     * and BACK to cancel; the public confirm API keeps probes explicit. */
    if (m11_dm1_hoc_menu_route_blocks_normal_input(state)) {
        if (state->candidateMirrorRenameActive) {
            if (!m11_dm1_hoc_c027_input_material_ready(state)) {
                return M11_GAME_INPUT_IGNORED;
            }
            if (input == M12_MENU_INPUT_BACK) {
                return M11_GameView_ApplyMirrorCandidateRenameCommand(
                           state,
                           DM1_V1_RESURRECTION_RENAME_UI_COMMAND_BACKSPACE_PC34_COMPAT)
                           ? M11_GAME_INPUT_REDRAW
                           : M11_GAME_INPUT_IGNORED;
            }
            if (input == M12_MENU_INPUT_ACCEPT || input == M12_MENU_INPUT_ACTION) {
                int sensorIndex;
                if (!m11_front_mirror_first_sensor_index_pc34(state,
                                                               &sensorIndex)) {
                    return M11_GAME_INPUT_IGNORED;
                }
                return M11_GameView_ApplyMirrorCandidateRenameCommand(
                           state,
                           DM1_V1_RESURRECTION_RENAME_UI_COMMAND_OK_PC34_COMPAT)
                           ? M11_GAME_INPUT_REDRAW
                           : M11_GAME_INPUT_IGNORED;
            }
            return M11_GAME_INPUT_IGNORED;
        }
        if (!m11_dm1_hoc_c040_input_material_ready(state)) {
            return M11_GAME_INPUT_IGNORED;
        }
        if (input == M12_MENU_INPUT_BACK) {
            return M11_GameView_CancelMirrorCandidate(state)
                       ? M11_GAME_INPUT_REDRAW
                       : M11_GAME_INPUT_IGNORED;
        }
        if (input == M12_MENU_INPUT_ACCEPT || input == M12_MENU_INPUT_ACTION) {
            int sensorIndex;
            if (!m11_front_mirror_first_sensor_index_pc34(state,
                                                           &sensorIndex)) {
                return M11_GAME_INPUT_IGNORED;
            }
            return M11_GameView_ConfirmMirrorCandidate(state, 0)
                       ? M11_GAME_INPUT_REDRAW
                       : M11_GAME_INPUT_IGNORED;
        }
        return M11_GAME_INPUT_IGNORED;
    }

    /* Endgame: only ESC (return to menu) once the final endgame screen
     * exists. ReDMCSB ENDGAME.C F0446 lines 939-961 blocks in its
     * victory-text/final delay before F0444 installs the final endgame
     * presentation path, so complete-FUSE delay playback ignores input. */
    if (state->gameWon) {
        DM1_V1_EndgamePresentationInputPc34 endgameInput = {0};
        DM1_V1_EndgamePresentationDecisionPc34 endgameDecision;
        endgameInput.gameWon = state->gameWon;
        endgameInput.finalHandoffReady = state->endgameFinalHandoffReady;
        endgameInput.endgameCalledWithTrue = state->endgameCalledWithTrue;
        endgameInput.finalDelayTicks = state->endgameFinalDelayTicks;
        endgameInput.fuseDelayTicks = state->endgameFuseSequenceDelayTicks;
        endgameInput.fuseDelayRemainingTicks = state->endgameFuseSequenceDelayRemainingTicks;
        endgameInput.textMessageDelayTicks = state->endgameTextMessageDelayTicks;
        endgameInput.restartAllowed = state->endgameRestartAllowed;
        endgameInput.backRequested = (input == M12_MENU_INPUT_BACK);
        dm1_v1_endgame_presentation_decide_pc34(&endgameInput, &endgameDecision);
        if (endgameDecision.action ==
            DM1_V1_ENDGAME_PRESENTATION_ACTION_RETURN_TO_MENU_PC34) {
            m11_set_status(state, "RETURN", "BACK TO LAUNCHER");
            return M11_GAME_INPUT_RETURN_TO_MENU;
        }
        return M11_GAME_INPUT_IGNORED;
    }

    if (state->partyDead) {
        if (input == M12_MENU_INPUT_BACK) {
            m11_set_status(state, "RETURN", "BACK TO LAUNCHER");
            return M11_GAME_INPUT_RETURN_TO_MENU;
        }
        return M11_GAME_INPUT_IGNORED;
    }

    /* ReDMCSB COMMAND.C switches resting play to the dedicated
     * G0450/G0460 PartyResting input lists after C145_COMMAND_REST:
     * movement/action/menu commands are no longer routed, and only
     * C146_COMMAND_WAKE_UP (plus the platform freeze/menu escape paths)
     * leaves the rest screen.  Keep Firestaff's R binding as the local
     * wake key, and accept Enter/ACCEPT as the source-backed keyboard
     * wake equivalent; do not spend a movement tick while resting. */
    if (state->resting) {
        if (input == M12_MENU_INPUT_REST_TOGGLE ||
            input == M12_MENU_INPUT_ACCEPT) {
            m11_wake_party_from_rest(state);
            m11_log_event(state, M11_COLOR_LIGHT_BLUE, "T%u: WOKE UP",
                          (unsigned int)state->world.gameTick);
            m11_set_status(state, "REST", "PARTY AWAKE");
            snprintf(state->inspectTitle, sizeof(state->inspectTitle), "AWAKE");
            snprintf(state->inspectDetail, sizeof(state->inspectDetail),
                     "REST ENDED. RESUME EXPLORING.");
            return M11_GAME_INPUT_REDRAW;
        }
        if (input != M12_MENU_INPUT_NONE) {
            return M11_GAME_INPUT_IGNORED;
        }
    }

    /* Map/inventory toggle.
     *
     * The full-screen map overlay is a Firestaff convenience/debug
     * surface, not a source-backed DM1 V1 UI (see
     * PARITY_MATRIX_DM1_V1.md pass 102).  Keep it available to debug
     * HUD sessions, but ignore the M-key in default V1 chrome mode so
     * normal parity play cannot enter an invented screen. */
    if (input == M12_MENU_INPUT_MAP_TOGGLE) {
        if (m11_v1_chrome_mode_enabled(state) && !state->showDebugHUD) {
            return M11_GAME_INPUT_IGNORED;
        }
        state->inventoryPanelActive = 0;
        M11_GameView_ToggleMapOverlay(state);
        return M11_GAME_INPUT_REDRAW;
    }
    if (input == M12_MENU_INPUT_INVENTORY_TOGGLE) {
        state->mapOverlayActive = 0;
        M11_GameView_ToggleInventoryPanel(state);
        return M11_GAME_INPUT_REDRAW;
    }

    /* While an overlay is open, block gameplay input; ESC/BACK closes it. */
    if (state->mapOverlayActive || state->inventoryPanelActive) {
        if (input == M12_MENU_INPUT_BACK) {
            state->mapOverlayActive = 0;
            state->inventoryPanelActive = 0;
            return M11_GAME_INPUT_REDRAW;
        }
        /* In inventory panel, accept up/down/left/right to navigate slots */
        if (state->inventoryPanelActive) {
            if (input == M12_MENU_INPUT_UP && state->inventorySelectedSlot > 0) {
                state->inventorySelectedSlot--;
                return M11_GAME_INPUT_REDRAW;
            }
            if (input == M12_MENU_INPUT_DOWN && state->inventorySelectedSlot < 20) {
                state->inventorySelectedSlot++;
                return M11_GAME_INPUT_REDRAW;
            }
        }
        return M11_GAME_INPUT_IGNORED;
    }

    switch (input) {
        case M12_MENU_INPUT_UP:
            command = m11_forward_command_for_direction(state->world.party.direction);
            label = "FORWARD";
            break;
        case M12_MENU_INPUT_DOWN:
            command = m11_backward_command_for_direction(state->world.party.direction);
            label = "BACKSTEP";
            break;
        /* v2.8.x: arrow Left/Right now mean strafe (original DM1 PC
         * 3.4 convention; see also the user's keyboard-mapping
         * request).  TURN_LEFT/TURN_RIGHT come from Home / End / Q /
         * E / KP_4 / KP_6.  Defensive fallback for any caller still
         * passing M12_MENU_INPUT_LEFT/RIGHT into the gameplay path
         * (the menu-click arrow route at m11_dispatch_arrow_command
         * uses these tokens for menu cycling and should NOT route
         * into gameplay, but a defensive default keeps the legacy
         * behaviour consistent with what was documented). */
        case M12_MENU_INPUT_LEFT:
        case M12_MENU_INPUT_TURN_LEFT:
            command = CMD_TURN_LEFT;
            label = "TURN LEFT";
            break;
        case M12_MENU_INPUT_RIGHT:
        case M12_MENU_INPUT_TURN_RIGHT:
            command = CMD_TURN_RIGHT;
            label = "TURN RIGHT";
            break;
        case M12_MENU_INPUT_STRAFE_LEFT:
            command = m11_strafe_left_command_for_direction(state->world.party.direction);
            label = "STRAFE LEFT";
            break;
        case M12_MENU_INPUT_STRAFE_RIGHT:
            command = m11_strafe_right_command_for_direction(state->world.party.direction);
            label = "STRAFE RIGHT";
            break;
        case M12_MENU_INPUT_ACCEPT:
            if (m11_inspect_front_cell(state)) {
                return M11_GAME_INPUT_REDRAW;
            }
            return M11_GAME_INPUT_IGNORED;
        case M12_MENU_INPUT_ACTION:
            if (m11_front_cell_has_attack_target(state)) {
                command = CMD_ATTACK;
                label = "ATTACK";
                break;
            }
            if (m11_front_cell_is_door(state)) {
                if (m11_toggle_front_door(state)) {
                    return M11_GAME_INPUT_REDRAW;
                }
                return M11_GAME_INPUT_IGNORED;
            }
            command = CMD_NONE;
            label = "WAIT";
            break;
        case M12_MENU_INPUT_CYCLE_CHAMPION:
            if (m11_cycle_active_champion(state)) {
                return M11_GAME_INPUT_REDRAW;
            }
            return M11_GAME_INPUT_IGNORED;
        case M12_MENU_INPUT_REST_TOGGLE:
            /* COMMAND.C C145 switches the complete party-resting state,
             * not just the M11 presentation flag.  Save/resume, F0230's
             * attack wake path, and F0303 skill queries consume the world
             * and lifecycle mirrors on later ticks. */
            state->resting = 1;
            state->world.partyIsResting = 1;
            state->world.lifecycle.rest.isResting = 1;
            m11_log_event(state, M11_COLOR_LIGHT_BLUE, "T%u: RESTING",
                          (unsigned int)state->world.gameTick);
            m11_set_status(state, "REST", "PARTY IS RESTING");
            snprintf(state->inspectTitle, sizeof(state->inspectTitle), "RESTING");
            snprintf(state->inspectDetail, sizeof(state->inspectDetail),
                     "HP AND STAMINA RECOVER SLOWLY. PRESS R AGAIN TO WAKE.");
            return M11_GAME_INPUT_REDRAW;
        case M12_MENU_INPUT_USE_STAIRS:
            if (m11_try_stairs_transition(state)) {
                return M11_GAME_INPUT_REDRAW;
            }
            m11_set_status(state, "STAIRS", "NO STAIRS HERE");
            return M11_GAME_INPUT_REDRAW;
        case M12_MENU_INPUT_PICKUP_ITEM:
            if (M11_GameView_PickupItem(state)) {
                return M11_GAME_INPUT_REDRAW;
            }
            return M11_GAME_INPUT_REDRAW;
        case M12_MENU_INPUT_DROP_ITEM:
            if (M11_GameView_DropItem(state)) {
                return M11_GAME_INPUT_REDRAW;
            }
            return M11_GAME_INPUT_REDRAW;
        case M12_MENU_INPUT_SPELL_RUNE_1:
        case M12_MENU_INPUT_SPELL_RUNE_2:
        case M12_MENU_INPUT_SPELL_RUNE_3:
        case M12_MENU_INPUT_SPELL_RUNE_4:
        case M12_MENU_INPUT_SPELL_RUNE_5:
        case M12_MENU_INPUT_SPELL_RUNE_6: {
            int runeIdx = (int)(input - M12_MENU_INPUT_SPELL_RUNE_1);
            if (!state->spellPanelOpen) {
                M11_GameView_OpenSpellPanel(state);
            }
            if (M11_GameView_EnterRune(state, runeIdx)) {
                return M11_GAME_INPUT_REDRAW;
            }
            return M11_GAME_INPUT_IGNORED;
        }
        case M12_MENU_INPUT_SPELL_CAST:
            if (state->spellPanelOpen && state->spellBuffer.runeCount >= 2) {
                M11_GameView_CastSpell(state);
                return M11_GAME_INPUT_REDRAW;
            }
            return M11_GAME_INPUT_IGNORED;
        case M12_MENU_INPUT_SPELL_CLEAR:
            if (state->spellPanelOpen) {
                M11_GameView_ClearSpell(state);
                M11_GameView_CloseSpellPanel(state);
                return M11_GAME_INPUT_REDRAW;
            }
            return M11_GAME_INPUT_IGNORED;
        case M12_MENU_INPUT_USE_ITEM:
            if (M11_GameView_UseItem(state)) {
                return M11_GAME_INPUT_REDRAW;
            }
            return M11_GAME_INPUT_REDRAW;
        case M12_MENU_INPUT_SAVE_GAME: {
            /* ReDMCSB LOADSAVE.C F0433 opens the save-disk dialog before
             * writing.  Do not collapse C140 to an invisible host quicksave. */
            m11_dm1_show_save_disk_menu(state);
            return M11_GAME_INPUT_REDRAW;
        }
        case M12_MENU_INPUT_BACK:
            /* Return-to-launcher confirmation is a full-screen modal route,
             * not a champion inventory interaction.  Clear invented/debug
             * overlays before drawing it so ESC never leaves the champion
             * inventory panel visible behind the quit prompt. */
            state->inventoryPanelActive = 0;
            state->mapOverlayActive = 0;
            state->spellPanelOpen = 0;
            /* G2018_ul_LastSaveTime quit-guard (ReDMCSB LOADSAVE.C:1371-1379).
             * When the dungeon tick has advanced more than 100 ticks past the
             * last save AND past the last load, surface the original game's
             * "GAME NOT SAVED" prompt with SAVE-AND-QUIT / CANCEL choices
             * instead of the plain confirm.  The compound condition matches
             * LOADSAVE.C verbatim: both inequalities must hold. */
            {
                uint32_t tick = (uint32_t)state->world.gameTick;
                int unsaved = (tick > state->lastSaveTick + 100u) &&
                              (tick > state->loadGameTick + 100u);
                if (unsaved) {
                    M11_GameView_ShowDialogOverlayChoices(state,
                                                          _("GAME NOT SAVED. SAVE AND QUIT?"),
                                                          _("SAVE AND QUIT"),
                                                          _("CANCEL"),
                                                          NULL,
                                                          NULL);
                    state->returnToMenuConfirmActive = 1;
                    state->quitGuardActive = 1;
                    m11_set_status(state, "RETURN", "UNSAVED");
                } else {
                    M11_GameView_ShowDialogOverlayChoices(state,
                                                          _("RETURN TO START MENU?"),
                                                          _("YES"),
                                                          _("NO"),
                                                          NULL,
                                                          NULL);
                    state->returnToMenuConfirmActive = 1;
                    state->quitGuardActive = 0;
                    m11_set_status(state, "RETURN", "CONFIRM");
                }
            }
            return M11_GAME_INPUT_REDRAW;
        case M12_MENU_INPUT_NONE:
            /* A restored F0435 world may be driven directly through this
             * public M11 input boundary by callers that do not own the main
             * loop's idle scheduler.  CMD_NONE is the source wait command;
             * do not discard it before F0884 can advance the restored queue. */
            command = CMD_NONE;
            label = "WAIT";
            break;
        default:
            return M11_GAME_INPUT_IGNORED;
    }
    if (DM1_V1_Movement_CommandForFirestaffMenuCodePc34Compat((int)input) !=
        DM1_V1_COMMAND_NONE) {
        if (!m11_apply_dm1_v1_pipeline_tick(state, input, label)) {
            return M11_GAME_INPUT_IGNORED;
        }
        return M11_GAME_INPUT_REDRAW;
    }
    if (!m11_apply_tick(state, command, label)) {
        return M11_GAME_INPUT_IGNORED;
    }
    return M11_GAME_INPUT_REDRAW;
}
