/* Draw a DM1 explosion bitmap from GRAPHICS.DAT.
 *
 * Replaces the previous cue-style palette-rect bloom with the real
 * explosion bitmap frames Fontanel ships in GRAPHICS.DAT at indices
 * 486 (fire), 487 (spell) and 488 (poison; also reused for smoke
 * with palette changes).
 *
 * The DM1 original calls F0675_DUNGEONVIEW_GetScaledBitmap to request a
 * cached scaled copy of the bitmap at a depth-specific pixel size.  We
 * achieve the same visible result by loading the native bitmap once and
 * blitting it with M11_AssetLoader_BlitScaled at a face-local size
 * chosen from the depth slot, then modulating that size across
 * currentFrame / maxFrames so the bitmap blooms on frame 0 and fades
 * on later frames (fireball / lightning / dispell) or decays with the
 * residual attack (poison / smoke), matching how F0822 progresses
 * the aftermath tick-by-tick.
 *
 * Smoke reuses the poison bitmap with DM1's palette substitution
 * G0212_auc_Graphic558_PaletteChanges_Smoke {0,1,2,3,4,5,12,1,...}
 * which only changes pixel values 6 (-> 12 = DARK_GRAY) and 7 (-> 1 =
 * NAVY); all other indices are identity. F0663 verifies that full source
 * table before its two non-identity mappings reach BlitScaledReplace.
 *
 * Returns 1 only when a real PC34 bitmap was blit. */
static int m11_draw_explosion_sprite_bound(const M11_GameViewState* state,
                                           unsigned char* framebuffer,
                                           int framebufferWidth,
                                           int framebufferHeight,
                                           int x, int y, int w, int h,
                                           int aspect,
                                           int gfxIndex,
                                           int isSmoke,
                                           int frame,
                                           int maxFrames,
                                           int attack,
                                           int depthIndex) {
    return m11_draw_explosion_sprite_bound_ex(state,
                                             framebuffer,
                                             framebufferWidth,
                                             framebufferHeight,
                                             x,
                                             y,
                                             w,
                                             h,
                                             aspect,
                                             gfxIndex,
                                             isSmoke,
                                             frame,
                                             maxFrames,
                                             attack,
                                             depthIndex,
                                             -1,
                                             0);
}

static int m11_draw_explosion_sprite_bound_ex(const M11_GameViewState* state,
                                              unsigned char* framebuffer,
                                              int framebufferWidth,
                                              int framebufferHeight,
                                              int x, int y, int w, int h,
                                              int aspect,
                                              int gfxIndex,
                                              int isSmoke,
                                              int frame,
                                              int maxFrames,
                                              int attack,
                                              int depthIndex,
                                              int transparentColor,
                                              int usesF0791Blit) {
    const M11_AssetSlot* slot;
    DM1_ExplosionSpriteBlitPlan plan;
    int effectiveTransparentColor;
    if (!state || !state->assetsAvailable) return 0;
    if (aspect < 0 || gfxIndex < 0) return 0;
    if (state->sourceKind == M11_GAME_SOURCE_CSB_BOOT &&
        !m11_csb_install_runtime_source_graphic(state, (unsigned int)gfxIndex)) {
        return 0;
    }
    slot = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader,
                                (unsigned int)gfxIndex);
    /* F0114 may scale only a decoded PC34 explosion surface. A cache entry
     * with dimensions but no pixel payload is not source material. */
    if (!slot || !slot->loaded || !slot->pixels ||
        slot->width == 0 || slot->height == 0) return 0;

    if (!dm1_v1_explosion_sprite_blit_plan(&plan,
                                           aspect,
                                           gfxIndex,
                                           isSmoke,
                                           frame,
                                           maxFrames,
                                           attack,
                                           depthIndex,
                                           x,
                                           y,
                                           w,
                                           h,
                                           (int)slot->width,
                                           (int)slot->height)) {
        return 0;
    }
    /* CSB explosion blit records carry the F0791 material decision from the
     * CSB viewport layer.  Without this gate, M11 can accidentally apply a
     * CSB source-zone transparent color to ordinary DM1 explosion draws. */
    effectiveTransparentColor =
        (usesF0791Blit && transparentColor >= 0)
            ? transparentColor
            : plan.transparent_color;

    if (!m11_dm1_v1_f0675_scaled_material_ready(
            state, slot, plan.draw_w, plan.draw_h,
            plan.is_smoke ? dm1_v1_f0663_smoke_palette_changes_pc34() : NULL,
            plan.is_smoke ? DM1_V1_F0663_PALETTE_COUNT_PC34 : 0)) {
        return 0;
    }
    if (m11_is_dm1_source_kind(state->sourceKind) &&
        !m11_dm1_v1_f0682_transparent_material_ready(
            state, slot, effectiveTransparentColor,
            plan.is_smoke ? dm1_v1_f0663_smoke_palette_changes_pc34() : NULL,
            plan.is_smoke ? DM1_V1_F0663_PALETTE_COUNT_PC34 : 0)) {
        return 0;
    }

    if (plan.is_smoke) {
        DM1_V1_F0663SmokeSurfaceReceiptPc34 smokeMaterial;
        memset(&smokeMaterial, 0, sizeof(smokeMaterial));
        if (gfxIndex != DM1_V1_F0663_C488_POISON_SOURCE_PC34 ||
            !m11_dm1_v1_f0663_smoke_surface_ready(
                state, slot, gfxIndex, &smokeMaterial)) {
            return 0;
        }
        M11_AssetLoader_BlitScaledReplace(
            slot, framebuffer, framebufferWidth, framebufferHeight,
            plan.draw_x, plan.draw_y, plan.draw_w, plan.draw_h,
            effectiveTransparentColor,
            smokeMaterial.replacementSourceA,
            smokeMaterial.replacementDestinationA,
            smokeMaterial.replacementSourceB,
            smokeMaterial.replacementDestinationB);
    } else {
        M11_AssetLoader_BlitScaled(
            slot, framebuffer, framebufferWidth, framebufferHeight,
            plan.draw_x, plan.draw_y, plan.draw_w, plan.draw_h,
            effectiveTransparentColor);
    }
    return 1;
}

static int m11_draw_explosion_sprite(const M11_GameViewState* state,
                                     unsigned char* framebuffer,
                                     int framebufferWidth,
                                     int framebufferHeight,
                                     int x, int y, int w, int h,
                                     int expType,
                                     int frame,
                                     int maxFrames,
                                     int attack,
                                     int depthIndex) {
    int aspect = dm1_v1_explosion_type_to_aspect(expType);
    int gfxIndex = dm1_v1_explosion_aspect_to_graphic(aspect);
    int isSmoke = dm1_v1_explosion_is_smoke(expType);
    return m11_draw_explosion_sprite_bound(state,
                                           framebuffer,
                                           framebufferWidth,
                                           framebufferHeight,
                                           x,
                                           y,
                                           w,
                                           h,
                                           aspect,
                                           gfxIndex,
                                           isSmoke,
                                           frame,
                                           maxFrames,
                                           attack,
                                           depthIndex);
}

/* ReDMCSB DUNVIEW.C F0115:6038-6074 handles the D0C explosion separately
 * from the F0114 scaled-sprite path: it selects one of M636's three
 * small/medium/large pattern bitmaps, then composites it through the D0C
 * explosion mask. Firestaff has the authentic PC34 bitmap family already;
 * consume that family here rather than falling through to the D1+ material. */
static int m11_draw_d0c_explosion_pattern(const M11_GameViewState* state,
                                          unsigned char* framebuffer,
                                          int framebufferWidth,
                                          int framebufferHeight,
                                          int x,
                                          int y,
                                          int w,
                                          int h,
                                          int explosionType,
                                          int attack)
{
    /* ReDMCSB DEFS.H:2088 C10_COLOR_FLESH, F0115 bitmap transparency. */
    enum { M11_DM1_PC34_COLOR_FLESH = 10 };
    const M11_AssetSlot* slot;
    int graphicIndex;
    if (!state || !state->assetsAvailable || w <= 0 || h <= 0) {
        return 0;
    }
    graphicIndex = dm1_v1_explosion_pattern_graphic_index(explosionType,
                                                            attack);
    if (graphicIndex < DM1_GFX_FIRST_EXPLOSION_PATTERN) {
        return 0;
    }
    if (state->sourceKind == M11_GAME_SOURCE_CSB_BOOT &&
        !m11_csb_install_runtime_source_graphic(state,
                                                (unsigned int)graphicIndex)) {
        return 0;
    }
    slot = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader,
                                (unsigned int)graphicIndex);
    /* The D0C M636 route is distinct from F0114. It too needs a complete
     * decoded PC34 bitmap; no host-colored pattern may stand in for it. */
    if (!slot || !slot->loaded || !slot->pixels ||
        slot->width == 0 || slot->height == 0) {
        return 0;
    }
    if (dm1_v1_explosion_is_smoke(explosionType)) {
        DM1_V1_F0663SmokeSurfaceReceiptPc34 smokeMaterial;
        memset(&smokeMaterial, 0, sizeof(smokeMaterial));
        if (graphicIndex < DM1_V1_F0663_C498_SMOKE_PATTERN_SMALL_PC34 ||
            graphicIndex > DM1_V1_F0663_C500_SMOKE_PATTERN_LARGE_PC34 ||
            !m11_dm1_v1_f0663_smoke_surface_ready(
                state, slot, graphicIndex, &smokeMaterial)) {
            return 0;
        }
        M11_AssetLoader_BlitScaledReplace(
            slot, framebuffer, framebufferWidth, framebufferHeight,
            x, y, w, h, M11_DM1_PC34_COLOR_FLESH,
            smokeMaterial.replacementSourceA,
            smokeMaterial.replacementDestinationA,
            smokeMaterial.replacementSourceB,
            smokeMaterial.replacementDestinationB);
    } else {
        M11_AssetLoader_BlitScaled(slot, framebuffer, framebufferWidth,
                                   framebufferHeight, x, y, w, h,
                                   M11_DM1_PC34_COLOR_FLESH);
    }
    return 1;
}

static int m11_draw_explosion_material(unsigned char* framebuffer,
                                       int framebufferWidth,
                                       int framebufferHeight,
                                       int x,
                                       int y,
                                       int w,
                                       int h,
                                       const M11_ViewportCell* cell,
                                       int depthIndex,
                                       int isD0c) {
    int expType;
    int frame;
    int maxFrames;
    int attack;
    int rendered;
    int graphicIndex;
    const M11_AssetSlot* slot;
    unsigned int materialFNV1a;
    M11_Dm1F0115C15CaptureRequest* capture =
        &s_m11_dm1_f0115_c15_capture_request;

    if (!m11_viewport_cell_has_renderable_explosion(cell)) {
        return 0;
    }
    if (!g_drawState || !g_drawState->assetsAvailable) {
        return 0;
    }
    /* ReDMCSB DUNVIEW.C F0115:5915-6137 selects F0114/M636 material for
     * each ordinary C15 record. Missing PC34 graphics remain no-draw; there
     * is no palette-rect, crosshair, or host-defined explosion substitute. */
    expType = cell->firstExplosionType;
    frame = cell->firstExplosionFrame;
    maxFrames = cell->firstExplosionMaxFrames;
    attack = cell->firstExplosionAttack;
    if (m11_is_dm1_source_kind(g_drawState->sourceKind) &&
        !m11_is_stock_dm1_hall_map0(g_drawState) &&
        capture->owner == g_drawState &&
        capture->runtimeTick == g_drawState->world.gameTick) {
        /* F0115's restarted C15 loop owns this request. Record it before
         * F0114/M636 resolution so a missing original bitmap cannot retain
         * an earlier final-capture receipt. */
        capture->requestedMaterialCount++;
    }
    if (isD0c) {
        /* ReDMCSB DUNVIEW.C F0115:6038-6074 has a separate M636 pattern
         * route for D0C.  A missing pattern is no-draw: falling through to
         * the F0114 D1-D3 sprite would invent a non-source replacement. */
        rendered = m11_draw_d0c_explosion_pattern(
            g_drawState, framebuffer, framebufferWidth, framebufferHeight,
            x, y, w, h, expType, attack);
        graphicIndex = dm1_v1_explosion_pattern_graphic_index(expType, attack);
    } else {
        rendered = m11_draw_explosion_sprite(
            g_drawState, framebuffer, framebufferWidth, framebufferHeight,
            x, y, w, h, expType, frame, maxFrames, attack, depthIndex);
        graphicIndex = dm1_v1_explosion_aspect_to_graphic(
            dm1_v1_explosion_type_to_aspect(expType));
    }
    if (!rendered || capture->owner != g_drawState ||
        capture->runtimeTick != g_drawState->world.gameTick ||
        capture->requestedMaterialCount <= 0 || graphicIndex < 0) {
        return rendered;
    }
    slot = M11_AssetLoader_Load((M11_AssetLoader*)&g_drawState->assetLoader,
                                (unsigned int)graphicIndex);
    materialFNV1a = slot && slot->loaded && slot->pixels &&
        slot->width > 0 && slot->height > 0
        ? m11_dm1_runtime_capture_fnv1a(
              slot->pixels, (size_t)slot->width * (size_t)slot->height)
        : 0u;
    if (materialFNV1a == 0u) {
        return rendered;
    }
    materialFNV1a ^= (unsigned int)graphicIndex;
    materialFNV1a *= 16777619u;
    materialFNV1a ^= (unsigned int)expType;
    materialFNV1a *= 16777619u;
    materialFNV1a ^= (unsigned int)frame;
    materialFNV1a *= 16777619u;
    materialFNV1a ^= (unsigned int)attack;
    materialFNV1a *= 16777619u;
    materialFNV1a ^= (unsigned int)isD0c;
    materialFNV1a *= 16777619u;
    if (capture->materialFNV1a == 0u) {
        capture->materialFNV1a = 2166136261u;
    }
    capture->materialFNV1a ^= materialFNV1a;
    capture->materialFNV1a *= 16777619u;
    if (capture->materialFNV1a == 0u) {
        /* A non-empty, fully source-backed pass must keep a non-zero
         * aggregate receipt; zero remains the missing/stale sentinel. */
        capture->materialFNV1a = 1u;
    }
    capture->completedMaterialCount++;
    return rendered;
}

static void m11_draw_effect_cue(unsigned char* framebuffer,
                                int framebufferWidth,
                                int framebufferHeight,
                                int x,
                                int y,
                                int w,
                                int h,
                                const M11_ViewportCell* cell,
                                int depthIndex,
                                int sourceZoneRow) {
    int cx = x + w / 2;
    int cy = y + h / 2;
    if (!cell) {
        return;
    }
    /* ReDMCSB F0115 draws the resolved C2900 projectile bitmap only. */
    if (cell->renderableProjectileCount > 0 &&
        cell->dm1MaterializationDecisionReady &&
        cell->dm1MaterializationDecision.drawRuntimeProjectiles) {
        int projectileIndex;
        for (projectileIndex = 0;
             projectileIndex < cell->renderableProjectileCount;
             ++projectileIndex) {
            M11_ViewportCell projectile;
            if (!m11_viewport_cell_projectile_sample(cell, projectileIndex,
                                                      &projectile) ||
                !m11_viewport_cell_has_renderable_projectile(&projectile) ||
                !g_drawState || !g_drawState->assetsAvailable) {
                continue;
            }
            (void)m11_draw_viewport_projectile_sprite(
                g_drawState, framebuffer, framebufferWidth, framebufferHeight,
                x, y, w, h, &projectile, depthIndex, sourceZoneRow);
        }
    }
    /* Teleporter fields are source bitmap overlays, not procedural cue art.
     * Normal V1 draws them in m11_draw_dm1_teleporter_fields(), using
     * DUNVIEW.C F0113 + G0188/G2035 field-aspect rows. */
    /* The F0128/F0104 source pit pass owns C049..C063. Missing original
     * material is intentionally no-draw; do not replace it with host geometry. */
    /* Explosions are intentionally not drawn here.  ReDMCSB F0115
     * finishes every packed object/creature/projectile cell first, then
     * restarts the thing list for a separate explosion pass
     * (DUNVIEW.C:5915-5933).  m11_draw_dm1_deferred_explosion_pass()
     * owns that after-all-cells layer. */

    /* Sensors and text strings are control metadata unless a source-backed
     * wall inscription/field path draws them.  ReDMCSB DUNVIEW.C F0115
     * draws objects, creatures, projectiles, and explosions from the thing
     * list; DEFS.H marks C127 sensors as trigger data.  Keep Firestaff's
     * old sensor/text outline as a debug-HUD cue only so normal V1 does not
     * leak a tan/orange square into Hall of Champions floor views. */
    if (g_drawState && g_drawState->showDebugHUD &&
        (cell->summary.sensors > 0 || cell->summary.textStrings > 0)) {
        m11_draw_rect(framebuffer, framebufferWidth, framebufferHeight,
                      cx - 4, cy - 4, 9, 9, M11_COLOR_MAGENTA);
    }
}

static void m11_append_phrase(char* out,
                              size_t outSize,
                              const char* phrase) {
    size_t used;
    if (!out || outSize == 0U || !phrase || phrase[0] == '\0') {
        return;
    }
    used = strlen(out);
    if (used > 0U && used + 2U < outSize) {
        snprintf(out + used, outSize - used, ", ");
        used = strlen(out);
    }
    if (used + 1U < outSize) {
        snprintf(out + used, outSize - used, "%s", phrase);
    }
}

static void m11_append_count_phrase(char* out,
                                    size_t outSize,
                                    int count,
                                    const char* singular,
                                    const char* plural) {
    char chunk[32];
    if (count <= 0 || !singular || !plural) {
        return;
    }
    snprintf(chunk, sizeof(chunk), "%d %s", count, count == 1 ? singular : plural);
    m11_append_phrase(out, outSize, chunk);
}

static void m11_format_square_summary(const M11_ViewportCell* cell,
                                      char* out,
                                      size_t outSize) {
    char extras[96];
    const char* base;

    if (!out || outSize == 0U) {
        return;
    }
    if (!cell || !cell->valid) {
        snprintf(out, outSize, "VOID");
        return;
    }

    extras[0] = '\0';
    if (cell->elementType == DUNGEON_ELEMENT_DOOR) {
        m11_append_phrase(extras, sizeof(extras),
                          (cell->doorState == 0 || cell->doorState == 5) ? "OPEN" : "SHUT");
    }
    m11_append_count_phrase(extras, sizeof(extras), cell->summary.groups, "FOE", "FOES");
    m11_append_count_phrase(extras, sizeof(extras), cell->summary.items, "ITEM", "ITEMS");
    m11_append_count_phrase(extras, sizeof(extras),
                            cell->summary.projectiles + cell->summary.explosions,
                            "EFFECT", "EFFECTS");
    m11_append_count_phrase(extras, sizeof(extras), cell->summary.sensors, "SENSOR", "SENSORS");
    m11_append_count_phrase(extras, sizeof(extras),
                            cell->summary.textStrings + cell->summary.teleporters,
                            "MARK", "MARKS");

    base = F0503_DUNGEON_GetElementName_Compat(cell->elementType);
    if (extras[0] != '\0') {
        snprintf(out, outSize, "%s, %s", base, extras);
    } else {
        snprintf(out, outSize, "%s", base);
    }
}

static void m11_format_square_things(unsigned short firstThing,
                                     int squareThingCount,
                                     char* out,
                                     size_t outSize) {
    int thingType;
    if (!out || outSize == 0U) {
        return;
    }
    if (firstThing == THING_ENDOFLIST || firstThing == THING_NONE || squareThingCount <= 0) {
        snprintf(out, outSize, "QUIET FLOOR");
        return;
    }
    thingType = THING_GET_TYPE(firstThing);
    switch (thingType) {
        case THING_TYPE_GROUP:
            snprintf(out, outSize, "%d CREATURE %s",
                     squareThingCount,
                     squareThingCount == 1 ? "CONTACT" : "CONTACTS");
            break;
        case THING_TYPE_PROJECTILE:
        case THING_TYPE_EXPLOSION:
            snprintf(out, outSize, "%d LIVE EFFECT %s",
                     squareThingCount,
                     squareThingCount == 1 ? "AHEAD" : "STACKED");
            break;
        case THING_TYPE_TEXTSTRING:
            snprintf(out, outSize, "TEXT PLAQUE");
            break;
        case THING_TYPE_SENSOR:
            snprintf(out, outSize, "TRIGGER TILE");
            break;
        case THING_TYPE_TELEPORTER:
            snprintf(out, outSize, "TELEPORT FIELD");
            break;
        default:
            snprintf(out, outSize, "%d FLOOR %s",
                     squareThingCount,
                     squareThingCount == 1 ? "ITEM" : "ITEMS");
            break;
    }
}

static void m11_get_food_water_average(const struct PartyState_Compat* party,
                                       int* outFood,
                                       int* outWater) {
    int slot;
    int foodTotal = 0;
    int waterTotal = 0;
    int count = 0;
    if (!party) {
        if (outFood) {
            *outFood = 0;
        }
        if (outWater) {
            *outWater = 0;
        }
        return;
    }
    for (slot = 0; slot < CHAMPION_MAX_PARTY; ++slot) {
        if (!party->champions[slot].present) {
            continue;
        }
        foodTotal += party->champions[slot].food;
        waterTotal += party->champions[slot].water;
        ++count;
    }
    if (outFood) {
        *outFood = count > 0 ? foodTotal / count : 0;
    }
    if (outWater) {
        *outWater = count > 0 ? waterTotal / count : 0;
    }
}

static void m11_direction_vectors(int direction,
                                  int* outForwardX,
                                  int* outForwardY,
                                  int* outRightX,
                                  int* outRightY) {
    if (!outForwardX || !outForwardY || !outRightX || !outRightY) {
        return;
    }
    switch (direction) {
        case DIR_NORTH:
            *outForwardX = 0;
            *outForwardY = -1;
            *outRightX = 1;
            *outRightY = 0;
            break;
        case DIR_EAST:
            *outForwardX = 1;
            *outForwardY = 0;
            *outRightX = 0;
            *outRightY = 1;
            break;
        case DIR_SOUTH:
            *outForwardX = 0;
            *outForwardY = 1;
            *outRightX = -1;
            *outRightY = 0;
            break;
        case DIR_WEST:
        default:
            *outForwardX = -1;
            *outForwardY = 0;
            *outRightX = 0;
            *outRightY = -1;
            break;
    }
}

/* ── Per-map ornament index cache ──
 * Load the wall and door ornament index tables for a given map from
 * DUNGEON.DAT metadata.  In the original, the metadata follows the
 * square tile data: creatureTypeCount bytes of creature type indices,
 * then wallOrnamentCount bytes of wall ornament graphic indices,
 * then floorOrnamentCount bytes of floor ornament graphic indices,
 * then doorOrnamentCount bytes of door ornament graphic indices.
 * Ref: ReDMCSB DUNGEON.C F0173_DUNGEON_ReadMapData_CPSE.
 * We read these lazily and cache in the game view state. */
static void m11_ensure_ornament_cache(M11_GameViewState* state, int mapIndex) {
    const struct DungeonDatState_Compat* dun;
    const struct DungeonMapDesc_Compat* m;
    long rawDataFileOffset;
    long mapFileOffset;
    int squareCount;
    unsigned char metaBuf[128]; /* enough for all metadata bytes */
    int metaSize;
    int offset;
    FILE* fp;
    int i;
    int totalColumns;
    long thingDataTotalBytes;

    if (!state || !state->world.dungeon || !state->world.dungeon->loaded) return;
    dun = state->world.dungeon;
    if (mapIndex < 0 || mapIndex >= (int)dun->header.mapCount) return;
    if (mapIndex >= (int)32) return;
    if (state->ornamentCacheLoaded[mapIndex]) return;

    /* No raw DUNGEON.DAT table means no source-selected ornament material.
     * Initialize every local ordinal to unavailable before any read failure. */
    for (i = 0; i < 16; ++i) {
        state->wallOrnamentIndices[mapIndex][i] = -1;
        state->floorOrnamentIndices[mapIndex][i] = -1;
        state->doorOrnamentIndices[mapIndex][i] = -1;
    }

    m = &dun->maps[mapIndex];
    squareCount = (int)m->width * (int)m->height;

    /* Compute metadata size: creature types + wall ornaments + floor ornaments
     * + door ornaments.  ReDMCSB DUNGEON.C F0173 lines 2758-2762 reads only
     * B.WallOrnamentCount bytes from map data, then assigns the synthetic
     * inscription slot in memory:
     * G0261[WallOrnamentCount] = C0_WALL_ORNAMENT_INSCRIPTION. */
    metaSize = (int)m->creatureTypeCount + (int)m->wallOrnamentCount +
               (int)m->floorOrnamentCount + (int)m->doorOrnamentCount;
    if (metaSize <= 0 || metaSize > (int)sizeof(metaBuf)) {
        state->ornamentCacheLoaded[mapIndex] = 1;
        return;
    }

    /* Use the verified dungeon path from launch. Older builds reconstructed
     * DUNGEON.DAT beside GRAPHICS.DAT, which broke renamed/hash-resolved data. */
    {
        char datPath[512];
        if (state->dungeonPath[0] == '\0') {
            state->ornamentCacheLoaded[mapIndex] = 1;
            return;
        }
        snprintf(datPath, sizeof(datPath), "%s", state->dungeonPath);
        fp = fopen(datPath, "rb");
        if (!fp) {
            state->ornamentCacheLoaded[mapIndex] = 1;
            return;
        }
    }

    /* Compute the raw data section offset with the same complete layout as
     * F0502_DUNGEON_LoadTileData_Compat.  Text words precede the typed Thing
     * records in PC34 DUNGEON.DAT; omitting them shifts every map metadata
     * table and turns real wall ornaments into unrelated graphic indices. */
    totalColumns = 0;
    for (i = 0; i < (int)dun->header.mapCount; ++i) {
        totalColumns += dun->maps[i].width;
    }
    thingDataTotalBytes = 0;
    for (i = 0; i < 16; ++i) {
        thingDataTotalBytes += (long)dun->header.thingCounts[i] *
                               (long)s_thingDataByteCount[i];
    }
    rawDataFileOffset = DUNGEON_HEADER_SIZE +
                        (long)dun->header.mapCount * DUNGEON_MAP_DESC_SIZE +
                        (long)totalColumns * 2 +
                        (long)dun->header.squareFirstThingCount * 2 +
                        (long)dun->header.textDataWordCount * 2 +
                        thingDataTotalBytes;
    mapFileOffset = rawDataFileOffset + (long)m->rawMapDataByteOffset;

    /* Seek past square data to the metadata area */
    if (fseek(fp, mapFileOffset + (long)squareCount, SEEK_SET) != 0) {
        fclose(fp);
        state->ornamentCacheLoaded[mapIndex] = 1;
        return;
    }

    if ((int)fread(metaBuf, 1, (size_t)metaSize, fp) != metaSize) {
        fclose(fp);
        state->ornamentCacheLoaded[mapIndex] = 1;
        return;
    }
    fclose(fp);

    /* Parse: skip creature type bytes, then read wall ornament indices.
     * Each byte is a global ornament index used by the rendering engine.
     * Ref: ReDMCSB DUNGEON.C F0173_DUNGEON_ReadMapData_CPSE —
     *   CopyBytes(MapMetaData + CreatureTypeCount, G0261, WallOrnamentCount)
     *   G0261[InscriptionWallOrnamentIndex] = C0_WALL_ORNAMENT_INSCRIPTION */
    offset = (int)m->creatureTypeCount;
    for (i = 0; i < 16; ++i) {
        if (i < (int)m->wallOrnamentCount && (offset + i) < metaSize) {
            state->wallOrnamentIndices[mapIndex][i] = (int)metaBuf[offset + i];
        } else if (i == (int)m->wallOrnamentCount) {
            state->wallOrnamentIndices[mapIndex][i] = 0; /* C0_WALL_ORNAMENT_INSCRIPTION */
        } else {
            state->wallOrnamentIndices[mapIndex][i] = -1;
        }
    }
    offset += (int)m->wallOrnamentCount;

    /* Read floor ornament indices.
     * Ref: ReDMCSB DUNGEON.C F173 — G262_auc_CurrentMapFloorOrnamentIndices.
     * Each byte is a global floor ornament graphic set index.  In the
     * original, floor ornaments start at graphic index 247 and each
     * ornament has 6 perspective variants (D3L..D1R).
     * Floor ornament graphic = 247 + globalIndex * 6 + viewOffset. */
    for (i = 0; i < 16; ++i) {
        if (i < (int)m->floorOrnamentCount && (offset + i) < metaSize) {
            state->floorOrnamentIndices[mapIndex][i] = (int)metaBuf[offset + i];
        } else {
            state->floorOrnamentIndices[mapIndex][i] = -1; /* no ornament */
        }
    }
    offset += (int)m->floorOrnamentCount;

    /* Read door ornament indices */
    for (i = 0; i < 16; ++i) {
        if (i < (int)m->doorOrnamentCount && (offset + i) < metaSize) {
            state->doorOrnamentIndices[mapIndex][i] = (int)metaBuf[offset + i];
        } else {
            state->doorOrnamentIndices[mapIndex][i] = -1;
        }
    }

    state->ornamentCacheLoaded[mapIndex] = 1;
}

/* ReDMCSB DUNGEON.C F0174 keeps G0267 (the current-map alcove ornament
 * list) in sync on every current-map change; DUNVIEW.C:2672-2690 rebuilds
 * it from the map's G0261 wall-ornament table against the G0192 source
 * table.  Firestaff wires the DUNGEON.DAT-loaded table into the wall
 * ornament contract module so the F0149 alcove predicate classifies from
 * real map data instead of failing closed. */
static void m11_dm1_wire_current_map_alcove_list(M11_GameViewState* state,
                                                 int mapIndex) {
    if (!state || mapIndex < 0 || mapIndex >= 32 ||
        !state->world.dungeon || !state->world.dungeon->loaded) {
        dm1_v1_wall_ornament_clear_current_map_alcove_list_pc34();
        return;
    }
    m11_ensure_ornament_cache(state, mapIndex);
    if (!state->ornamentCacheLoaded[mapIndex]) {
        dm1_v1_wall_ornament_clear_current_map_alcove_list_pc34();
        return;
    }
    if (dm1_v1_wall_ornament_current_map_alcove_list_map_pc34() != mapIndex) {
        (void)dm1_v1_wall_ornament_wire_current_map_alcove_list_pc34(
            mapIndex, state->wallOrnamentIndices[mapIndex], 16);
    }
}

/* ReDMCSB DUNGEON.C F0601 / DUNVIEW.C G0268.  The fountain is not a
 * hard-coded wall-ornament kind: G0261's local slot must resolve to the
 * current map's global ornament table and then match G0193's source list.
 * Failing closed is important for HoC: an arbitrary wall ornament must not
 * consume or mutate the object in the leader hand. */
static int m11_dm1_front_wall_is_fountain(
    M11_GameViewState* state,
    const M11_ViewportCell* frontCell) {
    int mapIndex;
    int localOrdinal;
    int globalIndex;
    int i;

    if (!state || !frontCell || !frontCell->valid ||
        frontCell->elementType != DUNGEON_ELEMENT_WALL ||
        frontCell->wallOrnamentOrdinal <= 0) {
        return 0;
    }
    mapIndex = state->world.party.mapIndex;
    localOrdinal = frontCell->wallOrnamentOrdinal - 1;
    if (mapIndex < 0 || mapIndex >= 32 || localOrdinal < 0 ||
        localOrdinal >= 16) {
        return 0;
    }
    m11_ensure_ornament_cache(state, mapIndex);
    if (!state->world.dungeon || !state->world.dungeon->maps ||
        !state->ornamentCacheLoaded[mapIndex] ||
        localOrdinal >= (int)state->world.dungeon->maps[mapIndex].wallOrnamentCount) {
        return 0;
    }
    globalIndex = state->wallOrnamentIndices[mapIndex][localOrdinal];
    for (i = 0; i < dm1_v1_g0193_size_pc34(); ++i) {
        if (globalIndex == dm1_v1_g0193_get_pc34(i)) {
            return 1;
        }
    }
    return 0;
}

/* Apply the source-locked CLIKVIEW.C fountain path to the actual loaded
 * Thing record.  This deliberately does not infer a fountain from a graphic
 * id or a generic ornament fallback. */
static int m11_dm1_apply_fountain_click(
    M11_GameViewState* state,
    const M11_ViewportCell* frontCell) {
    unsigned short handThing;
    int icon;

    if (!state || !frontCell || !m11_dm1_front_wall_is_fountain(state, frontCell) ||
        !state->world.things) {
        return 0;
    }
    handThing = DM1_V1_M11Runtime_GetLeaderHandThingPc34Compat(state);
    if (handThing == THING_NONE) {
        int championIndex = state->world.party.activeChampionIndex;
        if (championIndex < 0 || championIndex >= CHAMPION_MAX_PARTY ||
            !state->world.party.champions[championIndex].present) {
            return 0;
        }
        state->world.party.champions[championIndex].water =
            DM1_V1_FOUNTAIN_WATER_MAX;
        m11_audio_emit_source_sound(state, DM1_V1_FOUNTAIN_SWALLOW_SOUND,
                                    M11_AUDIO_MARKER_COMBAT);
        m11_set_status(state, "FOUNTAIN", "DRANK WATER");
        m11_refresh_hash(state);
        return 1;
    }

    icon = m11_object_icon_index_for_thing(state, state->world.things,
                                           handThing);
    if (THING_GET_TYPE(handThing) == THING_TYPE_JUNK &&
        icon >= DM1_V1_ICON_JUNK_WATER &&
        icon <= DM1_V1_ICON_JUNK_WATERSKIN) {
        int index = THING_GET_INDEX(handThing);
        if (!state->world.things->junks || index < 0 ||
            index >= state->world.things->junkCount) {
            return 0;
        }
        state->world.things->junks[index].chargeCount =
            DM1_V1_FOUNTAIN_FULL_CHARGES;
        m11_set_status(state, "FOUNTAIN", "CONTAINER FILLED");
        m11_refresh_hash(state);
        return 1;
    }
    if (THING_GET_TYPE(handThing) == THING_TYPE_POTION && icon ==
        DM1_V1_ICON_POTION_EMPTY_FLASK) {
        int index = THING_GET_INDEX(handThing);
        if (!state->world.things->potions || index < 0 ||
            index >= state->world.things->potionCount) {
            return 0;
        }
        state->world.things->potions[index].type = 15;
        m11_set_status(state, "FOUNTAIN", "FLASK FILLED WITH WATER");
        m11_refresh_hash(state);
        return 1;
    }
    return 0;
}

static int m11_projectile_subtype_to_aspect_index(int subtype) {
    return dm1_v1_projectile_subtype_to_aspect(subtype);
}

static int m11_projectile_aspect_bitmap_delta(int aspectIndex, int relativeDir) {
    return dm1_v1_projectile_bitmap_delta(aspectIndex, relativeDir);
}

static int m11_projectile_aspect_to_graphic_index(int aspectIndex, int relativeDir) {
    return dm1_v1_projectile_graphic_index(aspectIndex, relativeDir);
}

static int m11_sample_viewport_cell(const M11_GameViewState* state,
                                    int relForward,
                                    int relSide,
                                    M11_ViewportCell* outCell) {
    int fx;
    int fy;
    int rx;
    int ry;
    int mapX;
    int mapY;
    unsigned char square = 0;
    unsigned short firstThing = THING_ENDOFLIST;
    unsigned short viewportStaticFirstThing = THING_ENDOFLIST;
    int visibleWallCell = -1;
    int f0115CandidatesReady = 0;
    DM1_F0115WorldCandidatesPc34 f0115Candidates;
    M11_ViewportCell cell;

    memset(&cell, 0, sizeof(cell));
    cell.relForward = relForward;
    cell.relSide = relSide;
    cell.elementType = DUNGEON_ELEMENT_WALL;
    cell.firstThing = THING_ENDOFLIST;
    cell.doorState = -1;
    cell.doorType = 0;
    cell.creatureType = -1;
    { int ci; for (ci = 0; ci < M11_MAX_CELL_CREATURES; ++ci) { cell.creatureTypes[ci] = -1; cell.creatureCountsPerGroup[ci] = 0; cell.creatureDirections[ci] = -1; } }
    cell.creatureGroupCount = 0;
    cell.firstItemThingType = -1;
    cell.firstItemSubtype = -1;
    { int fi; for (fi = 0; fi < M11_MAX_CELL_ITEMS; ++fi) { cell.floorItemTypes[fi] = -1; cell.floorItemSubtypes[fi] = -1; cell.floorItemCells[fi] = 0; cell.floorItemThings[fi] = THING_NONE; } }
    cell.floorItemCount = 0;
    cell.wallOrnamentOrdinal = -1;
    cell.inscriptionTextIndex = -1;
    cell.championPortraitOrdinal = -1;
    cell.championPortraitWallCell = -1;
    cell.doorOrnamentOrdinal = -1;
    cell.firstProjectileGfxIndex = -1;
    cell.firstProjectileMaterialReady = 0;
    cell.firstProjectileSubtype = -1;
    cell.firstProjectileRelDir = -1;
    cell.firstProjectileCell = -1;
    cell.firstProjectileFlipFlags = 0;
    cell.floorOrnamentOrdinal = 0;
    cell.firstExplosionType = -1;
    cell.firstExplosionFrame = -1;
    cell.firstExplosionMaxFrames = 0;
    cell.firstExplosionAttack = -1;

    if (!state || !state->active) {
        if (outCell) {
            *outCell = cell;
        }
        return 0;
    }

    m11_direction_vectors(state->world.party.direction, &fx, &fy, &rx, &ry);
    {
        int viewDir = state->world.party.direction;
        if (relSide < 0) {
            viewDir = (viewDir + 3) & 3;
        } else if (relSide > 0) {
            viewDir = (viewDir + 1) & 3;
        }
        visibleWallCell = (viewDir + 2) & 3;
    }

    /* Phase 5 smooth movement: apply camera interpolation offset to the
     * view-cone sampling.
     *
     * The camera controller (dm1_v2_camera_controller_pc34) produces
     * visualX/Y offsets in sub-pixel units (DM1_V2_SUBPIXEL_SCALE = 256).
     * We convert to fractional forward/side steps by dividing by SCALE.
     *
     * When the party moves north (direction 0, forward=-Y), a positive
     * camera_offset_y (downward = south in screen space) means the view
     * cone should sample squares one step closer to north — the viewport
     * appears to have scrolled south, revealing the new north wall.
     *
     * The offset is added to the forward step vector so the view cone
     * glides in the direction of movement/interpolation without changing
     * the logical party map coordinates (collision/cooldowns untouched).
     *
     * Source-lock: DUNGEON.C:1371-1391 produces discrete G0306/G0307;
     * DUNVIEW.C:8606-8612 renders from those without offset.
     * This is V2-only presentation — no game logic changes. */
    {
        int camX = state->camera_offset_x;
        int camY = state->camera_offset_y;
        /* Convert pixel-space camera offset to fractional map steps.
         * A full dungeon square = DM1_V2_SUBPIXEL_SCALE subpixels.
         * camX/camY in range [-255, +255] for sub-grid interpolation.
         * camX > 0 means visual position is right of logical — for N-facing
         * (forward=-Y, right=+X), this shifts the view cone right.
         *
         * For each relForward step, shift by camX/camY scaled by relForward
         * so the view cone glides toward the target position. */
        if (camX != 0 || camY != 0) {
            /* camFx/camFy = fractional step nudge per relForward unit. */
            float camFx = (float)camX / (float)256.0f;
            float camFy = (float)camY / (float)256.0f;
            /* Apply offset to the forward step (the dominant scroll axis).
             * relForward=-1 (D1, front cell): view cone shifts most.
             * relForward=-2 (D2): shifts less.
             * relForward=-3 (D3): shifts least.
             * relForward=0 (center): no shift. */
            float depthNudge = 0.0f;
            if (relForward < 0) {
                depthNudge = (float)relForward; /* -1 or -2 or -3, negative = forward */
                fx += (int)(camFx * depthNudge);
                fy += (int)(camFy * depthNudge);
            }
        }
    }

    mapX = state->world.party.mapX + relForward * fx + relSide * rx;
    mapY = state->world.party.mapY + relForward * fy + relSide * ry;
    cell.mapX = mapX;
    cell.mapY = mapY;

    if (!m11_get_viewport_square_byte_pc34(&state->world,
                                           state->world.party.mapIndex,
                                           mapX,
                                           mapY,
                                           &square)) {
        if (outCell) {
            *outCell = cell;
        }
        return 0;
    }

    viewportStaticFirstThing = m11_get_viewport_static_first_thing(&state->world,
                                                                   state->world.party.mapIndex,
                                                                   mapX,
                                                                   mapY);
    /* F0160/F0161 owns every viewport square's thing-chain lookup.  Door
     * state/type must use that same compact table as the object, sensor and
     * ornament passes; dense mapX*height+mapY indexing can otherwise borrow
     * a door from an unrelated square in real PC34 data. */
    firstThing = viewportStaticFirstThing;
    cell.valid = 1;
    cell.square = square;
    cell.elementType = (square & DUNGEON_SQUARE_MASK_TYPE) >> 5;
    cell.thingCount = m11_count_square_things(&state->world,
                                              state->world.party.mapIndex,
                                              mapX,
                                              mapY);
    cell.firstThing = firstThing;
    m11_summarize_square_things(&state->world,
                                state->world.party.mapIndex,
                                mapX,
                                mapY,
                                &cell.summary);
    memset(&f0115Candidates, 0, sizeof(f0115Candidates));
    f0115CandidatesReady = dm1_v1_f0115_world_candidates_pc34(
        &state->world, state->world.party.mapIndex, mapX, mapY,
        m11_f0115_mirror_ordinal_lookup, (void*)state, &f0115Candidates);
    if (cell.elementType == DUNGEON_ELEMENT_DOOR) {
        cell.doorState = square & 0x07;
        cell.doorVertical = (square & 0x08) != 0;
        if (firstThing != THING_ENDOFLIST && firstThing != THING_NONE &&
            THING_GET_TYPE(firstThing) == THING_TYPE_DOOR &&
            state->world.things && state->world.things->doors) {
            int doorIndex = THING_GET_INDEX(firstThing);
            if (doorIndex >= 0 && doorIndex < state->world.things->doorCount) {
                cell.hasDoorThing = 1;
                cell.doorType = state->world.things->doors[doorIndex].type & 1;
                cell.doorVertical = state->world.things->doors[doorIndex].vertical;
            }
        }
    }

    /* ReDMCSB DUNVIEW.C F0115 defers C04 groups until the floor-object
     * pass.  DM1/M10 owns compact-chain traversal and typed group decode;
     * M11 only copies the source-backed candidates into presentation cells. */
    if (f0115CandidatesReady) {
        int gi;
        for (gi = 0; gi < f0115Candidates.groupCount &&
                     cell.creatureGroupCount < M11_MAX_CELL_CREATURES; ++gi) {
            const DM1_F0115WorldGroupCandidatePc34* group =
                &f0115Candidates.groups[gi];
            if (cell.creatureGroupCount == 0) {
                cell.creatureType = group->creatureType;
            }
            cell.creatureTypes[cell.creatureGroupCount] = group->creatureType;
            cell.creatureCountsPerGroup[cell.creatureGroupCount] =
                group->creatureCount;
            cell.creatureDirections[cell.creatureGroupCount] = group->direction;
            ++cell.creatureGroupCount;
        }
        cell.summary.groups = cell.creatureGroupCount;
    }

    /* ReDMCSB DUNVIEW.C F0115 draws objects from the same compact chain as
     * groups.  HoC mirror payload objects are filtered by the DM1 receipt,
     * so host rendering cannot rediscover them as floor loot. */
    if (f0115CandidatesReady) {
        int ii;
        for (ii = 0; ii < f0115Candidates.itemCount &&
                     cell.floorItemCount < M11_MAX_CELL_ITEMS; ++ii) {
            const DM1_F0115WorldItemCandidatePc34* item =
                &f0115Candidates.items[ii];
            if (cell.floorItemCount == 0) {
                cell.firstItemThingType = item->thingType;
                cell.firstItemSubtype = item->subtype;
            }
            cell.floorItemTypes[cell.floorItemCount] = item->thingType;
            cell.floorItemSubtypes[cell.floorItemCount] = item->subtype;
            cell.floorItemCells[cell.floorItemCount] =
                (item->cell - state->world.party.direction) & 3;
            cell.floorItemThings[cell.floorItemCount] = item->thing;
            ++cell.floorItemCount;
        }
        cell.summary.items = cell.floorItemCount;
        if (cell.summary.total > cell.floorItemCount) {
            cell.summary.total -=
                f0115Candidates.staticReceipt.ignoredHallPayloadItems;
            if (cell.summary.total < cell.floorItemCount) {
                cell.summary.total = cell.floorItemCount;
            }
        }
    }

    /* Extract door ornament ordinal */
    if (cell.elementType == DUNGEON_ELEMENT_DOOR && cell.hasDoorThing &&
        state->world.things && state->world.things->doors) {
        int doorIdx = THING_GET_INDEX(firstThing);
        if (doorIdx >= 0 && doorIdx < state->world.things->doorCount) {
            int ord = (int)state->world.things->doors[doorIdx].ornamentOrdinal;
            if (ord > 0) cell.doorOrnamentOrdinal = ord;
        }
    }

    /* ── Random wall ornament computation ──────────────────────────────
     * ReDMCSB DUNGEON.C F0172_DUNGEON_SetSquareAspect + F0171 + F0170 + F0169.
     *
     * Wall squares have bits 0-3 indicating which cardinal faces allow
     * random ornaments:
     *   Bit 0 (0x01) = West,  Bit 1 (0x02) = South,
     *   Bit 2 (0x04) = East,  Bit 3 (0x08) = North.
     *
     * The "front" face (what the player sees looking at this wall) depends
     * on the viewing direction.  F0172 maps direction→face:
     *   Facing North → front=South (bit 1), left=East (bit 2), right=West (bit 0)
     *   Facing East  → front=West  (bit 0), left=South(bit 1), right=North(bit 3)
     *   Facing South → front=North (bit 3), left=West (bit 0), right=East (bit 2)
     *   Facing West  → front=East  (bit 2), left=North(bit 3), right=South(bit 1)
     *
     * For the viewport front ornament, the viewed direction from the
     * party toward this square is computed from the relative position.
     * For center cells (relSide==0): viewDir = partyDirection.
     * For side cells: the face visible is the side face, not the front.
     *
     * PRNG (F0169): ((value1*31417 >> 1) + (value2*11) + seed) >> 2) % modulo
     *   value1 = 2000 + (mapX << 5) + mapY_modified
     *   value2 = 3000 + (mapIndex << 6) + mapWidth + mapHeight
     *   modulo = 30
     * If result < randomWallOrnamentCount → ordinal = result + 1.
     *
     * F0171 calls F0170 for each face (right/front/left) with modified
     * mapY and incremented direction for each call.  We compute the
     * front ornament for center walls (what the player actually sees).
     * ────────────────────────────────────────────────────────────────── */
    if (cell.elementType == DUNGEON_ELEMENT_WALL &&
        cell.wallOrnamentOrdinal < 0 &&
        state->world.dungeon &&
        state->world.party.mapIndex >= 0 &&
        state->world.party.mapIndex < (int)state->world.dungeon->header.mapCount) {
        const struct DungeonMapDesc_Compat* ornMap =
            &state->world.dungeon->maps[state->world.party.mapIndex];
        int rwoc = (int)ornMap->randomWallOrnamentCount;
        if (rwoc > 0) {
            /* Determine which face the player is viewing.
             * For front walls (center lane): the face is opposite to
             * the party's approach direction.  The approach direction
             * into this square is the party's facing direction.
             * The "front" face of the wall from the party's perspective
             * is the face OPPOSITE to the party's approach, i.e.:
             *   Party faces North → sees the South face of the wall ahead
             *   Party faces East  → sees the West face
             *   Party faces South → sees the North face
             *   Party faces West  → sees the East face
             *
             * But for side walls (relSide != 0), the visible face is
             * the side that faces the corridor the party is in.
             * We compute the approach direction from relative position. */
            int viewDir = state->world.party.direction;
            /* For side walls: if the wall is to the left (relSide < 0),
             * approach from the right side; adjust viewDir accordingly */
            if (relSide < 0) {
                viewDir = (viewDir + 3) & 3; /* turn left = approach from right */
            } else if (relSide > 0) {
                viewDir = (viewDir + 1) & 3; /* turn right = approach from left */
            }

            /* Front face ornament bit mask per viewing direction.
             * From F0172: facing North→front=South(0x02), etc. */
            static const unsigned char frontFaceMask[4] = {
                0x02, /* North: front = South */
                0x01, /* East:  front = West  */
                0x08, /* South: front = North */
                0x04  /* West:  front = East  */
            };
            int frontAllowed = (square & frontFaceMask[viewDir & 3]) != 0;

            if (frontAllowed) {
                /* F0171 computes the front ornament as the SECOND call
                 * (after right, before left).  The mapY and direction
                 * are modified cumulatively:
                 *   Right: mapY+1, dir+1
                 *   Front: same mapY, dir+1 (so dir is original+2)
                 *   Left:  mapY-1, dir+1 (so dir is original+3)
                 *
                 * For the front ornament (MEDIA720 I34E path):
                 *   value1_mapY = (mapY+1) * (normalize(dir+2) + 1)
                 * where dir = original direction passed to F0171. */
                int ornDir = viewDir; /* F0171 receives the viewing direction */
                int ornMapY = mapY + 1; /* ++P0315_i_MapY from right call */
                int modDir = ((ornDir + 2) & 3) + 1; /* normalize(++dir twice) + 1 */
                int ornY = ornMapY * modDir;

                unsigned int v1 = (unsigned int)(2000 + (mapX << 5) + ornY);
                unsigned int v2 = (unsigned int)(3000 +
                    (state->world.party.mapIndex << 6) +
                    (int)ornMap->width + (int)ornMap->height);
                unsigned int seed = state->world.dungeon->header.ornamentRandomSeed;
                int rndIdx = (int)((((v1 * 31417u) >> 1) + (v2 * 11u) + seed) >> 2) % 30;
                if (rndIdx < rwoc) {
                    cell.wallOrnamentOrdinal = rndIdx + 1; /* INDEX_TO_ORDINAL */
                }
            }
        }
    }

    /* Extract wall ornament ordinal from sensors on this square.
     * In DM, wall ornaments are placed via sensor things whose
     * ornamentOrdinal field specifies the graphic to display.
     * Sensor-placed ornaments OVERRIDE random ornaments.
     * Only walls carry ornaments and champion mirrors. */
    if (cell.elementType == DUNGEON_ELEMENT_WALL &&
        state->world.things && state->world.things->sensors) {
        unsigned short scanThing = viewportStaticFirstThing;
        int scanSafety = 0;
        while (scanThing != THING_ENDOFLIST && scanThing != THING_NONE && scanSafety < 64) {
            if (THING_GET_TYPE(scanThing) == THING_TYPE_SENSOR) {
                int sIdx = THING_GET_INDEX(scanThing);
                if (sIdx >= 0 && sIdx < state->world.things->sensorCount) {
                    DM1_V1_ChampionMirrorFrontWallReceiptPc34 mirrorReceipt;
                    const struct DungeonSensor_Compat* sensor =
                        &state->world.things->sensors[sIdx];
                    if (DM1_V1_ChampionMirror_F0172FrontWallSensorReceiptPc34(
                            (int)sensor->sensorType,
                            (int)sensor->sensorData,
                            (int)sensor->ornamentOrdinal,
                            (int)THING_GET_CELL(scanThing),
                            visibleWallCell,
                            &mirrorReceipt) &&
                        mirrorReceipt.isFrontMirror) {
                        cell.championPortraitOrdinal =
                            mirrorReceipt.championPortraitRenderIndex;
                        cell.championPortraitWallCell =
                            (int)THING_GET_CELL(scanThing);
                        if (mirrorReceipt.wallOrnamentOrdinal > 0) {
                            cell.wallOrnamentOrdinal =
                                mirrorReceipt.wallOrnamentOrdinal;
                        }
                        break;
                    }
                    if ((int)THING_GET_CELL(scanThing) != visibleWallCell) {
                        scanThing = m11_raw_next_thing(state->world.things, scanThing);
                        ++scanSafety;
                        continue;
                    }
                    int ord = (int)sensor->ornamentOrdinal;
                    if (ord > 0) {
                        cell.wallOrnamentOrdinal = ord;
                        break;
                    }
                }
            }
            scanThing = m11_raw_next_thing(state->world.things, scanThing);
            ++scanSafety;
        }
    }

    /* ReDMCSB DUNGEON.C:F0172/F0174 maps visible TextString things on
     * WALL squares to the synthetic current-map inscription ornament slot
     * (wallOrnamentCount + 1).  Hall of Champions mirror TextStrings are
     * invisible champion records paired with the C127 portrait/mirror wall
     * ornament route, whose map-local frame ordinal is the last wall
     * ornament in DM1 map 0.  Sensor ornaments keep precedence. */
    if (DM1_V1_Viewport_SquareIsWallLikePc34Compat(cell.square) && cell.wallOrnamentOrdinal <= 0 &&
        state->world.dungeon && state->world.things && state->world.things->textStrings &&
        state->world.party.mapIndex >= 0 &&
        state->world.party.mapIndex < (int)state->world.dungeon->header.mapCount) {
        const struct DungeonMapDesc_Compat* mapDesc =
            &state->world.dungeon->maps[state->world.party.mapIndex];
        unsigned short scanThing = viewportStaticFirstThing;
        int scanSafety = 0;
        int hasVisibleText = 0;
        while (scanThing != THING_ENDOFLIST && scanThing != THING_NONE && scanSafety < 64) {
            if (THING_GET_TYPE(scanThing) == THING_TYPE_TEXTSTRING) {
                int textIdx = THING_GET_INDEX(scanThing);
                if ((int)THING_GET_CELL(scanThing) == visibleWallCell &&
                    textIdx >= 0 && textIdx < state->world.things->textStringCount) {
                    if (state->mirrorCatalogAvailable && mapDesc->wallOrnamentCount > 0 &&
                        F0676_CHAMPION_MirrorCatalogGetOrdinalForTextStringIndex_Compat(
                            &state->mirrorCatalog, textIdx) >= 0) {
                        cell.wallOrnamentOrdinal = (int)mapDesc->wallOrnamentCount;
                        break;
                    }
                    if (state->world.things->textStrings[textIdx].visible) {
                        hasVisibleText = 1;
                    }
                }
            }
            scanThing = m11_raw_next_thing(state->world.things, scanThing);
            ++scanSafety;
        }
        if (cell.wallOrnamentOrdinal <= 0 && hasVisibleText) {
            cell.wallOrnamentOrdinal = (int)mapDesc->wallOrnamentCount + 1;
        }
    }

    /* Inscription text detection.
     * ReDMCSB DUNGEON.C:2585-2593 sets
     * G0290_T_DungeonView_InscriptionThing when the current wall ornament
     * matches the synthetic current-map inscription ornament. */
    if (DM1_V1_Viewport_SquareIsWallLikePc34Compat(cell.square) &&
        state->world.dungeon &&
        state->world.things &&
        state->world.things->textStrings) {
        int mi = state->world.party.mapIndex;
        if (mi >= 0 && mi < (int)state->world.dungeon->header.mapCount) {
            const struct DungeonMapDesc_Compat* ornMap =
                &state->world.dungeon->maps[mi];
            int inscSlot = (int)ornMap->wallOrnamentCount;
            int localIdx = cell.wallOrnamentOrdinal - 1;
            /* ReDMCSB DUNGEON.C F0172/F0174 lines 2585-2593 store the
             * synthetic inscription wall-ornament *ordinal* in the square
             * aspect, while F0173 lines 2758-2762 maps that local slot to
             * global ornament 0 for drawing.  Match the local slot here;
             * comparing against the global ornament value drops every map
             * whose inscription slot is not local index 0. */
            if (inscSlot >= 0 && inscSlot < 16) {
                /* TextString chains use the packed F0511 square-list
                 * index.  `firstThing` is the broad viewport summary and
                 * may be map-local on later maps; retain the F0172-visible
                 * static chain selected above. */
                unsigned short tScan = viewportStaticFirstThing;
                int tSafety = 0;
                while (tScan != THING_ENDOFLIST && tScan != THING_NONE &&
                       tSafety++ < 64) {
                    if (THING_GET_TYPE(tScan) == THING_TYPE_TEXTSTRING) {
                        int tsIdx = THING_GET_INDEX(tScan);
                        if ((int)THING_GET_CELL(tScan) == visibleWallCell &&
                            tsIdx >= 0 &&
                            tsIdx < state->world.things->textStringCount &&
                            state->world.things->textStrings[tsIdx].visible) {
                            /* ReDMCSB DUNGEON.C F0172/F0174 turns this
                             * visible wall TextString into the map-local
                             * synthetic inscription ornament before
                             * DUNVIEW.C F0107 renders M648. */
                            if (localIdx != inscSlot) {
                                cell.wallOrnamentOrdinal = inscSlot + 1;
                            }
                            cell.inscriptionTextIndex = tsIdx;
                            break;
                        }
                    }
                    tScan = m11_raw_next_thing(state->world.things, tScan);
                }
            }
        }
    }

    /* Extract floor ornament ordinal from random generation or sensor things.
     * ReDMCSB F0172 assigns random floor ornaments only on the
     * corridor/fakewall path, but the pit/teleporter path still scans
     * floor sensors.  Stairs route through T0172046_Stairs without
     * assigning M558_FLOOR_ORNAMENT_ORDINAL; their 0x08 bit is
     * orientation, not random-ornament permission. */
    if (cell.valid && m11_viewport_cell_is_wall_free(&cell)) {
        cell.floorOrnamentOrdinal = m11_compute_floor_ornament_ordinal(
            state, state->world.party.mapIndex, mapX, mapY, square);
    }

    cell.dm1MaterializationDecisionReady =
        m11_build_dm1_viewport_materialization_decision(
            state, &cell, &cell.dm1MaterializationDecision);

    if (outCell) {
        *outCell = cell;
    }
    return 1;
}

int M11_GameView_ProbeViewportFloorItemCounts(
    const M11_GameViewState* state,
    int relativeForward,
    int relativeSide,
    int* outMapX,
    int* outMapY,
    int* outElementType,
    int* outFloorItems,
    int* outSummaryItems) {
    M11_ViewportCell cell;

    if (!state || !outMapX || !outMapY || !outElementType ||
        !outFloorItems || !outSummaryItems) {
        return 0;
    }

    memset(&cell, 0, sizeof(cell));
    if (!m11_sample_viewport_cell(state, relativeForward, relativeSide, &cell) ||
        !cell.valid) {
        return 0;
    }

    *outMapX = cell.mapX;
    *outMapY = cell.mapY;
    *outElementType = cell.elementType;
    *outFloorItems = cell.floorItemCount;
    *outSummaryItems = cell.summary.items;
    return 1;
}

static int m11_viewport_cell_is_open(const M11_ViewportCell* cell) {
    if (!cell || !cell->valid) {
        return 0;
    }
    return DM1_V1_Viewport_SquareIsOpenPc34Compat(cell->square);
}

static int m11_viewport_cell_is_wall_like(const M11_ViewportCell* cell) {
    int effectiveElement;
    if (!cell) {
        return 0;
    }
    if (!cell->valid) {
        return 1;
    }
    effectiveElement = DM1_V1_Viewport_EffectiveElementForSquarePc34Compat(cell->square);
    /* ReDMCSB DUNGEON.C F0172: closed fakewalls become
     * DUNGEON_ELEMENT_WALL for viewport aspect, while open fakewalls become
     * corridors.  Keep the explicit DUNGEON_ELEMENT_FAKEWALL mention here so
     * the front-wall depth gate can prove the fakewall source boundary. */
    return effectiveElement == DUNGEON_ELEMENT_WALL ||
           (cell->elementType == DUNGEON_ELEMENT_FAKEWALL &&
            effectiveElement == DUNGEON_ELEMENT_WALL);
}

static int m11_viewport_cell_is_wall_free(const M11_ViewportCell* cell) {
    int effectiveElement;
    if (!cell || !cell->valid) {
        return 0;
    }
    effectiveElement = DM1_V1_Viewport_EffectiveElementForSquarePc34Compat(cell->square);
    /* ReDMCSB DUNGEON.C F0172 gives corridor, pit, and teleporter squares the
     * floor-ornament/sensor path.  Stairs are excluded there because bit 0x08
     * is orientation, not random-ornament permission. */
    return effectiveElement == DUNGEON_ELEMENT_CORRIDOR ||
           effectiveElement == DUNGEON_ELEMENT_PIT ||
           effectiveElement == DUNGEON_ELEMENT_TELEPORTER;
}

static int m11_build_front_text_readout(const M11_GameViewState* state,
                                        const M11_ViewportCell* cell,
                                        char* outTitle,
                                        size_t outTitleSize,
                                        char* outDetail,
                                        size_t outDetailSize) {
    unsigned short thing;

    if (!state || !cell || !cell->valid || !outTitle || !outDetail) {
        return 0;
    }

    thing = cell->firstThing;
    while (thing != THING_ENDOFLIST && thing != THING_NONE) {
        int thingType = THING_GET_TYPE(thing);
        int thingIndex = THING_GET_INDEX(thing);
        if (thingType == THING_TYPE_TEXTSTRING && state->world.things &&
            state->world.things->textStrings && thingIndex >= 0 &&
            thingIndex < state->world.things->textStringCount) {
            const struct DungeonTextString_Compat* textThing = &state->world.things->textStrings[thingIndex];
            char decoded[96];
            if (state->world.things->textData && state->world.things->textDataWordCount > 0 &&
                F0507_DUNGEON_DecodeTextAtOffset_Compat(state->world.things->textData,
                                                        state->world.things->textDataWordCount,
                                                        textThing->textDataWordOffset,
                                                        decoded,
                                                        sizeof(decoded)) >= 0 &&
                decoded[0] != '\0') {
                snprintf(outTitle, outTitleSize, "TEXT PLAQUE");
                snprintf(outDetail, outDetailSize, "%s", decoded);
                return 1;
            }
            snprintf(outTitle, outTitleSize, "TEXT PLAQUE");
            snprintf(outDetail, outDetailSize, "TEXT OFFSET %u (DECODE UNAVAILABLE)",
                     (unsigned int)textThing->textDataWordOffset);
            return 1;
        }
        thing = m11_raw_next_thing(state->world.things, thing);
    }

    return 0;
}

/* ── ReDMCSB CLIKVIEW.C G0462 object pile clickable boxes ──
 * { X1, X2, Y1, Y2 } in viewport-relative coordinates.
 * The original uses these for hit-testing item piles at depth-1. */
static const int g_objectPileBoxes[4][4] = {
    {  24, 111, 115, 135 },  /* C00 FRONT LEFT  (scaled for 224-wide viewport) */
    { 112, 199, 115, 135 },  /* C01 FRONT RIGHT */
    { 112, 183,  89, 114 },  /* C02 BACK RIGHT  */
    {  40, 111,  89, 114 }   /* C03 BACK LEFT   */
};

/* ReDMCSB CLIKVIEW.C C05 door button / wall ornament clickable zone. */
static const int g_wallOrnamentBox[4] = { 96, 127, 35, 63 };

/* F0115's C2548 alcove-object pass may place the real object's clickable
 * material below C05's generic wall-ornament rectangle.  Keep the C05 box
 * for bare ornaments and sensors, but let the rendered original material
 * own the object interaction zone. */
static int m11_dm1_alcove_item_hit_test(int x, int y) {
    const M11_Dm1FloorItemHostPresentationReceipt *receipt =
        &s_m11_dm1_alcove_item_host_presentation_receipt;

    return receipt->valid && !receipt->floorItemLane &&
           receipt->usesF0791Blit && receipt->destinationW > 0 &&
           receipt->destinationH > 0 &&
           x >= receipt->destinationX &&
           x < receipt->destinationX + receipt->destinationW &&
           y >= receipt->destinationY &&
           y < receipt->destinationY + receipt->destinationH;
}

/* (declared in m11_game_view.h so tests can pin the F0376 contract) */
int m11_point_in_source_box(int px, int py, const int box[4]) {
    return px >= box[0] && px <= box[1] && py >= box[2] && py <= box[3];
}

static int m11_csb_f0329_throw_leader_hand(
    M11_GameViewState* state,
    int championIndex,
    unsigned short leaderThing);

/* Grab the first floor item from the front cell into the leader hand.
 * Mirrors ReDMCSB CLIKVIEW.C F0373. */
static int m11_c080_grab_leader_hand(M11_GameViewState* state,
                                     int viewCell) {
    M11_ViewportCell cell;
    unsigned short item;
    int targetMapX, targetMapY;

    if (!state || !state->active) return 0;
    if (DM1_V1_M11Runtime_GetLeaderHandThingPc34Compat(state) != THING_NONE) return 0;

    /* ReDMCSB CLIKVIEW.C F0373:117-128 removes G0292's rendered pile-top
     * object and calls F0297 directly.  F0297 owns the separate leader hand
     * (G4055); it does not require a free inventory slot.  F0302's empty-slot
     * branch applies only to a click on an inventory/chest slot, never to a
     * dungeon-floor pickup. */

    memset(&cell, 0, sizeof(cell));
    if (viewCell >= 2) {
        /* Cells 2,3 = front cell (back-right/back-left of front square) */
        if (!m11_sample_viewport_cell(state, 1, 0, &cell) || !cell.valid) return 0;
    } else {
        /* Cells 0,1 = party square */
        if (!m11_sample_viewport_cell(state, 0, 0, &cell) || !cell.valid) return 0;
    }
    targetMapX = cell.mapX;
    targetMapY = cell.mapY;

    item = m11_find_pile_top_item_on_square(
        &state->world,
        state->world.party.mapIndex,
        targetMapX, targetMapY,
        viewCell,
        state->world.party.direction);
    if (item == THING_NONE) return 0;

    if (!m11_unlink_thing_from_square(&state->world,
                                      state->world.party.mapIndex,
                                      targetMapX, targetMapY, item)) {
        return 0;
    }

    if (!DM1_V1_M11Runtime_SetLeaderHandObjectPc34Compat(state, item)) {
        /* Rollback */
        m11_prepend_thing_to_square(&state->world,
                                    state->world.party.mapIndex,
                                    targetMapX, targetMapY, item);
        return 0;
    }

    {
        char itemName[48];
        m11_get_source_item_name(state, state->world.things, item, itemName, sizeof(itemName));
        m11_set_status(state, "PICKUP", itemName);
    }
    m11_refresh_hash(state);
    return 1;
}

/* ReDMCSB CLIKVIEW.C F0373 tests the G2210 rectangle assembled by F0115,
 * then moves that rectangle's G0292 pile-top object into G4055.  Targets are
 * stored in paint order, so scan backwards to match the visible top object. */
static int m11_c080_grab_rendered_pile_target(M11_GameViewState* state,
                                              int localX,
                                              int localY) {
    int i;
    int screenX;
    int screenY;

    if (!state || !state->active ||
        DM1_V1_M11Runtime_GetLeaderHandThingPc34Compat(state) != THING_NONE) {
        return 0;
    }
    screenX = localX + M11_VIEWPORT_X;
    screenY = localY + M11_VIEWPORT_Y;
    for (i = s_m11_dm1_rendered_pile_target_count - 1; i >= 0; --i) {
        const M11_Dm1RenderedPileTarget* target =
            &s_m11_dm1_rendered_pile_targets[i];
        char itemName[48];
        if (!target->valid || target->mapIndex != state->world.party.mapIndex ||
            screenX < target->x ||
            screenX >= target->x + target->w || screenY < target->y ||
            screenY >= target->y + target->h) {
            continue;
        }
        if (!m11_unlink_thing_from_square(&state->world,
                                          target->mapIndex,
                                          target->mapX, target->mapY,
                                          target->thing)) {
            return 0;
        }
        if (!DM1_V1_M11Runtime_SetLeaderHandObjectPc34Compat(state,
                                                              target->thing)) {
            m11_prepend_thing_to_square(&state->world,
                                        target->mapIndex,
                                        target->mapX, target->mapY,
                                        target->thing);
            return 0;
        }
        m11_get_source_item_name(state, state->world.things, target->thing,
                                 itemName, sizeof(itemName));
        m11_set_status(state, "PICKUP", itemName);
        m11_refresh_hash(state);
        return 1;
    }
    return 0;
}

/* Drop the leader hand object onto a floor cell or alcove.
 * Mirrors ReDMCSB CLIKVIEW.C F0374. */
static int m11_c080_drop_leader_hand(M11_GameViewState* state,
                                     int viewCell) {
    unsigned short item;
    int targetMapX, targetMapY;
    M11_ViewportCell cell;

    if (!state || !state->active) return 0;
    item = DM1_V1_M11Runtime_GetLeaderHandThingPc34Compat(state);
    if (item == THING_NONE) return 0;

    memset(&cell, 0, sizeof(cell));
    /* For alcove (viewCell == 4), use front cell coordinates */
    if (viewCell >= 2) {
        if (!m11_sample_viewport_cell(state, 1, 0, &cell) || !cell.valid) return 0;
    } else {
        if (!m11_sample_viewport_cell(state, 0, 0, &cell) || !cell.valid) return 0;
    }
    targetMapX = cell.mapX;
    targetMapY = cell.mapY;

    DM1_V1_M11Runtime_ClearLeaderHandObjectPc34Compat(state);

    if (!m11_prepend_thing_to_square(&state->world,
                                     state->world.party.mapIndex,
                                     targetMapX, targetMapY, item)) {
        /* Rollback */
        DM1_V1_M11Runtime_SetLeaderHandObjectPc34Compat(state, item);
        return 0;
    }

    {
        char itemName[48];
        m11_get_source_item_name(state, state->world.things, item, itemName, sizeof(itemName));
        m11_set_status(state, "DROP", itemName);
    }
    m11_refresh_hash(state);
    return 1;
}

static M11_GameInputResult m11_process_csb_v1_c080_click(M11_GameViewState* state,
                                                         int localX,
                                                         int localY) {
    int queued;
    unsigned short leaderHand;

    if (!state || state->sourceKind != M11_GAME_SOURCE_CSB_BOOT ||
        !state->csbBootProfile) {
        return M11_GAME_INPUT_IGNORED;
    }
    if (DM1_V1_M11Runtime_GetLeaderHandThingPc34Compat(state) != THING_NONE &&
        localY >= 14 && localY <= 69) {
        unsigned short throwThing = DM1_V1_M11Runtime_GetLeaderHandThingPc34Compat(state);
        int championIndex = state->world.party.activeChampionIndex;
        int throwSide = (localX < 112) ? 0 : 1;

        if (!m11_csb_f0329_throw_leader_hand(
                state,
                championIndex,
                throwThing)) {
            return M11_GAME_INPUT_IGNORED;
        }
        DM1_V1_M11Runtime_ClearLeaderHandObjectPc34Compat(state);
        m11_sync_csb_state_from_boot_profile(state, state->csbBootProfile);
        m11_set_status(state, "THROW",
                       throwSide ? "THROWN RIGHT" : "THROWN LEFT");
        /* ReDMCSB CLIKVIEW.C F0375 lines 243-285: accepted leader-hand
         * throws consume the waiting input frame after F0329/F0328 creates
         * the projectile.  Keep CSB runtime throws on the same C080 boundary
         * without routing through DM1 GameWorld projectile storage. */
        (void)m11_apply_tick(state, CMD_NONE, "THROW");
        m11_set_status(state, "THROW",
                       throwSide ? "THROWN RIGHT" : "THROWN LEFT");
        m11_refresh_hash(state);
        return M11_GAME_INPUT_REDRAW;
    }
    if (!m11_point_in_source_box(localX, localY, g_wallOrnamentBox)) {
        return M11_GAME_INPUT_IGNORED;
    }

    /* ReDMCSB MOVESENS.C F0276 lines 1737-1785: a C080 viewport
     * click on C05/front-wall ornament enters the CSB wall-square
     * sensor path, not the DM1 M11 world thing-list path. */
    queued =
        csb_v1_boot_runtime_trigger_front_wall_ornament_click_pc34(
            (CSB_V1_BootProfile*)state->csbBootProfile,
            DM1_V1_M11Runtime_GetLeaderHandThingPc34Compat(state),
            &leaderHand);
    if (queued <= 0) {
        return M11_GAME_INPUT_IGNORED;
    }
    if (leaderHand == THING_NONE || leaderHand == THING_ENDOFLIST) {
        DM1_V1_M11Runtime_ClearLeaderHandObjectPc34Compat(state);
    } else {
        (void)DM1_V1_M11Runtime_SetLeaderHandObjectPc34Compat(state, leaderHand);
    }

    m11_sync_csb_state_from_boot_profile(state, state->csbBootProfile);
    m11_set_status(state, "CSB", "WALL SENSOR");
    return M11_GAME_INPUT_REDRAW;
}

static M11_GameInputResult m11_process_v1_c080_click(M11_GameViewState* state,
                                                       int x,
                                                       int y) {
    M11_ViewportCell frontCell;
    int localX;
    int localY;
    int facingAlcove;
    int facingWall;
    int alcoveItemHit;

    if (!state || !state->active) {
        return M11_GAME_INPUT_IGNORED;
    }

    localX = x - M11_VIEWPORT_X;
    localY = y - M11_VIEWPORT_Y;

    if (state->sourceKind == M11_GAME_SOURCE_CSB_BOOT) {
        return m11_process_csb_v1_c080_click(state, localX, localY);
    }

    /* ReDMCSB CLIKVIEW.C F0377 subtracts COORD.C viewport origin
     * G2067/G2068, then tests G2210_aai_XYZ_DungeonViewClickable[]. */
    memset(&frontCell, 0, sizeof(frontCell));
    (void)m11_get_front_cell(state, &frontCell);

    /* The source's G0286_B_FacingAlcove is the render-time F0149 result
     * (DUNVIEW.C:3726); classifying here through the same F0174-wired
     * current-map alcove list keeps the click route in agreement. */
    m11_dm1_wire_current_map_alcove_list(state, state->world.party.mapIndex);
    facingAlcove = frontCell.valid &&
                   frontCell.elementType == DUNGEON_ELEMENT_WALL &&
                   frontCell.wallOrnamentOrdinal >= 0 &&
                   dm1_v1_wall_ornament_is_alcove_local_ordinal_pc34(
                       frontCell.wallOrnamentOrdinal);
    facingWall = frontCell.valid &&
                 frontCell.elementType == DUNGEON_ELEMENT_WALL;
    alcoveItemHit = facingAlcove && m11_dm1_alcove_item_hit_test(x, y);

    /* ── Door button (CLIKVIEW.C:356-390) ── */
    if (frontCell.valid && frontCell.elementType == DUNGEON_ELEMENT_DOOR &&
        frontCell.hasDoorThing && state->world.things && state->world.things->doors) {
        int doorIdx = THING_GET_INDEX(frontCell.firstThing);
        if (doorIdx >= 0 && doorIdx < state->world.things->doorCount &&
            state->world.things->doors[doorIdx].button) {
            if (DM1_V1_M11Runtime_GetLeaderHandThingPc34Compat(state) == THING_NONE) {
                static const int kDoorButtonD1CBox[4] = { 160, 175, 44, 52 };
                /* ReDMCSB DUNVIEW.C lines 4207-4212 copies the rendered
                 * D1C door-button zone (C1950 + C3_VIEW_DOOR_BUTTON_D1C)
                 * into G2210[C05], then CLIKVIEW.C lines 356-390 tests
                 * C080 clicks against that zone before scheduling C10
                 * EVENT_DOOR.  The D1C bitmap zone is 160..175,44..52;
                 * the wall-ornament box is only for front-wall ornaments. */
                if (m11_point_in_source_box(localX, localY, kDoorButtonD1CBox)) {
                    m11_audio_emit_source_sound(state, 1, M11_AUDIO_MARKER_DOOR);
                    if (!m11_toggle_front_door(state)) {
                        return M11_GAME_INPUT_IGNORED;
                    }
                    return M11_GAME_INPUT_REDRAW;
                }
            } else {
                static const int kDoorButtonD1CBox[4] = { 160, 175, 44, 52 };
                /* ReDMCSB CLIKVIEW.C F0377 opens the D1C door only from
                 * the empty-hand door-button route; a wrong item on the
                 * keyhole/button box must not fall through into throw/drop. */
                if (m11_point_in_source_box(localX, localY, kDoorButtonD1CBox)) {
                    return M11_GAME_INPUT_IGNORED;
                }
            }
        }
    }

    /* C127/D1C mirror clicks use the current C026 receipt's actual
     * destination. A generic HoC rectangle cannot select a placeholder. */
    {
        int mirrorOrdinal = -1;
        if (m11_front_mirror_hit_test(state, localX, localY, &mirrorOrdinal) &&
            m11_select_mirror_candidate_by_ordinal(state, mirrorOrdinal)) {
            return M11_GAME_INPUT_REDRAW;
        }
    }

    /* ═══ ReDMCSB CLIKVIEW.C F0375 — throw object ═══
     * If leader hand holds an item and click is in the upper viewport
     * (y < 102 in source coords), attempt to throw left or right based
     * on x position relative to center.  F0329_CHAMPION_IsLeaderHandObjectThrown
     * in the original places the thrown object as a projectile. */
    if (DM1_V1_M11Runtime_GetLeaderHandThingPc34Compat(state) != THING_NONE &&
        localY >= 14 && localY <= 69) {
        /* Upper viewport = throw zone per F0375 */
        int throwSide = (localX < 112) ? 0 : 1; /* 0=left, 1=right */
        unsigned short throwThing = DM1_V1_M11Runtime_GetLeaderHandThingPc34Compat(state);
        int championIndex = state->world.party.activeChampionIndex;
        struct ChampionState_Compat* champ;
        unsigned short actionHandThing;
        int spawned;
        DM1_LeaderHandThrowAdmissionInputF0329Pc34 throwAdmission;
        DM1_LeaderHandThrowAdmissionReceiptF0329Pc34 throwReceipt;

        if (championIndex < 0 || championIndex >= CHAMPION_MAX_PARTY ||
            championIndex >= state->world.party.championCount ||
            !state->world.party.champions[championIndex].present) {
            return M11_GAME_INPUT_IGNORED;
        }

        champ = &state->world.party.champions[championIndex];
        memset(&throwAdmission, 0, sizeof(throwAdmission));
        memset(&throwReceipt, 0, sizeof(throwReceipt));
        throwAdmission.things = state->world.things;
        throwAdmission.party = &state->world.party;
        throwAdmission.leaderIndex = championIndex;
        throwAdmission.leaderHandThing = throwThing;
        throwAdmission.throwSide = throwSide;
        if (!dm1_v1_leader_hand_throw_admit_f0329_pc34(
                &throwAdmission, &throwReceipt) || !throwReceipt.valid) {
            return M11_GAME_INPUT_IGNORED;
        }
        actionHandThing = champ->inventory[CHAMPION_SLOT_ACTION_HAND];
        /* ReDMCSB CHAMPION.C F0328 lines 2146-2162 and F0329 lines
         * 2196-2208: a leader-hand throw temporarily places the leader
         * object in the champion action hand for F0312 strength, then
         * restores the original action hand before F0212 creates the
         * projectile.  Firestaff clears the leader hand only after F0328
         * accepts the throw, preserving inventory on pre-F0328 failure;
         * PJE-05 full-list overflow is an accepted throw with no new slot. */
        champ->inventory[CHAMPION_SLOT_ACTION_HAND] = throwThing;
        spawned = m11_dm1_f0328_spawn_thrown_thing(state, championIndex,
                                                   champ, throwThing,
                                                   throwSide);
        champ->inventory[CHAMPION_SLOT_ACTION_HAND] = actionHandThing;
        if (!spawned) {
            return M11_GAME_INPUT_IGNORED;
        }

        DM1_V1_M11Runtime_ClearLeaderHandObjectPc34Compat(state);
        m11_set_status(state, "THROW",
                        throwSide ? "THROWN RIGHT" : "THROWN LEFT");
        /* ReDMCSB CLIKVIEW.C F0375 lines 243-285 (PC34 CHANGE8_11_FIX)
         * sets G0321_B_StopWaitingForPlayerInput after an accepted
         * F0329/F0328 leader-hand throw.  Mirror that by consuming a real
         * source tick immediately; this advances the first C48/C49
         * projectile move and ages the F0328 cooldowns just like other
         * meaningful player actions. */
        (void)m11_apply_tick(state, CMD_NONE, "THROW");
        m11_set_status(state, "THROW",
                        throwSide ? "THROWN RIGHT" : "THROWN LEFT");
        m11_refresh_hash(state);
        return M11_GAME_INPUT_REDRAW;
    }

    /* ═══ ReDMCSB CLIKVIEW.C F0377 — item interaction ═══ */

    if (DM1_V1_M11Runtime_GetLeaderHandThingPc34Compat(state) == THING_NONE) {
        /* ── Empty hand: grab floor items or touch wall sensor ──
         * F0377 iterates view cells 0..5 and grabs from the first
         * matching pile box.  Cell 5 = wall ornament/door button
         * (alcove or wall sensor). */
        if (m11_c080_grab_rendered_pile_target(state, localX, localY)) {
            return M11_GAME_INPUT_REDRAW;
        }
        if (facingWall &&
            m11_point_in_source_box(localX, localY, g_wallOrnamentBox) &&
            m11_dm1_apply_fountain_click(state, &frontCell)) {
            return M11_GAME_INPUT_REDRAW;
        }
        /* DM1 production has real F0115 rectangles above. Retain the
         * historical fixed boxes only for non-source diagnostic sessions;
         * otherwise an unavailable/occluded bitmap could still be picked. */
        if (!m11_is_dm1_source_kind(state->sourceKind)) {
            int vc;
            for (vc = 0; vc < 4; ++vc) {
                if (m11_point_in_source_box(localX, localY, g_objectPileBoxes[vc])) {
                    if (m11_c080_grab_leader_hand(state, vc)) {
                        return M11_GAME_INPUT_REDRAW;
                    }
                    break; /* No item to grab at this cell */
                }
            }
        }
        /* Wall ornament zone: alcove grab or wall sensor trigger */
        if (alcoveItemHit ||
            m11_point_in_source_box(localX, localY, g_wallOrnamentBox)) {
            if (facingAlcove) {
                /* Grab from alcove (front cell, view cell 2 = back-right
                 * for front square in DM1's cell numbering) */
                if (m11_c080_grab_leader_hand(state, 2)) {
                    return M11_GAME_INPUT_REDRAW;
                }
            }
            /* Wall sensor trigger (F0372: TouchFrontWallSensor).
             * ReDMCSB F0275: walk the sensor thing list on the front
             * wall square, check sensorType for wall click types (1-18),
             * and fire the matching sensor.  We call the sensor pipeline
             * directly with a wall-click context. */
            if (frontCell.valid && frontCell.summary.sensors > 0 &&
                state->world.things && state->world.things->sensors) {
                /* ReDMCSB F0275/F0726: enumerate sensors on the front
                 * wall square and fire wall-click triggers. */
                struct SensorOnSquare_Compat sensorsOnSq[SENSOR_ENUM_CAPACITY];
                int sensCount = 0;
                unsigned short sThing = frontCell.firstThing;
                int sSafety = 0;
                memset(sensorsOnSq, 0, sizeof(sensorsOnSq));
                while (sThing != THING_ENDOFLIST && sThing != THING_NONE &&
                       sSafety++ < 64 && sensCount < SENSOR_ENUM_CAPACITY) {
                    if (THING_GET_TYPE(sThing) == THING_TYPE_SENSOR) {
                        int si = THING_GET_INDEX(sThing);
                        if (si >= 0 && si < state->world.things->sensorCount) {
                            sensorsOnSq[sensCount].found = 1;
                            sensorsOnSq[sensCount].sensorIndex = si;
                            sensorsOnSq[sensCount].sensorType =
                                (int)state->world.things->sensors[si].sensorType;
                            sensorsOnSq[sensCount].sensorData =
                                state->world.things->sensors[si].sensorData;
                            sensorsOnSq[sensCount].targetMapX =
                                (int)state->world.things->sensors[si].targetMapX;
                            sensorsOnSq[sensCount].targetMapY =
                                (int)state->world.things->sensors[si].targetMapY;
                            sensorsOnSq[sensCount].cell =
                                (int)(state->world.things->sensors[si].targetCell & 3);
                            sensorsOnSq[sensCount].isLocal =
                                state->world.things->sensors[si].localEffect;
                            sensCount++;
                        }
                    }
                    sThing = m11_raw_next_thing(state->world.things, sThing);
                }
                if (sensCount > 0) {
                    struct WallSensorContext_Compat ctx;
                    struct SensorTriggerResultList_Compat trigResults;
                    memset(&ctx, 0, sizeof(ctx));
                    ctx.mapX = frontCell.mapX;
                    ctx.mapY = frontCell.mapY;
                    ctx.cell = 0;
                    ctx.leaderEmptyHanded =
                        (DM1_V1_M11Runtime_GetLeaderHandThingPc34Compat(state) == THING_NONE) ? 1 : 0;
                    ctx.leaderHandObjectType = ctx.leaderEmptyHanded ? -1 :
                        (int)THING_GET_TYPE(DM1_V1_M11Runtime_GetLeaderHandThingPc34Compat(state));
                    ctx.leaderIndex = state->world.party.activeChampionIndex;
                    ctx.sensorCountInCell = sensCount;
                    memset(&trigResults, 0, sizeof(trigResults));
                    if (F0726_SENSOR_ProcessWallClick_Compat(
                            sensorsOnSq, sensCount,
                            state->world.things->sensors,
                            state->world.things->sensorCount,
                            &ctx, &trigResults) && trigResults.count > 0) {
                        /* Convert trigger results to effect list */
                        struct SensorEffectList_Compat effects;
                        int ri;
                        memset(&effects, 0, sizeof(effects));
                        for (ri = 0; ri < trigResults.count &&
                             effects.count < SENSOR_EFFECT_LIST_MAX_COUNT; ++ri) {
                            const struct SensorTriggerResult_Compat* tr =
                                &trigResults.results[ri];
                            if (!tr->triggered) continue;
                            if (tr->effectKind == SENSOR_EFFECT_CHAMPION &&
                                tr->sensorIndex >= 0 &&
                                tr->sensorIndex < state->world.things->sensorCount) {
                                int mirrorOrdinal =
                                    (int)state->world.things->sensors[tr->sensorIndex].sensorData;
                                /* ReDMCSB MOVESENS.C F0275 lines 1501-1503
                                 * handles C127 inside the wall-click sensor
                                 * loop by calling REVIVE.C F0280 with the
                                 * sensor data.  The D1C portrait fast-path
                                 * above covers visible portrait clicks; this
                                 * branch keeps the source wall-sensor route
                                 * working for the same C127 sensor result
                                 * instead of treating it as a remote toggle. */
                                if (m11_select_mirror_candidate_by_ordinal(
                                        state, mirrorOrdinal)) {
                                    return M11_GAME_INPUT_REDRAW;
                                }
                                continue;
                            }
                            effects.effects[effects.count].kind =
                                SENSOR_EFFECT_TOGGLE_REMOTE;
                            effects.effects[effects.count].destMapX = tr->targetMapX;
                            effects.effects[effects.count].destMapY = tr->targetMapY;
                            effects.effects[effects.count].textIndex = tr->resolvedEffect;
                            effects.count++;
                        }
                        m11_apply_sensor_effects(state, &effects);
                        if (trigResults.results[0].audible) {
                            m11_audio_emit_source_sound(state, 1,
                                                      M11_AUDIO_MARKER_DOOR);
                        }
                    }
                    m11_set_status(state, "WALL", "SENSOR ACTIVATED");
                    return M11_GAME_INPUT_REDRAW;
                }
            }
        }
    } else {
        /* ── Item in hand: throw or drop ── */
        /* ReDMCSB CLIKVIEW.C checks G0288_B_FacingFountain before the
         * generic wall-drop path.  Keep this before the broad wall branch;
         * otherwise a held flask/waterskin can never reach F0601/CLIKVIEW's
         * fill operation. */
        if (facingWall &&
            m11_point_in_source_box(localX, localY, g_wallOrnamentBox) &&
            m11_dm1_apply_fountain_click(state, &frontCell)) {
            return M11_GAME_INPUT_REDRAW;
        } else if (facingWall && !facingAlcove) {
            /* F0377: Wall ahead, not alcove → drop at party-square cells
             * 0..1, then check wall ornament zone for sensor. */
            int vc;
            for (vc = 0; vc < 2; ++vc) {
                if (m11_point_in_source_box(localX, localY, g_objectPileBoxes[vc])) {
                    if (m11_c080_drop_leader_hand(state, vc)) {
                        return M11_GAME_INPUT_REDRAW;
                    }
                    break;
                }
            }
            /* Wall ornament zone → wall sensor touch */
            if (alcoveItemHit ||
                m11_point_in_source_box(localX, localY, g_wallOrnamentBox)) {
                /* Sensor click pass-through handled by existing system */
            }
        } else if (facingWall && frontCell.wallOrnamentOrdinal >= 0 &&
                   !facingAlcove) {
            /* Non-fountain wall ornament with item: touch sensor */
            if (m11_point_in_source_box(localX, localY, g_wallOrnamentBox)) {
                /* Wall sensor pass-through */
            }
        } else if (facingWall && facingAlcove) {
            /* F0377: Alcove ahead → drop into alcove */
            if (alcoveItemHit ||
                m11_point_in_source_box(localX, localY, g_wallOrnamentBox)) {
                /* Check if we're dropping champion bones at Vi Altar.
                 * ReDMCSB: G0287_B_FacingViAltar + icon == C147_ICON_JUNK_CHAMPION_BONES
                 * triggers C13_EVENT_VI_ALTAR_REBIRTH.  Vi Altar is a specific
                 * wall ornament (varies by dungeon). */
                {
                    unsigned short dropThing = DM1_V1_M11Runtime_GetLeaderHandThingPc34Compat(state);
                    int dropIcon = (dropThing != THING_NONE)
                        ? m11_object_icon_index_for_thing(state, state->world.things, dropThing)
                        : -1;
                    if (dropIcon == 147) { /* C147_ICON_JUNK_CHAMPION_BONES */
                        if (m11_c080_drop_leader_hand(state, 4)) {
                            m11_set_status(state, "ALTAR", "CHAMPION BONES PLACED — REBIRTH");
                            /* ReDMCSB CLIKVIEW.C F0374: dropping bones at Vi Altar
                             * schedules C13_EVENT_VI_ALTAR_REBIRTH at gameTick + 1.
                             * The event handler resurrects the champion from bones. */
                            {
                                struct TimelineEvent_Compat rebirthEvent;
                                memset(&rebirthEvent, 0, sizeof(rebirthEvent));
                                rebirthEvent.fireAtTick = state->world.gameTick + 1;
                                rebirthEvent.mapIndex = state->world.party.mapIndex;
                                rebirthEvent.mapX = frontCell.mapX;
                                rebirthEvent.mapY = frontCell.mapY;
                                rebirthEvent.kind = 13; /* DM1_EVENT_VI_ALTAR_REBIRTH */
                                (void)F0721_TIMELINE_Schedule_Compat(
                                    &state->world.timeline, &rebirthEvent);
                            }
                            return M11_GAME_INPUT_REDRAW;
                        }
                    }
                }
                if (m11_c080_drop_leader_hand(state, 4)) {
                    return M11_GAME_INPUT_REDRAW;
                }
            }
        } else {
            /* F0377: Open square ahead → drop at front-cell piles 0..3 */
            int vc;
            for (vc = 0; vc < 4; ++vc) {
                if (m11_point_in_source_box(localX, localY, g_objectPileBoxes[vc])) {
                    if (m11_c080_drop_leader_hand(state, vc)) {
                        return M11_GAME_INPUT_REDRAW;
                    }
                    break;
                }
            }
        }
    }

    return M11_GAME_INPUT_IGNORED;
}

static int m11_inspect_front_cell(M11_GameViewState* state) {
    M11_ViewportCell frontCell;
    char title[64];
    char detail[128];

    if (!state || !state->active) {
        return 0;
    }

    memset(&frontCell, 0, sizeof(frontCell));
    if (!m11_sample_viewport_cell(state, 1, 0, &frontCell) || !frontCell.valid) {
        m11_set_status(state, "INSPECT", "VOID AHEAD");
        m11_set_inspect_readout(state, "VOID", "TURN TO RE-ENTER THE MAP");
        return 1;
    }

    if (m11_build_front_text_readout(state, &frontCell,
                                     title, sizeof(title),
                                     detail, sizeof(detail))) {
        if (m11_front_mirror_host_material_ready(state) &&
            M11_GameView_SelectFrontMirrorCandidate(state) == 1) {
            return 1;
        }
        m11_set_status(state, "INSPECT", "READ TEXT");
        m11_set_inspect_readout(state, title, detail);
        /* Show a dialog overlay so the text plaque is prominently
         * displayed; the player dismisses it with any key. */
        M11_GameView_ShowDialogOverlay(state, detail);
        return 1;
    }

    if (frontCell.elementType == DUNGEON_ELEMENT_DOOR) {
        snprintf(title, sizeof(title), "FRONT DOOR");
        snprintf(detail, sizeof(detail), "%s, STATE %d, %s",
                 frontCell.doorVertical ? "VERTICAL" : "HORIZONTAL",
                 frontCell.doorState,
                 m11_viewport_cell_is_open(&frontCell) ? "OPEN ENOUGH TO CROSS" : "STILL CLOSED");
        m11_set_status(state, "INSPECT", "DOOR CHECK");
        m11_set_inspect_readout(state, title, detail);
        return 1;
    }

    if (frontCell.summary.groups > 0) {
        snprintf(title, sizeof(title), "CREATURE CONTACT");
        snprintf(detail, sizeof(detail), "%d GROUP TARGET%s IN FRONT CELL",
                 frontCell.summary.groups,
                 frontCell.summary.groups == 1 ? "" : "S");
        m11_set_status(state, "INSPECT", "ENEMY SPOTTED");
        m11_set_inspect_readout(state, title, detail);
        return 1;
    }

    if (frontCell.summary.items > 0 || frontCell.summary.projectiles > 0 ||
        frontCell.summary.explosions > 0 || frontCell.summary.sensors > 0 ||
        frontCell.summary.teleporters > 0 || frontCell.summary.textStrings > 0 ||
        frontCell.elementType == DUNGEON_ELEMENT_PIT ||
        frontCell.elementType == DUNGEON_ELEMENT_STAIRS ||
        frontCell.elementType == DUNGEON_ELEMENT_TELEPORTER) {
        snprintf(title, sizeof(title), "%s",
                 F0503_DUNGEON_GetElementName_Compat(frontCell.elementType));
        m11_format_square_summary(&frontCell, detail, sizeof(detail));
        m11_set_status(state, "INSPECT", "FRONT CELL READOUT");
        m11_set_inspect_readout(state, title, detail);
        return 1;
    }

    return 0;
}

static int m11_front_cell_mirror_ordinal(const M11_GameViewState* state) {
    M11_ViewportCell frontCell;
    DM1_V1_ChampionMirrorRenderReceiptPc34 receipt;

    if (!state || !state->active ||
        !m11_get_front_cell(state, &frontCell) || !frontCell.valid) {
        return -1;
    }
    if (m11_build_dm1_front_champion_portrait_receipt(&frontCell, &receipt) &&
        receipt.valid &&
        receipt.drawChampionPortrait &&
        receipt.renderIndex >= 0) {
        /* ReDMCSB DUNGEON.C F0172 lines 2573/2608-2612 publishes C127
         * portrait data only for the visible wall face, and DUNVIEW.C
         * 3913-3928 consumes G0289 as the C026 atlas render index.  Use the
         * same DM1-owned render receipt here as the HoC draw path; M11 must
         * not select mirrors from a loose cached ordinal. */
        return receipt.renderIndex;
    }
    return -1;
}

static int m11_front_mirror_hit_test(const M11_GameViewState* state,
                                     int viewportX,
                                     int viewportY,
                                     int* outMirrorOrdinal)
{
    M11_ViewportCell frontCell;
    DM1_V1_ChampionMirrorRenderReceiptPc34 receipt;

    if (outMirrorOrdinal) *outMirrorOrdinal = -1;
    if (!state || !outMirrorOrdinal || !m11_get_front_cell(state, &frontCell) ||
        !m11_build_dm1_front_champion_portrait_receipt(&frontCell, &receipt) ||
        !receipt.valid || !receipt.drawChampionPortrait ||
        !m11_front_mirror_host_material_ready(state) || receipt.width <= 0 ||
        receipt.height <= 0 || viewportX < receipt.dstX ||
        viewportX >= receipt.dstX + receipt.width || viewportY < receipt.dstY ||
        viewportY >= receipt.dstY + receipt.height) {
        return 0;
    }
    *outMirrorOrdinal = receipt.renderIndex;
    return 1;
}

static int m11_front_mirror_click_wall_cell(const M11_GameViewState* state,
                                            int mirrorOrdinal,
                                            int* outWallCell)
{
    M11_ViewportCell frontCell;

    if (outWallCell) *outWallCell = -1;
    if (!state || !outWallCell || mirrorOrdinal < 0 ||
        !m11_get_front_cell(state, &frontCell) ||
        frontCell.championPortraitOrdinal != mirrorOrdinal ||
        frontCell.championPortraitWallCell < 0 ||
        frontCell.championPortraitWallCell > 3) {
        return 0;
    }
    *outWallCell = frontCell.championPortraitWallCell;
    return 1;
}

static int m11_get_front_cell(const M11_GameViewState* state, M11_ViewportCell* outCell) {
    M11_ViewportCell frontCell;

    memset(&frontCell, 0, sizeof(frontCell));
    if (!state || !state->active || !m11_sample_viewport_cell(state, 1, 0, &frontCell) || !frontCell.valid) {
        if (outCell) {
            *outCell = frontCell;
        }
        return 0;
    }
    if (outCell) {
        *outCell = frontCell;
    }
    return 1;
}

static int m11_front_mirror_host_material_ready(const M11_GameViewState* state) {
    M11_ViewportCell frontCell;
    DM1_V1_ChampionMirrorRenderReceiptPc34 renderReceipt;
    DM1_V1_ChampionMirrorHostDrawReceiptPc34 hostDraw;
    const M11_AssetSlot* portraits;
    const M11_AssetSlot* backing;
    DM1_V1_ObjectIconSourceZonePc34 sourceZone;

    if (!state || !state->active ||
        !m11_get_front_cell(state, &frontCell) ||
        !m11_build_dm1_front_champion_portrait_receipt(&frontCell,
                                                       &renderReceipt) ||
        !renderReceipt.valid || !renderReceipt.drawChampionPortrait) {
        return 0;
    }

    /* ReDMCSB DUNVIEW.C:3913-3928 first draws C346, then copies the exact
     * C026 atlas cell selected by F0172's C127 sensor.  The host may only
     * turn that visible wall into REVIVE.C F0280 input when both original
     * materials are present.  This deliberately does not gate the public
     * M10-facing selection API used by save/runtime tests. */
    portraits = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader,
                                     (unsigned int)renderReceipt.graphicIndex);
    if (!portraits || !portraits->loaded || !portraits->pixels ||
        !dm1_v1_graphic_validate_champion_portrait_atlas_pc34(
            (int)portraits->width, (int)portraits->height) ||
        !dm1_v1_graphic_champion_portrait_source_zone_pc34(
            renderReceipt.renderIndex, &sourceZone) ||
        renderReceipt.graphicIndex != sourceZone.graphic_index ||
        renderReceipt.sourceX != sourceZone.x ||
        renderReceipt.sourceY != sourceZone.y ||
        renderReceipt.width != sourceZone.w ||
        renderReceipt.height != sourceZone.h ||
        renderReceipt.sourceX < 0 || renderReceipt.sourceY < 0 ||
        renderReceipt.width <= 0 || renderReceipt.height <= 0 ||
        portraits->width < renderReceipt.sourceX + renderReceipt.width ||
        portraits->height < renderReceipt.sourceY + renderReceipt.height) {
        return 0;
    }

    backing = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader,
                                   (unsigned int)renderReceipt.backingGraphicIndex);
    if (!backing || !backing->loaded || !backing->pixels ||
        renderReceipt.backingSourceX < 0 || renderReceipt.backingSourceY < 0 ||
        renderReceipt.backingSourceWidth <= 0 ||
        renderReceipt.backingSourceHeight <= 0 ||
        renderReceipt.backingWidth <= 0 || renderReceipt.backingHeight <= 0 ||
        renderReceipt.backingSourceX + renderReceipt.backingSourceWidth >
            (int)backing->width ||
        renderReceipt.backingSourceY + renderReceipt.backingSourceHeight >
            (int)backing->height ||
        !DM1_V1_ChampionMirror_BuildHostDrawReceiptPc34(
            &renderReceipt, 0, 1, &hostDraw) ||
        !hostDraw.valid || !hostDraw.drawChampionPortrait ||
        !hostDraw.drawMirrorBackingAsset ||
        !hostDraw.suppressHostFallbackVisuals) {
        return 0;
    }
    return 1;
}

static int m11_front_cell_has_live_f0115_floor_item_request(
    const M11_GameViewState* state)
{
    M11_ViewportCell frontCell;

    if (!m11_get_front_cell(state, &frontCell) || !frontCell.valid ||
        !frontCell.dm1MaterializationDecisionReady) {
        return 0;
    }
    /* ReDMCSB DUNVIEW.C F0115:4547-4581 dispatches items before the
     * separate projectile/explosion passes. The host receipt records only
     * the completed item blit, so a midair effect cannot satisfy this HoC
     * material observation. */
    return frontCell.floorItemCount > 0 &&
           frontCell.dm1MaterializationDecision.drawFloorItems &&
           frontCell.elementType != DUNGEON_ELEMENT_WALL;
}

static int m11_front_cell_has_attack_target(const M11_GameViewState* state) {
    M11_ViewportCell frontCell;

    if (!m11_get_front_cell(state, &frontCell)) {
        return 0;
    }
    return frontCell.summary.groups > 0;
}

static int m11_front_cell_is_door(const M11_GameViewState* state) {
    M11_ViewportCell frontCell;

    if (!m11_get_front_cell(state, &frontCell)) {
        return 0;
    }
    return frontCell.valid && frontCell.elementType == DUNGEON_ELEMENT_DOOR;
}

/*
 * Thin shim over F0715_DOOR_ResolveToggleAction_Compat +
 * F0713_DOOR_BuildAnimationEvent_Compat: compat decides whether to open
 * or close, the viewport schedules a TIMELINE_EVENT_DOOR_ANIMATE event
 * on the world timeline and then runs the tick orchestrator.  The
 * animating intermediate states (1..3) are owned by the compat layer
 * via F0712_DOOR_StepAnimation_Compat inside F0887 (Pass 38), not by
 * this M11 shim.
 */
static int m11_toggle_front_door(M11_GameViewState* state) {
    M11_ViewportCell frontCell;
    struct DoorToggleResult_Compat action;
    int doorEffect;
    int currentState = -1;
    int finalState;

    if (!state || !state->active || !m11_get_front_cell(state, &frontCell) ||
        !frontCell.valid || frontCell.elementType != DUNGEON_ELEMENT_DOOR) {
        return 0;
    }

    if (!F0715_DOOR_ResolveToggleAction_Compat(state->world.dungeon,
                                               state->world.party.mapIndex,
                                               frontCell.mapX,
                                               frontCell.mapY,
                                               &action)) {
        return 0;
    }

    if (action.kind == DOOR_ACTION_DESTROYED) {
        m11_set_status(state, "DOOR", "DOOR DESTROYED");
        m11_set_inspect_readout(state, "FRONT DOOR", "DESTROYED, NO LONGER BLOCKING THE PASSAGE");
        return 1;
    }

    if (action.kind != DOOR_ACTION_OPEN && action.kind != DOOR_ACTION_CLOSE) {
        return 0;
    }

    /*
     * Convert OPEN/CLOSE into a DOOR_EFFECT_SET/CLEAR and schedule an
     * animation event.  The action.newDoorState (0 or 4) carried over
     * from Pass 31 is still the final target; it is no longer applied
     * directly.
     */
    finalState = action.newDoorState;
    if (!F0714_DOOR_ResolveAnimationEffect_Compat(
            state->world.dungeon,
            state->world.party.mapIndex,
            frontCell.mapX,
            frontCell.mapY,
            DOOR_EFFECT_TOGGLE,
            &doorEffect,
            &currentState)) {
        /* Already at target (e.g. state==0 on OPEN / state==4 on CLOSE) —
         * nothing to animate; still surface the status line so the UI
         * reflects the user's intent. */
        if (finalState == 0) {
            m11_set_status(state, "DOOR", "DOOR OPENED");
            m11_set_inspect_readout(state, "FRONT DOOR", "OPEN, PASSAGE CLEAR, CLICK CENTER OR PRESS UP TO CROSS");
        } else {
            m11_set_status(state, "DOOR", "DOOR CLOSED");
            m11_set_inspect_readout(state, "FRONT DOOR", "SHUT, ENTER INSPECTS, SPACE TOGGLES AGAIN");
        }
        return 1;
    }

    {
        struct TimelineEvent_Compat animEvent;
        if (F0713_DOOR_BuildAnimationEvent_Compat(
                state->world.party.mapIndex,
                frontCell.mapX,
                frontCell.mapY,
                doorEffect,
                state->world.gameTick,
                &animEvent)) {
            /* fireAtTick = gameTick + 1 — dispatches on the tick below. */
            (void)F0721_TIMELINE_Schedule_Compat(&state->world.timeline, &animEvent);
        }
    }

    /*
     * Advance the world by one tick through the orchestrator so the
     * scheduled TIMELINE_EVENT_DOOR_ANIMATE fires.  On each such tick
     * F0887_ORCH_DispatchTimelineEvents_Compat calls the Pass-38 step
     * handler, which walks the door state by one (4 -> 3, 3 -> 2, …)
     * and reschedules the event for the next tick until the final
     * state is reached.
     */
    {
        struct TickInput_Compat input;
        memset(&input, 0, sizeof(input));
        input.tick    = state->world.gameTick;
        input.command = CMD_NONE;
        memset(&state->lastTickResult, 0, sizeof(state->lastTickResult));
        /* Door animation consumes a real game tick; GAMELOOP.C:122-127
         * still decrements G0310/G0311 on that tick before command polling.
         */
        DM1_V1_MovementPipeline_DecrementCooldownsPc34Compat(
            &state->dm1V1MovementPipeline);
        (void)F0884_ORCH_AdvanceOneTick_Compat(
            &state->world, &input, &state->lastTickResult);
    }
    state->lastWorldHash = state->lastTickResult.worldHashPost;
    M11_GameView_ProcessTickEmissions(state);
    m11_refresh_hash(state);
    state->lastTickResult.worldHashPost = state->lastWorldHash;

    /*
     * Status / inspect text reflects the player's *intent*, not the
     * current in-flight state; the actual pixel-level animation is
     * expressed by the EMIT_DOOR_STATE stream consumed by
     * M11_GameView_ProcessTickEmissions.  This matches the original:
     * TIMELINE.C does not emit text when it rattles a closing door.
     */
    if (finalState == 0) {
        m11_set_status(state, "DOOR", "DOOR OPENING");
        m11_set_inspect_readout(state, "FRONT DOOR", "OPENING, PASSAGE CLEARING, CLICK CENTER OR PRESS UP TO CROSS");
    } else {
        m11_set_status(state, "DOOR", "DOOR CLOSING");
        m11_set_inspect_readout(state, "FRONT DOOR", "CLOSING, WAIT FOR RATTLE, SPACE TOGGLES AGAIN");
    }
    return 1;
}

static M12_MenuInput m11_pointer_viewport_input(const M11_GameViewState* state,
                                                int x,
                                                int y) {
    M11_ViewportCell frontCell;
    int localX;
    int localY;

    if (!state || !state->active) {
        return M12_MENU_INPUT_NONE;
    }

    localX = x - M11_VIEWPORT_X;
    localY = y - M11_VIEWPORT_Y;

    if (localX < M11_VIEWPORT_W / 3) {
        if (localY >= (M11_VIEWPORT_H * 2) / 3) {
            return M12_MENU_INPUT_STRAFE_LEFT;
        }
        return M12_MENU_INPUT_LEFT;
    }
    if (localX >= (M11_VIEWPORT_W * 2) / 3) {
        if (localY >= (M11_VIEWPORT_H * 2) / 3) {
            return M12_MENU_INPUT_STRAFE_RIGHT;
        }
        return M12_MENU_INPUT_RIGHT;
    }
    if (!m11_get_front_cell(state, &frontCell)) {
        return M12_MENU_INPUT_ACCEPT;
    }
    if (localY >= (M11_VIEWPORT_H * 2) / 3) {
        if (frontCell.summary.groups > 0) {
            return M12_MENU_INPUT_ACTION;
        }
        if (m11_viewport_cell_is_open(&frontCell) &&
            frontCell.summary.items == 0 &&
            frontCell.summary.sensors == 0 &&
            frontCell.summary.textStrings == 0 &&
            frontCell.summary.projectiles == 0 &&
            frontCell.summary.explosions == 0 &&
            frontCell.elementType != DUNGEON_ELEMENT_PIT) {
            return M12_MENU_INPUT_UP;
        }
    }
    return M12_MENU_INPUT_ACCEPT;
}

static unsigned char m11_viewport_fill_color(const M11_ViewportCell* cell) {
    if (!cell || !cell->valid) {
        return M11_COLOR_DARK_GRAY;
    }
    switch (cell->elementType) {
        case DUNGEON_ELEMENT_WALL:
            return M11_COLOR_DARK_GRAY;
        case DUNGEON_ELEMENT_CORRIDOR:
            return M11_COLOR_BLACK;
        case DUNGEON_ELEMENT_PIT:
            return M11_COLOR_RED;
        case DUNGEON_ELEMENT_STAIRS:
            return M11_COLOR_GREEN;
        case DUNGEON_ELEMENT_DOOR:
            return M11_COLOR_BROWN;
        case DUNGEON_ELEMENT_TELEPORTER:
            return M11_COLOR_MAGENTA;
        case DUNGEON_ELEMENT_FAKEWALL:
            return M11_COLOR_LIGHT_GRAY;
        default:
            return M11_COLOR_BLACK;
    }
}

static unsigned char m11_feature_accent_color(const M11_ViewportCell* cell) {
    if (!cell || !cell->valid) {
        return M11_COLOR_DARK_GRAY;
    }
    switch (cell->elementType) {
        case DUNGEON_ELEMENT_DOOR: return M11_COLOR_LIGHT_RED;
        case DUNGEON_ELEMENT_STAIRS: return M11_COLOR_YELLOW;
        case DUNGEON_ELEMENT_PIT: return M11_COLOR_BROWN;
        case DUNGEON_ELEMENT_TELEPORTER: return M11_COLOR_LIGHT_CYAN;
        case DUNGEON_ELEMENT_FAKEWALL: return M11_COLOR_MAGENTA;
        case DUNGEON_ELEMENT_CORRIDOR: return M11_COLOR_LIGHT_GRAY;
        default: return M11_COLOR_WHITE;
    }
}

static void m11_draw_wall_contents(unsigned char* framebuffer,
                                   int framebufferWidth,
                                   int framebufferHeight,
                                   const M11_ViewRect* rect,
                                   const M11_ViewportCell* cell,
                                   int depthIndex);

/* NOTE: g_drawState forward-declared near file top. */

static int m11_dm1_authenticated_viewport_source_active(void)
{
    const M11_GameViewState* state = g_drawState;

    if (!state || !m11_is_dm1_source_kind(state->sourceKind) ||
        !state->assetsAvailable || !state->assetLoader.initialized ||
        !state->assetLoader.fileState || !state->assetLoader.runtimeState) {
        return 0;
    }
    /* Source ownership begins when the authenticated PC34 graphics loader is
     * live. Thing tables are a later F0115 input and must not decide whether
     * the legacy primitive wall/door/stairs renderer is allowed to run. */
    return 1;
}

