static void m11_draw_wall_face(unsigned char* framebuffer,
                               int framebufferWidth,
                               int framebufferHeight,
                               const M11_ViewRect* rect,
                               const M11_ViewportCell* cell,
                               int depthIndex) {
    int inset = 6 + depthIndex * 4;
    int faceX = rect->x + inset;
    int faceY = rect->y + inset / 2;
    int faceW = rect->w - inset * 2;
    int faceH = rect->h - inset;
    unsigned char accent = m11_feature_accent_color(cell);

    if (faceW < 8 || faceH < 8) {
        return;
    }

    m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                  faceX, faceY, faceW, faceH,
                  cell->elementType == DUNGEON_ELEMENT_WALL ? M11_COLOR_DARK_GRAY : m11_viewport_fill_color(cell));
    m11_draw_rect(framebuffer, framebufferWidth, framebufferHeight,
                  faceX, faceY, faceW, faceH, accent);

    switch (cell->elementType) {
        case DUNGEON_ELEMENT_DOOR:
            /* ReDMCSB F0111/F0128 owns every authenticated DM1 door
             * panel/frame pass, including depth, state and orientation.
             * The generic face pass must not scale a frame-strip over the
             * whole face before those source passes run; doing so produces
             * duplicate/misaligned doors and can hide the correct panel. */
            if (!m11_dm1_authenticated_viewport_source_active() &&
                g_drawState &&
                m11_draw_door_frame_asset(g_drawState, framebuffer,
                                          framebufferWidth, framebufferHeight,
                                          rect, depthIndex)) {
                break; /* Real asset drawn successfully */
            }
            /* A real PC34 session must not receive a synthetic door. */
            if (m11_dm1_authenticated_viewport_source_active()) {
                break;
            }
            /* Legacy/test fallback: primitive door frame + gate.
             * ReDMCSB: door frame always visible.  Gate height scales
             * with doorState: 0 = fully open, 4 = fully closed.
             * Frame persists at all states so the door never disappears. */
            m11_draw_vline(framebuffer, framebufferWidth, framebufferHeight,
                           faceX + 2, faceY + 2, faceY + faceH - 3, M11_COLOR_YELLOW);
            m11_draw_vline(framebuffer, framebufferWidth, framebufferHeight,
                           faceX + faceW - 3, faceY + 2, faceY + faceH - 3, M11_COLOR_YELLOW);
            m11_draw_hline(framebuffer, framebufferWidth, framebufferHeight,
                           faceX + 2, faceX + faceW - 3, faceY + 2, M11_COLOR_YELLOW);
            if (cell->doorState > 0 && cell->doorState <= 4) {
                /* Gate descends from top: 4 = full, 1 = quarter */
                int shutHeight = (faceH - 8) * cell->doorState / 4;
                int gateY = faceY + 3;
                int barSpacing = (faceW - 6) > 20 ? 4 : 3;
                int ix;
                for (ix = 0; ix < shutHeight; ix += barSpacing) {
                    m11_draw_hline(framebuffer, framebufferWidth, framebufferHeight,
                                   faceX + 3, faceX + faceW - 4,
                                   gateY + ix, M11_COLOR_BROWN);
                }
                for (ix = faceX + 5; ix < faceX + faceW - 4; ix += barSpacing) {
                    m11_draw_vline(framebuffer, framebufferWidth, framebufferHeight,
                                   ix, gateY, gateY + shutHeight - 1, M11_COLOR_BROWN);
                }
            }
            break;
        case DUNGEON_ELEMENT_STAIRS:
            /* ReDMCSB F0104/F0128 owns the authenticated stairs material
             * pass.  Do not stretch a generic front bitmap here before the
             * source zone/orientation pass has selected the exact D/L/R
             * record. */
            if (!m11_dm1_authenticated_viewport_source_active() && g_drawState) {
                int stairUp = (cell->square & 0x04) ? 1 : 0; /* ReDMCSB DEFS.H MASK0x0004_STAIRS_UP */
                if (m11_draw_stairs_asset(g_drawState, framebuffer,
                                          framebufferWidth, framebufferHeight,
                                          rect, depthIndex, stairUp)) {
                    break;
                }
            }
            if (!m11_dm1_authenticated_viewport_source_active()) {
                /* Legacy/test fallback: primitive stair lines. */
                m11_draw_hline(framebuffer, framebufferWidth, framebufferHeight,
                               faceX + 4, faceX + faceW - 5, faceY + faceH - 5, M11_COLOR_YELLOW);
                m11_draw_hline(framebuffer, framebufferWidth, framebufferHeight,
                               faceX + 8, faceX + faceW - 9, faceY + faceH - 10, M11_COLOR_YELLOW);
                m11_draw_hline(framebuffer, framebufferWidth, framebufferHeight,
                               faceX + 12, faceX + faceW - 13, faceY + faceH - 15, M11_COLOR_YELLOW);
            }
            break;
        case DUNGEON_ELEMENT_PIT:
            /* ReDMCSB DUNGEON.C F0172: closed pit renders as corridor.
             * Only open pits (MASK0x0008_PIT_OPEN) show the hole. */
            if (cell->square & 0x08) { /* PIT_OPEN */
                m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                              faceX + 5, faceY + faceH / 2,
                              faceW - 10, faceH / 3, M11_COLOR_BLACK);
                m11_draw_rect(framebuffer, framebufferWidth, framebufferHeight,
                              faceX + 5, faceY + faceH / 2,
                              faceW - 10, faceH / 3, M11_COLOR_BROWN);
            }
            break;
        case DUNGEON_ELEMENT_TELEPORTER:
            m11_draw_rect(framebuffer, framebufferWidth, framebufferHeight,
                          faceX + 5, faceY + 4, faceW - 10, faceH - 8, M11_COLOR_LIGHT_CYAN);
            m11_draw_rect(framebuffer, framebufferWidth, framebufferHeight,
                          faceX + 10, faceY + 8, faceW - 20, faceH - 16, M11_COLOR_WHITE);
            break;
        case DUNGEON_ELEMENT_FAKEWALL:
            m11_draw_rect(framebuffer, framebufferWidth, framebufferHeight,
                          faceX + 5, faceY + 4, faceW - 10, faceH - 8, M11_COLOR_MAGENTA);
            break;
        case DUNGEON_ELEMENT_CORRIDOR:
        default:
            m11_draw_rect(framebuffer, framebufferWidth, framebufferHeight,
                          faceX + 4, faceY + 4, faceW - 8, faceH - 8, M11_COLOR_DARK_GRAY);
            break;
    }

    /* Draw wall ornament on wall-type cells (sensor-placed ornaments) */
    if (cell->elementType == DUNGEON_ELEMENT_WALL && cell->wallOrnamentOrdinal >= 0) {
        M11_ViewRect ornRect;
        ornRect.x = faceX;
        ornRect.y = faceY;
        /* Champion mirror portraits are not perspective-scaled wall-face
         * ornaments in DM1.  ReDMCSB DUNVIEW.C:3916 blits C026 only into
         * the fixed D1C portrait-on-wall box {96..127,35..63}; the normal
         * source wall-ornament pass handles that route.  Keep this debug
         * procedural wall-face path from drawing a second floating portrait. */
        ornRect.w = faceW;
        ornRect.h = faceH;
        if (g_drawState) {
            m11_draw_wall_ornament(g_drawState, framebuffer,
                                   framebufferWidth, framebufferHeight,
                                   &ornRect, cell->wallOrnamentOrdinal, depthIndex);
        }
    }

    /* Draw door ornament on door-type cells */
    if (cell->elementType == DUNGEON_ELEMENT_DOOR && cell->doorOrnamentOrdinal >= 0) {
        M11_ViewRect ornRect;
        ornRect.x = faceX;
        ornRect.y = faceY;
        ornRect.w = faceW;
        ornRect.h = faceH;
        if (g_drawState) {
            m11_draw_door_ornament(g_drawState, framebuffer,
                                   framebufferWidth, framebufferHeight,
                                   &ornRect, cell->doorOrnamentOrdinal, depthIndex);
        }
    }

    if (m11_viewport_cell_is_open(cell)) {
        m11_draw_wall_contents(framebuffer, framebufferWidth, framebufferHeight,
                               rect, cell, depthIndex);
    } else if (cell->thingCount > 0 &&
               g_drawState && g_drawState->showDebugHUD &&
               !m11_is_dm1_source_kind(g_drawState->sourceKind) &&
               !m11_source_is_csb(g_drawState)) {
        /* Diagnostic-only marker for synthetic probe worlds.  ReDMCSB never
         * paints a host marker on a closed wall because its thing chain is
         * consumed only by the source F0128/F0115 schedule. */
        m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                      faceX + faceW / 2 - 1, faceY + faceH / 2 - 1,
                      3, 3, M11_COLOR_WHITE);
    }
}

static void m11_draw_wall_contents(unsigned char* framebuffer,
                                   int framebufferWidth,
                                   int framebufferHeight,
                                   const M11_ViewRect* rect,
                                   const M11_ViewportCell* cell,
                                   int depthIndex) {
    int inset = 6 + depthIndex * 4;
    int faceX = rect->x + inset;
    int faceY = rect->y + inset / 2;
    int faceW = rect->w - inset * 2;
    int faceH = rect->h - inset;
    int sourceZoneRow;

    if (!cell || !m11_viewport_cell_is_open(cell) || faceW < 8 || faceH < 8) {
        return;
    }

    sourceZoneRow = dm1_viewport_3d_f0115_c2500_c2900_row(cell->relForward,
                                                          cell->relSide);

    /* ── DM1-faithful Z-order: floor ornaments → floor items → creatures → projectiles ──
     * ReDMCSB DUNVIEW.C F0115_DUNGEONVIEW_DrawObjectsCreaturesProjectilesExplosions_CPSEF
     * documents the original per-cell pass as: scan square things while
     * deferring group/projectile/explosion draw, draw objects, then draw one
     * creature for the processed cell, then restart the thing list to draw
     * projectiles, followed later by explosions (DUNVIEW.C:4567-4582).
     * The concrete code sections are marked Draw objects at DUNVIEW.C:4820,
     * Draw creatures at DUNVIEW.C:5201, and Draw projectiles at
     * DUNVIEW.C:5645. DUNVIEW.C:5244-5247 also says a single centered
     * creature waits for the full object-cell pass so it appears over
     * all floor objects. Keep this local V1 stack in that order. */

    /* Layer 0: Floor ornaments (painted on the floor, below everything) */
    if (cell->floorOrnamentOrdinal > 0 && g_drawState) {
        M11_ViewRect floorRect;
        floorRect.x = faceX;
        floorRect.y = faceY;
        floorRect.w = faceW;
        floorRect.h = faceH;
        m11_draw_floor_ornament(g_drawState, framebuffer,
                                framebufferWidth, framebufferHeight,
                                &floorRect, cell->floorOrnamentOrdinal,
                                depthIndex, 0 /* center cell */);
    }

    /* Layer 1: Floor items (lowest physical objects — on the ground).
     * Skip wall squares — items on walls are in alcoves, rendered
     * separately by m11_draw_dm1_alcove_wall_items. */
    if (cell->floorItemCount > 0 &&
        m11_dm1_floor_item_material_allowed(cell, 0) &&
        cell->elementType != DUNGEON_ELEMENT_WALL) {
        int ii;
        int itemsToShow = cell->floorItemCount;
        for (ii = 0; ii < itemsToShow; ++ii) {
            if (cell->floorItemTypes[ii] < 0) continue;
            if (g_drawState) {
                /* ReDMCSB DUNVIEW.C F0115 has no synthetic object route:
                 * missing PC34 aspect/material deliberately draws nothing. */
                (void)m11_draw_dm1_f0115_floor_item_sprite(
                    g_drawState, framebuffer, framebufferWidth, framebufferHeight,
                    faceX + 2, faceY + 2, faceW - 4, faceH - 4,
                    cell->floorItemTypes[ii], cell->floorItemSubtypes[ii],
                    cell->floorItemCells[ii], ii, depthIndex, sourceZoneRow,
                    cell->floorItemThings[ii], cell->mapX, cell->mapY);
            }
        }
    }

    /* Layer 2: Creatures (standing on the floor, above items). ReDMCSB
     * DUNVIEW.C:5244-5247: single centered creature waits until all
     * object cells are drawn before rendering over the floor-object pass. */
    if (cell->creatureGroupCount > 0) {
        DM1_CreatureDrawPlan plan;
        int pi;
        dm1_creature_center_draw_plan(cell->creatureTypes,
                                      cell->creatureCountsPerGroup,
                                      cell->creatureDirections,
                                      cell->creatureGroupCount,
                                      depthIndex,
                                      faceX,
                                      faceY,
                                      faceW,
                                      faceH,
                                      &plan);
        for (pi = 0; pi < plan.count; ++pi) {
            const DM1_CreatureDrawPlanEntry *entry = &plan.entries[pi];
            const DM1_CreatureDrawPlacement *placement = &entry->placement;
            if (g_drawState && g_drawState->assetsAvailable) {
                (void)m11_draw_creature_sprite_source_anchored(
                    g_drawState, framebuffer, framebufferWidth,
                    framebufferHeight, placement, entry->creature_type,
                    entry->creature_direction);
            }
        }
    }

    /* Layer 3: Projectiles and explosions (in flight, topmost) */
    if (cell->dm1MaterializationDecisionReady &&
        cell->dm1MaterializationDecision.drawRuntimeProjectiles &&
        m11_viewport_cell_has_renderable_projectile(cell)) {
        m11_draw_effect_cue(framebuffer, framebufferWidth, framebufferHeight,
                            faceX + 3, faceY + 3, faceW - 6, faceH - 6, cell,
                            depthIndex, sourceZoneRow);
    }
}

