static int m11_dm1_visible_wall_inscription_presentation(
    const M11_GameViewState* state,
    const M11_ViewportCell* cell,
    DM1_V1_WallInscriptionPresentationReceiptPc34* outReceipt)
{
    if (!state || !cell || !state->world.things) {
        return 0;
    }
    return dm1_v1_wall_inscription_presentation_from_selected_wall_pc34(
        state->world.things, cell->inscriptionTextIndex, outReceipt);
}

static int m11_dm1_unreadable_inscription_box_height(int relForward,
                                                     int relSide,
                                                     int sideProjection,
                                                     int lineCount) {
    return DM1_V1_InscriptionUnreadableBoxHeightPc34(
        relForward, relSide, sideProjection, lineCount);
}

static const M11_AssetSlot* m11_dm1_inscription_font_slot_for_material(
    const M11_GameViewState* state,
    const DM1_V1_InscriptionHostMaterialReceiptPc34* material)
{
    const M11_AssetSlot* fontSlot;
    if (!state || !material || !material->valid ||
        material->glyphByteCount <= 0) {
        return NULL;
    }
    if (!M11_AssetLoader_IsReady(&state->assetLoader)) {
        return NULL;
    }
    fontSlot = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader,
                                    DM1_V1_INSCRIPTION_FONT_GRAPHIC_INDEX_PC34);
    if (!fontSlot || !fontSlot->loaded || !fontSlot->pixels ||
        fontSlot->width != DM1_V1_INSCRIPTION_FONT_WIDTH_PC34 ||
        fontSlot->height != DM1_V1_INSCRIPTION_FONT_HEIGHT_PC34) {
        return NULL;
    }
    return fontSlot;
}

static int m11_draw_dm1_inscription_glyph_line(
                                               const M11_AssetSlot* fontSlot,
                                               const DM1_V1_InscriptionHostMaterialReceiptPc34* material,
                                               int lineIndex,
                                               unsigned char* framebuffer,
                                               int fbW,
                                               int fbH,
                                               int x,
                                               int y) {
    const DM1_V1_InscriptionFrontWallLineDrawPlanPc34* line;
    int i;
    if (!framebuffer || !material || lineIndex < 0 ||
        lineIndex >= DM1_V1_INSCRIPTION_MAX_LINES) {
        return 0;
    }
    line = &material->lines[lineIndex];
    if (line->glyphCount <= 0) {
        return 0;
    }
    if (!fontSlot || !fontSlot->loaded || !fontSlot->pixels) {
        return 0;
    }
    /* ReDMCSB DUNVIEW.C F0107 lines ~3631/~3704 blit each decoded
     * inscription byte from M648 at source_x = byte << 3. */
    for (i = 0; i < line->glyphCount; ++i) {
        DM1_V1_InscriptionRasterCellBindingPc34 binding;
        if (!DM1_V1_InscriptionBuildRasterCellBindingPc34(
                material, lineIndex, i, &binding) ||
            binding.fontGraphicIndex != (int)fontSlot->graphicIndex ||
            binding.transparentColor != DM1_V1_INSCRIPTION_TRANSPARENT_COLOR ||
            binding.sourceWidth != DM1_V1_INSCRIPTION_GLYPH_WIDTH ||
            binding.sourceHeight != DM1_V1_INSCRIPTION_GLYPH_HEIGHT) {
            return 0;
        }
        M11_AssetLoader_BlitRegion(fontSlot,
                                   binding.sourceX, binding.sourceY,
                                   binding.sourceWidth, binding.sourceHeight,
                                   framebuffer,
                                   fbW,
                                   fbH,
                                   x + binding.destinationX,
                                   y + binding.destinationY,
                                   binding.transparentColor);
    }
    return 1;
}

static unsigned int m11_dm1_inscription_fnv1a_bytes(
    const unsigned char* bytes, int byteCount);

static int m11_dm1_inscription_material_raster_ready(
    const M11_GameViewState* state,
    const DM1_V1_InscriptionHostMaterialReceiptPc34* material,
    const M11_AssetSlot** outFontSlot,
    DM1_V1_InscriptionSourceRasterCapturePc34* outCapture)
{
    const M11_AssetSlot* fontSlot;
    DM1_V1_InscriptionSourceRasterCapturePc34 capture;
    int line;

    if (outFontSlot) {
        *outFontSlot = NULL;
    }
    if (outCapture) {
        memset(outCapture, 0, sizeof(*outCapture));
    }
    if (!state || !material || !material->valid) {
        return 0;
    }
    fontSlot = m11_dm1_inscription_font_slot_for_material(state, material);
    if (!fontSlot ||
        !DM1_V1_InscriptionHostMaterialRasterGatePc34(
            material, (int)fontSlot->width, (int)fontSlot->height) ||
        material->textDataWordOffset < 0 || material->textDataWordCount <= 0 ||
        material->textDataFNV1a == 0u || material->glyphBytesFNV1a == 0u ||
        material->glyphBytesFNV1a != m11_dm1_inscription_fnv1a_bytes(
            material->glyphBytes, material->glyphByteCount + 1) ||
        m11_dm1_inscription_fnv1a_bytes(
            fontSlot->pixels, (int)fontSlot->width * (int)fontSlot->height) == 0u) {
        return 0;
    }

    /* Validate every F0168 glyph binding before M648 writes its first byte.
     * This is a source transaction, not a best-effort text loop: a malformed
     * late line must leave the reconstructed wall untouched. */
    for (line = 0; line < DM1_V1_INSCRIPTION_MAX_LINES; ++line) {
        const DM1_V1_InscriptionFrontWallLineDrawPlanPc34* drawPlan =
            &material->lines[line];
        int glyph;
        if (drawPlan->glyphCount <= 0) {
            if (drawPlan->done) {
                break;
            }
            continue;
        }
        for (glyph = 0; glyph < drawPlan->glyphCount; ++glyph) {
            DM1_V1_InscriptionRasterCellBindingPc34 binding;
            if (!DM1_V1_InscriptionBuildRasterCellBindingPc34(
                    material, line, glyph, &binding) ||
                binding.fontGraphicIndex != (int)fontSlot->graphicIndex ||
                binding.transparentColor != DM1_V1_INSCRIPTION_TRANSPARENT_COLOR ||
                binding.sourceWidth != DM1_V1_INSCRIPTION_GLYPH_WIDTH ||
                binding.sourceHeight != DM1_V1_INSCRIPTION_GLYPH_HEIGHT ||
                binding.sourceX < 0 || binding.sourceY < 0 ||
                binding.sourceX + binding.sourceWidth > (int)fontSlot->width ||
                binding.sourceY + binding.sourceHeight > (int)fontSlot->height ||
                binding.destinationX < 0 || binding.destinationY < 0 ||
                binding.destinationX + binding.sourceWidth > M11_VIEWPORT_W ||
                binding.destinationY + binding.sourceHeight > M11_VIEWPORT_H) {
                return 0;
            }
        }
        if (drawPlan->done) {
            break;
        }
    }
    if (!DM1_V1_InscriptionCaptureSourceRasterPc34(
            material, fontSlot->pixels, (int)fontSlot->width,
            (int)fontSlot->height, &capture)) {
        return 0;
    }
    if (outFontSlot) {
        *outFontSlot = fontSlot;
    }
    if (outCapture) {
        *outCapture = capture;
    }
    return 1;
}

static unsigned int m11_dm1_inscription_fnv1a_bytes(const unsigned char* bytes,
                                                     int byteCount)
{
    unsigned int hash = 2166136261u;
    int i;

    if (!bytes || byteCount <= 0) {
        return 0u;
    }
    for (i = 0; i < byteCount; ++i) {
        hash ^= bytes[i];
        hash *= 16777619u;
    }
    return hash;
}

static int m11_restore_dm1_f0107_inscription_wall_patch(
    const M11_GameViewState* state,
    unsigned char* framebuffer,
    int fbW,
    int fbH)
{
    const M11_AssetSlot* wall;
    const int dstX = dm1_v1_g0202_get_pc34(0);
    const int dstRight = dm1_v1_g0202_get_pc34(1);
    const int dstY = dm1_v1_g0202_get_pc34(2);
    const int dstBottom = dm1_v1_g0202_get_pc34(3);
    const int width = dstRight - dstX + 1;
    const int height = dstBottom - dstY + 1;
    const int sourceX = 94;
    const int sourceY = 28;
    const int flipped = m11_dm1_use_flipped_walls(state);
    const unsigned int graphicIndex = m11_wallset_graphic_index_for_state(
        state, M11_GFX_WALLSET0_D1C);
    int y;

    /* ReDMCSB DUNVIEW.C F0107:778 restores G202 from the current C10 D1C
     * wall bitmap before M648 overlays its C10-transparent cells.  This is
     * not a generic text backdrop: it is a 4x26 source crop whose position
     * and pixels are part of the original wall composition. */
    if (!state || !framebuffer || graphicIndex == M11_GFX_UNAVAILABLE ||
        width != 4 || height != 26 || sourceX + width > 160 ||
        sourceY + height > 111 || dstX < 0 || dstY < 0 ||
        M11_VIEWPORT_X + dstX + width > fbW ||
        M11_VIEWPORT_Y + dstY + height > fbH) {
        return 0;
    }
    wall = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader,
                                graphicIndex);
    if (!wall || !wall->loaded || !wall->pixels ||
        wall->width != 160 || wall->height != 111) {
        return 0;
    }
    for (y = 0; y < height; ++y) {
        int x;
        for (x = 0; x < width; ++x) {
            const int sx = flipped ? 159 - (sourceX + x) : sourceX + x;
            framebuffer[(M11_VIEWPORT_Y + dstY + y) * fbW +
                        M11_VIEWPORT_X + dstX + x] =
                wall->pixels[(sourceY + y) * (int)wall->width + sx];
        }
    }
    return 1;
}

static void m11_draw_dm1_front_wall_inscription_material(
    const M11_GameViewState* state,
    const DM1_V1_InscriptionHostMaterialReceiptPc34* inputMaterial,
    unsigned char* framebuffer,
    int fbW,
    int fbH) {
    DM1_V1_InscriptionHostMaterialReceiptPc34 material;
    const M11_AssetSlot* fontSlot;
    DM1_V1_InscriptionSourceRasterCapturePc34 sourceCapture;
    int line = 0;
    if (!state || !inputMaterial || !inputMaterial->valid) {
        return;
    }
    material = *inputMaterial;
    if (!m11_dm1_inscription_material_raster_ready(state, &material,
                                                    &fontSlot,
                                                    &sourceCapture)) {
        return;
    }
    if (!m11_restore_dm1_f0107_inscription_wall_patch(state, framebuffer,
                                                       fbW, fbH)) {
        return;
    }
    for (line = 0; line < DM1_V1_INSCRIPTION_MAX_LINES; ++line) {
        const DM1_V1_InscriptionFrontWallLineDrawPlanPc34* drawPlan =
            &material.lines[line];
        if (drawPlan->glyphCount > 0) {
            if (!m11_draw_dm1_inscription_glyph_line(
                    fontSlot, &material, line, framebuffer, fbW, fbH,
                    M11_VIEWPORT_X, M11_VIEWPORT_Y)) {
                return;
            }
        }
        if (drawPlan->done) {
            break;
        }
    }
    /* Publish only after the real M648 source slots were accepted and the
     * completed M10 receipt was consumed. No host text/font fallback exists. */
    m11_dm1_invalidate_wall_inscription_material();
    s_m11_dm1_inscription_host_presentation_receipt.valid = 1;
    s_m11_dm1_inscription_host_presentation_receipt.textStringIndex =
        material.textStringIndex;
    s_m11_dm1_inscription_host_presentation_receipt.fontGraphicIndex =
        material.fontGraphicIndex;
    s_m11_dm1_inscription_host_presentation_receipt.transparentColor =
        material.transparentColor;
    s_m11_dm1_inscription_host_presentation_receipt.glyphByteCount =
        material.glyphByteCount;
    s_m11_dm1_inscription_host_presentation_receipt.lineCount =
        material.lineCount;
    s_m11_dm1_inscription_host_presentation_receipt.textDataWordOffset =
        material.textDataWordOffset;
    s_m11_dm1_inscription_host_presentation_receipt.textDataWordCount =
        material.textDataWordCount;
    s_m11_dm1_inscription_host_presentation_receipt.textDataFNV1a =
        material.textDataFNV1a;
    s_m11_dm1_inscription_host_presentation_receipt.glyphBytesFNV1a =
        material.glyphBytesFNV1a;
    s_m11_dm1_inscription_host_presentation_receipt.fontPixelsFNV1a =
        m11_dm1_inscription_fnv1a_bytes(
            fontSlot->pixels, (int)fontSlot->width * (int)fontSlot->height);
    s_m11_dm1_inscription_host_presentation_receipt.sourceCellsFNV1a =
        sourceCapture.sourceCellsFNV1a;
    s_m11_dm1_inscription_host_presentation_receipt.glyphSourceWidth =
        DM1_V1_INSCRIPTION_GLYPH_WIDTH;
    s_m11_dm1_inscription_host_presentation_receipt.glyphSourceHeight =
        DM1_V1_INSCRIPTION_GLYPH_HEIGHT;
    s_m11_dm1_inscription_host_presentation_receipt.glyphCellCount =
        sourceCapture.glyphCellCount;
    s_m11_dm1_inscription_host_presentation_receipt.opaqueGlyphPixelCount =
        sourceCapture.opaquePixelCount;
    s_m11_dm1_inscription_host_presentation_receipt.transparentGlyphPixelCount =
        sourceCapture.transparentPixelCount;
    s_m11_dm1_inscription_host_presentation_receipt.glyphScaleNumerator = 1;
    s_m11_dm1_inscription_host_presentation_receipt.glyphScaleDenominator = 1;
    s_m11_dm1_inscription_host_presentation_receipt.paletteMapValid = 0;
    memcpy(s_m11_dm1_inscription_host_presentation_receipt.glyphBytes,
           material.glyphBytes, sizeof(material.glyphBytes));
    for (line = 0; line < DM1_V1_INSCRIPTION_MAX_LINES; ++line) {
        const DM1_V1_InscriptionFrontWallLineDrawPlanPc34* drawPlan =
            &material.lines[line];
        if (drawPlan->glyphCount <= 0) {
            continue;
        }
        s_m11_dm1_inscription_host_presentation_receipt.lineDestinationX[line] =
            M11_VIEWPORT_X + drawPlan->textX;
        s_m11_dm1_inscription_host_presentation_receipt.lineDestinationY[line] =
            M11_VIEWPORT_Y + drawPlan->textY;
        s_m11_dm1_inscription_host_presentation_receipt.lineGlyphCount[line] =
            drawPlan->glyphCount;
    }
}

static int m11_build_dm1_front_champion_portrait_receipt(
    const M11_ViewportCell* cell,
    DM1_V1_ChampionMirrorRenderReceiptPc34* outReceipt) {
    DM1_V1_ChampionMirrorFrontWallReceiptPc34 frontReceipt;
    int portraitIdx;
    if (!cell || !outReceipt) {
        return 0;
    }
    portraitIdx = cell->championPortraitOrdinal;
    if (portraitIdx < 0) {
        return 0;
    }
    if (cell->championPortraitWallCell < 0 ||
        !DM1_V1_ChampionMirror_F0172FrontWallSensorReceiptPc34(
            127, portraitIdx, cell->wallOrnamentOrdinal,
            cell->championPortraitWallCell, cell->championPortraitWallCell,
            &frontReceipt)) {
        return 0;
    }
    return DM1_V1_ChampionMirror_BuildViewportRenderReceiptPc34(
        1, &frontReceipt, outReceipt);
}

static int m11_build_dm1_hoc_front_mirror_runtime_decision(
    const M11_GameViewState* state,
    const M11_ViewportCell* frontCell,
    DM1_V1_ChampionMirrorRuntimeRenderDecisionPc34* outDecision) {
    DM1_V1_ChampionMirrorRenderReceiptPc34 renderReceipt;
    DM1V1D1LD1RF0115RuntimeThingReceiptPc34 floorThing;
    DM1_V1_ChampionMirrorRuntimeRenderInputPc34 runtimeInput;
    const DM1V1D1LD1RF0115LanePc34Data* lane;
    const M11_AssetSlot* backing;
    int thingType;
    int squareHasProjectile;
    if (!state || !frontCell || !outDecision) {
        return 0;
    }
    memset(outDecision, 0, sizeof(*outDecision));
    if (!m11_build_dm1_front_champion_portrait_receipt(frontCell,
                                                       &renderReceipt) ||
        !renderReceipt.valid || !renderReceipt.drawChampionPortrait) {
        return 1;
    }
    lane = dm1_v1_viewport_d1l_d1r_f0115_thing_pass_lane_at_pc34(0);
    thingType = frontCell->floorItemCount > 0 ?
        frontCell->firstItemThingType : THING_TYPE_PROJECTILE;
    squareHasProjectile = frontCell->summary.projectiles > 0;
    if (!lane || !dm1_v1_viewport_d1l_d1r_f0115_runtime_thing_receipt_pc34(
                     lane, thingType, 1, 1, squareHasProjectile, &floorThing)) {
        return 0;
    }
    backing = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader,
                                   (unsigned int)renderReceipt.backingGraphicIndex);
    memset(&runtimeInput, 0, sizeof(runtimeInput));
    runtimeInput.wallSquareVisible = 1;
    runtimeInput.sensorType = 127;
    runtimeInput.sensorData = renderReceipt.renderIndex;
    /* ReDMCSB DUNGEON.C:2608-2612 keeps the C127 sensor's wall-ornament
     * ordinal beside its portrait data.  C346 is selected later by the
     * source-owned render receipt; feeding its GRAPHICS.DAT id back into
     * F0172 loses the original sensor fact and lets a host route drift. */
    runtimeInput.ornamentOrdinal = frontCell->wallOrnamentOrdinal;
    runtimeInput.thingCell = frontCell->championPortraitWallCell;
    runtimeInput.visibleWallCell = frontCell->championPortraitWallCell;
    runtimeInput.candidatePanelActive = state->candidateMirrorPanelActive;
    runtimeInput.backingAssetAvailable =
        backing && backing->loaded && backing->pixels && backing->width > 0 &&
        backing->height > 0;
    runtimeInput.runtimeThingReceipt = &floorThing;
    return DM1_V1_ChampionMirror_BuildRuntimeRenderDecisionPc34(
        &runtimeInput, outDecision);
}

static int m11_build_dm1_hoc_current_front_mirror_runtime_decision(
    const M11_GameViewState* state,
    DM1_V1_ChampionMirrorRuntimeRenderDecisionPc34* outDecision) {
    M11_ViewportCell frontCell;

    if (!state || !outDecision || !m11_get_front_cell(state, &frontCell)) {
        return 0;
    }
    return m11_build_dm1_hoc_front_mirror_runtime_decision(
        state, &frontCell, outDecision);
}

