static int m11_spawn_f0190_death_smoke(
    M11_GameViewState* state,
    int creatureType,
    int killedCell,
    int mapIndex,
    int mapX,
    int mapY) {
    const struct CreatureBehaviorProfile_Compat* profile;
    DM1_MeleeF0190DeathSmokeInputPc34 smokeIn;
    DM1_MeleeF0190DeathSmokePlanPc34 smokePlan;
    struct TimelineEvent_Compat eFirst;
    int slot = -1;
    if (!state) return 0;
    profile = CREATURE_GetProfile_Compat(creatureType);
    memset(&smokeIn, 0, sizeof(smokeIn));
    memset(&smokePlan, 0, sizeof(smokePlan));
    smokeIn.shouldCreate = 1;
    smokeIn.smokeAttack = dm1_v1_melee_death_smoke_attack_f0190_pc34(
        profile ? profile->attributes : 0);
    smokeIn.smokeCell = killedCell;
    smokeIn.mapIndex = mapIndex;
    smokeIn.mapX = mapX;
    smokeIn.mapY = mapY;
    smokeIn.currentTick = (int)state->world.gameTick;
    if (!dm1_v1_melee_death_smoke_plan_f0190_pc34(
            &smokeIn, &smokePlan) ||
        !smokePlan.valid || !smokePlan.shouldCreate) {
        return 0;
    }
    /* M10 and M11 must publish the same original owner chain.  In a loaded
     * PC34 world this reserves C15, publishes C25, and only then exposes the
     * decoded runtime C040.  The helper retains its bounded ownerless route
     * solely for legacy/probe worlds without raw Thing data. */
    (void)slot;
    (void)eFirst;
    return F0887_ORCH_CreateSourceExplosion_Compat(
        &state->world,
        &smokePlan.createInput,
        smokePlan.createInput.centered ? 0 : smokePlan.createInput.cell);
}

static void m11_cleanup_f0190_creature_events(
    M11_GameViewState* state,
    int mapIndex,
    int mapX,
    int mapY,
    int killedCreatureIndex) {
    int readIndex;
    int writeIndex = 0;
    int oldCount;
    if (!state || killedCreatureIndex < 0 || killedCreatureIndex > 3) return;

    oldCount = state->world.timeline.count;
    for (readIndex = 0; readIndex < oldCount; ++readIndex) {
        struct TimelineEvent_Compat ev = state->world.timeline.events[readIndex];
        DM1_MeleeF0190TimelineCleanupInputPc34 cleanupIn;
        DM1_MeleeF0190TimelineCleanupPlanPc34 cleanupPlan;

        memset(&cleanupIn, 0, sizeof(cleanupIn));
        memset(&cleanupPlan, 0, sizeof(cleanupPlan));
        cleanupIn.eventKind = ev.kind;
        cleanupIn.eventMapIndex = ev.mapIndex;
        cleanupIn.eventMapX = ev.mapX;
        cleanupIn.eventMapY = ev.mapY;
        cleanupIn.eventType = ev.aux2;
        cleanupIn.targetMapIndex = mapIndex;
        cleanupIn.targetMapX = mapX;
        cleanupIn.targetMapY = mapY;
        cleanupIn.killedCreatureIndex = killedCreatureIndex;
        if (dm1_v1_melee_timeline_cleanup_plan_f0190_pc34(
                &cleanupIn, &cleanupPlan) &&
            cleanupPlan.valid) {
            if (!cleanupPlan.shouldKeepEvent) continue;
            ev.aux2 = cleanupPlan.newEventType;
        }
        state->world.timeline.events[writeIndex++] = ev;
    }
    while (writeIndex < oldCount) {
        memset(&state->world.timeline.events[writeIndex], 0,
               sizeof(state->world.timeline.events[writeIndex]));
        ++writeIndex;
    }
    state->world.timeline.count = writeIndex;
}

static int m11_apply_f0190_fear(
    M11_GameViewState* state,
    struct DungeonGroup_Compat* group,
    int creatureType,
    int groupIndex,
    int killedCreatureIndex,
    int originalGroupCount,
    int mapIndex,
    int mapX,
    int mapY) {
    const struct CreatureBehaviorProfile_Compat* profile;
    DM1_MeleeF0190KilledSomeStateInputPc34 stateIn;
    DM1_MeleeF0190KilledSomeStatePlanPc34 statePlan;
    DM1_MeleeF0190KilledSomeStatePlanPc34 applyPlan;
    int shouldFlee = 0;
    int fleeDelay = 0;
    int activeIndex;

    if (!state || !group) return 0;
    if (group->behavior != DM1_BEHAVIOR_ATTACK) return 0;
    if (mapIndex != state->world.partyMapIndex) return 0;

    profile = CREATURE_GetProfile_Compat(creatureType);
    if (!profile) return 0;

    memset(&stateIn, 0, sizeof(stateIn));
    memset(&statePlan, 0, sizeof(statePlan));
    memset(&applyPlan, 0, sizeof(applyPlan));
    stateIn.outcome = COMBAT_OUTCOME_KILLED_SOME_CREATURES;
    stateIn.groupBehavior = group->behavior;
    stateIn.groupIndex = groupIndex;
    stateIn.killedCreatureIndex = killedCreatureIndex;
    stateIn.originalGroupCount = originalGroupCount;
    stateIn.mapIndex = mapIndex;
    stateIn.mapX = mapX;
    stateIn.mapY = mapY;
    stateIn.partyMapIndex = state->world.party.mapIndex;
    stateIn.partyMapX = state->world.party.mapX;
    stateIn.partyMapY = state->world.party.mapY;
    stateIn.creatureType = creatureType;
    stateIn.creatureProperties = profile->properties;

    if (!dm1_v1_melee_killed_some_state_plan_f0190_pc34(
            &stateIn, &statePlan) ||
        !statePlan.valid || !statePlan.shouldEvaluateFear) {
        return 0;
    }

    if (!F0821_DM1_GROUP_ShouldFrighten_Compat(
            &statePlan.fearContext, originalGroupCount, &state->world.masterRng,
            &shouldFlee, &fleeDelay)) {
        return 0;
    }
    if (!dm1_v1_melee_killed_some_fear_apply_from_state_plan_f0190_pc34(
            &statePlan, shouldFlee, fleeDelay, &applyPlan) ||
        !applyPlan.valid || !applyPlan.shouldApplyFear) {
        return 0;
    }

    group->behavior = (unsigned char)applyPlan.newGroupBehavior;
    activeIndex = m11_find_creature_ai_on_square(
        state, applyPlan.mapIndex, applyPlan.mapX, applyPlan.mapY);
    if (activeIndex >= 0) {
        state->world.creatureAI[activeIndex].stateKind =
            applyPlan.newAiStateKind;
        state->world.creatureAI[activeIndex].fearCounter =
            applyPlan.fearCounter;
        state->world.creatureAI[activeIndex].reserved0 =
            applyPlan.groupIndex;
    }
    return 1;
}

static int m11_apply_f0190_projectile_possession_drops(
    M11_GameViewState* state,
    int creatureType,
    int creatureAttributes,
    int killedCell,
    int mapIndex,
    int mapX,
    int mapY,
    int outcome)
{
    DM1_MeleeF0190PossessionDropInputPc34 dropIn;
    DM1_MeleeF0190PossessionDropPlanPc34 dropPlan;

    if (!state) return 0;
    memset(&dropIn, 0, sizeof(dropIn));
    memset(&dropPlan, 0, sizeof(dropPlan));
    dropIn.outcome = outcome;
    dropIn.creatureType = creatureType;
    dropIn.creatureAttributes = creatureAttributes;
    dropIn.killedCell = killedCell;
    dropIn.mapIndex = mapIndex;
    dropIn.mapX = mapX;
    dropIn.mapY = mapY;
    if (!dm1_v1_melee_possession_drop_plan_f0190_pc34(
            &dropIn, &dropPlan) ||
        !dropPlan.valid || !dropPlan.shouldDropCreatureFixedPossessions) {
        return 0;
    }
    return m11_materialize_creature_fixed_possession_drops(
        state, dropPlan.creatureType, dropPlan.creatureCell,
        dropPlan.mapIndex, dropPlan.mapX, dropPlan.mapY);
}

static void m11_schedule_creature_reaction_f0209(
    M11_GameViewState* state,
    int groupIndex,
    const struct DungeonGroup_Compat* group,
    int mapIndex,
    int mapX,
    int mapY,
    int reactionType);

static int m11_fluxcage_present_on_square_f0224(M11_GameViewState* state,
                                                int mapIndex,
                                                int mapX,
                                                int mapY) {
    int isFluxcage = 0;
    if (!state || !state->world.dungeon || !state->world.things) return 0;
    if (!dm1_v1_f0221_fluxcage_on_square_pc34(
            state->world.dungeon, state->world.things, mapIndex, mapX, mapY,
            &isFluxcage)) {
        return 0;
    }
    return isFluxcage;
}

static int m11_lord_chaos_group_on_square_f0224(
    M11_GameViewState* state,
    int mapIndex,
    int mapX,
    int mapY,
    int* outGroupIndex,
    const struct DungeonGroup_Compat** outGroup) {
    unsigned short groupThing;
    int groupIndex;
    if (!state || !state->world.things || !outGroupIndex || !outGroup) return 0;
    groupThing = m11_find_group_on_square(&state->world, mapIndex, mapX, mapY);
    if (groupThing == THING_NONE || groupThing == THING_ENDOFLIST ||
        THING_GET_TYPE(groupThing) != THING_TYPE_GROUP) {
        return 0;
    }
    groupIndex = (int)THING_GET_INDEX(groupThing);
    if (groupIndex < 0 || groupIndex >= state->world.things->groupCount) {
        return 0;
    }
    if (state->world.things->groups[groupIndex].creatureType !=
        DM1_CREATURE_LORD_CHAOS_ID) {
        return 0;
    }
    *outGroupIndex = groupIndex;
    *outGroup = &state->world.things->groups[groupIndex];
    return 1;
}

static void m11_schedule_fluxcage_danger_reaction_f0224(
    M11_GameViewState* state,
    int mapIndex,
    int cageX,
    int cageY) {
    static const int chaosDx[4] = {0, -1, +1, 0};
    static const int chaosDy[4] = {-1, 0, 0, +1};
    static const int fluxDx[4] = {-1, +1, 0, 0};
    static const int fluxDy[4] = {0, 0, -1, +1};
    int i;
    if (!state) return;
    for (i = 0; i < 4; ++i) {
        int chaosX = cageX + chaosDx[i];
        int chaosY = cageY + chaosDy[i];
        int groupIndex = -1;
        const struct DungeonGroup_Compat* group = NULL;
        int otherFluxcages = 0;
        int j;
        if (!m11_lord_chaos_group_on_square_f0224(state, mapIndex,
                                                  chaosX, chaosY,
                                                  &groupIndex, &group)) {
            continue;
        }
        /* ReDMCSB PROJEXPL.C F0224 lines 995-1033 checks the first
         * adjacent Lord Chaos in north/west/east/south order.  It counts
         * the three other cardinal fluxcage squares around Lord Chaos; the
         * just-created cage is implicit.  Count 2 creates C29 danger. */
        for (j = 0; j < 4; ++j) {
            int fx = chaosX + fluxDx[j];
            int fy = chaosY + fluxDy[j];
            if (fx == cageX && fy == cageY) continue;
            otherFluxcages +=
                m11_fluxcage_present_on_square_f0224(state, mapIndex, fx, fy);
        }
        if (otherFluxcages == 2) {
            m11_schedule_creature_reaction_f0209(
                state, groupIndex, group, mapIndex, chaosX, chaosY,
                DM1_CM3_REACTION_DANGER_ON_SQUARE);
        }
        return;
    }
}

static int m11_spawn_fluxcage_f0224(M11_GameViewState* state,
                                    int mapIndex,
                                    int mapX,
                                    int mapY) {
    struct ExplosionCreateInput_Compat eIn;
    struct TimelineEvent_Compat eFirst;
    struct TimelineEvent_Compat removeEvent;
    struct ExplosionList_Compat explosionsBefore;
    struct TimelineQueue_Compat timelineBefore;
    DM1_C15PoolReservationPc34 reservation;
    const unsigned char* rawC15;
    uint32_t c15Fingerprint;
    unsigned char square = 0;
    int sourceFluxcage = 0;
    int squareType;
    int slot = -1;
    if (!state || !state->world.dungeon || !state->world.things) return 0;
    if (m11_get_square_byte(&state->world, mapIndex, mapX, mapY, &square)) {
        squareType = (square & DUNGEON_SQUARE_MASK_TYPE) >> 5;
        if (squareType == DUNGEON_ELEMENT_WALL ||
            squareType == DUNGEON_ELEMENT_STAIRS) {
            /* ReDMCSB: PROJEXPL.C F0224 lines 961-977 returns before
             * allocating an explosion when the target square is wall/stairs. */
            return 0;
        }
    }
    memset(&eIn, 0, sizeof(eIn));
    eIn.explosionType = C050_EXPLOSION_FLUXCAGE;
    eIn.attack = 255;
    eIn.mapIndex = mapIndex;
    eIn.mapX = mapX;
    eIn.mapY = mapY;
    eIn.cell = EXPLOSION_CELL_CENTERED;
    eIn.centered = 1;
    eIn.currentTick = (int)state->world.gameTick;
    eIn.ownerKind = PROJECTILE_OWNER_CHAMPION;
    eIn.ownerIndex = state->world.party.activeChampionIndex;
    eIn.creatorProjectileSlot = -1;
    /* ReDMCSB PROJEXPL.C F0224 allocates C15 before publishing C24.  The
     * runtime explosion is only a decoded consumer of that raw owner. */
    if (!dm1_v1_c15_pool_reserve_pc34(state->world.things, &reservation) ||
        !dm1_v1_c15_pool_initialize_and_link_pc34(
            &reservation, state->world.dungeon, C050_EXPLOSION_FLUXCAGE,
            255, 1, 0, mapIndex, mapX, mapY)) {
        return 0;
    }
    if (!dm1_v1_f0221_fluxcage_on_square_pc34(
            state->world.dungeon, state->world.things, mapIndex, mapX, mapY,
            &sourceFluxcage) || !sourceFluxcage) {
        (void)dm1_v1_c15_pool_rollback_pc34(&reservation);
        return 0;
    }
    explosionsBefore = state->world.explosions;
    timelineBefore = state->world.timeline;
    if (!F0821_EXPLOSION_Create_Compat(&eIn, &state->world.explosions,
                                       &slot, &eFirst)) {
        (void)dm1_v1_c15_pool_rollback_pc34(&reservation);
        return 0;
    }

    /* C24 owns the exact C15 that F0514 just linked.  The live C50 entry is
     * only its decoded projection: keep the raw owner fingerprint that
     * F0828/F0829 later require before publishing the remove event. */
    rawC15 = dm1_v1_dungeon_get_thing_data_pc34(state->world.things,
                                                  reservation.thing);
    c15Fingerprint = dm1_v1_c15_layout_fingerprint_pc34(rawC15, 4u);
    if (!rawC15 || c15Fingerprint == 0u) {
        state->world.explosions = explosionsBefore;
        (void)dm1_v1_c15_pool_rollback_pc34(&reservation);
        return 0;
    }
    state->world.explosions.entries[slot].sourceC15Fingerprint =
        c15Fingerprint;
    state->world.explosions.entries[slot].sourceC25Priority = 0;

    memset(&removeEvent, 0, sizeof(removeEvent));
    removeEvent.kind = TIMELINE_EVENT_REMOVE_FLUXCAGE;
    /* ReDMCSB: PROJEXPL.C F0224 lines 987-994 schedules C24
     * EVENT_REMOVE_FLUXCAGE for GameTime + 100 with the explosion slot. */
    removeEvent.fireAtTick = state->world.gameTick + 100U;
    removeEvent.mapIndex = mapIndex;
    removeEvent.mapX = mapX;
    removeEvent.mapY = mapY;
    /* C24 stores the linked C15's Thing cell. A centered C15 uses cell C0;
     * EXPLOSION_CELL_CENTERED is the host-only presentation sentinel. */
    removeEvent.cell = 0;
    removeEvent.aux0 = slot;
    removeEvent.aux1 = C050_EXPLOSION_FLUXCAGE;
    removeEvent.aux2 = reservation.thing;
    removeEvent.aux3 = (int)c15Fingerprint;
    removeEvent.aux4 = 0;
    if (!F0721_TIMELINE_Schedule_Compat(&state->world.timeline, &removeEvent)) {
        state->world.explosions = explosionsBefore;
        state->world.timeline = timelineBefore;
        (void)dm1_v1_c15_pool_rollback_pc34(&reservation);
        return 0;
    }
    m11_schedule_fluxcage_danger_reaction_f0224(state, mapIndex, mapX, mapY);
    return 1;
}

static int m11_find_creature_ai_on_square(const M11_GameViewState* state,
                                          int mapIndex,
                                          int mapX,
                                          int mapY) {
    int i;
    if (!state) return -1;
    for (i = 0; i < state->world.creatureAICount &&
                i < GAMEWORLD_CREATURE_AI_CAPACITY; ++i) {
        const struct CreatureAIState_Compat* ai = &state->world.creatureAI[i];
        if (ai->groupMapIndex == mapIndex && ai->groupMapX == mapX &&
            ai->groupMapY == mapY) {
            return i;
        }
    }
    return -1;
}

static int m11_creature_type_on_square(const M11_GameViewState* state,
                                       int mapIndex,
                                       int mapX,
                                       int mapY) {
    unsigned short groupThing;
    int gIdx;
    if (!state || !state->world.things) return -1;
    groupThing = m11_find_group_on_square(&state->world, mapIndex, mapX, mapY);
    if (groupThing == THING_NONE || groupThing == THING_ENDOFLIST) return -1;
    gIdx = THING_GET_INDEX(groupThing);
    if (gIdx < 0 || gIdx >= state->world.things->groupCount) return -1;
    return (int)state->world.things->groups[gIdx].creatureType;
}

static void m11_set_group_type_on_square(M11_GameViewState* state,
                                         int mapIndex,
                                         int mapX,
                                         int mapY,
                                         int creatureType,
                                         int partyDirection) {
    unsigned short groupThing;
    int gIdx;
    int aiIdx;
    int groupDirection = (partyDirection + 2) & 3;
    if (!state || !state->world.things) return;
    groupThing = m11_find_group_on_square(&state->world, mapIndex, mapX, mapY);
    if (groupThing != THING_NONE && groupThing != THING_ENDOFLIST) {
        gIdx = THING_GET_INDEX(groupThing);
        if (gIdx >= 0 && gIdx < state->world.things->groupCount) {
            /* ReDMCSB: ENDGAME.C F0446 lines 829-831 turns Lord Chaos into
             * the Grey Lord, heals it to 10000, centers the single creature
             * with C0xFF, and faces it opposite the party direction. */
            state->world.things->groups[gIdx].creatureType = (unsigned char)creatureType;
            state->world.things->groups[gIdx].health[0] = 10000;
            state->world.things->groups[gIdx].cells = 0xFF;
            state->world.things->groups[gIdx].direction = (unsigned char)groupDirection;
        }
    }
    aiIdx = m11_find_creature_ai_on_square(state, mapIndex, mapX, mapY);
    if (aiIdx >= 0) {
        state->world.creatureAI[aiIdx].creatureType = creatureType;
        state->world.creatureAI[aiIdx].groupCells = 0xFF;
        state->world.creatureAI[aiIdx].groupDirection = groupDirection;
    }
}

static void m11_remove_creature_ai_for_group_f0446(M11_GameViewState* state,
                                                   int groupIndex) {
    int i;
    int writeIndex = 0;
    int oldCount;
    int retainedCount;
    if (!state || groupIndex < 0) return;
    oldCount = state->world.creatureAICount;
    for (i = 0; i < oldCount; ++i) {
        if (state->world.creatureAI[i].reserved0 == groupIndex) continue;
        if (writeIndex != i) {
            state->world.creatureAI[writeIndex] = state->world.creatureAI[i];
        }
        ++writeIndex;
    }
    retainedCount = writeIndex;
    while (writeIndex < oldCount) {
        memset(&state->world.creatureAI[writeIndex], 0,
               sizeof(state->world.creatureAI[writeIndex]));
        ++writeIndex;
    }
    state->world.creatureAICount = retainedCount;
}

static void m11_delete_other_groups_for_endgame_f0446(M11_GameViewState* state,
                                                      int mapIndex,
                                                      int greyLordX,
                                                      int greyLordY) {
    const struct DungeonMapDesc_Compat* map;
    int x;
    int y;
    if (!state || !state->world.dungeon || !state->world.things) return;
    if (mapIndex < 0 || mapIndex >= (int)state->world.dungeon->header.mapCount) return;
    map = &state->world.dungeon->maps[mapIndex];
    for (x = 0; x < (int)map->width; ++x) {
        for (y = 0; y < (int)map->height; ++y) {
            unsigned short groupThing;
            int groupIndex;
            if (x == greyLordX && y == greyLordY) continue;
            groupThing = m11_find_group_on_square(&state->world, mapIndex, x, y);
            if (groupThing == THING_NONE || groupThing == THING_ENDOFLIST ||
                THING_GET_TYPE(groupThing) != THING_TYPE_GROUP) {
                continue;
            }
            groupIndex = (int)THING_GET_INDEX(groupThing);
            if (m11_unlink_thing_from_square(&state->world, mapIndex, x, y,
                                             groupThing)) {
                /* ReDMCSB: ENDGAME.C F0446 lines 915-922 deletes every
                 * group except the Grey Lord square after setting
                 * G0077_B_DoNotDrawFluxcagesDuringEndgame. */
                m11_remove_creature_ai_for_group_f0446(state, groupIndex);
            }
        }
    }
}

static void m11_clear_message_log_for_source_message_area(M11_GameViewState* state) {
    if (!state) return;
    memset(&state->messageLog, 0, sizeof(state->messageLog));
}

static void m11_record_fuse_sequence_update_f0445(M11_GameViewState* state,
                                                  int replayType,
                                                  int attack,
                                                  int creatureType);

static int m11_print_endgame_text_messages_f0446(M11_GameViewState* state,
                                                 int mapIndex) {
    unsigned short textThings[64];
    unsigned short thing;
    int textThingCount = 0;
    int scanGuard = 0;
    int remaining;
    int printed = 0;
    char expected = 'A';
    if (!state || !state->world.things || !state->world.things->textStrings ||
        !state->world.things->textData ||
        state->world.things->textDataWordCount <= 0) {
        return 0;
    }

    /* ReDMCSB: ENDGAME.C F0446 lines 928-952 walks the current map's
     * square (0,0), keeps only TextString things, decodes each as a message
     * even when invisible, then prints them in A/B/... order by the first
     * decoded character while suppressing that ordering character. */
    thing = m11_get_first_square_thing(&state->world, mapIndex, 0, 0);
    while (thing != THING_NONE && thing != THING_ENDOFLIST && scanGuard++ < 1024) {
        if (THING_GET_TYPE(thing) == THING_TYPE_TEXTSTRING &&
            textThingCount < (int)(sizeof(textThings) / sizeof(textThings[0]))) {
            textThings[textThingCount++] = thing;
        }
        thing = m11_raw_next_thing(state->world.things, thing);
    }

    remaining = textThingCount;
    while (remaining-- > 0) {
        int i;
        for (i = 0; i < textThingCount; ++i) {
            char decoded[128];
            int textIndex = (int)THING_GET_INDEX(textThings[i]);
            int len = F0508_DUNGEON_DecodeTextStringThing_Compat(
                state->world.things, textIndex,
                DUNGEON_TEXT_TYPE_MESSAGE |
                    DUNGEON_TEXT_MASK_DECODE_EVEN_IF_INVISIBLE,
                decoded, (int)sizeof(decoded));
            if (len > 1 && decoded[1] == expected) {
                decoded[1] = '\n';
                m11_clear_message_log_for_source_message_area(state);
                M11_MessageLog_Push(&state->messageLog, &decoded[1],
                                    M11_COLOR_WHITE);
                /* ReDMCSB: ENDGAME.C F0446 lines 946-947 runs F0445 once
                 * after each printed message, then Delay(780). */
                m11_record_fuse_sequence_update_f0445(
                    state, M11_ENDGAME_F0445_EVENT_TEXT_MESSAGE, 0, 0);
                state->endgameTextMessageDelayTicks += 780;
                state->endgameFuseSequenceDelayTicks += 780;
                ++printed;
                ++expected;
                break;
            }
        }
    }
    return printed;
}

static int m11_count_fluxcages_around_square(M11_GameViewState* state,
                                             int mapIndex,
                                             int mapX,
                                             int mapY,
                                             int present[4]) {
    static const int dx[4] = {-1, +1, 0, 0};
    static const int dy[4] = {0, 0, -1, +1};
    int i, count = 0;
    if (!state || !present) return 0;
    for (i = 0; i < 4; ++i) {
        int c = 0;
        (void)F0871_RUNTIME_CountFluxcagesOnSquare_Compat(&state->world.explosions,
                                                          mapIndex,
                                                          mapX + dx[i],
                                                          mapY + dy[i],
                                                          &c);
        present[i] = (c > 0) ? 1 : 0;
        count += present[i];
    }
    return count;
}

static void m11_remove_fluxcages_on_square_f0446(M11_GameViewState* state,
                                                 int mapIndex,
                                                 int mapX,
                                                 int mapY) {
    int i;
    if (!state) return;
    /* ReDMCSB: ENDGAME.C F0446 lines 853-875 removes C050 Fluxcage
     * explosion things from both the party square and Lord Chaos square
     * before the fuse-sequence fireball burst is created. */
    for (i = 0; i < EXPLOSION_LIST_CAPACITY; ++i) {
        const struct ExplosionInstance_Compat* e =
            &state->world.explosions.entries[i];
        if (e->reserved0 == 0) continue;
        if (e->explosionType != C050_EXPLOSION_FLUXCAGE) continue;
        if (e->mapIndex != mapIndex || e->mapX != mapX || e->mapY != mapY) {
            continue;
        }
        (void)F0824_EXPLOSION_Despawn_Compat(&state->world.explosions, i);
    }
}

static void m11_record_fuse_sequence_update_f0445(M11_GameViewState* state,
                                                  int replayType,
                                                  int attack,
                                                  int creatureType) {
    if (!state) return;
    /* ReDMCSB: ENDGAME.C F0445 lines 742-759 processes timeline,
     * redraws the dungeon view, plays pending sound, then advances
     * G0313.  M11's F0446 path is non-blocking, so this records each
     * source-cadence presentation frame plus the mutation that should be
     * visible when idle replay redraws that frame. */
    state->endgameFuseSequenceTotalUpdateTicks += 1;
    state->endgameFuseSequenceFrameReplayTicks += 1;
    state->endgameFuseSequenceFrameReplayRemainingTicks += 1;
    if (state->endgameFuseSequenceReplayEventCount <
        M11_ENDGAME_F0445_REPLAY_CAPACITY) {
        int index = state->endgameFuseSequenceReplayEventCount++;
        state->endgameFuseSequenceReplayTypes[index] = replayType;
        state->endgameFuseSequenceReplayAttacks[index] = attack;
        state->endgameFuseSequenceReplayCreatureTypes[index] = creatureType;
    }
}

static void m11_apply_fuse_mutation_plan_f0446(
    M11_GameViewState* state,
    int mapIndex,
    int mapX,
    int mapY,
    const DM1EndgameFuseMutationPlan* plan) {
    int i;
    if (!state || !plan) return;
    /* DM1 supplies the ReDMCSB F0446 mutation and F0445 replay order. */
    for (i = 0; i < plan->stepCount; ++i) {
        const DM1EndgameFuseMutationStep* step = &plan->steps[i];
        if (step->spawnFireball) {
            (void)m11_spawn_centered_explosion(state, C000_EXPLOSION_FIREBALL,
                                               step->attackValue, mapIndex, mapX, mapY);
        }
        if (step->spawnHarmNonMaterial) {
            (void)m11_spawn_centered_explosion(state,
                                               C003_EXPLOSION_HARM_NON_MATERIAL,
                                               step->attackValue, mapIndex, mapX, mapY);
        }
        if (step->requestBuzz) {
            m11_audio_emit_source_sound(state, DM1_SND_BUZZ,
                                        M11_AUDIO_MARKER_CREATURE);
            state->endgameBuzzRequestCount += 1;
            if (step->replayType == DM1_ENDGAME_F0445_EVENT_CHAOS_ORDER_SWITCH) {
                state->endgameChaosOrderSwitchCount += 1;
            }
        }
        if (step->setCreatureType) {
            m11_set_group_type_on_square(state, mapIndex, mapX, mapY,
                                         step->creatureType,
                                         state->world.party.direction);
        }
        if (step->hideFluxcages) state->endgameDoNotDrawFluxcages = 1;
        if (step->deleteOtherGroups) {
            m11_delete_other_groups_for_endgame_f0446(state, mapIndex, mapX, mapY);
        }
        if (step->replayType == DM1_ENDGAME_F0445_EVENT_CHAOS_ORDER_SWITCH) {
            /* ReDMCSB F0446 increments the cycle-local update counter before
             * its matching F0445 call.  Keep that diagnostic counter distinct
             * from the DM1-owned replay cadence. */
            state->endgameFuseSequenceUpdateTicks += 1;
        }
        m11_record_fuse_sequence_update_f0445(state, (int)step->replayType,
                                               step->attackValue, step->creatureType);
    }
}

static int m11_find_lord_chaos_escape_square_f0225(
    M11_GameViewState* state,
    int mapIndex,
    int mapX,
    int mapY,
    const int present[4],
    int* outX,
    int* outY) {
    static const int dx[4] = {-1, +1, 0, 0};
    static const int dy[4] = {0, 0, -1, +1};
    int start;
    int step;

    if (!state || !present || !outX || !outY) return 0;
    /* ReDMCSB PROJEXPL.C F0225 lines 1087-1118 starts at
     * M004_RANDOM(4), then scans the four cardinal fluxcage slots with
     * M017_NEXT until it finds an unblocked, allowed square. */
    start = F0732_COMBAT_RngRandom_Compat(&state->world.masterRng, 4);
    for (step = 0; step < 4; ++step) {
        int slot = (start + step) & 3;
        int tx;
        int ty;
        if (present[slot]) continue;
        tx = mapX + dx[slot];
        ty = mapY + dy[slot];
        if (m11_square_walkable_for_creature(&state->world, mapIndex, tx, ty)) {
            *outX = tx;
            *outY = ty;
            return 1;
        }
    }
    return 0;
}

static void m11_update_group_ai_position(M11_GameViewState* state,
                                         int groupIndex,
                                         int mapIndex,
                                         int oldX,
                                         int oldY,
                                         int newX,
                                         int newY) {
    int i;
    if (!state) return;
    for (i = 0; i < state->world.creatureAICount; ++i) {
        struct CreatureAIState_Compat* ai = &state->world.creatureAI[i];
        if ((ai->reserved0 == groupIndex) ||
            (ai->groupMapIndex == mapIndex &&
             ai->groupMapX == oldX &&
             ai->groupMapY == oldY)) {
            ai->groupMapIndex = mapIndex;
            ai->groupMapX = newX;
            ai->groupMapY = newY;
            if (state->world.things && state->world.things->groups &&
                groupIndex >= 0 && groupIndex < state->world.things->groupCount) {
                ai->creatureType =
                    state->world.things->groups[groupIndex].creatureType;
            }
        }
    }
}

static int m11_move_group_thing_f0225(M11_GameViewState* state,
                                      int mapIndex,
                                      int oldX,
                                      int oldY,
                                      int newX,
                                      int newY,
                                      unsigned short groupThing) {
    int groupIndex;
    if (!state || !state->world.things ||
        groupThing == THING_NONE || groupThing == THING_ENDOFLIST ||
        THING_GET_TYPE(groupThing) != THING_TYPE_GROUP) {
        return 0;
    }
    groupIndex = (int)THING_GET_INDEX(groupThing);
    if (groupIndex < 0 || groupIndex >= state->world.things->groupCount) {
        return 0;
    }
    if (!m11_unlink_thing_from_square(&state->world, mapIndex, oldX, oldY,
                                      groupThing)) {
        return 0;
    }
    if (!m11_prepend_thing_to_square(&state->world, mapIndex, newX, newY,
                                     groupThing)) {
        (void)m11_prepend_thing_to_square(&state->world, mapIndex, oldX, oldY,
                                          groupThing);
        return 0;
    }
    m11_update_group_ai_position(state, groupIndex, mapIndex, oldX, oldY,
                                 newX, newY);
    return 1;
}

static int m11_perform_fluxcage_action(M11_GameViewState* state,
                                       const char* champName,
                                       int mapIndex,
                                       int mapX,
                                       int mapY) {
    if (!state) return 0;
    if (!m11_spawn_fluxcage_f0224(state, mapIndex, mapX, mapY)) {
        /* ReDMCSB: MENU.C F0407 lines 1488-1497 leaves
         * AL1245_B_ActionPerformed TRUE around the void F0224 call.
         * PROJEXPL.C F0224 can still return early for wall/stairs or no
         * explosion slot, so keep the common F0407 stamina/XP tail. */
        m11_log_event(state, M11_COLOR_LIGHT_RED,
                      "T%u: FLUXCAGE FIZZLES",
                      (unsigned int)state->world.gameTick);
        return 1;
    }
    m11_log_event(state, M11_COLOR_LIGHT_CYAN,
                  "T%u: %s CREATES A FLUXCAGE",
                  (unsigned int)state->world.gameTick, champName);
    return 1;
}

static void m11_mark_game_won_from_fuse_f0446(M11_GameViewState* state) {
    if (!state) return;

    /* ReDMCSB: PROJEXPL.C F0225 lines 1122-1123 calls
     * ENDGAME.C F0446, where lines 805 and 810 set
     * G0302_B_GameWon = C1_TRUE and MagicalLightAmount = 200. */
    state->world.gameWon = 1;
    if (!state->gameWon) {
        state->gameWon = 1;
        state->gameWonTick = state->world.gameTick;
    }
}

static void m11_apply_fuse_final_endgame_params_f0446(
    M11_GameViewState* state,
    const DM1EndgameFuseMutationPlan* plan) {
    if (!state || !plan) return;

    /* ReDMCSB: ENDGAME.C F0446 lines 924-960 plays C2_MUSIC_GAME_WON
     * on MEDIA503 builds, then after the victory text waits 600 ticks,
     * clears G0524_B_RestartGameAllowed, and calls
     * F0444_STARTEND_Endgame(C1_TRUE).  M11 records this final handoff
     * explicitly while the actual timed credits/palette sequence remains
     * in the presentation follow-up. */
    state->endgameFinalDelayTicks = plan->finalDelayTicks;
    state->endgameFuseSequenceDelayTicks += plan->finalDelayTicks;
    state->endgameFuseSequenceDelayRemainingTicks =
        state->endgameFuseSequenceDelayTicks;
    state->endgameFinalHandoffReady =
        (state->endgameFuseSequenceFrameReplayRemainingTicks <= 0 &&
         state->endgameFuseSequenceDelayRemainingTicks <= 0) ? 1 : 0;
    state->endgameRestartAllowed = plan->restartAllowedAfterWin;
    state->endgameCalledWithTrue = plan->endgameCalledWithTrue;
    if (plan->victoryMusicId >= 0) {
        (void)M11_Audio_RequestSourceMusicTrack(&state->audioState,
                                                plan->victoryMusicId);
    }
}

static int m11_perform_fuse_action_at(M11_GameViewState* state,
                                      const char* champName,
                                      int mapIndex,
                                      int mapX,
                                      int mapY) {
    const struct DungeonMapDesc_Compat* map;
    int flux[4] = {0, 0, 0, 0};
    int creatureType;
    int escapeAvailable;
    int escapeX = -1;
    int escapeY = -1;
    unsigned short chaosThing;
    DM1EndgameFuseActionResult result;
    DM1EndgameFuseMutationPlan mutationPlan;
    if (!state || !state->world.dungeon ||
        mapIndex < 0 || mapIndex >= (int)state->world.dungeon->header.mapCount) {
        return 0;
    }
    map = &state->world.dungeon->maps[mapIndex];
    if (mapX < 0 || mapX >= (int)map->width ||
        mapY < 0 || mapY >= (int)map->height) {
        /* ReDMCSB MENU.C F0407 lines 1499-1505 leaves the FUSE action
         * performed after calling F0225.  PC34 PROJEXPL.C F0225 lines
         * 1074-1077 guards the Harm Non Material explosion and Chaos handling
         * behind an in-bounds coordinate check, so a boundary-facing FUSE has
         * no F0225 side effect but still reaches the common F0407 tail. */
        m11_log_event(state, M11_COLOR_LIGHT_RED,
                      "T%u: %s FUSES BEYOND THE WALL",
                      (unsigned int)state->world.gameTick, champName);
        return 1;
    }
    (void)m11_spawn_centered_explosion(state, C003_EXPLOSION_HARM_NON_MATERIAL, 255,
                                       mapIndex, mapX, mapY);
    creatureType = m11_creature_type_on_square(state, mapIndex, mapX, mapY);
    (void)m11_count_fluxcages_around_square(state, mapIndex, mapX, mapY, flux);
    escapeAvailable = 0;
    if (creatureType == DM1_CREATURE_LORD_CHAOS_ID) {
        escapeAvailable = m11_find_lord_chaos_escape_square_f0225(
            state, mapIndex, mapX, mapY, flux, &escapeX, &escapeY);
    }
    memset(&result, 0, sizeof(result));
    DM1_Endgame_EvaluateFuseAction(mapX, mapY,
                                   (int32_t)map->width,
                                   (int32_t)map->height,
                                   creatureType, flux, escapeAvailable,
                                   &result);
    if (!result.lordChaosPresent) {
        /* ReDMCSB MENU.C F0407 lines 1499-1505 calls F0225 and leaves
         * AL1245_B_ActionPerformed TRUE.  PROJEXPL.C F0225 lines 1077-1083
         * has already created the Harm Non Material fuse explosion before it
         * discovers that Lord Chaos is absent, so the common F0407 tail still
         * runs and the action reports performed. */
        m11_log_event(state, M11_COLOR_LIGHT_RED,
                      "T%u: %s FUSES NOTHING",
                      (unsigned int)state->world.gameTick, champName);
        return 1;
    }
    if (result.lordChaosEscaped) {
        /* ReDMCSB PROJEXPL.C F0225 lines 1115-1119 moves Lord Chaos to
         * the selected allowed gap when the four Fluxcages are incomplete. */
        chaosThing = m11_find_group_on_square(&state->world, mapIndex, mapX, mapY);
        (void)m11_move_group_thing_f0225(state, mapIndex, mapX, mapY,
                                         escapeX, escapeY, chaosThing);
        m11_log_event(state, M11_COLOR_YELLOW,
                      "T%u: LORD CHAOS SLIPS THE FLUXCAGE",
                      (unsigned int)state->world.gameTick);
        return 1;
    }
    if (!result.fuseSequenceTriggered) return 0;

    if (!DM1_Endgame_BuildFuseMutationPlan(&mutationPlan)) return 0;

    m11_remove_fluxcages_on_square_f0446(state, mapIndex,
                                         state->world.party.mapX,
                                         state->world.party.mapY);
    m11_remove_fluxcages_on_square_f0446(state, mapIndex, mapX, mapY);
    m11_apply_fuse_mutation_plan_f0446(state, mapIndex, mapX, mapY,
                                        &mutationPlan);
    /* ReDMCSB: ENDGAME.C F0446 lines 805-812 marks the game won, sets
     * MagicalLightAmount to 200, then sets FireShieldDefense,
     * SpellShieldDefense, and ShieldDefense to 100 before the fuse
     * sequence proceeds. */
    state->world.magic.magicalLightAmount = 200;
    state->world.magic.fireShieldDefense = 100;
    state->world.magic.spellShieldDefense = 100;
    state->world.magic.partyShieldDefense = 100;
    /* ReDMCSB: ENDGAME.C F0446 lines 912-914 sets
     * G0077_B_DoNotDrawFluxcagesDuringEndgame before continuing the
     * endgame cleanup.  Keep the live C50 entries for timing/accounting,
     * but suppress them from runtime viewport sampling from this point on. */
    (void)m11_print_endgame_text_messages_f0446(state, mapIndex);
    m11_apply_fuse_final_endgame_params_f0446(state, &mutationPlan);
    m11_mark_game_won_from_fuse_f0446(state);
    m11_log_event(state, M11_COLOR_LIGHT_GREEN,
                  "T%u: %s FUSES CHAOS AND ORDER",
                  (unsigned int)state->world.gameTick, champName);
    m11_set_status(state, "ENDGAME", "FUSE COMPLETE");
    return 1;
}

static int m11_perform_fuse_action(M11_GameViewState* state,
                                   const char* champName) {
    int mapIndex, mapX, mapY;
    if (!m11_party_front_square(state, &mapIndex, &mapX, &mapY)) return 0;
    return m11_perform_fuse_action_at(state, champName, mapIndex, mapX, mapY);
}

static void m11_decrement_action_hand_charges_f0405(M11_GameViewState* state,
                                                    int championIndex) {
    struct ChampionState_Compat* champion;
    unsigned short thing;
    int thingType;
    int thingIndex;
    int chargeCount = 0;
    DM1_ActionF0405ChargeInputPc34 chargeIn;
    DM1_ActionF0405ChargePlanPc34 chargePlan;
    unsigned char* raw;
    unsigned short bits;

    if (!state || !state->world.things) return;
    if (championIndex < 0 || championIndex >= CHAMPION_MAX_PARTY) return;
    champion = &state->world.party.champions[championIndex];
    thing = champion->inventory[CHAMPION_SLOT_ACTION_HAND];
    if (thing == THING_NONE || thing == THING_ENDOFLIST) return;

    thingType = (int)THING_GET_TYPE(thing);
    thingIndex = (int)THING_GET_INDEX(thing);
    if (thingType == THING_TYPE_WEAPON) {
        if (!state->world.things->weapons ||
            thingIndex < 0 || thingIndex >= state->world.things->weaponCount) return;
        chargeCount = state->world.things->weapons[thingIndex].chargeCount;
    } else if (thingType == THING_TYPE_ARMOUR) {
        if (!state->world.things->armours ||
            thingIndex < 0 || thingIndex >= state->world.things->armourCount) return;
        chargeCount = state->world.things->armours[thingIndex].chargeCount;
    } else if (thingType == THING_TYPE_JUNK) {
        if (!state->world.things->junks ||
            thingIndex < 0 || thingIndex >= state->world.things->junkCount) return;
        chargeCount = state->world.things->junks[thingIndex].chargeCount;
    } else {
        return;
    }
    memset(&chargeIn, 0, sizeof(chargeIn));
    chargeIn.thingType = thingType;
    chargeIn.thingIndex = thingIndex;
    chargeIn.currentChargeCount = chargeCount;
    if (!dm1_v1_action_f0405_charge_plan_pc34(&chargeIn, &chargePlan) ||
        !chargePlan.valid || !chargePlan.shouldDecrement) {
        return;
    }
    if (thingType == THING_TYPE_WEAPON) {
        state->world.things->weapons[thingIndex].chargeCount--;
    } else if (thingType == THING_TYPE_ARMOUR) {
        state->world.things->armours[thingIndex].chargeCount--;
    } else if (thingType == THING_TYPE_JUNK) {
        state->world.things->junks[thingIndex].chargeCount--;
    }

    /* F0405 mutates the loaded C05/C06/C0A record, not a host-only mirror.
     * Keep the PC34 bitfield in step whenever this action has an authentic
     * raw owner; absent raw data remains a compatibility-only decoded path. */
    if (!state->world.things->rawThingData[thingType] ||
        thingIndex >= state->world.things->thingCounts[thingType]) {
        return;
    }
    raw = state->world.things->rawThingData[thingType] + thingIndex * 4;
    bits = (unsigned short)(raw[2] | ((unsigned short)raw[3] << 8));
    if (thingType == THING_TYPE_WEAPON) {
        bits = (unsigned short)((bits & ~(unsigned short)(0x0fu << 10)) |
                                ((unsigned short)state->world.things->weapons[thingIndex]
                                     .chargeCount << 10));
    } else if (thingType == THING_TYPE_ARMOUR) {
        bits = (unsigned short)((bits & ~(unsigned short)(0x0fu << 9)) |
                                ((unsigned short)state->world.things->armours[thingIndex]
                                     .chargeCount << 9));
    } else {
        bits = (unsigned short)((bits & ~(unsigned short)(0x03u << 14)) |
                                ((unsigned short)state->world.things->junks[thingIndex]
                                     .chargeCount << 14));
    }
    raw[2] = (unsigned char)(bits & 0xffu);
    raw[3] = (unsigned char)(bits >> 8);
}

static int m11_build_freeze_life_object_input_f0407(
    const M11_GameViewState* state,
    const struct ChampionState_Compat* champion,
    int currentFreezeLifeTicks,
    DM1_ActionFreezeLifeObjectInputPc34* out) {
    unsigned short thing;
    int thingType;
    int thingIndex;

    if (!out) return 0;
    memset(out, 0, sizeof(*out));
    out->currentFreezeLifeTicks = currentFreezeLifeTicks;
    out->actionHandThingType = -1;
    out->actionHandThingIndex = -1;
    out->actionHandChargeCount = 0;
    out->actionHandJunkType = -1;
    if (!state || !champion || !state->world.things) {
        return 1;
    }
    thing = champion->inventory[CHAMPION_SLOT_ACTION_HAND];
    if (thing == THING_NONE || thing == THING_ENDOFLIST) {
        return 1;
    }
    thingType = (int)THING_GET_TYPE(thing);
    thingIndex = (int)THING_GET_INDEX(thing);
    out->actionHandThingType = thingType;
    out->actionHandThingIndex = thingIndex;
    if (thingType == THING_TYPE_WEAPON) {
        if (!state->world.things->weapons ||
            thingIndex < 0 || thingIndex >= state->world.things->weaponCount) {
            return 1;
        }
        out->actionHandChargeCount =
            state->world.things->weapons[thingIndex].chargeCount;
    } else if (thingType == THING_TYPE_ARMOUR) {
        if (!state->world.things->armours ||
            thingIndex < 0 || thingIndex >= state->world.things->armourCount) {
            return 1;
        }
        out->actionHandChargeCount =
            state->world.things->armours[thingIndex].chargeCount;
    } else if (thingType == THING_TYPE_JUNK) {
        if (!state->world.things->junks ||
            thingIndex < 0 || thingIndex >= state->world.things->junkCount) {
            return 1;
        }
        out->actionHandChargeCount =
            state->world.things->junks[thingIndex].chargeCount;
        out->actionHandJunkType = (int)state->world.things->junks[thingIndex].type;
    }
    return 1;
}

static void m11_remove_action_hand_object_f0300(
    M11_GameViewState* state,
    struct ChampionState_Compat* champion)
{
    unsigned short thing;

    if (!state || !champion) {
        return;
    }
    thing = champion->inventory[CHAMPION_SLOT_ACTION_HAND];
    champion->inventory[CHAMPION_SLOT_ACTION_HAND] = THING_NONE;
    /* ReDMCSB MENU.C F0407 lines 1590-1597 calls
     * F0300_CHAMPION_GetObjectRemovedFromSlot() and then sets the
     * removed magical box Thing->Next to C0xFFFF_THING_NONE. */
    m11_set_object_drop_next(state->world.things, thing, THING_NONE);
}

static int m11_apply_party_shield_f0403(M11_GameViewState* state,
                                        int championIndex,
                                        int spellShield,
                                        int ticks,
                                        int useMana) {
    struct ChampionState_Compat* champion;
    struct TimelineEvent_Compat expiryEvent;
    DM1_ActionShieldInputPc34 input;
    DM1_ActionShieldPlanPc34 plan;
    int* shieldDefense;

    if (!state) return 0;
    if (championIndex < 0 || championIndex >= CHAMPION_MAX_PARTY) return 0;
    if (championIndex >= state->world.party.championCount) return 0;
    champion = &state->world.party.champions[championIndex];
    if (!champion->present) return 0;
    shieldDefense = spellShield ? &state->world.magic.spellShieldDefense
                                : &state->world.magic.fireShieldDefense;
    memset(&input, 0, sizeof(input));
    input.isSpellShield = spellShield;
    input.useMana = useMana;
    input.currentMana = champion->mana.current;
    input.baseTicks = ticks;
    input.currentShieldDefense = *shieldDefense;
    if (!dm1_v1_action_shield_plan_f0403_pc34(&input, &plan) || !plan.valid) {
        return 0;
    }
    champion->mana.current = (unsigned short)plan.remainingMana;
    if (plan.eventDelayTicks <= 0) {
        return plan.successful;
    }
    *shieldDefense = plan.newShieldDefense;
    memset(&expiryEvent, 0, sizeof(expiryEvent));
    expiryEvent.kind = TIMELINE_EVENT_STATUS_TIMEOUT;
    expiryEvent.fireAtTick = state->world.gameTick + (uint32_t)plan.eventDelayTicks;
    expiryEvent.mapIndex = state->world.party.mapIndex;
    expiryEvent.mapX = state->world.party.mapX;
    expiryEvent.mapY = state->world.party.mapY;
    expiryEvent.cell = -1;
    expiryEvent.aux0 = plan.statusEventType;
    expiryEvent.aux1 = plan.defenseDelta;
    expiryEvent.aux2 = championIndex;
    /* ReDMCSB MENU.C F0403 lines 1099-1115 stores the shield defense in
     * the event and schedules C77/C78 at GameTime + adjusted ticks; the
     * TIMELINE.C C77/C78 handler later subtracts the same defense value. */
    (void)F0721_TIMELINE_Schedule_Compat(&state->world.timeline, &expiryEvent);
    return plan.successful;
}

static int m11_add_influence_experience(M11_GameViewState* state,
                                        int championIndex,
                                        int experience) {
    struct ChampionLifecycleState_Compat* lifecycleChampion;
    struct LevelUpMarker_Compat marker;
    int mapDifficulty = 0;
    int priestLevel;
    if (!state || championIndex < 0 ||
        championIndex >= CHAMPION_MAX_PARTY || experience <= 0) {
        return 0;
    }
    lifecycleChampion = &state->world.lifecycle.champions[championIndex];
    memset(&marker, 0, sizeof(marker));
    if (state->world.dungeon && state->world.dungeon->maps &&
        state->world.party.mapIndex >= 0 &&
        state->world.party.mapIndex < state->world.dungeon->header.mapCount) {
        mapDifficulty =
            (int)state->world.dungeon->maps[state->world.party.mapIndex].difficulty;
    }
    /* ReDMCSB MENU.C F0401 line 987 calls CHAMPION.C F0304 with
     * C14_SKILL_INFLUENCE.  Use the lifecycle F0304 wrapper so the award
     * also updates temporary XP, the Priest base skill and level-up state. */
    if (F0852_LIFECYCLE_AwardMagicXP_Compat(
            lifecycleChampion, championIndex, LIFECYCLE_SKILL_INFLUENCE,
            experience, mapDifficulty, state->world.gameTick,
            state->world.lifecycle.lastCreatureAttackTime,
            &state->world.masterRng, &marker)) {
        priestLevel = F0848_LIFECYCLE_ComputeSkillLevel_Compat(
            lifecycleChampion, LIFECYCLE_SKILL_PRIEST, 0);
        if (priestLevel > 0) {
            state->world.party.champions[championIndex]
                .skillLevels[LIFECYCLE_SKILL_PRIEST] = (unsigned short)priestLevel;
        }
    }
    return 1;
}

static int m11_perform_f0401_frighten_action(M11_GameViewState* state,
                                             int championIndex,
                                             unsigned char actionIndex,
                                             int mapIndex,
                                             int mapX,
                                             int mapY) {
    unsigned short groupThing;
    int groupIndex;
    struct DungeonGroup_Compat* group;
    const struct CreatureBehaviorProfile_Compat* profile;
    DM1_ActionFrightInputPc34 frightIn;
    DM1_ActionFrightPlanPc34 frightPlan;
    int influenceLevel;
    int fearResistance;
    int randomRange;
    int randomDraw;
    int activeIndex = -1;

    if (!state || !state->world.things || !state->world.things->groups) return 0;

    groupThing = m11_find_group_on_square(&state->world, mapIndex, mapX, mapY);
    if (groupThing == THING_NONE || groupThing == THING_ENDOFLIST) {
        activeIndex = m11_find_creature_ai_on_square(state, mapIndex, mapX, mapY);
        if (activeIndex < 0) return 0;
        groupIndex = state->world.creatureAI[activeIndex].reserved0;
    } else {
        groupIndex = THING_GET_INDEX(groupThing);
    }
    if (groupIndex < 0 || groupIndex >= state->world.things->groupCount) {
        return 0;
    }

    group = &state->world.things->groups[groupIndex];
    profile = CREATURE_GetProfile_Compat(group->creatureType);
    if (!profile) return 0;

    influenceLevel = M11_GameView_GetSkillLevel(
        state, championIndex, DM1_SKILL_IDX_INFLUENCE);
    if (influenceLevel < 0) influenceLevel = 0;
    fearResistance = DM1_FEAR_RESISTANCE(profile->properties);
    randomRange = dm1_v1_action_fright_random_range_f0401_pc34(
        actionIndex, influenceLevel);
    if (randomRange <= 0) return 0;
    randomDraw = fearResistance == DM1_IMMUNE_TO_FEAR ? 0 :
        F0732_COMBAT_RngRandom_Compat(&state->world.masterRng, randomRange);
    memset(&frightIn, 0, sizeof(frightIn));
    frightIn.actionIndex = actionIndex;
    frightIn.influenceSkillLevel = influenceLevel;
    frightIn.fearResistance = fearResistance;
    frightIn.randomDraw = randomDraw;
    frightIn.movementTicks = profile->movementTicks;
    if (!dm1_v1_action_fright_plan_f0401_pc34(&frightIn, &frightPlan) ||
        !frightPlan.valid) {
        return 0;
    }

    if (frightPlan.resisted) {
        (void)m11_add_influence_experience(
            state, championIndex, frightPlan.influenceExperience);
        return 0;
    }

    group->behavior = DM1_BEHAVIOR_FLEE;
    if (activeIndex < 0) {
        activeIndex = m11_find_creature_ai_on_square(state, mapIndex, mapX, mapY);
    }
    if (activeIndex >= 0) {
        state->world.creatureAI[activeIndex].stateKind = AI_STATE_FLEE;
        state->world.creatureAI[activeIndex].fearCounter = frightPlan.fleeDelayTicks;
    }
    (void)m11_add_influence_experience(
        state, championIndex, frightPlan.influenceExperience);
    return frightPlan.frightened;
}

/* ---------------------------------------------------------------
 * V1 projectile tick advance — drives F0811 per live projectile.
 *
     * M10 ships F0811_PROJECTILE_Advance_Compat (mirror of
     * F0219_PROJECTILE_ProcessEvents48To49) fully implemented and
     * verified by the M10 projectile probe: cell flip, cross-cell
     * step, kinetic/energy decay, wall / door / boundary / fluxcage
     * hit classification, impact-attack computation, explosion spawn
     * on magical hit, and next-move rescheduling.  The M10 timeline
     * dispatcher can now advance/reschedule the core flight path, while
     * this V1 game-view layer still owns runtime side effects that need
     * M11 state: audio/log cues, explosion insertion for rendering,
     * champion/group mutation handoffs, and thrown-object cleanup.
 *
 * Each active projectile is advanced once per game tick as long
 * as its `scheduledAtTick` has arrived.  The function builds a
 * CellContentDigest_Compat from the dungeon tile data, party
 * position and live creature-AI state, calls F0811, then applies
 * the returned new state back to the slot.  On impact it despawns
 * the slot via F0813, optionally spawns a source-backed explosion
 * via F0821, applies damage to any DungeonGroup at the dest via
 * F0738 for HIT_CREATURE, decrements champion HP for HIT_CHAMPION,
 * and emits DM1-style log cues so the player sees the cast through
 * to its recognisable conclusion instead of only the first frame.
 *
     * M10 functions are CALLED here and share the same F0811 source
     * core as the orchestrator dispatcher; this function keeps the
     * M11-visible side effects in one place until those handoffs are
     * source-locked in M10 individually.
 *
 * Ref: ReDMCSB PROJEXPL.C F0219_PROJECTILE_ProcessEvents48To49
 *      (per-tick advance), F0220_EXPLOSION_ProcessEvent25 (per-
 *      tick explosion; v1 explosion-advance is covered by spawning
 *      the explosion into world.explosions so it is rendered by
 *      the viewport for one visible burst frame). */

/* Helper: which direction does cell X lie in?  Destination cell on a
 * cross-cell step is determined by F0811 internally; what we need is
 * the destination SQUARE (mapX, mapY) adjacent to the source square
 * in the projectile's direction.  Exact mirror of Fontanel step
 * table: NORTH=-Y, EAST=+X, SOUTH=+Y, WEST=-X. */
static void m11_projectile_step(int dir, int* dx, int* dy) {
    switch (dir & 3) {
        case 0: *dx = 0;  *dy = -1; break;  /* NORTH */
        case 1: *dx = +1; *dy =  0; break;  /* EAST  */
        case 2: *dx = 0;  *dy = +1; break;  /* SOUTH */
        case 3: *dx = -1; *dy =  0; break;  /* WEST  */
        default:*dx = 0;  *dy =  0; break;
    }
}

static int m11_party_champion_cell_mask(const struct GameWorld_Compat* world) {
    int mask = 0;
    int i;
    if (!world) return 0;
    /* ReDMCSB: MOVESENS.C F0266 lines 241-247 builds the party impact
     * cell map through F0285_CHAMPION_GetIndexInCell instead of treating
     * every party sub-cell as occupied. */
    for (i = 0; i < CHAMPION_MAX_PARTY; ++i) {
        const struct ChampionState_Compat* champion =
            &world->party.champions[i];
        if (!champion->present) continue;
        mask |= 1 << ((int)champion->cell & 3);
    }
    return mask;
}

/* Build a CellContentDigest_Compat capturing everything F0811
 * needs to know about the source and destination squares.  Returns
 * 1 on success, 0 if the source square cannot be sampled (should
 * never happen for a live projectile).  Populates destIsMapBoundary
 * on off-map destinations so F0811 classifies them as HIT_WALL. */
static int m11_build_projectile_digest(
    const struct GameWorld_Compat* world,
    const struct ProjectileInstance_Compat* p,
    int otherProjectileIndex,
    struct CellContentDigest_Compat* out) {
    unsigned char sourceSq = 0;
    unsigned char destSq = 0;
    int dx = 0, dy = 0;
    int destX, destY;
    const struct DungeonMapDesc_Compat* map;
    int i;
    if (!world || !p || !out) return 0;
    if (!world->dungeon || p->mapIndex < 0
        || p->mapIndex >= (int)world->dungeon->header.mapCount) return 0;
    map = &world->dungeon->maps[p->mapIndex];
    if (!m11_get_square_byte(world, p->mapIndex, p->mapX, p->mapY,
                             &sourceSq)) return 0;
    m11_projectile_step(p->direction, &dx, &dy);
    destX = p->mapX + dx;
    destY = p->mapY + dy;

    memset(out, 0, sizeof(*out));
    out->sourceMapIndex   = p->mapIndex;
    out->sourceMapX       = p->mapX;
    out->sourceMapY       = p->mapY;
    out->sourceSquareType = (sourceSq >> 5) & 7;

    /* Check for other projectiles on source square (to detect
     * in-flight collisions when two projectiles converge). */
    for (i = 0; i < world->projectiles.count; ++i) {
        const struct ProjectileInstance_Compat* q = &world->projectiles.entries[i];
        if (i == otherProjectileIndex) continue;
        if (!m11_projectile_instance_active(q)) continue;
        if (q->mapIndex == p->mapIndex && q->mapX == p->mapX
                && q->mapY == p->mapY && q->cell == p->cell) {
            /* ReDMCSB PROJEXPL.C F0219/F0217 keeps projectile impact
             * tests cell-specific through M011_CELL; same square is not
             * enough to collide. */
            out->sourceHasOtherProjectile = 1;
            break;
        }
    }

    /* Map boundary check. */
    if (destX < 0 || destY < 0
        || destX >= (int)map->width || destY >= (int)map->height) {
        out->destMapIndex      = p->mapIndex;
        out->destMapX          = destX;
        out->destMapY          = destY;
        out->destIsMapBoundary = 1;
        out->destSquareType    = PROJECTILE_ELEMENT_WALL;
        out->destDoorState     = PROJECTILE_DOOR_STATE_NONE;
        out->destTeleporterNewDirection = -1;
        return 1;
    }
    if (!m11_get_square_byte(world, p->mapIndex, destX, destY, &destSq)) {
        out->destMapIndex      = p->mapIndex;
        out->destMapX          = destX;
        out->destMapY          = destY;
        out->destIsMapBoundary = 1;
        out->destSquareType    = PROJECTILE_ELEMENT_WALL;
        out->destDoorState     = PROJECTILE_DOOR_STATE_NONE;
        out->destTeleporterNewDirection = -1;
        return 1;
    }

    out->destMapIndex  = p->mapIndex;
    out->destMapX      = destX;
    out->destMapY      = destY;
    out->destSquareType = (destSq >> 5) & 7;
    out->destTeleporterNewDirection = -1;

    /* Door state — DM1 encodes door state in the low bits of the
     * square attribute byte.  0 = open, 4 = fully closed. */
    if (out->destSquareType == PROJECTILE_ELEMENT_DOOR) {
        int doorAttr = destSq & 0x07;
        if (doorAttr == 0) {
            out->destDoorState = PROJECTILE_DOOR_STATE_OPEN;
        } else if (doorAttr <= 4) {
            out->destDoorState = doorAttr;  /* CLOSED_ONE_FOURTH..CLOSED_FULL */
        } else if (doorAttr == 5) {
            out->destDoorState = PROJECTILE_DOOR_STATE_DESTROYED;
        } else {
            out->destDoorState = PROJECTILE_DOOR_STATE_NONE;
        }
        {
            unsigned short firstThing = THING_ENDOFLIST;
            firstThing = m11_get_first_square_thing(world, p->mapIndex, destX, destY);
            if (firstThing != THING_ENDOFLIST
                    && firstThing != THING_NONE
                    && THING_GET_TYPE(firstThing) == THING_TYPE_DOOR
                    && world->things
                    && world->things->doors) {
                int doorIndex = THING_GET_INDEX(firstThing);
                if (doorIndex >= 0 && doorIndex < world->things->doorCount) {
                    out->destDoorHasButton = world->things->doors[doorIndex].button ? 1 : 0;
                }
            }
        }
        /* Magical projectiles pass through normal doors; v1 leaves
         * the per-door MASK0x0002 flag unset so F0816 uses its
         * per-subtype override only. */
        out->destDoorAllowsProjectilePassThrough = 0;
    } else {
        out->destDoorState = PROJECTILE_DOOR_STATE_NONE;
    }

    /* ReDMCSB PROJEXPL.C:1260-1310 (F0228/F0229): when the dest
     * square carries a TELEPORTER, the projectile gets rotated to
     * the direction the teleporter points to.  v1 reads the
     * first thing on the square, looks up THING_TYPE_TELEPORTER,
     * and uses the direction field (rotated by F0228 visibility)
     * to set destTeleporterNewDirection.  In DM1 PC 3.4 the
     * teleporter thing carries an explicit target direction in
     * the scope/direction field.  If no teleporter thing is
     * present, destTeleporterNewDirection stays -1 (no rotation). */
    if (out->destSquareType == PROJECTILE_ELEMENT_TELEPORTER) {
        unsigned short firstThing = m11_get_first_square_thing(
            world, p->mapIndex, destX, destY);
        if (firstThing != THING_ENDOFLIST
                && firstThing != THING_NONE
                && THING_GET_TYPE(firstThing) == THING_TYPE_TELEPORTER
                && world->things
                && world->things->teleporters) {
            int teleIndex = THING_GET_INDEX(firstThing);
            if (teleIndex >= 0
                    && teleIndex < world->things->teleporterCount) {
                /* ReDMCSB PROJEXPL.C:1260-1310: the teleporter
                 * rotation field (2 bits, 0..3) is the direction
                 * the projectile is rotated to when entering the
                 * teleporter.  absoluteRotation toggles whether
                 * the rotation is world-frame or party-relative.
                 * F0228 visibility picks this when the destination
                 * is visible; v1 always applies the rotation
                 * (the projectile then enters the destination map
                 * with the rotated direction). */
                int newDir = (int)world->things->teleporters[teleIndex].rotation;
                if (newDir >= 0 && newDir <= 3) {
                    out->destTeleporterNewDirection = newDir;
                }
            }
        }
    }

    /* Party presence on destination square. */
    if (world->party.mapIndex == p->mapIndex
            && world->party.mapX == destX
            && world->party.mapY == destY) {
        out->destChampionCellMask = m11_party_champion_cell_mask(world);
        out->destHasChampion = out->destChampionCellMask ? 1 : 0;
        out->destPartyDirection = world->party.direction & 3;
    }

    /* Creature group on destination square (via AI state slots).  v1
     * uses cellMask=0x0F so a projectile that enters a creature's
     * square resolves as HIT_CREATURE regardless of which sub-cell
     * the creature occupies.  Source-locked per ReDMCSB
     * GROUP.C:1503-1510 (F0202) and the sub-cell mask bits in
     * DEFS.H: M550_GROUP_CELL_OCCUPIED_MASK = 0x0F for a
     * full-square creature; quarter-square creatures use the
     * high nibble (0xF0).  v1 keeps the full 0x0F mask because
     * the per-sub-cell positioning is not yet wired in the
     * V1 creature-drawing pass; see GROUP.C:1503 for the
     * original and DEFS.H M550 for the mask layout. */
    for (i = 0; i < world->creatureAICount
                && i < GAMEWORLD_CREATURE_AI_CAPACITY; ++i) {
        const struct CreatureAIState_Compat* ai = &world->creatureAI[i];
        if (ai->groupMapIndex == p->mapIndex
                && ai->groupMapX == destX
                && ai->groupMapY == destY) {
            const struct CreatureBehaviorProfile_Compat* profile =
                CREATURE_GetProfile_Compat(ai->creatureType);
            out->destHasCreatureGroup = 1;
            out->destCreatureType     = ai->creatureType;
            out->destCreatureCellMask = 0x0F;
            out->destCreatureIsNonMaterial = (profile != NULL)
                && ((profile->attributes
                     & CREATURE_ATTR_MASK_NON_MATERIAL) != 0);
            break;
        }
    }

    /* Other projectiles on destination square. */
    for (i = 0; i < world->projectiles.count; ++i) {
        const struct ProjectileInstance_Compat* q = &world->projectiles.entries[i];
        if (i == otherProjectileIndex) continue;
        if (!m11_projectile_instance_active(q)) continue;
        if (q->mapIndex == p->mapIndex && q->mapX == destX
                && q->mapY == destY) {
            int newCell;
            if ((p->direction & 1) == (p->cell & 1)) {
                newCell = (p->cell - 1) & 3;
            } else {
                newCell = (p->cell + 1) & 3;
            }
            if (q->cell == newCell) {
                /* ReDMCSB F0219 lines 721-725 applies the parity cell step
                 * before the projectile is relinked; only that landing cell
                 * can collide with another projectile. */
                out->destHasOtherProjectile = 1;
                break;
            }
        }
    }

    return 1;
}

static int m11_projectile_landing_cell_f0219(
    const struct ProjectileInstance_Compat* p) {
    if (!p) return -1;
    if ((p->direction & 1) == (p->cell & 1)) {
        return (p->cell - 1) & 3;
    }
    return (p->cell + 1) & 3;
}

static int m11_find_projectile_collision_peer(
    const struct GameWorld_Compat* world,
    const struct ProjectileInstance_Compat* p,
    int projectileIndex,
    const struct CellContentDigest_Compat* digest) {
    int i;
    int landingCell;
    if (!world || !p || !digest) return -1;

    for (i = 0; i < PROJECTILE_LIST_CAPACITY; ++i) {
        const struct ProjectileInstance_Compat* q =
            &world->projectiles.entries[i];
        if (i == projectileIndex || !m11_projectile_instance_active(q)) continue;
        if (q->mapIndex == p->mapIndex && q->mapX == p->mapX &&
            q->mapY == p->mapY && q->cell == p->cell) {
            return i;
        }
    }

    landingCell = m11_projectile_landing_cell_f0219(p);
    if (landingCell < 0) return -1;
    for (i = 0; i < PROJECTILE_LIST_CAPACITY; ++i) {
        const struct ProjectileInstance_Compat* q =
            &world->projectiles.entries[i];
        if (i == projectileIndex || !m11_projectile_instance_active(q)) continue;
        if (q->mapIndex == digest->destMapIndex &&
            q->mapX == digest->destMapX &&
            q->mapY == digest->destMapY &&
            q->cell == landingCell) {
            return i;
        }
    }
    return -1;
}

static void m11_schedule_open_door_spell_toggle(
    M11_GameViewState* state,
    const struct ProjectileTickResult_Compat* r) {
    int resolvedEffect = -1;
    struct TimelineEvent_Compat animEvent;

    if (!state || !state->world.dungeon || !r || !r->emittedDoorToggleEvent) {
        return;
    }
    if (!F0714_DOOR_ResolveAnimationEffect_Compat(
            state->world.dungeon,
            r->outNextTick.mapIndex,
            r->outNextTick.mapX,
            r->outNextTick.mapY,
            DOOR_EFFECT_TOGGLE,
            &resolvedEffect,
            NULL)) {
        return;
    }
    if (!F0713_DOOR_BuildAnimationEvent_Compat(
            r->outNextTick.mapIndex,
            r->outNextTick.mapX,
            r->outNextTick.mapY,
            resolvedEffect,
            r->outNextTick.fireAtTick,
            &animEvent)) {
        return;
    }
    (void)F0721_TIMELINE_Schedule_Compat(&state->world.timeline, &animEvent);
}

static void m11_schedule_projectile_door_destruction(
    M11_GameViewState* state,
    const struct ProjectileTickResult_Compat* r) {
    if (!state || !r || !r->emittedDoorDestructionEvent) {
        return;
    }
    if (r->outNextTick.kind != TIMELINE_EVENT_DOOR_DESTRUCTION) {
        return;
    }
    /* ReDMCSB PROJEXPL.C F0217 lines 506-507 routes blocking door hits
     * through F0232; Firestaff F0819 has already built the source-shaped
     * C02/TIMELINE_EVENT_DOOR_DESTRUCTION event, so M11 only enqueues it
     * for the normal F0887 timeline dispatcher to set door state C5. */
    (void)F0721_TIMELINE_Schedule_Compat(&state->world.timeline,
                                         &r->outNextTick);
}

static int m11_projectile_associated_weapon_type(
    M11_GameViewState* state,
    const struct ProjectileInstance_Compat* projectile) {
    unsigned short associatedThing;
    const unsigned char* raw;
    DM1_WeaponInfo info;
    int objectWeight;
    if (!state || !projectile || !state->world.things) return -1;

    associatedThing = (unsigned short)projectile->reserved1;
    if (associatedThing == THING_NONE || associatedThing == THING_ENDOFLIST) return -1;
    if (THING_GET_TYPE(associatedThing) != THING_TYPE_WEAPON) return -1;
    if (!dm1_v1_dungeon_get_object_weight_f0140_pc34(
            state->world.things, associatedThing, &objectWeight)) {
        return -1;
    }
    raw = dm1_v1_dungeon_get_thing_data_pc34(
        state->world.things, associatedThing);
    if (!raw || !dm1_weapon_info_pc34(raw[2] & 0x7f, &info)) {
        return -1;
    }
    return raw[2] & 0x7f;
}

static int m11_attach_projectile_associated_thing_to_group(
    M11_GameViewState* state,
    struct DungeonGroup_Compat* group,
    const struct ProjectileInstance_Compat* projectile) {
    unsigned short associatedThing;
    DM1_ProjectileGroupSlotAttachReceiptPc34 attachReceipt;
    unsigned short chainThings[64];
    unsigned short current;
    int chainCount = 0;
    if (!state || !group || !projectile || !state->world.things) return 0;
    associatedThing = (unsigned short)projectile->reserved1;
    if (associatedThing == THING_NONE || associatedThing == THING_ENDOFLIST) return 0;

    /* ReDMCSB PROJEXPL.C:F0217 lines 540-553 selects GROUP.Slot as the
     * projectile-delete target. F0215 lines 248-256 then delegates existing
     * possession lists to DUNGEON.C:F0163 lines 1798-1837. M11 now consumes
     * the same DM1 receipt as M10 instead of duplicating tail-link policy. */
    current = group->slot;
    while (current != THING_NONE &&
           current != THING_ENDOFLIST &&
           chainCount < (int)(sizeof(chainThings) / sizeof(chainThings[0]))) {
        chainThings[chainCount++] = current;
        current = m11_get_raw_next_thing(state->world.things, current);
        if (current == THING_NONE || current == THING_ENDOFLIST) {
            current = m11_get_decoded_next_thing(
                state->world.things, chainThings[chainCount - 1]);
        }
    }
    if (chainCount < (int)(sizeof(chainThings) / sizeof(chainThings[0]))) {
        chainThings[chainCount++] = current;
    }

    memset(&attachReceipt, 0, sizeof(attachReceipt));
    if (!dm1_v1_projectile_group_slot_attach_receipt_f0215_pc34(
            associatedThing, group->slot, chainThings, chainCount,
            &attachReceipt) ||
        !attachReceipt.valid ||
        !attachReceipt.shouldSetAssociatedNextEnd ||
        attachReceipt.chainOverflow) {
        return 0;
    }
    m11_set_next_thing(state->world.things, attachReceipt.associatedThing,
                       THING_ENDOFLIST);
    if (attachReceipt.shouldSetGroupSlotHead) {
        group->slot = attachReceipt.associatedThing;
        return 1;
    }
    if (attachReceipt.shouldAppendAfterTail && attachReceipt.foundTail) {
        m11_set_next_thing(state->world.things, attachReceipt.tailThing,
                           attachReceipt.associatedThing);
        return 1;
    }
    return 0;
}

static int m11_maybe_consume_thrown_potion_on_impact(
    M11_GameViewState* state,
    const struct ProjectileInstance_Compat* projectile,
    const struct ProjectileTickResult_Compat* result) {
    DM1_ProjectileMaterializationPlanPc34 plan;
    int potionCount;
    if (!state || !projectile || !result || !state->world.things) return 0;
    potionCount = state->world.things->potions
                      ? state->world.things->potionCount
                      : 0;
    if (!dm1_v1_projectile_materialization_plan_pc34(
            projectile, result, 0, potionCount, &plan) ||
        !plan.shouldConsumePotion) {
        return 0;
    }
    {
        int thingType;
        int thingSubtype;
        int weaponProjectileAspectOrdinal;
        if (!m11_projectile_associated_thing_material(
                state, plan.associatedThing, &thingType, &thingSubtype,
                &weaponProjectileAspectOrdinal) ||
            thingType != THING_TYPE_POTION) {
            return 0;
        }
    }
    /* ReDMCSB PROJEXPL.C F0217 lines 444-455 records thrown Ven/Ful
     * potions as RemovePotion impacts.  The impact deletes the projectile
     * thing, so the associated potion object must leave any live object
     * chain instead of remaining recoverable after the explosion. */
    m11_set_object_drop_next(state->world.things,
                             plan.associatedThing, THING_NONE);
    return 1;
}

static int m11_link_projectile_thing_to_square_tail(
    struct GameWorld_Compat* world,
    int mapIndex,
    int mapX,
    int mapY,
    unsigned short thing) {
    int base;
    const struct DungeonMapDesc_Compat* map;
    int squareIndex;
    DM1_ProjectileSquareAttachReceiptPc34 attachReceipt;
    unsigned short chainThings[64];
    unsigned short current;
    int chainCount = 0;

    if (!world || !world->dungeon || !world->things ||
        !world->things->squareFirstThings) {
        return 0;
    }
    if (mapIndex < 0 || mapIndex >= (int)world->dungeon->header.mapCount) {
        return 0;
    }
    map = &world->dungeon->maps[mapIndex];
    if (mapX < 0 || mapY < 0 ||
        mapX >= (int)map->width || mapY >= (int)map->height) {
        return 0;
    }
    /* ReDMCSB DUNGEON.C F0163 delegates real compact-table mutation to
     * F0514.  Dense test worlds retain the legacy branch below. */
    if (m11_world_has_compact_sft(world)) {
        return F0514_DUNGEON_LinkThingToList_Compat(
            world->dungeon, world->things, thing, THING_ENDOFLIST,
            mapIndex, mapX, mapY);
    }
    base = m11_map_square_base(world->dungeon, mapIndex);
    if (base < 0) return 0;
    squareIndex = base + mapX * (int)map->height + mapY;
    if (squareIndex < 0 ||
        squareIndex >= world->things->squareFirstThingCount) {
        return 0;
    }

    current = world->things->squareFirstThings[squareIndex];
    while (current != THING_NONE &&
           current != THING_ENDOFLIST &&
           chainCount < (int)(sizeof(chainThings) / sizeof(chainThings[0]))) {
        chainThings[chainCount++] = current;
        current = m11_get_raw_next_thing(world->things, current);
        if (current == THING_NONE || current == THING_ENDOFLIST) {
            current = m11_get_decoded_next_thing(
                world->things, chainThings[chainCount - 1]);
        }
    }
    if (chainCount < (int)(sizeof(chainThings) / sizeof(chainThings[0]))) {
        chainThings[chainCount++] = current;
    }

    memset(&attachReceipt, 0, sizeof(attachReceipt));
    if (!dm1_v1_projectile_square_attach_receipt_f0215_pc34(
            thing, world->things->squareFirstThings[squareIndex],
            chainThings, chainCount, &attachReceipt) ||
        !attachReceipt.valid ||
        !attachReceipt.shouldSetDroppedNextEnd ||
        attachReceipt.chainOverflow) {
        return 0;
    }
    m11_set_object_drop_next(world->things, attachReceipt.baseThing,
                             THING_ENDOFLIST);
    m11_set_next_thing(world->things, attachReceipt.baseThing,
                       THING_ENDOFLIST);
    if (attachReceipt.shouldSetSquareFirstThing) {
        world->things->squareFirstThings[squareIndex] =
            attachReceipt.droppedThing;
        return 1;
    }
    if (attachReceipt.shouldAppendAfterTail && attachReceipt.foundTail) {
        m11_set_next_thing(world->things, attachReceipt.tailThing,
                           attachReceipt.droppedThing);
        return 1;
    }
    return 0;
}

static int m11_materialize_projectile_associated_thing(
    M11_GameViewState* state,
    const struct ProjectileInstance_Compat* projectile,
    const struct ProjectileTickResult_Compat* result,
    int associatedThingMovedToGroup) {
    DM1_ProjectileMaterializationReceiptPc34 receipt;
    if (!state || !projectile) return 1;
    if (!state->world.things || !state->world.dungeon) return 1;
    memset(&receipt, 0, sizeof(receipt));
    if (!dm1_v1_projectile_materialization_receipt_f0215_pc34(
            projectile, result, associatedThingMovedToGroup,
            state->world.things->potions ? state->world.things->potionCount : 0,
            THING_ENDOFLIST, NULL, 0, &receipt) ||
        !receipt.valid || !receipt.handled ||
        !receipt.shouldUnlinkProjectileFromSquare) {
        return 0;
    }

    if (receipt.shouldMaterialize) {
        int thingType;
        int thingSubtype;
        int weaponProjectileAspectOrdinal;
        if (!m11_projectile_associated_thing_material(
                state, receipt.materialization.droppedThing, &thingType,
                &thingSubtype, &weaponProjectileAspectOrdinal)) {
            return 0;
        }
    }

    /* F0215 deletes the live C14 after F0214 has retired its C48/C49
     * receipt. A compact square chain may not mirror that runtime C14 in
     * headless/direct M11 advances; unlink it when present, but never let
     * that absent mirror suppress the independent Projectile.Slot drop. */
    (void)m11_unlink_thing_from_square(
        &state->world, receipt.cleanupMapIndex, receipt.cleanupMapX,
        receipt.cleanupMapY, receipt.projectileThing);

    /* ReDMCSB PROJEXPL.C F0217:607-608 unlinks C14 before F0215:248-260
     * decides whether Slot enters GROUP.Slot, a target square, or nowhere.
     * This M11 direct-tick path must consume the same DM1 receipt as M10 so
     * the next F0115 sample cannot draw both the old projectile and its drop. */
    if (receipt.shouldMaterialize &&
        !m11_link_projectile_thing_to_square_tail(
            &state->world, receipt.mapIndex, receipt.mapX,
            receipt.mapY, receipt.materialization.droppedThing)) {
        return 0;
    }

    if (state->world.things->projectiles &&
        (int)THING_GET_INDEX(receipt.projectileThing) <
            state->world.things->projectileCount) {
        m11_set_next_thing(state->world.things, receipt.projectileThing,
                           receipt.projectileNextAfterDelete);
    }
    return 1;
}

static void m11_delete_projectile_move_events_after_impact(
    M11_GameViewState* state,
    int projectileSlot)
{
    int readIndex;
    int newCount;
    int writeIndex = 0;

    if (!state || projectileSlot < 0) {
        return;
    }
    /* ReDMCSB PROJEXPL.C F0214 deletes the C48/C49 event before F0215
     * clears C14. This direct M11 F0811 loop otherwise leaves the original
     * move event queued after it has already despawned the runtime slot.
     * C11 belongs to F0330/F0407 action cooldown ownership and is never a
     * projectile cleanup target. */
    for (readIndex = 0; readIndex < state->world.timeline.count; ++readIndex) {
        const struct TimelineEvent_Compat* event =
            &state->world.timeline.events[readIndex];
        if (event->kind == TIMELINE_EVENT_PROJECTILE_MOVE &&
            event->aux0 == projectileSlot) {
            continue;
        }
        state->world.timeline.events[writeIndex++] = *event;
    }
    newCount = writeIndex;
    while (writeIndex < state->world.timeline.count) {
        memset(&state->world.timeline.events[writeIndex++], 0,
               sizeof(state->world.timeline.events[0]));
    }
    state->world.timeline.count = newCount;
}

/* M10 owns every authenticated source-backed C48/C49 projectile step. M11
 * retains legacy synthetic/probe advancement, but must never advance a slot
 * that the orchestrator already consumed through F0219/F0218. */
static int m11_projectile_has_m10_move_owner(
    const M11_GameViewState* state,
    int projectileSlot)
{
    uint64_t slotMask;
    uint32_t dispatchedAt;
    uint32_t currentTick;
    if (!state || !state->world.pc34OriginalC3C4ReceiptValid ||
        projectileSlot < 0 ||
        projectileSlot >= PROJECTILE_LIST_CAPACITY) return 0;
    slotMask = UINT64_C(1) << projectileSlot;
    dispatchedAt = state->world.pc34M10ProjectileDispatchTick;
    currentTick = state->world.gameTick;
    /* F0887 may be called directly by the M11 movement bridge, or from
     * F0884 just before it advances GameTime.  Both retain the same
     * post-dispatch presentation frame. */
    return (state->world.pc34M10ProjectileDispatchMask & slotMask) != 0 &&
           (dispatchedAt == currentTick || dispatchedAt + 1u == currentTick);
}

static int m11_maybe_heal_black_flame_from_fireball(
    M11_GameViewState* state,
    const struct ProjectileInstance_Compat* projectile,
    const struct ProjectileTickResult_Compat* result)
{
    int impactMap;
    int impactX;
    int impactY;
    unsigned short groupThing;
    int groupIndex;
    struct DungeonGroup_Compat* group;
    int slotIndex = -1;
    int healed = 0;
    if (!state || !projectile || !result || !state->world.things) return 0;
    if (result->resultKind != PROJECTILE_RESULT_HIT_CREATURE ||
        !result->emittedCombatAction) {
        return 0;
    }
    if (projectile->projectileSubtype != PROJECTILE_SUBTYPE_FIREBALL) return 0;

    impactMap = result->newMapIndex;
    impactX = result->newMapX;
    impactY = result->newMapY;
    groupThing = m11_find_group_on_square(&state->world, impactMap,
                                          impactX, impactY);
    if (groupThing == THING_NONE || groupThing == THING_ENDOFLIST) return 0;
    groupIndex = THING_GET_INDEX(groupThing);
    if (groupIndex < 0 || groupIndex >= state->world.things->groupCount) {
        return 0;
    }
    group = &state->world.things->groups[groupIndex];
    if (!dm1_v1_black_flame_fireball_heal_pc34(
            projectile, result, group, &slotIndex, &healed)) {
        return 0;
    }
    group->health[slotIndex] = (unsigned short)healed;
    m11_write_raw_group_record(state->world.things, groupIndex);
    m11_log_event(state, M11_COLOR_ORANGE,
                  "T%u: FIREBALL FEEDS %s",
                  (unsigned int)state->world.gameTick,
                  m11_creature_name((int)group->creatureType));
    return 1;
}

