static int m11_dm1_armour_defense_f0143(int armourType,
                                        int useSharpDefense,
                                        int* outDefense,
                                        int* outIsShield,
                                        int* outWeight)
{
    int defense;
    int attributes;
    if (!outDefense) return 0;
    *outDefense = 0;
    if (outIsShield) *outIsShield = 0;
    if (outWeight) *outWeight = 0;
    if (armourType < 0 ||
        armourType >= (int)(sizeof(s_m11_dm1_armour_info_pc34) /
                            sizeof(s_m11_dm1_armour_info_pc34[0]))) {
        return 0;
    }
    defense = (int)s_m11_dm1_armour_info_pc34[armourType].defense;
    attributes = (int)s_m11_dm1_armour_info_pc34[armourType].attributes;
    if (useSharpDefense) {
        /* ReDMCSB DUNGEON.C F0143 lines 1240-1244:
         * F0030_MAIN_GetScaledProduct(Defense, 3, sharp + 4). */
        defense = (defense * ((attributes & 0x07) + 4)) >> 3;
    }
    *outDefense = defense;
    if (outIsShield) *outIsShield = (attributes & 0x80) ? 1 : 0;
    if (outWeight) *outWeight = (int)s_m11_dm1_armour_info_pc34[armourType].weight;
    return 1;
}

static int m11_defender_inventory_slot_for_wound_index(int woundIndex)
{
    switch (woundIndex) {
    case 0: return CHAMPION_SLOT_HAND_LEFT;
    case 1: return CHAMPION_SLOT_HEAD;
    case 2: return CHAMPION_SLOT_TORSO;
    case 3: return CHAMPION_SLOT_ACTION_HAND;
    case 4: return CHAMPION_SLOT_LEGS;
    case 5: return CHAMPION_SLOT_FEET;
    default: return -1;
    }
}

static int m11_defender_armour_defense_for_thing(
    const struct GameWorld_Compat* world,
    unsigned short thing,
    int useSharpDefense,
    int* outDefense,
    int* outIsShield,
    int* outWeight)
{
    int thingIndex;
    int armourType;

    if (outDefense) *outDefense = 0;
    if (outIsShield) *outIsShield = 0;
    if (outWeight) *outWeight = 0;
    if (!world || !world->things || !world->things->armours ||
        !outDefense) {
        return 0;
    }
    if (thing == THING_NONE || thing == THING_ENDOFLIST ||
        THING_GET_TYPE(thing) != THING_TYPE_ARMOUR) {
        return 0;
    }
    thingIndex = (int)THING_GET_INDEX(thing);
    if (thingIndex < 0 || thingIndex >= world->things->armourCount) {
        return 0;
    }
    armourType = (int)world->things->armours[thingIndex].type;
    return m11_dm1_armour_defense_f0143(
        armourType, useSharpDefense, outDefense, outIsShield, outWeight);
}

static int m11_f0312_stamina_adjusted_value(
    const struct ChampionState_Compat* champion,
    int value)
{
    int currentStamina;
    int halfMaximumStamina;
    if (!champion) return value;
    currentStamina = (int)champion->stamina.current;
    halfMaximumStamina = (int)champion->stamina.maximum >> 1;
    /* ReDMCSB CHAMPION.C F0306:1078-1100 BUGX_XX. DM1 PC 3.4's Turbo
     * C++ 1.01 evaluates the scaled operand from the pre-shift value. */
    return F0306_CHAMPION_GetStaminaAdjustedValuePc34_Compat(
        currentStamina, halfMaximumStamina, value);
}

static int m11_f0312_hand_strength_baseline(
    const struct ChampionState_Compat* champion,
    int handWoundIndex,
    int objectWeight)
{
    int strength;
    int maxLoad;
    int oneSixteenthMaximumLoad;
    int loadThreshold;

    if (!champion) return 0;

    /* ReDMCSB CHAMPION.C F0312 lines 1264-1306 starts with RANDOM(16)
     * plus current strength, adjusts for held-object weight, stamina, and
     * hand wounds, then returns bounded strength >> 1.  M11 projectile
     * defender snapshots keep the same non-random baseline as M10. */
    strength = (int)champion->attributes[CHAMPION_ATTR_STRENGTH];
    maxLoad = (int)champion->maxLoad;
    if (maxLoad <= 0) {
        maxLoad = (strength << 3) + 100;
    }
    oneSixteenthMaximumLoad = maxLoad >> 4;
    if (objectWeight <= oneSixteenthMaximumLoad) {
        strength += objectWeight - 12;
    } else {
        loadThreshold =
            oneSixteenthMaximumLoad + ((oneSixteenthMaximumLoad - 12) >> 1);
        if (objectWeight <= loadThreshold) {
            strength += (objectWeight - oneSixteenthMaximumLoad) >> 1;
        } else {
            strength -= (objectWeight - loadThreshold) << 1;
        }
    }
    strength = m11_f0312_stamina_adjusted_value(champion, strength);
    if ((champion->wounds & (1u << handWoundIndex)) != 0) {
        strength >>= 1;
    }
    strength >>= 1;
    if (strength < 0) return 0;
    if (strength > 100) return 100;
    return strength;
}

static void m11_fill_defender_wound_defense_baseline(
    const struct GameWorld_Compat* world,
    const struct ChampionState_Compat* champion,
    int useSharpDefense,
    struct CombatantChampionSnapshot_Compat* outChampion)
{
    static const int s_woundDefenseFactor[6] = { 5, 5, 4, 6, 3, 1 };
    int woundIndex;

    if (!world || !champion || !outChampion) return;

    for (woundIndex = 0; woundIndex < 6; ++woundIndex) {
        int inventorySlot;
        int bodyDefense = 0;
        int ignoredShield = 0;
        int baseline = 0;

        /* ReDMCSB CHAMPION.C F0313 lines 1336-1346: shields in
         * ready/action hands contribute F0312 hand strength plus armour
         * defense, weighted by the target wound slot. */
        {
            static const int s_handSlots[2] = {
                CHAMPION_SLOT_HAND_LEFT,
                CHAMPION_SLOT_ACTION_HAND
            };
            static const int s_handWoundIndexes[2] = { 0, 3 };
            int hand;
            for (hand = 0; hand < 2; ++hand) {
                int shieldDefense = 0;
                int isShield = 0;
                int shieldWeight = 0;
                if (m11_defender_armour_defense_for_thing(
                        world, champion->inventory[s_handSlots[hand]],
                        useSharpDefense,
                        &shieldDefense, &isShield, &shieldWeight) &&
                    isShield) {
                    int handStrength =
                        m11_f0312_hand_strength_baseline(
                            champion, s_handWoundIndexes[hand], shieldWeight);
                    baseline +=
                        ((handStrength + shieldDefense) *
                         s_woundDefenseFactor[woundIndex]) >>
                        ((s_handWoundIndexes[hand] == woundIndex) ? 4 : 5);
                }
            }
        }

        inventorySlot =
            m11_defender_inventory_slot_for_wound_index(woundIndex);
        if (inventorySlot >= 0 && inventorySlot < CHAMPION_SLOT_COUNT &&
            woundIndex != 0 && woundIndex != 3 &&
            m11_defender_armour_defense_for_thing(
                world, champion->inventory[inventorySlot], useSharpDefense,
                &bodyDefense, &ignoredShield, NULL)) {
            /* ReDMCSB CHAMPION.C F0313 lines 1355-1361 adds body-slot
             * armour defense for wound slots past the two hand slots. */
            baseline += bodyDefense;
        }
        outChampion->woundDefense[woundIndex] = baseline;
    }
}

static int m11_build_projectile_defender_champion_snapshot(
    const struct GameWorld_Compat* world,
    int championIndex,
    int attackType,
    struct CombatantChampionSnapshot_Compat* outChampion)
{
    const struct ChampionState_Compat* champion;

    if (!world || !outChampion) return 0;
    memset(outChampion, 0, sizeof(*outChampion));
    if (championIndex < 0 || championIndex >= CHAMPION_MAX_PARTY) return 0;
    champion = &world->party.champions[championIndex];
    if (!champion->present || champion->hp.current == 0) return 0;

    outChampion->championIndex = championIndex;
    outChampion->currentHealth = champion->hp.current;
    outChampion->dexterity = champion->attributes[CHAMPION_ATTR_DEXTERITY];
    outChampion->skillLevelParry = F0888_ORCH_GetChampionF0303SkillLevel_Compat(
        world, championIndex, DM1_SKILL_IDX_PARRY);
    outChampion->statisticVitality = champion->attributes[CHAMPION_ATTR_VITALITY];
    outChampion->statisticAntifire = champion->attributes[CHAMPION_ATTR_ANTIFIRE];
    outChampion->statisticAntimagic = champion->attributes[CHAMPION_ATTR_ANTIMAGIC];
    outChampion->statisticWisdom = champion->attributes[CHAMPION_ATTR_WISDOM];
    outChampion->statisticLuck = (int)world->lifecycle.champions[championIndex]
        .statistics[LIFECYCLE_STAT_LUCK][LIFECYCLE_STAT_CURRENT];
    outChampion->statisticLuckMax = (int)world->lifecycle.champions[championIndex]
        .statistics[LIFECYCLE_STAT_LUCK][LIFECYCLE_STAT_MAXIMUM];
    outChampion->statisticLuckMin = (int)world->lifecycle.champions[championIndex]
        .statistics[LIFECYCLE_STAT_LUCK][LIFECYCLE_STAT_MINIMUM];
    outChampion->wounds = champion->wounds;
    m11_fill_defender_wound_defense_baseline(
        world, champion, attackType == COMBAT_ATTACK_SHARP, outChampion);
    outChampion->isResting =
        world->partyIsResting || world->lifecycle.rest.isResting;

    /* ReDMCSB CHAMPION.C F0321 lines 1878-1888 subtracts the
     * attack-specific party spell/fire shield before the common
     * F0313 body-defense scale.  For physical/lightning projectile
     * paths, fold action defense plus lifecycle/party shield defense into
     * the F0313 snapshot, matching the M10 dispatcher. */
    if (attackType == COMBAT_ATTACK_MAGIC) {
        outChampion->partyShieldDefense = world->magic.spellShieldDefense;
    } else if (attackType == COMBAT_ATTACK_FIRE) {
        outChampion->partyShieldDefense = world->magic.fireShieldDefense;
    } else {
        outChampion->partyShieldDefense =
            champion->actionDefense +
            world->lifecycle.champions[championIndex].shieldDefense +
            world->magic.partyShieldDefense;
    }
    return 1;
}

static void m11_writeback_champion_luck_from_snapshot(
    struct GameWorld_Compat* world,
    int championIndex,
    const struct CombatantChampionSnapshot_Compat* snapshot)
{
    int luck;
    if (!world || !snapshot) return;
    if (championIndex < 0 || championIndex >= CHAMPION_MAX_PARTY) return;
    luck = snapshot->statisticLuck;
    if (luck < 0) luck = 0;
    if (luck > 255) luck = 255;
    world->lifecycle.champions[championIndex]
        .statistics[LIFECYCLE_STAT_LUCK][LIFECYCLE_STAT_CURRENT] =
            (uint8_t)luck;
}

static int m11_dm1_behavior_from_ai_state(int stateKind)
{
    switch (stateKind) {
        case AI_STATE_ATTACK: return DM1_BEHAVIOR_ATTACK;
        case AI_STATE_FLEE: return DM1_BEHAVIOR_FLEE;
        case AI_STATE_APPROACH: return DM1_BEHAVIOR_APPROACH;
        case AI_STATE_IDLE:
        case AI_STATE_WANDER:
        default:
            return DM1_BEHAVIOR_WANDER;
    }
}

static void m11_schedule_creature_reaction_f0209(
    M11_GameViewState* state,
    int groupIndex,
    const struct DungeonGroup_Compat* group,
    int mapIndex,
    int mapX,
    int mapY,
    int reactionType)
{
    int aiIndex;
    int ticksSinceLastMove = 0;
    const struct CreatureBehaviorProfile_Compat* profile;
    struct DM1GroupBehaviorContext_Compat ctx;
    struct DM1ActiveGroup_Compat activeGroup;
    struct DM1BehaviorResult_Compat behavior;
    struct DM1BehaviorReactionSchedulePlan_Compat schedulePlan;
    struct TimelineEvent_Compat reaction;
    if (!state || !group || groupIndex < 0) return;

    memset(&ctx, 0, sizeof(ctx));
    memset(&activeGroup, 0, sizeof(activeGroup));
    memset(&behavior, 0, sizeof(behavior));
    memset(&schedulePlan, 0, sizeof(schedulePlan));

    aiIndex = m11_find_creature_ai_on_square(state, mapIndex, mapX, mapY);
    profile = CREATURE_GetProfile_Compat((int)group->creatureType);
    ctx.currentMapIndex = mapIndex;
    ctx.currentGroupMapX = mapX;
    ctx.currentGroupMapY = mapY;
    ctx.partyMapIndex = state->world.party.mapIndex;
    ctx.partyMapX = state->world.party.mapX;
    ctx.partyMapY = state->world.party.mapY;
    ctx.partyChampionCount = state->world.party.championCount;
    ctx.creatureType = (int)group->creatureType;
    ctx.groupBehavior = (aiIndex >= 0)
        ? m11_dm1_behavior_from_ai_state(state->world.creatureAI[aiIndex].stateKind)
        : (int)group->behavior;
    ctx.creatureCount = group->count;
    ctx.movementTicks = profile ? profile->movementTicks : 1;
    if (ctx.movementTicks < 1) ctx.movementTicks = 1;
    if (aiIndex >= 0 && state->world.creatureAI[aiIndex].lastSeenPartyTick >= 0) {
        ticksSinceLastMove = (int)state->world.gameTick -
            state->world.creatureAI[aiIndex].lastSeenPartyTick;
        if (ticksSinceLastMove < 0) ticksSinceLastMove = 0;
    }
    ctx.ticksSinceLastMove = ticksSinceLastMove;
    ctx.currentTickLow = (int)state->world.gameTick;
    ctx.eventType = reactionType;
    ctx.eventTicks = (int)state->world.gameTick;

    activeGroup.groupThingIndex = groupIndex;
    activeGroup.cells = group->cells;
    activeGroup.directions = group->direction;
    activeGroup.lastMoveTime = (aiIndex >= 0)
        ? state->world.creatureAI[aiIndex].lastSeenPartyTick : 0;
    activeGroup.priorMapX = mapX;
    activeGroup.priorMapY = mapY;

    if (!F0810_DM1_GROUP_DispatchBehavior_Compat(
            &ctx, &activeGroup, &state->world.masterRng, &behavior)) {
        return;
    }
    if (!F0810c_DM1_GROUP_PlanReactionSchedule_Compat(
            &behavior, groupIndex, (int)group->creatureType,
            mapIndex, mapX, mapY, state->world.gameTick, &schedulePlan) ||
        !schedulePlan.shouldSchedule) {
        return;
    }

    memset(&reaction, 0, sizeof(reaction));
    reaction.kind = TIMELINE_EVENT_CREATURE_REACTION;
    reaction.fireAtTick = schedulePlan.fireAtTick;
    reaction.mapIndex = schedulePlan.mapIndex;
    reaction.mapX = schedulePlan.mapX;
    reaction.mapY = schedulePlan.mapY;
    reaction.aux0 = schedulePlan.groupIndex;
    reaction.aux1 = schedulePlan.creatureType;
    reaction.aux2 = schedulePlan.eventType;
    (void)F0721_TIMELINE_Schedule_Compat(&state->world.timeline, &reaction);
}

static void m11_schedule_projectile_hit_creature_reaction(
    M11_GameViewState* state,
    int groupIndex,
    const struct DungeonGroup_Compat* group,
    int mapIndex,
    int mapX,
    int mapY)
{
    m11_schedule_creature_reaction_f0209(state, groupIndex, group,
                                         mapIndex, mapX, mapY,
                                         DM1_CM2_REACTION_HIT_BY_PROJECTILE);
}

static int m11_maybe_apply_projectile_poison_to_champion(
    M11_GameViewState* state,
    int championIndex,
    struct ChampionState_Compat* champion,
    const DM1_ProjectileChampionImpactPlanPc34* impactPlan,
    const struct ProjectileInstance_Compat* projectile,
    int appliedDamage) {
    DM1_ProjectileChampionPoisonApplyPlanPc34 poisonApply;
    int rng2;
    if (!state || !champion || !impactPlan || !projectile) return 0;
    if (championIndex < 0 || championIndex >= CHAMPION_MAX_PARTY) return 0;
    rng2 = F0732_COMBAT_RngRandom_Compat(&state->world.masterRng, 2);
    if (!dm1_v1_projectile_champion_poison_apply_pc34(
            impactPlan, projectile, appliedDamage, rng2,
            state->world.gameTick, state->world.partyMapIndex,
            state->world.party.mapX, state->world.party.mapY,
            champion, &poisonApply) ||
        !poisonApply.shouldApply) {
        return 0;
    }

    if (poisonApply.schedulePoisonEvent) {
        (void)F0721_TIMELINE_Schedule_Compat(&state->world.timeline,
                                             &poisonApply.poisonEvent);
        if (poisonApply.incrementPoisonEventCount &&
            state->world.lifecycle.champions[championIndex].poisonEventCount
            < 255) {
            state->world.lifecycle.champions[championIndex].poisonEventCount++;
        }
    }
    return 1;
}

/* Apply bounded V1 impact side-effects: explosion spawn, creature
 * damage, champion damage, and DM1-style log cue.  Designed to
 * touch only data the M10 layer already owns (world.explosions via
 * F0821, world.things->groups via F0738, party champion HP direct
 * write) and to NEVER edit M10 code paths.  Returns nothing. */
static void m11_projectile_apply_impact(
    M11_GameViewState* state,
    const struct ProjectileInstance_Compat* p,
    const struct ProjectileTickResult_Compat* r) {
    const char* name = dm1_v1_projectile_subtype_name_pc34(
        p->projectileSubtype);
    int sourceSoundIndex =
        dm1_v1_projectile_impact_source_sound_index_pc34(p, r);
    int associatedThingMovedToGroup = 0;
    if (sourceSoundIndex >= 0) {
        m11_audio_emit_source_sound(state, sourceSoundIndex,
                                    M11_Audio_FallbackMarkerForSoundIndex(sourceSoundIndex));
    }
    m11_schedule_open_door_spell_toggle(state, r);
    m11_schedule_projectile_door_destruction(state, r);
    (void)m11_maybe_consume_thrown_potion_on_impact(state, p, r);
    if (m11_maybe_heal_black_flame_from_fireball(state, p, r)) {
        return;
    }

    {
        struct ExplosionCreateInput_Compat eIn;
        if (dm1_v1_projectile_explosion_create_input_pc34(
                r, (int)state->world.gameTick, &eIn)) {
            struct TimelineEvent_Compat eFirst;
            int eSlot = -1;
            (void)F0821_EXPLOSION_Create_Compat(
                &eIn, &state->world.explosions, &eSlot, &eFirst);
        }
    }

    /* Apply damage on HIT_CREATURE to the DungeonGroup at the impact
     * cell. ReDMCSB PROJEXPL.C:F0217 lines 515-523 resolves the concrete
     * creature with F0176_GROUP_GetCreatureOrdinalInCell before applying
     * F0190 damage, so M11 must use the F0811 target cell rather than a
     * first-living-creature fallback. */
    if (r->resultKind == PROJECTILE_RESULT_HIT_CREATURE
            && r->emittedCombatAction) {
        int impactMap = r->newMapIndex;
        int impactX = r->newMapX;
        int impactY = r->newMapY;
        /* ReDMCSB PROJEXPL.C F0219 lines 687-697 and 717-743 carry
         * real projectile target coordinates through the event; (0,0)
         * is a valid map cell, not a missing-coordinate sentinel. */
        unsigned short groupThing = m11_find_group_on_square(
            &state->world, impactMap, impactX, impactY);
        if (groupThing != THING_NONE && groupThing != THING_ENDOFLIST
                && state->world.things) {
            int gIdx = THING_GET_INDEX(groupThing);
            if (gIdx >= 0 && gIdx < state->world.things->groupCount) {
                struct DungeonGroup_Compat* g = &state->world.things->groups[gIdx];
                const struct CreatureBehaviorProfile_Compat* profile =
                    CREATURE_GetProfile_Compat((int)g->creatureType);
                int creatureAttributes = profile ? profile->attributes : 0;
                DM1_ProjectileCreatureActionPlanPc34 actionPlan;
                DM1_ProjectileCreatureActionApplyPlanPc34 actionApply;
                DM1_ProjectileCreatureImpactAftermathPc34 aftermath;
                memset(&actionPlan, 0, sizeof(actionPlan));
                memset(&actionApply, 0, sizeof(actionApply));
                memset(&aftermath, 0, sizeof(aftermath));
                if (dm1_v1_projectile_creature_action_plan_pc34(
                        p, &r->outAction, g, creatureAttributes, &actionPlan) &&
                    actionPlan.healsBlackFlame) {
                        g->health[actionPlan.slotIndex] =
                            (unsigned short)actionPlan.newHealth;
                        m11_write_raw_group_record(state->world.things, gIdx);
                        m11_log_event(state, M11_COLOR_ORANGE,
                                      "T%u: FIREBALL FEEDS %s",
                                      (unsigned int)state->world.gameTick,
                                      m11_creature_name((int)g->creatureType));
                        (void)m11_materialize_projectile_associated_thing(
                            state, p, r, 0);
                        return;
                }
                if (actionPlan.handled && actionPlan.shouldApplyDamage) {
                        if (!dm1_v1_projectile_creature_action_apply_pc34(
                                &actionPlan, g, &actionApply) ||
                            !actionApply.handled) {
                            return;
                        }
                        (void)dm1_v1_projectile_creature_action_aftermath_pc34(
                            &actionPlan, p, creatureAttributes, (int)g->behavior,
                            actionApply.outcomeCode,
                            m11_projectile_associated_weapon_type(state, p),
                            &aftermath);
                        if (aftermath.cleanupEventsAndFear) {
                                m11_cleanup_f0190_creature_events(
                                    state, impactMap, impactX, impactY,
                                    actionPlan.slotIndex);
                                (void)m11_apply_f0190_fear(
                                    state, g, actionPlan.originalCreatureType, gIdx,
                                    actionPlan.slotIndex,
                                    actionPlan.originalGroupCount,
                                    impactMap, impactX, impactY);
                        }
                        if (aftermath.dropFixedPossessions) {
                            (void)m11_apply_f0190_projectile_possession_drops(
                                state, actionPlan.originalCreatureType,
                                creatureAttributes, actionPlan.killedCell,
                                impactMap, impactX, impactY,
                                actionApply.outcomeCode);
                        }
                        if (aftermath.spawnDeathSmoke &&
                            actionApply.outcomeCode !=
                                COMBAT_OUTCOME_KILLED_ALL_CREATURES) {
                            /* ReDMCSB GROUP.C F0190:892-916 compacts a
                             * surviving group before its C040. The all-kill
                             * branch defers C040 to the F0188/F0189 route
                             * below, where event deletion can free its
                             * source timeline slot first. */
                            (void)m11_spawn_f0190_death_smoke(
                                state, actionPlan.originalCreatureType,
                                actionPlan.killedCell, impactMap, impactX,
                                impactY);
                        }
                        if (aftermath.scheduleReaction) {
                            m11_schedule_projectile_hit_creature_reaction(
                                state, gIdx, g, impactMap, impactX, impactY);
                        }
                        if (aftermath.keepSharpWeaponInGroup) {
                            associatedThingMovedToGroup =
                                m11_attach_projectile_associated_thing_to_group(
                                    state, g, p);
                        }
                        /* ReDMCSB PROJEXPL.C:F0217 lines 515-539 reaches
                         * GROUP.C:F0190 for creature projectile damage. Keep
                         * M11's raw DUNGEON.DAT group record in step with
                         * decoded HP/cells/count/slot mutations before any
                         * later viewport/save/export path can resample it. */
                        m11_write_raw_group_record(state->world.things, gIdx);
                }
                m11_log_event(state, M11_COLOR_LIGHT_RED,
                              "T%u: %s HITS %s",
                              (unsigned int)state->world.gameTick,
                              name,
                              m11_creature_name((int)g->creatureType));
                /* Check if the group is dead after projectile damage */
                (void)m11_check_group_death_and_drop(
                    state, groupThing, impactMap, impactX, impactY,
                    actionPlan.killedCell,
                    aftermath.spawnDeathSmoke &&
                        actionApply.outcomeCode ==
                            COMBAT_OUTCOME_KILLED_ALL_CREATURES);
                m11_write_raw_group_record(state->world.things, gIdx);
                (void)m11_materialize_projectile_associated_thing(
                    state, p, r, associatedThingMovedToGroup);
                return;
            }
        }
        m11_log_event(state, M11_COLOR_LIGHT_RED,
                      "T%u: %s STRIKES CREATURE",
                      (unsigned int)state->world.gameTick, name);
        (void)m11_materialize_projectile_associated_thing(state, p, r, 0);
        return;
    }

    if (r->resultKind == PROJECTILE_RESULT_HIT_CHAMPION
            && r->emittedCombatAction) {
        DM1_ProjectileChampionImpactPlanPc34 impactPlan;
        int ci = r->outAction.defenderSlotOrCreatureIndex;
        int championPresent = (ci >= 0 && ci < CHAMPION_MAX_PARTY &&
                               state->world.party.champions[ci].present);
        memset(&impactPlan, 0, sizeof(impactPlan));
        (void)dm1_v1_projectile_champion_impact_plan_pc34(
            p, r, championPresent, &impactPlan);
        if (impactPlan.handled && impactPlan.championPresent &&
            impactPlan.championIndex >= 0 &&
            impactPlan.championIndex < CHAMPION_MAX_PARTY) {
            struct CombatantChampionSnapshot_Compat defender;
            DM1_ProjectileChampionDamageApplyPlanPc34 damagePlan;
            ci = impactPlan.championIndex;

            /* ReDMCSB PROJEXPL.C F0217 lines 513-558 routes champion
             * projectile impact through F0321, which applies attack-type
             * defense, wounds, shields, armour, and vitality before HP is
             * changed; CHAMPION.C F0321 lines 1842-1900 contains the
             * scaling path. */
            memset(&damagePlan, 0, sizeof(damagePlan));
            if (m11_build_projectile_defender_champion_snapshot(
                    &state->world, ci, impactPlan.attackTypeCode,
                    &defender)) {
                (void)dm1_v1_projectile_champion_damage_apply_pc34(
                    &impactPlan,
                    &defender,
                    &state->world.masterRng,
                    &state->world.party.champions[ci],
                    &damagePlan);
            }
            /* ReDMCSB PROJEXPL.C F0217 lines 545-556 applies poison only
             * after F0321 returns applied damage and the source random gate
             * passes. */
            (void)m11_maybe_apply_projectile_poison_to_champion(
                state, ci, &state->world.party.champions[ci],
                &impactPlan, p, damagePlan.scaledAttack);
            /* CHAMPION.C lines 1659-1667 sets G0303_B_PartyDead when the
             * final party champion reaches zero HP; mirror that M11 gate
             * for direct F0811 projectile advances that bypass F0884. */
            if (dm1_v1_projectile_champion_party_death_check_pc34(
                    damagePlan.killed,
                    (int)state->world.party.champions[ci].hp.current)) {
                m11_check_party_death(state);
            }
            m11_log_event(state, M11_COLOR_LIGHT_RED,
                          "T%u: %s HITS PARTY FOR %d",
                          (unsigned int)state->world.gameTick, name,
                          damagePlan.scaledAttack);
        } else {
            m11_log_event(state, M11_COLOR_LIGHT_RED,
                          "T%u: %s HITS PARTY",
                          (unsigned int)state->world.gameTick, name);
        }
        /* ReDMCSB PROJEXPL.C:F0219 commits a cross-cell champion hit to
         * the resolved projectile square before F0217 reaches F0215. */
        (void)m11_materialize_projectile_associated_thing(
            state, p, r, 0);
        return;
    }

    {
        DM1_ProjectileImpactLogPlanPc34 logPlan;
        if (dm1_v1_projectile_impact_log_plan_pc34(r, &logPlan) &&
            logPlan.handled) {
            switch (logPlan.logKind) {
                case DM1_PROJECTILE_IMPACT_LOG_HIT_WALL_PC34:
                    m11_log_event(state, M11_COLOR_YELLOW,
                                  "T%u: %s HITS WALL",
                                  (unsigned int)state->world.gameTick, name);
                    break;
                case DM1_PROJECTILE_IMPACT_LOG_HIT_DOOR_PC34:
                    m11_log_event(state, M11_COLOR_YELLOW,
                                  "T%u: %s HITS DOOR",
                                  (unsigned int)state->world.gameTick, name);
                    break;
                case DM1_PROJECTILE_IMPACT_LOG_HIT_FLUXCAGE_PC34:
                    m11_log_event(state, M11_COLOR_MAGENTA,
                                  "T%u: %s ABSORBED BY FLUXCAGE",
                                  (unsigned int)state->world.gameTick, name);
                    break;
                case DM1_PROJECTILE_IMPACT_LOG_HIT_OTHER_PROJECTILE_PC34:
                    m11_log_event(state, M11_COLOR_LIGHT_CYAN,
                                  "T%u: %s COLLIDES IN FLIGHT",
                                  (unsigned int)state->world.gameTick, name);
                    break;
                case DM1_PROJECTILE_IMPACT_LOG_DESPAWN_ENERGY_PC34:
                    m11_log_event(state, M11_COLOR_DARK_GRAY,
                                  "T%u: %s FADES",
                                  (unsigned int)state->world.gameTick, name);
                    break;
                case DM1_PROJECTILE_IMPACT_LOG_DESPAWN_BOUNDS_PC34:
                    m11_log_event(state, M11_COLOR_DARK_GRAY,
                                  "T%u: %s OUT OF BOUNDS",
                                  (unsigned int)state->world.gameTick, name);
                    break;
                default:
                    break;
            }
        }
    }
    (void)m11_materialize_projectile_associated_thing(state, p, r, 0);
}

/* Public per-tick advance: iterate live projectiles, drive F0811
 * once per projectile whose scheduled tick has arrived, apply the
 * new state or despawn + impact side-effects.  Called from
 * M11_GameView_ProcessTickEmissions so every orchestrator tick
 * (movement, attack, rest, action menu) steps active projectiles
 * through the world exactly once.  Idempotent on empty lists. */
static void m11_advance_projectiles_v1(M11_GameViewState* state,
                                       int allowM10OwnedProbeAdvance) {
    int i;
    uint32_t now;
    if (!state || !state->active) return;
    /* No dungeon = no reliable cell-content digest.  This is the
     * case for probe harnesses that exercise action-menu dispatch
     * without wiring a full dungeon; for those the correct V1
     * behaviour is to leave projectile slots undisturbed so the
     * probe can still verify spawn side-effects.  In real gameplay
     * the dungeon is always loaded before projectiles can fire. */
    if (!state->world.dungeon || !state->world.dungeon->tilesLoaded) return;
    now = state->world.gameTick;

    for (i = 0; i < PROJECTILE_LIST_CAPACITY; ++i) {
        struct ProjectileInstance_Compat* p = &state->world.projectiles.entries[i];
        struct ProjectileInstance_Compat newState;
        struct ProjectileTickResult_Compat result;
        struct CellContentDigest_Compat digest;

        if (!m11_projectile_instance_active(p)) continue;
        if ((uint32_t)p->scheduledAtTick > now) continue;
        if (!allowM10OwnedProbeAdvance &&
            m11_projectile_has_m10_move_owner(state, i)) continue;

        if (!m11_build_projectile_digest(&state->world, p, i, &digest)) {
            /* Can't classify the digest this tick (e.g. transient
             * dungeon state).  Skip rather than despawn so the slot
             * stays visible and can be advanced on a later tick. */
            continue;
        }

        if (!F0811_PROJECTILE_Advance_Compat(p, &digest, now,
                                             &state->world.masterRng,
                                             &newState, &result)) {
            m11_delete_projectile_move_events_after_impact(state, i);
            F0813_PROJECTILE_Despawn_Compat(&state->world.projectiles, i);
            continue;
        }

        if (result.despawn) {
            /* Apply impact side effects (explosion, damage, log cue)
             * before freeing the slot so the cue references the
             * right projectile type. */
            m11_projectile_apply_impact(state, p, &result);
            if (result.resultKind == PROJECTILE_RESULT_HIT_OTHER_PROJECTILE) {
                int otherIndex = m11_find_projectile_collision_peer(
                    &state->world, p, i, &digest);
                if (otherIndex >= 0) {
                    struct ProjectileInstance_Compat* other =
                        &state->world.projectiles.entries[otherIndex];
                    /* Phase17 v1 §4.6 makes projectile-vs-projectile
                     * annihilation order-independent: both live projectile
                     * slots are consumed. */
                    (void)m11_materialize_projectile_associated_thing(
                        state, other, &result, 0);
                    m11_delete_projectile_move_events_after_impact(
                        state, otherIndex);
                    (void)F0813_PROJECTILE_Despawn_Compat(
                        &state->world.projectiles, otherIndex);
                }
            }
            m11_delete_projectile_move_events_after_impact(state, i);
            F0813_PROJECTILE_Despawn_Compat(&state->world.projectiles, i);
        } else {
            /* Commit the flown state.  F0811 fills outNewState with
             * the updated cell/map/direction/energy; we also advance
             * scheduledAtTick per F0825 semantics (1 tick on party
             * map, 3 ticks off-map).  The timeline queue itself is
             * untouched — M10 policy. */
            newState.scheduledAtTick = (int)now +
                ((newState.mapIndex == (int)state->world.partyMapIndex) ? 1 : 3);
            *p = newState;
        }
    }
}

/* Probe-visible wrapper so game_view_probe.c can drive the advance
 * deterministically without needing to replay an orchestrator tick. */
void M11_GameView_AdvanceProjectilesOnce(M11_GameViewState* state) {
    m11_advance_projectiles_v1(state, 1);
}

/* Build a CellContentDigest_Compat for an explosion's current cell so
 * F0822_EXPLOSION_Advance_Compat can classify champion / creature-group
 * presence and door state at the AoE target square.  Returns 1 on
 * success.  Mirrors m11_build_projectile_digest but centred on the
 * explosion's cell (source == dest for a stationary explosion). */
static int m11_build_explosion_digest(
    const struct GameWorld_Compat* world,
    const struct ExplosionInstance_Compat* e,
    struct CellContentDigest_Compat* out) {
    unsigned char sq = 0;
    int hasSquare = 0;
    int i;
    if (!world || !e || !out) return 0;
    if (!world->dungeon || e->mapIndex < 0
        || e->mapIndex >= (int)world->dungeon->header.mapCount) return 0;
    /* Explosions can land on wall / boundary cells (projectile
     * detonation on impact with a wall), so a missing squareByte is
     * fine — classify as a wall-cell burst and let F0822 run with a
     * minimal digest.  Matches ReDMCSB where a fireball bursting on
     * a wall still progresses through F0822's frame logic. */
    hasSquare = m11_get_square_byte(world, e->mapIndex, e->mapX, e->mapY, &sq);

    memset(out, 0, sizeof(*out));
    out->sourceMapIndex    = e->mapIndex;
    out->sourceMapX        = e->mapX;
    out->sourceMapY        = e->mapY;
    out->sourceSquareType  = hasSquare ? ((sq >> 5) & 7) : PROJECTILE_ELEMENT_WALL;
    out->destMapIndex      = e->mapIndex;
    out->destMapX          = e->mapX;
    out->destMapY          = e->mapY;
    out->destSquareType    = hasSquare ? ((sq >> 5) & 7) : PROJECTILE_ELEMENT_WALL;
    out->destIsMapBoundary = hasSquare ? 0 : 1;
    out->destTeleporterNewDirection = -1;
    if (!hasSquare) {
        /* Off-map / unreadable cell: no champion, no creature, no door;
         * just let F0822 despawn a one-shot or decay a persistent type. */
        return 1;
    }

    if (out->destSquareType == PROJECTILE_ELEMENT_DOOR) {
        int doorAttr = sq & 0x07;
        if (doorAttr == 0) {
            out->destDoorState = PROJECTILE_DOOR_STATE_OPEN;
        } else if (doorAttr <= 4) {
            out->destDoorState = doorAttr;
        } else if (doorAttr == 5) {
            out->destDoorState = PROJECTILE_DOOR_STATE_DESTROYED;
        } else {
            out->destDoorState = PROJECTILE_DOOR_STATE_NONE;
        }
    } else {
        out->destDoorState = PROJECTILE_DOOR_STATE_NONE;
    }

    /* Party presence on the explosion cell. */
    if (world->party.mapIndex == e->mapIndex
            && world->party.mapX == e->mapX
            && world->party.mapY == e->mapY) {
        out->destChampionCellMask = m11_party_champion_cell_mask(world);
        out->destHasChampion = out->destChampionCellMask ? 1 : 0;
        out->destPartyDirection = world->party.direction & 3;
    }

    /* Creature group on the explosion cell. */
    for (i = 0; i < world->creatureAICount
                && i < GAMEWORLD_CREATURE_AI_CAPACITY; ++i) {
        const struct CreatureAIState_Compat* ai = &world->creatureAI[i];
        if (ai->groupMapIndex == e->mapIndex
                && ai->groupMapX == e->mapX
                && ai->groupMapY == e->mapY) {
            const struct CreatureBehaviorProfile_Compat* profile =
                CREATURE_GetProfile_Compat(ai->creatureType);
            out->destHasCreatureGroup = 1;
            out->destCreatureType     = ai->creatureType;
            out->destCreatureCellMask = 0x0F;
            out->destCreatureIsNonMaterial = (profile != NULL)
                && ((profile->attributes
                     & CREATURE_ATTR_MASK_NON_MATERIAL) != 0);
            break;
        }
    }

    return 1;
}

/* Apply the per-frame combat actions that F0822 emitted for this
 * explosion advance.  Mirrors the bounded V1 damage path used for
 * projectile impacts: champion HP direct write for party hits and the DM1
 * F0220 group-apply receipt for creature-group hits.
 * Pure data mutation, no M10 edits. */
static void m11_explosion_apply_tick_result(
    M11_GameViewState* state,
    const struct ExplosionInstance_Compat* e,
    const struct ExplosionTickResult_Compat* r) {
    const char* typeName = "EXPLOSION";
    if (e->explosionType == C000_EXPLOSION_FIREBALL)           typeName = "FIREBALL";
    else if (e->explosionType == C002_EXPLOSION_LIGHTNING_BOLT) typeName = "LIGHTNING";
    else if (e->explosionType == C007_EXPLOSION_POISON_CLOUD)   typeName = "POISON CLOUD";
    else if (e->explosionType == C040_EXPLOSION_SMOKE)          typeName = "SMOKE";

    /* Champion damage. */
    if (r->emittedCombatActionPartyCount > 0) {
        int ci = r->outActionParty.defenderSlotOrCreatureIndex;
        int dmg = r->outActionParty.rawAttackValue;
        if (ci >= 0 && ci < CHAMPION_MAX_PARTY
                && state->world.party.champions[ci].present) {
            int hp = (int)state->world.party.champions[ci].hp.current;
            if (dmg < 0) dmg = 0;
            if (dmg > hp) dmg = hp;
            state->world.party.champions[ci].hp.current =
                (unsigned short)(hp - dmg);
            m11_log_event(state, M11_COLOR_LIGHT_RED,
                          "T%u: %s BURNS PARTY FOR %d",
                          (unsigned int)state->world.gameTick,
                          typeName, dmg);
        }
    }

    /* Creature group damage. */
    if (r->emittedCombatActionGroupCount > 0 && state->world.things) {
        unsigned short groupThing = m11_find_group_on_square(
            &state->world,
            r->outActionGroup.targetMapIndex,
            r->outActionGroup.targetMapX,
            r->outActionGroup.targetMapY);
        if (groupThing != THING_NONE && groupThing != THING_ENDOFLIST) {
            int gIdx = THING_GET_INDEX(groupThing);
            if (gIdx >= 0 && gIdx < state->world.things->groupCount) {
                struct DungeonGroup_Compat* g = &state->world.things->groups[gIdx];
                DM1_ExplosionGroupApplyPlanPc34 applyPlan;
                memset(&applyPlan, 0, sizeof(applyPlan));
                (void)dm1_v1_explosion_group_apply_pc34(
                    &r->outActionGroup, g, &applyPlan);
                m11_log_event(state, M11_COLOR_LIGHT_RED,
                              "T%u: %s SEARS %s",
                              (unsigned int)state->world.gameTick,
                              typeName,
                              m11_creature_name((int)g->creatureType));
                /* Check if the group is dead after melee/explosion damage */
                (void)m11_check_group_death_and_drop(
                    state, groupThing,
                    r->outActionGroup.targetMapIndex >= 0
                        ? r->outActionGroup.targetMapIndex
                        : state->world.party.mapIndex,
                    r->outActionGroup.targetMapX,
                    r->outActionGroup.targetMapY,
                    r->outActionGroup.targetCell,
                    1);
            }
        }
    }
}

/* Keep an M11 C040 projection and its original PC34 C15 owner in one
 * lifecycle. Persistent smoke rewrites C15.Attack; despawn unlinks the exact
 * cell-bearing Thing through F0515. A source fingerprint must never become
 * an orphaned raw record. */
static int m11_sync_source_explosion_owner(
    M11_GameViewState* state,
    const struct ExplosionInstance_Compat* explosion,
    int newAttack,
    int removeOwner,
    uint32_t* outFingerprint) {
    unsigned short thing;
    int safety = 0;

    if (outFingerprint) *outFingerprint = 0;
    if (!explosion || explosion->sourceC15Fingerprint == 0u) return 1;
    if (!state || !state->world.dungeon || !state->world.things ||
        !state->world.things->loaded ||
        !state->world.things->rawThingData[THING_TYPE_EXPLOSION] ||
        !state->world.things->explosions || explosion->mapIndex < 0 ||
        explosion->mapX < 0 || explosion->mapY < 0) {
        return 0;
    }

    thing = F0511_DUNGEON_GetSquareFirstThing_Compat(
        state->world.dungeon, state->world.things,
        explosion->mapIndex, explosion->mapX, explosion->mapY);
    while (thing != THING_NONE && thing != THING_ENDOFLIST && safety++ < 64) {
        int index;
        unsigned char* raw;
        unsigned short target;
        if (THING_GET_TYPE(thing) != THING_TYPE_EXPLOSION) {
            thing = F0512_DUNGEON_GetThingNext_Compat(state->world.things, thing);
            continue;
        }
        index = THING_GET_INDEX(thing);
        if (index < 0 || index >= state->world.things->explosionCount ||
            index >= state->world.things->thingCounts[THING_TYPE_EXPLOSION]) {
            return 0;
        }
        raw = state->world.things->rawThingData[THING_TYPE_EXPLOSION] +
            (size_t)index * 4u;
        if (dm1_v1_c15_layout_fingerprint_pc34(raw, 4u) !=
            explosion->sourceC15Fingerprint) {
            thing = F0512_DUNGEON_GetThingNext_Compat(state->world.things, thing);
            continue;
        }
        target = (unsigned short)(thing |
            ((unsigned short)(explosion->cell & 3) << 14));
        if (removeOwner) {
            return m11_unlink_thing_from_square(
                &state->world, explosion->mapIndex,
                explosion->mapX, explosion->mapY, target);
        }
        if (newAttack < 0 || newAttack > 255) return 0;
        raw[3] = (unsigned char)newAttack;
        state->world.things->explosions[index].attack = (unsigned char)newAttack;
        if (outFingerprint) {
            *outFingerprint = dm1_v1_c15_layout_fingerprint_pc34(raw, 4u);
        }
        return outFingerprint && *outFingerprint != 0u;
    }
    return 0;
}

/* V1 explosion tick advance — drives F0822 per live explosion whose
 * scheduledAtTick has arrived.  Called once per orchestrator tick
 * (right after the projectile advance) so a fireball detonation
 * progresses through its frame sequence instead of freezing at the
 * first burst frame.  The persistent types (poison cloud / smoke)
 * reduce attack per frame and despawn when attack drops below the
 * type-specific threshold; one-shot types (fireball / lightning)
 * emit damage on the first advance and despawn immediately.  Idle
 * on empty lists.  Mirrors ReDMCSB TIMELINE.C's EXPLOSION_ADVANCE
 * timeline-event dispatch to F0822. */
static void m11_advance_explosions_v1(M11_GameViewState* state) {
    int i;
    uint32_t now;
    if (!state || !state->active) return;
    if (!state->world.dungeon || !state->world.dungeon->tilesLoaded) return;
    now = state->world.gameTick;

    for (i = 0; i < EXPLOSION_LIST_CAPACITY; ++i) {
        struct ExplosionInstance_Compat* e = &state->world.explosions.entries[i];
        struct ExplosionInstance_Compat newState;
        struct ExplosionTickResult_Compat result;
        struct CellContentDigest_Compat digest;

        if (e->reserved0 == 0) continue;
        if ((uint32_t)e->scheduledAtTick > now) continue;

        if (!m11_build_explosion_digest(&state->world, e, &digest)) {
            continue;
        }

        if (!F0822_EXPLOSION_Advance_Compat(e, &digest, now,
                                             &state->world.masterRng,
                                             &newState, &result)) {
            (void)m11_sync_source_explosion_owner(state, e, 0, 1, NULL);
            F0824_EXPLOSION_Despawn_Compat(&state->world.explosions, i);
            continue;
        }

        /* Apply AoE effects before the slot is reused on despawn. */
        m11_explosion_apply_tick_result(state, e, &result);

        if (result.despawn) {
            (void)m11_sync_source_explosion_owner(state, e, 0, 1, NULL);
            F0824_EXPLOSION_Despawn_Compat(&state->world.explosions, i);
        } else {
            /* Commit advanced state (new frame, possibly reduced attack,
             * possibly promoted rebirth step 1 -> step 2).  Re-schedule
             * per F0826: 1 tick default, 5 ticks for REBIRTH_STEP1
             * -> STEP2.  newAttack already reflects F0822's decay for
             * poison/smoke. */
            int delay = (e->explosionType == C100_EXPLOSION_REBIRTH_STEP1)
                ? 5 : 1;
            newState.reserved0 = 1; /* preserve occupied flag */
            newState.slotIndex = i;
            newState.scheduledAtTick = (int)now + delay;
            if (e->sourceC15Fingerprint != 0u &&
                !m11_sync_source_explosion_owner(
                    state, e, newState.attack, 0,
                    &newState.sourceC15Fingerprint)) {
                F0824_EXPLOSION_Despawn_Compat(&state->world.explosions, i);
                continue;
            }
            *e = newState;
        }
    }
}

/* Probe-visible wrapper so game_view_probe.c can drive the explosion
 * advance deterministically without replaying an orchestrator tick. */
void M11_GameView_AdvanceExplosionsOnce(M11_GameViewState* state) {
    m11_advance_explosions_v1(state);
}

