static int m11_perform_csb_throw_action(M11_GameViewState* state,
                                        int championIndex,
                                        struct ChampionState_Compat* champ,
                                        const char* champName)
{
    unsigned short handThing;
    int projectileSlot = -1;

    if (!state || !champ) return 0;
    if (state->sourceKind != M11_GAME_SOURCE_CSB_BOOT) return 0;

    handThing = m11_get_action_hand_thing(champ);
    m11_set_champion_direction_to_party_f0406(state, champ);
    if (handThing == THING_NONE || handThing == THING_ENDOFLIST) {
        m11_log_event(state, M11_COLOR_LIGHT_RED,
                      "T%u: %s HAS NOTHING TO THROW",
                      (unsigned int)state->world.gameTick,
                      champName);
        return 0;
    }

    if (!csb_v1_runtime_throw_action_hand_from_boot_profile_pc34(
            state->csbBootProfile,
            championIndex,
            &projectileSlot)) {
        return 0;
    }

    champ->inventory[CHAMPION_SLOT_ACTION_HAND] = THING_NONE;
    state->world.projectileDisabledMovementTicks = 4;
    state->world.lastProjectileDisabledMovementDirection =
        state->world.party.direction;
    m11_log_event(state, M11_COLOR_YELLOW,
                  "T%u: %s THROWS",
                  (unsigned int)state->world.gameTick,
                  champName);
    (void)projectileSlot;
    return 1;
}

static int m11_perform_csb_melee_action(M11_GameViewState* state,
                                        int championIndex,
                                        unsigned char chosen)
{
    struct ChampionState_Compat* champ;

    if (!state || state->sourceKind != M11_GAME_SOURCE_CSB_BOOT) return 0;
    if (championIndex < 0 ||
        championIndex >= state->world.party.championCount ||
        championIndex >= CHAMPION_MAX_PARTY) {
        return 0;
    }
    champ = &state->world.party.champions[championIndex];
    if (!champ->present || champ->hp.current == 0) return 0;

    m11_set_champion_direction_to_party_f0406(state, champ);
    if (!csb_v1_runtime_perform_melee_action_from_boot_profile_pc34(
            state->csbBootProfile,
            championIndex,
            (int)chosen)) {
        return 0;
    }
    m11_write_csb_runtime_champion_vitals(state, championIndex);
    return 1;
}

static int m11_spawn_csb_champion_projectile(
    M11_GameViewState* state,
    int championIndex,
    unsigned char actionIndex,
    int projectileSubtype,
    int projectileCategory,
    int kineticEnergy,
    int attack,
    int attackTypeCode,
    int stepEnergy,
    unsigned short associatedThing,
    int poisonAttack,
    int potionPower)
{
    int projectileSlot = -1;

    if (!state || state->sourceKind != M11_GAME_SOURCE_CSB_BOOT) return 0;
    if (!csb_v1_runtime_spawn_champion_projectile_from_boot_profile_pc34(
            state->csbBootProfile,
            championIndex,
            (int)actionIndex,
            projectileSubtype,
            projectileCategory,
            kineticEnergy,
            attack,
            attackTypeCode,
            stepEnergy,
            associatedThing,
            poisonAttack,
            potionPower,
            &projectileSlot)) {
        return 0;
    }
    (void)projectileSlot;
    return 1;
}

static const char* m11_dm1_projectile_action_verb_pc34(int verbKind)
{
    switch (verbKind) {
        case DM1_ACTION_PROJECTILE_VERB_FIREBALL_PC34:
            return "CASTS FIREBALL";
        case DM1_ACTION_PROJECTILE_VERB_DISPELL_PC34:
            return "CASTS DISPELL";
        case DM1_ACTION_PROJECTILE_VERB_LIGHTNING_PC34:
            return "CASTS LIGHTNING";
        case DM1_ACTION_PROJECTILE_VERB_SPIT_PC34:
            return "SPITS FIRE";
        case DM1_ACTION_PROJECTILE_VERB_INVOKE_PC34:
            return "INVOKES";
        default:
            return "";
    }
}

