static int m11_draw_v1_status_hand_slot(const M11_GameViewState* state,
                                        const struct ChampionState_Compat* champ,
                                        unsigned char* framebuffer,
                                        int framebufferWidth,
                                        int framebufferHeight,
                                        int championSlot,
                                        int handIndex,
                                        int dstX,
                                        int dstY) {
    int boxGfx;
    int iconIndex;
    const M11_AssetSlot* box;

    if (!state || !champ || !framebuffer) return 0;
    boxGfx = dm1_v1_champion_status_hand_slot_graphic_pc34(
        handIndex,
        (uint16_t)champ->wounds,
        (handIndex == DM1_SLOT_ACTION_HAND &&
         state->actingChampionOrdinal == (unsigned int)(championSlot + 1)));
    if (boxGfx <= 0) return 0;

    /* CSB owns a separately verified runtime surface contract. Preserve its
     * existing source-clear behavior; this DM1-only change below must not
     * alter the CSB handoff while it is maintained in a different task. */
    if (state->sourceKind == M11_GAME_SOURCE_CSB_BOOT &&
        !state->assetsAvailable) {
        m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                      dstX, dstY, 18, 18,
                      (unsigned char)dm1_v1_champion_status_box_fill_color_pc34());
        return 0;
    }

    /* CHAMDRAW.C F0291 owns C033/C034/C035 before F0038 adds a C020 icon.
     * These 18x18 source surfaces have no host equivalent: an invented
     * border makes empty hands appear as objects and shifts the icon crop.
     * Keep the F0292-cleared status background unchanged until the exact
     * GRAPHICS.DAT surface is present. */
    if (!state->assetsAvailable) return 0;
    box = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader,
                               (unsigned int)boxGfx);
    if (!box ||
        !DM1_ChampionPanel_AssetSurfaceAccepted(
            boxGfx, boxGfx, box->loaded, box->pixels != NULL,
            box->width, box->height, 18, 18)) {
        if (state->sourceKind == M11_GAME_SOURCE_CSB_BOOT) {
            m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                          dstX, dstY, 18, 18,
                          (unsigned char)
                              dm1_v1_champion_status_box_fill_color_pc34());
        }
        return 0;
    }
    M11_AssetLoader_Blit(box, framebuffer, framebufferWidth,
                         framebufferHeight, dstX, dstY, 0);

    iconIndex = m11_v1_status_hand_icon_index(state, championSlot, handIndex);
    if (iconIndex < 0) return 1;

    {
        DM1_V1_ChampionStatusRectPc34 iconRect;
        int iconX = dstX + 1;
        int iconY = dstY + 1;
        if (dm1_v1_champion_status_hand_icon_rect_pc34(
                championSlot, handIndex, &iconRect)) {
            iconX = iconRect.x;
            iconY = iconRect.y;
        }
        (void)m11_draw_dm_object_icon_index(
            state, framebuffer, framebufferWidth, framebufferHeight,
            iconIndex, iconX, iconY, 0);
    }
    return 1;
}

static void m11_draw_v1_leader_hand_object_name(const M11_GameViewState* state,
                                                unsigned char* framebuffer,
                                                int framebufferWidth,
                                                int framebufferHeight) {
    int nameX, nameY, nameW, nameH;
    char objectName[16];
    DM1_V1_LayoutZoneRectPc34 nameRect;
    if (!state || !framebuffer || state->showDebugHUD ||
        !m11_v1_chrome_mode_enabled(state) ||
        (m11_v2_vertical_slice_enabled(state) &&
         state->sourceKind != M11_GAME_SOURCE_CSB_BOOT)) {
        return;
    }
    if (state->sourceKind == M11_GAME_SOURCE_DM2_BOOT) {
        /* SKProject GET_ITEM_NAME resolves an ObjectID through its GDAT
         * category/class `dtText/0x18` entry and FORMAT_SKSTR. The shared
         * M11 name field uses a DM1 rectangle and host font; its DM2 catalog
         * labels are not a substitute for that source-owned text route. */
        return;
    }
    if (!dm1_v1_leader_hand_object_name_zone_id_pc34()) {
        return;
    }
    nameRect = dm1_v1_leader_hand_object_name_rect_pc34();
    nameX = nameRect.x;
    nameY = nameRect.y;
    nameW = nameRect.w;
    nameH = nameRect.h;
    m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                  nameX, nameY, nameW, nameH, M11_COLOR_BLACK);
    /* OBJECT.C F0034 owns C017's cleared source field and its M653 text
     * geometry.  A generic host font changes the name's advance and makes
     * this narrow HUD lane overlap the action surface, so absent PC34 font
     * data deliberately leaves the original black clear intact. */
    if (!g_activeOriginalFont || !M11_Font_IsLoaded(g_activeOriginalFont)) {
        return;
    }
    if (DM1_V1_M11Runtime_GetLeaderHandObjectNamePc34Compat(
            state, objectName, sizeof(objectName))) {
        /* F0034 prints at most C014_OBJECT_NAME_MAXIMUM_LENGTH (14)
         * source characters into C017.  Keep the runtime readout in
         * that same bounded field. */
        objectName[14] = '\0';
        M11_Font_DrawString(g_activeOriginalFont, framebuffer,
                            framebufferWidth, framebufferHeight,
                            nameX, nameY, objectName,
                            M11_COLOR_CYAN, -1, 1);
    }
}

/* c_dialog.cpp::DM2_dialog_OPEN_DIALOG_PANEL expands raw4 rectangles, blits
 * DIALOG_BOXES/0x81/0 with its local palette, and then renders its compiled
 * heading plus the two GDAT labels through DRAW_VP_RC_STR.  Keep that work in
 * the DM2 source renderer: an M11-only panel blit would visibly discard the
 * original font and (for FM Towns English) the authenticated companion text.
 * Source: SKWINSPX/src/v5/uidialog.cpp:352-415; v4/sktext.cpp:763-778. */
static int m11_draw_dm2_save_dialogue_panel(
    const M11_GameViewState *state,
    unsigned char *framebuffer,
    int framebufferWidth,
    int framebufferHeight)
{
    DM2_V1_BootProfile *profile;
    DM2_V1_DialogueOpenPanelHostCommand command;
    DM2_V1_InterfacePalette interface_palette;
    DM2_V1_InterfaceActionTable action_table;
    DM2_V1_ViewportState viewport;
    const uint8_t *font_rows = NULL;
    uint32_t font_hash = 0u;
    uint8_t action_palette[16];

    if (!state || !framebuffer ||
        state->sourceKind != M11_GAME_SOURCE_DM2_BOOT ||
        !state->dm2SaveDialoguePanelActive || !state->dm2BootProfile ||
        framebufferWidth < DM2_VP_WIDTH ||
        framebufferHeight < DM2_VP_HEIGHT) {
        return 0;
    }
    profile = (DM2_V1_BootProfile *)state->dm2BootProfile;
    memset(&command, 0, sizeof(command));
    memset(&interface_palette, 0, sizeof(interface_palette));
    memset(&action_table, 0, sizeof(action_table));
    if (!dm2_v1_boot_dialogue_open_panel_host_command(profile, &command) ||
        !command.valid || !command.draw.valid ||
        command.panel_rect.w <= 0 || command.panel_rect.h <= 0 ||
        !dm2_v1_boot_interface_palette(profile, &interface_palette) ||
        !dm2_v1_boot_interface_action_table(profile, &action_table) ||
        !dm2_v1_boot_interface_font_table(profile, &font_rows, &font_hash)) {
        return 0;
    }
    memcpy(action_palette, interface_palette.palette16,
           sizeof(action_palette));
    if (!dm2_v1_interface_action_table_remap_palette(
            &action_table, action_palette, 16u, 0u, -1, -1)) {
        return 0;
    }
    dm2_v1_viewport_init(&viewport, framebuffer, framebufferWidth);
    dm2_v1_viewport_set_asset_provider(
        &viewport, dm2_v1_boot_viewport_asset_fetch, profile);
    dm2_v1_viewport_set_asset_palette_provider(
        &viewport, dm2_v1_boot_viewport_asset_palette_fetch, profile);
    dm2_v1_viewport_set_source_materials_required(&viewport, 1);
    dm2_v1_viewport_set_gdat_interface_font(&viewport, font_rows, font_hash);
    dm2_v1_viewport_set_gdat_interface_text_palette(
        &viewport, 1, interface_palette.hash, action_palette);
    dm2_v1_viewport_set_gdat_dialogue_open_panel_host_command(
        &viewport, &command, 1);
    dm2_v1_render_dialogue_open_panel(&viewport);
    return viewport.gdat_dialogue_open_panel_consumed_count == 4 &&
        viewport.gdat_dialogue_open_panel_consumed_hash == command.command_hash &&
        viewport.blocked_material_draw_count == 0;
}

typedef struct M11_DM2StartupDrawContext {
    const M11_GameViewState *state;
    const DM2_V1_BootStartupRenderOwnershipReceipt *ownership_receipt;
    unsigned char *framebuffer;
    int framebufferWidth;
    int framebufferHeight;
    int gdat_blit_count;
    int title_gdat_blit_count;
    int menu_gdat_blit_count;
    int gdat_proof_failure_count;
    int rect_count;
    int text_count;
    int draw_title_phase;
    int draw_menu_phase;
} M11_DM2StartupDrawContext;

static uint32_t m11_dm2_startup_frame_hash(const unsigned char *framebuffer,
                                           int width,
                                           int height)
{
    uint32_t hash = 0x4d324453u;
    int i;
    if (!framebuffer || width <= 0 || height <= 0) {
        return 0u;
    }
    for (i = 0; i < width * height; ++i) {
        hash ^= (uint32_t)framebuffer[i];
        hash *= 16777619u;
    }
    return hash;
}

static int m11_dm2_startup_exec_gdat_image(
    void *userdata,
    const DM2_V1_StartupDrawCommand *command)
{
    M11_DM2StartupDrawContext *context = (M11_DM2StartupDrawContext*)userdata;
    DM2_V1_BootProfile *profile;
    uint8_t *pixels = NULL;
    int srcW = 0;
    int srcH = 0;
    int stride = 0;
    int dstW;
    int dstH;
    int y;
    uint32_t raw_hash = 0u;
    uint32_t raw_byte_count = 0u;
    uint32_t expected_hash = 0u;
    uint32_t expected_byte_count = 0u;
    uint32_t seed = 0u;
    DM2_V1_InterfacePalette palette;

    if (!context || !context->state || !context->ownership_receipt ||
        !context->framebuffer || !command) {
        return 0;
    }
    profile = (DM2_V1_BootProfile *)context->state->dm2BootProfile;
    if (command->frame_owner == DM2_V1_FRAME_OWNER_STARTUP_TITLE) {
        if (!context->draw_title_phase) {
            return 1;
        }
        seed = 0x32545257u;
        expected_hash = context->ownership_receipt->startup_title_raw_gdat_hash;
        expected_byte_count =
            context->ownership_receipt->startup_title_raw_gdat_byte_count;
    } else if (command->frame_owner == DM2_V1_FRAME_OWNER_STARTUP_MENU) {
        if (!context->draw_menu_phase) {
            return 1;
        }
        seed = 0x324d5257u;
        expected_hash = context->ownership_receipt->startup_menu_raw_gdat_hash;
        expected_byte_count =
            context->ownership_receipt->startup_menu_raw_gdat_byte_count;
    } else {
        ++context->gdat_proof_failure_count;
        return 0;
    }
    if (!context->ownership_receipt->startup_title_menu_raw_gdat_receipt_consumed ||
        !dm2_v1_boot_gdat_raw_asset_proof(profile,
                                           command->gdat_category,
                                           command->gdat_index,
                                           command->gdat_field,
                                           seed,
                                           &raw_hash,
                                           &raw_byte_count) ||
        raw_hash != expected_hash || raw_byte_count != expected_byte_count) {
        ++context->gdat_proof_failure_count;
        return 0;
    }
    if (!profile ||
        !dm2_v1_boot_interface_palette(profile, &palette) ||
        dm2_v1_boot_gdat_image_asset_fetch(profile,
                                           command->gdat_category,
                                           command->gdat_index,
                                           command->gdat_field,
                                           &pixels,
                                           &srcW,
                                           &srcH,
                                           &stride) != 0 ||
        !pixels || srcW <= 0 || srcH <= 0 || stride < srcW) {
        dm2_v1_boot_gdat_image_asset_free(pixels);
        return 0;
    }
    dstW = command->rect.w;
    dstH = command->rect.h;
    if (dstW <= 0) {
        dstW = srcW;
    }
    if (dstH <= 0) {
        dstH = srcH;
    }
    for (y = 0; y < dstH; ++y) {
        int x;
        int sy = y * srcH / dstH;
        int dy = command->rect.y + y;
        if (dy < 0 || dy >= context->framebufferHeight) {
            continue;
        }
        for (x = 0; x < dstW; ++x) {
            int sx = x * srcW / dstW;
            int dx = command->rect.x + x;
            unsigned char c;
            if (dx < 0 || dx >= context->framebufferWidth) {
                continue;
            }
            c = pixels[sy * stride + sx];
            if (command->transparent_color >= 0 &&
                c == (unsigned char)command->transparent_color) {
                continue;
            }
            /* DRAW_TITLE_MENU_SCREEN blits TITLE/0/dt07/4 directly as an
             * 8-bit screen when the original 64000-byte payload exists.
             * Its bytes are already physical indices in the IRGB set chosen
             * by FIRE_SELECT_PALETTE_SET(0), so remapping low values through
             * dtPalette16 corrupts the menu colours.  The unused credits
             * picture is separately palette-owned by the original title
             * event route and is never substituted for this startup menu. */
            if (command->frame_owner != DM2_V1_FRAME_OWNER_STARTUP_MENU &&
                c < 16u) {
                c = palette.palette16[c];
            }
            context->framebuffer[dy * context->framebufferWidth + dx] = c;
        }
    }
    dm2_v1_boot_gdat_image_asset_free(pixels);
    ++context->gdat_blit_count;
    if (command->frame_owner == DM2_V1_FRAME_OWNER_STARTUP_TITLE) {
        ++context->title_gdat_blit_count;
    } else if (command->frame_owner == DM2_V1_FRAME_OWNER_STARTUP_MENU) {
        ++context->menu_gdat_blit_count;
    }
    return 1;
}

static void m11_dm2_startup_exec_fill_rect(
    void *userdata,
    const DM2_V1_StartupDrawCommand *command)
{
    M11_DM2StartupDrawContext *context = (M11_DM2StartupDrawContext*)userdata;
    unsigned char color;

    if (!context || !context->framebuffer || !command) {
        return;
    }
    if (context->ownership_receipt &&
        context->ownership_receipt->startup_title_menu_raw_gdat_receipt_consumed) {
        return;
    }
    color = command->style == DM2_V1_STARTUP_STYLE_SELECTED_FILL
        ? M11_COLOR_RED
        : M11_COLOR_BLACK;
    m11_fill_rect(context->framebuffer,
                  context->framebufferWidth,
                  context->framebufferHeight,
                  command->rect.x,
                  command->rect.y,
                  command->rect.w,
                  command->rect.h,
                  color);
    ++context->rect_count;
}

static void m11_dm2_startup_exec_outline_rect(
    void *userdata,
    const DM2_V1_StartupDrawCommand *command)
{
    M11_DM2StartupDrawContext *context = (M11_DM2StartupDrawContext*)userdata;

    if (!context || !context->framebuffer || !command) {
        return;
    }
    if (context->ownership_receipt &&
        context->ownership_receipt->startup_title_menu_raw_gdat_receipt_consumed) {
        return;
    }
    m11_draw_rect(context->framebuffer,
                  context->framebufferWidth,
                  context->framebufferHeight,
                  command->rect.x,
                  command->rect.y,
                  command->rect.w,
                  command->rect.h,
                  M11_COLOR_WHITE);
    ++context->rect_count;
}

static void m11_dm2_startup_exec_text(
    void *userdata,
    const DM2_V1_StartupDrawCommand *command)
{
    M11_DM2StartupDrawContext *context = (M11_DM2StartupDrawContext*)userdata;
    const M11_TextStyle *style;

    if (!context || !context->framebuffer || !command) {
        return;
    }
    if (context->ownership_receipt &&
        context->ownership_receipt->startup_title_menu_raw_gdat_receipt_consumed) {
        return;
    }
    style = command->style == DM2_V1_STARTUP_STYLE_TITLE ||
            command->style == DM2_V1_STARTUP_STYLE_SELECTED_TEXT
        ? &g_text_title
        : &g_text_shadow;
    m11_draw_text(context->framebuffer,
                  context->framebufferWidth,
                  context->framebufferHeight,
                  command->x,
                  command->y,
                  command->text,
                  style);
    ++context->text_count;
}

static int m11_draw_dm2_startup_credits(const M11_GameViewState *state,
                                        unsigned char *framebuffer,
                                        int framebufferWidth,
                                        int framebufferHeight)
{
    DM2_V1_BootProfile *profile;
    const DM2_V1_AssetLoader *loader;
    DM2_V1_QueryGdatSummaryImageReceipt image;
    uint8_t *pixels = NULL;
    uint32_t raw_hash = 0u;
    uint32_t raw_bytes = 0u;
    int width = 0;
    int height = 0;
    int stride = 0;
    int y;

    if (!state || !framebuffer || !state->dm2State.startup_credits_active ||
        state->sourceKind != M11_GAME_SOURCE_DM2_BOOT ||
        !(profile = (DM2_V1_BootProfile *)state->dm2BootProfile) ||
        !(loader = dm2_v1_boot_asset_loader(profile))) {
        return 0;
    }
    memset(&image, 0, sizeof(image));
    if (!dm2_v1_query_gdat_summary_image_receipt(
            loader, DM2_GDAT_CATEGORY_TITLE, 0, 1, &image) ||
        !image.accepted || image.metadata.width != 320u ||
        image.metadata.height != 200u ||
        !((image.metadata.bits_per_pixel == 8u) ||
          (image.metadata.bits_per_pixel == 4u && image.colors == 16u &&
           image.palette_hash != 0u)) ||
        !dm2_v1_boot_gdat_raw_asset_proof(
            profile, DM2_GDAT_CATEGORY_TITLE, 0, 1, 0x32435244u,
            &raw_hash, &raw_bytes) || raw_hash == 0u || raw_bytes == 0u ||
        dm2_v1_boot_gdat_image_asset_fetch(
            profile, DM2_GDAT_CATEGORY_TITLE, 0, 1, &pixels, &width, &height,
            &stride) != 0 || !pixels || width != 320 || height != 200 ||
        stride < width) {
        dm2_v1_boot_gdat_image_asset_free(pixels);
        return 0;
    }
    /* ReDMCSB/SKProject SHOW_CREDITS passes glbl_pal2 only for non-BPP8
     * IMG3 images.  The PC English BPP8 page keeps its physical source
     * indices and is presented through DM2_INIT's dtPalIRGB table. */
    for (y = 0; y < framebufferHeight; ++y) {
        int x;
        int sy = y * height / framebufferHeight;
        for (x = 0; x < framebufferWidth; ++x) {
            uint8_t pixel = pixels[sy * stride + x * width / framebufferWidth];
            if (image.metadata.bits_per_pixel == 4u) {
                pixel = image.palette16[pixel & 0x0fu];
            }
            framebuffer[y * framebufferWidth + x] = pixel;
        }
    }
    dm2_v1_boot_gdat_image_asset_free(pixels);
    return 1;
}

static int m11_draw_dm2_startup_menu(const M11_GameViewState *state,
                                     unsigned char *framebuffer,
                                     int framebufferWidth,
                                     int framebufferHeight,
                                     DM2_V1_BootStartupHostViewReceipt
                                         *out_host_receipt,
                                     DM2_V1_BootStartupRenderOwnershipReceipt
                                         *out_ownership_receipt,
                                     DM2_V1_BootStartupRealVisualCaptureReceipt
                                         *out_visual_capture_receipt)
{
    DM2_V1_BootStartupViewModel view_model;
    DM2_V1_BootRuntimeStartupSnapshot snapshot;
    DM2_V1_BootStartupRenderOwnershipReceipt ownership_receipt;
    DM2_V1_BootStartupRealVisualCaptureReceipt visual_capture_receipt;
    DM2_V1_StartupDrawExecutor executor;
    M11_DM2StartupDrawContext context;

    if (out_host_receipt) {
        memset(out_host_receipt, 0, sizeof(*out_host_receipt));
    }
    if (out_ownership_receipt) {
        memset(out_ownership_receipt, 0, sizeof(*out_ownership_receipt));
    }
    if (out_visual_capture_receipt) {
        memset(out_visual_capture_receipt, 0,
               sizeof(*out_visual_capture_receipt));
    }
    if (!state || !framebuffer || !state->dm2State.startup_menu_active) {
        return 0;
    }
    if (!m11_dm2_boot_runtime_startup_view_model(state, &view_model) ||
        !view_model.host_view_receipt.valid ||
        !view_model.host_view_receipt.capture_proof_valid) {
        return 0;
    }
    m11_dm2_boot_runtime_startup_snapshot(state, &snapshot);
    if (!dm2_v1_boot_startup_render_ownership_receipt_from_runtime_state(
            (DM2_V1_BootProfile *)snapshot.profile,
            snapshot.startup_menu_active,
            snapshot.startup_save_root,
            snapshot.resume_available,
            snapshot.slot_mask,
            snapshot.selected_row,
            state->dm2State.startup_title_animation_tick,
            &ownership_receipt) ||
        !ownership_receipt.valid ||
        !ownership_receipt.final_m11_draw_caller_ready ||
        !ownership_receipt.final_m11_draw_caller_consumes_ownership ||
        !ownership_receipt.execute_startup_draw_commands ||
        !ownership_receipt.extended_spells_definition_consumed ||
        memcmp(&ownership_receipt.extended_spells,
               &view_model.host_view_receipt.extended_spells,
               sizeof(ownership_receipt.extended_spells)) != 0 ||
        ownership_receipt.draw_command_count != view_model.command_count) {
        return 0;
    }
    (void)dm2_v1_boot_startup_real_visual_capture_receipt_from_runtime_state(
        (DM2_V1_BootProfile *)snapshot.profile,
        snapshot.startup_menu_active,
        snapshot.startup_save_root,
        snapshot.resume_available,
        snapshot.slot_mask,
        snapshot.selected_row,
        state->dm2State.startup_title_animation_tick,
        &visual_capture_receipt);
    if (
        !visual_capture_receipt.title_menu_hud_visual_proof_ready ||
        !visual_capture_receipt.no_fallback_title_blit ||
        visual_capture_receipt.menu_command_count !=
            ownership_receipt.draw_command_count ||
        visual_capture_receipt.packaged_visual_capture_hash == 0u) {
        return 0;
    }
    if (out_host_receipt) {
        *out_host_receipt = view_model.host_view_receipt;
    }
    if (out_ownership_receipt) {
        *out_ownership_receipt = ownership_receipt;
    }
    if (out_visual_capture_receipt) {
        *out_visual_capture_receipt = visual_capture_receipt;
    }
    context.state = state;
    context.framebuffer = framebuffer;
    context.framebufferWidth = framebufferWidth;
    context.framebufferHeight = framebufferHeight;
    context.ownership_receipt = &ownership_receipt;
    context.gdat_blit_count = 0;
    context.title_gdat_blit_count = 0;
    context.menu_gdat_blit_count = 0;
    context.gdat_proof_failure_count = 0;
    context.rect_count = 0;
    context.text_count = 0;
    /* SKProject's SHOW_MENU_SCREEN loads TITLE/0/dt07/1 as the optional
     * credits picture, then DRAW_TITLE_MENU_SCREEN immediately presents
     * TITLE/0/dt07/4 (or its 64000-byte raw screen).  The credits picture is
     * reached only after the title-menu event loop requests SHOW_CREDITS;
     * it is not a timed boot animation.  Do not hold the startup host on
     * field 1: apart from trapping launch on the credits, SHOW_CREDITS owns
     * its palette transaction.  startend.cpp lines 285-298 retain a local
     * palette only for non-BPP8 credits; the verified PC English BPP8 image
     * instead keeps the global dtPalIRGB selected by DM2_INIT.  Source:
     * SKProject SKWINSPX/src/v5/startend.cpp::DM2_SHOW_MENU_SCREEN,
     * DM2_SHOW_CREDITS and DM2_INIT. */
    context.draw_title_phase = 0;
    context.draw_menu_phase = 1;
    executor.userdata = &context;
    executor.draw_gdat_image = m11_dm2_startup_exec_gdat_image;
    executor.fill_rect = m11_dm2_startup_exec_fill_rect;
    executor.outline_rect = m11_dm2_startup_exec_outline_rect;
    executor.draw_text = m11_dm2_startup_exec_text;
    if (!dm2_v1_boot_startup_execute_draw_commands(
            view_model.commands,
            ownership_receipt.draw_command_count,
            &executor)) {
        return 0;
    }
    if (context.gdat_proof_failure_count != 0 ||
        (context.draw_title_phase &&
         (context.title_gdat_blit_count != 1 ||
          context.menu_gdat_blit_count != 0)) ||
        (context.draw_menu_phase &&
         (context.title_gdat_blit_count != 0 ||
          context.menu_gdat_blit_count != 1))) {
        return 0;
    }
    dm2_v1_runtime_note_startup_frame_consumption(
        context.title_gdat_blit_count, context.menu_gdat_blit_count);
    visual_capture_receipt.m11_draw_executed_command_count =
        ownership_receipt.draw_command_count;
    visual_capture_receipt.m11_draw_gdat_blit_count =
        context.gdat_blit_count;
    visual_capture_receipt.m11_draw_rect_count = context.rect_count;
    visual_capture_receipt.m11_draw_text_count = context.text_count;
    visual_capture_receipt.m11_draw_frame_hash =
        m11_dm2_startup_frame_hash(framebuffer,
                                   framebufferWidth,
                                   framebufferHeight);
    visual_capture_receipt.m11_draw_frame_pixel_count =
        (uint32_t)(framebufferWidth * framebufferHeight);
    visual_capture_receipt.m11_draw_matches_real_visual_receipt =
        visual_capture_receipt.m11_draw_executed_command_count ==
            ownership_receipt.draw_command_count &&
        ((context.draw_title_phase &&
          visual_capture_receipt.m11_draw_gdat_blit_count == 1 &&
          context.title_gdat_blit_count == 1 &&
          context.menu_gdat_blit_count == 0) ||
         (context.draw_menu_phase &&
          visual_capture_receipt.m11_draw_gdat_blit_count == 1 &&
          context.title_gdat_blit_count == 0 &&
          context.menu_gdat_blit_count == 1)) &&
        visual_capture_receipt.m11_draw_rect_count == 0 &&
        visual_capture_receipt.m11_draw_text_count == 0 &&
        context.gdat_proof_failure_count == 0 &&
        visual_capture_receipt.m11_draw_frame_hash != 0u &&
        visual_capture_receipt.m11_draw_frame_pixel_count ==
            (uint32_t)(framebufferWidth * framebufferHeight);
    visual_capture_receipt.m11_draw_consumption_ready =
        visual_capture_receipt.m11_draw_matches_real_visual_receipt &&
        visual_capture_receipt.title_menu_hud_visual_proof_ready &&
        visual_capture_receipt.hud_suppressed_capture_ready;
    if (!visual_capture_receipt.m11_draw_consumption_ready) {
        return 0;
    }
    if (out_visual_capture_receipt) {
        *out_visual_capture_receipt = visual_capture_receipt;
    }
    return 1;
}

typedef struct M11_NexusStartupDrawContext {
    const M11_GameViewState *state;
    const Nexus_V1_StartupFullStartPackageReceipt *startup_package;
    const Nexus_V1_StartupTitleTransitionCaptureReceipt *transition_capture;
    unsigned char *framebuffer;
    int framebufferWidth;
    int framebufferHeight;
} M11_NexusStartupDrawContext;

static int m11_nexus_startup_title_receipt_ready(
    const M11_NexusStartupDrawContext *context,
    const Nexus_V1_StartupDrawCommand *command)
{
    const Nexus_V1_StartupFullStartPackageReceipt *package;
    int title_frame;

    if (!context || !context->state || !context->startup_package ||
        !command) {
        return 0;
    }
    if (command->kind != NEXUS_V1_STARTUP_DRAW_BOOT_TITLE_FRAME) {
        return 0;
    }
    package = context->startup_package;
    title_frame = context->state->nexusState.title_frame -
                  package->boot_warning_frames;
    return context->transition_capture &&
           context->transition_capture->consumer_ready &&
           context->transition_capture->expected_draw_kind ==
               NEXUS_V1_STARTUP_DRAW_BOOT_TITLE_FRAME &&
           context->transition_capture->expected_title_frame == title_frame &&
           package->consumer.full_start.assets.title_surface_loaded &&
           package->title_capture_surface_ready &&
           package->saturn_timing_exact &&
           package->saturn_capture_frames_exact &&
           context->state->nexusState.title_frame >=
               package->boot_warning_frames &&
           command->title_frame == title_frame;
}

static void m11_nexus_startup_exec_title_background(
    void *userdata,
    const Nexus_V1_StartupDrawCommand *command)
{
    /* TITLE.CG/TITLE.BIN are source receipts, not a Saturn framebuffer.
     * A host-sized top-left crop is not proof of VDP1/VDP2 placement. Keep
     * this executor no-draw until an original capture surface is bound. */
    (void)userdata;
    (void)command;
}

static void m11_nexus_startup_exec_warning_background(
    void *userdata,
    const Nexus_V1_StartupDrawCommand *command)
{
    /* WARNING.BIN is source evidence only. Do not blit its DGT2 pixels or
     * install a host palette without captured Saturn destination/CLUT state. */
    (void)userdata;
    (void)command;
}

static void m11_nexus_startup_exec_boot_title_frame(
    void *userdata,
    const Nexus_V1_StartupDrawCommand *command)
{
    M11_NexusStartupDrawContext *context =
        (M11_NexusStartupDrawContext*)userdata;
    Nexus_Framebuffer nexusFb;
    int y;
    int copyW;
    int copyH;
    if (!context || !context->framebuffer || !command) {
        return;
    }
    if (!m11_nexus_startup_title_receipt_ready(context, command)) {
        return;
    }
    nexus_fb_init(&nexusFb);
    nexus_render_title((const Nexus_TitleScreen*)(
                           context->state
                               ? context->state->nexusTitleScreen
                               : NULL),
                       &nexusFb,
                       command->title_frame + nexus_title_boot_warning_frames());
    copyW = context->framebufferWidth < NEXUS_FB_W
                ? context->framebufferWidth
                : NEXUS_FB_W;
    copyH = context->framebufferHeight < NEXUS_FB_H
                ? context->framebufferHeight
                : NEXUS_FB_H;
    for (y = 0; y < copyH; ++y) {
        memcpy(&context->framebuffer[y * context->framebufferWidth],
               &nexusFb.color_buffer[y * NEXUS_FB_W],
               (size_t)copyW);
    }
}

static void m11_nexus_startup_exec_fill_rect(
    void *userdata,
    const Nexus_V1_StartupDrawCommand *command)
{
    /* The startup planner retains hit-test/state geometry, but these
     * procedural rectangles are not authenticated Saturn MENU.BPK/STABG
     * surfaces.  Keep the visual executor no-draw until VDP1 placement and
     * palette ownership are proven by capture. */
    (void)userdata;
    (void)command;
}

static void m11_nexus_startup_exec_outline_rect(
    void *userdata,
    const Nexus_V1_StartupDrawCommand *command)
{
    /* Selection frames are likewise layout metadata, not source pixels. */
    (void)userdata;
    (void)command;
}

static void m11_nexus_startup_exec_text(
    void *userdata,
    const Nexus_V1_StartupDrawCommand *command)
{
    M11_NexusStartupDrawContext *context =
        (M11_NexusStartupDrawContext*)userdata;
    (void)context;
    (void)command;
    /* TEXT4/TABL/RLOWFIX FONT012 → Saturn VDP2 glyph ownership is not yet
     * authenticated.  Keep this final executor boundary no-draw even if a
     * stale or synthetic startup command bypasses the launcher filter. */
}

static void m11_nexus_startup_exec_portrait(
    void *userdata,
    const Nexus_V1_StartupDrawCommand *command)
{
    /* FACE.BIN bytes are authenticated as portrait assets, but the startup
     * roster index, destination rectangle and Saturn VDP placement are not.
     * Do not turn the planner's guessed 10x10 rectangle into live pixels. */
    (void)userdata;
    (void)command;
}

static void m11_draw_nexus_startup_commands(
    const M11_GameViewState *state,
    unsigned char *framebuffer,
    int framebufferWidth,
    int framebufferHeight,
    const Nexus_V1_StartupFullStartPackageReceipt *startup_package,
    const Nexus_V1_StartupTitleTransitionCaptureReceipt *transition_capture,
    const Nexus_V1_StartupDrawCommand *commands,
    int command_count)
{
    M11_NexusStartupDrawContext context;
    Nexus_V1_StartupDrawExecutor executor;
    if (!commands || command_count <= 0) {
        return;
    }
    memset(&context, 0, sizeof(context));
    context.state = state;
    context.startup_package = startup_package;
    context.transition_capture = transition_capture;
    context.framebuffer = framebuffer;
    context.framebufferWidth = framebufferWidth;
    context.framebufferHeight = framebufferHeight;
    memset(&executor, 0, sizeof(executor));
    executor.userdata = &context;
    executor.draw_title_background = m11_nexus_startup_exec_title_background;
    executor.fill_rect = m11_nexus_startup_exec_fill_rect;
    executor.outline_rect = m11_nexus_startup_exec_outline_rect;
    executor.draw_text = m11_nexus_startup_exec_text;
    executor.draw_portrait = m11_nexus_startup_exec_portrait;
    executor.draw_boot_title_frame = m11_nexus_startup_exec_boot_title_frame;
    executor.draw_warning_background =
        m11_nexus_startup_exec_warning_background;
    (void)nexus_v1_launcher_startup_presentation_execute(commands,
                                                         command_count,
                                                         &executor);
}

static int m11_draw_nexus_dgn_host_plan(
    const M11_GameViewState *state,
    unsigned char *framebuffer,
    int framebufferWidth,
    int framebufferHeight)
{
    Nexus_Viewport viewport;
    Nexus_V1_DgnViewportHostRouteReceipt receipt;
    int y;
    int copy_width;
    int copy_height;

    if (!state || !framebuffer ||
        !state->nexusState.startup_host_execute_dgn_draws ||
        !state->nexusState.startup_dgn_render_ready ||
        !state->nexusState.startup_dgn_viewport_host_route_ready ||
        state->nexusState.startup_dgn_viewport_host_blocks_runtime) {
        return 0;
    }
    nexus_viewport_init(&viewport);
    nexus_viewport_render(&viewport, state->nexusEngine);
    memset(&receipt, 0, sizeof(receipt));
    if (nexus_viewport_dgn_host_route_receipt(&viewport,
                                              state->nexusEngine,
                                              &receipt) != 0 ||
        !receipt.can_present_runtime_dgn || receipt.blocks_runtime_dgn ||
        !receipt.written_pixels ||
        (!receipt.material_surface_count &&
         receipt.status != NEXUS_V1_DGN_HOST_ROUTE_READY_RENDERED_MESH)) {
        return 0;
    }
    m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                  0, 0, framebufferWidth, framebufferHeight,
                  M11_COLOR_BLACK);
    copy_width = framebufferWidth < NEXUS_FB_W ? framebufferWidth : NEXUS_FB_W;
    copy_height = framebufferHeight < NEXUS_FB_H ? framebufferHeight : NEXUS_FB_H;
    for (y = 0; y < copy_height; ++y) {
        memcpy(&framebuffer[y * framebufferWidth],
               &viewport.fb.color_buffer[y * NEXUS_FB_W],
               (size_t)copy_width);
    }
    if (receipt.status == NEXUS_V1_DGN_HOST_ROUTE_READY_RENDERED_MESH) {
        uint8_t rgb6[256][3];
        int c;
        for (c = 0; c < 256; ++c) {
            uint32_t rgba = viewport.fb.palette[c];
            rgb6[c][0] = (uint8_t)((rgba >> 18) & 0x3FU);
            rgb6[c][1] = (uint8_t)((rgba >> 10) & 0x3FU);
            rgb6[c][2] = (uint8_t)((rgba >> 2) & 0x3FU);
        }
        M11_Render_SetIndexedPaletteRgb6(rgb6);
    }
    nexus_v2_hud_runtime_set_direction(state->nexusEngine->game.party_dir);
    nexus_v2_hud_runtime_set_level(
        state->nexusEngine->game.current_level, 15);
    /* The mechanics state owns the live party purse.  Do not seed the HUD
     * with a synthetic zero: ReDMCSB's gold-pile pickup updates this field
     * before the viewport/HUD handoff. */
    nexus_v2_hud_runtime_set_party_gold(
        state->nexusEngine->mechanics
            ? state->nexusEngine->mechanics->gold_pieces
            : 0);
    {
        const Nexus_V1_ChampionPool *pool = &state->nexusEngine->champions;
        int ci;
        for (ci = 0; ci < pool->party_count && ci < NEXUS_MAX_PARTY; ++ci) {
            int idx = pool->party[ci];
            if (idx >= 0 && idx < pool->champion_count &&
                pool->champions[idx].alive) {
                const Nexus_V1_Champion *c = &pool->champions[idx];
                int hp_pct = c->max_health > 0
                    ? (c->health * 100 / c->max_health) : 0;
                int sta_pct = c->max_stamina > 0
                    ? (c->stamina * 100 / c->max_stamina) : 0;
                int mana_pct = c->max_mana > 0
                    ? (c->mana * 100 / c->max_mana) : 0;
                nexus_v2_hud_runtime_set_champion(ci, hp_pct, sta_pct,
                    mana_pct, idx == pool->leader_index, false);
            }
        }
    }
    {
        static NEXUS_V2_PhaseGateConfig nexus_dgn_hud_gate;
        static int nexus_dgn_hud_gate_set = 0;
        if (!nexus_dgn_hud_gate_set) {
            memset(&nexus_dgn_hud_gate, 0, sizeof(nexus_dgn_hud_gate));
            /* No retail Nexus HUD widget/VDP placement receipt has been
             * admitted yet. Keep the procedural V2 overlay closed in the
             * production route instead of manufacturing HUD pixels. */
            nexus_v2_hud_runtime_set_gate_config(&nexus_dgn_hud_gate);
            nexus_dgn_hud_gate_set = 1;
        }
    }
    nexus_v2_hud_runtime_render(framebuffer, framebufferWidth,
                                framebufferHeight);
    return 1;
}

/* ReDMCSB STARTUP2.C:411-423 completes F0394's spell-area update before
 * F0387 redraws the action area, then F0395 draws movement arrows.  Keep
 * the action area as a final-panel pass so later M11 HUD work cannot retain
 * stale pixels in the C093..C096 empty-hand icon boxes. */
static void m11_draw_v1_action_area_overlay(const M11_GameViewState* state,
                                            unsigned char* framebuffer,
                                            int framebufferWidth,
                                            int framebufferHeight) {
    if (!state || state->showDebugHUD || m11_v2_vertical_slice_enabled(state) ||
        !m11_v1_chrome_mode_enabled(state)) {
        return;
    }

    if (state->actingChampionOrdinal != 0 &&
        m11_draw_dm_action_menu(state, framebuffer,
                                framebufferWidth, framebufferHeight)) {
        return;
    }

    {
        DM1_V1_ActionAreaRectPc34 action = dm1_v1_action_area_rect_pc34();
        m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                      action.x, action.y, action.w, action.h,
                      (unsigned char)dm1_v1_action_area_clear_color_pc34());
        (void)m11_draw_dm_action_icon_cells(state, framebuffer,
                                            framebufferWidth,
                                            framebufferHeight);
    }
}

static void m11_draw_utility_panel(const M11_GameViewState* state,
                                   unsigned char* framebuffer,
                                   int framebufferWidth,
                                   int framebufferHeight,
                                   const struct DungeonMapDesc_Compat* mapDesc) {
    char line[32];
    char champion[16];
    const struct ChampionState_Compat* activeChampion = m11_get_active_champion(state);
    unsigned char accent = activeChampion ? M11_COLOR_LIGHT_GREEN : M11_COLOR_LIGHT_CYAN;
    int drewAuthenticFrames = 0;

    if (!state) {
        return;
    }

    if (m11_v2_vertical_slice_enabled(state)) {
        DM1_V1_SpellAreaRectPc34 spell = dm1_v1_spell_area_graphic_rect_pc34();
        int spellX = spell.x;
        int spellY = spell.y;
        int spellW = spell.w;
        int spellH = spell.h;
        (void)spellW;
        (void)spellH;
        m11_blit_v2_slice_asset(&m11_v2_action_area_base,
                                framebuffer, framebufferWidth, framebufferHeight,
                                224, 45, 1);
        m11_blit_v2_slice_asset(&m11_v2_spell_area_base,
                                framebuffer, framebufferWidth, framebufferHeight,
                                spellX, spellY, 1);
        m11_blit_v2_slice_asset(&m11_v2_spell_area_rune_bed,
                                framebuffer, framebufferWidth, framebufferHeight,
                                spellX, spellY, 1);
        m11_blit_v2_slice_asset(state->spellPanelOpen
                                    ? &m11_v2_spell_area_active
                                    : &m11_v2_spell_area_highlight,
                                framebuffer, framebufferWidth, framebufferHeight,
                                spellX, spellY, 1);
        drewAuthenticFrames = 1;
    }

    /* V1 mode: replace the procedural utility-panel backdrop with the
     * original GRAPHICS.DAT action area (graphic 10, 87x45) and the
     * spell area lines graphic (graphic 9, 87x33) blitted at their
     * classic-DM screen coordinates.  This gives the right column the
     * authentic carved frame and avoids the flat-fill + hairline rect
     * that read as procedural.  Debug HUD keeps the procedural panel
     * so the ad-hoc I/S/L buttons still have a dark backdrop.
     *
     * The combined action+spell strip covers y=45..114, which lines up
     * with the utility panel's current vertical band (y=28..70) plus
     * the previously empty space above the party HUD (y=70..146).
     * Reference: ReDMCSB ACTIDRAW.C / CASTER.C and C011_ZONE_ACTION_AREA /
     * C013_ZONE_SPELL_AREA in ZONES.H. */
    if (!state->showDebugHUD && !m11_v2_vertical_slice_enabled(state)) {
        DM1_V1_ActionAreaRectPc34 action = dm1_v1_action_area_rect_pc34();
        DM1_V1_SpellAreaRectPc34 spell = dm1_v1_spell_area_graphic_rect_pc34();
        const M11_AssetSlot* actionAsset = NULL;
        const M11_AssetSlot* spellAsset = NULL;

        /* C010 belongs only to F0387 menu mode and C009 only to an active
         * F0394 caster.  Validate their real PC34 dimensions here, but do
         * not prepaint either surface before its source-owned state path. */
        if (state->assetsAvailable) {
            actionAsset = M11_AssetLoader_Load(
                (M11_AssetLoader*)&state->assetLoader,
                (unsigned int)dm1_v1_action_area_graphic_id_pc34());
            spellAsset = M11_AssetLoader_Load(
                (M11_AssetLoader*)&state->assetLoader,
                (unsigned int)DM1_V1_SPELL_AREA_BACKGROUND_GRAPHIC_ID_PC34);
        }
        if (actionAsset && spellAsset && actionAsset->loaded && actionAsset->pixels &&
            spellAsset->loaded && spellAsset->pixels &&
            (int)actionAsset->width == action.w &&
            (int)actionAsset->height == action.h &&
            (int)spellAsset->width == spell.w &&
            (int)spellAsset->height == spell.h) {
            drewAuthenticFrames = 1;
        } else {
            /* Missing real data leaves this source-owned strip black. */
            int stripX, stripY, stripW, stripH;
            (void)m11_v1_action_spell_strip_zone(
                &stripX, &stripY, &stripW, &stripH);
            m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                          stripX, stripY, stripW, stripH,
                          (unsigned char)dm1_v1_action_area_clear_color_pc34());
        }
    }

    /* C010/C011 are source-owned V1 surfaces. A failed GRAPHICS.DAT
     * validation has already cleared their strip; never replace that result
     * with Firestaff's procedural utility frame in V1 chrome. */
    /* FIRESTAFF_V1_CHROME=0 is a DM1 compatibility switch, not authority to
     * manufacture CSB chrome. ReDMCSB's C009/C010 route stays black when its
     * verified GRAPHICS.DAT material is absent. */
    if (!drewAuthenticFrames && !m11_v1_chrome_mode_enabled(state) &&
        !m11_is_dm1_source_kind(state->sourceKind) &&
        state->sourceKind != M11_GAME_SOURCE_CSB_BOOT) {
        m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                      M11_UTILITY_PANEL_X, M11_UTILITY_PANEL_Y,
                      M11_UTILITY_PANEL_W, M11_UTILITY_PANEL_H, M11_COLOR_BLACK);
        m11_draw_rect(framebuffer, framebufferWidth, framebufferHeight,
                      M11_UTILITY_PANEL_X, M11_UTILITY_PANEL_Y,
                      M11_UTILITY_PANEL_W, M11_UTILITY_PANEL_H, M11_COLOR_LIGHT_CYAN);
    }

    m11_get_active_champion_label(state, champion, sizeof(champion));

    if (state->showDebugHUD) {
        /* Debug mode: show MENU label, source kind, full metadata */
        m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                      222, 34, "MENU", &g_text_small);
        snprintf(line, sizeof(line), "%s %s", m11_source_name(state->sourceKind), champion);
        m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                      250, 34, line, &g_text_small);
    } else if (activeChampion && !drewAuthenticFrames &&
               !m11_v1_chrome_mode_enabled(state) &&
               !m11_is_dm1_source_kind(state->sourceKind) &&
               state->sourceKind != M11_GAME_SOURCE_CSB_BOOT) {
        /* Legacy/procedural fallback only.  In normal V1 chrome mode,
         * C017 is reserved for the source leader-hand object name and
         * must not be repurposed as a champion-name/status label.  When
         * authentic action/spell graphics are active, the idle/icon
         * branch is owned by F0386-style action-hand icon cells;
         * champion names belong to F0387 menu mode and are drawn there
         * after a fresh graphic-10 blit. */
        int nameY = 34;
        m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                      227, nameY, champion, &g_text_small);
    }

    line[0] = '\0';
    if (activeChampion &&
        (state->showDebugHUD ||
         (!(drewAuthenticFrames && !state->showDebugHUD) &&
          !m11_v1_chrome_mode_enabled(state) &&
          !m11_is_dm1_source_kind(state->sourceKind) &&
          state->sourceKind != M11_GAME_SOURCE_CSB_BOOT))) {
        if (state->showDebugHUD) {
            snprintf(line, sizeof(line), "L%d HP%u ST%u",
                     mapDesc ? (int)mapDesc->level : 0,
                     (unsigned int)activeChampion->hp.current,
                     (unsigned int)activeChampion->stamina.current);
        } else {
            snprintf(line, sizeof(line), "HP%u ST%u",
                     (unsigned int)activeChampion->hp.current,
                     (unsigned int)activeChampion->stamina.current);
        }
    } else if (state->showDebugHUD) {
        snprintf(line, sizeof(line), "%s",
                 state->lastOutcome[0] != '\0' ? state->lastOutcome : "READY");
    }
    if (line[0] != '\0') {
        int statY = 44;
        int statX = 222;
        m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                      statX, statY, line, &g_text_small);
    }

    m11_draw_v1_leader_hand_object_name(state, framebuffer,
                                        framebufferWidth, framebufferHeight);

    if (state->showDebugHUD) {
        /* Debug mode: show I/S/L button labels */
        m11_draw_control_button(framebuffer, framebufferWidth, framebufferHeight,
                                M11_UTILITY_INSPECT_X, M11_UTILITY_BUTTON_Y,
                                M11_UTILITY_INSPECT_W, M11_UTILITY_BUTTON_H,
                                "I", -1,
                                accent, M11_COLOR_BLACK);
        m11_draw_control_button(framebuffer, framebufferWidth, framebufferHeight,
                                M11_UTILITY_SAVE_X, M11_UTILITY_BUTTON_Y,
                                M11_UTILITY_SAVE_W, M11_UTILITY_BUTTON_H,
                                "S", -1,
                                M11_COLOR_YELLOW, M11_COLOR_BLACK);
        m11_draw_control_button(framebuffer, framebufferWidth, framebufferHeight,
                                M11_UTILITY_LOAD_X, M11_UTILITY_BUTTON_Y,
                                M11_UTILITY_LOAD_W, M11_UTILITY_BUTTON_H,
                                "L", -1,
                                M11_COLOR_LIGHT_BLUE, M11_COLOR_BLACK);
    }

    /* Light level indicator: debug/procedural fallback only.  The
     * normal V1 action/spell strip is source-owned; invented light
     * bars make the DM1 action area look like a debug utility panel. */
    if (state->showDebugHUD ||
        (!drewAuthenticFrames && !m11_v1_chrome_mode_enabled(state) &&
         !m11_is_dm1_source_kind(state->sourceKind) &&
         state->sourceKind != M11_GAME_SOURCE_CSB_BOOT)) {
        int lightLevel = m11_compute_light_level(state);
        unsigned char lightColor;
        const char* lightLabel;
        int barW;
        if (lightLevel >= 200) {
            lightColor = M11_COLOR_YELLOW;
            lightLabel = "BRIGHT";
        } else if (lightLevel >= 120) {
            lightColor = M11_COLOR_BROWN;
            lightLabel = "LIT";
        } else if (lightLevel >= 50) {
            lightColor = M11_COLOR_DARK_GRAY;
            lightLabel = "DIM";
        } else {
            lightColor = M11_COLOR_BLACK;
            lightLabel = "DARK";
        }
        int barY = 67;
        int barFillY = barY + 1;
        /* PANEL.C F0337's palette thresholds top out at 99.  The utility
         * bar is diagnostic-only, so clamp its physical width without
         * changing the source-owned total returned by the light receipt. */
        if (lightLevel < 0) lightLevel = 0;
        if (lightLevel > 100) lightLevel = 100;
        barW = (lightLevel * 80) / 100;
        if (barW < 1 && lightLevel > 0) barW = 1;
        m11_draw_rect(framebuffer, framebufferWidth, framebufferHeight,
                      222, barY, 80, 5, M11_COLOR_DARK_GRAY);
        m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                      222, barFillY, 80, 3, M11_COLOR_DARK_GRAY);
        if (barW > 0) {
            m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                          222, barFillY, barW, 3, lightColor);
        }
        if (state->showDebugHUD) {
            m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                          222, 73, lightLabel, &g_text_small);
        }
    }
}

static void m11_draw_v1_movement_arrows(const M11_GameViewState* state,
                                        unsigned char* framebuffer,
                                        int framebufferWidth,
                                        int framebufferHeight) {
    int arrowX, arrowY, arrowW, arrowH;
    int outerX, outerY, outerW, outerH;
    DM1_V1_MovementArrowRectPc34 outerRect;
    DM1_V1_MovementArrowRectPc34 arrowRect;
    if (!state || !framebuffer || state->showDebugHUD ||
        !m11_v1_chrome_mode_enabled(state) ||
        (m11_v2_vertical_slice_enabled(state) &&
         state->sourceKind != M11_GAME_SOURCE_CSB_BOOT)) {
        return;
    }
    if (!dm1_v1_movement_arrows_outer_rect_pc34(&outerRect) ||
        !dm1_v1_movement_arrows_graphic_rect_pc34(&arrowRect)) {
        return;
    }
    outerX = outerRect.x;
    outerY = outerRect.y;
    outerW = outerRect.w;
    outerH = outerRect.h;
    arrowX = arrowRect.x;
    arrowY = arrowRect.y;
    arrowW = arrowRect.w;
    arrowH = arrowRect.h;

    /* Clear the full legacy movement-arrow box first.  ReDMCSB DATA.C
     * G0002_ai_Graphic562_Box_MovementArrows is 224..319 / 124..168;
     * PANEL.C and STARTUP2.C also use that box when hatching/clearing
     * disabled movement controls.  The PC source graphic itself is
     * 87×45 and sits in the layout-696 C009 panel area inside that box. */
    m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                  outerX, outerY, outerW, outerH, M11_COLOR_BLACK);

    /* Classic DM1 draws the movement controls as one native graphic,
     * not as Firestaff's old procedural button strip.  ReDMCSB
     * MENUDRAW.C F0395 calls F0660_(C013_GRAPHIC_MOVEMENT_ARROWS,
     * C009_ZONE_MOVEMENT_ARROWS, no transparency); the layout-696
     * C068..C073 arrow hit rectangles sit one pixel inside this
     * 87×45 source panel. */
    (void)m11_blit_panel_asset_native(state,
        framebuffer, framebufferWidth, framebufferHeight,
        (unsigned int)dm1_v1_movement_arrows_graphic_id_pc34(),
        arrowW, arrowH, arrowX, arrowY);
    /* The C013 panel is authentic CSB GRAPHICS.DAT material.  The extra
     * hatch/cyan keyboard cue below is an M11 affordance, not a CSBWin or
     * ReDMCSB framebuffer operation; CSB therefore keeps C013 unchanged
     * until a source-owned pressed-arrow state is available. */
    if (state->sourceKind != M11_GAME_SOURCE_CSB_BOOT) {
        m11_draw_v1_movement_arrow_visual_feedback(
            state, framebuffer, framebufferWidth, framebufferHeight);
    }
}

/* ReDMCSB SPELDRAW.C F0393 sends the current source panel pixels through
 * IMAGE.C F0698_InvertBox.  The retained M11 surface is indexed 4bpp, so
 * complementing its low nibble is the exact inverse operation; this never
 * creates a color, border, or font outside C009/C011's loaded pixels. */
static int m11_invert_dm1_pc34_indexed_box(
    unsigned char* framebuffer,
    int framebufferWidth,
    int framebufferHeight,
    int left,
    int top,
    int right,
    int bottom)
{
    int x;
    int y;

    if (!framebuffer || left > right || top > bottom ||
        right < 0 || bottom < 0 || left >= framebufferWidth ||
        top >= framebufferHeight) {
        return 0;
    }
    if (left < 0) left = 0;
    if (top < 0) top = 0;
    if (right >= framebufferWidth) right = framebufferWidth - 1;
    if (bottom >= framebufferHeight) bottom = framebufferHeight - 1;
    for (y = top; y <= bottom; ++y) {
        for (x = left; x <= right; ++x) {
            framebuffer[y * framebufferWidth + x] ^= 0x0fU;
        }
    }
    return 1;
}

static int m11_build_dm1_spell_area_overlay_plan(
    const M11_GameViewState* state,
    DM1_V1_ChampionPanelSpellAreaOverlayPlanPc34* outPlan)
{
    DM1_V1_ChampionPanelSpellAreaOverlayInputPc34 input;
    int active;
    int i;

    if (!state || !outPlan) return 0;
    /* CASTER.C F0394 owns G0514.  A visible panel without that selected
     * source caster is not a partially drawable legacy spell buffer: the
     * caller must retain the F0394 black clear instead. */
    active = state->dm1SpellCasting.magicCasterIndex;
    if (active < 0 || active >= state->world.party.championCount ||
        active >= DM1_V1_CPSAO_CHAMPION_COUNT_PC34) {
        return 0;
    }
    memset(&input, 0, sizeof(input));
    input.previous_caster_index = DM1_V1_CPSAO_CHAMPION_NONE_PC34;
    input.requested_caster_index = active;
    input.party_champion_count = state->world.party.championCount;
    input.symbol_step =
        (unsigned int)state->dm1SpellCasting.input[active].symbolStep;
    for (i = 0; i < input.party_champion_count; ++i) {
        input.champions[i].index = i;
        input.champions[i].current_health =
            state->world.party.champions[i].present
                ? (int)state->world.party.champions[i].hp.current : 0;
    }
    for (i = 0; i < input.party_champion_count; ++i) {
        memcpy(input.champions[i].symbols,
               state->dm1SpellCasting.input[i].symbols,
               sizeof(input.champions[i].symbols));
    }
    return dm1_v1_champion_panel_spell_area_overlay_plan_pc34(
        &input, outPlan) && outPlan->valid &&
        outPlan->drew_spell_area_controls &&
        outPlan->drew_available_symbols && outPlan->drew_champion_symbols;
}

static void m11_draw_v1_spell_area_overlay(const M11_GameViewState* state,
                                           unsigned char* framebuffer,
                                           int framebufferWidth,
                                           int framebufferHeight) {
    int spellW, spellH;
    int i;
    DM1_V1_ChampionPanelSpellAreaOverlayPlanPc34 plan;
    DM1_V1_ChampionPanelSpellAreaOverlayMaterialFactsPc34 facts;
    DM1_V1_ChampionPanelSpellAreaOverlayMaterialReceiptPc34 receipt;
    DM1_V1_ActionSpellM11BlitPlanPc34 blitPlan;
    if (!state || state->showDebugHUD || !m11_v1_chrome_mode_enabled(state) ||
        m11_v2_vertical_slice_enabled(state)) {
        return;
    }
    {
        /* CASTER.C F0394 clears DATA.C G0000 in every exit path. Keep this
         * separate from C009's narrower GRAPHICS.DAT blit rectangle so a
         * closed or rejected caster cannot retain the previous panel gutter. */
        DM1_V1_SpellAreaRectPc34 sourceBox =
            dm1_v1_spell_area_source_box_rect_pc34();
        if (!state->spellPanelOpen) {
            m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                          sourceBox.x, sourceBox.y, sourceBox.w, sourceBox.h,
                          M11_COLOR_BLACK);
            return;
        }
    }
    {
        /* ReDMCSB CASTER.C F0394 clears the physical G0000 box
         * (224,42,96x33 per DATA.C:119) and blits the stored 87x25 C009
         * into the C013 zone at 233,42.  spellX/spellY/spellW/spellH
         * track the C009 blit rect; clears use the G0000 box. */
        DM1_V1_SpellAreaRectPc34 spell = dm1_v1_spell_area_graphic_rect_pc34();
        if (!DM1_V1_SPELL_AREA_ZONE_ID_PC34) return;
        spellW = spell.w;
        spellH = spell.h;
    }
    /* CASTER.C F0394: clear G0000, paint C009, then copy C011 rows 1 and 2
     * to the two symbol lines.  C011 is not optional decoration: it owns
     * the controls behind the source-font glyphs. */
    memset(&facts, 0, sizeof(facts));
    facts.c009_graphic_index = DM1_V1_CPSAO_GFX_SPELL_AREA_BACKGROUND_PC34;
    facts.c009_loaded_pixels = m11_panel_asset_source_loaded(
        state,
        (unsigned int)DM1_V1_SPELL_AREA_BACKGROUND_GRAPHIC_ID_PC34,
        spellW, spellH, &facts.c009_width, &facts.c009_height);
    facts.c011_graphic_index = DM1_V1_CPSAO_GFX_SPELL_AREA_LINES_PC34;
    facts.c011_loaded_pixels = m11_panel_asset_source_loaded(
        state,
        (unsigned int)DM1_V1_SPELL_AREA_LINES_GRAPHIC_ID_PC34,
        DM1_V1_SPELL_AREA_LINES_WIDTH_PC34,
        DM1_V1_SPELL_AREA_LINES_HEIGHT_PC34,
        &facts.c011_width, &facts.c011_height);
    facts.m653_source_bound = m11_dm1_pc34_hud_font_is_source_bound(state);
    facts.m653_graphic_index =
        facts.m653_source_bound && g_activeOriginalFont
            ? M11_Font_ResolvedGraphicIndex(g_activeOriginalFont)
            : 0;
    if (!m11_build_dm1_spell_area_overlay_plan(state, &plan) ||
        !dm1_v1_champion_panel_spell_area_overlay_material_receipt_pc34(
            &plan, &facts, &receipt) ||
        !receipt.drawable) {
        DM1_V1_SpellAreaRectPc34 sourceBox =
            dm1_v1_spell_area_source_box_rect_pc34();
        m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                      sourceBox.x, sourceBox.y, sourceBox.w, sourceBox.h,
                      M11_COLOR_BLACK);
        return;
    }
    if (!dm1_v1_action_spell_m11_blit_plan_build_pc34(
            DM1_V1_ACTION_HUD_PRESENTATION_SPELL_EFFECT_PC34, 0,
            &blitPlan) || !blitPlan.accepted || blitPlan.blitCount != 3) {
        return;
    }
    m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                  blitPlan.clearX, blitPlan.clearY,
                  blitPlan.clearW, blitPlan.clearH, M11_COLOR_BLACK);
    /* C009 is the stored 87x25 spell-area background (GRAPHICS.DAT item
     * 0009) and blits into the C013 zone at 233,42.  DATA.C G0000
     * {224,319,42,74} is only the clear box, never the blit bounds. */
    if (!m11_blit_panel_asset_native(state,
        framebuffer, framebufferWidth, framebufferHeight,
        (unsigned int)blitPlan.blits[0].graphicId,
        blitPlan.blits[0].sourceW, blitPlan.blits[0].sourceH,
        blitPlan.blits[0].destinationX, blitPlan.blits[0].destinationY)) {
        return;
    }
    if (!m11_blit_panel_asset_region_native(state,
        framebuffer, framebufferWidth, framebufferHeight,
        (unsigned int)blitPlan.blits[1].graphicId,
        DM1_V1_SPELL_AREA_LINES_WIDTH_PC34,
        DM1_V1_SPELL_AREA_LINES_HEIGHT_PC34,
        blitPlan.blits[1].sourceX, blitPlan.blits[1].sourceY,
        blitPlan.blits[1].sourceW, blitPlan.blits[1].sourceH,
        blitPlan.blits[1].destinationX, blitPlan.blits[1].destinationY) ||
        !m11_blit_panel_asset_region_native(state,
        framebuffer, framebufferWidth, framebufferHeight,
        (unsigned int)blitPlan.blits[2].graphicId,
        DM1_V1_SPELL_AREA_LINES_WIDTH_PC34,
        DM1_V1_SPELL_AREA_LINES_HEIGHT_PC34,
        blitPlan.blits[2].sourceX, blitPlan.blits[2].sourceY,
        blitPlan.blits[2].sourceW, blitPlan.blits[2].sourceH,
        blitPlan.blits[2].destinationX, blitPlan.blits[2].destinationY)) {
        return;
    }
    /* SPELDRAW.C F0393 inverts only the living caster tab after C009 has
     * materialized it. The plan supplies the original inclusive box, so the
     * inverse cannot leak into another champion or rune line. */
    for (i = 0; i < plan.tab_count; ++i) {
        if (plan.line1[i].highlighted) {
            (void)m11_invert_dm1_pc34_indexed_box(
                framebuffer, framebufferWidth, framebufferHeight,
                plan.line1[i].tab_x0, plan.line1[i].tab_y0,
                plan.line1[i].tab_x1, plan.line1[i].tab_y1);
        }
    }
    /* MENUDRAW.C F0397 always repaints the six-symbol source window. A full
     * four-rune buffer must not suppress this line. */
    for (i = 0; i < plan.available_symbol_count; ++i) {
        (void)m11_draw_dm1_m653_cell_clipped_at_baseline(
            g_activeOriginalFont, framebuffer, framebufferWidth,
            framebufferHeight, plan.line2[i].screen_x,
            plan.line2[i].screen_y, (unsigned char)plan.line2[i].character,
            (unsigned char)plan.line2[i].color_cyan,
            (unsigned char)plan.line2[i].color_black,
            DM1_V1_CPSAO_LINE2_X0_PC34, DM1_V1_CPSAO_LINE2_Y0_PC34,
            DM1_V1_CPSAO_LINE2_X1_PC34 - DM1_V1_CPSAO_LINE2_X0_PC34 + 1,
            DM1_V1_CPSAO_LINE2_Y1_PC34 - DM1_V1_CPSAO_LINE2_Y0_PC34 + 1);
    }
    /* MENUDRAW.C F0398 owns exactly four output cells, space-padding the
     * tail so recant/caster changes cannot retain stale source glyphs. */
    for (i = 0; i < plan.champion_symbol_count; ++i) {
        (void)m11_draw_dm1_m653_cell_clipped_at_baseline(
            g_activeOriginalFont, framebuffer, framebufferWidth,
            framebufferHeight, plan.line3[i].screen_x,
            plan.line3[i].screen_y,
            (unsigned char)plan.line3[i].drawn_character,
            DM1_V1_CPSAO_COLOR_CYAN_PC34,
            DM1_V1_CPSAO_COLOR_BLACK_PC34,
            DM1_V1_CPSAO_LINE3_X0_PC34, DM1_V1_CPSAO_LINE3_Y0_PC34,
            DM1_V1_CPSAO_LINE3_X1_PC34 - DM1_V1_CPSAO_LINE3_X0_PC34 + 1,
            DM1_V1_CPSAO_LINE3_Y1_PC34 - DM1_V1_CPSAO_LINE3_Y0_PC34 + 1);
    }
}

/* ReDMCSB F0407/F0412 presentation is admitted as source commands before
 * this renderer sees it.  This M11 bridge binds the exact retained loader
 * surfaces, applies one live frame, and verifies its source ordering before
 * invoking the matching source-owned action/spell painters. */
static int m11_dm1_v1_action_spell_materials_from_loader(
    const M11_GameViewState* state,
    DM1_V1_ActionSpellHudSurfacePc34 surfaces[5],
    DM1_V1_ActionSpellHudMaterialSetPc34* outMaterials)
{
    static const int graphicIds[4] = {
        14,
        DM1_V1_ACTION_AREA_GRAPHIC_ID_PC34,
        DM1_V1_SPELL_AREA_BACKGROUND_GRAPHIC_ID_PC34,
        DM1_V1_SPELL_AREA_LINES_GRAPHIC_ID_PC34
    };
    int index;

    if (!state || !surfaces || !outMaterials || !state->assetsAvailable ||
        !m11_dm1_pc34_hud_font_is_source_bound(state)) return 0;
    memset(surfaces, 0, 5 * sizeof(*surfaces));
    for (index = 0; index < 4; ++index) {
        const M11_AssetSlot* slot = M11_AssetLoader_Load(
            (M11_AssetLoader*)&state->assetLoader,
            (unsigned int)graphicIds[index]);
        if (!slot || !slot->loaded || !slot->pixels || slot->width <= 0 ||
            slot->height <= 0) return 0;
        surfaces[index].graphicId = graphicIds[index];
        surfaces[index].width = slot->width;
        surfaces[index].height = slot->height;
        surfaces[index].pixelCount = slot->width * slot->height;
        surfaces[index].pixels = slot->pixels;
        surfaces[index].sourceOwned = 1;
    }
    surfaces[4].graphicId = M11_Font_ResolvedGraphicIndex(g_activeOriginalFont);
    surfaces[4].width = M11_FONT_BITMAP_WIDTH;
    surfaces[4].height = M11_FONT_BITMAP_HEIGHT;
    surfaces[4].pixelCount = M11_FONT_BITMAP_BYTES;
    surfaces[4].pixels = g_activeOriginalFont->bitmap;
    surfaces[4].sourceOwned = 1;
    if ((surfaces[4].graphicId != M11_FONT_GRAPHIC_INDEX_PC34 &&
         surfaces[4].graphicId != M11_FONT_GRAPHIC_INDEX_LEGACY) ||
        !surfaces[4].pixels) return 0;
    outMaterials->surfaces = surfaces;
    outMaterials->surfaceCount = 5;
    outMaterials->actionMenuRowCount = 0;
    return 1;
}

static int m11_dm1_v1_action_spell_material_surface_is_source_bound(
    const DM1_V1_ActionSpellHudSurfacePc34* surface)
{
    if (!surface || !surface->sourceOwned || !surface->pixels ||
        surface->width <= 0 || surface->height <= 0 ||
        surface->pixelCount <= 0) {
        return 0;
    }

    /* M653 is a raw 1bpp 1024x6 bitplane.  Its byte count is 768, not
     * width*height as for the indexed C009/C010/C011 surfaces.  Treating it
     * as an indexed bitmap rejected every otherwise valid F0407/F0412 frame
     * and cleared the real action/spell panel at the last M11 gate. */
    if (surface->graphicId == M11_FONT_GRAPHIC_INDEX_PC34 ||
        surface->graphicId == M11_FONT_GRAPHIC_INDEX_LEGACY) {
        return surface->width == M11_FONT_BITMAP_WIDTH &&
               surface->height == M11_FONT_BITMAP_HEIGHT &&
               surface->pixelCount == M11_FONT_BITMAP_BYTES;
    }

    return surface->pixelCount == surface->width * surface->height;
}

static unsigned int m11_dm1_v1_action_spell_material_fnv1a(
    const DM1_V1_ActionSpellHudMaterialSetPc34* materials)
{
    unsigned int hash = 2166136261u;
    int index;

    if (!materials || !materials->surfaces || materials->surfaceCount != 5) {
        return 0u;
    }
    for (index = 0; index < materials->surfaceCount; ++index) {
        const DM1_V1_ActionSpellHudSurfacePc34* surface =
            &materials->surfaces[index];
        unsigned int sourceHash;
        if (!m11_dm1_v1_action_spell_material_surface_is_source_bound(
                surface)) {
            return 0u;
        }
        sourceHash = m11_dm1_runtime_capture_fnv1a(
            surface->pixels, (size_t)surface->pixelCount);
        if (sourceHash == 0u) {
            return 0u;
        }
        hash ^= sourceHash;
        hash *= 16777619u;
        hash ^= (unsigned int)surface->graphicId;
        hash *= 16777619u;
    }
    return hash;
}

static void m11_clear_dm1_v1_action_spell_receipt_region(
    int presentationKind,
    unsigned char* framebuffer,
    int framebufferWidth,
    int framebufferHeight)
{
    if (presentationKind == DM1_V1_ACTION_HUD_PRESENTATION_ACTION_LOCK_PC34) {
        DM1_V1_ActionAreaRectPc34 action = {
            dm1_v1_box_action_area_x_pc34(),
            dm1_v1_box_action_area_y_pc34(),
            dm1_v1_box_action_area_w_pc34(),
            dm1_v1_box_action_area_h_pc34()
        };
        m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                      action.x, action.y, action.w, action.h,
                      (unsigned char)dm1_v1_action_area_clear_color_pc34());
    } else {
        /* F0394's physical G0000 clear is wider than its C009 blit. */
        m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                      224, 42, 96, 33, M11_COLOR_BLACK);
    }
}

/* The last F0407/F0412 HUD boundary accepts no painter until the source
 * feedback identity has crossed final-paint, lifecycle, bridge, and render
 * admission.  Failure deliberately returns no render permission. */
static int m11_dm1_v1_action_spell_final_paint_consume(
    const M11_GameViewState* state,
    const DM1_V1_LiveActionEffectPc34* live,
    const DM1_V1_ActionSpellHudPresentationReceiptPc34* presentation,
    const DM1_V1_ActionSpellExecutionReceiptPc34* execution,
    const DM1_V1_ActionSpellHudMaterialSetPc34* materials,
    const DM1_V1_ActionSpellRenderCommandReceiptPc34* commands,
    const DM1_V1_ActionSpellPresentationFrameStatePc34* frame,
    const DM1_V1_ActionSpellCommandFrameOrderReceiptPc34* order,
    DM1_V1_ActionSpellRenderConsumptionReceiptPc34* outRender)
{
    DM1_V1_ActionSpellFeedbackFramePresentationReceiptPc34 feedback;
    DM1_V1_ActionSpellFinalHudPaintReceiptPc34 paint;
    DM1_V1_ActionSpellFinalHudPaintLifecycleReceiptPc34 lifecycle;
    DM1_V1_ActionSpellFinalHudPaintFrameBridgeReceiptPc34 bridge;
    DM1_V1_ActionSpellRenderConsumptionLifecycleReceiptPc34 renderLifecycle;
    DM1_V1_ActionSpellHostRouteBridgeReceiptPc34 hostRoute;
    DM1_V1_ActionSpellHostRouteLifecycleReceiptPc34 hostRouteLifecycle;
    DM1_V1_ActionSpellM11ConsumptionReceiptPc34 m11Consumption;
    DM1_V1_ActionSpellM11ConsumptionLifecycleReceiptPc34 m11ConsumptionLifecycle;
    DM1_V1_ActionSpellM11HostRenderReceiptPc34 m11HostRender;
    DM1_V1_ActionSpellM11HostRenderLifecycleReceiptPc34 m11HostRenderLifecycle;
    DM1_V1_ActionSpellRuntimeFrameAdmissionReceiptPc34 runtimeAdmission;
    DM1_V1_ActionSpellSourceAssetRuntimeReceiptPc34 sourceAssets;
    M11_Dm1ActionSpellFinalPaintRuntime* runtime =
        &s_m11_dm1_action_spell_final_paint_runtime;
    unsigned int lifecycleGeneration;

    if (!state || !live || !presentation || !execution || !materials ||
        !commands || !frame || !order ||
        !outRender || !presentation->valid || !presentation->drawable ||
        !presentation->suppressSyntheticFallback || !execution->accepted ||
        !execution->readyForPresentation || !order->accepted ||
        !order->readyForPresentation || order->commandCount <= 0 ||
        state->world.gameTick == 0 || live->sourceTick == 0 ||
        live->serial == 0 || execution->commandFingerprint == 0 ||
        order->orderingFingerprint == 0 ||
        execution->sourceTick != live->sourceTick ||
        execution->serial != live->serial ||
        execution->presentationKind != presentation->presentationKind) {
        return 0;
    }
    if (runtime->owner != state) {
        memset(runtime, 0, sizeof(*runtime));
        runtime->owner = state;
    }
    lifecycleGeneration = runtime->lifecycle.active &&
        runtime->lifecycle.frameTick == state->world.gameTick
            ? runtime->lifecycle.lifecycleGeneration
            : runtime->lifecycle.lifecycleGeneration + 1u;
    if (lifecycleGeneration == 0u) {
        return 0;
    }

    memset(&feedback, 0, sizeof(feedback));
    feedback.accepted = 1;
    feedback.resultKind = presentation->presentationKind ==
        DM1_V1_ACTION_HUD_PRESENTATION_ACTION_LOCK_PC34
            ? DM1_V1_ACTION_SPELL_RESULT_ACTION_SUCCESS_PC34
            : DM1_V1_ACTION_SPELL_RESULT_SPELL_SUCCESS_PC34;
    feedback.presentationKind = presentation->presentationKind;
    feedback.championIndex = execution->championIndex;
    feedback.inputZoneId = 0;
    feedback.commandRepaintCurrent = 1;
    feedback.suppressSyntheticFallback = 1;
    feedback.frameTick = state->world.gameTick;
    feedback.sourceTick = execution->sourceTick;
    feedback.serial = execution->serial;
    feedback.commandFingerprint = execution->commandFingerprint;
    feedback.orderingFingerprint = order->orderingFingerprint;
    feedback.lifecycleGeneration = lifecycleGeneration;
    memset(&paint, 0, sizeof(paint));
    if (!dm1_v1_action_spell_final_hud_paint_build_pc34(&feedback, &paint)) {
        return 0;
    }
    memset(&lifecycle, 0, sizeof(lifecycle));
    if (!dm1_v1_action_spell_final_hud_paint_lifecycle_apply_pc34(
            &runtime->lifecycle, &paint, &lifecycle) || !lifecycle.accepted ||
        lifecycle.alreadyCurrent || !lifecycle.renderCurrentPaint) {
        return 0;
    }
    memset(&bridge, 0, sizeof(bridge));
    memset(outRender, 0, sizeof(*outRender));
    if (!dm1_v1_action_spell_final_hud_paint_frame_bridge_build_pc34(
            &paint, &lifecycle, &bridge) || !bridge.accepted ||
        !bridge.suppressSyntheticFallback ||
        !dm1_v1_action_spell_render_consumption_build_pc34(
            &bridge, outRender) || !outRender->accepted ||
        !outRender->renderReadyForHost ||
        !outRender->suppressSyntheticFallback ||
        outRender->sourceGraphicId != paint.sourceGraphicId ||
        outRender->sourceZoneId != paint.sourceZoneId ||
        outRender->frameTick != paint.frameTick ||
        outRender->sourceTick != paint.sourceTick ||
        outRender->serial != paint.serial) {
        return 0;
    }

    /* The original F0387/F0394 material receipt used to stop at the generic
     * final-paint gate.  Carry it through every source-owned host fence so
     * the M11 painter cannot consume C009/C010/C011 from a detached frame. */
    memset(&renderLifecycle, 0, sizeof(renderLifecycle));
    memset(&hostRoute, 0, sizeof(hostRoute));
    memset(&hostRouteLifecycle, 0, sizeof(hostRouteLifecycle));
    memset(&m11Consumption, 0, sizeof(m11Consumption));
    memset(&m11ConsumptionLifecycle, 0, sizeof(m11ConsumptionLifecycle));
    memset(&m11HostRender, 0, sizeof(m11HostRender));
    memset(&m11HostRenderLifecycle, 0, sizeof(m11HostRenderLifecycle));
    memset(&runtimeAdmission, 0, sizeof(runtimeAdmission));
    memset(&sourceAssets, 0, sizeof(sourceAssets));
    if (!dm1_v1_action_spell_render_consumption_lifecycle_apply_pc34(
            &runtime->renderConsumptionLifecycle, outRender, &renderLifecycle) ||
        !dm1_v1_action_spell_host_route_bridge_build_pc34(
            &renderLifecycle, &hostRoute) ||
        !dm1_v1_action_spell_host_route_lifecycle_apply_pc34(
            &runtime->hostRouteLifecycle, &hostRoute, &hostRouteLifecycle) ||
        !dm1_v1_action_spell_m11_consumption_build_pc34(
            &hostRouteLifecycle, &m11Consumption) ||
        !dm1_v1_action_spell_m11_consumption_lifecycle_apply_pc34(
            &runtime->m11ConsumptionLifecycle, &m11Consumption,
            &m11ConsumptionLifecycle) ||
        !dm1_v1_action_spell_m11_host_render_build_pc34(
            &m11ConsumptionLifecycle, &m11HostRender) ||
        !dm1_v1_action_spell_m11_host_render_lifecycle_apply_pc34(
            &runtime->m11HostRenderLifecycle, &m11HostRender,
            &m11HostRenderLifecycle) ||
        !dm1_v1_action_spell_runtime_frame_admission_apply_pc34(
            &runtime->runtimeAdmission, &renderLifecycle,
            &m11HostRenderLifecycle, &runtimeAdmission) ||
        !dm1_v1_action_spell_source_asset_runtime_build_pc34(
            materials, commands, frame, order, &runtimeAdmission, &sourceAssets) ||
        !sourceAssets.accepted || !sourceAssets.suppressSyntheticFallback ||
        sourceAssets.originalGraphicId != outRender->sourceGraphicId ||
        sourceAssets.originalZoneId != outRender->sourceZoneId ||
        sourceAssets.commandFingerprint != outRender->commandFingerprint ||
        sourceAssets.orderingFingerprint != outRender->orderingFingerprint) {
        return 0;
    }
    return 1;
}

static void m11_dm1_v1_action_spell_final_paint_clear_commands(
    const DM1_V1_ActionSpellRenderConsumptionReceiptPc34* render,
    int presentationKind,
    unsigned char* framebuffer,
    int framebufferWidth,
    int framebufferHeight)
{
    if (!render || !render->accepted || !render->renderReadyForHost) {
        return;
    }
    (void)presentationKind;
    m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                  render->clearRect.x, render->clearRect.y,
                  render->clearRect.w, render->clearRect.h,
                  M11_COLOR_BLACK);
}

/* Returns 1 after consuming an admitted receipt, 0 if no live F0407/F0412
 * presentation is active, and -1 after a source-material rejection. */
static int m11_draw_dm1_v1_action_spell_receipt_frame(
    const M11_GameViewState* state,
    unsigned char* framebuffer,
    int framebufferWidth,
    int framebufferHeight)
{
    const DM1_V1_LiveActionEffectPc34* live = NULL;
    DM1_V1_ActionSpellHudPresentationReceiptPc34 presentation;
    DM1_V1_ActionSpellHudSurfacePc34 surfaces[5];
    DM1_V1_ActionSpellHudMaterialSetPc34 materials;
    DM1_V1_ActionSpellHudMaterialReceiptPc34 materialReceipt;
    DM1_V1_ActionSpellPresentationSequenceReceiptPc34 sequence;
    DM1_V1_ActionSpellRenderCommandReceiptPc34 commands;
    DM1_V1_ActionSpellExecutionReceiptPc34 execution;
    DM1_V1_ActionSpellPresentationFrameStatePc34 frame;
    DM1_V1_ActionSpellPresentationApplyReceiptPc34 apply;
    DM1_V1_ActionSpellCommandFrameOrderReceiptPc34 order;
    DM1_V1_ActionSpellRenderConsumptionReceiptPc34 finalRender;
    DM1_V1_ActionSpellSourceFrameM11BridgeReceiptPc34 sourceBridge;
    DM1_V1_ActionSpellSourceFrameM11LifecycleReceiptPc34 sourceLifecycle;
    DM1_V1_ActionSpellRuntimeCaptureReceiptPc34 runtimeCapture;
    unsigned int materialFNV1a;
    int actionRows = 0;
    int index;

    if (!state || !framebuffer || !m11_is_dm1_source_kind(state->sourceKind) ||
        state->showDebugHUD || !m11_v1_chrome_mode_enabled(state) ||
        m11_v2_vertical_slice_enabled(state)) return 0;
    memset(&presentation, 0, sizeof(presentation));
    for (index = 0; index < state->dm1LiveActionEffects.count; ++index) {
        const DM1_V1_LiveActionEffectPc34* candidate =
            &state->dm1LiveActionEffects.entries[index];
        DM1_V1_ActionSpellHudPresentationReceiptPc34 candidatePresentation;
        if (!dm1_v1_live_action_effect_hud_presentation_pc34(
                candidate, &candidatePresentation) || !candidatePresentation.valid ||
            (candidatePresentation.presentationKind !=
                 DM1_V1_ACTION_HUD_PRESENTATION_ACTION_LOCK_PC34 &&
             candidatePresentation.presentationKind !=
                 DM1_V1_ACTION_HUD_PRESENTATION_SPELL_POTION_PC34 &&
             candidatePresentation.presentationKind !=
                 DM1_V1_ACTION_HUD_PRESENTATION_SPELL_PROJECTILE_PC34 &&
             candidatePresentation.presentationKind !=
                 DM1_V1_ACTION_HUD_PRESENTATION_SPELL_EFFECT_PC34)) {
            continue;
        }
        if (!live || candidate->serial > live->serial) {
            live = candidate;
            presentation = candidatePresentation;
        }
    }
    if (!live) return 0;
    s_m11_dm1_action_spell_last_presentation = presentation;

    if (presentation.presentationKind ==
        DM1_V1_ACTION_HUD_PRESENTATION_ACTION_LOCK_PC34) {
        unsigned char actionIndices[3];
        if (!M11_GameView_GetActingActionIndices(state, actionIndices)) {
            m11_clear_dm1_v1_action_spell_receipt_region(
                presentation.presentationKind, framebuffer,
                framebufferWidth, framebufferHeight);
            return -1;
        }
        actionRows = m11_count_source_action_menu_rows(actionIndices);
    }
    if (!m11_dm1_v1_action_spell_materials_from_loader(
            state, surfaces, &materials)) {
        m11_clear_dm1_v1_action_spell_receipt_region(
            presentation.presentationKind, framebuffer,
            framebufferWidth, framebufferHeight);
        return -1;
    }
    materials.actionMenuRowCount = actionRows;
    materialFNV1a = m11_dm1_v1_action_spell_material_fnv1a(&materials);
    if (materialFNV1a == 0u) {
        m11_clear_dm1_v1_action_spell_receipt_region(
            presentation.presentationKind, framebuffer,
            framebufferWidth, framebufferHeight);
        return -1;
    }
    if (!dm1_v1_live_action_effect_hud_bind_materials_pc34(
            &presentation, &materials, &materialReceipt) ||
        !dm1_v1_action_spell_presentation_sequence_build_pc34(
            &presentation, &materialReceipt, actionRows, &sequence) ||
        !dm1_v1_action_spell_render_command_admit_pc34(
            &sequence, &materials, &commands) ||
        !dm1_v1_action_spell_execution_receipt_build_pc34(
            live, &presentation, &commands, &execution)) {
        m11_clear_dm1_v1_action_spell_receipt_region(
            presentation.presentationKind, framebuffer,
            framebufferWidth, framebufferHeight);
        return -1;
    }
    memset(&frame, 0, sizeof(frame));
    dm1_v1_action_spell_presentation_frame_begin_pc34(
        &frame, state->world.gameTick);
    if (!dm1_v1_action_spell_presentation_apply_pc34(
            &frame, &execution, &commands, &materials, &apply) ||
        !dm1_v1_action_spell_command_frame_order_build_pc34(
            &frame, &apply, &materials, &order) || !order.accepted ||
        !order.readyForPresentation) {
        m11_clear_dm1_v1_action_spell_receipt_region(
            presentation.presentationKind, framebuffer,
            framebufferWidth, framebufferHeight);
        return -1;
    }
    for (index = 0; index < order.commandCount; ++index) {
        if (order.orderedSurfaceIndices[index] !=
            frame.commands[index].sourceSurfaceIndex) {
            m11_clear_dm1_v1_action_spell_receipt_region(
                presentation.presentationKind, framebuffer,
                framebufferWidth, framebufferHeight);
            return -1;
        }
    }

    memset(&finalRender, 0, sizeof(finalRender));
    if (!m11_dm1_v1_action_spell_final_paint_consume(
            state, live, &presentation, &execution, &materials, &commands,
            &frame, &order, &finalRender)) {
        m11_clear_dm1_v1_action_spell_receipt_region(
            presentation.presentationKind, framebuffer,
            framebufferWidth, framebufferHeight);
        return -1;
    }
    m11_dm1_v1_action_spell_final_paint_clear_commands(
        &finalRender, presentation.presentationKind, framebuffer,
        framebufferWidth, framebufferHeight);

    /* The command receipt's blit/font ordering now owns this repaint.  Both
     * painters below already use only those exact GRAPHICS.DAT surfaces and
     * the authenticated M653 font; no generic text or fallback path remains. */
    if (presentation.presentationKind ==
        DM1_V1_ACTION_HUD_PRESENTATION_ACTION_LOCK_PC34) {
        if (!m11_draw_dm_action_menu(state, framebuffer,
                                     framebufferWidth, framebufferHeight)) {
            m11_clear_dm1_v1_action_spell_receipt_region(
                presentation.presentationKind, framebuffer,
                framebufferWidth, framebufferHeight);
            return -1;
        }
    } else {
        m11_draw_v1_spell_area_overlay(state, framebuffer,
                                       framebufferWidth, framebufferHeight);
    }
    materialFNV1a ^= finalRender.commandFingerprint;
    materialFNV1a *= 16777619u;
    materialFNV1a ^= finalRender.orderingFingerprint;
    materialFNV1a *= 16777619u;
    if (materialFNV1a == 0u) {
        m11_clear_dm1_v1_action_spell_receipt_region(
            presentation.presentationKind, framebuffer,
            framebufferWidth, framebufferHeight);
        return -1;
    }
    /* The capture gate consumes the source-frame lifecycle, not the painter's
     * success alone.  It carries only the admitted GRAPHICS.DAT identities;
     * no host surface or fallback artwork is introduced here. */
    memset(&sourceBridge, 0, sizeof(sourceBridge));
    sourceBridge.accepted = 1;
    sourceBridge.m11SourceFrameReady = 1;
    sourceBridge.presentationKind = presentation.presentationKind;
    sourceBridge.originalGraphicId = finalRender.sourceGraphicId;
    sourceBridge.originalZoneId = finalRender.sourceZoneId;
    sourceBridge.companionGraphicId =
        presentation.presentationKind ==
            DM1_V1_ACTION_HUD_PRESENTATION_ACTION_LOCK_PC34 ? 0 :
        DM1_V1_SPELL_AREA_LINES_GRAPHIC_ID_PC34;
    sourceBridge.sourceAssetCount = sourceBridge.companionGraphicId ? 2 : 1;
    sourceBridge.sourceCommandCount = order.commandCount;
    sourceBridge.suppressSyntheticFallback = 1;
    sourceBridge.frameTick = finalRender.frameTick;
    sourceBridge.sourceTick = finalRender.sourceTick;
    sourceBridge.serial = finalRender.serial;
    sourceBridge.commandFingerprint = finalRender.commandFingerprint;
    sourceBridge.orderingFingerprint = finalRender.orderingFingerprint;
    memset(&sourceLifecycle, 0, sizeof(sourceLifecycle));
    memset(&runtimeCapture, 0, sizeof(runtimeCapture));
    if (!dm1_v1_action_spell_source_frame_m11_lifecycle_apply_pc34(
            &s_m11_dm1_action_spell_final_paint_runtime.captureLifecycle,
            &sourceBridge, &sourceLifecycle) ||
        !dm1_v1_action_spell_runtime_capture_build_pc34(
            &sourceLifecycle, &runtimeCapture) || !runtimeCapture.accepted ||
        !runtimeCapture.runtimeCaptureCurrent ||
        !runtimeCapture.suppressSyntheticFallback ||
        runtimeCapture.frameTick != state->world.gameTick ||
        runtimeCapture.originalGraphicId != finalRender.sourceGraphicId ||
        runtimeCapture.originalZoneId != finalRender.sourceZoneId ||
        runtimeCapture.sourceTick != finalRender.sourceTick ||
        runtimeCapture.serial != finalRender.serial ||
        runtimeCapture.commandFingerprint != finalRender.commandFingerprint ||
        runtimeCapture.orderingFingerprint != finalRender.orderingFingerprint) {
        m11_clear_dm1_v1_action_spell_receipt_region(
            presentation.presentationKind, framebuffer,
            framebufferWidth, framebufferHeight);
        return -1;
    }
    m11_dm1_runtime_capture_route_evidence(
        state, M11_DM1_RUNTIME_CAPTURE_ACTION_SPELL, 1,
        1, 1,
        runtimeCapture.sourceTick, runtimeCapture.serial, materialFNV1a);
    return 1;
}

static void m11_apply_viewport_turn_pan(unsigned char* framebuffer,
                                        int framebufferWidth,
                                        int framebufferHeight,
                                        int x,
                                        int y,
                                        int w,
                                        int h,
                                        int turnPanOffsetX) {
    int panPixels;
    int yy;
    int maxPanPixels;
    if (!framebuffer || framebufferWidth <= 0 || framebufferHeight <= 0 ||
        w <= 0 || h <= 0 || turnPanOffsetX == 0) {
        return;
    }
    maxPanPixels = w / 4;
    if (maxPanPixels < 1) {
        return;
    }
    panPixels = (int)(((int64_t)turnPanOffsetX * (int64_t)maxPanPixels) /
                      (int64_t)DM1_V2_SUBPIXEL_SCALE);
    if (panPixels == 0) {
        panPixels = turnPanOffsetX > 0 ? 1 : -1;
    }
    if (panPixels > maxPanPixels) panPixels = maxPanPixels;
    if (panPixels < -maxPanPixels) panPixels = -maxPanPixels;

    /* V2-only presentation pan. ReDMCSB COMMAND.C:2150-2152 and
     * CLIKMENU.C:142-173 still own the accepted logical turn and
     * GAMELOOP.C:90 redraws from the discrete party direction. This pass
     * only translates the already-rendered viewport pixels for Custom/V2. */
    for (yy = 0; yy < h; ++yy) {
        int py = y + yy;
        unsigned char* row;
        if (py < 0 || py >= framebufferHeight) {
            continue;
        }
        if (x < 0 || x + w > framebufferWidth) {
            continue;
        }
        row = &framebuffer[py * framebufferWidth + x];
        if (panPixels > 0) {
            memmove(row + panPixels, row, (size_t)(w - panPixels));
            memset(row, M11_COLOR_BLACK, (size_t)panPixels);
        } else {
            int shift = -panPixels;
            memmove(row, row + shift, (size_t)(w - shift));
            memset(row + (w - shift), M11_COLOR_BLACK, (size_t)shift);
        }
    }
}

static void m11_apply_viewport_motion_pan(unsigned char *framebuffer,
                                          int framebufferWidth,
                                          int framebufferHeight,
                                          int x, int y, int w, int h,
                                          int offset_x, int offset_y)
{
    int max_x;
    int max_y;
    int pan_x;
    int pan_y;
    int row;

    if (!framebuffer || framebufferWidth <= 0 || framebufferHeight <= 0 ||
        x < 0 || y < 0 || w <= 0 || h <= 0 || x + w > framebufferWidth ||
        y + h > framebufferHeight || (offset_x == 0 && offset_y == 0)) {
        return;
    }
    max_x = w / 4;
    max_y = h / 4;
    pan_x = (int)(((int64_t)offset_x * (int64_t)max_x) / 256);
    pan_y = (int)(((int64_t)offset_y * (int64_t)max_y) / 256);
    if (offset_x != 0 && pan_x == 0) pan_x = offset_x > 0 ? 1 : -1;
    if (offset_y != 0 && pan_y == 0) pan_y = offset_y > 0 ? 1 : -1;
    if (pan_x > max_x) pan_x = max_x;
    if (pan_x < -max_x) pan_x = -max_x;
    if (pan_y > max_y) pan_y = max_y;
    if (pan_y < -max_y) pan_y = -max_y;

    /* Present-only translation after the source viewport has completed. The
     * revealed band remains black rather than borrowing a synthetic dungeon
     * cell; the next source frame fills it as the V1 tick completes. */
    if (pan_y > 0) {
        for (row = h - 1; row >= pan_y; --row) {
            memmove(&framebuffer[(y + row) * framebufferWidth + x],
                    &framebuffer[(y + row - pan_y) * framebufferWidth + x],
                    (size_t)w);
        }
        for (row = 0; row < pan_y; ++row) {
            memset(&framebuffer[(y + row) * framebufferWidth + x],
                   M11_COLOR_BLACK, (size_t)w);
        }
    } else if (pan_y < 0) {
        int shift = -pan_y;
        for (row = 0; row < h - shift; ++row) {
            memmove(&framebuffer[(y + row) * framebufferWidth + x],
                    &framebuffer[(y + row + shift) * framebufferWidth + x],
                    (size_t)w);
        }
        for (row = h - shift; row < h; ++row) {
            memset(&framebuffer[(y + row) * framebufferWidth + x],
                   M11_COLOR_BLACK, (size_t)w);
        }
    }
    if (pan_x != 0) {
        for (row = 0; row < h; ++row) {
            unsigned char *pixels = &framebuffer[(y + row) * framebufferWidth + x];
            if (pan_x > 0) {
                memmove(pixels + pan_x, pixels, (size_t)(w - pan_x));
                memset(pixels, M11_COLOR_BLACK, (size_t)pan_x);
            } else {
                int shift = -pan_x;
                memmove(pixels, pixels + shift, (size_t)(w - shift));
                memset(pixels + w - shift, M11_COLOR_BLACK, (size_t)shift);
            }
        }
    }
}

static void m11_repaint_dm1_f0128_front_wall_inscription(
    const M11_GameViewState* state,
    unsigned char* framebuffer,
    int framebufferWidth,
    int framebufferHeight)
{
    M11_ViewportCell frontCell;
    DM1_V1_ViewportInscriptionReceiptPc34 viewportReceipt;

    /* The clear action belongs to the DM1 F0128/F0107 receipt even when no
     * current world cell is available. M11 only performs that action. */
    if (!dm1_v1_viewport_inscription_receipt_from_world_pc34(
            NULL, -1, THING_NONE,
            DM1_V1_INSCRIPTION_PROJECTION_CLEAR_ONLY_PC34,
            0, &viewportReceipt) ||
        !viewportReceipt.clearPreviousMaterial) {
        return;
    }
    m11_dm1_invalidate_wall_inscription_material();
    if (!state || !framebuffer ||
        !m11_sample_viewport_cell(state, 1, 0, &frontCell) ||
        !frontCell.valid || !m11_viewport_cell_is_wall_like(&frontCell)) {
        return;
    }
    if (!dm1_v1_viewport_inscription_receipt_from_selected_wall_pc34(
            state->world.things, frontCell.inscriptionTextIndex,
            DM1_V1_INSCRIPTION_PROJECTION_D1C_FRONT_PC34,
            frontCell.championPortraitOrdinal >= 0, &viewportReceipt)) {
        return;
    }
    /* ReDMCSB DUNGEON.C F0172/F0174 reselects G0290 from the current party
     * tuple, then DUNVIEW.C F0107:3592-3706 decodes and draws M648. The
     * receipt is frame-local and is clear-only for C127 or hidden text. */
    if (viewportReceipt.drawFrontMaterial) {
        m11_draw_dm1_front_wall_inscription_material(
            state, &viewportReceipt.frontMaterial, framebuffer,
            framebufferWidth, framebufferHeight);
    }
}

/* ── V2.2 GPU render path: per-frame V22 shape cache ─────────
 *
 * The V22 cache is implemented in m11_v22_shape_cache_pc34.c (its
 * own module so tests don't need to pull in the full M11 game
 * view). m11_draw_viewport populates it from the sampled cells
 * after the sample loop, and the per-cell draw passes can
 * consult m11_v22_shape_cache_get(depth, lateral) to read the
 * V22 shape data.
 *
 * The actual swap of draw primitives (replacing the V1 GRAPHICS.DAT
 * bitmap blit with a V22 modern art draw call) is a follow-up;
 * this commit adds the data flow so the per-cell pass has the V22
 * params available when the swap is implemented.
 *
 * Source-lock: ReDMCSB DUNVIEW.C:6697-6816 (composition draw order).
 */

/* ── F0128 per-square scheduler live bridge ─────────────────────────
 * ReDMCSB DUNVIEW.C F0128:8318-8561 visits the 19 view squares in a
 * fixed source order and dispatches each square's merged F0104/F0107/
 * F0108/F0111/F0113/F0115 material families.  The DM1-owned contract
 * module dm1_v1_f0128_per_square_scheduler_pc34_compat owns that
 * schedule; this bridge feeds it the live sampled view and lets the
 * verified plan drive the F0115 content loop below.  Contract-only:
 * the plan sequences existing source-material passes; it never draws
 * pixels and never substitutes host material. */

/* View-square -> (relForward, relSide) cone coordinates, in exact F0128
 * source visit order (DUNVIEW.C:8479-8542).  Squares inside the 3x3
 * sample reuse its cell (cellDepth/cellSide >= 0); the rest are sampled
 * on demand. */
typedef struct M11_Dm1F0128ViewSquareMap {
    int square;
    int relForward;
    int relSide;
    int cellDepth;
    int cellSide;
} M11_Dm1F0128ViewSquareMap;

static const M11_Dm1F0128ViewSquareMap kM11Dm1F0128ViewSquares[DM1_V1_F0128_VIEW_SQUARE_COUNT] = {
    { DM1_V1_F0128_VIEW_SQUARE_D4L,  4, -1, -1, -1 },
    { DM1_V1_F0128_VIEW_SQUARE_D4R,  4,  1, -1, -1 },
    { DM1_V1_F0128_VIEW_SQUARE_D4C,  4,  0, -1, -1 },
    { DM1_V1_F0128_VIEW_SQUARE_D3L2, 3, -2, -1, -1 },
    { DM1_V1_F0128_VIEW_SQUARE_D3R2, 3,  2, -1, -1 },
    { DM1_V1_F0128_VIEW_SQUARE_D3L,  3, -1,  2,  0 },
    { DM1_V1_F0128_VIEW_SQUARE_D3R,  3,  1,  2,  2 },
    { DM1_V1_F0128_VIEW_SQUARE_D3C,  3,  0,  2,  1 },
    { DM1_V1_F0128_VIEW_SQUARE_D2L2, 2, -2, -1, -1 },
    { DM1_V1_F0128_VIEW_SQUARE_D2R2, 2,  2, -1, -1 },
    { DM1_V1_F0128_VIEW_SQUARE_D2L,  2, -1,  1,  0 },
    { DM1_V1_F0128_VIEW_SQUARE_D2R,  2,  1,  1,  2 },
    { DM1_V1_F0128_VIEW_SQUARE_D2C,  2,  0,  1,  1 },
    { DM1_V1_F0128_VIEW_SQUARE_D1L,  1, -1,  0,  0 },
    { DM1_V1_F0128_VIEW_SQUARE_D1R,  1,  1,  0,  2 },
    { DM1_V1_F0128_VIEW_SQUARE_D1C,  1,  0,  0,  1 },
    { DM1_V1_F0128_VIEW_SQUARE_D0L,  0, -1, -1, -1 },
    { DM1_V1_F0128_VIEW_SQUARE_D0R,  0,  1, -1, -1 },
    { DM1_V1_F0128_VIEW_SQUARE_D0C,  0,  0, -1, -1 }
};

/* Maps a sampled cell to the view-relative F0128 element
 * (DEFS.H:1007-1017 C16..C19 orientation variants).  Doors and stairs
 * are front-facing when the party looks along the square's orientation
 * axis (bit 0x08, the same axis rule DUNVIEW.C applies to stairs;
 * dm1_v1_stairs_front_facing_pc34).  D0-row doors are always seen from
 * inside the party square, so they stay C16 door-side — F0125/F0126/
 * F0127 have no source door-front pass and the contract fails closed
 * on one. */
static int m11_dm1_f0128_scheduler_element_for_cell(
    const M11_GameViewState* state,
    const M11_ViewportCell* cell,
    int relForward)
{
    switch (cell->elementType) {
    case DUNGEON_ELEMENT_WALL:
        return DM1_V1_F0128_ELEMENT_WALL;
    case DUNGEON_ELEMENT_CORRIDOR:
        return DM1_V1_F0128_ELEMENT_CORRIDOR;
    case DUNGEON_ELEMENT_PIT:
        return DM1_V1_F0128_ELEMENT_PIT;
    case DUNGEON_ELEMENT_STAIRS:
        return dm1_v1_stairs_front_facing_pc34(
                   cell->square, (int)state->world.party.direction)
                   ? DM1_V1_F0128_ELEMENT_STAIRS_FRONT
                   : DM1_V1_F0128_ELEMENT_STAIRS_SIDE;
    case DUNGEON_ELEMENT_DOOR:
        if (relForward > 0) {
            int doorNorthSouth = cell->doorVertical != 0;
            int partyNorthSouth =
                ((state->world.party.direction & 3u) & 1u) == 0u;
            if (doorNorthSouth == partyNorthSouth) {
                return DM1_V1_F0128_ELEMENT_DOOR_FRONT;
            }
        }
        return DM1_V1_F0128_ELEMENT_DOOR_SIDE;
    case DUNGEON_ELEMENT_TELEPORTER:
        return DM1_V1_F0128_ELEMENT_TELEPORTER;
    case DUNGEON_ELEMENT_FAKEWALL:
        return DM1_V1_F0128_ELEMENT_FAKEWALL;
    default:
        return -1;
    }
}

/* Fills one scheduler square from a sampled cell.  Out-of-view samples
 * arrive as invalid cells whose element defaults to a wall, matching
 * the source's solid map edge. */
static void m11_dm1_f0128_scheduler_input_from_cell(
    const M11_GameViewState* state,
    const M11_ViewportCell* cell,
    int relForward,
    DM1_V1_F0128SchedulerSquarePc34* out)
{
    out->element = m11_dm1_f0128_scheduler_element_for_cell(
        state, cell, relForward);
    /* SquareAspect[M554] (DUNGEON.C F0172): pit bit 0x04 clear = the pit
     * shows; teleporter bit 0x04 set = the blue haze shows (dmweb
     * dungeon format; dm1_v1_floor_pit/dm1_v1_field_teleporter masks). */
    if (cell->elementType == DUNGEON_ELEMENT_PIT) {
        out->pitOrTeleporterVisible =
            !dm1_v1_floor_pit_square_uses_invisible_pc34(cell->square);
    } else if (cell->elementType == DUNGEON_ELEMENT_TELEPORTER) {
        out->pitOrTeleporterVisible =
            (cell->square & DM1_FIELD_TELEPORTER_VISIBLE_MASK_PC34) != 0 &&
            (cell->square & DM1_FIELD_TELEPORTER_OPEN_MASK_PC34) != 0;
    } else {
        out->pitOrTeleporterVisible = 0;
    }
    /* F0107 checks the front wall ornament's alcove predicate on the
     * wall facing the party (M552).  The F0149 classification runs on the
     * F0174-wired current-map alcove list (G0267 equivalent). */
    m11_dm1_wire_current_map_alcove_list((M11_GameViewState*)state,
                                         state->world.party.mapIndex);
    out->frontWallOrnamentIsAlcove =
        cell->elementType == DUNGEON_ELEMENT_WALL &&
        cell->wallOrnamentOrdinal >= 0 &&
        dm1_v1_wall_ornament_is_alcove_local_ordinal_pc34(
            cell->wallOrnamentOrdinal);
    out->hasFloorOrnament = cell->floorOrnamentOrdinal > 0;
}

/* Builds and verifies the live F0128 plan for the current view.
 * Returns 1 only when the contract build and the invariant re-verify
 * both succeed; the receipt records the outcome either way. */
static int m11_dm1_f0128_build_live_view_plan(
    const M11_GameViewState* state,
    const M11_ViewportCell cells[3][3],
    DM1_V1_F0128SchedulerPlanPc34* outPlan)
{
    DM1_V1_F0128SchedulerSquarePc34 squares[DM1_V1_F0128_VIEW_SQUARE_COUNT];
    int i;
    if (!state || !cells || !outPlan) {
        return 0;
    }
    for (i = 0; i < DM1_V1_F0128_VIEW_SQUARE_COUNT; ++i) {
        const M11_Dm1F0128ViewSquareMap* map = &kM11Dm1F0128ViewSquares[i];
        const M11_ViewportCell* cell;
        M11_ViewportCell sampled;
        if (map->cellDepth >= 0) {
            cell = &cells[map->cellDepth][map->cellSide];
        } else {
            memset(&sampled, 0, sizeof(sampled));
            (void)m11_sample_viewport_cell(state, map->relForward,
                                           map->relSide, &sampled);
            cell = &sampled;
        }
        m11_dm1_f0128_scheduler_input_from_cell(state, cell,
                                                map->relForward,
                                                &squares[map->square]);
    }
    s_m11_dm1_f0128_per_square_scheduler_receipt.valid = 1;
    if (!DM1_V1_F0128_PerSquareSchedulerBuildPc34Compat(squares, outPlan)) {
        return 0;
    }
    s_m11_dm1_f0128_per_square_scheduler_receipt.stepCount =
        outPlan->stepCount;
    s_m11_dm1_f0128_per_square_scheduler_receipt.scheduleHash =
        (unsigned long)outPlan->scheduleHash;
    if (!DM1_V1_F0128_PerSquareSchedulerVerifyPc34Compat(outPlan)) {
        return 0;
    }
    s_m11_dm1_f0128_per_square_scheduler_receipt.planReady = 1;
    return 1;
}

typedef struct M11_Dm1F0128DispatchContext {
    const M11_GameViewState *state;
    int preflightCount;
    int executeCount;
} M11_Dm1F0128DispatchContext;

static int m11_dm1_f0128_preflight_source_step(
    void *context, const DM1_V1_F0128SchedulerStepPc34 *step)
{
    M11_Dm1F0128DispatchContext *dispatch =
        (M11_Dm1F0128DispatchContext *)context;

    /* The scheduler already established the exact F0128 operation and
     * square order. M11 may consume it only with a mounted original PC34
     * catalog. Do not revive primitive drawing for an unmounted or partly
     * initialized GRAPHICS.DAT source. */
    if (!dispatch || !dispatch->state || !step ||
        !dispatch->state->assetsAvailable ||
        !M11_AssetLoader_IsReady(&dispatch->state->assetLoader)) {
        return 0;
    }
    ++dispatch->preflightCount;
    return 1;
}

static void m11_dm1_f0128_execute_source_step(
    void *context, const DM1_V1_F0128SchedulerStepPc34 *step)
{
    M11_Dm1F0128DispatchContext *dispatch =
        (M11_Dm1F0128DispatchContext *)context;

    /* Existing F0104/F0107/F0108/F0111/F0113/F0115 consumers own their
     * exact source bitmap/palette checks. This marks only a successful
     * schedule admission and deliberately supplies no substitute pixels. */
    if (dispatch && step) {
        ++dispatch->executeCount;
    }
}

static int m11_dm1_f0128_dispatch_live_view_plan(
    const M11_GameViewState *state,
    const DM1_V1_F0128SchedulerPlanPc34 *plan)
{
    M11_Dm1F0128DispatchContext dispatch;
    int rejectedStep = -1;

    memset(&dispatch, 0, sizeof(dispatch));
    dispatch.state = state;
    if (!DM1_V1_F0128_PerSquareSchedulerDispatchPc34Compat(
            plan, m11_dm1_f0128_preflight_source_step,
            m11_dm1_f0128_execute_source_step, &dispatch, &rejectedStep)) {
        return 0;
    }
    return dispatch.preflightCount == plan->stepCount &&
           dispatch.executeCount == plan->stepCount && rejectedStep == -1;
}

static void m11_draw_viewport(const M11_GameViewState* state,
                              unsigned char* framebuffer,
                              int framebufferWidth,
                              int framebufferHeight) {
    /* Phase 5 smooth movement: retrieve camera offset from state.
     * V1 paths set camera_offset_x/y=0 (no-op).  V2 paths set these
     * to the interpolated pixel nudge from dm1_v2_camera_controller_pc34.
     * The offset shifts the viewport's view-cone sampling so the entire
     * dungeon view glides smoothly between source-accepted positions.
     *
     * Source-lock: DUNGEON.C:1371-1391 applies direction-step tables to
     * produce discrete map coordinates; DUNVIEW.C:8606-8612 renders from
     * those coordinates without offset.  The offset is purely a V2
     * presentation layer — it does NOT change cooldowns, collision,
     * sensors, creature timing, or redraw cadence. */
    int camX = state->camera_offset_x;
    int camY = state->camera_offset_y;
    int camDir = state->camera_interpolated_facing;
    int turnPanX = dm1_v2_camera_turn_pan_offset_x(&state->p5_camera);
    int csbMotionPanX = 0;
    int csbMotionPanY = 0;
    if (state->sourceKind == M11_GAME_SOURCE_CSB_BOOT &&
        state->presentationMode != M12_PRESENTATION_V1_ORIGINAL &&
        csb_v2_runtime_is_bound()) {
        /* CSB owns a separate V2 animation clock. Consume its cardinal
         * turn-pan here after the source viewport has rendered, exactly as
         * the DM1 V2 camera path does. This remains presentation-only. */
        turnPanX = csb_v2_smooth_turn_pan_offset_x();
        csb_v2_runtime_get_presentation_offset(&csbMotionPanX,
                                                &csbMotionPanY);
    }
    (void)camDir; /* facing interpolation used by creature sprite pass */
    static const M11_ViewRect viewport = {M11_VIEWPORT_X, M11_VIEWPORT_Y, M11_VIEWPORT_W, M11_VIEWPORT_H};
    static const M11_ViewRect frames[4] = {
        {8, 41, 208, 120},
        {34, 54, 156, 88},
        {58, 68, 108, 58},
        {78, 79, 68, 36}
    };
    M11_ViewportCell cells[3][3];
    DM1_ViewportLaneVisibilityReceiptPc34 visibility;
    DM1_V1_F0128SchedulerPlanPc34 dm1F0128Plan;
    int dm1F0128PlanReady;
    int dm1F0128PlanDispatched;
    int depth;
    int occluded = 0;
    int maxVisibleForward;
    (void)camX; (void)camY; /* applied via view-cone sampling shift in each draw pass */

    memset(cells, 0, sizeof(cells));

    for (depth = 0; depth < 3; ++depth) {
        int side;
        for (side = 0; side < 3; ++side) {
            (void)m11_sample_viewport_cell(state, depth + 1, side - 1, &cells[depth][side]);
        }
    }
    /* ReDMCSB DUNGEON.C F0172 (2608-2612) publishes the visible HoC
     * mirror once, then DUNVIEW.C consumes it across wall and F0115 layers. */
    cells[0][1].dm1RuntimeRenderDecisionReady =
        m11_build_dm1_hoc_front_mirror_runtime_decision(
            state, &cells[0][1], &cells[0][1].dm1RuntimeRenderDecision);
    /* The DM1 V2.2 cache remains a DM1-owned presentation helper.  CSB's
     * old 3x3 cache carried hard-coded material parameters and no original
     * F0128 command, clip, palette or Thing-chain receipt.  The CSB live
     * path therefore never populates it: CSB V2.2 may replace pixels only
     * inside csb_v1_viewport_consume_first_frame_material_raster_pc34(),
     * where each admitted source command owns those facts. */
    visibility = m11_dm1_lane_visibility(cells);
    maxVisibleForward = visibility.max_visible_forward;
    {
        unsigned char raw_squares[3][3];
        int d, s;
        for (d = 0; d < 3; ++d) {
            for (s = 0; s < 3; ++s) {
                raw_squares[d][s] = cells[d][s].square;
                /* F0128's nearest closed D1/D2/D3 center square owns the
                 * final wall/door pixels. Do not let a later V2.2 cell pass
                 * reopen its occluded depth with generated art. */
                if (visibility.nearest_blocking_center_depth_index >= 0 &&
                    d > visibility.nearest_blocking_center_depth_index) {
                    raw_squares[d][s] = M11_V22_SHAPE_CACHE_HIDDEN_SQUARE;
                }
                /* ReDMCSB DUNVIEW.C F0128 draws side squares far-to-near;
                 * a nearer non-open side square occludes farther ones.
                 * Hide side cells behind a nearer side-lane wall so the
                 * V2.2 inplace pass cannot repaint corridor art over it. */
                if (s != 1 && d > 0) {
                    int rel_side = s == 0 ? -1 : 1;
                    if (!dm1_viewport_3d_side_lane_clear_from_visibility_pc34(
                            &visibility, d + 1, rel_side)) {
                        raw_squares[d][s] = M11_V22_SHAPE_CACHE_HIDDEN_SQUARE;
                    }
                }
            }
        }
        if (state->sourceKind != M11_GAME_SOURCE_CSB_BOOT) {
            m11_v22_shape_cache_update((int)state->world.party.direction,
                                       raw_squares);
        }
    }

    /* ReDMCSB DUNVIEW.C F0128:8318-8561 builds its per-square draw
     * schedule from the live view each pass. M11 consumes that transaction
     * before any viewport material pass. An unschedulable or unmounted view
     * stays cleared: there is no legacy content-loop fallback. */
    dm1F0128PlanReady = m11_dm1_f0128_build_live_view_plan(state, cells,
                                                           &dm1F0128Plan);
    dm1F0128PlanDispatched = dm1F0128PlanReady &&
        m11_dm1_f0128_dispatch_live_view_plan(state, &dm1F0128Plan);

    m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                  viewport.x, viewport.y, viewport.w, viewport.h, M11_COLOR_BLACK);
    if (!dm1F0128PlanDispatched) {
        return;
    }
    /* Real viewport background from GRAPHICS.DAT; missing material remains
     * the F0128-cleared black viewport. */
    m11_draw_viewport_background(state, framebuffer, framebufferWidth, framebufferHeight,
                                 viewport.x, viewport.y, viewport.w, viewport.h);
    if (state->showDebugHUD) {
        m11_draw_rect(framebuffer, framebufferWidth, framebufferHeight,
                      viewport.x - 2, viewport.y - 2, viewport.w + 4, viewport.h + 4, M11_COLOR_YELLOW);
        m11_draw_rect(framebuffer, framebufferWidth, framebufferHeight,
                      viewport.x, viewport.y, viewport.w, viewport.h, M11_COLOR_LIGHT_CYAN);
    }

    /* ReDMCSB DUNVIEW.C F0128:8466-8477 invokes F0115 for D4L/R/C, but
     * C0x0001 reaches F0115's depth>3 break at :5110 before projectile
     * handling. G2028 has no D4 C2900 row, so D4 stays no-draw instead of
     * receiving a host-defined small sprite or marker. */
    /* First source-bound wall passes: draw blocked side/front square
     * panels using original wall-set bitmaps and original layout-696
     * zones.  This is still narrower than full DUNVIEW.C: ornaments,
     * doors, pits, stairs, fields, and exact object order remain next. */
    /* ReDMCSB F0128 invokes every D3..D1 square route; geometry is hidden
     * by later source panels, not pre-culled by a host visibility shortcut. */
    m11_draw_dm1_floor_pits(state, framebuffer, framebufferWidth, framebufferHeight,
                             1, 3, cells);
    m11_draw_dm1_floor_ornaments(state, framebuffer, framebufferWidth, framebufferHeight,
                                  3, cells);
    /* ReDMCSB DUNVIEW.C F0128: side squares are drawn in source order before
     * the same-depth center square (D3L/D3R before D3C, D2L/D2R before D2C,
     * D1L/D1R before D1C).  Do not cap the primary side-wall pass at the
     * nearest center blocker; the later center-wall pass overpaints it.  The
     * replay pass below still uses a reduced max to repair near-side occlusion
     * after center doors/walls have been drawn. */
    m11_draw_dm1_side_walls(state, framebuffer, framebufferWidth, framebufferHeight,
                            dm1_viewport_3d_primary_side_wall_max_forward_pc34(
                                maxVisibleForward),
                            &visibility);
    m11_draw_dm1_front_walls(state, framebuffer, framebufferWidth, framebufferHeight, cells);
    m11_draw_dm1_wall_ornaments(state, framebuffer, framebufferWidth, framebufferHeight,
                                  maxVisibleForward, cells, 0);
    m11_draw_dm1_thieves_eye_d1c_wall_material(
        state, framebuffer, framebufferWidth, framebufferHeight, cells);
    m11_draw_dm1_teleporter_fields(state, framebuffer, framebufferWidth, framebufferHeight,
                                  1, 3, cells);
    m11_draw_dm1_d3l2_d3r2_f0111_door_fronts(
        state, framebuffer, framebufferWidth, framebufferHeight,
        maxVisibleForward, cells);
    m11_draw_dm1_side_doors(state, framebuffer, framebufferWidth, framebufferHeight,
                             maxVisibleForward, cells);
    m11_draw_dm1_side_door_ornaments(state, framebuffer, framebufferWidth, framebufferHeight,
                                       maxVisibleForward, cells);
    m11_draw_dm1_side_destroyed_door_masks(state, framebuffer, framebufferWidth, framebufferHeight,
                                          maxVisibleForward, cells);
    m11_draw_dm1_center_doors(state, framebuffer, framebufferWidth, framebufferHeight, cells);
    m11_draw_dm1_center_door_ornaments(state, framebuffer, framebufferWidth, framebufferHeight, cells);
    m11_draw_dm1_center_thieves_eye_mask(state, framebuffer, framebufferWidth, framebufferHeight, cells);
    m11_draw_dm1_center_destroyed_door_masks(state, framebuffer, framebufferWidth, framebufferHeight, cells);
    m11_draw_dm1_center_door_buttons(state, framebuffer, framebufferWidth, framebufferHeight, cells);
    m11_draw_dm1_d3r_door_button(state, framebuffer, framebufferWidth, framebufferHeight,
                                  maxVisibleForward, cells);

    /* ReDMCSB DUNVIEW.C F0128 draws complete squares far-to-near
     * (D3 side/center, then D2 side/center, then D1 side/center).
     * Firestaff current V1 renderer still batches by primitive class.
     * After drawing a blocking center door/wall at D2C or D3C, replay only
     * the nearer side layers so farther center doors/buttons/items cannot
     * bleed through near side-wall/door occluders. */
    {
        int blockingCenterDepth = visibility.nearest_blocking_center_depth_index;
        if (blockingCenterDepth > 0) {
            int nearMaxVisibleForward = blockingCenterDepth;
            m11_draw_dm1_side_walls(state, framebuffer, framebufferWidth, framebufferHeight,
                                    nearMaxVisibleForward, &visibility);
            m11_draw_dm1_wall_ornaments(state, framebuffer, framebufferWidth, framebufferHeight,
                                        nearMaxVisibleForward, cells, 0);
            m11_draw_dm1_d3l2_d3r2_f0111_door_fronts(
                state, framebuffer, framebufferWidth, framebufferHeight,
                nearMaxVisibleForward, cells);
            m11_draw_dm1_side_doors(state, framebuffer, framebufferWidth, framebufferHeight,
                                    nearMaxVisibleForward, cells);
            m11_draw_dm1_side_door_ornaments(state, framebuffer, framebufferWidth, framebufferHeight,
                                             nearMaxVisibleForward, cells);
            m11_draw_dm1_side_destroyed_door_masks(state, framebuffer, framebufferWidth, framebufferHeight,
                                                   nearMaxVisibleForward, cells);
        }
    }

    /* ReDMCSB DUNVIEW.C F0128 completes D1L/D1R before its D1C F0107
     * ornament branch. M11's split renderer may replay those side panels
     * after the first ornament batch; consume C127's C346->C026 pair only
     * after that replay, but before D1C F0115 objects/projectiles. This
     * keeps a live mirror from being erased by a side-wall material pass
     * without letting it cover the later thing layer. */
    m11_draw_dm1_front_mirror_route(state, &cells[0][1], framebuffer,
                                    framebufferWidth, framebufferHeight);

    /* ReDMCSB DUNVIEW.C F0128 calls F0115 in full square order:
     * D3L/D3R/D3C, D2L/D2R/D2C, then D1L/D1R/D1C. Keep the current
     * source-material consumers, but run each side pair immediately before
     * the matching center route instead of batching all sides first. */
    {
        int centerContentMask =
            visibility.center_visible_depth_mask;
        int blockingCenterDepth =
            visibility.nearest_blocking_center_depth_index;
        if (dm1F0128PlanDispatched) {
            /* Plan-driven loop: the verified F0128 contract plan supplies
             * the visit order and each square's F0115 admission through its
             * per-square step span (DUNVIEW.C:8491-8542).  A square whose
             * span carries no F0115 step (plain wall; D2L2/D2R2/early D4
             * are outside this D3..D1 content range) draws no thing-layer
             * content — matching the source routes that return before their
             * F0115 pass.  Side pairs still draw once per depth, ordered
             * immediately before their center square. */
            static const int kContentSquares[9] = {
                DM1_V1_F0128_VIEW_SQUARE_D3L, DM1_V1_F0128_VIEW_SQUARE_D3R,
                DM1_V1_F0128_VIEW_SQUARE_D3C,
                DM1_V1_F0128_VIEW_SQUARE_D2L, DM1_V1_F0128_VIEW_SQUARE_D2R,
                DM1_V1_F0128_VIEW_SQUARE_D2C,
                DM1_V1_F0128_VIEW_SQUARE_D1L, DM1_V1_F0128_VIEW_SQUARE_D1R,
                DM1_V1_F0128_VIEW_SQUARE_D1C
            };
            int sidesDrawnForDepth[3] = {0, 0, 0};
            int f0115SquareCount = 0;
            int i;
            for (i = 0; i < 9; ++i) {
                int square = kContentSquares[i];
                int squareDepth = 2 - (i / 3);
                int spanStart = 0;
                int spanCount = 0;
                int hasF0115 = 0;
                int j;
                if (!DM1_V1_F0128_PerSquareSchedulerSquareSpanPc34Compat(
                        &dm1F0128Plan, square, &spanStart, &spanCount)) {
                    continue;
                }
                for (j = spanStart; j < spanStart + spanCount; ++j) {
                    int op = dm1F0128Plan.steps[j].op;
                    if (op == DM1_V1_F0128_STEP_F0115_MAIN ||
                        op == DM1_V1_F0128_STEP_F0115_DOOR_PASS1 ||
                        op == DM1_V1_F0128_STEP_F0115_DOOR_PASS2) {
                        hasF0115 = 1;
                        break;
                    }
                }
                if (!hasF0115) {
                    continue;
                }
                ++f0115SquareCount;
                if (square == DM1_V1_F0128_VIEW_SQUARE_D3C ||
                    square == DM1_V1_F0128_VIEW_SQUARE_D2C ||
                    square == DM1_V1_F0128_VIEW_SQUARE_D1C) {
                    if ((centerContentMask & (1 << squareDepth)) != 0) {
                        m11_draw_wall_contents(framebuffer,
                                               framebufferWidth,
                                               framebufferHeight,
                                               &frames[squareDepth + 1],
                                               &cells[squareDepth][1],
                                               squareDepth);
                    }
                } else if (!sidesDrawnForDepth[squareDepth]) {
                    sidesDrawnForDepth[squareDepth] = 1;
                    m11_draw_dm1_side_contents_at_depth(
                        state, framebuffer, framebufferWidth,
                        framebufferHeight, frames, cells, squareDepth,
                        &visibility, blockingCenterDepth);
                }
            }
            s_m11_dm1_f0128_per_square_scheduler_receipt
                .planDrivenContentLoop = 1;
            s_m11_dm1_f0128_per_square_scheduler_receipt
                .f0115ContentSquareCount = f0115SquareCount;
        }
    }
    /* F0128 visits each side square far-to-near.  In the original, a nearer
     * closed side wall or door therefore overpaints F0115 material from the
     * farther side lane.  M11 batches all structural panels before its
     * deferred F0115 loop, so restore that source-owned occlusion boundary
     * after the loop rather than letting a floor object bleed through stone. */
    m11_draw_dm1_side_walls(state, framebuffer, framebufferWidth,
                            framebufferHeight, maxVisibleForward, &visibility);
    m11_draw_dm1_wall_ornaments(state, framebuffer, framebufferWidth,
                                 framebufferHeight, maxVisibleForward, cells, 0);
    m11_draw_dm1_d3l2_d3r2_f0111_door_fronts(
        state, framebuffer, framebufferWidth, framebufferHeight,
        maxVisibleForward, cells);
    m11_draw_dm1_side_doors(state, framebuffer, framebufferWidth,
                            framebufferHeight, maxVisibleForward, cells);
    m11_draw_dm1_side_door_ornaments(state, framebuffer, framebufferWidth,
                                     framebufferHeight, maxVisibleForward, cells);
    m11_draw_dm1_side_destroyed_door_masks(state, framebuffer,
                                           framebufferWidth, framebufferHeight,
                                           maxVisibleForward, cells);
    /* ReDMCSB F0128 draws each center wall as part of its square before the
     * next nearer square is visited.  M11's deferred F0115 loop can otherwise
     * leave a far corridor/object visible through a nearer D1C/D2C/D3C wall.
     * Re-emit only the source-owned center wall envelope after that deferred
     * loop, then restore the wall-owned champion mirror route.  This is an
     * occlusion repair, not a synthetic mask or a replacement bitmap. */
    m11_draw_dm1_front_walls(state, framebuffer, framebufferWidth,
                             framebufferHeight, cells);
    /* Restore only centre-wall ornaments after the occluding wall replay.
     * Replaying side ornaments here would let distant material cross the
     * nearer wall boundary again. */
    m11_draw_dm1_wall_ornaments(state, framebuffer, framebufferWidth,
                                framebufferHeight, maxVisibleForward, cells, 1);
    m11_draw_dm1_front_mirror_route(state, &cells[0][1], framebuffer,
                                    framebufferWidth, framebufferHeight);
    /* The final F0128 center-wall replay is an occlusion repair.  F0104's
     * floor-feature pass must follow it, otherwise an exact stairs bitmap on
     * an open square can be painted over by the replayed wall envelope. */
    m11_draw_dm1_stairs(state, framebuffer, framebufferWidth, framebufferHeight,
                        1, 3, cells);
    m11_draw_dm1_deferred_explosion_pass(state, framebuffer,
                                         framebufferWidth, framebufferHeight,
                                         frames, cells);
    /* ReDMCSB DUNVIEW.C F0125/F0126/F0127 dispatches D0 only after the
     * D1 F0115 route has completed.  Keep the near pit/stair/field material
     * out of the early D3..D1 primitive batches so it receives the original
     * final overpaint order.  The source F0108 plan has no verified D0 zone,
     * so floor ornaments deliberately remain D1..D3-only. */
    m11_draw_dm1_floor_pits(state, framebuffer, framebufferWidth, framebufferHeight,
                             0, 0, cells);
    m11_draw_dm1_stairs(state, framebuffer, framebufferWidth, framebufferHeight,
                        0, 0, cells);
    /* F0127's D0C F0115 object pass precedes its F0113 field overlay. */
    m11_draw_dm1_d0c_floor_item_pass(state, framebuffer,
                                     framebufferWidth, framebufferHeight);
    m11_draw_dm1_teleporter_fields(state, framebuffer, framebufferWidth, framebufferHeight,
                                  0, 0, cells);
    m11_draw_dm1_d0c_projectile_pass(state, framebuffer,
                                     framebufferWidth, framebufferHeight);
    m11_draw_dm1_d0c_deferred_explosion_pass(state, framebuffer,
                                             framebufferWidth, framebufferHeight);

    /* The Firestaff procedural corridor/trapezoid renderer is not source
     * DRAWVIEW output.  DM1 and CSB already composed their original material
     * above, so debug HUD must add diagnostics without repainting invented
     * wall panels over that frame. */
    if (state->showDebugHUD && !m11_source_is_csb(state) &&
        !m11_is_dm1_source_kind(state->sourceKind)) {
        for (depth = 0; depth < 3; ++depth) {
            m11_draw_corridor_frame(framebuffer, framebufferWidth, framebufferHeight,
                                    &frames[depth], &frames[depth + 1], depth);
        }

        for (depth = 0; depth < 3; ++depth) {
            m11_draw_side_feature(framebuffer, framebufferWidth, framebufferHeight,
                                  &frames[depth], &frames[depth + 1], &cells[depth][0], -1, depth);
            m11_draw_side_feature(framebuffer, framebufferWidth, framebufferHeight,
                                  &frames[depth], &frames[depth + 1], &cells[depth][2], 1, depth);
            if (!occluded) {
                m11_draw_wall_face(framebuffer, framebufferWidth, framebufferHeight,
                                   &frames[depth + 1], &cells[depth][1], depth);
                if (!m11_viewport_cell_is_open(&cells[depth][1])) {
                    occluded = 1;
                }
            }
        }

        {
            int centerContentMask =
                visibility.center_visible_depth_mask;
            for (depth = 0; depth < 3; ++depth) {
                if ((centerContentMask & (1 << depth)) == 0) {
                    continue;
                }
                m11_draw_wall_contents(framebuffer, framebufferWidth, framebufferHeight,
                                       &frames[depth + 1], &cells[depth][1], depth);
            }
        }
    }

    if (state->showDebugHUD) {
        m11_draw_lane_chip(framebuffer, framebufferWidth, framebufferHeight,
                           viewport.x + 26, viewport.y + 6, 42, 11,
                           &cells[0][0], "L");
        m11_draw_lane_chip(framebuffer, framebufferWidth, framebufferHeight,
                           viewport.x + 77, viewport.y + 6, 42, 11,
                           &cells[0][1], "F");
        m11_draw_lane_chip(framebuffer, framebufferWidth, framebufferHeight,
                           viewport.x + 128, viewport.y + 6, 42, 11,
                           &cells[0][2], "R");

        m11_draw_depth_chip(framebuffer, framebufferWidth, framebufferHeight,
                            viewport.x + 40, viewport.y + viewport.h - 24, 34, 10,
                            &cells[0][1], 0);
        m11_draw_depth_chip(framebuffer, framebufferWidth, framebufferHeight,
                            viewport.x + 88, viewport.y + viewport.h - 24, 34, 10,
                            &cells[1][1], 1);
        m11_draw_depth_chip(framebuffer, framebufferWidth, framebufferHeight,
                            viewport.x + 136, viewport.y + viewport.h - 24, 34, 10,
                            &cells[2][1], 2);

        m11_draw_focus_brackets(framebuffer, framebufferWidth, framebufferHeight,
                                &frames[1], &cells[0][1]);

        m11_draw_viewport_feedback_frame(framebuffer, framebufferWidth, framebufferHeight,
                                         state, &cells[0][1]);
        m11_draw_hline(framebuffer, framebufferWidth, framebufferHeight,
                       viewport.x + 6, viewport.x + viewport.w - 7,
                       viewport.y + viewport.h / 2 + 8, M11_COLOR_LIGHT_GRAY);
    }

    /* Debug/prototype only: the old Firestaff path tiled GRAPHICS.DAT
     * wall/floor strips across procedural trapezoids.  That creates the
     * noisy, speckled "not DM1" viewport Daniel called out. Both DM1 and CSB
     * stay source-owned even in debug mode; non-source diagnostics alone may
     * use this visual aid. */
    if (state->assetsAvailable && state->showDebugHUD &&
        !m11_source_is_csb(state) &&
        !m11_is_dm1_source_kind(state->sourceKind)) {
        int d;
        int mapWallSet;
        int mapFloorSet;
        if (!m11_current_map_wall_set(state, &mapWallSet) ||
            !m11_current_map_floor_set(state, &mapFloorSet)) {
            goto skip_debug_legacy_texture_tiling;
        }
        for (d = 2; d >= 0; --d) {
            const M11_AssetSlot* wallSlot;
            unsigned int wallIdx = (unsigned int)
                dm1_v1_graphic_materialized_wallset_index_pc34(
                    mapWallSet,
                    dm1_v1_graphic_wallset0_index_pc34(DM1_WALL_D1C));
            wallSlot = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader, wallIdx);
            if (wallSlot && wallSlot->width > 0 && wallSlot->height > 0) {
                int ceilH = frames[d + 1].y - frames[d].y;
                int floorY = frames[d + 1].y + frames[d + 1].h;
                int floorH = (frames[d].y + frames[d].h) - floorY;
                int leftW = frames[d + 1].x - frames[d].x;
                int rightX = frames[d + 1].x + frames[d + 1].w;
                int rightW = (frames[d].x + frames[d].w) - rightX;
                /* Ceiling strip */
                if (ceilH > 2) {
                    M11_AssetLoader_BlitScaled(wallSlot, framebuffer,
                        framebufferWidth, framebufferHeight,
                        frames[d].x + 1, frames[d].y + 1,
                        frames[d].w - 2, ceilH - 1, -1);
                }
                /* Left wall strip */
                if (leftW > 2) {
                    M11_AssetLoader_BlitScaled(wallSlot, framebuffer,
                        framebufferWidth, framebufferHeight,
                        frames[d].x + 1, frames[d + 1].y,
                        leftW - 1, frames[d + 1].h, -1);
                }
                /* Right wall strip */
                if (rightW > 2) {
                    M11_AssetLoader_BlitScaled(wallSlot, framebuffer,
                        framebufferWidth, framebufferHeight,
                        rightX + 1, frames[d + 1].y,
                        rightW - 1, frames[d + 1].h, -1);
                }
                /* Floor strip — use the current map's floor set */
                if (floorH > 2) {
                    const M11_AssetSlot* floorSlot = M11_AssetLoader_Load(
                        (M11_AssetLoader*)&state->assetLoader,
                        (unsigned int)(M11_GFX_FIRST_FLOOR_SET +
                                       mapFloorSet * M11_GFX_FLOOR_SET_GRAPHIC_COUNT));
                    if (floorSlot && floorSlot->width > 0 && floorSlot->height > 0) {
                        M11_AssetLoader_BlitScaled(floorSlot, framebuffer,
                            framebufferWidth, framebufferHeight,
                            frames[d].x + 1, floorY + 1,
                            frames[d].w - 2, floorH - 1, -1);
                    }
                }
            }
        }
    }
skip_debug_legacy_texture_tiling:

    /* ReDMCSB source lock: F0337 selects one G0304 dungeon-view
     * palette index, and DRAWVIEW applies that palette to the whole
     * dungeon viewport.  Do not add Firestaff-only distance dimming
     * passes over D0/D1/D2 rectangles; wall/floor/field distance
     * appearance must come from the source graphics and zone order. */
    {
        int paletteIndex = m11_compute_dungeon_palette_index(state);
        m11_apply_dungeon_palette_level(framebuffer, framebufferWidth, framebufferHeight,
                                        M11_VIEWPORT_X, M11_VIEWPORT_Y,
                                        M11_VIEWPORT_W, M11_VIEWPORT_H,
                                        paletteIndex);
    }
    /* F0128 has completed the tuple's wall/ornament composition.  Repaint
     * the selected D1C F0107 material once, after the host palette pass. */
    m11_repaint_dm1_f0128_front_wall_inscription(
        state, framebuffer, framebufferWidth, framebufferHeight);
    if (state->presentationMode == M12_PRESENTATION_V22_MODERN) {
        /* CSB keeps its F0128 source page intact until the V2.2 route has a
         * source-owned perspective projection receipt. See the boot renderer
         * above. Other games retain their own proven in-place renderer. */
        if (state->sourceKind != M11_GAME_SOURCE_CSB_BOOT) {
            (void)m11_v22_inplace_render_pass(framebuffer,
                                               framebufferWidth,
                                               framebufferHeight);
        }
    }

    m11_apply_viewport_turn_pan(framebuffer, framebufferWidth, framebufferHeight,
                                M11_VIEWPORT_X, M11_VIEWPORT_Y,
                                M11_VIEWPORT_W, M11_VIEWPORT_H,
                                turnPanX);
    m11_apply_viewport_motion_pan(framebuffer, framebufferWidth,
                                  framebufferHeight, M11_VIEWPORT_X,
                                  M11_VIEWPORT_Y, M11_VIEWPORT_W,
                                  M11_VIEWPORT_H, csbMotionPanX,
                                  csbMotionPanY);
    {
        uint8_t presented_viewport[DM1_VIEWPORT_WIDTH * DM1_VIEWPORT_HEIGHT];
        DM1_ViewportPresentReceiptPc34 present_receipt;
        M11_GameViewState *mutable_state = (M11_GameViewState *)state;
        int y;

        /* F0097 consumes the fully composed G0296 bitmap after F0128 and
         * turn-pan. Stage the actual C007 pixels so source/destination never
         * alias; unavailable host geometry remains a no-draw. */
        if (framebufferWidth < DM1_VIEWPORT_SCREEN_WIDTH ||
            framebufferHeight < DM1_VIEWPORT_SCREEN_HEIGHT) {
            return;
        }
        for (y = 0; y < DM1_VIEWPORT_HEIGHT; ++y) {
            memcpy(presented_viewport + y * DM1_VIEWPORT_WIDTH,
                   framebuffer + (M11_VIEWPORT_Y + y) * framebufferWidth +
                       M11_VIEWPORT_X,
                   DM1_VIEWPORT_WIDTH);
        }
        (void)dm1_viewport_3d_present_pc34(
            presented_viewport, DM1_VIEWPORT_WIDTH,
            framebuffer, framebufferWidth, framebufferHeight, framebufferWidth,
            1, m11_compute_dungeon_palette_index(state),
            state->world.party.mapIndex, 255,
            -1, -1,
            &mutable_state->dm1ViewportPresentedPaletteIndex,
            &present_receipt);
    }
}

static void m11_format_champion_name(const unsigned char* raw,
                                     char* out,
                                     size_t outSize) {
    size_t i;
    size_t end = 0;
    if (!out || outSize == 0U) {
        return;
    }
    if (!raw) {
        snprintf(out, outSize, "EMPTY");
        return;
    }
    for (i = 0; i + 1 < outSize && i < CHAMPION_NAME_LENGTH; ++i) {
        unsigned char ch = raw[i];
        if (ch == 0U) {
            break;
        }
        out[i] = isprint(ch) ? (char)ch : ' ';
        if (out[i] != ' ') {
            end = i + 1;
        }
    }
    out[i < outSize ? i : outSize - 1] = '\0';
    out[end] = '\0';
    if (out[0] == '\0') {
        snprintf(out, outSize, "EMPTY");
    }
}

static void m11_format_champion_title(const unsigned char* raw,
                                      char* out,
                                      size_t outSize) {
    size_t i;
    size_t end = 0;
    if (!out || outSize == 0U) return;
    out[0] = '\0';
    if (!raw) return;
    for (i = 0; i + 1 < outSize && i < CHAMPION_TITLE_LENGTH; ++i) {
        unsigned char ch = raw[i];
        if (ch == 0U) break;
        out[i] = isprint(ch) ? (char)ch : ' ';
        if (out[i] != ' ') end = i + 1;
    }
    out[i < outSize ? i : outSize - 1] = '\0';
    out[end] = '\0';
}

int M11_GameView_EndgameTitleXForSourceText(const char* name, const char* title) {
    int titleX;
    char firstTitleChar;
    if (!name) name = "";
    if (!title || !title[0]) return 87 + ((int)strlen(name) * 6);
    titleX = 87 + ((int)strlen(name) * 6);
    firstTitleChar = title[0];
    if (firstTitleChar != ',' && firstTitleChar != ';' && firstTitleChar != '-') {
        titleX += 6;
    }
    return titleX;
}

static int m11_endgame_source_skill_level(const M11_GameViewState* state,
                                           int championIndex,
                                           int baseSkillIndex) {
    int lifecycleLevel = 1;
    int storedLevel = 1;
    if (!state || championIndex < 0 || championIndex >= CHAMPION_MAX_PARTY ||
        baseSkillIndex < 0 || baseSkillIndex >= CHAMPION_SKILL_COUNT) {
        return 1;
    }
    if (!state->world.party.champions[championIndex].present) {
        return 1;
    }
    storedLevel = (int)state->world.party.champions[championIndex].skillLevels[baseSkillIndex];
    lifecycleLevel = F0848_LIFECYCLE_ComputeSkillLevel_Compat(
        &state->world.lifecycle.champions[championIndex],
        baseSkillIndex,
        1); /* ENDGAME.C uses IGNORE_TEMPORARY_EXPERIENCE. */
    if (lifecycleLevel < storedLevel) lifecycleLevel = storedLevel;
    if (lifecycleLevel > 16) lifecycleLevel = 16;
    if (lifecycleLevel < 1) lifecycleLevel = 1;
    return lifecycleLevel;
}

static void m11_get_active_champion_label(const M11_GameViewState* state,
                                          char* out,
                                          size_t outSize) {
    if (!out || outSize == 0U) {
        return;
    }
    if (!state || !state->active ||
        state->world.party.activeChampionIndex < 0 ||
        state->world.party.activeChampionIndex >= CHAMPION_MAX_PARTY ||
        !state->world.party.champions[state->world.party.activeChampionIndex].present) {
        snprintf(out, outSize, "LEADER");
        return;
    }
    m11_format_champion_name(state->world.party.champions[state->world.party.activeChampionIndex].name,
                             out,
                             outSize);
}

static int m11_cycle_active_champion(M11_GameViewState* state) {
    int start;
    int step;
    char champion[16];

    if (!state || !state->active || state->world.party.championCount <= 0) {
        return 0;
    }

    start = state->world.party.activeChampionIndex;
    if (start < 0 || start >= CHAMPION_MAX_PARTY ||
        !state->world.party.champions[start].present) {
        start = 0;
    }

    for (step = 1; step <= CHAMPION_MAX_PARTY; ++step) {
        int candidate = (start + step) % CHAMPION_MAX_PARTY;
        if (candidate < state->world.party.championCount &&
            state->world.party.champions[candidate].present) {
            state->world.party.activeChampionIndex = candidate;
            m11_get_active_champion_label(state, champion, sizeof(champion));
            m11_set_status(state, "CHAMP", "ACTIVE CHAMPION READY");
            snprintf(state->inspectTitle, sizeof(state->inspectTitle), "%s READY", champion);
            snprintf(state->inspectDetail, sizeof(state->inspectDetail),
                     "SPACE ACTS, ENTER INSPECTS, CLICK CENTER TO COMMIT, TAB CYCLES THE FRONT CHAMPION");
            return 1;
        }
    }

    return 0;
}

static int m11_set_active_champion(M11_GameViewState* state, int championIndex) {
    char champion[16];

    if (!state || !state->active || championIndex < 0 || championIndex >= CHAMPION_MAX_PARTY) {
        return 0;
    }
    if (championIndex >= state->world.party.championCount ||
        !state->world.party.champions[championIndex].present) {
        return 0;
    }
    if (state->world.party.activeChampionIndex == championIndex) {
        return 1;
    }

    state->world.party.activeChampionIndex = championIndex;
    m11_get_active_champion_label(state, champion, sizeof(champion));
    m11_set_status(state, "CHAMP", "ACTIVE CHAMPION READY");
    snprintf(state->inspectTitle, sizeof(state->inspectTitle), "%s READY", champion);
    snprintf(state->inspectDetail, sizeof(state->inspectDetail),
             "CLICK OR TAB TO SWAP, CLICK CENTER TO COMMIT, SPACE ACTS, ENTER INSPECTS");
    return 1;
}

static int m11_source_is_csb(const M11_GameViewState* state) {
    return state &&
           (state->sourceKind == M11_GAME_SOURCE_CSB_BOOT ||
            strcmp(state->sourceId, "csb") == 0);
}

/* COMMAND.C C007..C010 reaches this same toggle from the champion status
 * boxes.  Keep the target selection and open/close decision together: the
 * old pointer path assigned activeChampionIndex before testing sameOpen,
 * which made a click on a different champion close the currently open panel. */
static M11_GameInputResult m11_toggle_champion_inventory(M11_GameViewState* state,
                                                          int championIndex) {
    int sameOpen;
    char champion[16];

    if (!state || championIndex < 0 || championIndex >= CHAMPION_MAX_PARTY ||
        championIndex >= state->world.party.championCount ||
        !state->world.party.champions[championIndex].present) {
        m11_set_status(state, "INVENTORY", "NO CHAMPION");
        return M11_GAME_INPUT_REDRAW;
    }

    if (state->sourceKind == M11_GAME_SOURCE_DM2_BOOT) {
        /* SKProject CHANGE_VIEWPORT_TO_INVENTORY owns the CHAMPIONS and
         * INTERFACE_GENERAL GDAT surfaces plus the matching click table.
         * M11's champion boxes are DM1 geometry, so retain DM2 ObjectIDs in
         * the source session but never expose or mutate them through that
         * substitute panel. */
        state->inventoryPanelActive = 0;
        state->inventorySelectedSlot = -1;
        m11_set_status(state, "INVENTORY", "DM2 INVENTORY GDAT REQUIRED");
        return M11_GAME_INPUT_REDRAW;
    }

    sameOpen = state->inventoryPanelActive &&
               state->world.party.activeChampionIndex == championIndex;
    state->mapOverlayActive = 0;
    state->spellPanelOpen = 0;
    state->world.party.activeChampionIndex = championIndex;
    if (sameOpen) {
        state->inventoryPanelActive = 0;
        state->inventorySelectedSlot = -1;
        m11_set_status(state, "INVENTORY", "CLOSED");
        return M11_GAME_INPUT_REDRAW;
    }

    state->inventoryPanelActive = 1;
    state->inventorySelectedSlot = 0;
    m11_clear_v1_mouth_visual(state);
    m11_get_active_champion_label(state, champion, sizeof(champion));
    m11_set_status(state, "INVENTORY", "CHAMPION READY");
    snprintf(state->inspectTitle, sizeof(state->inspectTitle), "%s INVENTORY", champion);
    snprintf(state->inspectDetail, sizeof(state->inspectDetail),
             "%s CHAMPION INVENTORY TOGGLE",
             m11_source_is_csb(state) ? "CSB F1-F4" : "DM1 HUD");
    return M11_GAME_INPUT_REDRAW;
}

static CSB_V1_StartupSessionMovementCommand_PC34
m11_csb_first_post_c040_movement_command(M12_MenuInput input)
{
    switch (input) {
    case M12_MENU_INPUT_UP:
        return CSB_V1_STARTUP_SESSION_MOVEMENT_FORWARD_PC34;
    case M12_MENU_INPUT_DOWN:
        return CSB_V1_STARTUP_SESSION_MOVEMENT_BACKWARD_PC34;
    case M12_MENU_INPUT_TURN_LEFT:
        return CSB_V1_STARTUP_SESSION_MOVEMENT_TURN_LEFT_PC34;
    case M12_MENU_INPUT_TURN_RIGHT:
        return CSB_V1_STARTUP_SESSION_MOVEMENT_TURN_RIGHT_PC34;
    default:
        return CSB_V1_STARTUP_SESSION_MOVEMENT_NONE_PC34;
    }
}

static int m11_csb_preflight_first_post_c040_input(
    M11_GameViewState *state,
    M12_MenuInput input,
    unsigned int *out_source_tick)
{
    CSB_V1_StartupSessionMovementCommand_PC34 command;
    CSB_V1_StartupRuntimeAssetSession_PC34 candidate;
    CSB_V1_StartupSessionLiveHudReceipt_PC34 live_hud;
    CSB_V1_StartupSessionInputReceipt_PC34 input_receipt;
    CSB_V1_StartupRuntimeAssetSession_PC34 *session;
    unsigned int next_tick;

    if (out_source_tick) {
        *out_source_tick = 0u;
    }
    if (!state || !state->csbState.c040_clear_live_hud_ready) {
        return 1;
    }
    command = m11_csb_first_post_c040_movement_command(input);
    if (command == CSB_V1_STARTUP_SESSION_MOVEMENT_NONE_PC34 ||
        !state->csbStartupRuntimeAssetSession) {
        return command == CSB_V1_STARTUP_SESSION_MOVEMENT_NONE_PC34;
    }
    session = (CSB_V1_StartupRuntimeAssetSession_PC34 *)
        state->csbStartupRuntimeAssetSession;
    if (session->generation !=
            state->csbState.c040_clear_session_generation ||
        session->source_tick != state->csbState.c040_clear_source_tick ||
        state->csbState.c040_clear_source_tick == (unsigned int)-1) {
        return 0;
    }
    next_tick = state->csbState.c040_clear_source_tick + 1u;
    candidate = *session;
    candidate.source_tick = next_tick;
    memset(&live_hud, 0, sizeof(live_hud));
    live_hud.valid = 1;
    live_hud.c040_cleared_once = 1;
    live_hud.c017_live_base_only = 1;
    live_hud.c017_source_asset_id = 17;
    live_hud.source_tick = state->csbState.c040_clear_source_tick;
    live_hud.session_generation =
        state->csbState.c040_clear_session_generation;
    /* ReDMCSB COMMAND.C F0361/F0380 dispatches the first movement only
     * after PANEL.C F0346/F0347 has restored C017.  CSBWin consumes the
     * same post-panel command stream; validate it before the bridge can
     * mutate the source runtime. */
    if (!csb_v1_startup_session_first_input_receipt_pc34(
            &candidate, &live_hud, command, next_tick,
            candidate.generation, &input_receipt) ||
        !input_receipt.valid || !input_receipt.first_post_c040_input) {
        return 0;
    }
    if (out_source_tick) {
        *out_source_tick = next_tick;
    }
    return 1;
}

static M11_GameInputResult m11_csb_handle_source_keyboard(M11_GameViewState* state,
                                                          M12_MenuInput input) {
    int championIndex = -1;
    CSB_V1_InputCommandBridgeResult bridge;

    if (!m11_source_is_csb(state)) {
        return M11_GAME_INPUT_IGNORED;
    }

    /* ReDMCSB COMMAND.C:245-260 / 263-305 / 308-310 / 708-717:
     * CSB routes F1-F4 to champion inventories, Ctrl-S to the disk/save
     * menu, Escape to C147 freeze and C148 unfreeze, and Return to C146
     * wake while resting.  Handle those before the generic DM1 quit and
     * movement paths so CSB keeps its own keyboard contract. */
    if (input == M12_MENU_INPUT_FREEZE_TOGGLE) {
        state->csbGameFrozen = !state->csbGameFrozen;
        state->csbDiskMenuActive = 0;
        state->csbDiskMenuStage = M11_CSB_SAVE_DISK_MENU_NONE;
        m11_set_status(state, "CSB", state->csbGameFrozen ? "FROZEN" : "UNFROZEN");
        snprintf(state->inspectTitle, sizeof(state->inspectTitle),
                 state->csbGameFrozen ? "CSB FROZEN" : "CSB ACTIVE");
        snprintf(state->inspectDetail, sizeof(state->inspectDetail),
                 "ESCAPE TO %s GAME", state->csbGameFrozen ? "UNFREEZE" : "FREEZE");
        return M11_GAME_INPUT_REDRAW;
    }

    if (state->csbGameFrozen) {
        return M11_GAME_INPUT_IGNORED;
    }

    if (input == M12_MENU_INPUT_DISK_MENU) {
        state->mapOverlayActive = 0;
        state->inventoryPanelActive = 0;
        state->spellPanelOpen = 0;
        m11_csb_show_save_disk_menu(state);
        return M11_GAME_INPUT_REDRAW;
    }

    if (state->csbDiskMenuActive) {
        return M11_GAME_INPUT_IGNORED;
    }

    if (input >= M12_MENU_INPUT_CHAMPION_1_INVENTORY &&
        input <= M12_MENU_INPUT_CHAMPION_4_INVENTORY) {
        championIndex = (int)(input - M12_MENU_INPUT_CHAMPION_1_INVENTORY);
        return m11_toggle_champion_inventory(state, championIndex);
    }

    if (state->sourceKind == M11_GAME_SOURCE_CSB_BOOT) {
        unsigned int first_post_c040_tick = 0u;
        if (!state->csbBootProfile) {
            return M11_GAME_INPUT_IGNORED;
        }

        /* ReDMCSB COMMAND.C F0361/F0380 owns keyboard movement command
         * queueing for CSB.  Reuse the source-locked CSB bridge so M11
         * does not duplicate the C001..C006 scancode/queue mapping.
         * Current CSB runtime support applies C001/C002 turns through
         * F0365/F0284; C003..C006 movement commands are consumed and
         * reported by the bridge until the dungeon-aware movement boundary
         * is widened separately. */
        if (!m11_csb_preflight_first_post_c040_input(
                state, input, &first_post_c040_tick)) {
            m11_set_status(state, "CSB", "STALE HUD SESSION");
            return M11_GAME_INPUT_IGNORED;
        }
        memset(&bridge, 0, sizeof(bridge));
        if (CSB_V1_InputCommandBridge_ProcessMenuInputFromBootProfilePc34Compat(
                state->csbBootProfile,
                input,
                0,
                0,
                0,
                0,
                -1,
                &bridge) < 0) {
            m11_set_status(state, "CSB", "INPUT REJECTED");
            return M11_GAME_INPUT_IGNORED;
        }
        if (bridge.mapped) {
            if (first_post_c040_tick != 0u) {
                CSB_V1_StartupRuntimeAssetSession_PC34 *session =
                    (CSB_V1_StartupRuntimeAssetSession_PC34 *)
                        state->csbStartupRuntimeAssetSession;
                session->source_tick = first_post_c040_tick;
                state->csbState.c040_clear_live_hud_ready = 0;
                state->csbState.c040_clear_source_tick = 0u;
                state->csbState.c040_clear_session_generation = 0u;
            }
            /* ReDMCSB GAMELOOP.C:124-155 advances game time before the
             * command wait loop ages G0491/G0495 action locks.  The CSB
             * bridge consumes one mapped command per input, so advance the
             * M11 action-effect clock one tick before the receipt-driven
             * cooldown pass; otherwise a SHOOT/THROW lock materialized at
             * the current tick can never expire on the CSB route. */
            state->world.gameTick++;
            m11_decrement_action_disabled_ticks(state);
            /* ReDMCSB GAMELOOP.C processes TIMELINE.C's due queue before
             * the next command surface is exposed.  The CSB input route
             * must consume due C11 receipts through the same source-locked
             * dispatch as the DM1 tick path, otherwise the action re-enable
             * (and SHOOT's ready-hand refill, TIMELINE.C:1597-1607) never
             * closes on this route. */
            {
                struct TickResult_Compat timelineResult;
                memset(&timelineResult, 0, sizeof(timelineResult));
                (void)F0887_ORCH_DispatchTimelineEvents_Compat(
                    &state->world, &timelineResult);
                state->lastTickResult = timelineResult;
                M11_GameView_ProcessTickEmissions(state);
            }
            m11_sync_csb_state_from_boot_profile(state, state->csbBootProfile);
            if (bridge.is_turn && bridge.runtime_state_changed) {
                m11_set_status(state, "CSB", "FACING UPDATED");
            } else if (bridge.queue_result.dispatchedMove) {
                m11_set_status(state, "CSB", "MOVE QUEUED");
            } else if (bridge.queue_result.movementDisabledGate) {
                m11_set_status(state, "CSB", "MOVEMENT COOLDOWN");
            } else if (bridge.queue_result.dequeued) {
                m11_set_status(state, "CSB", "INPUT CONSUMED");
            } else {
                m11_set_status(state, "CSB", "INPUT QUEUED");
            }
            return M11_GAME_INPUT_REDRAW;
        }
    }

    return M11_GAME_INPUT_IGNORED;
}

static int m11_v1_champion_icon_invisibility_remap(int paletteIndex) {
    const unsigned char* remap =
        dm1_v1_f0662_invisibility_palette_changes_pc34();
    if (paletteIndex < 0 || paletteIndex > 15) {
        return -1;
    }
    return (int)remap[paletteIndex];
}

static void m11_apply_v1_champion_icon_invisibility_remap(unsigned char* framebuffer,
                                                          int framebufferWidth,
                                                          int framebufferHeight,
                                                          int x,
                                                          int y,
                                                          int w,
                                                          int h) {
    int yy;
    int xx;
    if (!framebuffer) return;
    for (yy = 0; yy < h; ++yy) {
        int py = y + yy;
        if (py < 0 || py >= framebufferHeight) continue;
        for (xx = 0; xx < w; ++xx) {
            int px = x + xx;
            int remapped;
            unsigned char* p;
            if (px < 0 || px >= framebufferWidth) continue;
            p = &framebuffer[py * framebufferWidth + px];
            remapped = m11_v1_champion_icon_invisibility_remap((int)(*p & 0x0F));
            if (remapped >= 0) {
                *p = (unsigned char)remapped;
            }
        }
    }
}

static void m11_draw_v1_champion_icons(const M11_GameViewState* state,
                                        unsigned char* framebuffer,
                                        int framebufferWidth,
                                        int framebufferHeight) {
    int slot;
    const M11_AssetSlot* iconStrip = NULL;
    if (!state || !framebuffer || state->showDebugHUD) {
        return;
    }
    if (!m11_v1_chrome_mode_enabled(state) || m11_v2_vertical_slice_enabled(state)) {
        return;
    }
    if (state->assetsAvailable) {
        iconStrip = M11_AssetLoader_Load(
            (M11_AssetLoader*)&state->assetLoader,
            (unsigned int)dm1_v1_graphic_champion_icons_pc34());
    }

    /* CHAMDRAW.C F0622 requires C028's four 19x14 frames. CSB's selected
     * GRAPHICS.DAT must supply that full strip before its icon zones exist. */
    if (state->sourceKind == M11_GAME_SOURCE_CSB_BOOT &&
        (!iconStrip || !iconStrip->loaded || !iconStrip->pixels ||
         iconStrip->width != 4 * 19 || iconStrip->height != 14)) {
        for (slot = 0; slot < CHAMPION_MAX_PARTY; ++slot) {
            DM1_V1_LayoutZoneRectPc34 clearRect;
            if (dm1_v1_champion_icon_rect_pc34(slot, &clearRect)) {
                m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                              clearRect.x, clearRect.y,
                              clearRect.w, clearRect.h, M11_COLOR_BLACK);
            }
        }
        return;
    }

    /* F0622 first fills the temporary 19x14 bitmap, then overlays C028.
     * Without the verified original strip, that fill alone is a fabricated
     * party marker, so the complete icon route stays unavailable. */
    if (!iconStrip ||
        !DM1_ChampionPanel_AssetSurfaceAccepted(
            dm1_v1_graphic_champion_icons_pc34(),
            DM1_GFX_CHAMPION_ICONS,
            iconStrip->loaded,
            iconStrip->pixels != NULL,
            iconStrip->width,
            iconStrip->height,
            DM1_CHAMPION_ICON_WIDTH * 4,
            DM1_CHAMPION_ICON_HEIGHT)) {
        return;
    }

    /* ReDMCSB CHAMDRAW.C F0288 clears C113..C116, fills a 19x14
     * temporary bitmap with G0046_auc_Graphic562_ChampionColor[slot],
     * overlays C028_GRAPHIC_CHAMPION_ICONS with C12 transparent, then
     * blits the result to the clipped champion-icon zones.  This restores
     * the visible top-right party-position icons that the V1 status-box
     * pass exposed as hit zones but did not yet draw. */
    for (slot = 0; slot < CHAMPION_MAX_PARTY; ++slot) {
        DM1_V1_LayoutZoneRectPc34 rect;
        int x, y, w, h;
        if (!dm1_v1_champion_icon_rect_pc34(slot, &rect)) {
            continue;
        }
        x = rect.x;
        y = rect.y;
        w = rect.w;
        h = rect.h;
        m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                      x, y, w, h, M11_COLOR_BLACK);
        if (slot >= state->world.party.championCount ||
            !state->world.party.champions[slot].present) {
            continue;
        }
        {
            const struct ChampionState_Compat* champ =
                &state->world.party.champions[slot];
            DM1_ChampionPanel_IconBitmapModel iconModel;
            if (!DM1_ChampionPanel_BuildIconBitmapModel(
                    slot,
                    (int)champ->direction & 0x03,
                    state->world.party.direction & 0x03,
                    (int)state->world.magic.event71CountInvisibility,
                    &iconModel)) {
                continue;
            }
            m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                          x, y, w, h, (unsigned char)iconModel.fillColor);
            if (iconStrip->width == iconModel.width * 4 &&
                iconStrip->height == iconModel.height &&
                iconModel.sourceX >= 0 &&
                iconModel.sourceX + iconModel.width <= iconStrip->width) {
                M11_AssetLoader_BlitRegion(iconStrip,
                    iconModel.sourceX,
                    iconModel.sourceY,
                    w < iconModel.width ? w : iconModel.width,
                    h < iconModel.height ? h : iconModel.height,
                    framebuffer, framebufferWidth, framebufferHeight,
                    x, y, iconModel.transparentColor);
            }
            if (iconModel.applyInvisibilityPalette) {
                m11_apply_v1_champion_icon_invisibility_remap(framebuffer,
                                                              framebufferWidth,
                                                              framebufferHeight,
                                                              x, y, w, h);
            }
        }
    }
}

/* ReDMCSB CHAMDRAW.C F0287/F0291/F0292 route.  The PC34 top-row contract
 * already admits C008/C028/C033/C034/C035 as one source-owned asset set and
 * turns live champion state into ordered presentation operations.  M11 must
 * consume that receipt as-is: a partially loaded bank is not permission to
 * revive the earlier per-widget renderer or a host-font substitute. */
static int m11_dm1_v1_top_row_receipt_required(const M11_GameViewState* state)
{
    return state && m11_is_dm1_source_kind(state->sourceKind) &&
           !state->showDebugHUD && m11_v1_chrome_mode_enabled(state) &&
           !m11_v2_vertical_slice_enabled(state);
}

static unsigned int m11_dm1_v1_top_row_material_fnv1a(
    const Dm1V1ChampionTopRowAssetsReceiptPc34* assets)
{
    const Dm1V1ChampionTopRowSurfacePc34* surfaces[5];
    unsigned int hash = 2166136261u;
    int index;

    if (!assets || !assets->valid || !assets->c008Accepted ||
        !assets->c028Accepted || !assets->c033Accepted ||
        !assets->c034Accepted || !assets->c035Accepted) {
        return 0u;
    }
    surfaces[0] = &assets->assets.deadStatusBox;
    surfaces[1] = &assets->assets.championIcons;
    surfaces[2] = &assets->assets.slotNormal;
    surfaces[3] = &assets->assets.slotWounded;
    surfaces[4] = &assets->assets.slotActing;
    for (index = 0; index < 5; ++index) {
        const Dm1V1ChampionTopRowSurfacePc34* surface = surfaces[index];
        unsigned int sourceHash;
        if (!surface || !surface->loaded || !surface->pixels ||
            surface->width <= 0 || surface->height <= 0) {
            return 0u;
        }
        sourceHash = m11_dm1_runtime_capture_fnv1a(
            surface->pixels,
            (size_t)surface->width * (size_t)surface->height);
        if (sourceHash == 0u) {
            return 0u;
        }
        hash ^= sourceHash;
        hash *= 16777619u;
        hash ^= (unsigned int)surface->graphicIndex;
        hash *= 16777619u;
    }
    return hash;
}

static void m11_clear_dm1_v1_top_row_receipt_zones(unsigned char* framebuffer,
                                                    int framebufferWidth,
                                                    int framebufferHeight)
{
    int slot;
    for (slot = 0; slot < CHAMPION_MAX_PARTY; ++slot) {
        DM1_V1_ChampionStatusRectPc34 statusRect;
        DM1_V1_ChampionStatusRectPc34 nameRect;
        DM1_V1_ChampionStatusRectPc34 handRect;
        DM1_V1_LayoutZoneRectPc34 iconRect;
        int hand;

        if (dm1_v1_champion_status_box_rect_pc34(slot, &statusRect)) {
            m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                          statusRect.x, statusRect.y,
                          statusRect.w, statusRect.h, M11_COLOR_BLACK);
        }
        if (dm1_v1_champion_status_name_rect_pc34(slot, &nameRect)) {
            m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                          nameRect.x, nameRect.y, nameRect.w, nameRect.h,
                          M11_COLOR_BLACK);
        }
        if (dm1_v1_champion_icon_rect_pc34(slot, &iconRect)) {
            m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                          iconRect.x, iconRect.y, iconRect.w, iconRect.h,
                          M11_COLOR_BLACK);
        }
        if (dm1_v1_champion_poison_label_rect_pc34(slot, 96, 15,
                                                    &statusRect)) {
            m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                          statusRect.x, statusRect.y,
                          statusRect.w, statusRect.h, M11_COLOR_BLACK);
        }
        if (dm1_v1_champion_damage_indicator_rect_pc34(slot, 45, 7,
                                                        &statusRect)) {
            m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                          statusRect.x, statusRect.y,
                          statusRect.w, statusRect.h, M11_COLOR_BLACK);
        }
        if (dm1_v1_champion_inventory_damage_indicator_rect_pc34(slot, 32, 29,
                                                                  &statusRect)) {
            m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                          statusRect.x, statusRect.y,
                          statusRect.w, statusRect.h, M11_COLOR_BLACK);
        }
        for (hand = 0; hand < DM1_V1_CHAMPION_TOP_ROW_HAND_COUNT_PC34;
             ++hand) {
            if (dm1_v1_champion_status_hand_slot_box_rect_pc34(
                    slot, hand, &handRect)) {
                m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                              handRect.x, handRect.y, handRect.w, handRect.h,
                              M11_COLOR_BLACK);
            }
        }
    }
}

static const M11_AssetSlot* m11_dm1_v1_top_row_receipt_source_slot(
    const M11_GameViewState* state,
    const Dm1V1ChampionTopRowPresentationOpPc34* operation)
{
    const M11_AssetSlot* slot;

    if (!state || !operation || !operation->sourcePixels ||
        operation->graphicIndex <= 0 || operation->sourceX < 0 ||
        operation->sourceY < 0 || operation->sourceWidth <= 0 ||
        operation->sourceHeight <= 0 || !state->assetsAvailable) {
        return NULL;
    }
    slot = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader,
                                (unsigned int)operation->graphicIndex);
    if (!slot || !slot->loaded || !slot->pixels ||
        slot->pixels != operation->sourcePixels ||
        operation->sourceX + operation->sourceWidth > slot->width ||
        operation->sourceY + operation->sourceHeight > slot->height) {
        return NULL;
    }
    return slot;
}

static int m11_dm1_v1_redraw_materials_from_loader(
    const M11_GameViewState* state,
    Dm1V1ChampionRedrawMaterialsPc34* outMaterials)
{
    const M11_AssetSlot* poison;
    const M11_AssetSlot* damageSmall;
    const M11_AssetSlot* damageBig;

    if (!state || !outMaterials || !state->assetsAvailable) return 0;
    memset(outMaterials, 0, sizeof(*outMaterials));
    poison = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader,
                                  DM1_GFX_POISONED_LABEL);
    damageSmall = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader, 15);
    damageBig = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader, 16);
    if (!poison || !damageSmall || !damageBig) return 0;

    outMaterials->poisonLabel.graphicIndex = DM1_GFX_POISONED_LABEL;
    outMaterials->poisonLabel.loaded = poison->loaded;
    outMaterials->poisonLabel.pixels = poison->pixels;
    outMaterials->poisonLabel.width = poison->width;
    outMaterials->poisonLabel.height = poison->height;
    outMaterials->damageSmall.graphicIndex = 15;
    outMaterials->damageSmall.loaded = damageSmall->loaded;
    outMaterials->damageSmall.pixels = damageSmall->pixels;
    outMaterials->damageSmall.width = damageSmall->width;
    outMaterials->damageSmall.height = damageSmall->height;
    outMaterials->damageBig.graphicIndex = 16;
    outMaterials->damageBig.loaded = damageBig->loaded;
    outMaterials->damageBig.pixels = damageBig->pixels;
    outMaterials->damageBig.width = damageBig->width;
    outMaterials->damageBig.height = damageBig->height;
    return 1;
}

static const M11_AssetSlot* m11_dm1_v1_redraw_receipt_source_slot(
    const M11_GameViewState* state,
    const Dm1V1ChampionRedrawPriorityOpPc34* operation)
{
    const M11_AssetSlot* slot;
    if (!state || !operation || !operation->sourcePixels ||
        operation->graphicIndex <= 0 || operation->width <= 0 ||
        operation->height <= 0 || !state->assetsAvailable) return NULL;
    slot = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader,
                                (unsigned int)operation->graphicIndex);
    if (!slot || !slot->loaded || slot->pixels != operation->sourcePixels ||
        slot->width < operation->width || slot->height < operation->height) {
        return NULL;
    }
    return slot;
}

static int m11_dm1_v1_party_inventory_handoff_from_frame(
    const M11_GameViewState* state,
    const Dm1V1ChampionTopRowPresentationReceiptPc34* presentation,
    Dm1V1ChampionRedrawMaterialsPc34* outMaterials,
    Dm1V1ChampionRedrawPriorityReceiptPc34* outRedraw,
    Dm1V1ChampionPartyInventoryHandoffReceiptPc34* outHandoff)
{
    Dm1V1ChampionRedrawStatePc34 redrawState;
    Dm1V1ChampionPartyInventorySwitchPc34 transition;
    int slot;

    if (!state || !presentation || !outMaterials || !outRedraw || !outHandoff ||
        !m11_dm1_v1_redraw_materials_from_loader(state, outMaterials)) {
        return 0;
    }
    memset(&redrawState, 0, sizeof(redrawState));
    redrawState.partyChampionCount = state->world.party.championCount;
    redrawState.inventoryChampionIndex = state->inventoryPanelActive
        ? state->world.party.activeChampionIndex : -1;
    if (redrawState.partyChampionCount < 0 ||
        redrawState.partyChampionCount > CHAMPION_MAX_PARTY ||
        redrawState.inventoryChampionIndex >= CHAMPION_MAX_PARTY) {
        return 0;
    }
    for (slot = 0; slot < redrawState.partyChampionCount; ++slot) {
        const struct ChampionState_Compat* champion =
            &state->world.party.champions[slot];
        redrawState.present[slot] = champion->present;
        redrawState.currentHealth[slot] = champion->hp.current;
        redrawState.poisonDose[slot] = champion->poisonDose;
        redrawState.pendingDamage[slot] = state->championDamageTimer[slot] > 0;
        redrawState.pendingDamageAmount[slot] =
            state->championDamageAmount[slot];
    }
    if (!dm1_v1_champion_redraw_priority_from_top_row_pc34(
            presentation, &redrawState, outMaterials, outRedraw)) {
        return 0;
    }
    transition.partyChampionCount = redrawState.partyChampionCount;
    transition.inventoryChampionBefore = redrawState.inventoryChampionIndex;
    transition.inventoryChampionAfter = redrawState.inventoryChampionIndex;
    return dm1_v1_champion_party_inventory_handoff_pc34(
        presentation, outRedraw, &transition, outMaterials, outHandoff);
}

static void m11_clear_dm1_v1_status_bar_receipt_zones(
    unsigned char* framebuffer,
    int framebufferWidth,
    int framebufferHeight)
{
    int championIndex;
    int statIndex;

    for (championIndex = 0; championIndex < CHAMPION_MAX_PARTY;
         ++championIndex) {
        for (statIndex = 0; statIndex < 3; ++statIndex) {
            DM1_V1_ChampionStatusRectPc34 rect;
            if (dm1_v1_champion_status_bar_rect_pc34(
                    championIndex, statIndex, &rect)) {
                m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                              rect.x, rect.y, rect.w, rect.h, M11_COLOR_BLACK);
            }
        }
    }
}

/* CHAMDRAW.C F0287 emits indexed bar commands. Bind those commands to the
 * current original M11 indexed surface and the exact VIDEODRV.C palette;
 * there is no host color mapping or procedural-bar fallback on this route. */
static int m11_draw_dm1_v1_status_bar_frame_receipt(
    const M11_GameViewState* state,
    const Dm1V1ChampionTopRowAssetsReceiptPc34* assets,
    unsigned char* framebuffer,
    int framebufferWidth,
    int framebufferHeight)
{
    Dm1V1ChampionLeaderOwnershipInputPc34 ownershipInput;
    Dm1V1ChampionLeaderOwnershipReceiptPc34 ownership;
    Dm1V1ChampionPortraitStatusRedrawReceiptPc34 portraitPolicy;
    Dm1V1ChampionStatusBarRedrawReceiptPc34 redraw;
    Dm1V1ChampionStatusBarRedrawMaterialsPc34 commandMaterials;
    Dm1V1ChampionStatusBarRedrawCommandSequencePc34 commands;
    Dm1V1ChampionStatusBarFrameMaterialsPc34 frameMaterials;
    Dm1V1ChampionStatusBarFramePresentationReceiptPc34 presentation;
    int operationIndex;

    if (!state || !assets || !assets->valid || !framebuffer ||
        framebufferWidth <= 0 || framebufferHeight <= 0) {
        return 0;
    }
    memset(&ownershipInput, 0, sizeof(ownershipInput));
    ownershipInput.candidateChampionOrdinal =
        state->candidateMirrorPanelActive && state->candidateMirrorPartyIndex >= 0
            ? state->candidateMirrorPartyIndex + 1 : 0;
    ownershipInput.inventoryPanelActive = state->inventoryPanelActive;
    ownershipInput.inventoryChampionOrdinal = state->inventoryPanelActive &&
        state->world.party.activeChampionIndex >= 0
            ? state->world.party.activeChampionIndex + 1 : 0;
    memset(&ownership, 0, sizeof(ownership));
    memset(&portraitPolicy, 0, sizeof(portraitPolicy));
    memset(&redraw, 0, sizeof(redraw));
    if (!dm1_v1_champion_leader_ownership_handoff_pc34(
            &state->world.party, &ownershipInput, &ownership) ||
        !dm1_v1_champion_portrait_status_redraw_policy_pc34(
            &state->world.party, &ownership, assets, &portraitPolicy) ||
        !dm1_v1_champion_status_bar_redraw_receipt_pc34(
            &state->world.party, &portraitPolicy, &redraw)) {
        return 0;
    }

    memset(&commandMaterials, 0, sizeof(commandMaterials));
    commandMaterials.statusTargetReady = 1;
    commandMaterials.indexedPaletteOriginal = 1;
    commandMaterials.indexedPalette = &G9010_auc_VgaPaletteBrightest_Compat[0][0];
    commandMaterials.indexedPaletteEntryCount = VGA_PALETTE_PC34_COLOR_COUNT;
    memset(&commands, 0, sizeof(commands));
    if (!dm1_v1_champion_status_bar_redraw_commands_pc34(
            &redraw, &commandMaterials, &commands)) {
        return 0;
    }

    memset(&frameMaterials, 0, sizeof(frameMaterials));
    frameMaterials.originalPaletteReady = 1;
    frameMaterials.originalPalette = commandMaterials.indexedPalette;
    frameMaterials.originalPaletteEntryCount =
        commandMaterials.indexedPaletteEntryCount;
    frameMaterials.originalSurfaceReady = 1;
    frameMaterials.originalIndexedSurface = framebuffer;
    frameMaterials.surfaceWidth = framebufferWidth;
    frameMaterials.surfaceHeight = framebufferHeight;
    frameMaterials.surfacePitch = framebufferWidth;
    memset(&presentation, 0, sizeof(presentation));
    if (!dm1_v1_champion_status_bar_frame_presentation_pc34(
            &commands, &frameMaterials, &presentation) || !presentation.valid ||
        !presentation.atomicPublish ||
        presentation.operationCount != commands.commandCount) {
        return 0;
    }
    for (operationIndex = 0; operationIndex < presentation.operationCount;
         ++operationIndex) {
        const Dm1V1ChampionStatusBarFrameOpPc34* operation =
            &presentation.operations[operationIndex];
        if (operation->originalPalette != frameMaterials.originalPalette ||
            operation->originalIndexedSurface != framebuffer ||
            operation->surfacePitch != framebufferWidth ||
            (operation->operation != DM1_V1_CHAMPION_STATUS_BAR_CLEAR_PC34 &&
             operation->operation != DM1_V1_CHAMPION_STATUS_BAR_REPAINT_PC34)) {
            return 0;
        }
        m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                      operation->x, operation->y,
                      operation->width, operation->height,
                      operation->colorIndex);
    }
    return 1;
}

/* Rebuilds the same source-owned C008/C028/F0287 materials that the top-row
 * painter consumes, then requires the F0680/F0692 clear/composition handoff
 * to admit them to this M11 frame. */
static int m11_dm1_v1_top_row_atomic_host_consume(
    const M11_GameViewState* state,
    const Dm1V1ChampionTopRowAssetsReceiptPc34* assets,
    unsigned char* framebuffer,
    int framebufferWidth,
    int framebufferHeight)
{
    Dm1V1ChampionLeaderOwnershipInputPc34 ownershipInput;
    Dm1V1ChampionLeaderOwnershipReceiptPc34 ownership;
    Dm1V1ChampionPortraitStatusRedrawReceiptPc34 policy;
    Dm1V1ChampionStatusBarRedrawReceiptPc34 redraw;
    Dm1V1ChampionStatusBarRedrawMaterialsPc34 commandMaterials;
    Dm1V1ChampionStatusBarRedrawCommandSequencePc34 commands;
    Dm1V1ChampionStatusBarFrameMaterialsPc34 frameMaterials;
    Dm1V1ChampionStatusBarFramePresentationReceiptPc34 statusBars;
    Dm1V1ChampionTopRowAtomicFrameReceiptPc34 clearFrame;
    Dm1V1ChampionTopRowAtomicFrameReceiptPc34 compositionFrame;
    Dm1V1ChampionTopRowAtomicLifecycleReceiptPc34 lifecycle;
    Dm1V1ChampionTopRowLifecycleRenderReceiptPc34 render;
    Dm1V1ChampionTopRowHostConsumptionReceiptPc34 host;
    Dm1V1ChampionTopRowAssetsReceiptPc34 clearAssets;
    M11_Dm1TopRowAtomicRuntime* runtime = &s_m11_dm1_top_row_atomic_runtime;
    int index;

    if (!state || !assets || !assets->valid || !framebuffer ||
        framebufferWidth <= 0 || framebufferHeight <= 0) {
        return 0;
    }
    if (runtime->owner != state) {
        memset(runtime, 0, sizeof(*runtime));
        runtime->owner = state;
        dm1_v1_champion_top_row_atomic_lifecycle_init_pc34(
            &runtime->atomicLifecycle);
        dm1_v1_champion_top_row_lifecycle_render_bridge_init_pc34(
            &runtime->renderBridge);
        dm1_v1_champion_top_row_host_consumption_init_pc34(
            &runtime->hostConsumption);
    }

    memset(&ownershipInput, 0, sizeof(ownershipInput));
    ownershipInput.candidateChampionOrdinal =
        state->candidateMirrorPanelActive && state->candidateMirrorPartyIndex >= 0
            ? state->candidateMirrorPartyIndex + 1 : 0;
    ownershipInput.inventoryPanelActive = state->inventoryPanelActive;
    ownershipInput.inventoryChampionOrdinal = state->inventoryPanelActive &&
        state->world.party.activeChampionIndex >= 0
            ? state->world.party.activeChampionIndex + 1 : 0;
    memset(&ownership, 0, sizeof(ownership));
    memset(&policy, 0, sizeof(policy));
    memset(&redraw, 0, sizeof(redraw));
    if (!dm1_v1_champion_leader_ownership_handoff_pc34(
            &state->world.party, &ownershipInput, &ownership) ||
        !dm1_v1_champion_portrait_status_redraw_policy_pc34(
            &state->world.party, &ownership, assets, &policy) ||
        !dm1_v1_champion_status_bar_redraw_receipt_pc34(
            &state->world.party, &policy, &redraw)) {
        return 0;
    }
    memset(&commandMaterials, 0, sizeof(commandMaterials));
    commandMaterials.statusTargetReady = 1;
    commandMaterials.indexedPaletteOriginal = 1;
    commandMaterials.indexedPalette = &G9010_auc_VgaPaletteBrightest_Compat[0][0];
    commandMaterials.indexedPaletteEntryCount = VGA_PALETTE_PC34_COLOR_COUNT;
    memset(&commands, 0, sizeof(commands));
    if (!dm1_v1_champion_status_bar_redraw_commands_pc34(
            &redraw, &commandMaterials, &commands)) {
        return 0;
    }
    memset(&frameMaterials, 0, sizeof(frameMaterials));
    frameMaterials.originalPaletteReady = 1;
    frameMaterials.originalPalette = commandMaterials.indexedPalette;
    frameMaterials.originalPaletteEntryCount =
        commandMaterials.indexedPaletteEntryCount;
    frameMaterials.originalSurfaceReady = 1;
    frameMaterials.originalIndexedSurface = framebuffer;
    frameMaterials.surfaceWidth = framebufferWidth;
    frameMaterials.surfaceHeight = framebufferHeight;
    frameMaterials.surfacePitch = framebufferWidth;
    memset(&statusBars, 0, sizeof(statusBars));
    if (!dm1_v1_champion_status_bar_frame_presentation_pc34(
            &commands, &frameMaterials, &statusBars) || !statusBars.valid ||
        !statusBars.atomicPublish) {
        return 0;
    }

    /* Atomic lifecycle requires its source clear phase before a complete
     * retained-material composition. Marking C028 unavailable asks the
     * source frame builder for that clear only; it introduces no art. */
    clearAssets = *assets;
    clearAssets.c028Accepted = 0;
    memset(&clearFrame, 0, sizeof(clearFrame));
    if (!dm1_v1_champion_top_row_atomic_frame_pc34(
            &state->world.party, &policy, &clearAssets, &statusBars,
            &clearFrame) || !clearFrame.valid || !clearFrame.clearOnly ||
        !dm1_v1_champion_top_row_atomic_lifecycle_step_pc34(
            &runtime->atomicLifecycle, &clearFrame, &lifecycle) ||
        !dm1_v1_champion_top_row_lifecycle_render_bridge_pc34(
            &runtime->renderBridge, &lifecycle, &render) ||
        !dm1_v1_champion_top_row_host_consumption_pc34(
            &runtime->hostConsumption, &render, &host) || !host.valid) {
        return 0;
    }
    for (index = 0; index < host.operationCount; ++index) {
        const Dm1V1ChampionTopRowHostConsumptionOpPc34* operation =
            &host.operations[index];
        if (operation->kind != DM1_V1_CHAMPION_TOP_ROW_LIFECYCLE_RENDER_CLEAR_PC34) {
            return 0;
        }
        m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                      operation->source.x, operation->source.y,
                      operation->source.width, operation->source.height,
                      M11_COLOR_BLACK);
    }

    memset(&compositionFrame, 0, sizeof(compositionFrame));
    if (!dm1_v1_champion_top_row_atomic_frame_pc34(
            &state->world.party, &policy, assets, &statusBars,
            &compositionFrame) || !compositionFrame.valid ||
        compositionFrame.clearOnly || !compositionFrame.originalMaterialsPublished ||
        !dm1_v1_champion_top_row_atomic_lifecycle_step_pc34(
            &runtime->atomicLifecycle, &compositionFrame, &lifecycle) ||
        !dm1_v1_champion_top_row_lifecycle_render_bridge_pc34(
            &runtime->renderBridge, &lifecycle, &render) ||
        !dm1_v1_champion_top_row_host_consumption_pc34(
            &runtime->hostConsumption, &render, &host) || !host.valid ||
        host.publication !=
            DM1_V1_CHAMPION_TOP_ROW_ATOMIC_LIFECYCLE_COMPOSITION_PC34) {
        return 0;
    }
    for (index = 0; index < host.operationCount; ++index) {
        const Dm1V1ChampionTopRowHostConsumptionOpPc34* operation =
            &host.operations[index];
        if (operation->kind == DM1_V1_CHAMPION_TOP_ROW_LIFECYCLE_RENDER_STATUS_BAR_PC34 &&
            (operation->source.statusBar.originalPalette !=
                 frameMaterials.originalPalette ||
             operation->source.statusBar.originalIndexedSurface != framebuffer)) {
            return 0;
        }
        if (operation->kind != DM1_V1_CHAMPION_TOP_ROW_LIFECYCLE_RENDER_BLIT_C008_PC34 &&
            operation->kind != DM1_V1_CHAMPION_TOP_ROW_LIFECYCLE_RENDER_COMPOSE_C028_PC34 &&
            operation->kind != DM1_V1_CHAMPION_TOP_ROW_LIFECYCLE_RENDER_STATUS_BAR_PC34) {
            return 0;
        }
    }
    return 1;
}

static int m11_dm1_v1_f0659_shield_material_ready(
    const M11_GameViewState* state,
    DM1_V1_F0659ShieldMaterialReceiptPc34* outReceipt)
{
    DM1_V1_F0659SourceSurfacePc34 surfaces[3];
    DM1_V1_F0659GlyphSourcePc34 glyph;
    M11_FontState loadedFont;
    const M11_FontState* sourceFont;
    int index;

    if (!state || !outReceipt || !state->assetsAvailable) return 0;
    sourceFont = &state->originalFont;
    if (!state->originalFontAvailable || !M11_Font_IsLoaded(sourceFont)) {
        M11_Font_Init(&loadedFont);
        if (!M11_Font_LoadFromGraphicsDat(&loadedFont,
                                          state->assetLoader.fileState,
                                          state->assetLoader.runtimeState)) {
            return 0;
        }
        sourceFont = &loadedFont;
    }
    if (M11_Font_ResolvedGraphicIndex(sourceFont) != M11_FONT_GRAPHIC_INDEX_PC34 &&
        M11_Font_ResolvedGraphicIndex(sourceFont) != M11_FONT_GRAPHIC_INDEX_LEGACY) {
        return 0;
    }
    memset(surfaces, 0, sizeof(surfaces));
    memset(&glyph, 0, sizeof(glyph));
    for (index = 0; index < 3; ++index) {
        const M11_AssetSlot* slot = M11_AssetLoader_Load(
            (M11_AssetLoader*)&state->assetLoader, (unsigned int)(37 + index));
        if (!slot || !slot->loaded || !slot->pixels) return 0;
        surfaces[index].graphicsDatOwned = 1;
        surfaces[index].graphicIndex = (int)slot->graphicIndex;
        surfaces[index].width = (int)slot->width;
        surfaces[index].height = (int)slot->height;
        surfaces[index].indexedPixelCount = surfaces[index].width * surfaces[index].height;
        surfaces[index].indexedPixels = slot->pixels;
        surfaces[index].pixelsFNV1a = dm1_v1_f0659_shield_material_fnv1a_pc34(
            slot->pixels, surfaces[index].indexedPixelCount);
    }
    glyph.graphicsDatOwned = 1;
    glyph.graphicIndex = M11_Font_ResolvedGraphicIndex(sourceFont);
    glyph.bits = sourceFont->bitmap;
    glyph.byteCount = M11_FONT_BITMAP_BYTES;
    glyph.bitsFNV1a = dm1_v1_f0659_shield_material_fnv1a_pc34(
        glyph.bits, glyph.byteCount);
    return surfaces[0].pixelsFNV1a && surfaces[1].pixelsFNV1a &&
           surfaces[2].pixelsFNV1a && glyph.bitsFNV1a &&
           dm1_v1_f0659_shield_material_receipt_pc34(
               surfaces, 3, &glyph, 1, outReceipt) && outReceipt->valid &&
           outReceipt->suppressSyntheticFallback &&
           outReceipt->m653GraphicIndex == glyph.graphicIndex;
}

static void m11_draw_dm1_v1_f0659_shield_borders(
    const M11_GameViewState* state,
    const DM1_V1_F0659ShieldMaterialReceiptPc34* receipt,
    unsigned char* framebuffer, int framebufferWidth, int framebufferHeight,
    int championSlot)
{
    DM1_V1_ChampionStatusRectPc34 rect;
    int graphics[3] = {0, 0, 0};
    int count;
    int index;

    if (!state || !receipt || !receipt->valid || !framebuffer ||
        championSlot < 0 || championSlot >= state->world.party.championCount ||
        !state->world.party.champions[championSlot].present ||
        state->world.party.champions[championSlot].hp.current == 0 ||
        !dm1_v1_champion_status_shield_border_rect_pc34(championSlot, &rect)) {
        return;
    }
    count = dm1_v1_champion_status_shield_border_graphics_pc34(
        (int)state->world.magic.fireShieldDefense,
        (int)state->world.magic.spellShieldDefense,
        (int)state->world.magic.partyShieldDefense, graphics);
    for (index = 0; index < count; ++index) {
        const M11_AssetSlot* slot;
        if (graphics[index] < receipt->shieldGraphicIndex ||
            graphics[index] > receipt->spellShieldGraphicIndex) return;
        slot = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader,
                                    (unsigned int)graphics[index]);
        if (!slot || !slot->loaded || !slot->pixels ||
            (int)slot->graphicIndex != graphics[index] ||
            (int)slot->width != receipt->sourceWidth ||
            (int)slot->height != receipt->sourceHeight) return;
        M11_AssetLoader_BlitRegion(slot, 0, 0, receipt->sourceWidth,
                                   receipt->sourceHeight, framebuffer,
                                   framebufferWidth, framebufferHeight,
                                   rect.x, rect.y, receipt->transparentColor);
    }
}

