int M11_GameView_GetV1ViewportBaseGraphic(int layer,
                                          int* outGraphic,
                                          int* outX,
                                          int* outY,
                                          int* outW,
                                          int* outH) {
    switch (layer) {
        case 0:
            if (outGraphic) *outGraphic = M11_GFX_CEILING_PANEL;
            if (outX) *outX = 0;
            if (outY) *outY = 0;
            if (outW) *outW = 224;
            if (outH) *outH = 39;
            return 1;
        case 1:
            if (outGraphic) *outGraphic = M11_GFX_FLOOR_PANEL;
            if (outX) *outX = 0;
            if (outY) *outY = 39;
            if (outW) *outW = 224;
            if (outH) *outH = 97;
            return 1;
        default:
            return 0;
    }
}
